export interface MCQItem {
  id: string;
  section: string;
  unit: string;
  chapter: string;
  questionNumber: string;
  question: string;
  options: Record<string, string>;
  correctOption: string;
  correctAnswer: string;
  questionType: string;
  explanation?: any;
}

export const MCQ_BANK_3: MCQItem[] = [{"id":"P1_U3_MCQ_001","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_001","question":"A newly opened urban bakery surveys local commuters about breakfast preferences before designing its morning pastry menu. Which core role of marketing is the bakery performing?","options":{"A":"Identifying and anticipating customer needs profitably","B":"Maximizing factory production output regardless of demand","C":"Reducing corporate income tax liabilities through bookkeeping","D":"Recruiting and training kitchen staff for shift work"},"correctOption":"A","correctAnswer":"Identifying and anticipating customer needs profitably","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because marketing's primary role is to identify, anticipate, and satisfy customer requirements profitably.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because maximizing output without checking demand describes a product-oriented operations focus.","C":"Incorrect because tax calculation and accounting belong to the Finance function.","D":"Incorrect because staffing and training belong to the Human Resources function."}}},{"id":"P1_U3_MCQ_002","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_002","question":"A mid-sized coffee chain notices regular customers switching to a new rival offering loyalty rewards and oat-milk drinks. Which marketing objective best helps the chain maintain customer loyalty?","options":{"A":"Eliminating all market research to cut administrative overheads","B":"Building strong brand relationships and adapting products to evolving customer tastes","C":"Raising coffee prices sharply without improving product quality","D":"Reducing store opening hours during busy morning commuter periods"},"correctOption":"B","correctAnswer":"Building strong brand relationships and adapting products to evolving customer tastes","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because retaining loyal customers requires understanding changing preferences and strengthening perceived brand value.","distractor_reasons":{"A":"Incorrect because cutting research leaves the firm blind to shifting consumer tastes.","B":"Correct selection.","C":"Incorrect because unsubstantiated price hikes drive price-sensitive buyers toward competitors.","D":"Incorrect because restricting availability inconveniences regular commuters."}}},{"id":"P1_U3_MCQ_003","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_003","question":"In a regional bottled-water market worth $40 million annually, PureSpring Ltd generates $6 million in sales revenue. What is PureSpring Ltd's market share?","options":{"A":"6.7%","B":"24.0%","C":"15.0%","D":"60.0%"},"correctOption":"C","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Market Share (%) = (Business Sales / Total Market Sales) × 100 = ($6m / $40m) × 100 = 15.0%.","distractor_reasons":{"A":"Incorrect because 6.7% divides $40m by $6m instead of $6m by $40m.","B":"Incorrect because 24.0% multiplies 6 by 4 rather than calculating a percentage share.","C":"Correct selection.","D":"Incorrect because 60.0% misplaces the decimal point during percentage conversion."}}},{"id":"P1_U3_MCQ_004","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_004","question":"An electric bicycle manufacturer sees total industry sales rise from $200 million to $250 million in one year, while its own sales stay at $20 million. How has the manufacturer's market position changed?","options":{"A":"Its market share increased from 8% to 10%","B":"Its sales revenue fell by 20% over the year","C":"Its market share remained unchanged at 10%","D":"Its market share fell from 10% to 8% despite stable sales revenue"},"correctOption":"D","correctAnswer":"Its market share fell from 10% to 8% despite stable sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because its share dropped from ($20m / $200m) = 10% to ($20m / $250m) = 8% as competitors captured the market growth.","distractor_reasons":{"A":"Incorrect because 8% to 10% reverses the before-and-after market share figures.","B":"Incorrect because the firm's absolute sales revenue stayed constant at $20 million.","C":"Incorrect because constant sales in a growing total market reduces relative market share.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_005","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_005","question":"As average household incomes rise in a developing economy, a supermarket chain notices shoppers buying fewer basic canned foods and more organic fresh meals. Which factor explains this shift in consumer spending patterns?","options":{"A":"Higher disposable income increasing demand for higher-quality, premium convenience foods","B":"An ageing population reducing total demand for all grocery products","C":"Government bans on selling canned vegetables in retail stores","D":"A decrease in the number of supermarkets operating in the country"},"correctOption":"A","correctAnswer":"Higher disposable income increasing demand for higher-quality, premium convenience foods","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rising consumer incomes shift spending away from basic staples toward higher-value, healthier, and convenient options.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the scenario specifically highlights rising household incomes rather than demographic ageing.","C":"Incorrect because no regulatory ban was mentioned.","D":"Incorrect because fewer stores would not explain a shift from canned to organic products."}}},{"id":"P1_U3_MCQ_006","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_006","question":"A traditional travel agency loses bookings as more consumers use smartphone apps to compare flights and hotels independently. How has the market changed for the agency?","options":{"A":"Price elasticity of demand for holidays has become completely inelastic","B":"Technological advances and changing buying habits have increased online competition","C":"Consumer demand for international travel has fallen to zero","D":"The travel market has transformed into a pure monopoly"},"correctOption":"B","correctAnswer":"Technological advances and changing buying habits have increased online competition","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because digital booking platforms empower consumers to compare prices easily, intensifying competition for traditional high-street agencies.","distractor_reasons":{"A":"Incorrect because easy price comparison makes consumers more price-sensitive (elastic), not inelastic.","B":"Correct selection.","C":"Incorrect because consumers are still booking holidays, just via online channels.","D":"Incorrect because online comparison sites increase competition rather than creating a monopoly."}}},{"id":"P1_U3_MCQ_007","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_007","question":"A local electronics retailer faces fierce price competition from global e-commerce giants selling identical televisions. Which response is most effective for the local retailer to survive?","options":{"A":"Ignore competitor prices and stop training shop-floor sales staff","B":"Reduce product warranties while raising delivery charges","C":"Differentiate through expert in-store advice, same-day installation, and personalized after-sales service","D":"Attempt to outspend global giants on nationwide television advertising"},"correctOption":"C","correctAnswer":"Differentiate through expert in-store advice, same-day installation, and personalized after-sales service","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because smaller retailers rarely win pure price wars against giants, so adding tailored service differentiation creates a competitive advantage.","distractor_reasons":{"A":"Incorrect because neglecting pricing and staff knowledge accelerates customer loss.","B":"Incorrect because cutting service value while raising fees drives shoppers online.","C":"Correct selection.","D":"Incorrect because a local retailer lacks the budget to outspend multinational corporations on national TV."}}},{"id":"P1_U3_MCQ_008","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_008","question":"An artisan chocolatier produces handmade, allergen-free vegan truffles sold exclusively to health-conscious luxury buyers. Which market approach is this business using?","options":{"A":"Mass marketing","B":"Cost-leadership marketing","C":"Undifferentiated marketing","D":"Niche marketing"},"correctOption":"D","correctAnswer":"Niche marketing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because niche marketing tailors specialized products to a small, well-defined segment with specific preferences.","distractor_reasons":{"A":"Incorrect because mass marketing targets the broadest possible audience with standardized goods.","B":"Incorrect because handmade luxury truffles focus on specialization rather than lowest-cost volume.","C":"Incorrect because undifferentiated marketing ignores segment differences.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_009","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_009","question":"What is a major financial advantage for a small startup operating in a 'niche market' rather than a 'mass market'?","options":{"A":"Less direct competition from large multinationals, allowing higher profit margins per unit sold","B":"Huge economies of scale from producing millions of identical units daily","C":"Guaranteed stable demand even if consumer tastes change suddenly","D":"Zero need to understand specific customer preferences"},"correctOption":"A","correctAnswer":"Less direct competition from large multinationals, allowing higher profit margins per unit sold","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because large corporations often overlook small niches, enabling specialists to charge premium prices for closely matched products.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because large-scale economies of scale are an advantage of mass marketing.","C":"Incorrect because niche firms face high risk if demand in their single narrow segment shifts.","D":"Incorrect because niche success depends on deep knowledge of specialized buyer needs."}}},{"id":"P1_U3_MCQ_010","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_010","question":"A small firm specializing solely in left-handed mechanical watches experiences a sharp drop in profits when a rival enters the segment. What key risk of niche marketing does this illustrate?","options":{"A":"Excessive spending on nationwide mass-media advertising","B":"Small total market size limits growth, leaving profits vulnerable if a competitor takes market share","C":"Inability to charge prices above basic manufacturing cost","D":"Over-reliance on standardized mass-production assembly lines"},"correctOption":"B","correctAnswer":"Small total market size limits growth, leaving profits vulnerable if a competitor takes market share","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because niche markets have a limited pool of buyers, so even one new competitor can severely erode sales volume.","distractor_reasons":{"A":"Incorrect because niche firms use targeted promotion rather than expensive mass-media campaigns.","B":"Correct selection.","C":"Incorrect because niche products usually command premium margins rather than bare-cost pricing.","D":"Incorrect because niche goods are typically produced in small batches or job production."}}},{"id":"P1_U3_MCQ_011","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_011","question":"A global soft-drinks company sells its flagship cola in identical cans across millions of supermarkets worldwide using standardized television campaigns. Which strategy does this represent?","options":{"A":"Niche marketing","B":"Bespoke job marketing","C":"Mass marketing","D":"Geographic micro-targeting"},"correctOption":"C","correctAnswer":"Mass marketing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because mass marketing appeals to the entire market with one standardized product and unified promotional message.","distractor_reasons":{"A":"Incorrect because niche marketing targets a narrow, specialized consumer group.","B":"Incorrect because bespoke marketing customizes items for individual buyers.","C":"Correct selection.","D":"Incorrect because selling identical cans globally ignores narrow local variations."}}},{"id":"P1_U3_MCQ_012","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_012","question":"Why does a 'mass marketing' strategy allow a household detergent manufacturer to charge lower retail prices than a niche eco-detergent brand?","options":{"A":"Mass-market firms never pay for market research or distribution","B":"Mass-market firms are exempt from consumer protection laws","C":"Niche brands are legally forced to charge higher prices by regulators","D":"High sales volumes generate purchasing and technical economies of scale, lowering average unit production costs"},"correctOption":"D","correctAnswer":"High sales volumes generate purchasing and technical economies of scale, lowering average unit production costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because large-scale standardized production spreads fixed overheads and secures bulk ingredient discounts, reducing unit costs.","distractor_reasons":{"A":"Incorrect because mass-market brands invest heavily in research and wide distribution.","B":"Incorrect because all firms must obey consumer protection laws.","C":"Incorrect because niche pricing reflects higher unit costs and value positioning, not government mandates.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_013","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_013","question":"What is a major disadvantage for a business competing in a 'mass market'?","options":{"A":"Intense price and promotional competition from large rivals can squeeze profit margins","B":"Total potential customer demand is too small to justify automated machinery","C":"Products cannot be distributed through national supermarket chains","D":"Brand awareness is impossible to build through mass media"},"correctOption":"A","correctAnswer":"Intense price and promotional competition from large rivals can squeeze profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mass markets attract powerful competitors offering similar products, driving heavy advertising outlays and price pressure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because huge demand in mass markets directly supports automated flow production.","C":"Incorrect because mass-market goods rely heavily on national supermarket distribution.","D":"Incorrect because mass media is ideal for reaching mass-market consumers."}}},{"id":"P1_U3_MCQ_014","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_014","question":"A clothing retailer divides its customer base into distinct groups—such as teenagers, working professionals, and retirees—and designs separate ranges for each. What is this practice called?","options":{"A":"Product orientation","B":"Market segmentation","C":"Price skimming","D":"Vertical integration"},"correctOption":"B","correctAnswer":"Market segmentation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because market segmentation subdivides a heterogeneous market into smaller groups with shared characteristics and needs.","distractor_reasons":{"A":"Incorrect because product orientation focuses on engineering features without tailoring to customer groups.","B":"Correct selection.","C":"Incorrect because price skimming is a launch pricing strategy.","D":"Incorrect because vertical integration involves merging with suppliers or distributors."}}},{"id":"P1_U3_MCQ_015","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_015","question":"A financial services firm promotes student bank accounts to 18-to-21-year-olds and retirement annuities to customers aged over 60. Which basis of market segmentation is it using?","options":{"A":"Geographic segmentation","B":"Climatic segmentation","C":"Demographic segmentation (age)","D":"Distribution-channel segmentation"},"correctOption":"C","correctAnswer":"Demographic segmentation (age)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because demographic segmentation divides consumers using population variables such as age, gender, family size, or occupation.","distractor_reasons":{"A":"Incorrect because geographic segmentation groups buyers by region, city, or country.","B":"Incorrect because climate is a geographic factor rather than age.","C":"Correct selection.","D":"Incorrect because distribution channels relate to Place in the marketing mix."}}},{"id":"P1_U3_MCQ_016","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_016","question":"An international fast-food chain sells spicy rice bowls in Southeast Asia, vegetarian paneer wraps in India, and beef burgers in North America. Which segmentation method is guiding its menus?","options":{"A":"Income segmentation","B":"Age segmentation","C":"Gender segmentation","D":"Geographic and cultural segmentation"},"correctOption":"D","correctAnswer":"Geographic and cultural segmentation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because adapting menus by country and regional dietary traditions reflects geographic and cultural segmentation.","distractor_reasons":{"A":"Incorrect because menu items are tailored to regional tastes rather than wealth brackets.","B":"Incorrect because meals target all age groups within each region.","C":"Incorrect because menus are not split by male or female buyers.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_017","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_017","question":"An airline offers ultra-low-fare basic economy tickets alongside $6,000 flat-bed first-class suites on the same long-haul flight. Which segmentation variable is the airline primarily targeting?","options":{"A":"Income / socio-economic group","B":"Gender","C":"Residential postcode","D":"Marital status"},"correctOption":"A","correctAnswer":"Income / socio-economic group","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because offering budget seats and luxury suites segments travellers by disposable income and willingness to pay.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cabin classes are open to passengers of any gender.","C":"Incorrect because seating tiers are based on fare budget rather than home address.","D":"Incorrect because cabin selection does not depend on marital status."}}},{"id":"P1_U3_MCQ_018","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_018","question":"A smartwatch brand markets a rugged GPS model to outdoor trail runners and a sleek leather-strap model to fashion-conscious city professionals. Which segmentation approach is being applied?","options":{"A":"Geographic segmentation","B":"Psychographic / lifestyle segmentation","C":"Age-only segmentation","D":"Mass undifferentiated segmentation"},"correctOption":"B","correctAnswer":"Psychographic / lifestyle segmentation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because lifestyle segmentation groups consumers according to their hobbies, interests, values, and daily activities.","distractor_reasons":{"A":"Incorrect because buyers are grouped by athletic vs fashion interests rather than country or climate.","B":"Correct selection.","C":"Incorrect because trail runners and city professionals can belong to the same age bracket.","D":"Incorrect because the firm offers two distinct targeted designs rather than one uniform watch."}}},{"id":"P1_U3_MCQ_019","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_019","question":"How does effective 'market segmentation' help a medium-sized sportswear firm use its promotional budget more efficiently?","options":{"A":"It eliminates the need to conduct any primary or secondary market research","B":"It allows the firm to sell identical shoes at the exact same price in every country","C":"It directs adverts specifically to media channels read or watched by target buyer groups, avoiding wasted spending on uninterested audiences","D":"It legally prevents rival sportswear companies from entering the market"},"correctOption":"C","correctAnswer":"It directs adverts specifically to media channels read or watched by target buyer groups, avoiding wasted spending on uninterested audiences","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because targeting defined segments focuses advertising expenditure on high-potential buyers rather than broadcasting broadly.","distractor_reasons":{"A":"Incorrect because identifying segments actually relies on solid market research.","B":"Incorrect because segmentation encourages tailoring products and prices to different groups.","C":"Correct selection.","D":"Incorrect because segmentation does not create legal barriers against competitors."}}},{"id":"P1_U3_MCQ_020","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_020","question":"What is a potential disadvantage for a car manufacturer that creates too many narrow sub-models across dozens of tiny market segments?","options":{"A":"Higher design, tooling, and marketing costs per model, reducing economies of scale","B":"Customers complain that there is zero variety in vehicle features","C":"The manufacturer becomes completely immune to changes in fuel prices","D":"Retail dealerships no longer need trained salespeople"},"correctOption":"A","correctAnswer":"Higher design, tooling, and marketing costs per model, reducing economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because over-segmenting fragments production runs and requires separate promotional campaigns, driving up unit costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because offering dozens of sub-models provides extensive variety.","C":"Incorrect because macroeconomic factors like fuel prices still affect vehicle demand.","D":"Incorrect because multiple models actually require knowledgeable sales staff."}}},{"id":"P1_U3_MCQ_021","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_021","question":"A toy manufacturer notices birth rates falling steadily in its home country while the proportion of citizens aged over 65 is rising rapidly. Which strategic marketing response is most appropriate?","options":{"A":"Double factory capacity for infant baby rattles in the domestic market","B":"Expand exports to countries with growing young populations or diversify into adult board games and brain-training puzzles","C":"Eliminate all digital marketing and raise prices on children's toys by 50%","D":"Stop tracking demographic statistics because population trends never affect sales"},"correctOption":"B","correctAnswer":"Expand exports to countries with growing young populations or diversify into adult board games and brain-training puzzles","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because demographic shifts shrink the domestic child segment, requiring either new geographic markets or new products for older consumers.","distractor_reasons":{"A":"Incorrect because expanding baby-toy output in a shrinking birth-rate market causes unsold inventory.","B":"Correct selection.","C":"Incorrect because steep price rises in a declining market accelerate revenue loss.","D":"Incorrect because demographic trends directly govern segment size."}}},{"id":"P1_U3_MCQ_022","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_022","question":"Which business is most likely to succeed using a 'mass marketing' strategy rather than a 'niche marketing' strategy?","options":{"A":"A bespoke wedding-dress tailor operating from a single boutique studio","B":"A manufacturer of specialized surgical instruments for brain surgeons","C":"A large consumer-goods corporation producing everyday toothpaste and bath soap","D":"An artisan restorer of antique 18th-century grandfather clocks"},"correctOption":"C","correctAnswer":"A large consumer-goods corporation producing everyday toothpaste and bath soap","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because toothpaste and soap are universal everyday necessities suited to high-volume standardized production and broad distribution.","distractor_reasons":{"A":"Incorrect because bespoke bridal wear is customized for individual buyers.","B":"Incorrect because specialized surgical tools serve a tiny, expert niche.","C":"Correct selection.","D":"Incorrect because antique clock restoration serves a very narrow collector niche."}}},{"id":"P1_U3_MCQ_023","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_023","question":"Why might a once-profitable 'niche market' suddenly attract intense competition from large corporations?","options":{"A":"Rapid sales growth in the niche signals high profit potential, prompting large firms to launch competing lines","B":"Governments force large corporations to enter every small niche market by law","C":"Niche markets always have lower unit production costs than mass markets","D":"Consumers in niche markets prefer unbranded generic goods"},"correctOption":"A","correctAnswer":"Rapid sales growth in the niche signals high profit potential, prompting large firms to launch competing lines","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because if a niche grows substantially (such as plant-based milks), big corporations enter to capture the expanding revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because corporations enter markets voluntarily for profit, not by government order.","C":"Incorrect because mass markets achieve lower unit costs through economies of scale.","D":"Incorrect because niche buyers often value strong specialist brands."}}},{"id":"P1_U3_MCQ_024","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_024","question":"A supermarket chain uses loyalty-card data to send coupons for baby diapers to new parents and pet-food discounts to dog owners. How does this benefit the supermarket?","options":{"A":"It eliminates the need to stock products for customers without children or pets","B":"Targeted promotions increase redemption rates and repeat store visits by matching offers to specific household segments","C":"It allows the supermarket to charge higher prices than competitors on every item","D":"It replaces the need for physical store locations or delivery vans"},"correctOption":"B","correctAnswer":"Targeted promotions increase redemption rates and repeat store visits by matching offers to specific household segments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because personalized segmentation ensures promotions are relevant to each household, boosting customer retention and basket size.","distractor_reasons":{"A":"Incorrect because supermarkets still serve all household types.","B":"Correct selection.","C":"Incorrect because coupons offer targeted discounts rather than universal price hikes.","D":"Incorrect because retail stores or delivery networks remain essential."}}},{"id":"P1_U3_MCQ_025","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_025","question":"When is 'gender segmentation' becoming less effective for modern personal-care and clothing brands?","options":{"A":"When younger consumers increasingly prefer gender-neutral styles and choose products based on lifestyle or skin type instead","B":"When governments ban men and women from shopping in the same retail stores","C":"When companies stop using demographic data in all market research","D":"When clothing sizes become identical across all adults worldwide"},"correctOption":"A","correctAnswer":"When younger consumers increasingly prefer gender-neutral styles and choose products based on lifestyle or skin type instead","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shifting social attitudes and unisex fashion trends mean lifestyle and functional needs often predict buying better than gender.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no such retail segregation laws exist.","C":"Incorrect because firms still collect demographic data while broadening segmentation criteria.","D":"Incorrect because sizing differences persist regardless of gender-neutral branding."}}},{"id":"P1_U3_MCQ_026","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_026","question":"An engineering firm invents a complex new kitchen gadget based purely on its engineers' technical interests, without checking if consumers want it or what price they would pay. Which business approach does this illustrate?","options":{"A":"Market-oriented approach","B":"Product-oriented approach","C":"Niche-segmented approach","D":"Customer-led approach"},"correctOption":"B","correctAnswer":"Product-oriented approach","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a product-oriented business focuses first on developing technical features and then tries to persuade customers to buy.","distractor_reasons":{"A":"Incorrect because a market-oriented firm researches customer needs before designing the product.","B":"Correct selection.","C":"Incorrect because niche segmentation starts with identifying a specific customer group's needs.","D":"Incorrect because customer-led firms prioritize buyer preferences from the outset."}}},{"id":"P1_U3_MCQ_027","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_027","question":"Why does a 'market-oriented' business generally face lower risk of new-product failure than a 'product-oriented' business?","options":{"A":"It conducts market research first to ensure products match verified consumer needs and price expectations","B":"It never spends money on research and development or product testing","C":"It is legally guaranteed a monopoly patent on every product launched","D":"It sells products exclusively to government departments"},"correctOption":"A","correctAnswer":"It conducts market research first to ensure products match verified consumer needs and price expectations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because basing design, pricing, and promotion on customer evidence reduces the chance of launching unwanted goods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because market-oriented firms invest heavily in research and prototype testing.","C":"Incorrect because market orientation provides commercial insight, not automatic patent monopolies.","D":"Incorrect because market-oriented firms operate across consumer and business markets."}}},{"id":"P1_U3_MCQ_028","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_028","question":"Which situation is an example of 'primary (field) market research'?","options":{"A":"Downloading national population census tables from a government statistics website","B":"Reading a competitor's published annual report and price list","C":"Distributing an original online questionnaire to 500 potential buyers about a proposed beverage flavour","D":"Purchasing a published industry trend report from a market research agency"},"correctOption":"C","correctAnswer":"Distributing an original online questionnaire to 500 potential buyers about a proposed beverage flavour","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because primary research collects brand-new, first-hand data directly from respondents for the business's specific purpose.","distractor_reasons":{"A":"Incorrect because census data was already collected by government (secondary research).","B":"Incorrect because existing competitor publications are external secondary data.","C":"Correct selection.","D":"Incorrect because pre-published commercial reports are secondary research."}}},{"id":"P1_U3_MCQ_029","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_029","question":"Why do market researchers usually gather 'secondary (desk) research' before commissioning expensive 'primary research'?","options":{"A":"Secondary research is always 100% tailored to the firm's brand-new product prototype","B":"Secondary research is faster and cheaper to obtain, helping clarify background market size and narrow down what primary questions are needed","C":"Secondary research is collected exclusively through face-to-face street interviews","D":"Secondary research is never accessible to rival businesses"},"correctOption":"B","correctAnswer":"Secondary research is faster and cheaper to obtain, helping clarify background market size and narrow down what primary questions are needed","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because reviewing existing internal records and published data saves time and money before designing targeted field surveys.","distractor_reasons":{"A":"Incorrect because secondary data was collected for other purposes and cannot test a brand-new prototype directly.","B":"Correct selection.","C":"Incorrect because face-to-face interviews are a primary research method.","D":"Incorrect because external secondary sources (like newspapers or government stats) are publicly available to rivals."}}},{"id":"P1_U3_MCQ_030","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_030","question":"Which of the following is an 'internal source of secondary data' for a retail supermarket chain?","options":{"A":"A national newspaper article on food inflation","B":"Government retail trade census statistics","C":"Past sales records and loyalty-card purchase histories stored in the supermarket's own database","D":"A street survey conducted by the supermarket's marketing interns"},"correctOption":"C","correctAnswer":"Past sales records and loyalty-card purchase histories stored in the supermarket's own database","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because past sales and customer records already exist inside the organisation and can be re-analyzed cheaply.","distractor_reasons":{"A":"Incorrect because newspapers are an external secondary source.","B":"Incorrect because government statistics are an external secondary source.","C":"Correct selection.","D":"Incorrect because a new street survey is primary research."}}},{"id":"P1_U3_MCQ_031","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_031","question":"What is a major limitation of relying solely on 'secondary market research' when launching an innovative product?","options":{"A":"Secondary data takes years to collect from individual households","B":"Secondary data may be outdated, collected for a different purpose, and publicly available to competitors","C":"Secondary data is always more expensive than hiring a team of field interviewers","D":"Secondary data provides qualitative emotional insights from focus groups"},"correctOption":"B","correctAnswer":"Secondary data may be outdated, collected for a different purpose, and publicly available to competitors","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because existing publications may not reflect current trends or specific product features, and offer no exclusive information advantage.","distractor_reasons":{"A":"Incorrect because secondary data is already compiled and quick to access.","B":"Correct selection.","C":"Incorrect because secondary research is typically far cheaper than primary research.","D":"Incorrect because focus groups are a primary qualitative method."}}},{"id":"P1_U3_MCQ_032","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_032","question":"A toy company invites 10 children and their parents to play with prototype board games in a room while a moderator observes and discusses their reactions. Which primary research method is this?","options":{"A":"Postal questionnaire","B":"Focus group","C":"Desk research","D":"Census enumeration"},"correctOption":"B","correctAnswer":"Focus group","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a focus group brings together a small group of target consumers for guided discussion and observation of attitudes and reactions.","distractor_reasons":{"A":"Incorrect because a postal questionnaire collects written answers remotely without group interaction.","B":"Correct selection.","C":"Incorrect because desk research analyzes existing secondary sources.","D":"Incorrect because a census surveys an entire population."}}},{"id":"P1_U3_MCQ_033","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_033","question":"What is a key disadvantage of using 'focus groups' to gather qualitative market research?","options":{"A":"Participants cannot explain the reasons behind their opinions","B":"Focus groups take place entirely via automated telephone dialers","C":"Small sample sizes may not represent the whole population, and one dominant speaker can bias other participants' views","D":"Focus groups produce only raw numerical percentages without any verbal detail"},"correctOption":"C","correctAnswer":"Small sample sizes may not represent the whole population, and one dominant speaker can bias other participants' views","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because group dynamics ('groupthink' or dominant voices) and small participant numbers limit statistical generalizability.","distractor_reasons":{"A":"Incorrect because exploring deeper reasons ('why') is the main strength of focus groups.","B":"Incorrect because focus groups are moderated group discussions, in person or via video.","C":"Correct selection.","D":"Incorrect because focus groups generate rich qualitative insights rather than large-scale statistics."}}},{"id":"P1_U3_MCQ_034","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_034","question":"A soft-drinks manufacturer launches a new mango-ginger soda in three mid-sized cities for two months to measure actual repeat purchases before rolling it out nationwide. Which research method is being used?","options":{"A":"Test marketing","B":"Secondary desk research","C":"Telephone polling","D":"Quota street interviewing"},"correctOption":"A","correctAnswer":"Test marketing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because test marketing trials a new product in a limited geographical area under real market conditions to gauge demand and spot flaws before national launch.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because test marketing generates new real-world sales data.","C":"Incorrect because telephone polling asks hypothetical questions rather than tracking real store sales.","D":"Incorrect because street interviews gather stated opinions rather than actual regional sales performance."}}},{"id":"P1_U3_MCQ_035","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_035","question":"What is a major risk for a consumer-electronics firm that conducts 'test marketing' in a limited region before a national launch?","options":{"A":"Rival firms can observe the test product, analyze customer reactions, and rush out a competing copy before the national rollout","B":"Test marketing provides zero information about real consumer purchasing behaviour","C":"Test marketing is always completely free of production or distribution costs","D":"Customers in test cities are legally forbidden from buying the product twice"},"correctOption":"A","correctAnswer":"Rival firms can observe the test product, analyze customer reactions, and rush out a competing copy before the national rollout","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because revealing a new product early in test cities alerts competitors and gives them time to imitate or disrupt the national launch.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because measuring real purchase behaviour is test marketing's core advantage.","C":"Incorrect because producing and distributing a regional batch still incurs significant cost.","D":"Incorrect because tracking repeat purchases is central to test marketing."}}},{"id":"P1_U3_MCQ_036","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_036","question":"A supermarket researcher stands quietly near the cereal aisle recording which shelf height shoppers look at first and how long they examine nutrition labels. Which primary research method is this?","options":{"A":"Observation","B":"Postal survey","C":"Focus group","D":"Secondary trade report"},"correctOption":"A","correctAnswer":"Observation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because observation records actual consumer behaviour without asking questions, avoiding discrepancies between what people say and what they do.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because postal surveys rely on self-reported written answers.","C":"Incorrect because focus groups involve moderated group conversation.","D":"Incorrect because watching live shoppers generates primary data."}}},{"id":"P1_U3_MCQ_037","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_037","question":"What is a key limitation of 'observation' as a primary market research method?","options":{"A":"It records what shoppers actually do, but cannot explain the underlying reasons why they behaved that way","B":"It relies on shoppers exaggerating their answers to please an interviewer","C":"It cannot be used inside physical retail stores or websites","D":"It requires sending printed forms to thousands of home addresses"},"correctOption":"A","correctAnswer":"It records what shoppers actually do, but cannot explain the underlying reasons why they behaved that way","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because seeing a customer put a product back on the shelf shows the action, but not whether the barrier was price, packaging, or ingredients.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because avoiding interviewer-pleasing bias is actually an advantage of unobtrusive observation.","C":"Incorrect because both store cameras/watchers and website click-tracking are forms of observation.","D":"Incorrect because mailing forms describes postal questionnaires."}}},{"id":"P1_U3_MCQ_038","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_038","question":"Why have 'online questionnaires' largely replaced traditional 'postal questionnaires' for many consumer brands?","options":{"A":"Online surveys guarantee a 100% response rate from every internet user","B":"Online surveys are much cheaper to distribute, gather responses rapidly, and automatically tabulate quantitative data","C":"Online surveys reach elderly consumers without internet access more easily than postal mail","D":"Online surveys prevent respondents from ever skipping questions"},"correctOption":"B","correctAnswer":"Online surveys are much cheaper to distribute, gather responses rapidly, and automatically tabulate quantitative data","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because digital survey tools eliminate printing and postage expenses while automating statistical chart generation.","distractor_reasons":{"A":"Incorrect because online surveys still experience non-response bias.","B":"Correct selection.","C":"Incorrect because digitally excluded groups are actually missed by online-only surveys.","D":"Incorrect because respondents can still abandon online forms mid-way."}}},{"id":"P1_U3_MCQ_039","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_039","question":"How does 'random sampling' differ from 'quota sampling' when selecting survey respondents?","options":{"A":"Random sampling gives every member of the target population an equal chance of selection, whereas quota sampling selects set numbers matching specific population characteristics (e.g., age or gender)","B":"Random sampling interviews only people passing a busy shopping mall, whereas quota sampling uses computer number generators","C":"Random sampling is used only for secondary data, whereas quota sampling is used only for primary data","D":"Random sampling is faster and cheaper than quota sampling when no population list exists"},"correctOption":"A","correctAnswer":"Random sampling gives every member of the target population an equal chance of selection, whereas quota sampling selects set numbers matching specific population characteristics (e.g., age or gender)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because true random sampling relies on chance across a sampling frame, while quota sampling mirrors key demographic proportions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because interviewing passers-by at will is convenience/quota selection, whereas computer generators support random sampling.","C":"Incorrect because both are sampling methods for primary research.","D":"Incorrect because quota sampling is generally quicker and cheaper when a complete population list is unavailable."}}},{"id":"P1_U3_MCQ_040","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_040","question":"A fitness club's membership is 60% female and 40% male. If the club uses 'quota sampling' to survey 150 members about new gym classes, how many female and male members should be interviewed?","options":{"A":"75 females and 75 males","B":"60 females and 40 males","C":"90 females and 60 males","D":"100 females and 50 males"},"correctOption":"C","correctAnswer":"90 females and 60 males","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because 60% of 150 = 90 females and 40% of 150 = 60 males, preserving the population's gender ratio.","distractor_reasons":{"A":"Incorrect because 75/75 splits the sample 50/50 rather than matching the 60/40 membership ratio.","B":"Incorrect because 60 + 40 totals only 100 respondents instead of 150.","C":"Correct selection.","D":"Incorrect because 100/50 applies a 66.7%/33.3% split instead of 60%/40%."}}},{"id":"P1_U3_MCQ_041","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_041","question":"What is a potential source of bias when interviewers use 'quota sampling' on a high street?","options":{"A":"Interviewers may consciously choose friendly-looking passers-by who fit the age/gender quota rather than selecting objectively","B":"The sample will completely ignore the age and gender proportions of the target market","C":"Quota sampling requires obtaining a complete list of every citizen's name and address first","D":"Quota sampling cannot be used for face-to-face interviews"},"correctOption":"A","correctAnswer":"Interviewers may consciously choose friendly-looking passers-by who fit the age/gender quota rather than selecting objectively","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quota sampling is non-random, so interviewer selection judgment can introduce subtle bias within each quota category.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because matching target demographic proportions is the exact purpose of quota sampling.","C":"Incorrect because needing a full sampling frame is a requirement of random sampling, not quota sampling.","D":"Incorrect because quota sampling is very commonly used in face-to-face street surveys."}}},{"id":"P1_U3_MCQ_042","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_042","question":"A luxury golf-club manufacturer conducts a street survey outside a university campus at 10:00 AM on a Tuesday to forecast demand for $2,500 golf clubs. Why will the resulting data likely be inaccurate?","options":{"A":"Sampling bias: the location and time over-represent full-time students rather than high-income golf buyers","B":"Primary research can never collect quantitative opinions on price","C":"University students always refuse to answer street questionnaires","D":"Market research is only accurate if 100% of the national population is interviewed"},"correctOption":"A","correctAnswer":"Sampling bias: the location and time over-represent full-time students rather than high-income golf buyers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because surveying outside a university captures a non-representative sample whose income and interests differ from luxury golf consumers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because surveys routinely test price willingness.","C":"Incorrect because even willing student respondents do not represent the target luxury segment.","D":"Incorrect because properly selected samples yield reliable results without surveying everyone."}}},{"id":"P1_U3_MCQ_043","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_043","question":"A survey asks respondents: 'Don't you agree that our eco-friendly bamboo toothbrush is far superior to wasteful plastic brushes?' Why does this question reduce data reliability?","options":{"A":"It is a leading (biased) question whose loaded wording pushes respondents toward a positive answer","B":"It is an open-ended question that takes two hours to answer","C":"It uses secondary census statistics instead of primary opinions","D":"It targets too large a sample size"},"correctOption":"A","correctAnswer":"It is a leading (biased) question whose loaded wording pushes respondents toward a positive answer","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because phrasing like 'Don't you agree' and 'wasteful' nudges respondents to agree rather than giving honest preferences.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because it is a closed yes/no leading question.","C":"Incorrect because this is a poorly worded primary survey question.","D":"Incorrect because larger sample sizes generally improve rather than reduce accuracy."}}},{"id":"P1_U3_MCQ_044","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_044","question":"What is the main difference between 'quantitative' and 'qualitative' market research data?","options":{"A":"Quantitative data measures numerical quantities (such as '72% prefer blue'), whereas qualitative data explores opinions, attitudes, and reasons behind behaviour","B":"Quantitative data comes only from secondary sources, whereas qualitative data comes only from primary sources","C":"Quantitative data is collected only from focus groups, whereas qualitative data comes only from barcode scanners","D":"Quantitative data is always biased, whereas qualitative data is always 100% objective"},"correctOption":"A","correctAnswer":"Quantitative data measures numerical quantities (such as '72% prefer blue'), whereas qualitative data explores opinions, attitudes, and reasons behind behaviour","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quantitative research answers 'how many/how much' statistically, while qualitative research answers 'why/how' consumers feel.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both primary and secondary research can produce quantitative or qualitative data.","C":"Incorrect because this reverses the typical outputs of focus groups and barcode scanners.","D":"Incorrect because both data types can suffer bias if poorly designed."}}},{"id":"P1_U3_MCQ_045","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_045","question":"Why do market researchers include both 'closed questions' and 'open-ended questions' in a customer satisfaction questionnaire?","options":{"A":"Closed questions allow quick statistical analysis, while open-ended questions capture unexpected customer suggestions in their own words","B":"Closed questions prevent respondents from completing the form honestly","C":"Open-ended questions are required by law in every commercial questionnaire","D":"Open-ended questions are easier to summarize into pie charts than closed questions"},"correctOption":"A","correctAnswer":"Closed questions allow quick statistical analysis, while open-ended questions capture unexpected customer suggestions in their own words","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because combining structured ratings with free-text boxes balances quantitative measurement and qualitative insight.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because well-written closed questions yield clear, honest choices.","C":"Incorrect because questionnaire structure is a research design choice, not a legal mandate.","D":"Incorrect because closed questions are far easier to tabulate into charts."}}},{"id":"P1_U3_MCQ_046","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_046","question":"A restaurant chain relies on a 2019 industry report to plan its 2026 takeaway delivery strategy. Why is this decision risky?","options":{"A":"Secondary data from 2019 is outdated and fails to reflect major shifts in food-delivery apps and consumer ordering habits","B":"Industry reports never contain numerical market-size estimates","C":"Primary research is illegal in the restaurant and hospitality sector","D":"Older reports always overestimate demand for digital delivery apps"},"correctOption":"A","correctAnswer":"Secondary data from 2019 is outdated and fails to reflect major shifts in food-delivery apps and consumer ordering habits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid changes in technology and consumer behaviour quickly make historical secondary data obsolete.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because industry reports frequently include market-size statistics.","C":"Incorrect because restaurants routinely run primary customer surveys.","D":"Incorrect because a 2019 report would actually understate post-2020 delivery app adoption."}}},{"id":"P1_U3_MCQ_047","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_047","question":"How does presenting market research findings using 'bar charts and pie charts' rather than raw spreadsheet tables assist marketing managers?","options":{"A":"Charts visually highlight key proportions, comparisons, and trends quickly for faster decision-making","B":"Charts automatically correct sampling errors and biased survey questions","C":"Charts eliminate the need to collect accurate numerical responses","D":"Charts prevent competitors from ever copying the business's products"},"correctOption":"A","correctAnswer":"Charts visually highlight key proportions, comparisons, and trends quickly for faster decision-making","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because visual data presentation makes complex patterns immediately clear to decision-makers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because visual formatting cannot fix flawed underlying data collection.","C":"Incorrect because accurate figures are still needed to build valid charts.","D":"Incorrect because internal charts do not create legal product protection."}}},{"id":"P1_U3_MCQ_048","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_048","question":"When is a 'product-oriented' approach most likely to succeed in modern business?","options":{"A":"When a firm develops breakthrough medical or technological innovations where consumers cannot yet imagine what is possible","B":"When selling standard commodity clothing in a saturated high-street market","C":"When operating a local restaurant in a diverse multicultural neighbourhood","D":"When consumer tastes change rapidly every fashion season"},"correctOption":"A","correctAnswer":"When a firm develops breakthrough medical or technological innovations where consumers cannot yet imagine what is possible","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because in cutting-edge R&D fields (such as pharmaceuticals or novel hardware), technical breakthroughs often create entirely new customer demand.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because saturated clothing markets require close market orientation to match shopper styles.","C":"Incorrect because local restaurants succeed by tailoring menus to neighbourhood tastes.","D":"Incorrect because fast-changing fashion markets penalize firms that ignore customer trends."}}},{"id":"P1_U3_MCQ_049","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_049","question":"An online fashion retailer analyzes website 'abandoned shopping cart' analytics and customer return logs before redesigning its sizing guide. Which type of research is this?","options":{"A":"Internal secondary research","B":"External primary focus group","C":"Quota street sampling","D":"External government census research"},"correctOption":"A","correctAnswer":"Internal secondary research","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because website logs and return records are existing operational data held internally by the retailer.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no external focus group discussion was held.","C":"Incorrect because no street interviews were conducted.","D":"Incorrect because the data came from the company's own platform rather than government files."}}},{"id":"P1_U3_MCQ_050","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_050","question":"Why does increasing a survey's 'sample size' from 20 respondents to 1,000 respondents improve market research reliability?","options":{"A":"It reduces random sampling error so results reflect the wider target population more accurately, though at higher cost and time","B":"It guarantees that poorly worded leading questions become unbiased","C":"It eliminates the need to define the target market segment","D":"It makes primary research cheaper than reading free government websites"},"correctOption":"A","correctAnswer":"It reduces random sampling error so results reflect the wider target population more accurately, though at higher cost and time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because larger representative samples minimize the distortion caused by a few unusual responses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a larger sample still produces biased answers if the questions themselves are leading.","C":"Incorrect because researchers must still target the relevant population group.","D":"Incorrect because surveying 1,000 people increases time and fieldwork costs."}}},{"id":"P1_U3_MCQ_051","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_051","question":"During new product development, a smartphone maker creates a working physical sample to test battery safety and gather user ergonomics feedback before mass production. What is this sample called?","options":{"A":"A prototype","B":"A brand extension","C":"A cash cow","D":"A distribution channel"},"correctOption":"A","correctAnswer":"A prototype","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a prototype is an early working model built to test technical feasibility and user reaction prior to full-scale manufacturing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because brand extension uses an established brand name to launch a product in a new category.","C":"Incorrect because a cash cow is an established product generating high steady profits.","D":"Incorrect because a distribution channel moves finished goods to buyers."}}},{"id":"P1_U3_MCQ_052","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_052","question":"How does building a strong, recognizable 'brand image' benefit an athletic footwear company?","options":{"A":"It creates customer loyalty, differentiates shoes from generic rivals, and supports premium pricing with less price-sensitive demand","B":"It eliminates the need to maintain consistent shoe quality or comfort","C":"It legally forbids any competitor from manufacturing running shoes","D":"It reduces advertising expenditure to zero permanently"},"correctOption":"A","correctAnswer":"It creates customer loyalty, differentiates shoes from generic rivals, and supports premium pricing with less price-sensitive demand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because strong brand equity builds emotional trust, encourages repeat purchases, and makes demand more price inelastic.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because poor product quality quickly destroys a brand's reputation.","C":"Incorrect because trademarks protect brand names/logos, not the entire product category.","D":"Incorrect because brands require ongoing promotion to maintain awareness."}}},{"id":"P1_U3_MCQ_053","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_053","question":"A gourmet olive oil producer switches to dark UV-protective glass bottles featuring embossed gold labels and clear origin stories. Which two functions of 'packaging' are highlighted here?","options":{"A":"Protecting product freshness from light damage and promoting a premium brand image on store shelves","B":"Lowering manufacturing unit costs to zero and replacing wholesale distributors","C":"Eliminating the need for legal ingredient labelling and barcode scanning","D":"Making the bottle heavier to increase international air-freight charges"},"correctOption":"A","correctAnswer":"Protecting product freshness from light damage and promoting a premium brand image on store shelves","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because packaging physically protects contents during transport/storage while acting as a silent salesperson reinforcing brand positioning.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because glass and embossed labels increase packaging cost and still use distributors.","C":"Incorrect because legal nutritional/origin information is displayed on packaging.","D":"Incorrect because heavier freight weight is a logistical drawback rather than a marketing objective."}}},{"id":"P1_U3_MCQ_054","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_054","question":"Why are many supermarket snack brands redesigning their packaging using recyclable paper pouches instead of single-use plastics?","options":{"A":"To appeal to environmentally conscious consumers and comply with stricter sustainability expectations","B":"Because paper packaging is always stronger and more waterproof than heavy plastic","C":"To hide mandatory nutritional and allergy warnings from shoppers","D":"Because consumers prefer products with no brand logos on the wrapper"},"correctOption":"A","correctAnswer":"To appeal to environmentally conscious consumers and comply with stricter sustainability expectations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because eco-friendly packaging strengthens brand image among sustainability-minded shoppers and reduces environmental waste.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because paper often requires careful barrier design to match plastic durability.","C":"Incorrect because legal nutritional and allergen info must remain clearly visible.","D":"Incorrect because brands still print prominent logos on recyclable pouches."}}},{"id":"P1_U3_MCQ_055","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_055","question":"During which stage of the 'Product Life Cycle (PLC)' are sales rising slowly, unit costs high due to low output, and cash flow typically negative because of heavy launch promotion?","options":{"A":"Introduction stage","B":"Maturity stage","C":"Saturation stage","D":"Decline stage"},"correctOption":"A","correctAnswer":"Introduction stage","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at introduction, low consumer awareness keeps sales modest while high R&D and launch advertising exceed early revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because maturity features peak sales, strong cash flow, and lower unit costs.","C":"Incorrect because saturation represents peak market penetration rather than slow initial uptake.","D":"Incorrect because decline occurs when sales fall due to changing tastes or superior substitutes."}}},{"id":"P1_U3_MCQ_056","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_056","question":"A wireless earbud brand experiences peak sales volume, intense competition from rival brands, and slowing sales growth as most target consumers already own a pair. Which PLC stage has it reached?","options":{"A":"Development","B":"Introduction","C":"Maturity","D":"Decline"},"correctOption":"C","correctAnswer":"Maturity","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because maturity is characterized by maximum sales plateauing, fierce competition, and heavy persuasive promotion to defend market share.","distractor_reasons":{"A":"Incorrect because development occurs before commercial launch with zero sales.","B":"Incorrect because introduction involves low initial sales and few direct competitors.","C":"Correct selection.","D":"Incorrect because decline involves falling sales rather than plateauing at peak levels."}}},{"id":"P1_U3_MCQ_057","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_057","question":"A classic breakfast cereal entering the 'maturity stage' of its Product Life Cycle launches new honey-almond and chocolate flavours alongside redesigned family-sized boxes. What is this strategy called?","options":{"A":"An extension strategy","B":"Price skimming","C":"Market withdrawal","D":"Product orientation"},"correctOption":"A","correctAnswer":"An extension strategy","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because extension strategies (new flavours, updated packaging, new markets) aim to prolong the profitable maturity phase and delay decline.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because price skimming sets a high initial price at product introduction.","C":"Incorrect because market withdrawal discontinues a declining product.","D":"Incorrect because product orientation focuses on engineering without market feedback."}}},{"id":"P1_U3_MCQ_058","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_058","question":"Which of the following is an effective 'extension strategy' for a baking-soda brand whose traditional cooking sales have plateaued?","options":{"A":"Promoting new uses for the product, such as refrigerator deodorizing and household cleaning","B":"Halting all advertising and reducing retail distribution to two stores","C":"Raising the retail price by 80% without changing the product or packaging","D":"Immediately discontinuing the product line and scrapping factory machinery"},"correctOption":"A","correctAnswer":"Promoting new uses for the product, such as refrigerator deodorizing and household cleaning","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because finding new applications for an existing product attracts fresh demand and extends its life cycle.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cutting promotion and distribution accelerates decline ('harvesting').","C":"Incorrect because an unjustified steep price rise drives buyers to generic substitutes.","D":"Incorrect because discontinuing the product ends its life cycle rather than extending it."}}},{"id":"P1_U3_MCQ_059","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_059","question":"A furniture workshop calculates that making one oak dining table costs $240 in materials, labour, and allocated overheads. If it applies a 40% cost-plus mark-up, what is the selling price?","options":{"A":"$280","B":"$336","C":"$96","D":"$400"},"correctOption":"B","correctAnswer":"$336","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Selling Price = Unit Cost + (Unit Cost × Mark-up %) = $240 + ($240 × 0.40) = $240 + $96 = $336.","distractor_reasons":{"A":"Incorrect because $280 adds $40 directly instead of 40% of $240.","B":"Correct selection.","C":"Incorrect because $96 is only the profit mark-up amount, not the total selling price.","D":"Incorrect because $400 divides $240 by 0.60 instead of adding a 40% mark-up."}}},{"id":"P1_U3_MCQ_060","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_060","question":"What is a major limitation of relying solely on 'cost-plus pricing' in a competitive retail market?","options":{"A":"It ignores competitor prices and how much customers are actually willing to pay, risking overpricing and lost sales","B":"It guarantees that the business will make a financial loss on every unit sold","C":"It is too complex for small businesses to calculate without specialist economists","D":"It forces businesses to sell products below variable manufacturing cost"},"correctOption":"A","correctAnswer":"It ignores competitor prices and how much customers are actually willing to pay, risking overpricing and lost sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost-plus pricing is purely inward-looking; if the firm's unit costs exceed rivals', the resulting price may be uncompetitive.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cost-plus ensures a profit margin per unit if forecasted sales volume is achieved.","C":"Incorrect because simplicity of calculation is actually cost-plus pricing's main advantage.","D":"Incorrect because adding a positive mark-up sets price above unit cost."}}},{"id":"P1_U3_MCQ_061","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_061","question":"A new video-streaming service enters a crowded market at $3.99 per month—well below established rivals charging $11.99—to attract millions of subscribers rapidly before raising prices later. Which pricing strategy is this?","options":{"A":"Price skimming","B":"Penetration pricing","C":"Cost-plus premium pricing","D":"Dynamic surge pricing"},"correctOption":"B","correctAnswer":"Penetration pricing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because penetration pricing sets a low introductory price to break into a competitive market and build market share quickly.","distractor_reasons":{"A":"Incorrect because price skimming sets a high initial price for an innovative product.","B":"Correct selection.","C":"Incorrect because charging far below rivals prioritizes rapid share over high initial unit margins.","D":"Incorrect because dynamic pricing adjusts prices continuously with real-time demand fluctuations."}}},{"id":"P1_U3_MCQ_062","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_062","question":"What is a key risk when a business uses 'penetration pricing' to launch a new product?","options":{"A":"Initial profit margins are very low, and customers may resist future price increases or perceive the brand as low quality","B":"High initial prices deter all price-sensitive buyers from trying the product","C":"Competitors never notice a low-priced rival entering their market","D":"Supermarkets refuse to stock affordable everyday products"},"correctOption":"A","correctAnswer":"Initial profit margins are very low, and customers may resist future price increases or perceive the brand as low quality","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because low launch prices require high sales volume to cover costs and can anchor consumer price expectations too low.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because high initial prices deterring buyers is a risk of price skimming.","C":"Incorrect because aggressive low pricing often triggers retaliatory price cuts from rivals.","D":"Incorrect because supermarkets welcome competitively priced high-turnover items."}}},{"id":"P1_U3_MCQ_063","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_063","question":"Why is 'price skimming' effective for a pharmaceutical or technology firm launching a patented, breakthrough innovation?","options":{"A":"Early adopters are willing to pay a high price for exclusive cutting-edge features, helping the firm rapidly recover heavy R&D costs","B":"There are dozens of identical low-cost substitutes already on supermarket shelves","C":"Low initial prices maximize immediate profit margins per unit","D":"Patent laws require firms to charge the highest legal price for ten years"},"correctOption":"A","correctAnswer":"Early adopters are willing to pay a high price for exclusive cutting-edge features, helping the firm rapidly recover heavy R&D costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because temporary protection from competition and strong early-adopter demand enable high unit margins before rivals catch up.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because abundant close substitutes make skimming unworkable.","C":"Incorrect because skimming relies on high initial prices, not low ones.","D":"Incorrect because patents grant exclusive production rights rather than mandating high prices."}}},{"id":"P1_U3_MCQ_064","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_064","question":"Three petrol stations located on the same highway interchange match each other's fuel prices within one cent every morning. Which pricing strategy are they following?","options":{"A":"Competitive pricing","B":"Price skimming","C":"Penetration pricing","D":"Psychological prestige pricing"},"correctOption":"A","correctAnswer":"Competitive pricing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because competitive pricing sets prices in line with rivals when products are very similar and buyers compare prices easily.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because price skimming applies to new, innovative launches.","C":"Incorrect because penetration pricing sets a deliberately low entry price for a new product.","D":"Incorrect because petrol is a homogenous commodity rather than a prestige luxury."}}},{"id":"P1_U3_MCQ_065","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_065","question":"A fashion retailer runs a '50% Off End-of-Season Clearance Sale' for two weeks to clear winter coats before spring stock arrives. Which pricing method is being used?","options":{"A":"Promotional pricing","B":"Price skimming","C":"Cost-plus mark-up pricing","D":"Predatory monopoly pricing"},"correctOption":"A","correctAnswer":"Promotional pricing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because promotional pricing temporarily reduces prices to stimulate short-term demand, clear seasonal stock, or attract store traffic.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because skimming charges a high launch price for new innovations.","C":"Incorrect because clearance discounts often cut prices near or below full cost rather than adding a mark-up.","D":"Incorrect because seasonal clearance is standard inventory management rather than illegal anti-competitive predation."}}},{"id":"P1_U3_MCQ_066","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_066","question":"What is a potential negative consequence if a sofa retailer runs '50% Off' promotional pricing almost every month of the year?","options":{"A":"Customers refuse to ever buy sofas at full price and the brand's perceived quality is damaged","B":"Profit margins per sofa increase automatically during every discount sale","C":"Competitors are legally prohibited from offering competing discounts","D":"Factory production costs drop by 50% every time a sale is advertised"},"correctOption":"A","correctAnswer":"Customers refuse to ever buy sofas at full price and the brand's perceived quality is damaged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because continuous discounting trains shoppers to wait for sales and erodes trust in regular prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because discounting lowers unit profit margins unless costs fall equally.","C":"Incorrect because rivals can freely run their own promotions.","D":"Incorrect because retail price discounts do not reduce manufacturing costs."}}},{"id":"P1_U3_MCQ_067","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_067","question":"A supermarket prices a popular brand of coffee at $4.99 instead of $5.00, while a luxury watchmaker prices its gold timepiece at a round $12,000. Both firms are applying which pricing concept?","options":{"A":"Psychological pricing","B":"Penetration pricing","C":"Cost-plus pricing","D":"Competitive price matching"},"correctOption":"A","correctAnswer":"Psychological pricing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because psychological pricing uses specific price points ($4.99 to feel under $5; $12,000 round figure to signal prestige) to influence buyer perception.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because penetration pricing sets a low entry price to gain market share.","C":"Incorrect because cost-plus calculates price mechanically from unit cost plus a percentage.","D":"Incorrect because these figures target buyer psychology rather than matching a rival."}}},{"id":"P1_U3_MCQ_068","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_068","question":"An airline uses software that automatically raises ticket prices as seats fill up and departure dates approach, while lowering prices on quiet mid-week flights. Which pricing method is this?","options":{"A":"Dynamic pricing","B":"Static cost-plus pricing","C":"Loss-leader pricing","D":"Penetration pricing"},"correctOption":"A","correctAnswer":"Dynamic pricing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dynamic pricing adjusts prices flexibly in real time according to changing demand levels and remaining capacity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because static cost-plus keeps prices fixed based on unit cost.","C":"Incorrect because loss-leader pricing sells an item below cost to attract buyers for other goods.","D":"Incorrect because penetration pricing is a low introductory launch strategy."}}},{"id":"P1_U3_MCQ_069","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_069","question":"When a coffee shop increases the price of its standard latte by 10%, quantity demanded falls by 25% because many rival cafés are nearby. How is demand for the coffee shop's latte described?","options":{"A":"Price elastic","B":"Price inelastic","C":"Perfectly price inelastic","D":"Unitary elastic"},"correctOption":"A","correctAnswer":"Price elastic","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the percentage change in quantity demanded (25%) is greater than the percentage change in price (10%), giving PED = 2.5 (> 1).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because price inelastic demand changes by a smaller percentage than the price change.","C":"Incorrect because perfectly inelastic demand means quantity demanded does not change at all.","D":"Incorrect because unitary elasticity occurs when percentage changes in quantity and price are equal."}}},{"id":"P1_U3_MCQ_070","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_070","question":"A commuter rail operator raises peak-hour train ticket prices by 8%, and passenger numbers fall by only 2% because commuters have few alternative transport options. What happens to the operator's total sales revenue?","options":{"A":"Total sales revenue increases because demand is price inelastic","B":"Total sales revenue decreases sharply because demand is price elastic","C":"Total sales revenue falls to zero","D":"Total sales revenue remains completely unchanged"},"correctOption":"A","correctAnswer":"Total sales revenue increases because demand is price inelastic","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when demand is price inelastic (%ΔQd < %ΔP), the extra revenue gained per ticket sold outweighs the small drop in ticket volume.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a 2% quantity fall from an 8% price rise indicates inelastic demand, raising total revenue.","C":"Incorrect because 98% of passengers still buy tickets at the higher fare.","D":"Incorrect because an 8% price gain against a 2% volume drop yields a net revenue increase."}}},{"id":"P1_U3_MCQ_071","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_071","question":"A smartphone brand sells 10,000 units per month at $500 each ($5,000,000 revenue). When it cuts the price by 10% to $450, monthly sales jump by 20% to 12,000 units. What is the new monthly revenue?","options":{"A":"$4,500,000","B":"$5,400,000","C":"$5,000,000","D":"$6,000,000"},"correctOption":"B","correctAnswer":"$5,400,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because New Revenue = $450 × 12,000 units = $5,400,000 (an increase of $400,000 because demand is price elastic).","distractor_reasons":{"A":"Incorrect because $4,500,000 multiplies $450 by the old volume of 10,000 units.","B":"Correct selection.","C":"Incorrect because $5,000,000 is the original revenue before the price cut.","D":"Incorrect because $6,000,000 multiplies the old $500 price by the new 12,000 volume."}}},{"id":"P1_U3_MCQ_072","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_072","question":"Which factor is most likely to make demand for a product 'price inelastic'?","options":{"A":"The product is an addictive necessity or strong brand with very few close substitutes","B":"Dozens of identical rival brands are sold side-by-side on the same shelf","C":"The purchase accounts for 40% of a household's annual income and can easily be postponed","D":"Consumers can switch to a cheaper substitute at zero effort or cost"},"correctOption":"A","correctAnswer":"The product is an addictive necessity or strong brand with very few close substitutes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lack of close substitutes, strong brand loyalty, or essential necessity makes buyers keep purchasing even when price rises.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because many identical substitutes make demand highly price elastic.","C":"Incorrect because large, postponable purchases are typically price elastic.","D":"Incorrect because easy switching creates price elastic demand."}}},{"id":"P1_U3_MCQ_073","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_073","question":"A supermarket sells cartons of fresh milk at slightly below cost price to draw families into the store, knowing they will also buy profitable groceries during the same visit. What is this pricing tactic called?","options":{"A":"Loss-leader pricing","B":"Price skimming","C":"Cost-plus pricing","D":"Prestige pricing"},"correctOption":"A","correctAnswer":"Loss-leader pricing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because loss-leader pricing prices a frequently bought staple very low to generate store footfall and higher-margin basket sales.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because price skimming sets a high initial price for new innovations.","C":"Incorrect because cost-plus adds a positive profit margin above unit cost.","D":"Incorrect because prestige pricing uses high prices to signal luxury status."}}},{"id":"P1_U3_MCQ_074","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_074","question":"Why do electronics manufacturers often update their smartphone models every 12 months even when current versions still sell well?","options":{"A":"To act as a continuous extension/innovation strategy that stimulates upgrade demand and prevents rivals from overtaking them in maturity","B":"Because laws require all smartphones to be destroyed after twelve months","C":"To increase unit manufacturing costs while lowering product functionality","D":"Because product life cycles never have a decline stage in technology markets"},"correctOption":"A","correctAnswer":"To act as a continuous extension/innovation strategy that stimulates upgrade demand and prevents rivals from overtaking them in maturity","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid technological innovation shortens life cycles, so regular feature upgrades keep customers upgrading within the brand.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no law mandates annual device replacement.","C":"Incorrect because upgrades aim to add customer value and sustain revenue.","D":"Incorrect because tech products actually decline very rapidly if not updated."}}},{"id":"P1_U3_MCQ_075","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_075","question":"How does a product's 'Unique Selling Point (USP)' support its pricing strategy?","options":{"A":"A clear USP differentiates the product from rivals, reducing price sensitivity and allowing the business to charge a higher price","B":"A USP forces the business to match the lowest discount supermarket price","C":"A USP eliminates the need for packaging or brand promotion","D":"A USP guarantees that fixed production costs fall to zero"},"correctOption":"A","correctAnswer":"A clear USP differentiates the product from rivals, reducing price sensitivity and allowing the business to charge a higher price","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a distinctive, valued feature (USP) makes substitutes less comparable, supporting stronger profit margins.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because undifferentiated commodities—not USP products—are forced into pure price matching.","C":"Incorrect because packaging and promotion are needed to communicate the USP to buyers.","D":"Incorrect because a USP affects perceived value rather than eliminating fixed costs."}}},{"id":"P1_U3_MCQ_076","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_076","question":"A custom wedding-cake baker takes orders directly from brides and delivers cakes straight to wedding venues without using any retail shops or wholesalers. Which distribution channel is this?","options":{"A":"Direct channel (Producer to Consumer)","B":"Traditional wholesale channel","C":"Agent-intermediated export channel","D":"Multi-tier retail chain channel"},"correctOption":"A","correctAnswer":"Direct channel (Producer to Consumer)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a zero-intermediary direct channel moves perishable, bespoke goods straight from producer to final consumer.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no wholesaler buys and resells the cakes.","C":"Incorrect because no overseas sales agent is involved.","D":"Incorrect because no third-party retail stores stock the cakes."}}},{"id":"P1_U3_MCQ_077","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_077","question":"What is a major advantage for a manufacturer selling directly to consumers via its own e-commerce website rather than through supermarkets?","options":{"A":"The manufacturer keeps the full retail profit margin and controls brand presentation and customer data directly","B":"Supermarkets pay all of the manufacturer's individual parcel delivery charges","C":"Consumers can physically inspect and try on products in thousands of local stores immediately","D":"The manufacturer avoids managing individual customer orders or returns"},"correctOption":"A","correctAnswer":"The manufacturer keeps the full retail profit margin and controls brand presentation and customer data directly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cutting out retail intermediaries avoids sharing profit margins and builds direct customer relationships.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because in direct e-commerce the manufacturer handles and funds parcel shipping.","C":"Incorrect because physical store browsing is an advantage of retail channels, not online-only direct sales.","D":"Incorrect because direct selling requires handling individual orders, customer service, and returns."}}},{"id":"P1_U3_MCQ_078","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_078","question":"How does a 'wholesaler' add value in the distribution channel between a large canned-food factory and thousands of small independent corner shops?","options":{"A":"By 'breaking bulk'—buying huge lorry-loads from the factory, storing stock, and selling smaller assorted quantities to local shops","B":"By manufacturing the canned food on behalf of the factory","C":"By guaranteeing that independent shops never pay for the stock they order","D":"By eliminating all transport between factories and retail stores"},"correctOption":"A","correctAnswer":"By 'breaking bulk'—buying huge lorry-loads from the factory, storing stock, and selling smaller assorted quantities to local shops","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because wholesalers bridge the gap between high-volume producers and small retailers that lack warehouse space for full truckloads.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because wholesalers distribute finished goods rather than manufacturing them.","C":"Incorrect because retailers must pay wholesalers for purchased inventory.","D":"Incorrect because wholesalers organize transport and regional warehousing."}}},{"id":"P1_U3_MCQ_079","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_079","question":"Why do large national supermarket chains usually buy groceries directly from food manufacturers instead of using a 'wholesaler'?","options":{"A":"Supermarkets buy in huge bulk quantities for their own regional warehouses, saving the wholesaler's profit margin","B":"Wholesalers are legally forbidden from selling food products to large companies","C":"Supermarkets sell only bespoke handmade goods","D":"Manufacturers refuse to sell large pallet loads to major retail chains"},"correctOption":"A","correctAnswer":"Supermarkets buy in huge bulk quantities for their own regional warehouses, saving the wholesaler's profit margin","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because large retail chains have the scale and logistics hubs to perform the wholesaling function themselves at lower unit cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no law bars wholesalers from serving large firms.","C":"Incorrect because supermarkets sell mass-produced everyday goods.","D":"Incorrect because manufacturers eagerly supply large retail chains."}}},{"id":"P1_U3_MCQ_080","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_080","question":"How does an 'agent' differ from a 'wholesaler' in international distribution?","options":{"A":"An agent negotiates sales on behalf of a producer for a commission without taking ownership of the goods, whereas a wholesaler buys and owns the stock to resell","B":"An agent operates physical supermarket stores, whereas a wholesaler sells only online","C":"An agent manufactures products locally, whereas a wholesaler designs television commercials","D":"An agent is employed exclusively in domestic retail shops, whereas a wholesaler works only in banks"},"correctOption":"A","correctAnswer":"An agent negotiates sales on behalf of a producer for a commission without taking ownership of the goods, whereas a wholesaler buys and owns the stock to resell","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because agents use local market contacts to connect exporters with foreign buyers on commission without taking inventory risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retail chains operate physical stores, not agents.","C":"Incorrect because agents arrange sales rather than manufacturing or advertising.","D":"Incorrect because both operate across commercial supply chains."}}},{"id":"P1_U3_MCQ_081","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_081","question":"Which distribution channel is most appropriate for a producer of fresh strawberries that spoil within 48 hours?","options":{"A":"Short channel: direct to consumers at farm shops or directly to local supermarkets with refrigerated transport","B":"Long four-tier channel passing through national exporters, regional wholesalers, and small corner kiosks","C":"Slow international sea freight via overseas commission agents","D":"Warehousing stock for six months before releasing it to retailers"},"correctOption":"A","correctAnswer":"Short channel: direct to consumers at farm shops or directly to local supermarkets with refrigerated transport","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because perishable produce requires fast, short distribution channels to reach consumers while still fresh.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because multi-tier intermediaries add handling delays that cause fresh fruit to rot.","C":"Incorrect because slow sea freight destroys short-shelf-life berries.","D":"Incorrect because fresh strawberries cannot be stored for months."}}},{"id":"P1_U3_MCQ_082","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_082","question":"How has the growth of 'e-commerce' benefited a small regional craft-tea business?","options":{"A":"It can reach customers nationwide and internationally 24/7 without paying expensive high-street store rents","B":"It eliminates all costs of packaging, parcel shipping, and website cybersecurity","C":"It guarantees that no rival tea brands can advertise online","D":"Customers no longer care about tea flavour or delivery speed"},"correctOption":"A","correctAnswer":"It can reach customers nationwide and internationally 24/7 without paying expensive high-street store rents","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an online storefront removes geographical limits and high-street property overheads for niche and small businesses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because e-commerce still incurs shipping, packaging, and web maintenance costs.","C":"Incorrect because online markets feature intense global competition.","D":"Incorrect because quality and fast delivery remain critical for online reviews and repeat orders."}}},{"id":"P1_U3_MCQ_083","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_083","question":"What is a major challenge for a traditional clothing retailer expanding into 'e-commerce'?","options":{"A":"High rates of customer garment returns due to sizing uncertainty and increased parcel logistics costs","B":"Customers are legally prohibited from buying clothes online using debit cards","C":"E-commerce websites can only be viewed during normal daytime shop hours","D":"Online stores require paying rent on physical shopping-mall units"},"correctOption":"A","correctAnswer":"High rates of customer garment returns due to sizing uncertainty and increased parcel logistics costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shoppers cannot try clothes on before buying online, leading to costly reverse logistics and return processing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because online card and digital payments are standard.","C":"Incorrect because websites operate 24 hours a day.","D":"Incorrect because online operations reduce reliance on physical mall space."}}},{"id":"P1_U3_MCQ_084","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_084","question":"What is the key difference between 'informative advertising' and 'persuasive advertising'?","options":{"A":"Informative advertising gives factual details about a new product's features or uses, whereas persuasive advertising appeals to emotions and brand image to convince buyers it is superior to rivals","B":"Informative advertising is free, whereas persuasive advertising is paid media","C":"Informative advertising is used only in the decline stage, whereas persuasive advertising is used only before product launch","D":"Informative advertising is illegal for consumer goods, whereas persuasive advertising is mandatory"},"correctOption":"A","correctAnswer":"Informative advertising gives factual details about a new product's features or uses, whereas persuasive advertising appeals to emotions and brand image to convince buyers it is superior to rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because informative ads educate consumers (vital at launch or for public health notices), while persuasive ads build brand preference in competitive markets.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both are paid forms of above-the-line advertising.","C":"Incorrect because informative ads are heavily used at introduction, while persuasive ads dominate growth and maturity.","D":"Incorrect because both are lawful when truthful and non-misleading."}}},{"id":"P1_U3_MCQ_085","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_085","question":"A breakfast-cereal brand includes free collectible sports cards inside cereal boxes and offers 'Buy Two, Get One Free' coupons in supermarkets. Which promotional category is this?","options":{"A":"Sales promotion","B":"Public relations (PR)","C":"Personal selling","D":"Television informative advertising"},"correctOption":"A","correctAnswer":"Sales promotion","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sales promotions use short-term incentives (free gifts, coupons, BOGOF, loyalty points) to stimulate immediate purchases.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because PR manages unpaid media coverage and public goodwill rather than point-of-sale coupons.","C":"Incorrect because personal selling involves face-to-face sales conversations.","D":"Incorrect because free gifts and coupons are below-the-line incentives rather than TV commercials."}}},{"id":"P1_U3_MCQ_086","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_086","question":"How does 'sales promotion' differ from 'advertising' in its typical impact on sales?","options":{"A":"Sales promotion triggers a rapid short-term spike in purchases, whereas advertising builds long-term brand awareness and loyalty","B":"Sales promotion is always more expensive than national television advertising","C":"Sales promotion is targeted only at factory suppliers, whereas advertising targets only employees","D":"Sales promotion never uses discounts, samples, or competitions"},"correctOption":"A","correctAnswer":"Sales promotion triggers a rapid short-term spike in purchases, whereas advertising builds long-term brand awareness and loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because coupons and multi-buys encourage immediate action ('buy now'), while advertising shapes lasting brand perception.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because national TV advertising is usually far costlier than point-of-sale promotions.","C":"Incorrect because both target end consumers (and trade promotions can also target retailers).","D":"Incorrect because discounts, free samples, and competitions are classic sales promotion tools."}}},{"id":"P1_U3_MCQ_087","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_087","question":"A sports-drink company sponsors a city charity marathon and donates clean water stations, earning positive stories on local TV news and newspapers without buying ad space. Which promotional method is this?","options":{"A":"Public relations (PR) and sponsorship","B":"Direct mail leaflets","C":"Personal door-to-door selling","D":"Loss-leader pricing"},"correctOption":"A","correctAnswer":"Public relations (PR) and sponsorship","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because PR and community sponsorship generate credible earned media coverage and strengthen public goodwill.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because direct mail sends paid promotional letters to households.","C":"Incorrect because personal selling involves individual sales pitches.","D":"Incorrect because loss-leader pricing is a retail pricing tactic."}}},{"id":"P1_U3_MCQ_088","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_088","question":"Why is 'personal selling' essential for an industrial machinery manufacturer selling $500,000 custom factory presses to corporate buyers?","options":{"A":"Complex, high-value B2B equipment requires tailored technical demonstrations, specification negotiation, and relationship trust","B":"Personal selling is the cheapest way to reach 10 million individual supermarket shoppers","C":"Industrial buyers are legally forbidden from reading technical brochures or websites","D":"Personal selling requires zero product knowledge from sales representatives"},"correctOption":"A","correctAnswer":"Complex, high-value B2B equipment requires tailored technical demonstrations, specification negotiation, and relationship trust","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high-ticket customized B2B orders involve detailed technical questions and contract terms best handled one-to-one.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because personal selling has a very high cost per contact and is unsuitable for mass consumer staples.","C":"Incorrect because brochures and websites support the sales process.","D":"Incorrect because B2B sales engineers need deep technical expertise."}}},{"id":"P1_U3_MCQ_089","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_089","question":"A local independent plumber has a monthly marketing budget of $300. Which promotional combination is most cost-effective?","options":{"A":"Targeted local social media ads, a free online business directory listing, and magnetic signs on the work van","B":"A 30-second commercial during an international football final","C":"Full-page colour advertisements in national glossy fashion magazines","D":"Sponsoring an international Formula 1 racing team"},"correctOption":"A","correctAnswer":"Targeted local social media ads, a free online business directory listing, and magnetic signs on the work van","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because geo-targeted social ads, local listings, and vehicle signage reach nearby homeowners at very low cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because global sports broadcasts cost hundreds of thousands of dollars and waste reach outside the plumber's town.","C":"Incorrect because national fashion magazines are expensive and poorly targeted for local plumbing.","D":"Incorrect because global motorsport sponsorship far exceeds a small local budget."}}},{"id":"P1_U3_MCQ_090","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_090","question":"How does 'social media influencer marketing' help a new skincare brand reach teenage and young-adult buyers?","options":{"A":"Trusted content creators demonstrate the products authentically to engaged niche followers at lower cost than traditional TV","B":"Influencers guarantee that products never need safety testing","C":"Social media posts reach retired citizens without smartphones more effectively than newspapers","D":"Influencer campaigns eliminate the need for an online checkout or retail stock"},"correctOption":"A","correctAnswer":"Trusted content creators demonstrate the products authentically to engaged niche followers at lower cost than traditional TV","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because younger consumers follow digital creators closely and respond strongly to peer-style recommendations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cosmetic safety laws remain strictly enforceable.","C":"Incorrect because print media and TV reach older demographics more broadly than youth social apps.","D":"Incorrect because e-commerce checkout and inventory remain essential to fulfil orders."}}},{"id":"P1_U3_MCQ_091","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_091","question":"What is a major risk when a sportswear brand relies heavily on a celebrity endorsement for its promotional campaigns?","options":{"A":"If the celebrity becomes involved in a public scandal, negative publicity can immediately damage the brand's reputation","B":"Celebrity endorsements are completely free for the sportswear company","C":"Consumers never recognize famous athletes in advertisements","D":"Celebrity endorsements prevent the brand from selling shoes in retail stores"},"correctOption":"A","correctAnswer":"If the celebrity becomes involved in a public scandal, negative publicity can immediately damage the brand's reputation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because linking brand identity closely to an individual exposes the company to reputational fallout from that person's private actions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because celebrity contracts are very expensive.","C":"Incorrect because high recognition is the exact reason brands hire celebrities.","D":"Incorrect because endorsements aim to boost retail and online store sales."}}},{"id":"P1_U3_MCQ_092","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_092","question":"A home-furnishings company generates $2,400,000 in annual sales and allocates 6% of sales revenue to its annual marketing budget. If $54,000 is spent on digital ads, how much remains for other promotional activities?","options":{"A":"$90,000","B":"$144,000","C":"$346,000","D":"$54,000"},"correctOption":"A","correctAnswer":"$90,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Total Budget = 6% of $2,400,000 = $144,000; Remaining Budget = $144,000 − $54,000 = $90,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $144,000 is the total marketing budget before subtracting the $54,000 digital ad spend.","C":"Incorrect because $346,000 uses 16.7% instead of 6%.","D":"Incorrect because $54,000 is the amount already spent on digital ads."}}},{"id":"P1_U3_MCQ_093","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_093","question":"How can a marketing director best evaluate whether a $30,000 online promotional campaign was financially worthwhile?","options":{"A":"Compare the extra gross profit generated from tracked campaign sales and promo codes against the $30,000 campaign cost","B":"Count only how many employees inside the company liked the advert's colours","C":"Check whether the company's factory rent decreased during the campaign","D":"Verify that the campaign used every single dollar of the budget regardless of sales"},"correctOption":"A","correctAnswer":"Compare the extra gross profit generated from tracked campaign sales and promo codes against the $30,000 campaign cost","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because promotional effectiveness is measured by comparing incremental sales/profit return against campaign expenditure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because internal staff opinions do not measure customer buying response.","C":"Incorrect because fixed factory rent is unrelated to promotional return.","D":"Incorrect because spending a full budget without generating profitable sales is ineffective."}}},{"id":"P1_U3_MCQ_094","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_094","question":"Why does an 'omnichannel' retail strategy—combining physical stores, a mobile app, and click-and-collect website ordering—give a clothing brand a competitive advantage?","options":{"A":"Customers can browse, buy, collect, or return items conveniently across whichever channel suits them best at any moment","B":"It eliminates the need to maintain any inventory tracking software","C":"It allows the retailer to close all warehouses and delivery networks","D":"It forces every customer to visit a physical store before viewing prices"},"correctOption":"A","correctAnswer":"Customers can browse, buy, collect, or return items conveniently across whichever channel suits them best at any moment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because integrating online convenience with physical store immediacy maximizes customer reach and convenience.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because omnichannel retailing requires sophisticated real-time stock integration.","C":"Incorrect because fulfilling click-and-collect and home deliveries relies on strong warehousing.","D":"Incorrect because online channels display prices transparently anytime."}}},{"id":"P1_U3_MCQ_095","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_095","question":"Which factor is most decisive when a luxury perfume house chooses which retail outlets ('Place') should stock its fragrance?","options":{"A":"Selecting prestigious department stores and exclusive boutiques whose upscale environment reinforces the brand's luxury image","B":"Placing bottles next to motor oil in discount roadside petrol stations for maximum volume","C":"Choosing only wholesale cash-and-carry warehouses with bare concrete floors","D":"Distributing exclusively through unbranded vending machines in train stations"},"correctOption":"A","correctAnswer":"Selecting prestigious department stores and exclusive boutiques whose upscale environment reinforces the brand's luxury image","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because selective distribution in high-end stores aligns Place with the brand's premium Product and Price positioning.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because discount petrol stations would destroy a luxury perfume's exclusive image.","C":"Incorrect because bare warehouses clash with prestige brand expectations.","D":"Incorrect because station vending machines cheapen luxury positioning."}}},{"id":"P1_U3_MCQ_096","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_096","question":"Why do manufacturers of mass-market chewing gum and batteries use 'intensive distribution' across supermarkets, convenience stores, cinemas, and vending machines?","options":{"A":"Because these low-cost impulse items rely on maximum convenience and immediate availability wherever shoppers happen to be","B":"Because chewing gum requires personalized technical consultation before purchase","C":"Because batteries are luxury status symbols bought once every ten years","D":"Because intensive distribution avoids using any wholesalers or retailers"},"correctOption":"A","correctAnswer":"Because these low-cost impulse items rely on maximum convenience and immediate availability wherever shoppers happen to be","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because buyers rarely travel far for routine convenience items; if one brand is unavailable, they immediately buy a rival.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because chewing gum is a simple everyday purchase requiring zero technical advice.","C":"Incorrect because batteries are routine utilitarian goods.","D":"Incorrect because intensive distribution relies heavily on wholesalers and multiple retail tiers."}}},{"id":"P1_U3_MCQ_097","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_097","question":"How does 'direct email marketing' using personalized customer purchase histories outperform untargeted printed flyers dropped through random letterboxes?","options":{"A":"It has virtually zero printing/postage cost, tailors offers to proven buyer interests, and allows instant click-through tracking","B":"It reaches households that have no internet access or email accounts","C":"Consumers never delete marketing emails without reading every word","D":"Direct email marketing is exempt from data privacy and consent regulations"},"correctOption":"A","correctAnswer":"It has virtually zero printing/postage cost, tailors offers to proven buyer interests, and allows instant click-through tracking","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because targeted email segments buyers by past behaviour, dramatically lowering cost per conversion and enabling precise analytics.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because offline households are reached by printed mail rather than email.","C":"Incorrect because spam filters and inbox clutter remain challenges if emails are irrelevant.","D":"Incorrect because businesses must comply with data protection and opt-in consent laws."}}},{"id":"P1_U3_MCQ_098","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_098","question":"A B2B cybersecurity software firm exhibits at an international banking technology trade fair. Which promotional strengths does a trade fair offer?","options":{"A":"Concentrated face-to-face access to pre-qualified corporate decision-makers and live software demonstrations","B":"Reaching millions of children watching Saturday morning cartoons","C":"Zero exhibition booth rental or staff travel expenses","D":"Complete secrecy from competitors attending the same industry"},"correctOption":"A","correctAnswer":"Concentrated face-to-face access to pre-qualified corporate decision-makers and live software demonstrations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade fairs gather serious industry buyers in one venue, supporting high-value personal selling and product demos.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because banking trade fairs target corporate executives, not general child consumers.","C":"Incorrect because trade fair stands and travel carry substantial costs.","D":"Incorrect because rivals also attend trade fairs and observe industry launches."}}},{"id":"P1_U3_MCQ_099","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_099","question":"Why do loyalty card schemes (such as earning points per dollar spent for future store vouchers) serve as both a 'sales promotion' and a 'market research' tool?","options":{"A":"Points incentivize repeat customer visits while checkout scans automatically record detailed buying patterns for segmentation","B":"Loyalty cards legally prevent customers from ever visiting a competing supermarket","C":"Loyalty cards eliminate the need to price products competitively","D":"Loyalty schemes cost the retailer nothing to administer or redeem"},"correctOption":"A","correctAnswer":"Points incentivize repeat customer visits while checkout scans automatically record detailed buying patterns for segmentation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reward points encourage retention while basket data generates continuous internal secondary research.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shoppers remain free to shop at multiple retailers.","C":"Incorrect because core shelf prices must still remain competitive.","D":"Incorrect because IT systems and voucher redemptions represent real promotional costs."}}},{"id":"P1_U3_MCQ_100","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_100","question":"When choosing promotional media for a complex pension and life-insurance plan aimed at middle-aged professionals, why are detailed financial newspaper articles and advisor consultations more effective than 6-second social media clips?","options":{"A":"High-involvement financial services require detailed explanation, credibility, and personal reassurance rather than brief impulse entertainment","B":"Middle-aged professionals are legally banned from using smartphones","C":"Newspaper advertisements are always cheaper than short social media posts","D":"Financial services never require regulatory risk disclosures"},"correctOption":"A","correctAnswer":"High-involvement financial services require detailed explanation, credibility, and personal reassurance rather than brief impulse entertainment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because complex, long-term financial commitments demand trust and thorough information that ultra-short clips cannot convey.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because professionals use smartphones, though they rely on credible sources for major financial choices.","C":"Incorrect because print ads in major newspapers are typically costlier than social posts.","D":"Incorrect because financial promotions require clear regulatory disclosures."}}},{"id":"P1_U3_MCQ_101","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_101","question":"A luxury Swiss watchmaker sells watches at $15,000 through exclusive boutiques, yet promotes them with 'Buy One, Get One Free' flyers distributed outside subway stations. Why is this marketing strategy ineffective?","options":{"A":"The four elements of the marketing mix conflict: discount subway flyers undermine the luxury Product, high Price, and exclusive Place positioning","B":"Luxury watches are always bought as impulse purchases by subway commuters","C":"Exclusive boutiques require heavy discount coupons to attract wealthy buyers","D":"Flyers are illegal to distribute in major cities"},"correctOption":"A","correctAnswer":"The four elements of the marketing mix conflict: discount subway flyers undermine the luxury Product, high Price, and exclusive Place positioning","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an effective marketing strategy requires all elements of the 4Ps to align consistently around the target segment's expectations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $15,000 watches are high-involvement luxury purchases.","C":"Incorrect because BOGOF promotions cheapen luxury prestige.","D":"Incorrect because the flaw is strategic inconsistency rather than illegality."}}},{"id":"P1_U3_MCQ_102","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_102","question":"A budget gym chain targets price-conscious students and young workers with no-frills 24-hour facilities. Which integrated marketing mix best supports its strategy?","options":{"A":"Low monthly membership fees, digital self-service sign-ups, and targeted social media referral promotions","B":"High $300 monthly fees, personal butler service, and print adverts in private-jet magazines","C":"Penetration pricing followed by an immediate 400% price hike in month two","D":"Exclusive invitation-only memberships sold through luxury hotel concierges"},"correctOption":"A","correctAnswer":"Low monthly membership fees, digital self-service sign-ups, and targeted social media referral promotions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because affordable pricing, automated low-overhead operations, and digital youth marketing reinforce a coherent cost-focused strategy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because luxury pricing and butler service target wealthy segments rather than budget students.","C":"Incorrect because extreme sudden price hikes cause immediate membership cancellations.","D":"Incorrect because exclusive hotel concierges misalign with a mass-budget gym."}}},{"id":"P1_U3_MCQ_103","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_103","question":"During an economic recession when consumer disposable incomes fall, how should a mid-priced family restaurant chain adapt its marketing strategy?","options":{"A":"Introduce value-meal bundles, highlight affordable family sharing platters, and offer mid-week loyalty discounts","B":"Double menu prices and remove all affordable children's meals","C":"Stop all promotional communication until the economy recovers","D":"Rebrand exclusively as an ultra-expensive caviar dining room"},"correctOption":"A","correctAnswer":"Introduce value-meal bundles, highlight affordable family sharing platters, and offer mid-week loyalty discounts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because recessions make diners more price-elastic, so value-oriented bundles preserve footfall and customer loyalty.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because steep price rises when incomes fall accelerate customer loss.","C":"Incorrect because cutting promotion makes customers forget the brand.","D":"Incorrect because pivoting abruptly to ultra-luxury alienates existing family customers."}}},{"id":"P1_U3_MCQ_104","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_104","question":"Why might a consumer-goods manufacturer expand into 'foreign markets' even when its domestic market is still profitable?","options":{"A":"To achieve faster sales growth, spread risk across multiple economies, and gain further economies of scale","B":"Because foreign markets never have local competitors or cultural differences","C":"Because exporting eliminates all shipping, insurance, and currency-exchange risks","D":"Because domestic consumer protection laws stop applying once a firm exports"},"correctOption":"A","correctAnswer":"To achieve faster sales growth, spread risk across multiple economies, and gain further economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because international expansion opens larger customer bases, reduces reliance on one home economy, and extends product life cycles.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because foreign markets feature strong local rivals and distinct cultural preferences.","C":"Incorrect because international trade adds freight, tariff, and exchange-rate complexities.","D":"Incorrect because firms must obey both domestic and foreign market regulations."}}},{"id":"P1_U3_MCQ_105","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_105","question":"What is a major challenge for a Western food manufacturer entering an East Asian retail market for the first time?","options":{"A":"Adapting recipes, packaging colours, and brand names to local cultural tastes, languages, and food-safety regulations","B":"Consumers in East Asia never buy packaged supermarket foods","C":"International shipping containers are legally banned from carrying processed foods","D":"Foreign companies are forbidden from conducting market research abroad"},"correctOption":"A","correctAnswer":"Adapting recipes, packaging colours, and brand names to local cultural tastes, languages, and food-safety regulations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cultural differences in flavour preferences, symbolism, and labelling laws require careful product and promotional localization.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because East Asia has massive, modern retail grocery markets.","C":"Incorrect because containerized food trade is standard globally.","D":"Incorrect because cross-cultural market research is essential and widely practiced."}}},{"id":"P1_U3_MCQ_106","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_106","question":"How does forming a 'joint venture' with a local partner help a European supermarket chain enter a complex foreign market?","options":{"A":"The local partner contributes established supply chains, regulatory knowledge, and cultural insight while sharing capital costs and risks","B":"The European chain keeps 100% of all profits without sharing any decision-making","C":"A joint venture guarantees that cultural disagreements between partners never arise","D":"The European chain avoids investing any capital or management expertise"},"correctOption":"A","correctAnswer":"The local partner contributes established supply chains, regulatory knowledge, and cultural insight while sharing capital costs and risks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pooling resources with a domestic company overcomes local regulatory and cultural barriers faster than going alone.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profits and control are shared between the joint-venture partners.","C":"Incorrect because differing management cultures and profit priorities are key risks of joint ventures.","D":"Incorrect because both partners contribute capital and capabilities."}}},{"id":"P1_U3_MCQ_107","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_107","question":"What is a primary disadvantage of entering a foreign market through a 'joint venture'?","options":{"A":"Disagreements over strategy, profit reinvestment, or quality standards between the two partner companies can slow decisions","B":"The foreign entrant must bear 100% of the financial startup risk alone","C":"The business gains zero access to the local partner's distribution network","D":"Joint ventures are illegal in all emerging economies"},"correctOption":"A","correctAnswer":"Disagreements over strategy, profit reinvestment, or quality standards between the two partner companies can slow decisions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shared ownership requires consensus, and clashes in corporate culture or strategic goals can undermine performance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because risk sharing is an advantage of joint ventures.","C":"Incorrect because accessing local networks is a primary benefit.","D":"Incorrect because many countries actively encourage foreign-local joint ventures."}}},{"id":"P1_U3_MCQ_108","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_108","question":"A popular animated-film studio grants a foreign toy manufacturer legal permission to produce and sell branded action figures in exchange for a royalty fee on sales. Which international entry method is this?","options":{"A":"Licensing","B":"Wholly owned foreign subsidiary","C":"Direct mail exporting","D":"Horizontal merger"},"correctOption":"A","correctAnswer":"Licensing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because licensing allows a foreign licensee to use intellectual property (characters, patents, trademarks) locally for royalty payments without the licensor building factories.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a wholly owned subsidiary requires building or buying foreign operations directly.","C":"Incorrect because direct exporting ships home-made goods abroad rather than licensing local production.","D":"Incorrect because a merger combines two firms into one corporate entity."}}},{"id":"P1_U3_MCQ_109","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_109","question":"What is a key risk for a brand owner using 'licensing' to expand into overseas markets?","options":{"A":"If the foreign licensee produces poor-quality goods, the original brand's global reputation can suffer damage","B":"The brand owner must fund 100% of the foreign factory construction costs","C":"The brand owner receives no royalty income when foreign sales grow","D":"Licensing exposes the brand owner to high international shipping tariffs on finished goods"},"correctOption":"A","correctAnswer":"If the foreign licensee produces poor-quality goods, the original brand's global reputation can suffer damage","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because delegating production to an independent licensee reduces direct quality control and risks creating a future competitor.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the local licensee funds its own production facilities.","C":"Incorrect because royalties are typically calculated as a percentage of licensee sales.","D":"Incorrect because local production under license avoids finished-good import tariffs."}}},{"id":"P1_U3_MCQ_110","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_110","question":"A US coffee-house brand expands into 25 countries by selling local entrepreneurs the right to operate stores under its brand name, store layout, and training manual. Which expansion strategy is this?","options":{"A":"International franchising","B":"Commission-agent exporting","C":"Unbranded wholesale distribution","D":"Product orientation"},"correctOption":"A","correctAnswer":"International franchising","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because franchising replicates a complete business format rapidly abroad using franchisee capital and local management.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because agents negotiate product orders rather than operating branded retail cafés.","C":"Incorrect because franchises rely heavily on uniform brand identity.","D":"Incorrect because product orientation describes engineering focus rather than an entry method."}}},{"id":"P1_U3_MCQ_111","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_111","question":"An exporter ships bicycles valued at $200 each to a foreign country that imposes a 15% import tariff on bicycles. What is the landed cost per bicycle after the tariff is added?","options":{"A":"$230","B":"$215","C":"$170","D":"$300"},"correctOption":"A","correctAnswer":"$230","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Tariff = 15% of $200 = $30; Landed Cost = $200 + $30 = $230, making the imported bicycle less price-competitive.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $215 adds $15 flat rather than 15% of $200.","C":"Incorrect because $170 subtracts $30 instead of adding the import tax.","D":"Incorrect because $300 adds a 50% tariff instead of 15%."}}},{"id":"P1_U3_MCQ_112","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_112","question":"How does a 'trade bloc' (such as a customs union or free-trade area) benefit a manufacturer exporting to member countries within that bloc?","options":{"A":"Tariffs and import quotas between member states are eliminated, keeping export prices competitive","B":"All member countries automatically speak the exact same language and share identical consumer tastes","C":"Transport distances between member countries are reduced to zero","D":"Competitors inside the trade bloc are forbidden from advertising"},"correctOption":"A","correctAnswer":"Tariffs and import quotas between member states are eliminated, keeping export prices competitive","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because free-trade agreements remove tariff barriers among members, lowering cross-border trading costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cultural and linguistic differences still exist across member states.","C":"Incorrect because physical geography and freight costs remain.","D":"Incorrect because trade blocs actually intensify competition among member firms."}}},{"id":"P1_U3_MCQ_113","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_113","question":"A cosmetics company advertises a face cream claiming it 'permanently erases all wrinkles in 24 hours,' despite zero clinical evidence. Which legal control over marketing is being breached?","options":{"A":"Misleading advertising and false product description laws","B":"Minimum wage employment legislation","C":"Trade union collective bargaining rules","D":"Import quota tariff regulations"},"correctOption":"A","correctAnswer":"Misleading advertising and false product description laws","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumer protection and advertising standards laws prohibit false, unsubstantiated performance claims.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because minimum wage laws govern employee pay rather than advert claims.","C":"Incorrect because union rules govern industrial relations.","D":"Incorrect because import tariffs govern cross-border trade taxes."}}},{"id":"P1_U3_MCQ_114","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_114","question":"A customer buys a brand-new washing machine that stops spinning after two weeks due to a factory wiring fault, and the retailer refuses to repair, replace, or refund it. Which consumer protection principle is violated?","options":{"A":"Goods sold must be of satisfactory quality and fit for their intended purpose","B":"Retailers must guarantee that every customer enjoys the colour of the appliance","C":"Manufacturers must sell all appliances at zero profit margin","D":"Customers are entitled to unlimited free electricity for five years"},"correctOption":"A","correctAnswer":"Goods sold must be of satisfactory quality and fit for their intended purpose","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumer protection laws grant buyers statutory remedies when faulty goods fail to perform their normal function.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because subjective colour preference is not a statutory defect.","C":"Incorrect because businesses may earn normal profits.","D":"Incorrect because utility bills are unrelated to appliance quality laws."}}},{"id":"P1_U3_MCQ_115","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_115","question":"Why do consumer protection laws require packaged foods to display accurate net weights, ingredient lists, and allergen warnings?","options":{"A":"To prevent deceptive short-weighing and protect consumers with severe food allergies from dangerous health risks","B":"To make food packaging more expensive for small bakeries","C":"To eliminate the need for supermarket barcode scanners","D":"To allow manufacturers to substitute cheaper ingredients secretly"},"correctOption":"A","correctAnswer":"To prevent deceptive short-weighing and protect consumers with severe food allergies from dangerous health risks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because weights-and-measures and labelling laws ensure fair value for money and vital consumer safety transparency.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cost increases are a compliance side-effect, not the purpose of the law.","C":"Incorrect because barcodes remain standard for retail checkout.","D":"Incorrect because accurate labelling specifically prevents hidden ingredient substitution."}}},{"id":"P1_U3_MCQ_116","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_116","question":"How do 'legal controls over marketing' affect a business's costs and marketing decisions?","options":{"A":"Compliance raises packaging, testing, and legal review costs, yet protects the brand from heavy fines, product recalls, and lost customer trust","B":"Legal controls reduce compliance costs to zero and allow unrestricted promotional claims","C":"Legal controls apply only to online retailers and exempt physical high-street shops","D":"Legal controls eliminate all competition within the industry"},"correctOption":"A","correctAnswer":"Compliance raises packaging, testing, and legal review costs, yet protects the brand from heavy fines, product recalls, and lost customer trust","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because adhering to safety and advertising rules requires upfront expenditure, while preventing far costlier legal penalties and reputational collapse.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because compliance involves real testing and legal review costs.","C":"Incorrect because consumer protection applies across both online and physical channels.","D":"Incorrect because regulation sets fair standards rather than eliminating rivals."}}},{"id":"P1_U3_MCQ_117","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_117","question":"A supermarket advertises a 'Was $100, Now $60' blender discount, even though the blender was never sold at $100 in any of its stores. Why is this practice unlawful in many countries?","options":{"A":"Deceptive price-comparison claims mislead consumers about genuine savings and breach fair-trading regulations","B":"Supermarkets are legally forbidden from ever discounting kitchen appliances","C":"All blenders must be sold using cost-plus pricing by law","D":"Consumers are prohibited from comparing prices across different stores"},"correctOption":"A","correctAnswer":"Deceptive price-comparison claims mislead consumers about genuine savings and breach fair-trading regulations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fictitious 'was/now' reference prices deceive shoppers and violate consumer protection rules against misleading pricing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because genuine discounts are completely lawful.","C":"Incorrect because firms choose their own pricing methods within fair-trading rules.","D":"Incorrect because price comparison is encouraged."}}},{"id":"P1_U3_MCQ_118","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_118","question":"An online retailer automatically ticks a hidden checkout box adding a $15 monthly subscription fee to customers' baskets unless they spot and untick it. Which legal issue does this violate?","options":{"A":"Consumer contract laws requiring clear, explicit opt-in consent before charging for additional items","B":"Workplace health and safety machinery rules","C":"International patent licensing treaties","D":"Quota sampling guidelines for street surveys"},"correctOption":"A","correctAnswer":"Consumer contract laws requiring clear, explicit opt-in consent before charging for additional items","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because modern e-commerce consumer laws ban pre-ticked hidden charges and require transparent pricing upfront.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because workplace safety rules govern employee physical safety.","C":"Incorrect because patent treaties protect inventions.","D":"Incorrect because quota sampling relates to market research."}}},{"id":"P1_U3_MCQ_119","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_119","question":"Why do consumer laws in many jurisdictions give online shoppers a 'cooling-off period' (e.g., 14 days) to return goods bought at a distance?","options":{"A":"Because online buyers cannot physically inspect or test products before purchase, reducing perceived buying risk and encouraging e-commerce trust","B":"Because online retailers never display product photos or descriptions","C":"To force all online businesses to close their websites and open physical shops","D":"Because postal delivery companies lose 50% of all parcels"},"correctOption":"A","correctAnswer":"Because online buyers cannot physically inspect or test products before purchase, reducing perceived buying risk and encouraging e-commerce trust","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because statutory return rights compensate for the inability to examine goods in person prior to ordering.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because online stores provide photos and specs, yet physical inspection remains impossible.","C":"Incorrect because cooling-off rules actually boost consumer confidence to shop online.","D":"Incorrect because parcel loss is handled separately from cooling-off return rights."}}},{"id":"P1_U3_MCQ_120","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_120","question":"A toy manufacturer discovers that a small detachable wheel on its new toddler truck poses a choking hazard. Rather than waiting for regulators to act, it immediately announces a voluntary public recall and full refund. How does this protect long-term marketing strategy?","options":{"A":"Proactive accountability demonstrates ethical responsibility, prevents injuries, and preserves long-term parent trust in the brand","B":"Voluntary recalls eliminate all short-term refund and logistics costs","C":"Issuing a recall exempts the company from future safety testing","D":"Product recalls immediately double current-month sales revenue"},"correctOption":"A","correctAnswer":"Proactive accountability demonstrates ethical responsibility, prevents injuries, and preserves long-term parent trust in the brand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because transparent, swift action protects child safety and prevents far worse reputational ruin from a cover-up.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because recalls incur substantial short-term refund and collection expenses.","C":"Incorrect because safety standards remain strictly enforced.","D":"Incorrect because recalls temporarily reduce sales while protecting long-term brand survival."}}},{"id":"P1_U3_MCQ_121","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_121","question":"A domestic electric-scooter startup wants to enter a neighbouring country quickly with limited capital, but faces unfamiliar local traffic laws and retail networks. Which entry strategy is most suitable?","options":{"A":"Forming a joint venture or appointing a local distributor/agent with established regulatory and retail connections","B":"Building a wholly owned gigafactory abroad before conducting any market research","C":"Using mass-market TV adverts in its home language without local translation","D":"Ignoring foreign scooter safety regulations to save testing costs"},"correctOption":"A","correctAnswer":"Forming a joint venture or appointing a local distributor/agent with established regulatory and retail connections","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because partnering with a local firm or distributor provides immediate market knowledge and shared investment when capital is constrained.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because building a wholly owned foreign factory requires huge capital and carries high risk without local insight.","C":"Incorrect because untranslated home-market TV ads fail to connect with foreign buyers.","D":"Incorrect because breaching local safety rules leads to import bans and fines."}}},{"id":"P1_U3_MCQ_122","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_122","question":"When developing a 'marketing strategy' to enter a mature, highly competitive domestic market with a new brand of mineral water, which factor is most critical to evaluate?","options":{"A":"Whether the product has a clear USP (such as eco-packaging or added electrolytes) and sufficient promotional budget to win shelf space from entrenched rivals","B":"Whether the factory uses time-rate or piece-rate wages for warehouse cleaners","C":"Whether the company's head office has a flat or tall span of control","D":"Whether competitors use random or quota sampling in their internal HR surveys"},"correctOption":"A","correctAnswer":"Whether the product has a clear USP (such as eco-packaging or added electrolytes) and sufficient promotional budget to win shelf space from entrenched rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because breaking into a saturated market requires meaningful differentiation and strong promotional/distribution backing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because internal cleaner wage systems do not determine external market entry success.","C":"Incorrect because internal span of control is an HR/organisational factor rather than a market-entry determinant.","D":"Incorrect because HR survey sampling is unrelated to winning retail shelf space."}}},{"id":"P1_U3_MCQ_123","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_123","question":"How does a strong 'social media customer-support and community strategy' reinforce the other elements of a brand's marketing mix?","options":{"A":"It provides real-time customer feedback to improve Product features, communicates Promotional offers, and drives traffic to e-commerce Place channels","B":"It eliminates the need to manufacture reliable products or price them fairly","C":"It replaces all physical delivery logistics for tangible goods","D":"It exempts the business from consumer refund and advertising laws"},"correctOption":"A","correctAnswer":"It provides real-time customer feedback to improve Product features, communicates Promotional offers, and drives traffic to e-commerce Place channels","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because digital engagement connects ongoing market research, promotion, and online distribution into a cohesive customer experience.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because product quality and fair pricing remain foundational.","C":"Incorrect because physical goods still require freight and parcel delivery.","D":"Incorrect because online channels remain fully subject to consumer protection laws."}}},{"id":"P1_U3_MCQ_124","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_124","question":"A solar-lantern manufacturer targets off-grid rural households in developing regions. Which coordinated 4Ps marketing strategy best fits this target segment?","options":{"A":"Durable weatherproof lantern design, affordable micro-instalment pricing, distribution via local rural cooperatives, and live village demonstrations","B":"Fragile glass designer lamps priced at $800, sold exclusively in luxury airport duty-free shops","C":"Subscription-only smartphone app controls requiring high-speed fiber broadband","D":"High-price skimming aimed at urban luxury penthouse owners"},"correctOption":"A","correctAnswer":"Durable weatherproof lantern design, affordable micro-instalment pricing, distribution via local rural cooperatives, and live village demonstrations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rugged product design, accessible payment terms, local rural distribution, and hands-on demos directly address rural off-grid customer needs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because luxury airport retail and $800 pricing do not reach rural off-grid households.","C":"Incorrect because off-grid rural communities lack fiber internet infrastructure.","D":"Incorrect because urban penthouse owners are a completely different target segment."}}},{"id":"P1_U3_MCQ_125","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_125","question":"Why must a business continuously review and adapt its 'marketing strategy' even after achieving market leadership?","options":{"A":"Because consumer tastes, competitor actions, technology, and economic or legal conditions constantly evolve, making static strategies obsolete","B":"Because government regulations force market leaders to change their brand logos every six months","C":"Because products in the maturity stage never experience competition or decline","D":"Because market research becomes illegal once a firm reaches a 30% market share"},"correctOption":"A","correctAnswer":"Because consumer tastes, competitor actions, technology, and economic or legal conditions constantly evolve, making static strategies obsolete","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dynamic external markets require ongoing research, product renewal, and agile marketing mix adjustments to sustain competitive advantage.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because governments do not mandate periodic logo redesigns.","C":"Incorrect because mature markets face intense competition and eventual decline without extension strategies.","D":"Incorrect because market research remains lawful and essential at every market share level."}}},{"id":"P1_U3_MCQ_126","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_126","question":"A subscription meal-kit company finds that spending $15 on loyalty perks for existing subscribers retains far more revenue than spending $60 per advert to attract first-time buyers. Which core marketing principle does this demonstrate?","options":{"A":"Acquiring brand-new customers is always cheaper than keeping existing buyers","B":"Maintaining customer loyalty is more cost-effective and profitable over time than constantly replacing lost customers","C":"Existing subscribers never care about meal quality or delivery punctuality","D":"Marketing departments should stop advertising completely once they reach 1,000 subscribers"},"correctOption":"B","correctAnswer":"Maintaining customer loyalty is more cost-effective and profitable over time than constantly replacing lost customers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because retaining satisfied repeat buyers lowers promotional acquisition costs and generates steady long-term revenue.","distractor_reasons":{"A":"Incorrect because attracting new buyers usually costs significantly more than retaining current customers.","B":"Correct selection.","C":"Incorrect because customer retention depends directly on consistent product quality and reliable service.","D":"Incorrect because businesses still need ongoing promotion to remind customers and replace natural churn."}}},{"id":"P1_U3_MCQ_127","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_127","question":"In a national organic-juice market worth $150 million annually, GreenSip Ltd records annual sales revenue of $18 million. What is GreenSip Ltd's market share?","options":{"A":"8.3%","B":"18.0%","C":"12.0%","D":"27.0%"},"correctOption":"C","correctAnswer":"12.0%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Market Share (%) = ($18m / $150m) × 100 = 12.0%.","distractor_reasons":{"A":"Incorrect because 8.3% divides $150m by $18m instead of $18m by $150m.","B":"Incorrect because 18.0% confuses dollar sales ($18m) with percentage share.","C":"Correct selection.","D":"Incorrect because 27.0% multiplies 18 by 1.5 instead of dividing."}}},{"id":"P1_U3_MCQ_128","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_128","question":"During an economic downturn, total national sales in the printed-newspaper market fall by 12%, while DailyChronicle Ltd's sales revenue falls by only 4%. How has DailyChronicle Ltd's market share changed?","options":{"A":"Its market share fell by 8% because its sales dropped","B":"Its market share remained completely unchanged","C":"Its market share fell to zero due to industry contraction","D":"Its market share increased because its sales declined more slowly than the overall market"},"correctOption":"D","correctAnswer":"Its market share increased because its sales declined more slowly than the overall market","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because outperforming the industry average—even during a market contraction—gives the firm a larger proportion of total remaining market sales.","distractor_reasons":{"A":"Incorrect because its competitors lost sales at a faster rate than DailyChronicle Ltd.","B":"Incorrect because different percentage changes between firm sales and total market sales alter market share.","C":"Incorrect because the firm retained 96% of its previous sales.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_129","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_129","question":"A household cleaning-products firm observes consumers increasingly rejecting single-use plastic spray bottles in favour of concentrated refill tablets. Which driver of changing consumer spending patterns is influencing this market?","options":{"A":"Growing environmental awareness and ethical concern over plastic waste","B":"A sudden collapse in average household disposable incomes","C":"Government bans on cleaning domestic kitchens and bathrooms","D":"An increase in the average age of retirement"},"correctOption":"A","correctAnswer":"Growing environmental awareness and ethical concern over plastic waste","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because heightened ecological concern changes buyer preferences toward sustainable, low-waste alternatives.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because switching from plastic bottles to eco-refills reflects sustainability preferences rather than falling incomes.","C":"Incorrect because no such ban exists.","D":"Incorrect because retirement age changes do not explain anti-plastic packaging trends."}}},{"id":"P1_U3_MCQ_130","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_130","question":"In several developed countries, healthcare providers, hearing-aid makers, and luxury river-cruise operators experience rapid long-term demand growth. Which demographic shift best explains this trend?","options":{"A":"Rising birth rates increasing the proportion of infants in the population","B":"An ageing population with higher life expectancy and greater numbers of retired consumers","C":"Rapid migration of teenagers into primary schools","D":"Declining average life expectancy across all income groups"},"correctOption":"B","correctAnswer":"An ageing population with higher life expectancy and greater numbers of retired consumers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because an expanding over-65 demographic boosts spending on medical care, mobility aids, and leisure travel.","distractor_reasons":{"A":"Incorrect because higher birth rates raise demand for baby products rather than hearing aids and cruises.","B":"Correct selection.","C":"Incorrect because school-age demographics drive demand for education and youth goods.","D":"Incorrect because declining life expectancy would shrink the senior consumer segment."}}},{"id":"P1_U3_MCQ_131","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_131","question":"A domestic furniture maker that once dominated its local city now faces intense pressure from overseas flat-pack brands and online comparison sites. Why have many markets become significantly more competitive?","options":{"A":"Governments have banned businesses from using internet websites to sell goods","B":"Transport costs have risen so high that international trade has stopped","C":"Globalization, lower trade barriers, and e-commerce price transparency have exposed local firms to global rivals","D":"Consumers no longer compare product prices or quality before purchasing"},"correctOption":"C","correctAnswer":"Globalization, lower trade barriers, and e-commerce price transparency have exposed local firms to global rivals","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because international trade agreements, cheaper logistics, and digital platforms allow foreign and online competitors to enter local markets easily.","distractor_reasons":{"A":"Incorrect because e-commerce is actively used worldwide.","B":"Incorrect because modern shipping and digital platforms facilitate global trade.","C":"Correct selection.","D":"Incorrect because digital tools make price and review comparisons easier than ever."}}},{"id":"P1_U3_MCQ_132","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_132","question":"When rival streaming platforms enter its market with lower monthly fees, an established entertainment company invests heavily in exclusive original dramas and ultra-HD streaming quality. How is it responding to competition?","options":{"A":"By abandoning product development to focus solely on cost cutting","B":"By reducing content variety while doubling subscription prices","C":"By switching from mass marketing to a tiny local geographic niche","D":"By differentiating its product quality and exclusive features so subscribers stay loyal despite cheaper rivals"},"correctOption":"D","correctAnswer":"By differentiating its product quality and exclusive features so subscribers stay loyal despite cheaper rivals","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because exclusive content creates a strong Unique Selling Point (USP) that reduces price sensitivity against low-cost competitors.","distractor_reasons":{"A":"Incorrect because funding original dramas represents major product investment.","B":"Incorrect because the firm expanded exclusive content rather than cutting variety.","C":"Incorrect because global streaming platforms operate across broad mass audiences.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_133","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_133","question":"A small independent bakery specializes exclusively in certified gluten-free, nut-free birthday cakes for children with severe food allergies. Why does this 'niche marketing' approach suit a small business?","options":{"A":"It avoids head-on price battles with giant supermarket bakeries and meets an urgent, specific need that parents gladly pay a premium for","B":"It allows the bakery to produce millions of identical plain loaves using automated flow lines","C":"It guarantees that no other bakery will ever learn how to bake gluten-free cakes","D":"It eliminates the need to follow food hygiene and allergen labelling laws"},"correctOption":"A","correctAnswer":"It avoids head-on price battles with giant supermarket bakeries and meets an urgent, specific need that parents gladly pay a premium for","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because specialized niches shelter small firms from mass-market giants while supporting strong profit margins through tailored value.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because automated mass production describes mass marketing.","C":"Incorrect because niche markets carry no permanent legal protection against future entrants.","D":"Incorrect because allergen safety laws are especially strict for allergy-free foods."}}},{"id":"P1_U3_MCQ_134","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_134","question":"A boutique manufacturer of custom carbon-fibre racing bicycles produces only 300 frames per year. What cost disadvantage does this 'niche market' strategy typically create?","options":{"A":"Excessive spending on nationwide television commercials during prime-time broadcasts","B":"Higher average unit production costs due to small batch sizes and inability to gain mass purchasing economies of scale","C":"Over-reliance on selling cheap unbranded bicycles through discount supermarkets","D":"Inability to communicate directly with cycling enthusiasts"},"correctOption":"B","correctAnswer":"Higher average unit production costs due to small batch sizes and inability to gain mass purchasing economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because low output volumes prevent bulk raw-material discounts and spread fixed tooling costs over fewer units.","distractor_reasons":{"A":"Incorrect because niche firms use targeted cycling magazines and clubs rather than mass TV ads.","B":"Correct selection.","C":"Incorrect because niche firms sell specialized high-value items rather than supermarket generics.","D":"Incorrect because niche businesses usually maintain close, direct ties with their specialist buyers."}}},{"id":"P1_U3_MCQ_135","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_135","question":"A global battery maker sells standard AA alkaline batteries to households, offices, and schools worldwide. What is a major advantage of this 'mass marketing' strategy?","options":{"A":"Zero competition from any rival battery brands","B":"Complete customization of battery chemical formulas for every individual buyer","C":"A huge customer base that spreads risk and supports large-scale, low-unit-cost automated manufacturing","D":"Ability to charge luxury boutique prices ten times higher than rivals"},"correctOption":"C","correctAnswer":"A huge customer base that spreads risk and supports large-scale, low-unit-cost automated manufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because broad universal demand reduces dependence on any single tiny segment and maximizes economies of scale.","distractor_reasons":{"A":"Incorrect because mass markets typically feature intense competition.","B":"Incorrect because mass marketing relies on standardized products.","C":"Correct selection.","D":"Incorrect because standardized mass-market commodities face strong price competition."}}},{"id":"P1_U3_MCQ_136","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_136","question":"A shampoo brand sells a single 'one-size-fits-all' formula across the entire country, but loses sales to rivals offering specialized shampoos for curly, dyed, and sensitive scalps. Which weakness of 'mass marketing' does this reveal?","options":{"A":"Unit manufacturing costs are always higher than in niche markets","B":"Standardized products cannot be advertised on national television","C":"Mass-market retailers refuse to stock single-formula products","D":"A standardized product fails to satisfy consumers who want solutions tailored to their specific individual needs"},"correctOption":"D","correctAnswer":"A standardized product fails to satisfy consumers who want solutions tailored to their specific individual needs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because undifferentiated mass products leave gaps that segmented or niche competitors can exploit.","distractor_reasons":{"A":"Incorrect because mass production yields lower unit costs.","B":"Incorrect because mass-market brands use national TV extensively.","C":"Incorrect because supermarkets routinely stock mainstream single-formula staples.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_137","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_137","question":"An oat-milk startup originally sold only through small health-food shops expands into major national supermarket chains to capture mainstream demand. What trade-off will it likely face as it moves toward the mass market?","options":{"A":"Higher total sales volume and lower unit production costs, balanced against lower profit margins per carton and tougher competition from food giants","B":"Lower sales volume, balanced against zero competition from dairy or beverage corporations","C":"Higher unit manufacturing costs, balanced against exemption from food safety regulations","D":"Complete elimination of all marketing and promotional expenses"},"correctOption":"A","correctAnswer":"Higher total sales volume and lower unit production costs, balanced against lower profit margins per carton and tougher competition from food giants","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because entering mainstream supermarkets boosts scale and revenue while triggering supermarket price pressure and multinational competition.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because mainstream supermarket distribution increases sales volume and attracts fierce corporate rivals.","C":"Incorrect because higher output lowers unit costs and safety laws always apply.","D":"Incorrect because competing in mass retail requires heavier promotional spending."}}},{"id":"P1_U3_MCQ_138","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_138","question":"A soft-drinks company analyzes consumer data and discovers that fitness enthusiasts want zero-sugar electrolyte drinks while office workers want lightly caffeinated herbal teas. How does 'market segmentation' help the company grow?","options":{"A":"It forces both groups to drink the exact same sugary cola","B":"It uncovers distinct unserved customer needs, enabling targeted product launches that expand total market share","C":"It eliminates the need to conduct product testing or packaging design","D":"It reduces the number of retail outlets willing to stock the company's drinks"},"correctOption":"B","correctAnswer":"It uncovers distinct unserved customer needs, enabling targeted product launches that expand total market share","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because segmentation identifies profitable sub-groups whose specific preferences can be satisfied with dedicated product lines.","distractor_reasons":{"A":"Incorrect because forcing one uniform product describes undifferentiated mass marketing.","B":"Correct selection.","C":"Incorrect because each targeted drink requires tailored testing and packaging.","D":"Incorrect because offering distinct products for different buyer groups typically increases shelf space."}}},{"id":"P1_U3_MCQ_139","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_139","question":"A frozen-food producer sells single-portion microwave meals in city-centre convenience stores and 2-kilogram family value packs in suburban supermarkets. Which demographic variable is driving this strategy?","options":{"A":"Gender","B":"Religious affiliation","C":"Household and family size","D":"Political party membership"},"correctOption":"C","correctAnswer":"Household and family size","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because household composition (single-person households vs multi-person families) directly determines ideal package sizes.","distractor_reasons":{"A":"Incorrect because portion sizes are based on household size rather than male or female buyers.","B":"Incorrect because pack size does not reflect religious dietary rules.","C":"Correct selection.","D":"Incorrect because political affiliation is irrelevant to frozen meal pack sizes."}}},{"id":"P1_U3_MCQ_140","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_140","question":"A footwear manufacturer designs steel-toe waterproof boots for construction engineers and lightweight slip-resistant clogs for hospital nurses. Which demographic segmentation factor is being used?","options":{"A":"Age group","B":"Climatic zone","C":"Marital status","D":"Occupation / job role"},"correctOption":"D","correctAnswer":"Occupation / job role","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because different professions require specific functional product attributes tailored to daily working conditions.","distractor_reasons":{"A":"Incorrect because engineers and nurses span all working ages.","B":"Incorrect because both products are differentiated by workplace hazards rather than weather climate.","C":"Incorrect because marital status has no bearing on occupational footwear.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_141","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_141","question":"An automotive tyre manufacturer promotes studded winter snow tyres in northern Scandinavia while marketing high-drainage monsoon tyres in Southeast Asia. Which segmentation basis is applied?","options":{"A":"Geographic and climatic segmentation","B":"Socio-economic income segmentation","C":"Gender segmentation","D":"Age segmentation"},"correctOption":"A","correctAnswer":"Geographic and climatic segmentation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because regional climate and weather conditions dictate distinct functional product requirements.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the distinction is based on snow vs tropical rain rather than buyer wealth.","C":"Incorrect because tyre tread design is unrelated to driver gender.","D":"Incorrect because all drivers in each climate zone need suitable seasonal tyres."}}},{"id":"P1_U3_MCQ_142","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_142","question":"A vehicle manufacturer markets compact electric city cars to apartment residents in congested metropolises and heavy-duty 4x4 pickup trucks to agricultural communities. Which segmentation dimension is this?","options":{"A":"Age segmentation","B":"Geographic (urban vs rural) segmentation","C":"Gender segmentation","D":"Undifferentiated mass marketing"},"correctOption":"B","correctAnswer":"Geographic (urban vs rural) segmentation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because population density, road infrastructure, and urban vs rural locations create markedly different transport needs.","distractor_reasons":{"A":"Incorrect because drivers of any age live in cities or rural areas.","B":"Correct selection.","C":"Incorrect because vehicle choice here reflects terrain and parking conditions rather than gender.","D":"Incorrect because two distinct vehicle types are targeted at different geographic environments."}}},{"id":"P1_U3_MCQ_143","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_143","question":"A commercial bank offers free basic digital current accounts to low-wage workers alongside dedicated wealth-management advisors for clients holding over $1 million in savings. How is the bank segmenting its market?","options":{"A":"By geographic postcode","B":"By gender and age","C":"By income and socio-economic wealth bracket","D":"By climate and seasonal weather"},"correctOption":"C","correctAnswer":"By income and socio-economic wealth bracket","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because matching financial services to clients' income and asset levels aligns service complexity and fees with ability to pay.","distractor_reasons":{"A":"Incorrect because account tiers depend on financial assets rather than street address.","B":"Incorrect because wealth brackets cut across all genders and adult age groups.","C":"Correct selection.","D":"Incorrect because banking tiers are unrelated to weather conditions."}}},{"id":"P1_U3_MCQ_144","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_144","question":"A travel company sells silent meditation retreats to stressed corporate executives and extreme bungee-jumping tours to thrill-seeking backpackers. Which segmentation criterion is it using?","options":{"A":"Gender","B":"Marital status","C":"Home postal code","D":"Lifestyle and psychographic attitudes"},"correctOption":"D","correctAnswer":"Lifestyle and psychographic attitudes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because personal values, leisure interests, and attitudes toward relaxation vs adventure define lifestyle segmentation.","distractor_reasons":{"A":"Incorrect because both retreats and adventure tours attract male and female travellers.","B":"Incorrect because marital status does not determine preference for meditation vs bungee jumping.","C":"Incorrect because buyer hobbies and values drive these choices rather than residential address.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_145","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_145","question":"A tour operator designs escorted cultural wildlife safaris priced at $8,000 specifically for active, high-income retirees aged 60–75. Which approach is the operator using?","options":{"A":"Multi-variable segmentation combining age, income, and lifestyle","B":"Undifferentiated mass marketing","C":"Product-oriented cost-plus discounting","D":"Geographic-only segmentation"},"correctOption":"A","correctAnswer":"Multi-variable segmentation combining age, income, and lifestyle","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because real-world businesses frequently combine demographic (age), socio-economic (income), and psychographic (active cultural travel) variables to pinpoint a profitable niche.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the package is highly tailored rather than aimed at the entire public.","C":"Incorrect because the safari is designed around specific customer traits rather than unresearched production.","D":"Incorrect because the target group is defined by age, wealth, and interests rather than where they live."}}},{"id":"P1_U3_MCQ_146","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_146","question":"A cloud-accounting software firm offers a $15/month self-service plan for sole traders and a $1,200/month multi-currency enterprise package for multinational corporations. How is this B2B market segmented?","options":{"A":"By customer gender and leisure hobbies","B":"By client business size and operational complexity","C":"By individual employee shoe size","D":"By residential neighbourhood"},"correctOption":"B","correctAnswer":"By client business size and operational complexity","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because business-to-business (B2B) segmentation groups organizational buyers by company scale, industry sector, and transaction volume.","distractor_reasons":{"A":"Incorrect because personal hobbies apply to consumer (B2C) lifestyle segmentation.","B":"Correct selection.","C":"Incorrect because personal physical traits are irrelevant to accounting software.","D":"Incorrect because business scale determines software tier rather than residential address."}}},{"id":"P1_U3_MCQ_147","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_147","question":"Why do mobile-phone network providers offer discounted phone upgrades and priority customer support to subscribers who renew two-year contracts?","options":{"A":"Because regulators forbid mobile networks from signing up new customers","B":"Because loyal subscribers generate zero revenue during their contract term","C":"Because retaining loyal customers secures predictable recurring revenue and prevents rivals from stealing market share","D":"Because offering upgrades eliminates all network maintenance expenses"},"correctOption":"C","correctAnswer":"Because retaining loyal customers secures predictable recurring revenue and prevents rivals from stealing market share","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because customer loyalty stabilizes cash flows and reduces costly customer churn in saturated telecom markets.","distractor_reasons":{"A":"Incorrect because mobile operators actively recruit new subscribers alongside retention deals.","B":"Incorrect because subscribers pay regular monthly fees throughout their contract.","C":"Correct selection.","D":"Incorrect because network infrastructure still requires ongoing investment."}}},{"id":"P1_U3_MCQ_148","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_148","question":"A specialty coffee roaster sells 25,000 bags of coffee beans at $20 per bag ($500,000 annual revenue) and holds a 20% share of its regional market. What is the total value of the regional market?","options":{"A":"$100,000","B":"$1,000,000","C":"$2,000,000","D":"$2,500,000"},"correctOption":"D","correctAnswer":"$2,500,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because if $500,000 represents 20% (0.20) of the market, Total Market Size = $500,000 / 0.20 = $2,500,000.","distractor_reasons":{"A":"Incorrect because $100,000 multiplies $500,000 by 0.20 instead of dividing.","B":"Incorrect because $1,000,000 assumes a 50% market share rather than 20%.","C":"Incorrect because $2,000,000 assumes a 25% market share rather than 20%.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_149","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_149","question":"A fast-fashion retailer notices viral social media trends shifting teen clothing styles every few weeks. How must its marketing and operations respond to survive?","options":{"A":"Use continuous digital trend monitoring and flexible short-run production to launch matching styles rapidly before trends fade","B":"Order a five-year supply of a single jacket style to maximize bulk discounts","C":"Stop conducting market research because teen fashions remain identical every decade","D":"Sell exclusively through printed mail-order catalogues published once a year"},"correctOption":"A","correctAnswer":"Use continuous digital trend monitoring and flexible short-run production to launch matching styles rapidly before trends fade","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid changes in consumer tastes and fashions shorten product life cycles, demanding agile research and fast supply chains.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because holding five years of inventory in fast fashion guarantees massive unsold stock when styles change.","C":"Incorrect because fast-changing markets require more frequent research, not less.","D":"Incorrect because annual print catalogues are far too slow for fast-moving trends."}}},{"id":"P1_U3_MCQ_150","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_150","question":"A newly founded startup with $25,000 in capital wants to enter the crowded athletic-socks market. Why is targeting a specific niche—such as blister-proof compression socks for marathon runners—better than undifferentiated mass marketing?","options":{"A":"Mass marketing requires zero promotional expenditure or retail distribution","B":"Limited capital cannot fund nationwide mass-market battles against giants, whereas focusing on marathon runners builds strong brand loyalty and higher margins","C":"Marathon runners are legally prohibited from buying standard supermarket socks","D":"Niche socks require no product design or quality testing"},"correctOption":"B","correctAnswer":"Limited capital cannot fund nationwide mass-market battles against giants, whereas focusing on marathon runners builds strong brand loyalty and higher margins","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because concentrating limited resources on a high-involvement niche avoids direct price wars with huge multinationals.","distractor_reasons":{"A":"Incorrect because mass marketing demands huge advertising and distribution budgets.","B":"Correct selection.","C":"Incorrect because marathon runners choose specialist socks voluntarily for performance, not by law.","D":"Incorrect because technical niche products require careful design and testing."}}},{"id":"P1_U3_MCQ_151","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_151","question":"A traditional wristwatch manufacturer spends millions perfecting mechanical gears without researching buyer trends, and is shocked when consumers switch to fitness-tracking smartwatches. What caused this failure?","options":{"A":"Excessive reliance on consumer focus groups and test marketing","B":"Over-segmenting the market into too many digital watch categories","C":"A product-oriented mindset that prioritized engineering tradition over evolving customer needs","D":"Setting launch prices too low through penetration pricing"},"correctOption":"C","correctAnswer":"A product-oriented mindset that prioritized engineering tradition over evolving customer needs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because product-oriented firms assume technical craftsmanship guarantees sales, leaving them vulnerable to shifts in customer preferences.","distractor_reasons":{"A":"Incorrect because the firm conducted no consumer research before investing.","B":"Incorrect because the firm ignored the emerging smartwatch segment altogether.","C":"Correct selection.","D":"Incorrect because the core issue was failing to adapt product functionality to customer demand."}}},{"id":"P1_U3_MCQ_152","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_152","question":"How does adopting a 'market-oriented' culture help a consumer-electronics brand respond faster when competitors launch rival gadgets?","options":{"A":"It eliminates the need for engineers to test product safety","B":"It guarantees that competitors will never copy the brand's designs","C":"It allows the firm to ignore customer complaints and warranty returns","D":"Ongoing customer feedback alerts the firm early to shifting user priorities so it can adapt features quickly"},"correctOption":"D","correctAnswer":"Ongoing customer feedback alerts the firm early to shifting user priorities so it can adapt features quickly","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because continuous market intelligence keeps product development aligned with real buyer expectations.","distractor_reasons":{"A":"Incorrect because safety testing remains essential in electronics.","B":"Incorrect because market orientation improves responsiveness rather than preventing imitation.","C":"Incorrect because market-oriented firms analyze complaints closely to improve products.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_153","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_153","question":"Before investing $15 million in new factory tooling for a folding electric scooter, a mobility firm conducts surveys, focus groups, and price-willingness tests. What is the main purpose of this market research?","options":{"A":"To reduce the financial risk of launching a product that fails to attract enough buyers at a profitable price","B":"To calculate exact corporate income tax rates owed to the government","C":"To replace the need for quality inspection on the factory assembly line","D":"To eliminate all fixed overhead costs during manufacturing"},"correctOption":"A","correctAnswer":"To reduce the financial risk of launching a product that fails to attract enough buyers at a profitable price","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because market research provides objective evidence on demand, design, and pricing before committing irreversible capital.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax calculations belong to Finance.","C":"Incorrect because operational quality control remains necessary during production.","D":"Incorrect because market research informs commercial decisions rather than eliminating factory overheads."}}},{"id":"P1_U3_MCQ_154","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_154","question":"A café owner designs a short questionnaire asking local office workers which sandwich fillings and lunch prices would make them visit daily. What is the key advantage of this 'primary research'?","options":{"A":"It is completely free of time or effort compared with reading online news","B":"The data is up-to-date, confidential to the café, and directly answers the owner's specific menu and pricing questions","C":"It automatically interviews every resident in the entire country","D":"It requires zero planning of question wording"},"correctOption":"B","correctAnswer":"The data is up-to-date, confidential to the café, and directly answers the owner's specific menu and pricing questions","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because primary research is gathered first-hand for the exact decision at hand and is not shared with rivals.","distractor_reasons":{"A":"Incorrect because primary research requires time and effort to design, collect, and analyze.","B":"Correct selection.","C":"Incorrect because surveys use a sample rather than a full national census.","D":"Incorrect because careful question design is vital to avoid bias."}}},{"id":"P1_U3_MCQ_155","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_155","question":"Why might a luxury carmaker use 'face-to-face personal interviews' with existing owners rather than an automated multiple-choice web form when designing its next flagship sedan?","options":{"A":"Face-to-face interviews are much cheaper and faster per respondent than online forms","B":"Face-to-face interviews completely eliminate any possibility of interviewer bias","C":"Trained interviewers can ask follow-up questions, clarify complex reactions, and capture nuanced qualitative insights","D":"Luxury car owners are legally forbidden from completing online surveys"},"correctOption":"C","correctAnswer":"Trained interviewers can ask follow-up questions, clarify complex reactions, and capture nuanced qualitative insights","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because personal interviews allow probing into detailed opinions and clarifying misunderstandings, though at higher cost per interview.","distractor_reasons":{"A":"Incorrect because personal interviews are far costlier and slower than online forms.","B":"Incorrect because interviewer tone or body language can introduce bias if not carefully trained.","C":"Correct selection.","D":"Incorrect because online surveys are completely lawful."}}},{"id":"P1_U3_MCQ_156","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_156","question":"A cereal manufacturer brings together eight parents of school-age children to taste three prototype oat bars and discuss packaging slogans for 90 minutes. What key advantage does this 'focus group' provide?","options":{"A":"Statistically representative numerical forecasts across millions of households","B":"Zero moderation cost because participants manage the session themselves","C":"Complete elimination of dominant speakers influencing quieter members","D":"Rich qualitative feedback and spontaneous group discussion revealing emotional reactions to taste and branding"},"correctOption":"D","correctAnswer":"Rich qualitative feedback and spontaneous group discussion revealing emotional reactions to taste and branding","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because group interaction sparks deeper explanation of why consumers prefer certain flavours or messages.","distractor_reasons":{"A":"Incorrect because small 8-person groups are qualitative and not statistically generalizable.","B":"Incorrect because skilled moderators are required to guide discussion objectively.","C":"Incorrect because dominant speakers are actually a well-known risk in focus groups.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_157","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_157","question":"A department store uses overhead heat-mapping cameras to track which store aisles shoppers walk down most frequently and where congestion slows foot traffic. Which primary research method is being used?","options":{"A":"Observation","B":"Postal questionnaire","C":"Telephone interview","D":"External government census"},"correctOption":"A","correctAnswer":"Observation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because observing natural shopper movement captures genuine behaviour without relying on self-reported memory.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because postal questionnaires collect written self-reports.","C":"Incorrect because telephone interviews ask verbal questions.","D":"Incorrect because store camera analytics generate internal primary data."}}},{"id":"P1_U3_MCQ_158","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_158","question":"A market research agency recruits 2,000 households to scan every grocery item they buy each week over a full year using a home barcode reader. Which research method is this?","options":{"A":"One-off street quota survey","B":"Consumer panel (longitudinal primary research)","C":"Internal accounting audit","D":"Newspaper article desk review"},"correctOption":"B","correctAnswer":"Consumer panel (longitudinal primary research)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a consumer panel tracks the same sample of households repeatedly over time to measure brand switching and repeat buying.","distractor_reasons":{"A":"Incorrect because street surveys capture a single moment rather than continuous weekly tracking.","B":"Correct selection.","C":"Incorrect because an accounting audit verifies financial records.","D":"Incorrect because reading newspapers is secondary desk research."}}},{"id":"P1_U3_MCQ_159","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_159","question":"Before designing a new vacuum cleaner model, an appliance manufacturer reviews five years of its own customer-helpline call logs and warranty repair records. Why is this a smart first step?","options":{"A":"It is expensive primary research that interviews rival companies' customers","B":"It automatically guarantees 100% sales growth in foreign markets","C":"These internal secondary records already exist at minimal cost and pinpoint real product weaknesses experienced by buyers","D":"It replaces the need to test prototypes with new target consumers"},"correctOption":"C","correctAnswer":"These internal secondary records already exist at minimal cost and pinpoint real product weaknesses experienced by buyers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal secondary data is immediately accessible, cheap, and highlights recurring functional faults to fix.","distractor_reasons":{"A":"Incorrect because internal company logs are secondary data rather than external primary interviews.","B":"Incorrect because fixing past defects aids quality but does not guarantee foreign expansion.","C":"Correct selection.","D":"Incorrect because new prototypes still require primary user testing."}}},{"id":"P1_U3_MCQ_160","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_160","question":"A private nursery chain uses free national census tables showing birth rates and average household incomes by city district to select where to open three new nurseries. Which type of research is this?","options":{"A":"Primary focus-group research","B":"Primary test marketing","C":"Internal company secondary data","D":"External secondary (desk) research"},"correctOption":"D","correctAnswer":"External secondary (desk) research","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because government census statistics were published by an external body for general public use and provide reliable demographic insights.","distractor_reasons":{"A":"Incorrect because no parent focus group discussions were conducted.","B":"Incorrect because no trial nursery was opened yet.","C":"Incorrect because census data comes from the government rather than the nursery's own records.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_161","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_161","question":"A boutique hotel manager checks competitors' public websites, online travel-agency reviews, and national tourism board reports before setting summer room rates. Which research approach is being used?","options":{"A":"External secondary research","B":"Random primary sampling","C":"Quota street interviewing","D":"Controlled laboratory experimentation"},"correctOption":"A","correctAnswer":"External secondary research","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because competitor price listings, existing reviews, and tourism board publications are pre-existing external sources.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no new survey sample was drawn.","C":"Incorrect because no street interviews took place.","D":"Incorrect because reviewing published websites is desk research."}}},{"id":"P1_U3_MCQ_162","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_162","question":"A small startup developing a pet-grooming app has a limited research budget of $500. Why should it start with secondary desk research before running primary surveys?","options":{"A":"Secondary research always reveals exact customer reactions to the startup's unreleased app prototype","B":"Secondary research uses free or low-cost existing pet-ownership statistics to estimate market size quickly, preserving the $500 budget for targeted user testing","C":"Primary surveys are illegal for startups with fewer than ten employees","D":"Secondary research is never available on the internet"},"correctOption":"B","correctAnswer":"Secondary research uses free or low-cost existing pet-ownership statistics to estimate market size quickly, preserving the $500 budget for targeted user testing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because starting with inexpensive secondary data avoids wasting scarce funds gathering basic industry facts that already exist.","distractor_reasons":{"A":"Incorrect because existing publications cannot test an unreleased custom prototype.","B":"Correct selection.","C":"Incorrect because startups can lawfully run primary surveys.","D":"Incorrect because vast amounts of secondary data are accessible online."}}},{"id":"P1_U3_MCQ_163","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_163","question":"What is a major drawback of commissioning a large-scale primary field survey before launching a trendy tech accessory?","options":{"A":"Primary data is always outdated by at least five years","B":"Competitors automatically receive free copies of the survey results","C":"High fieldwork costs and lengthy data-collection times may delay launch, allowing agile rivals to reach the market first","D":"Primary surveys cannot include questions about desired product features"},"correctOption":"C","correctAnswer":"High fieldwork costs and lengthy data-collection times may delay launch, allowing agile rivals to reach the market first","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because designing, conducting, and analyzing primary research is costly and time-consuming in fast-moving markets.","distractor_reasons":{"A":"Incorrect because primary research collects fresh, current data.","B":"Incorrect because primary data belongs exclusively to the commissioning firm.","C":"Correct selection.","D":"Incorrect because testing desired features is a primary purpose of product surveys."}}},{"id":"P1_U3_MCQ_164","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_164","question":"A university dining hall wants to survey student meal preferences fairly. It enters all 8,000 enrolled student ID numbers into a computer program that randomly selects 250 IDs to receive an email questionnaire. Which sampling method is this?","options":{"A":"Quota sampling","B":"Convenience street sampling","C":"Focus-group purposive selection","D":"Random sampling"},"correctOption":"D","correctAnswer":"Random sampling","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because every student in the complete population list had an equal, unbiased mathematical chance of selection.","distractor_reasons":{"A":"Incorrect because quota sampling selects set numbers matching demographic proportions rather than pure random draw.","B":"Incorrect because convenience sampling picks whoever is easiest to reach nearby.","C":"Incorrect because focus groups hand-pick small discussion panels.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_165","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_165","question":"Why is 'random sampling' often impractical for a soft-drinks brand wanting to survey casual supermarket shoppers nationwide?","options":{"A":"The brand lacks a complete, up-to-date list (sampling frame) of every individual shopper in the country, making true random selection costly and difficult","B":"Random sampling forces interviewers to interview only elderly retired citizens","C":"Random sampling is mathematically biased toward wealthy respondents","D":"Random sampling can only be used with secondary census tables"},"correctOption":"A","correctAnswer":"The brand lacks a complete, up-to-date list (sampling frame) of every individual shopper in the country, making true random selection costly and difficult","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because true random sampling requires an accurate population list, and selected individuals may be scattered geographically and hard to contact.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because random sampling gives all population members equal probability.","C":"Incorrect because unbiased random selection avoids systematic wealth skew.","D":"Incorrect because sampling applies to primary research."}}},{"id":"P1_U3_MCQ_166","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_166","question":"A commuter rail operator knows its passengers are 30% aged 18–30, 50% aged 31–55, and 20% aged 56+. If it uses 'quota sampling' to interview 200 passengers, how many aged 18–30 should be interviewed?","options":{"A":"30 passengers","B":"60 passengers","C":"100 passengers","D":"140 passengers"},"correctOption":"B","correctAnswer":"60 passengers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because 30% of a 200-person sample = 0.30 × 200 = 60 passengers aged 18–30.","distractor_reasons":{"A":"Incorrect because 30 would apply to a 100-person sample rather than 200.","B":"Correct selection.","C":"Incorrect because 100 represents the 50% bracket (31–55).","D":"Incorrect because 140 represents the combined 31–55 and 56+ brackets."}}},{"id":"P1_U3_MCQ_167","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_167","question":"A shopping mall manager surveys customer satisfaction by interviewing only the first 40 shoppers who walk through the main entrance at 9:00 AM on a Monday morning. Why is this sampling approach flawed?","options":{"A":"A sample of 40 is larger than the entire mall visitor population","B":"Monday morning shoppers always give dishonest answers to questionnaires","C":"Convenience sampling at one off-peak weekday hour excludes weekend families and evening workers, creating severe sample bias","D":"Interviewing shoppers in person is a form of secondary desk research"},"correctOption":"C","correctAnswer":"Convenience sampling at one off-peak weekday hour excludes weekend families and evening workers, creating severe sample bias","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because early Monday morning visitors do not represent the broader mix of weekend and evening mall shoppers.","distractor_reasons":{"A":"Incorrect because 40 is a very small fraction of total mall visitors.","B":"Incorrect because the flaw is unrepresentative timing/selection rather than deliberate lying.","C":"Correct selection.","D":"Incorrect because live shopper interviews are primary research."}}},{"id":"P1_U3_MCQ_168","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_168","question":"An umbrella manufacturer conducts street interviews during a rare three-week summer heatwave and concludes that umbrella demand has permanently collapsed. Which factor has distorted its market research accuracy?","options":{"A":"Excessive sample size reducing statistical reliability","B":"Over-reliance on government census records","C":"Using random number tables to select respondents","D":"Seasonal and temporary weather timing biasing respondents' immediate purchasing perceptions"},"correctOption":"D","correctAnswer":"Seasonal and temporary weather timing biasing respondents' immediate purchasing perceptions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because temporary seasonal conditions strongly influence short-term consumer opinions and distort long-term demand forecasts.","distractor_reasons":{"A":"Incorrect because larger sample sizes improve accuracy.","B":"Incorrect because the firm used street interviews rather than census data.","C":"Incorrect because random selection reduces bias rather than causing weather distortion.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_169","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_169","question":"In a face-to-face street survey, 85% of respondents claim they gladly pay extra for biodegradable packaging, yet actual supermarket sales show 80% buy the cheapest plastic-wrapped brand. What explains this discrepancy?","options":{"A":"Social desirability bias: respondents give answers that make them appear ethical to the interviewer rather than reflecting actual shopping habits","B":"Supermarkets illegally hide biodegradable products in locked back rooms","C":"Secondary data always contradicts primary observation","D":"Shoppers do not understand how to read price tags in supermarkets"},"correctOption":"A","correctAnswer":"Social desirability bias: respondents give answers that make them appear ethical to the interviewer rather than reflecting actual shopping habits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because people often overstate socially admirable intentions in interviews compared with their real price-driven behaviour at the checkout.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supermarkets display eco-lines prominently when stocked.","C":"Incorrect because valid secondary and primary data often complement each other.","D":"Incorrect because shoppers actively respond to lower shelf prices."}}},{"id":"P1_U3_MCQ_170","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_170","question":"A cinema survey asks: 'Do you go to the movies frequently? Yes / No.' Why will the responses provide unreliable data for marketing decisions?","options":{"A":"The question uses too many complex technical film-industry acronyms","B":"The word 'frequently' is vague and subjective—one person may mean once a week while another means twice a year","C":"Yes/No questions cannot be counted into percentages","D":"Cinema customers are legally barred from answering frequency questions"},"correctOption":"B","correctAnswer":"The word 'frequently' is vague and subjective—one person may mean once a week while another means twice a year","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because imprecise terms lead different respondents to interpret the question differently; specific ranges (e.g., 'once a month') are needed.","distractor_reasons":{"A":"Incorrect because 'frequently' is an everyday vague word rather than technical jargon.","B":"Correct selection.","C":"Incorrect because closed Yes/No questions are easily tabulated, though ambiguous wording ruins validity.","D":"Incorrect because no such legal restriction exists."}}},{"id":"P1_U3_MCQ_171","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_171","question":"An airline emails passengers a post-flight survey asking them to rate seat comfort from 1 to 5 and also provides a comment box asking 'How could we improve your flight?' Why is this combination effective?","options":{"A":"It eliminates the need to analyze survey results before changing seat designs","B":"It guarantees that every passenger will give a 5-star rating","C":"The numerical rating quantifies overall satisfaction trends, while the open comment box reveals specific actionable causes behind low scores","D":"It converts primary customer feedback into external government census data"},"correctOption":"C","correctAnswer":"The numerical rating quantifies overall satisfaction trends, while the open comment box reveals specific actionable causes behind low scores","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because combining quantitative scores with qualitative explanations tells managers both how well they are performing and what to fix.","distractor_reasons":{"A":"Incorrect because managers must still analyze both numbers and comments carefully.","B":"Incorrect because honest feedback includes critical scores when service falls short.","C":"Correct selection.","D":"Incorrect because post-flight surveys remain internal primary research."}}},{"id":"P1_U3_MCQ_172","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_172","question":"A marketing analyst wants to show the Board of Directors how monthly online sales revenue grew steadily over the past 24 months. Which visual chart is clearest for displaying continuous change over time?","options":{"A":"A single pie chart showing only total annual sales","B":"A random scatter plot of employee birthdays","C":"A 10-page unformatted list of raw daily transaction receipts","D":"A line graph plotting monthly sales revenue along the timeline"},"correctOption":"D","correctAnswer":"A line graph plotting monthly sales revenue along the timeline","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because line graphs clearly illustrate trends, seasonal peaks, and growth rates across consecutive time periods.","distractor_reasons":{"A":"Incorrect because pie charts show parts of a whole at one point rather than a 24-month trend.","B":"Incorrect because employee birthdays are unrelated to sales trends.","C":"Incorrect because raw receipt lists obscure overall patterns.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_173","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_173","question":"A brand manager presents a bar chart where Brand A scored 81% satisfaction and Brand B scored 80%, but starts the vertical axis at 79.5% so Brand A's bar looks four times taller. What risk does this create?","options":{"A":"Misleading visual presentation exaggerates a tiny 1% difference, risking flawed strategic decisions","B":"Starting the axis at 79.5% makes the survey sample size automatically larger","C":"Bar charts are illegal to use in internal company board meetings","D":"Truncated axes convert qualitative opinions into secondary data"},"correctOption":"A","correctAnswer":"Misleading visual presentation exaggerates a tiny 1% difference, risking flawed strategic decisions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because manipulating chart scales distorts visual proportions and can mislead executives into overreacting to negligible differences.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because chart formatting does not alter underlying sample size.","C":"Incorrect because bar charts are standard business tools when scaled honestly.","D":"Incorrect because axis scale does not change data origin."}}},{"id":"P1_U3_MCQ_174","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_174","question":"Before setting the retail price of a new wireless gaming mouse, a hardware firm tests whether target gamers would buy it at $49, $69, or $89. How does this research support the marketing mix?","options":{"A":"It determines the exact hourly wage rate to pay factory cleaners","B":"It estimates consumer price sensitivity and expected demand at different price points to maximize revenue and profit","C":"It eliminates the need to design protective retail packaging","D":"It legally prevents retail stores from discounting the mouse"},"correctOption":"B","correctAnswer":"It estimates consumer price sensitivity and expected demand at different price points to maximize revenue and profit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because researching willingness to pay aligns pricing strategy with perceived customer value and elasticity.","distractor_reasons":{"A":"Incorrect because employee wages are governed by HR and labour markets.","B":"Correct selection.","C":"Incorrect because protective packaging remains essential.","D":"Incorrect because price research guides recommended retail pricing rather than banning retailer promotions."}}},{"id":"P1_U3_MCQ_175","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_175","question":"Even after conducting thorough primary and secondary market research, a smartphone startup experiences weaker-than-forecast sales because a rival unexpectedly slashes prices by 40% on launch week. What limitation of market research does this show?","options":{"A":"Market research is only useful for sole traders selling agricultural produce","B":"Surveys always fail when sample sizes exceed 500 respondents","C":"Market research reduces uncertainty, but cannot predict sudden external shocks or aggressive competitor retaliation","D":"Businesses should never conduct market research before launching technology products"},"correctOption":"C","correctAnswer":"Market research reduces uncertainty, but cannot predict sudden external shocks or aggressive competitor retaliation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market research captures conditions at the time of study, whereas dynamic markets remain exposed to unexpected rival moves and economic shifts.","distractor_reasons":{"A":"Incorrect because market research benefits businesses of all sizes and sectors.","B":"Incorrect because larger samples increase statistical accuracy.","C":"Correct selection.","D":"Incorrect because skipping research would leave the startup even more vulnerable."}}},{"id":"P1_U3_MCQ_176","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_176","question":"A kitchen-appliance maker designs a sleek, award-winning toaster that burns bread unevenly and breaks after three months, leading to poor online reviews and falling repeat sales. Which aspect of 'Product' was neglected?","options":{"A":"Attractive exterior styling and colour variety","B":"Using a high psychological launch price","C":"Distributing through national department stores","D":"Core functional performance, reliability, and build quality"},"correctOption":"D","correctAnswer":"Core functional performance, reliability, and build quality","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because appealing aesthetics cannot compensate for poor core functionality and durability; successful products must perform reliably.","distractor_reasons":{"A":"Incorrect because the scenario notes the toaster already had sleek, award-winning styling.","B":"Incorrect because pricing strategy does not fix mechanical defects.","C":"Incorrect because distribution channels cannot rescue an unreliable product.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_177","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_177","question":"During new product development, a beverage company's brainstorming team proposes 40 new drink concepts, then evaluates production feasibility, ingredient costs, and target-market fit to eliminate 35 weak ideas early. Which stage is this?","options":{"A":"Idea screening","B":"Full commercial launch","C":"Maturity extension","D":"Decline harvesting"},"correctOption":"A","correctAnswer":"Idea screening","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because screening filters out unviable or unprofitable concepts before spending heavy funds on prototypes and test marketing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because full launch occurs at the end of development for the winning product.","C":"Incorrect because extension strategies apply to existing mature products.","D":"Incorrect because decline harvesting manages aging products at the end of their life cycle."}}},{"id":"P1_U3_MCQ_178","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_178","question":"Why does an athletic clothing company legally register its distinctive swoosh-style logo and brand name as a 'trademark'?","options":{"A":"To eliminate all fabric and sewing labour costs in its factories","B":"To prevent competitors from copying its brand identity and confusing customers with counterfeit lookalikes","C":"To exempt its clothing from displaying washing-instruction labels","D":"To force supermarkets to stock its hoodies free of charge"},"correctOption":"B","correctAnswer":"To prevent competitors from copying its brand identity and confusing customers with counterfeit lookalikes","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because trademark protection safeguards brand equity, ensuring consumers can identify genuine quality reliably.","distractor_reasons":{"A":"Incorrect because trademarks protect intellectual property rather than lowering production costs.","B":"Correct selection.","C":"Incorrect because statutory garment care labelling laws still apply.","D":"Incorrect because retail listing terms are negotiated commercially."}}},{"id":"P1_U3_MCQ_179","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_179","question":"Many shoppers recognize a budget airline's logo immediately, yet still switch to whichever airline is $5 cheaper on booking websites. By contrast, Apple or Nike buyers repeatedly choose those brands even when cheaper alternatives exist. What does this contrast illustrate?","options":{"A":"The difference between mass distribution and direct wholesale exporting","B":"The difference between primary quota sampling and secondary desk research","C":"The difference between simple brand awareness and strong brand loyalty","D":"The difference between product orientation and cost-plus accounting"},"correctOption":"C","correctAnswer":"The difference between simple brand awareness and strong brand loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because brand awareness merely means consumers recognize a name, whereas brand loyalty drives repeat purchase and lower price sensitivity.","distractor_reasons":{"A":"Incorrect because the scenario compares customer attachment rather than distribution channels.","B":"Incorrect because market research sampling is not being compared.","C":"Correct selection.","D":"Incorrect because product orientation and accounting methods are unrelated to brand attachment."}}},{"id":"P1_U3_MCQ_180","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_180","question":"Major supermarket chains sell their own 'store-brand (own-label)' breakfast cereals alongside famous manufacturer brands at 25% lower retail prices. Why are own-label products profitable for supermarkets?","options":{"A":"Supermarkets pay zero manufacturing or ingredient costs for own-label cereals","B":"Manufacturer brands are legally banned from advertising on television","C":"Own-label cereals never require nutritional or allergy packaging labels","D":"Supermarkets avoid heavy national brand-advertising costs and control supplier margins directly while building store loyalty"},"correctOption":"D","correctAnswer":"Supermarkets avoid heavy national brand-advertising costs and control supplier margins directly while building store loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because own-label ranges leverage the supermarket's existing store footfall without massive brand ad budgets, yielding attractive retail margins.","distractor_reasons":{"A":"Incorrect because supermarkets still pay contract manufacturers to produce own-label goods.","B":"Incorrect because manufacturer brands advertise heavily.","C":"Incorrect because all packaged foods must carry statutory labels.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_181","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_181","question":"A children's toy box displays a clear 'Not suitable for children under 36 months—small parts choking hazard' symbol, assembly steps, and a retail barcode. Which role of 'packaging' is being fulfilled?","options":{"A":"Providing essential consumer safety information, usage instructions, and retail stock-tracking data","B":"Using psychological prestige pricing to target wealthy luxury collectors","C":"Replacing the need for wholesale distributors or retail toy stores","D":"Extending the Product Life Cycle during the decline stage"},"correctOption":"A","correctAnswer":"Providing essential consumer safety information, usage instructions, and retail stock-tracking data","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because beyond physical protection and shelf promotion, packaging communicates mandatory safety warnings, instructions, and barcodes.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because safety warnings and barcodes are functional/legal information rather than prestige pricing.","C":"Incorrect because barcodes actually facilitate retail store checkout and inventory tracking.","D":"Incorrect because safety warnings are required from launch rather than being an extension strategy."}}},{"id":"P1_U3_MCQ_182","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_182","question":"An e-commerce homeware brand replaces oversized, air-filled decorative cardboard boxes with snug, stackable moulded-pulp packaging. What dual benefit does this packaging redesign achieve?","options":{"A":"It eliminates all product manufacturing costs and removes the need for online marketing","B":"It reduces breakage damage during courier transit while cutting shipping volume and warehousing costs","C":"It prevents customers from identifying the brand logo upon delivery","D":"It allows the brand to ignore consumer refund laws"},"correctOption":"B","correctAnswer":"It reduces breakage damage during courier transit while cutting shipping volume and warehousing costs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because smart packaging protects fragile items efficiently while maximizing container/van space and lowering freight costs.","distractor_reasons":{"A":"Incorrect because core manufacturing and marketing costs still apply.","B":"Correct selection.","C":"Incorrect because moulded pulp can still be printed or sleeved with clear branding.","D":"Incorrect because consumer laws remain fully binding."}}},{"id":"P1_U3_MCQ_183","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_183","question":"A pharmaceutical firm spends $40 million over four years testing a new allergy medication in clinical trials before receiving regulatory approval to sell a single dose. Which stage of the 'Product Life Cycle' is this?","options":{"A":"Growth stage","B":"Maturity stage","C":"Research and development (R&D) stage","D":"Decline stage"},"correctOption":"C","correctAnswer":"Research and development (R&D) stage","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because during R&D, the firm incurs heavy investment outlays with zero sales revenue and negative cash flow prior to commercial launch.","distractor_reasons":{"A":"Incorrect because growth features rapidly rising commercial sales.","B":"Incorrect because maturity represents peak sales and strong positive cash flow.","C":"Correct selection.","D":"Incorrect because decline occurs after peak sales when demand falls."}}},{"id":"P1_U3_MCQ_184","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_184","question":"Sales of a new portable solar power bank surge by 60% per quarter, unit production costs fall as factory output scales up, and the product turns profitable for the first time while rivals rush to launch copies. Which PLC stage is this?","options":{"A":"Development","B":"Introduction","C":"Decline","D":"Growth"},"correctOption":"D","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the growth stage combines rapid sales acceleration, economies of scale, rising profitability, and emerging competitor entry.","distractor_reasons":{"A":"Incorrect because development has zero sales.","B":"Incorrect because introduction features slow initial sales and typically net losses.","C":"Incorrect because decline features falling sales and shrinking margins.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_185","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_185","question":"Sales of a traditional corded landline telephone fall steadily every year as households switch exclusively to mobile smartphones. What action should the manufacturer take in this 'decline stage'?","options":{"A":"Gradually reduce promotional spending to harvest remaining cash flow, and prepare to discontinue the line once it becomes unprofitable","B":"Invest $50 million in building three brand-new corded-telephone factories","C":"Apply high price skimming as if the corded phone were a brand-new innovation","D":"Launch an expensive nationwide youth social-media influencer campaign"},"correctOption":"A","correctAnswer":"Gradually reduce promotional spending to harvest remaining cash flow, and prepare to discontinue the line once it becomes unprofitable","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when technological obsolescence drives permanent decline, cutting marketing overheads ('harvesting') and phasing out the product protects capital for newer lines.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because expanding factory capacity in a dying market wastes capital.","C":"Incorrect because price skimming works only at initial launch for innovative goods.","D":"Incorrect because youth audiences have permanently moved to smartphones."}}},{"id":"P1_U3_MCQ_186","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_186","question":"When domestic sales of its classic carbonated lemonade plateau in its mature home market, a beverage firm launches the drink in fast-growing emerging markets abroad. Which strategy is this?","options":{"A":"Product withdrawal","B":"Product Life Cycle extension strategy (entering new geographic markets)","C":"Cost-plus price skimming","D":"Primary quota sampling"},"correctOption":"B","correctAnswer":"Product Life Cycle extension strategy (entering new geographic markets)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because finding new geographic markets gives a domestically mature product a fresh growth curve abroad.","distractor_reasons":{"A":"Incorrect because withdrawal removes the product from sale.","B":"Correct selection.","C":"Incorrect because expanding into new markets is a Product/Place extension move rather than launch skimming.","D":"Incorrect because quota sampling is a research technique."}}},{"id":"P1_U3_MCQ_187","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_187","question":"A chocolate-bar brand whose sales have leveled off in maturity introduces a 'mint-crunch limited edition' and a resealable share-pouch format. What is the objective of these changes?","options":{"A":"To move the chocolate bar immediately into the decline stage","B":"To eliminate all supermarket distribution channels","C":"To stimulate fresh consumer interest and extend the profitable maturity stage of the Product Life Cycle","D":"To reduce product variety to a single basic wrapper"},"correctOption":"C","correctAnswer":"To stimulate fresh consumer interest and extend the profitable maturity stage of the Product Life Cycle","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because product variations and new packaging formats are classic extension strategies that revive mature sales.","distractor_reasons":{"A":"Incorrect because extension strategies aim to delay decline rather than accelerate it.","B":"Incorrect because new variants rely on strong supermarket distribution.","C":"Correct selection.","D":"Incorrect because adding limited editions and share-pouches increases variety."}}},{"id":"P1_U3_MCQ_188","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_188","question":"What is a major risk when a company spends heavily on advertising and packaging redesigns to extend the life of a product in the 'decline stage'?","options":{"A":"Extension strategies always reduce unit production costs to zero","B":"Regulators fine businesses that update packaging on mature products","C":"Customers become confused and buy twice as much as expected","D":"If consumer tastes or technology have permanently shifted away, the extra promotional spending will fail to revive sales and reduce overall profit"},"correctOption":"D","correctAnswer":"If consumer tastes or technology have permanently shifted away, the extra promotional spending will fail to revive sales and reduce overall profit","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because extension strategies cannot rescue a product made permanently obsolete by superior technology (such as film cameras vs smartphones).","distractor_reasons":{"A":"Incorrect because redesigning packaging and advertising increases marketing expenses.","B":"Incorrect because updating packaging is completely lawful.","C":"Incorrect because the risk is wasted expenditure with weak sales response, not excess demand.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_189","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_189","question":"A designer handbag maker uses hand-stitched Italian leather and exclusive boutique displays, yet prices its bags at $25—the same as mass-market canvas totes. Why is this pricing decision flawed?","options":{"A":"The low price conflicts with the luxury Product image, causing wealthy buyers to doubt its authenticity and failing to cover high craft costs","B":"Luxury handbags must always use penetration pricing to maximize supermarket volume","C":"Wealthy consumers only buy designer accessories priced under $30","D":"Italian leather handbags have zero variable material costs"},"correctOption":"A","correctAnswer":"The low price conflicts with the luxury Product image, causing wealthy buyers to doubt its authenticity and failing to cover high craft costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because price acts as a powerful quality signal and must align with product positioning and unit costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because luxury goods rely on prestige pricing rather than mass supermarket penetration.","C":"Incorrect because luxury shoppers associate high prices with exclusivity and status.","D":"Incorrect because fine leather and hand-stitching carry high unit costs."}}},{"id":"P1_U3_MCQ_190","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_190","question":"A ceramic-mug manufacturer incurs total production costs of $12,000 to produce a batch of 1,500 mugs. If it applies a 25% cost-plus mark-up, what is the selling price per mug?","options":{"A":"$8.00","B":"$10.00","C":"$10.67","D":"$12.50"},"correctOption":"B","correctAnswer":"$10.00","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Unit Cost = $12,000 / 1,500 = $8.00; Selling Price = $8.00 + (25% of $8.00) = $8.00 + $2.00 = $10.00.","distractor_reasons":{"A":"Incorrect because $8.00 is the unit production cost before adding the 25% profit mark-up.","B":"Correct selection.","C":"Incorrect because $10.67 divides $8.00 by 0.75 instead of adding a 25% mark-up.","D":"Incorrect because $12.50 adds $4.50 rather than 25% of $8.00."}}},{"id":"P1_U3_MCQ_191","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_191","question":"Why might a cloud-storage startup choose 'penetration pricing' (free basic tier + $2/month upgrade) rather than 'price skimming' when launching its app?","options":{"A":"Because cloud storage has very high physical shipping costs per gigabyte","B":"Because early adopters never try new software apps","C":"Because low initial prices rapidly build a huge user base and customer lock-in in a competitive market with low marginal serving costs","D":"Because price skimming is legally forbidden for digital software companies"},"correctOption":"C","correctAnswer":"Because low initial prices rapidly build a huge user base and customer lock-in in a competitive market with low marginal serving costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because digital platforms benefit from rapid scale and switching costs once users store files on the platform.","distractor_reasons":{"A":"Incorrect because digital cloud storage has zero physical parcel shipping costs.","B":"Incorrect because tech users readily adopt new apps.","C":"Correct selection.","D":"Incorrect because software firms can lawfully choose any non-predatory pricing model."}}},{"id":"P1_U3_MCQ_192","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_192","question":"A new regional airline launches flights on a popular route where two established airlines charge $140 per ticket. The new airline sets its fare at $139 while offering free seat selection and snacks. Why is 'competitive pricing' wiser than slashing fares to $60?","options":{"A":"Airlines are legally banned from charging below $130 per flight","B":"Slashing fares to $60 would make demand completely price inelastic","C":"Customers refuse to fly on airlines that offer discounted tickets","D":"Matching rival fares avoids triggering a destructive price war that would bankrupt all airlines on the route, allowing competition on service value"},"correctOption":"D","correctAnswer":"Matching rival fares avoids triggering a destructive price war that would bankrupt all airlines on the route, allowing competition on service value","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because matching industry prices prevents mutually damaging price-cutting while differentiating through added service perks.","distractor_reasons":{"A":"Incorrect because airlines set fares freely in deregulated markets.","B":"Incorrect because air travel leisure demand is typically price elastic.","C":"Incorrect because travellers love low fares, though unsustainably low fares destroy airline profitability.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_193","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_193","question":"Every evening at 7:30 PM, a supermarket bakery reduces the price of fresh bread loaves by 60% so they sell before closing time rather than being thrown away. Which pricing tactic is this?","options":{"A":"Promotional clearance pricing","B":"Price skimming","C":"Cost-plus mark-up pricing","D":"Psychological prestige pricing"},"correctOption":"A","correctAnswer":"Promotional clearance pricing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because temporary end-of-day markdowns clear perishable inventory quickly and recover cash.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because skimming charges a high launch price for innovative products.","C":"Incorrect because end-of-day markdowns often sell below full cost to avoid total spoilage loss.","D":"Incorrect because clearance discounts signal bargain value rather than luxury prestige."}}},{"id":"P1_U3_MCQ_194","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_194","question":"An electronics retailer prices a mid-range tablet computer at $299 rather than $300 so shoppers mentally categorize it as 'under $300'. Which pricing technique is being used?","options":{"A":"Penetration pricing","B":"Psychological (charm) pricing","C":"Dynamic surge pricing","D":"Loss-leader pricing"},"correctOption":"B","correctAnswer":"Psychological (charm) pricing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because charm pricing ($299 vs $300) exploits left-digit perception to make a price feel noticeably lower.","distractor_reasons":{"A":"Incorrect because penetration pricing sets a substantially lower entry price to win market share.","B":"Correct selection.","C":"Incorrect because dynamic pricing fluctuates automatically with live demand.","D":"Incorrect because loss-leader pricing sells an item below cost to attract store traffic."}}},{"id":"P1_U3_MCQ_195","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_195","question":"During a sudden evening thunderstorm, a ride-hailing app automatically increases trip fares by 1.5×, encouraging more drivers to log on while rationing rides to urgent passengers. Which pricing strategy is operating?","options":{"A":"Fixed cost-plus pricing","B":"Static penetration pricing","C":"Dynamic pricing","D":"Promotional clearance pricing"},"correctOption":"C","correctAnswer":"Dynamic pricing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because dynamic pricing uses real-time algorithms to adjust prices instantaneously to shifts in supply and demand.","distractor_reasons":{"A":"Incorrect because cost-plus remains fixed regardless of weather or demand spikes.","B":"Incorrect because penetration pricing is a low introductory launch price.","C":"Correct selection.","D":"Incorrect because surge fares raise prices during peak demand rather than discounting surplus stock."}}},{"id":"P1_U3_MCQ_196","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_196","question":"When a regional bus operator increases ticket fares by 20%, passenger journeys fall by 10%. What is the numerical magnitude of Price Elasticity of Demand (PED), and is demand elastic or inelastic?","options":{"A":"PED = 2.0 (price elastic)","B":"PED = 10.0 (perfectly price elastic)","C":"PED = 1.0 (unitary elastic)","D":"PED = 0.5 (price inelastic)"},"correctOption":"D","correctAnswer":"PED = 0.5 (price inelastic)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because PED = % Change in Quantity Demanded / % Change in Price = 10% / 20% = 0.5; since 0.5 < 1, demand is price inelastic.","distractor_reasons":{"A":"Incorrect because 2.0 divides 20% by 10% (inverting the formula).","B":"Incorrect because 10.0 confuses the percentage drop with elasticity.","C":"Incorrect because unitary elasticity requires equal percentage changes in quantity and price.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_197","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_197","question":"A restaurant chain discovers through pricing trials that demand for its lunchtime pasta bowls is highly 'price elastic' (PED = 2.2). If the chain wants to increase its total sales revenue, what should it do?","options":{"A":"Lower the price of the pasta bowls, because the percentage increase in customer orders will be more than double the percentage price cut","B":"Raise the price by 20%, because customers will ignore price changes","C":"Keep prices unchanged while cutting portion sizes in half","D":"Stop advertising lunchtime meals completely"},"correctOption":"A","correctAnswer":"Lower the price of the pasta bowls, because the percentage increase in customer orders will be more than double the percentage price cut","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when demand is price elastic (PED > 1), reducing price generates a proportionally larger surge in quantity demanded, raising total revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raising prices on an elastic product causes a sharp drop in volume and lower total revenue.","C":"Incorrect because halving portions reduces perceived value and drives diners away.","D":"Incorrect because cutting promotion reduces customer awareness."}}},{"id":"P1_U3_MCQ_198","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_198","question":"A manufacturer of specialized replacement water-pump seals for commercial ships faces highly 'price inelastic' demand. If it cuts prices by 15%, quantity ordered rises by only 3%. What is the financial result?","options":{"A":"Total sales revenue increases dramatically because shipping companies stockpile seals","B":"Total sales revenue falls because the 15% revenue loss per unit outweighs the tiny 3% gain in sales volume","C":"Total profit doubles immediately","D":"Demand automatically becomes perfectly price elastic"},"correctOption":"B","correctAnswer":"Total sales revenue falls because the 15% revenue loss per unit outweighs the tiny 3% gain in sales volume","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because discounting a price-inelastic essential component sacrifices margin without stimulating meaningful extra demand.","distractor_reasons":{"A":"Incorrect because buyers replace seals only when maintenance requires them (only +3% volume).","B":"Correct selection.","C":"Incorrect because lower revenue on slightly higher output reduces profit.","D":"Incorrect because price cuts do not turn a specialized essential spare part into an elastic impulse good."}}},{"id":"P1_U3_MCQ_199","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_199","question":"How does successful brand-building advertising affect a product's 'Price Elasticity of Demand (PED)' over time?","options":{"A":"It makes demand more price elastic so customers switch brands whenever a rival offers a 1-cent coupon","B":"It eliminates all consumer demand for the branded product","C":"It strengthens customer loyalty and perceived differentiation, making demand more price inelastic so the firm can sustain higher prices","D":"It forces the firm to adopt cost-plus pricing with a 1% mark-up"},"correctOption":"C","correctAnswer":"It strengthens customer loyalty and perceived differentiation, making demand more price inelastic so the firm can sustain higher prices","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because strong branding reduces the perceived substitutability of rival goods, lowering price sensitivity.","distractor_reasons":{"A":"Incorrect because strong branding reduces rather than increases switching.","B":"Incorrect because advertising stimulates demand.","C":"Correct selection.","D":"Incorrect because inelastic demand supports higher value-based profit margins."}}},{"id":"P1_U3_MCQ_200","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_200","question":"How does a typical technology hardware company adjust its pricing strategy as a flagship product moves from 'Introduction' to 'Maturity'?","options":{"A":"It starts with clearance discounts at introduction and raises prices by 100% during decline","B":"It keeps the exact same launch price for ten years regardless of competitor models","C":"It uses loss-leader pricing at launch and switches to price skimming when the product becomes obsolete","D":"It often starts with high price skimming for early adopters, then shifts toward competitive and promotional pricing as rivals enter during maturity"},"correctOption":"D","correctAnswer":"It often starts with high price skimming for early adopters, then shifts toward competitive and promotional pricing as rivals enter during maturity","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because evolving competition and buyer segments across the Product Life Cycle require adapting prices from early-adopter margins to mainstream competitiveness.","distractor_reasons":{"A":"Incorrect because clearance discounts belong at the end of the life cycle rather than introduction.","B":"Incorrect because rigid pricing loses share once competitors launch cheaper alternatives.","C":"Incorrect because skimming works only when a product is new and innovative.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_201","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_201","question":"An umbrella brand launches a great waterproof design at a fair price with catchy TV ads, yet sales disappoint because customers cannot find the umbrellas in local stores when it rains. Which element of the marketing mix failed?","options":{"A":"Place (distribution availability)","B":"Product design","C":"Price competitiveness","D":"Promotional awareness"},"correctOption":"A","correctAnswer":"Place (distribution availability)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because even the best product, price, and promotion fail if distribution channels do not place stock conveniently where and when buyers want it.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the scenario states the waterproof design was strong.","C":"Incorrect because the price was already competitive.","D":"Incorrect because TV ads generated awareness, but buyers could not locate stock."}}},{"id":"P1_U3_MCQ_202","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_202","question":"An organic vegetable farm sells weekly seasonal produce boxes directly to local households via its own website and delivery van. Why is this 'direct distribution channel' ideal?","options":{"A":"It allows vegetables to sit in wholesale warehouses for three months","B":"It keeps perishable produce fresh, avoids intermediary profit margins, and builds direct relationships with local subscribers","C":"It eliminates the need to harvest vegetables or maintain a delivery van","D":"It guarantees nationwide supermarket shelf space across 1,000 stores"},"correctOption":"B","correctAnswer":"It keeps perishable produce fresh, avoids intermediary profit margins, and builds direct relationships with local subscribers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because perishable farm produce benefits from zero-intermediary speed and full margin retention.","distractor_reasons":{"A":"Incorrect because storing fresh vegetables for months would cause spoilage.","B":"Correct selection.","C":"Incorrect because direct delivery still requires harvesting and transport logistics.","D":"Incorrect because selling direct via own vans bypasses national supermarkets."}}},{"id":"P1_U3_MCQ_203","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_203","question":"A major washing-machine manufacturer sells its appliances through large national electronics retail chains rather than operating hundreds of its own brand showrooms. Why is using 'retailers' advantageous here?","options":{"A":"Retailers never charge any profit margin on appliances sold","B":"Retailers manufacture the washing-machine motors on behalf of the brand","C":"Retail chains provide widespread physical store locations where shoppers can compare models and arrange home delivery without the manufacturer funding retail premises","D":"Using retailers prevents shoppers from comparing rival washing-machine brands"},"correctOption":"C","correctAnswer":"Retail chains provide widespread physical store locations where shoppers can compare models and arrange home delivery without the manufacturer funding retail premises","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because established retailers offer immediate nationwide store networks, customer footfall, and local delivery infrastructure.","distractor_reasons":{"A":"Incorrect because retailers earn a retail margin between wholesale purchase price and consumer price.","B":"Incorrect because retailers distribute finished appliances rather than manufacturing components.","C":"Correct selection.","D":"Incorrect because retail stores display competing brands side-by-side."}}},{"id":"P1_U3_MCQ_204","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_204","question":"A confectionery manufacturer sells chocolates through regional 'wholesalers', who then supply thousands of small convenience shops. What is a major disadvantage of this channel for the manufacturer?","options":{"A":"The manufacturer must deliver tiny ten-bar boxes individually to every corner shop","B":"Wholesalers refuse to buy bulk pallet loads from factories","C":"Independent corner shops cannot purchase small assorted quantities","D":"Each intermediary takes a profit margin, raising final retail prices or lowering factory margins, while the manufacturer loses direct control over store presentation"},"correctOption":"D","correctAnswer":"Each intermediary takes a profit margin, raising final retail prices or lowering factory margins, while the manufacturer loses direct control over store presentation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because adding both a wholesaler and a retailer lengthens the chain, sharing profit margins and distancing the producer from end consumers.","distractor_reasons":{"A":"Incorrect because wholesalers handle small-lot distribution to corner shops, saving the factory from doing so.","B":"Incorrect because buying in bulk is the wholesaler's core function.","C":"Incorrect because breaking bulk into small assortments is how wholesalers help corner shops.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_205","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_205","question":"A boutique Chilean vineyard wants to sell its wines to upscale restaurants in Japan, where it has no local contacts or staff. Why does it appoint an 'overseas sales agent' in Tokyo?","options":{"A":"The agent possesses established local hospitality contacts, language fluency, and import knowledge, earning commission only when orders are secured","B":"The agent buys the entire vineyard and pays all grape-harvesting wages","C":"Agents are legally required to sell products at zero profit margin","D":"Using an agent eliminates all international shipping and customs documentation"},"correctOption":"A","correctAnswer":"The agent possesses established local hospitality contacts, language fluency, and import knowledge, earning commission only when orders are secured","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because local agents overcome cultural and network barriers in unfamiliar export markets without fixed overseas branch overheads.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because agents represent producers on commission rather than buying the business.","C":"Incorrect because agents earn a negotiated sales commission.","D":"Incorrect because international freight and customs clearance still take place."}}},{"id":"P1_U3_MCQ_206","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_206","question":"Why do manufacturers of complex medical imaging equipment (such as hospital MRI scanners) use a 'direct sales channel' rather than selling through general wholesalers?","options":{"A":"MRI scanners are low-value impulse items bought in corner shops","B":"High technical complexity requires direct engineer consultation, custom hospital installation, staff training, and ongoing maintenance contracts","C":"Wholesalers are legally banned from storing electronic equipment","D":"Direct selling requires zero technical knowledge from the manufacturer's team"},"correctOption":"B","correctAnswer":"High technical complexity requires direct engineer consultation, custom hospital installation, staff training, and ongoing maintenance contracts","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because technically sophisticated, high-value capital goods need direct producer-to-buyer support before and after installation.","distractor_reasons":{"A":"Incorrect because MRI scanners are multi-million-dollar specialist capital equipment.","B":"Correct selection.","C":"Incorrect because wholesalers handle standard electronics, just not custom hospital scanners.","D":"Incorrect because direct B2B sales engineers must possess deep technical expertise."}}},{"id":"P1_U3_MCQ_207","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_207","question":"A quarry produces heavy crushed stone and concrete blocks that have high transport weight relative to their unit selling price. How does this product characteristic shape its 'Place' strategy?","options":{"A":"The quarry exports heavy stone blocks via individual air-freight parcels worldwide","B":"The quarry sells individual concrete blocks through luxury shopping-mall boutiques","C":"Distribution focuses on regional bulk truck deliveries directly to construction sites within a short radius to keep freight costs economical","D":"The quarry stores blocks in three layers of national wholesalers before selling"},"correctOption":"C","correctAnswer":"Distribution focuses on regional bulk truck deliveries directly to construction sites within a short radius to keep freight costs economical","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because bulky, low-value-to-weight materials become uncompetitive if shipped long distances or handled repeatedly.","distractor_reasons":{"A":"Incorrect because air freighting heavy stone would cost far more than the product's value.","B":"Incorrect because heavy construction materials are sold to builders rather than mall shoppers.","C":"Correct selection.","D":"Incorrect because multiple handling stages add prohibitive transport expenses."}}},{"id":"P1_U3_MCQ_208","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_208","question":"Many traditional book publishers and music labels now sell digital e-books and streaming downloads straight to consumers online, bypassing physical wholesalers and high-street shops. What is this trend called?","options":{"A":"Vertical backward integration","B":"Price skimming","C":"Quota market sampling","D":"Disintermediation (cutting out traditional intermediaries via e-commerce)"},"correctOption":"D","correctAnswer":"Disintermediation (cutting out traditional intermediaries via e-commerce)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because digital e-commerce allows producers to deliver directly to end users without middlemen.","distractor_reasons":{"A":"Incorrect because backward integration means buying a raw-material supplier.","B":"Incorrect because price skimming is a launch pricing method.","C":"Incorrect because quota sampling is a survey technique.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_209","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_209","question":"A medium-sized retailer launches an online store to complement its physical shops, but sees high cart-abandonment rates at checkout. Which 'e-commerce' barrier commonly causes shoppers to abandon online purchases?","options":{"A":"Unexpected high shipping fees, slow delivery estimates, or concerns over website payment security","B":"Shoppers are legally forbidden from buying goods online after 6:00 PM","C":"Online stores cannot display product prices in local currency","D":"E-commerce websites force buyers to visit a wholesale warehouse in person"},"correctOption":"A","correctAnswer":"Unexpected high shipping fees, slow delivery estimates, or concerns over website payment security","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because hidden delivery charges, long wait times, and trust/security doubts frequently deter online checkout completion.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because online shopping operates 24/7.","C":"Incorrect because e-commerce platforms routinely display local currencies.","D":"Incorrect because online purchases deliver directly to the buyer's address."}}},{"id":"P1_U3_MCQ_210","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_210","question":"A well-established toothpaste brand runs regular reminder advertisements even though most consumers already know the brand well. What is a primary aim of 'reminder promotion' for mature products?","options":{"A":"To explain for the very first time what toothpaste is used for","B":"To keep the brand top-of-mind in supermarkets so loyal buyers do not switch to aggressive rivals","C":"To eliminate the need to distribute toothpaste to retail stores","D":"To reduce factory production capacity to zero"},"correctOption":"B","correctAnswer":"To keep the brand top-of-mind in supermarkets so loyal buyers do not switch to aggressive rivals","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because in mature, competitive markets, ongoing promotion reinforces brand habit and defends shelf share.","distractor_reasons":{"A":"Incorrect because basic product education occurs during the introduction stage.","B":"Correct selection.","C":"Incorrect because retail distribution remains essential.","D":"Incorrect because reminder ads aim to sustain steady production and sales."}}},{"id":"P1_U3_MCQ_211","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_211","question":"A public health agency launches a campaign explaining the exact symptoms of heatstroke and step-by-step hydration advice during summer. Which type of advertising is this?","options":{"A":"Persuasive luxury brand advertising","B":"Point-of-sale clearance promotion","C":"Informative advertising","D":"Personal B2B door-to-door selling"},"correctOption":"C","correctAnswer":"Informative advertising","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because informative advertising focuses on communicating clear, factual knowledge and instructions to the audience.","distractor_reasons":{"A":"Incorrect because luxury ads use emotional status appeal rather than public safety facts.","B":"Incorrect because point-of-sale clearance discounts retail stock.","C":"Correct selection.","D":"Incorrect because personal selling involves individual commercial sales pitches."}}},{"id":"P1_U3_MCQ_212","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_212","question":"A fragrance brand's television commercial shows glamorous actors attending a Paris gala without mentioning bottle size, ingredients, or price. Which advertising approach is being used?","options":{"A":"Informative technical advertising","B":"Trade-fair wholesale cataloguing","C":"Loss-leader price promotion","D":"Persuasive (image-based) advertising"},"correctOption":"D","correctAnswer":"Persuasive (image-based) advertising","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because persuasive advertising builds emotional desire and aspirational brand associations to differentiate a product.","distractor_reasons":{"A":"Incorrect because no factual product specifications are given.","B":"Incorrect because trade catalogues target business buyers with technical details.","C":"Incorrect because luxury perfumes avoid discount loss-leader tactics.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_213","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_213","question":"Why does a multinational snack-food corporation still allocate millions of dollars to 'television and streaming video advertising' despite high airtime costs?","options":{"A":"Audiovisual storytelling demonstrates product enjoyment vividly and reaches millions of mass-market households simultaneously, building strong brand awareness","B":"Television commercials are cheaper per campaign than printing local flyers","C":"Viewers are legally forced to buy every product advertised on television","D":"Television advertising targets only a tiny niche of 50 industrial buyers"},"correctOption":"A","correctAnswer":"Audiovisual storytelling demonstrates product enjoyment vividly and reaches millions of mass-market households simultaneously, building strong brand awareness","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sight, sound, and motion create memorable brand impact across massive consumer audiences.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because national TV production and airtime are very expensive.","C":"Incorrect because consumers choose purchases freely.","D":"Incorrect because TV is a mass-market medium rather than a tiny B2B niche tool."}}},{"id":"P1_U3_MCQ_214","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_214","question":"A regional car dealership wants to promote its weekend trade-in event to drivers living within 30 kilometres of its showroom on a modest budget. Which advertising media are most suitable?","options":{"A":"Global airline in-flight magazines","B":"Local radio stations and local city newspapers","C":"International scientific academic journals","D":"Nationwide cinema trailers across all 50 states"},"correctOption":"B","correctAnswer":"Local radio stations and local city newspapers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because local radio (heard by commuters driving in their cars) and local newspapers reach the exact geographic catchment area affordably.","distractor_reasons":{"A":"Incorrect because in-flight magazines reach international travellers rather than local drivers.","B":"Correct selection.","C":"Incorrect because academic journals are untargeted for local car sales.","D":"Incorrect because nationwide cinema campaigns waste budget outside the dealership's 30 km radius."}}},{"id":"P1_U3_MCQ_215","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_215","question":"An urban food-delivery app places large illuminated billboards at busy commuter train stations. What design rule is most important for 'outdoor billboard advertising'?","options":{"A":"Include 500 words of detailed small-print terms and conditions","B":"Omit the brand name and app logo so commuters must guess the company","C":"Use bold visuals and a short, memorable 5-to-7-word headline because commuters pass by in just a few seconds","D":"Avoid placing billboards in high-footfall city centres"},"correctOption":"C","correctAnswer":"Use bold visuals and a short, memorable 5-to-7-word headline because commuters pass by in just a few seconds","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because outdoor posters have brief viewing windows, requiring instant visual clarity and concise messaging.","distractor_reasons":{"A":"Incorrect because passing commuters cannot read long paragraphs.","B":"Incorrect because clear brand identification is essential.","C":"Correct selection.","D":"Incorrect because high-traffic commuter hubs maximize billboard exposure."}}},{"id":"P1_U3_MCQ_216","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_216","question":"A new plant-based burger brand sets up cooking booths inside 50 supermarkets to hand out free hot bite-sized samples to weekend shoppers. Why is 'free sampling' an effective sales promotion for food launches?","options":{"A":"Free samples are completely free for the company to produce and staff","B":"Supermarkets legally require every new food product to give away free samples","C":"Free sampling eliminates the need to put nutritional labels on retail packs","D":"Tasting the product removes shopper scepticism about unfamiliar flavours and triggers immediate impulse purchases"},"correctOption":"D","correctAnswer":"Tasting the product removes shopper scepticism about unfamiliar flavours and triggers immediate impulse purchases","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumers hesitate to spend money on unfamiliar foods; tasting proves quality firsthand and converts trial into sales.","distractor_reasons":{"A":"Incorrect because producing sample stock and hiring demonstrators incurs significant cost.","B":"Incorrect because sampling is a voluntary promotional choice.","C":"Incorrect because full retail packs still require statutory labels.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_217","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_217","question":"A confectionery company pays supermarkets to place brightly coloured cardboard display stands of its chocolate bars right next to the checkout queues. What is this promotional technique called?","options":{"A":"Point-of-sale (POS) merchandising display","B":"Public relations press conference","C":"Personal B2B consultative selling","D":"External secondary desk research"},"correctOption":"A","correctAnswer":"Point-of-sale (POS) merchandising display","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because point-of-sale displays catch shoppers' eyes at the exact moment of payment, driving high-margin impulse buys.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because PR press conferences target journalists rather than checkout queues.","C":"Incorrect because personal selling involves one-to-one sales staff.","D":"Incorrect because POS displays are an in-store sales promotion tool."}}},{"id":"P1_U3_MCQ_218","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_218","question":"A soft-drinks brand runs an on-pack competition offering a chance to win concert tickets by entering a code printed inside bottle caps. What is a common limitation of such 'sales promotions'?","options":{"A":"Competitions are illegal in all consumer retail markets","B":"Sales often jump temporarily while the prize draw runs, but may drop back once the promotion ends if underlying brand loyalty is weak","C":"Every single customer must be awarded a concert ticket by law","D":"Competitions reduce product visibility on supermarket shelves"},"correctOption":"B","correctAnswer":"Sales often jump temporarily while the prize draw runs, but may drop back once the promotion ends if underlying brand loyalty is weak","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sales promotions create short-term spikes rather than permanent shifts in consumer preference unless paired with strong product value.","distractor_reasons":{"A":"Incorrect because promotional prize draws are lawful when run under fair rules.","B":"Correct selection.","C":"Incorrect because prize draws award prizes to randomly drawn winners.","D":"Incorrect because promotional packaging typically boosts shelf attention."}}},{"id":"P1_U3_MCQ_219","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_219","question":"An outdoor-apparel company donates waterproof jackets to mountain-rescue volunteers and sends a press release to national newspapers, resulting in favourable news articles. What is a key advantage and disadvantage of 'Public Relations (PR)'?","options":{"A":"News coverage is very expensive to buy, but the company controls every word printed by journalists","B":"PR is completely illegal for profit-making limited companies","C":"Editorial news coverage carries high public credibility at low media cost, but the business cannot control whether or how journalists report the story","D":"PR guarantees immediate 50% sales increases within twenty-four hours"},"correctOption":"C","correctAnswer":"Editorial news coverage carries high public credibility at low media cost, but the business cannot control whether or how journalists report the story","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because consumers trust independent news stories more than paid ads, though editors retain total control over publication.","distractor_reasons":{"A":"Incorrect because earned PR media space is unpaid and editors—not the firm—control the wording.","B":"Incorrect because PR is a standard, lawful marketing function.","C":"Correct selection.","D":"Incorrect because PR builds long-term goodwill rather than guaranteeing instant sales spikes."}}},{"id":"P1_U3_MCQ_220","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_220","question":"A telecommunications company pays to become the official shirt sponsor of a popular national football club. How does 'sponsorship' benefit the sponsor's marketing mix?","options":{"A":"It eliminates the need to maintain mobile phone towers or customer service","B":"It legally prevents rival telecom companies from advertising anywhere in the country","C":"It lowers the company's annual corporate tax rate to 0%","D":"It exposes the brand logo repeatedly to millions of passionate fans and associates the company with positive sporting excitement"},"correctOption":"D","correctAnswer":"It exposes the brand logo repeatedly to millions of passionate fans and associates the company with positive sporting excitement","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because sports sponsorship builds massive repeated brand visibility and transfers fan goodwill to the sponsor.","distractor_reasons":{"A":"Incorrect because network quality remains vital to retain subscribers.","B":"Incorrect because sponsorship grants exclusive club rights rather than banning rivals from general advertising.","C":"Incorrect because sponsorship does not eliminate corporate tax.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_221","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_221","question":"A commercial real-estate agency assigns dedicated property advisors to tour office buildings with corporate clients and negotiate custom lease terms. Why is 'personal selling' justified despite its high cost per client?","options":{"A":"Each commercial property lease is high-value and complex, requiring tailored negotiation and trust that mass advertising cannot close alone","B":"Personal selling is cheaper per contact than posting a single social media update","C":"Corporate clients are legally forbidden from viewing property photos online","D":"Personal selling requires zero commission or salary payments to advisors"},"correctOption":"A","correctAnswer":"Each commercial property lease is high-value and complex, requiring tailored negotiation and trust that mass advertising cannot close alone","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high-ticket transactions justify high personal-selling expenses when bespoke answers close lucrative contracts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because personal selling has a very high cost per contact.","C":"Incorrect because online listings introduce properties before personal tours occur.","D":"Incorrect because skilled advisors earn substantial salaries and commissions."}}},{"id":"P1_U3_MCQ_222","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_222","question":"When a shopper places running shoes into an online cart on a sportswear website but leaves without paying, the site sends an automated email two hours later offering free express shipping to complete the order. Which promotional tool is this?","options":{"A":"National television broadcast advertising","B":"Targeted digital direct marketing / email remarketing","C":"Outdoor highway billboard advertising","D":"In-store supermarket shelf wobbler"},"correctOption":"B","correctAnswer":"Targeted digital direct marketing / email remarketing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because personalized triggered emails follow up directly with warm prospects to convert abandoned carts into completed sales.","distractor_reasons":{"A":"Incorrect because TV broadcasts to mass audiences rather than individual website visitors.","B":"Correct selection.","C":"Incorrect because billboards are physical outdoor media.","D":"Incorrect because shelf wobblers are physical retail displays."}}},{"id":"P1_U3_MCQ_223","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_223","question":"How does 'social media marketing' differ fundamentally from traditional one-way newspaper or television advertising?","options":{"A":"Social media marketing is always completely free even when running paid targeted ad campaigns","B":"Social media platforms prohibit customers from posting comments or reviews","C":"Social media enables instant two-way dialogue, viral user sharing, and precise demographic/interest targeting","D":"Social media marketing can only be viewed on desktop computers in offices"},"correctOption":"C","correctAnswer":"Social media enables instant two-way dialogue, viral user sharing, and precise demographic/interest targeting","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social platforms turn passive audiences into interactive participants who comment, share, and provide immediate engagement analytics.","distractor_reasons":{"A":"Incorrect because paid social ads and content creation incur real budgets.","B":"Incorrect because public comments and reviews are defining features of social platforms.","C":"Correct selection.","D":"Incorrect because social media is accessed predominantly via mobile smartphones."}}},{"id":"P1_U3_MCQ_224","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_224","question":"A startup launching a brand-new food-delivery app allocates 35% of its first-year budget to promotion, whereas a long-established regional water utility spends less than 1%. Which factor explains this difference in 'marketing budgets'?","options":{"A":"Water utilities are legally forbidden from communicating with households","B":"Food-delivery apps have zero variable delivery costs","C":"Startups always earn higher first-year net profits than established utilities","D":"A new brand in a competitive market must build awareness from zero, whereas an established monopoly utility already has captive customers"},"correctOption":"D","correctAnswer":"A new brand in a competitive market must build awareness from zero, whereas an established monopoly utility already has captive customers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Product Life Cycle stage (introduction vs maturity) and competitive intensity strongly govern required promotional spending.","distractor_reasons":{"A":"Incorrect because utilities send bills and service notices regularly.","B":"Incorrect because delivery apps incur significant courier and app-operating costs.","C":"Incorrect because startups typically incur launch losses while building scale.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_225","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_225","question":"To launch a new smart fitness ring, a tech company combines tech-journalist preview reviews (PR), short-form workout influencer videos (social media), and a 15% pre-order launch code (sales promotion). Why is using a 'cohesive promotional mix' superior to relying on one single method?","options":{"A":"Different promotional tools reinforce each other—PR builds credibility, social media drives awareness, and launch codes trigger immediate purchases","B":"Combining three methods eliminates all promotional expenses","C":"Using multiple methods guarantees that the product never needs customer support","D":"Regulators require every product launch to use at least three advertising channels"},"correctOption":"A","correctAnswer":"Different promotional tools reinforce each other—PR builds credibility, social media drives awareness, and launch codes trigger immediate purchases","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because each promotional tool has distinct strengths; integrating them moves buyers smoothly from awareness to trust and action.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because running multiple coordinated activities requires careful budget allocation.","C":"Incorrect because post-purchase customer support remains vital for tech hardware.","D":"Incorrect because promotional mix choices are strategic rather than legally mandated."}}},{"id":"P1_U3_MCQ_226","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_226","question":"A skincare brand conducts customer research, selects environmentally conscious millennials as its target segment, and aligns refillable glass packaging, mid-premium pricing, e-commerce delivery, and influencer education campaigns. What has the brand created?","options":{"A":"An internal human resource redundancy plan","B":"A coherent, integrated marketing strategy built around a clear target market","C":"A product-oriented cost-plus accounting ledger","D":"An undifferentiated mass-market clearance policy"},"correctOption":"B","correctAnswer":"A coherent, integrated marketing strategy built around a clear target market","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a marketing strategy links market research and segmentation to a consistent, mutually reinforcing 4Ps marketing mix.","distractor_reasons":{"A":"Incorrect because redundancy planning belongs to Unit 2 Human Resources.","B":"Correct selection.","C":"Incorrect because the brand started with customer research rather than unresearched production.","D":"Incorrect because the brand specifically targeted eco-conscious millennials."}}},{"id":"P1_U3_MCQ_227","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_227","question":"An organic baby-food startup targets high-income, health-conscious parents. Which marketing mix combination best supports this 'marketing strategy'?","options":{"A":"Bulk 5-kilogram plastic tubs priced at $2, sold via roadside discount warehouses","B":"Unlabelled generic jars sold exclusively through late-night vending machines","C":"Certified organic BPA-free glass pouches, premium pricing, selective distribution in upscale grocers and online subscriptions, and paediatrician-endorsed parenting blogs","D":"High-sugar formula promoted via extreme-sports television commercials"},"correctOption":"C","correctAnswer":"Certified organic BPA-free glass pouches, premium pricing, selective distribution in upscale grocers and online subscriptions, and paediatrician-endorsed parenting blogs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because safe organic packaging, premium value pricing, trusted retail channels, and credible expert promotion align seamlessly with anxious, affluent parents' priorities.","distractor_reasons":{"A":"Incorrect because bulk plastic tubs and discount warehouses clash with affluent organic parent expectations.","B":"Incorrect because unlabelled jars violate food laws and fail to build parental trust.","C":"Correct selection.","D":"Incorrect because high sugar and extreme sports misalign completely with infant nutrition."}}},{"id":"P1_U3_MCQ_228","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_228","question":"A consumer-goods company launches a new everyday household laundry detergent aimed at budget-conscious mass-market families. Which marketing mix is most appropriate?","options":{"A":"Hand-numbered crystal bottles priced at $95, sold only in one boutique","B":"Personal door-to-door sales engineers visiting every household individually","C":"Price skimming at $60 per box with zero supermarket distribution","D":"Large economy family packs, competitive supermarket pricing, intensive grocery distribution, and TV/digital ads paired with money-off coupons"},"correctOption":"D","correctAnswer":"Large economy family packs, competitive supermarket pricing, intensive grocery distribution, and TV/digital ads paired with money-off coupons","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because everyday mass-market staples require affordable value packs, wide retail convenience, and broad promotional reach.","distractor_reasons":{"A":"Incorrect because crystal bottles and $95 pricing target ultra-luxury niches.","B":"Incorrect because personal selling is far too expensive for low-priced household staples.","C":"Incorrect because skipping supermarkets blocks access to everyday grocery shoppers.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_229","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_229","question":"A smart-thermostat brand moves from the 'Introduction stage' into the 'Maturity stage' as six rivals launch similar devices. How should its marketing strategy evolve?","options":{"A":"Shift from informative launch ads and high skimming prices toward persuasive brand differentiation, competitive bundle pricing, and wider retail distribution","B":"Cut retail distribution to one store and raise prices by 50%","C":"Stop all product updates and rely solely on early-adopter word-of-mouth","D":"Discontinue the thermostat immediately while sales are at their peak"},"correctOption":"A","correctAnswer":"Shift from informative launch ads and high skimming prices toward persuasive brand differentiation, competitive bundle pricing, and wider retail distribution","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because maturity brings intense competition, requiring broader availability, sharper value pricing, and persuasive differentiation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because restricting distribution and hiking prices when rivals enter causes rapid share loss.","C":"Incorrect because mainstream buyers need persuasive promotion and ongoing software/feature upgrades.","D":"Incorrect because maturity is the highest-volume profit phase and should be defended or extended."}}},{"id":"P1_U3_MCQ_230","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_230","question":"A major rival cuts prices on its cordless vacuum cleaners by 15%. Rather than matching the price cut and destroying profit margins, how can an established vacuum brand respond strategically?","options":{"A":"Ignore the competitor completely and reduce product warranty coverage","B":"Differentiate through value-added promotion—offering a free extra battery pack, a 5-year warranty, and persuasive ads highlighting superior suction power","C":"Close its online store and rely solely on wholesale cash-and-carry depots","D":"Raise its vacuum prices by 40% without adding any features"},"correctOption":"B","correctAnswer":"Differentiate through value-added promotion—offering a free extra battery pack, a 5-year warranty, and persuasive ads highlighting superior suction power","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-price competition (added accessories, extended warranties, quality positioning) protects brand equity and avoids destructive price wars.","distractor_reasons":{"A":"Incorrect because cutting warranties weakens perceived value against a cheaper rival.","B":"Correct selection.","C":"Incorrect because closing direct online sales restricts customer convenience.","D":"Incorrect because steep unsubstantiated price hikes widen the price gap further."}}},{"id":"P1_U3_MCQ_231","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_231","question":"During a strong economic boom with rising employment and consumer confidence, how should a home-renovation and furniture retailer adapt its marketing strategy?","options":{"A":"Discontinue all stylish higher-margin furniture ranges and sell only basic plastic chairs","B":"Cut promotional budgets to zero because consumers never shop during economic booms","C":"Promote higher-margin premium room collections, bespoke design consultations, and flexible upgrade packages to capture rising disposable income","D":"Switch exclusively to distress clearance pricing across all showrooms"},"correctOption":"C","correctAnswer":"Promote higher-margin premium room collections, bespoke design consultations, and flexible upgrade packages to capture rising disposable income","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because rising household incomes increase demand for big-ticket discretionary home upgrades and premium designs.","distractor_reasons":{"A":"Incorrect because booms shift spending toward higher-value goods rather than bare basics.","B":"Incorrect because active promotion helps capture growing consumer spending ahead of rivals.","C":"Correct selection.","D":"Incorrect because heavy discounting sacrifices margins unnecessarily when demand is strong."}}},{"id":"P1_U3_MCQ_232","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_232","question":"A European household-appliance maker faces a saturated domestic market where almost every household already owns a refrigerator. Why is expanding into fast-growing emerging foreign markets an attractive strategic opportunity?","options":{"A":"Emerging foreign markets never have any local competitors or import rules","B":"Shipping heavy refrigerators overseas costs zero freight or insurance","C":"Consumers in emerging markets prefer broken appliances without warranties","D":"Rising middle-class incomes abroad create millions of first-time buyers, enabling rapid sales growth and economies of scale"},"correctOption":"D","correctAnswer":"Rising middle-class incomes abroad create millions of first-time buyers, enabling rapid sales growth and economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because entering expanding overseas markets overcomes domestic saturation and extends product life cycles.","distractor_reasons":{"A":"Incorrect because emerging markets feature local rivals and regulatory requirements.","B":"Incorrect because international freight and insurance are real expenses.","C":"Incorrect because reliable quality and warranties remain vital to build trust abroad.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_233","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_233","question":"A North American beverage company translates its catchy English slogan word-for-word into a foreign language, accidentally creating an offensive slang phrase that triggers a consumer boycott. Which foreign market entry risk does this illustrate?","options":{"A":"Linguistic and cultural translation errors resulting from insufficient local market research","B":"High import tariffs imposed by customs authorities","C":"Currency exchange-rate appreciation making exports expensive","D":"Lack of factory production capacity in the home country"},"correctOption":"A","correctAnswer":"Linguistic and cultural translation errors resulting from insufficient local market research","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because idioms and brand names rarely translate literally; local cultural consultation is essential before launching campaigns abroad.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tariffs are trade taxes rather than slogan translation mistakes.","C":"Incorrect because exchange rates affect pricing rather than linguistic meaning.","D":"Incorrect because the boycott was triggered by offensive messaging rather than stock shortages."}}},{"id":"P1_U3_MCQ_234","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_234","question":"A British textile manufacturer exports wool coats priced in British pounds (£) to retail buyers in the United States. If the British pound appreciates (strengthens) sharply against the US dollar ($), how does this affect the exporter's foreign marketing competitiveness?","options":{"A":"British coats become much cheaper in US dollars, boosting US orders automatically","B":"British coats become more expensive in US dollars, reducing price competitiveness against US and rival foreign brands","C":"Exchange-rate movements have zero effect on export prices paid by foreign importers","D":"The British manufacturer is exempted from paying UK wages and raw-material bills"},"correctOption":"B","correctAnswer":"British coats become more expensive in US dollars, reducing price competitiveness against US and rival foreign brands","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a stronger home currency requires foreign buyers to spend more of their own currency per pound, raising export prices.","distractor_reasons":{"A":"Incorrect because a stronger pound makes UK exports dearer in dollars (currency depreciation makes exports cheaper).","B":"Correct selection.","C":"Incorrect because currency conversion directly alters foreign-currency retail prices or exporter margins.","D":"Incorrect because domestic operating costs remain unchanged."}}},{"id":"P1_U3_MCQ_235","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_235","question":"Before exporting electric hairdryers from Europe to North America and Japan, a manufacturer must redesign the electrical plugs, voltage ratings, and safety certification labels. Which challenge of entering foreign markets does this represent?","options":{"A":"Adapting products to comply with differing national technical standards and legal regulations","B":"Overcoming seasonal weather differences between cities","C":"Using quota sampling to choose factory assembly workers","D":"Eliminating all wholesale and retail intermediaries"},"correctOption":"A","correctAnswer":"Adapting products to comply with differing national technical standards and legal regulations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because foreign markets enforce distinct electrical, safety, and labelling laws that require product adaptation before sale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because voltage and plug differences are technical/regulatory rather than weather-related.","C":"Incorrect because quota sampling is a survey research method.","D":"Incorrect because exporters still use local distributors or retailers."}}},{"id":"P1_U3_MCQ_236","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_236","question":"A medium-sized footwear brand wants to enter three foreign countries quickly without investing millions in building overseas company-owned stores. Why might it export through established foreign retail distributors rather than opening wholly owned subsidiaries?","options":{"A":"Foreign distributors never earn any profit margin on shoes sold","B":"Wholly owned subsidiaries are illegal in every foreign country","C":"Exporting via distributors eliminates all shipping and customs tariffs","D":"It requires far lower upfront capital investment and leverages existing local store networks, even though profit margins are shared"},"correctOption":"D","correctAnswer":"It requires far lower upfront capital investment and leverages existing local store networks, even though profit margins are shared","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because using local distributors lowers financial risk and speeds market entry when capital and local knowledge are limited.","distractor_reasons":{"A":"Incorrect because distributors take a wholesale/retail margin for their services.","B":"Incorrect because wholly owned subsidiaries are lawful in most countries, just very expensive.","C":"Incorrect because exported goods still cross borders subject to freight and applicable tariffs.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_237","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_237","question":"In a foreign country where laws forbid 100% foreign ownership of telecommunications networks, a European mobile operator partners 50/50 with a local company to build a new 5G network. Why is a 'joint venture' ideal here?","options":{"A":"It satisfies local ownership regulations while combining the European firm's 5G technology with the local partner's regulatory access and customer base","B":"It allows the European operator to keep 100% of all profits without consulting the local partner","C":"It guarantees that zero capital investment is needed to build 5G towers","D":"It eliminates all competition from rival mobile networks"},"correctOption":"A","correctAnswer":"It satisfies local ownership regulations while combining the European firm's 5G technology with the local partner's regulatory access and customer base","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because joint ventures unlock restricted foreign markets and share massive infrastructure costs and risks.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profits and strategic control are shared between both partners.","C":"Incorrect because both partners contribute capital to build the network.","D":"Incorrect because rival telecom firms still compete in the market."}}},{"id":"P1_U3_MCQ_238","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_238","question":"Shipping heavy glass bottles of soft drinks across oceans is prohibitively expensive relative to their retail price. How does 'licensing' local overseas bottling companies solve this problem?","options":{"A":"The brand owner gives away its secret recipe for free without earning royalties","B":"The foreign licensee produces and bottles the drink locally using the brand's formula and trademark in return for royalty fees, avoiding heavy liquid shipping costs and import tariffs","C":"The brand owner builds and staffs 50 wholly owned overseas bottling plants itself","D":"Licensing prevents foreign consumers from ever tasting the beverage"},"correctOption":"B","correctAnswer":"The foreign licensee produces and bottles the drink locally using the brand's formula and trademark in return for royalty fees, avoiding heavy liquid shipping costs and import tariffs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because local production under license eliminates bulky cross-border freight while generating low-risk royalty revenue.","distractor_reasons":{"A":"Incorrect because licensors earn contracted royalty fees on licensee production/sales.","B":"Correct selection.","C":"Incorrect because the local licensee funds its own bottling facilities.","D":"Incorrect because local bottling increases availability and freshness for foreign buyers."}}},{"id":"P1_U3_MCQ_239","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_239","question":"A global burger chain expands abroad through 'franchising' and conducts strict unannounced hygiene, recipe, and service inspections at overseas outlets. Why are these inspections essential?","options":{"A":"Because the franchisor pays 100% of every franchisee's daily restaurant electricity and wage bills","B":"Because franchisees are forbidden from earning any profit from their restaurants","C":"Because poor food hygiene or inconsistent quality at one overseas franchise damages the entire brand's global reputation","D":"Because franchising is illegal without government food tasters present every day"},"correctOption":"C","correctAnswer":"Because poor food hygiene or inconsistent quality at one overseas franchise damages the entire brand's global reputation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because customers view all outlets under the same brand logo as one company, so quality failures anywhere harm global trust.","distractor_reasons":{"A":"Incorrect because franchisees fund their own local operating expenses.","B":"Incorrect because franchisees keep remaining profits after paying royalties.","C":"Correct selection.","D":"Incorrect because quality audits are enforced contractually by the franchisor."}}},{"id":"P1_U3_MCQ_240","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_240","question":"What is a major strategic advantage for a successful domestic bakery-café brand expanding internationally via 'franchising' rather than opening company-owned branches?","options":{"A":"The franchisor retains 100% of every café's net profit","B":"The franchisor avoids giving franchisees any training or operating manuals","C":"Franchisees have no motivation to work hard because they earn fixed hourly wages","D":"Rapid international expansion is funded largely by franchisees' initial fees and capital, while local owners bring strong entrepreneurial motivation"},"correctOption":"D","correctAnswer":"Rapid international expansion is funded largely by franchisees' initial fees and capital, while local owners bring strong entrepreneurial motivation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because franchising scales a proven business model quickly with lower capital outlay and motivated local owner-operators.","distractor_reasons":{"A":"Incorrect because the franchisor earns upfront fees and percentage royalties rather than 100% of store profits.","B":"Incorrect because comprehensive training and brand manuals are vital to franchise success.","C":"Incorrect because franchisees invest their own capital and profit directly from store success.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_241","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_241","question":"A global streaming platform keeps its core brand logo and app interface identical worldwide, but produces local-language dramas and accepts local mobile-wallet payments in each country. Which international marketing approach is this?","options":{"A":"Glocalization ('think global, act local'—balancing global brand consistency with local adaptation)","B":"Pure undifferentiated mass standardization","C":"Product-oriented cost-plus exporting","D":"Domestic-only niche withdrawal"},"correctOption":"A","correctAnswer":"Glocalization ('think global, act local'—balancing global brand consistency with local adaptation)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because glocalization captures global brand recognition and technical scale while tailoring content and payment convenience to local cultures.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pure standardization ignores local languages and payment methods.","C":"Incorrect because tailoring shows to local audiences is strongly market-oriented.","D":"Incorrect because the platform is expanding globally rather than withdrawing domestically."}}},{"id":"P1_U3_MCQ_242","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_242","question":"A concert-ticketing website advertises tickets at '$40', but only reveals unavoidable '$18 booking and facility fees' on the final payment screen. Why do consumer protection authorities penalize this 'drip pricing'?","options":{"A":"Concert tickets are legally required to be sold free of charge","B":"Hiding mandatory fees until checkout deceives consumers about the true total price and prevents fair price comparison","C":"Online ticket sites are forbidden from charging any service fees","D":"Drip pricing reduces consumer demand to zero across all industries"},"correctOption":"B","correctAnswer":"Hiding mandatory fees until checkout deceives consumers about the true total price and prevents fair price comparison","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because fair-trading regulations require upfront display of the full unavoidable price so buyers are not misled.","distractor_reasons":{"A":"Incorrect because tickets are commercial products.","B":"Correct selection.","C":"Incorrect because booking fees are lawful if included transparently in the upfront headline price.","D":"Incorrect because drip pricing exploits shoppers until checkout rather than eliminating demand."}}},{"id":"P1_U3_MCQ_243","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_243","question":"A clothing brand prints '100% Eco-Sustainable Carbon-Zero T-Shirt' on its labels without any verified environmental data or offset evidence. Which legal marketing violation is occurring?","options":{"A":"Predatory monopoly price-fixing","B":"Failure to pay statutory employee overtime wages","C":"Misleading environmental advertising ('greenwashing') that makes unsubstantiated claims to deceive eco-conscious buyers","D":"Violation of international patent licensing quotas"},"correctOption":"C","correctAnswer":"Misleading environmental advertising ('greenwashing') that makes unsubstantiated claims to deceive eco-conscious buyers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because advertising standards and consumer laws require all environmental and performance claims to be truthful and backed by objective proof.","distractor_reasons":{"A":"Incorrect because price-fixing involves collusion among rivals over prices.","B":"Incorrect because employee wages belong to employment law rather than marketing claims.","C":"Correct selection.","D":"Incorrect because patent licensing protects technical inventions."}}},{"id":"P1_U3_MCQ_244","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_244","question":"Before selling children's pyjamas or electric heaters, a manufacturer must pass mandatory flammability and electrical-insulation tests enforced by consumer safety legislation. How does this law impact the business?","options":{"A":"It lowers product design and testing expenses to zero","B":"It allows the manufacturer to sell untested imports at double profit margins","C":"It applies only to small sole traders and exempts multinational corporations","D":"It increases R&D and quality-testing costs, but prevents dangerous injuries, product recalls, and severe legal fines"},"correctOption":"D","correctAnswer":"It increases R&D and quality-testing costs, but prevents dangerous injuries, product recalls, and severe legal fines","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because product safety laws impose compliance costs while safeguarding consumers and protecting reputable firms from unsafe low-cost rivals.","distractor_reasons":{"A":"Incorrect because safety testing adds real R&D and compliance costs.","B":"Incorrect because all products sold must meet safety standards regardless of origin.","C":"Incorrect because safety regulations bind all businesses equally.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_245","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_245","question":"A coffee roaster sells bags printed with 'Net Weight 500g', but government inspectors discover bags routinely contain only 440g due to uncalibrated filling machines. Which consumer law is breached?","options":{"A":"Weights and measures legislation requiring goods sold by weight or volume to match their stated quantity accurately","B":"Trade union recognition and collective bargaining legislation","C":"Copyright protection over original musical compositions","D":"Dynamic surge pricing regulations"},"correctOption":"A","correctAnswer":"Weights and measures legislation requiring goods sold by weight or volume to match their stated quantity accurately","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because weights-and-measures laws protect consumers from being short-changed on packaged quantities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because union laws govern employer-employee relations.","C":"Incorrect because copyright protects creative works.","D":"Incorrect because dynamic pricing adjusts prices with demand rather than package weight."}}},{"id":"P1_U3_MCQ_246","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_246","question":"An online retailer collects customers' email addresses during checkout and automatically sells the email list to third-party telemarketers without customer consent. Which legal control is being violated?","options":{"A":"Weights and measures packaging rules","B":"Data protection and consumer privacy legislation governing how personal customer data is stored, used, and shared","C":"Factory health and safety machinery rules","D":"Import tariff customs valuation rules"},"correctOption":"B","correctAnswer":"Data protection and consumer privacy legislation governing how personal customer data is stored, used, and shared","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because data protection laws prohibit sharing or using personal consumer data for direct marketing without explicit permission.","distractor_reasons":{"A":"Incorrect because weights and measures govern physical product quantities.","B":"Correct selection.","C":"Incorrect because factory safety laws govern physical workplace hazards.","D":"Incorrect because customs rules govern cross-border goods taxes."}}},{"id":"P1_U3_MCQ_247","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_247","question":"In many countries, governments ban television commercials for high-sugar junk food during children's programming hours and prohibit tobacco advertising altogether. How must affected businesses adapt their marketing?","options":{"A":"Ignore the advertising bans and pay daily criminal fines indefinitely","B":"Continue airing children's TV ads using cartoon mascots","C":"Reformulate healthier low-sugar product lines or shift promotional budgets toward compliant adult channels, packaging, and in-store displays","D":"Stop maintaining product quality or financial accounts"},"correctOption":"C","correctAnswer":"Reformulate healthier low-sugar product lines or shift promotional budgets toward compliant adult channels, packaging, and in-store displays","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because legal advertising restrictions force firms either to innovate compliant healthier products or adjust their promotional mix within the law.","distractor_reasons":{"A":"Incorrect because persistent non-compliance leads to severe penalties and broadcast bans.","B":"Incorrect because cartoon mascots on restricted ads directly breach child-marketing rules.","C":"Correct selection.","D":"Incorrect because operational quality and accounting remain essential."}}},{"id":"P1_U3_MCQ_248","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_248","question":"A customer orders a dining table online advertised as '100% Solid Walnut Wood', but receives a table made of cheap chipboard covered in thin plastic wood-grain sticker. Which statutory consumer right applies?","options":{"A":"The buyer must keep the table because online descriptions are never legally binding","B":"The seller only has to offer a 5% discount coupon toward a future purchase","C":"Consumer protection laws apply only to food and medicine, not furniture","D":"Goods must match their description ('as described'), entitling the customer to reject the table and receive a full refund"},"correctOption":"D","correctAnswer":"Goods must match their description ('as described'), entitling the customer to reject the table and receive a full refund","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumer protection statutes require products to correspond accurately with seller descriptions and samples.","distractor_reasons":{"A":"Incorrect because product descriptions form a legally binding part of the sales contract.","B":"Incorrect because a misdescribed item entitles the buyer to a full refund rather than a tiny voucher.","C":"Incorrect because consumer goods laws cover all consumer products including furniture.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_249","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_249","question":"How do strict, well-enforced 'consumer protection laws' ultimately benefit honest, quality-focused businesses?","options":{"A":"They build consumer confidence to buy—especially online—and prevent dishonest competitors from undercutting reputable firms with unsafe or misdescribed goods","B":"They allow honest businesses to charge unlimited monopoly prices without competition","C":"They eliminate all compliance, testing, and customer-service costs","D":"They guarantee that every new product launched will achieve 50% market share"},"correctOption":"A","correctAnswer":"They build consumer confidence to buy—especially online—and prevent dishonest competitors from undercutting reputable firms with unsafe or misdescribed goods","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because strong legal standards create a fair competitive playing field and increase shopper willingness to purchase.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because competition laws prevent anti-competitive monopoly abuse.","C":"Incorrect because compliance and after-sales service still carry costs.","D":"Incorrect because market share still depends on customer preference and competitive execution."}}},{"id":"P1_U3_MCQ_250","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_250","question":"A mid-sized sportswear brand faces slowing domestic sales in a mature market and intense price competition from online fast-fashion rivals. Which integrated long-term 'marketing strategy' is most likely to restore profitable growth?","options":{"A":"Cut product fabric quality while raising domestic prices by 30% and stopping all digital marketing","B":"Develop differentiated performance-engineered activewear using recycled fabrics (Product/USP), expand direct-to-consumer e-commerce alongside selective foreign entry via local distributors (Place), and build community loyalty via fitness influencers (Promotion)","C":"Abandon market research completely and sell identical unbranded grey tracksuits solely through one local wholesale warehouse","D":"Use deceptive 'Was $200, Now $40' fake discount pricing on low-quality garments"},"correctOption":"B","correctAnswer":"Develop differentiated performance-engineered activewear using recycled fabrics (Product/USP), expand direct-to-consumer e-commerce alongside selective foreign entry via local distributors (Place), and build community loyalty via fitness influencers (Promotion)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because combining product differentiation (sustainability/performance), omnichannel & international expansion, and targeted digital community building addresses both domestic maturity and online competition coherently.","distractor_reasons":{"A":"Incorrect because lowering quality while hiking prices accelerates customer defection.","B":"Correct selection.","C":"Incorrect because removing differentiation and restricting distribution weakens brand competitiveness.","D":"Incorrect because fictitious reference pricing violates consumer law and destroys brand trust."}}},{"id":"P1_U3_MCQ_251","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_251","question":"Before launching a range of ergonomic home-office chairs, a furniture manufacturer interviews remote workers about back-pain issues and desk space constraints. Which core function of marketing does this illustrate?","options":{"A":"Identifying and anticipating customer needs so products can be designed and sold profitably","B":"Maximizing factory machine utilization without checking buyer preferences","C":"Preparing statutory end-of-year profit and loss accounts for shareholders","D":"Negotiating collective wage agreements with factory trade unions"},"correctOption":"A","correctAnswer":"Identifying and anticipating customer needs so products can be designed and sold profitably","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because marketing begins with researching and anticipating consumer requirements in order to satisfy them profitably.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because maximizing machine output regardless of buyer demand describes a product-oriented operations focus.","C":"Incorrect because preparing financial statements is the role of the Finance department.","D":"Incorrect because industrial relations and wage negotiations belong to Human Resources."}}},{"id":"P1_U3_MCQ_252","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_252","question":"A boutique pet-supplies store tracks customers' dog birthdays and sends personalized grooming vouchers each year, resulting in 78% of buyers returning every month. Which marketing goal is the store achieving?","options":{"A":"Eliminating all variable inventory costs","B":"Building strong customer relationships and long-term brand loyalty","C":"Converting the business into a pure public-sector monopoly","D":"Operating a product-oriented mass-production assembly line"},"correctOption":"B","correctAnswer":"Building strong customer relationships and long-term brand loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because personalized engagement strengthens emotional trust and encourages repeat purchases over time.","distractor_reasons":{"A":"Incorrect because retail stores still incur stock and grooming supply costs.","B":"Correct selection.","C":"Incorrect because private retail stores operate in competitive markets.","D":"Incorrect because tailoring vouchers to individual pets is customer-focused rather than product-oriented."}}},{"id":"P1_U3_MCQ_253","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_253","question":"Total annual sales in a national plant-based milk market equal $320 million, of which OatPure Ltd generates $48 million. What is OatPure Ltd's market share?","options":{"A":"6.7%","B":"48.0%","C":"15.0%","D":"18.0%"},"correctOption":"C","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Market Share (%) = ($48m / $320m) × 100 = 15.0%.","distractor_reasons":{"A":"Incorrect because 6.7% divides $320m by $48m instead of $48m by $320m.","B":"Incorrect because 48.0% confuses dollar sales ($48m) with percentage market share.","C":"Correct selection.","D":"Incorrect because 18.0% miscalculates the ratio between $48m and $320m."}}},{"id":"P1_U3_MCQ_254","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_254","question":"Over two years, total industry sales in the electric-scooter market expand by 30%, while VoltRide Ltd's sales revenue grows by 10%. How has VoltRide Ltd's competitive position changed?","options":{"A":"Its market share increased by 20%","B":"Its absolute sales revenue declined by 20%","C":"Its market share stayed exactly the same because sales rose","D":"Its market share fell because its sales grew more slowly than the overall market"},"correctOption":"D","correctAnswer":"Its market share fell because its sales grew more slowly than the overall market","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when total market sales expand faster (+30%) than a firm's own sales (+10%), rivals capture a larger share of the market.","distractor_reasons":{"A":"Incorrect because growing slower than the market reduces rather than increases market share.","B":"Incorrect because VoltRide's sales rose by 10% in absolute terms.","C":"Incorrect because market share depends on relative growth compared with total industry sales.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_255","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_255","question":"A traditional confectionery company observes consumers increasingly checking nutrition labels and cutting back on high-sugar sodas and sweets. Which driver of changing consumer spending patterns is affecting this industry?","options":{"A":"Growing health and wellness awareness shifting demand toward low-sugar, healthier alternatives","B":"A sudden decline in national literacy rates","C":"Government bans on supermarkets selling any packaged beverages","D":"Falling average life expectancy reducing total grocery demand"},"correctOption":"A","correctAnswer":"Growing health and wellness awareness shifting demand toward low-sugar, healthier alternatives","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because heightened health consciousness changes consumer tastes away from sugary items toward functional or low-calorie products.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because consumers are actively reading nutrition labels.","C":"Incorrect because supermarkets continue selling packaged beverages.","D":"Incorrect because health awareness—not falling life expectancy—drives low-sugar preferences."}}},{"id":"P1_U3_MCQ_256","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_256","question":"As dual-income households work longer hours and have less spare time for cooking from scratch, supermarkets report surging sales of pre-chopped vegetables and 15-minute meal kits. Which factor explains this spending shift?","options":{"A":"A massive drop in average household disposable income","B":"Changing lifestyles and higher demand for time-saving convenience products","C":"A legal ban on selling raw potatoes and fresh ingredients","D":"Decreasing availability of domestic kitchen refrigerators"},"correctOption":"B","correctAnswer":"Changing lifestyles and higher demand for time-saving convenience products","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because time-poor lifestyles increase willingness to pay for convenient, ready-to-cook food solutions.","distractor_reasons":{"A":"Incorrect because prepared meal kits cost more than raw ingredients, reflecting higher income and time scarcity.","B":"Correct selection.","C":"Incorrect because raw ingredients remain widely sold.","D":"Incorrect because chilled meal kits actually rely on household refrigeration."}}},{"id":"P1_U3_MCQ_257","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_257","question":"A DVD rental chain closes its high-street stores as households switch to monthly on-demand video streaming platforms. Which market change caused the rental chain's decline?","options":{"A":"Consumers stopped watching films and television series altogether","B":"DVD rental prices became completely price inelastic","C":"Technological innovation created superior digital substitutes that transformed consumer buying habits","D":"High-street landlords banned entertainment businesses from renting shops"},"correctOption":"C","correctAnswer":"Technological innovation created superior digital substitutes that transformed consumer buying habits","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because high-speed internet and streaming technology made physical disc rentals obsolete.","distractor_reasons":{"A":"Incorrect because film consumption increased via digital streaming.","B":"Incorrect because easy digital substitutes made physical DVD rentals highly price elastic.","C":"Correct selection.","D":"Incorrect because changing consumer technology—not landlord bans—drove the shift."}}},{"id":"P1_U3_MCQ_258","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_258","question":"After a government removes import tariffs and licensing restrictions in the domestic airline sector, three low-cost foreign carriers launch routes into the country. Why has competition intensified for the existing national airline?","options":{"A":"Consumer demand for air travel fell to zero","B":"Fuel costs disappeared for all newly licensed airlines","C":"Foreign airlines are legally forbidden from advertising ticket prices","D":"Deregulation and lower entry barriers allowed new rival suppliers to enter the market"},"correctOption":"D","correctAnswer":"Deregulation and lower entry barriers allowed new rival suppliers to enter the market","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because removing regulatory and trade barriers enables new competitors to challenge established incumbents.","distractor_reasons":{"A":"Incorrect because lower fares from new airlines typically expand passenger demand.","B":"Incorrect because all airlines still pay fuel and operating expenses.","C":"Incorrect because new entrants actively promote low fares.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_259","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_259","question":"Facing aggressive price-cutting from rival online pharmacies, an established pharmacy chain automates its prescription-sorting warehouses to cut unit handling costs by 25%. How does this operational change help its marketing response?","options":{"A":"Lower unit costs enable the chain to offer competitive prices without sacrificing profit margins","B":"Automation eliminates the need to employ qualified pharmacists in stores","C":"Warehouse automation guarantees that customers never compare medicine prices online","D":"Lower handling costs allow the chain to stop distributing medicines to local branches"},"correctOption":"A","correctAnswer":"Lower unit costs enable the chain to offer competitive prices without sacrificing profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because improving operational efficiency supports sustainable competitive pricing when rivals slash prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because licensed pharmacists remain legally required in retail pharmacies.","C":"Incorrect because online price comparison persists, making cost efficiency vital.","D":"Incorrect because warehouse sorting supplies local branches faster."}}},{"id":"P1_U3_MCQ_260","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_260","question":"When two giant supermarket chains open branches near a family-owned greengrocer, the greengrocer begins offering same-day local recipe boxes, locally grown heritage produce, and free home delivery for elderly residents. How is it responding to competition?","options":{"A":"By attempting to outspend national supermarkets on television advertising","B":"By differentiating through specialized local product quality and personalized community service","C":"By switching to undifferentiated mass-market canned goods","D":"By reducing store opening hours and raising prices on basic apples"},"correctOption":"B","correctAnswer":"By differentiating through specialized local product quality and personalized community service","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because small independent retailers compete effectively against supermarket scale by offering niche freshness and tailored personal care.","distractor_reasons":{"A":"Incorrect because a single greengrocer lacks the budget for national TV campaigns.","B":"Correct selection.","C":"Incorrect because selling standard canned goods puts the shop in direct price competition with supermarkets.","D":"Incorrect because cutting hours and raising prices on staples drives buyers away."}}},{"id":"P1_U3_MCQ_261","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_261","question":"A shoemaker crafts custom orthopaedic running shoes solely for athletes recovering from Achilles tendon injuries. Which market strategy is this business pursuing?","options":{"A":"Mass marketing","B":"Undifferentiated commodity marketing","C":"Niche marketing","D":"Cost-leadership supermarket marketing"},"correctOption":"C","correctAnswer":"Niche marketing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because niche marketing targets a small, specialized segment with very specific functional needs.","distractor_reasons":{"A":"Incorrect because mass marketing produces standardized shoes for the general public.","B":"Incorrect because undifferentiated marketing ignores specialized medical needs.","C":"Correct selection.","D":"Incorrect because custom orthopaedic shoes are specialist items rather than mass supermarket goods."}}},{"id":"P1_U3_MCQ_262","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_262","question":"How does a 'niche marketing' strategy help a specialist manufacturer of saltwater fly-fishing rods keep promotional costs low?","options":{"A":"Fly-fishing rods never require any product testing or quality control","B":"Governments pay 100% of advertising bills for specialist sports brands","C":"Mass-market supermarkets distribute fly-fishing rods free of charge","D":"The firm can advertise directly in dedicated fishing magazines and clubs where almost every reader is a potential buyer, avoiding wasted mass-media spend"},"correctOption":"D","correctAnswer":"The firm can advertise directly in dedicated fishing magazines and clubs where almost every reader is a potential buyer, avoiding wasted mass-media spend","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because well-defined niche audiences congregate in specialist media, maximizing promotional efficiency.","distractor_reasons":{"A":"Incorrect because technical gear requires rigorous testing.","B":"Incorrect because private firms fund their own marketing.","C":"Incorrect because specialist gear is sold via specialist tackle shops and direct online stores.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_263","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_263","question":"A small company produces exclusively custom leather covers for one specific model of e-reader. When the e-reader manufacturer discontinues that device, the cover company's sales collapse overnight. What key risk of 'niche marketing' does this demonstrate?","options":{"A":"Lack of product diversification leaves a niche business highly vulnerable if demand in its narrow segment disappears","B":"Unit production costs are always lower in niche markets than in mass markets","C":"Niche businesses spend too much on global television sponsorships","D":"Niche markets always have too many millions of customers to manage"},"correctOption":"A","correctAnswer":"Lack of product diversification leaves a niche business highly vulnerable if demand in its narrow segment disappears","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because relying on a single small segment exposes a firm to severe revenue shock if tastes or technology change.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because unit costs are generally higher in small-batch niche production.","C":"Incorrect because niche firms rarely use global TV sponsorships.","D":"Incorrect because small total customer numbers define niche markets."}}},{"id":"P1_U3_MCQ_264","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_264","question":"A paper mill produces standard white A4 printer paper sold in identical 500-sheet reams to offices, schools, and households nationwide. Which approach is the mill using?","options":{"A":"Bespoke luxury marketing","B":"Mass marketing","C":"Micro-niche targeting","D":"Psychographic lifestyle segmentation"},"correctOption":"B","correctAnswer":"Mass marketing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because standard A4 copy paper is a uniform product aimed at the widest possible market with standardized production.","distractor_reasons":{"A":"Incorrect because bespoke marketing customizes products for individual buyers.","B":"Correct selection.","C":"Incorrect because standard office paper serves universal mainstream demand.","D":"Incorrect because A4 paper is bought across all lifestyles without personal value tailoring."}}},{"id":"P1_U3_MCQ_265","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_265","question":"Why can a large 'mass-market' biscuit manufacturer afford to spend $10 million on a nationwide television campaign while keeping retail packet prices at $1.50?","options":{"A":"Television networks air commercials free of charge for food companies","B":"Biscuit factories pay zero wages or ingredient expenses","C":"Selling tens of millions of packets spreads fixed advertising and factory overheads across huge unit volumes","D":"Mass-market biscuits are exempt from retail sales taxes"},"correctOption":"C","correctAnswer":"Selling tens of millions of packets spreads fixed advertising and factory overheads across huge unit volumes","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because marketing and technical economies of scale reduce the advertising and production cost per unit sold.","distractor_reasons":{"A":"Incorrect because TV networks charge high commercial rates.","B":"Incorrect because factories incur major raw-material and labour costs.","C":"Correct selection.","D":"Incorrect because standard taxes apply equally."}}},{"id":"P1_U3_MCQ_266","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_266","question":"In a saturated mass market for bottled still water, four major brands offer nearly identical products, leading to frequent supermarket price discounts and squeezed profit margins. Which disadvantage of 'mass marketing' is occurring?","options":{"A":"Inability to use automated bottling machinery","B":"Total customer demand is too small to supply supermarkets","C":"High customer loyalty prevents shoppers from ever switching brands","D":"Low product differentiation intensifies price competition and erodes unit profit margins"},"correctOption":"D","correctAnswer":"Low product differentiation intensifies price competition and erodes unit profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when mass-market goods appear standardized, buyers easily switch on price, forcing firms into margin-eroding competition.","distractor_reasons":{"A":"Incorrect because high-volume bottling uses rapid automated machinery.","B":"Incorrect because bottled water has massive mainstream demand.","C":"Incorrect because undifferentiated commodities suffer high brand switching.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_267","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_267","question":"A global trainer brand manufactures standard running shoes in bulk, but lets online buyers pick custom sole colours, lace styles, and embroidered initials for an extra $25. How does this strategy combine mass and niche benefits?","options":{"A":"It captures core mass-production economies of scale while satisfying individual consumer desire for personalized differentiation","B":"It eliminates all online delivery and manufacturing costs","C":"It prevents customers from buying standard shoes in retail stores","D":"It forces every customer to accept the exact same shoe colour"},"correctOption":"A","correctAnswer":"It captures core mass-production economies of scale while satisfying individual consumer desire for personalized differentiation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mass customization uses standardized base components to keep unit costs reasonable while charging a premium for tailored finishing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because custom orders still incur production and shipping costs.","C":"Incorrect because retail stores continue selling standard models alongside online customization.","D":"Incorrect because buyers actively select their own colour combinations."}}},{"id":"P1_U3_MCQ_268","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_268","question":"What is the fundamental purpose of 'market segmentation' for a medium-sized consumer-electronics company?","options":{"A":"To charge every customer the exact same price regardless of product features","B":"To divide a broad, diverse market into distinct buyer groups with shared needs so tailored products and promotions can be designed for each","C":"To reduce the number of customers buying from the company","D":"To avoid conducting any market research before designing products"},"correctOption":"B","correctAnswer":"To divide a broad, diverse market into distinct buyer groups with shared needs so tailored products and promotions can be designed for each","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consumers differ in tastes, budgets, and uses; segmentation aligns the 4Ps closely with each target group.","distractor_reasons":{"A":"Incorrect because segmentation supports tiered pricing across different product versions.","B":"Correct selection.","C":"Incorrect because segmentation aims to grow sales by appealing more accurately to chosen groups.","D":"Incorrect because segmentation depends on thorough research data."}}},{"id":"P1_U3_MCQ_269","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_269","question":"A real-estate developer builds trendy studio apartments near nightlife districts for single young professionals, four-bedroom suburban houses near schools for families with children, and single-level bungalows for retirees. Which segmentation variable is applied?","options":{"A":"Gender","B":"Climatic zone","C":"Demographic segmentation (age and family life-cycle stage)","D":"Undifferentiated mass marketing"},"correctOption":"C","correctAnswer":"Demographic segmentation (age and family life-cycle stage)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because household composition and life stage (single youth, parents with children, retirees) shape housing requirements.","distractor_reasons":{"A":"Incorrect because housing designs reflect household stage rather than male/female differences.","B":"Incorrect because all three housing types can exist within the same city climate.","C":"Correct selection.","D":"Incorrect because three distinct property types are built for three distinct groups."}}},{"id":"P1_U3_MCQ_270","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_270","question":"A textbook publisher produces illustrated phonics workbooks for primary-school pupils, exam revision guides for secondary students, and peer-reviewed journals for university researchers. How is the publisher segmenting its market?","options":{"A":"By geographic postcode","B":"By residential climate","C":"By customer gender","D":"By demographic variables (age and educational stage)"},"correctOption":"D","correctAnswer":"By demographic variables (age and educational stage)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because age and academic/educational level define the distinct learning needs of each reader group.","distractor_reasons":{"A":"Incorrect because students across all postcodes use the same curriculum books.","B":"Incorrect because weather climate does not determine academic reading level.","C":"Incorrect because educational texts serve all genders equally.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_271","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_271","question":"A garden-equipment manufacturer sells compact cordless balcony-plant trimmers in high-rise cities like Singapore and Tokyo, while marketing ride-on lawn tractors in suburban North America. Which segmentation approach is guiding product design?","options":{"A":"Geographic segmentation (region and housing environment)","B":"Gender segmentation","C":"Age-only segmentation","D":"Mass undifferentiated standardization"},"correctOption":"A","correctAnswer":"Geographic segmentation (region and housing environment)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because regional geography and local living spaces dictate whether buyers have small balconies or large lawns.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because garden size is determined by location rather than buyer gender.","C":"Incorrect because adults of any age in Singapore vs suburban America face different yard sizes.","D":"Incorrect because the firm sells two contrasting products adapted to local geography."}}},{"id":"P1_U3_MCQ_272","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_272","question":"A hotel group operates 'SleepEasy' budget motels at $55 per night alongside 'Grandeur Palace' five-star resorts at $750 per night. Which segmentation dimension separates these two brands?","options":{"A":"Gender","B":"Income and socio-economic group","C":"Age bracket","D":"Climatic zone"},"correctOption":"B","correctAnswer":"Income and socio-economic group","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because offering budget and luxury tiers allows the company to capture travellers across different disposable income levels.","distractor_reasons":{"A":"Incorrect because both hotel brands welcome all genders.","B":"Correct selection.","C":"Incorrect because budget and luxury travellers span all adult ages.","D":"Incorrect because both hotel tiers can operate in the same tourist destination."}}},{"id":"P1_U3_MCQ_273","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_273","question":"A carmaker launches a zero-emission compact EV promoted around carbon-footprint reduction for environmentally committed buyers, while marketing a twin-turbo V8 coupe to motorsport enthusiasts. Which segmentation basis is being used?","options":{"A":"Geographic postcode","B":"Marital status","C":"Lifestyle, attitudes, and personal values (psychographic segmentation)","D":"Family size"},"correctOption":"C","correctAnswer":"Lifestyle, attitudes, and personal values (psychographic segmentation)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because personal values (environmental activism vs motorsport thrill) distinguish buyer motivations beyond simple age or income.","distractor_reasons":{"A":"Incorrect because both buyer types can live in the same city.","B":"Incorrect because marital status does not determine EV vs V8 preference.","C":"Correct selection.","D":"Incorrect because both vehicles are compact/two-door models rather than large family vans."}}},{"id":"P1_U3_MCQ_274","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_274","question":"While analyzing consumer demographics, a cosmetics firm notices that men aged 25–40 increasingly buy skincare moisturizers, yet almost all rival creams are packaged in floral pink jars marketed to women. How does segmentation benefit the firm here?","options":{"A":"It proves that men never buy personal-care products","B":"It allows the firm to stop advertising altogether","C":"It lowers factory ingredient costs to zero","D":"It reveals an unserved gap in the market, allowing the firm to launch a dedicated men's skincare range ahead of competitors"},"correctOption":"D","correctAnswer":"It reveals an unserved gap in the market, allowing the firm to launch a dedicated men's skincare range ahead of competitors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because systematic segmentation uncovers neglected consumer groups where competition is still weak.","distractor_reasons":{"A":"Incorrect because the data explicitly shows rising male demand.","B":"Incorrect because entering a new segment requires targeted promotion.","C":"Incorrect because launching a new line involves R&D and packaging costs.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_275","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_275","question":"A tea company divides its customers into 18 separate segments, producing distinct blends, boxes, and adverts for each tiny group, causing warehouse storage and packaging costs to soar. What lesson does this illustrate?","options":{"A":"Each market segment must be large and profitable enough to justify the extra production, inventory, and promotional costs of serving it separately","B":"Market segmentation is always less profitable than selling one unbranded product","C":"Businesses should never segment consumers by age or income","D":"Producing 18 different box designs reduces printing and warehousing costs"},"correctOption":"A","correctAnswer":"Each market segment must be large and profitable enough to justify the extra production, inventory, and promotional costs of serving it separately","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because effective segments must be substantial and accessible enough that incremental revenue exceeds added customization costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because well-chosen segmentation increases profitability when segments are viable.","C":"Incorrect because age and income are valuable segmentation tools when not fragmented excessively.","D":"Incorrect because multiple variants increase setup, printing, and inventory holding costs."}}},{"id":"P1_U3_MCQ_276","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_276","question":"A software startup builds a complex project-management app packed with 90 technical buttons that its programmers thought were clever, without asking office managers what they needed. Users find it confusing and cancel subscriptions. What caused this failure?","options":{"A":"Excessive reliance on customer focus groups","B":"A product-oriented approach that ignored actual user needs and usability","C":"Over-spending on primary test marketing","D":"Pricing the software too low via penetration pricing"},"correctOption":"B","correctAnswer":"A product-oriented approach that ignored actual user needs and usability","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because product-oriented businesses prioritize internal technical preferences over verified customer problems.","distractor_reasons":{"A":"Incorrect because no customer focus groups were consulted.","B":"Correct selection.","C":"Incorrect because no user trials were run prior to launch.","D":"Incorrect because product usability—not low price—caused cancellations."}}},{"id":"P1_U3_MCQ_277","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_277","question":"Before designing a new mobile banking app for teenagers, a bank interviews 200 teens and their parents to discover which spending-limit controls and savings goals they want most. Which business orientation is demonstrated?","options":{"A":"Product orientation","B":"Production-led orientation","C":"Market orientation","D":"Asset-stripping orientation"},"correctOption":"C","correctAnswer":"Market orientation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a market-oriented organization researches customer desires first and shapes its product around those findings.","distractor_reasons":{"A":"Incorrect because product orientation builds features first without user research.","B":"Incorrect because production orientation focuses purely on high-volume low-cost output.","C":"Correct selection.","D":"Incorrect because asset-stripping refers to selling off parts of an acquired company."}}},{"id":"P1_U3_MCQ_278","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_278","question":"How does accurate 'market research' assist a food manufacturer when deciding how much factory capacity and raw ingredients to order for a new cereal launch?","options":{"A":"It eliminates the need to pay suppliers for oats and packaging","B":"It legally guarantees that supermarkets will sell 100% of stock delivered","C":"It replaces the need for quality assurance inspectors on the production line","D":"It provides realistic sales-volume forecasts, preventing costly overproduction of unsold stock or underproduction shortages"},"correctOption":"D","correctAnswer":"It provides realistic sales-volume forecasts, preventing costly overproduction of unsold stock or underproduction shortages","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because estimating likely demand aligns production scheduling and inventory purchasing with expected orders.","distractor_reasons":{"A":"Incorrect because raw materials still must be purchased.","B":"Incorrect because market research estimates demand rather than guaranteeing legal sales.","C":"Incorrect because factory quality control remains necessary.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_279","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_279","question":"An entrepreneur planning to open an indoor climbing gym stands outside local sports centres interviewing climbers about membership fees and wall difficulty preferences. Which type of research is being conducted?","options":{"A":"Primary (field) research","B":"Internal secondary accounting research","C":"External government census desk research","D":"Competitor annual-report desk analysis"},"correctOption":"A","correctAnswer":"Primary (field) research","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because collecting new responses first-hand directly from target customers for a specific business decision is primary research.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a startup entrepreneur has no internal past sales records.","C":"Incorrect because no government census tables are being read.","D":"Incorrect because live interviews generate fresh primary data rather than reading published reports."}}},{"id":"P1_U3_MCQ_280","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_280","question":"Why does a pharmaceutical or consumer-tech firm value 'primary market research' over publicly published industry reports when testing a confidential new product concept?","options":{"A":"Primary research is always faster and cheaper than downloading a free report","B":"The findings are proprietary and confidential to the firm, giving a competitive insight advantage that rivals cannot access","C":"Primary research requires zero effort to design questions or recruit participants","D":"Primary research automatically eliminates all sampling errors"},"correctOption":"B","correctAnswer":"The findings are proprietary and confidential to the firm, giving a competitive insight advantage that rivals cannot access","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because original data collected privately belongs exclusively to the commissioning business.","distractor_reasons":{"A":"Incorrect because primary research is slower and costlier than reading existing reports.","B":"Correct selection.","C":"Incorrect because questionnaire design and recruitment require substantial effort.","D":"Incorrect because primary surveys can still suffer sampling bias if poorly executed."}}},{"id":"P1_U3_MCQ_281","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_281","question":"A small independent bookshop wants to understand national reading trends across the entire country, but decides against commissioning a nationwide face-to-face primary survey. Why is primary research unsuitable here?","options":{"A":"National reading statistics are illegal to collect via surveys","B":"Primary research never produces numerical percentages","C":"Hiring interviewers across the whole country would be far too expensive and time-consuming when national book-trade secondary reports already exist","D":"Bookshop customers refuse to answer questions about genres they read"},"correctOption":"C","correctAnswer":"Hiring interviewers across the whole country would be far too expensive and time-consuming when national book-trade secondary reports already exist","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because broad macro-level industry trends are already published cheaply in trade association and government secondary sources.","distractor_reasons":{"A":"Incorrect because reading surveys are completely lawful.","B":"Incorrect because structured primary surveys readily generate quantitative percentages.","C":"Correct selection.","D":"Incorrect because the barrier is cost and scale rather than reader refusal."}}},{"id":"P1_U3_MCQ_282","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_282","question":"A questionnaire asks: 'Do you think our new laptop is lightweight and reasonably priced? Yes / No.' Why is this a poorly designed survey question?","options":{"A":"It uses secondary census data instead of primary customer opinions","B":"It is an open-ended essay question that cannot be coded","C":"It uses overly complex computer engineering jargon","D":"It is a double-barrelled question combining two separate issues (weight and price), making a single Yes/No answer ambiguous"},"correctOption":"D","correctAnswer":"It is a double-barrelled question combining two separate issues (weight and price), making a single Yes/No answer ambiguous","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a respondent might think the laptop is lightweight (Yes) but overpriced (No); each attribute must be asked separately.","distractor_reasons":{"A":"Incorrect because this is a primary questionnaire item.","B":"Incorrect because Yes/No is a closed format.","C":"Incorrect because 'lightweight' and 'reasonably priced' are everyday words.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_283","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_283","question":"When designing a customer feedback survey for 2,000 hotel guests, why are 'closed questions' (such as 1-to-5 satisfaction scales) preferred for the majority of the questionnaire?","options":{"A":"Responses can be quickly counted, compared statistically, and turned into graphs without subjective interpretation","B":"Closed questions allow guests to write two-page essays about every detail of their stay","C":"Closed questions guarantee a 100% response rate from all hotel guests","D":"Closed questions eliminate the need to select a representative sample"},"correctOption":"A","correctAnswer":"Responses can be quickly counted, compared statistically, and turned into graphs without subjective interpretation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because standardized numerical choices make large-scale quantitative tabulation fast and objective.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because long free-text responses describe open-ended questions.","C":"Incorrect because non-response still occurs in any survey.","D":"Incorrect because representative sampling remains essential."}}},{"id":"P1_U3_MCQ_284","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_284","question":"Why do 'postal questionnaires' often suffer from lower data accuracy than 'face-to-face interviews'?","options":{"A":"Postal questionnaires are much more expensive per contact than hiring personal interviewers","B":"Very low response rates mean only people with unusually strong opinions reply (non-response bias), and nobody is present to clarify confusing questions","C":"Postal questionnaires force interviewers to read answers aloud to respondents","D":"Postal questionnaires can only be sent to businesses rather than households"},"correctOption":"B","correctAnswer":"Very low response rates mean only people with unusually strong opinions reply (non-response bias), and nobody is present to clarify confusing questions","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because most mailed questionnaires are discarded, skewing the small returning sample toward unrepresentative extremes.","distractor_reasons":{"A":"Incorrect because postal mail is cheaper per contact than face-to-face interviewers.","B":"Correct selection.","C":"Incorrect because postal forms are self-completed by respondents.","D":"Incorrect because households frequently receive mailed surveys."}}},{"id":"P1_U3_MCQ_285","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_285","question":"Before finalizing the brand name, bottle shape, and TV advert storyboard for a new iced tea, a beverage firm invites target young-adult drinkers to discuss mock-ups in a moderated session. Which method is being used?","options":{"A":"Focus group","B":"Automated barcode observation","C":"National population census","D":"Internal accounting audit"},"correctOption":"A","correctAnswer":"Focus group","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because focus groups excel at pre-testing creative branding, packaging designs, and advert concepts qualitatively.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because barcode scanning tracks actual store sales rather than discussing mock-ups.","C":"Incorrect because a census counts the entire population.","D":"Incorrect because financial audits verify accounting records."}}},{"id":"P1_U3_MCQ_286","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_286","question":"During a focus group testing a new smoothie flavour, the moderator repeatedly praises the recipe, leading hesitant participants to say they love it even though they found it too sour. Which research flaw occurred?","options":{"A":"Secondary desk-research obsolescence","B":"Interviewer / moderator bias distorting participants' genuine reactions","C":"Excessive sample size reducing statistical clarity","D":"Random sampling frame inaccuracy"},"correctOption":"B","correctAnswer":"Interviewer / moderator bias distorting participants' genuine reactions","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because an unskilled or biased moderator can subtly cue participants toward desired answers, invalidating qualitative feedback.","distractor_reasons":{"A":"Incorrect because a focus group is primary research.","B":"Correct selection.","C":"Incorrect because focus groups involve small panels of 6–12 people.","D":"Incorrect because focus groups use purposive selection rather than random sampling frames."}}},{"id":"P1_U3_MCQ_287","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_287","question":"An e-commerce website uses screen-tracking software to observe where visitors move their cursors and which checkout buttons cause users to hesitate or exit. Which research method is this?","options":{"A":"Digital observation","B":"Postal survey","C":"Telephone interview","D":"External government trade report"},"correctOption":"A","correctAnswer":"Digital observation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because recording actual user navigation and clicks captures real behaviour objectively without interrupting shoppers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no mailed forms are involved.","C":"Incorrect because no phone calls are made.","D":"Incorrect because website analytics generate first-hand primary behavioural data."}}},{"id":"P1_U3_MCQ_288","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_288","question":"Why do retail researchers often pair in-store 'observation' with short exit 'questionnaires'?","options":{"A":"Observation is illegal unless paired with a written questionnaire","B":"Questionnaires are needed to calculate exact shelf heights","C":"Observation reveals what shoppers actually did in the aisle, while exit questions uncover the reasons why they made those choices","D":"Pairing them converts primary research into secondary census data"},"correctOption":"C","correctAnswer":"Observation reveals what shoppers actually did in the aisle, while exit questions uncover the reasons why they made those choices","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because observation measures objective action while brief follow-up questions explain underlying motivations.","distractor_reasons":{"A":"Incorrect because unobtrusive store observation is standard commercial practice.","B":"Incorrect because shelf dimensions are already known by store managers.","C":"Correct selection.","D":"Incorrect because both methods collect primary data."}}},{"id":"P1_U3_MCQ_289","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_289","question":"A frozen-pizza company launches a new spicy-jackfruit pizza in just 20 supermarkets in one region for eight weeks to evaluate repeat sales and adjust packaging before committing to national TV ads. What is the main benefit of this 'test marketing'?","options":{"A":"It avoids the huge financial loss of a full national launch if the product underperforms, allowing fixes first","B":"It guarantees that competitors will never find out the new pizza exists","C":"It costs zero money to produce and distribute the regional trial batch","D":"It eliminates the need to analyze supermarket scanner data"},"correctOption":"A","correctAnswer":"It avoids the huge financial loss of a full national launch if the product underperforms, allowing fixes first","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trialling on a small scale tests real purchasing under authentic store conditions while limiting downside risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because exposing the product in regional stores alerts rivals—a known risk of test marketing.","C":"Incorrect because regional production and retail listing incur real costs.","D":"Incorrect because analyzing trial store sales is the exact goal of test marketing."}}},{"id":"P1_U3_MCQ_290","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_290","question":"Which of the following is an 'internal source of secondary data' that a hotel chain can analyze to improve guest satisfaction?","options":{"A":"National tourism ministry arrival statistics","B":"Past room-occupancy records, repeat-booking histories, and guest complaint logs stored in the hotel's own system","C":"A commercial hospitality industry report purchased from a consultancy","D":"A new telephone survey of rival hotels' customers"},"correctOption":"B","correctAnswer":"Past room-occupancy records, repeat-booking histories, and guest complaint logs stored in the hotel's own system","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because existing operational records inside the business provide fast, low-cost insight into guest patterns.","distractor_reasons":{"A":"Incorrect because government tourism statistics are external secondary data.","B":"Correct selection.","C":"Incorrect because commercial consultancy reports are external secondary data.","D":"Incorrect because a new phone survey is primary research."}}},{"id":"P1_U3_MCQ_291","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_291","question":"A solar-panel installer consults national energy-ministry household statistics, local newspaper articles on electricity tariffs, and competitors' published brochures before entering a new city. Which research type is this?","options":{"A":"Primary focus-group research","B":"Primary quota street sampling","C":"External secondary (desk) research","D":"Internal company sales-ledger analysis"},"correctOption":"C","correctAnswer":"External secondary (desk) research","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because government statistics, press articles, and competitor brochures are pre-existing information published outside the business.","distractor_reasons":{"A":"Incorrect because no group discussions were conducted.","B":"Incorrect because no street interviews took place.","C":"Correct selection.","D":"Incorrect because the sources came from external organizations rather than internal files."}}},{"id":"P1_U3_MCQ_292","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_292","question":"Why do multinational corporations regularly purchase 'external secondary reports' from specialist market-research agencies?","options":{"A":"Because specialist agencies compile nationwide market-size and competitor-share data that would be too vast for one firm to gather alone","B":"Because secondary reports are always free of charge","C":"Because secondary reports test confidential prototypes before anyone else sees them","D":"Because primary research is illegal for multinational corporations"},"correctOption":"A","correctAnswer":"Because specialist agencies compile nationwide market-size and competitor-share data that would be too vast for one firm to gather alone","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because syndicated industry reports aggregate macro-market intelligence rapidly, though at a purchase fee.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because commercial research agency reports are often expensive to buy.","C":"Incorrect because testing unreleased prototypes requires private primary research.","D":"Incorrect because multinationals use both primary and secondary research."}}},{"id":"P1_U3_MCQ_293","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_293","question":"A gourmet dog-bakery reads a free government report on 'Total National Pet Care Spending' (which combines veterinary bills, dog food, birdseed, and aquarium fish). Why is this secondary data insufficient on its own?","options":{"A":"Government statistics are always mathematically fabricated","B":"The broad category combines unrelated pet expenses and fails to show specific demand or price willingness for gourmet dog treats","C":"Secondary data can never be viewed by small businesses","D":"Primary research is always cheaper than reading a free government report"},"correctOption":"B","correctAnswer":"The broad category combines unrelated pet expenses and fails to show specific demand or price willingness for gourmet dog treats","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because secondary data was compiled for wider policy purposes and lacks the granular product-specific detail needed for niche decisions.","distractor_reasons":{"A":"Incorrect because government stats are reliable at macro level, just too broad here.","B":"Correct selection.","C":"Incorrect because public reports are accessible to all businesses.","D":"Incorrect because primary research costs more than reading free public reports."}}},{"id":"P1_U3_MCQ_294","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_294","question":"A survey finds that '64% of respondents buy takeaway coffee at least three times a week' (quantitative data), while follow-up interviews reveal 'commuters feel rushed in the morning and view barista coffee as an affordable daily treat' (qualitative data). How do both data types help a café chain?","options":{"A":"Quantitative data measures the numerical scale of demand, while qualitative data explains the emotional motivations needed to craft persuasive adverts","B":"Quantitative data is collected only from focus groups, while qualitative data comes only from cash registers","C":"Quantitative data eliminates the need for qualitative insights in branding","D":"Qualitative data always proves that 100% of consumers will buy the product"},"correctOption":"A","correctAnswer":"Quantitative data measures the numerical scale of demand, while qualitative data explains the emotional motivations needed to craft persuasive adverts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because numerical demand sizing and psychological insight complement each other in marketing planning.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this reverses their typical sources.","C":"Incorrect because numbers alone do not explain why buyers behave as they do.","D":"Incorrect because qualitative data explores feelings rather than guaranteeing universal sales."}}},{"id":"P1_U3_MCQ_295","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_295","question":"An electricity utility wants an unbiased survey of its 250,000 billed account holders. It assigns every account a number and uses a random number generator to select 1,000 customers. What is the key strength of this 'random sampling'?","options":{"A":"It requires no list of customers beforehand","B":"Every customer in the population has an equal chance of selection, eliminating human selection bias","C":"Interviewers can simply pick whichever neighbours are easiest to talk to","D":"It costs less than interviewing 10 passers-by outside the office"},"correctOption":"B","correctAnswer":"Every customer in the population has an equal chance of selection, eliminating human selection bias","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when a complete sampling frame exists (such as utility billing records), pure random selection provides the most statistically unbiased sample.","distractor_reasons":{"A":"Incorrect because random sampling requires a complete sampling frame.","B":"Correct selection.","C":"Incorrect because picking convenient neighbours describes convenience sampling.","D":"Incorrect because contacting 1,000 dispersed households is costlier than a quick local convenience sample."}}},{"id":"P1_U3_MCQ_296","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_296","question":"A city's commuter population is 45% aged under 35 and 55% aged 35 or older. If a transport planner uses 'quota sampling' to interview 200 commuters, how many respondents are needed in each age group?","options":{"A":"100 under 35 and 100 aged 35+","B":"45 under 35 and 55 aged 35+","C":"90 under 35 and 110 aged 35+","D":"110 under 35 and 90 aged 35+"},"correctOption":"C","correctAnswer":"90 under 35 and 110 aged 35+","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because 45% of 200 = 90 respondents under 35, and 55% of 200 = 110 respondents aged 35+.","distractor_reasons":{"A":"Incorrect because 100/100 splits 50/50 instead of matching the 45/55 population ratio.","B":"Incorrect because 45 + 55 equals only 100 respondents rather than 200.","C":"Correct selection.","D":"Incorrect because 110/90 reverses the two age percentages."}}},{"id":"P1_U3_MCQ_297","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_297","question":"Why do commercial market-research agencies frequently use 'quota sampling' rather than 'random sampling' for high-street consumer surveys?","options":{"A":"Quota sampling requires obtaining a complete register of every citizen's home address first","B":"Quota sampling guarantees zero interviewer bias in every single interview","C":"Random sampling cannot be used with questionnaires","D":"Quota sampling is faster and cheaper when no complete population list exists, while still reflecting key demographic proportions"},"correctOption":"D","correctAnswer":"Quota sampling is faster and cheaper when no complete population list exists, while still reflecting key demographic proportions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because quota sampling avoids the time and cost of tracking down scattered individuals from a master list while preserving demographic balance.","distractor_reasons":{"A":"Incorrect because needing a full register is a requirement of random sampling.","B":"Incorrect because interviewer judgment in picking respondents can still introduce subtle bias in quota sampling.","C":"Incorrect because random sampling is widely used with questionnaires.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_298","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_298","question":"A snack company surveys 40 people at $5 per interview ($200 total) and gets rough results, whereas surveying 1,200 people across the country costs $6,000. What trade-off must the marketing manager balance when choosing 'sample size'?","options":{"A":"Larger samples produce more statistically reliable results with lower sampling error, but increase fieldwork costs and delay decision-making","B":"Smaller samples are always more accurate than larger samples","C":"Larger samples eliminate the need to write unbiased survey questions","D":"Increasing sample size reduces total survey expenditure"},"correctOption":"A","correctAnswer":"Larger samples produce more statistically reliable results with lower sampling error, but increase fieldwork costs and delay decision-making","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managers must weigh the value of higher statistical confidence against budget limits and launch deadlines.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because small samples are easily distorted by outlier views.","C":"Incorrect because biased questions ruin accuracy regardless of sample size.","D":"Incorrect because larger samples increase total collection and processing costs."}}},{"id":"P1_U3_MCQ_299","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_299","question":"An airline emails a satisfaction survey to 5,000 passengers, but only 120 passengers reply—mostly travellers whose luggage was delayed. Why would relying on these 120 replies distort management decisions?","options":{"A":"Secondary data always contradicts email surveys","B":"Non-response bias: the tiny 2.4% response rate over-represents dissatisfied passengers rather than the typical flyer experience","C":"120 respondents is larger than the airline's entire annual passenger count","D":"Email surveys are illegal in the aviation industry"},"correctOption":"B","correctAnswer":"Non-response bias: the tiny 2.4% response rate over-represents dissatisfied passengers rather than the typical flyer experience","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when very few invited people respond, self-selection skews findings toward extreme experiences.","distractor_reasons":{"A":"Incorrect because the distortion comes from low response rate rather than secondary data.","B":"Correct selection.","C":"Incorrect because 120 is a tiny fraction of 5,000 invited passengers.","D":"Incorrect because post-flight email surveys are standard practice."}}},{"id":"P1_U3_MCQ_300","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_300","question":"A marketing manager wants to show how total industry sales of $100 million are divided among four competing smartphone brands (40%, 30%, 20%, and 10%). Which visual presentation format is most effective?","options":{"A":"An unsorted list of 500 raw customer interview transcripts","B":"A continuous scatter diagram of factory temperatures","C":"A pie chart clearly displaying each brand's percentage slice of the total market","D":"A paragraph of text omitting all numerical percentages"},"correctOption":"C","correctAnswer":"A pie chart clearly displaying each brand's percentage slice of the total market","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because pie charts visually highlight each component's proportional share of a 100% total.","distractor_reasons":{"A":"Incorrect because raw transcripts obscure market share proportions.","B":"Incorrect because factory temperatures are unrelated to market share.","C":"Correct selection.","D":"Incorrect because omitting figures reduces clarity for decision-makers."}}},{"id":"P1_U3_MCQ_301","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_301","question":"After generating and screening ideas for a foldable electric bicycle, an engineering team builds a working model and tests its frame strength and battery range before regional trials. Which stage of 'new product development' is this?","options":{"A":"Maturity extension","B":"Decline harvesting","C":"Mass commercial saturation","D":"Prototype development and testing"},"correctOption":"D","correctAnswer":"Prototype development and testing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because building and testing a working prototype verifies technical safety and performance prior to test marketing or mass production.","distractor_reasons":{"A":"Incorrect because extension strategies apply to mature existing products.","B":"Incorrect because harvesting manages aging products in decline.","C":"Incorrect because saturation occurs after full market rollout.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_302","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_302","question":"Why do leading consumer-electronics companies invest billions in 'new product development (NPD)' despite the high risk that many prototypes never reach store shelves?","options":{"A":"Continuous innovation creates new revenue streams, replaces aging declining products, and maintains a competitive edge over rivals","B":"Governments fine technology firms if they sell the same product for more than six months","C":"Prototype development reduces factory fixed costs to zero","D":"New products never require any advertising or distribution support"},"correctOption":"A","correctAnswer":"Continuous innovation creates new revenue streams, replaces aging declining products, and maintains a competitive edge over rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because existing products eventually mature and decline, so a pipeline of new products sustains long-term business growth.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because market competition—not government fines—drives continuous innovation.","C":"Incorrect because R&D adds substantial fixed development outlays.","D":"Incorrect because new launches require heavy informative promotion."}}},{"id":"P1_U3_MCQ_303","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_303","question":"Chemically, bottled mineral waters from different springs taste very similar, yet one brand charges twice as much as supermarket own-label water and outsells rivals. What enables this pricing power?","options":{"A":"Supermarkets are legally forbidden from selling cheap bottled water","B":"A strong, aspirational brand image built through distinctive packaging and lifestyle promotion that differentiates the product in consumers' minds","C":"The brand pays zero bottling or transport costs","D":"Consumers cannot see price tags in grocery stores"},"correctOption":"B","correctAnswer":"A strong, aspirational brand image built through distinctive packaging and lifestyle promotion that differentiates the product in consumers' minds","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because branding creates perceived uniqueness and emotional value even when physical product differences are subtle.","distractor_reasons":{"A":"Incorrect because own-label water is widely sold alongside premium brands.","B":"Correct selection.","C":"Incorrect because bottling and shipping carry real costs.","D":"Incorrect because shoppers see prices clearly and willingly pay more for the trusted brand."}}},{"id":"P1_U3_MCQ_304","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_304","question":"A well-known kitchenware brand known for durable cast-iron pans successfully launches a new line of stainless-steel knives under the same brand name. Why does an established 'brand image' make launching new products easier?","options":{"A":"Existing customer trust transfers to the new product line, reducing perceived buyer risk and winning faster retail shelf space","B":"Established brands are exempt from product safety and labelling regulations","C":"Existing brands never need to pay for manufacturing materials","D":"Retailers must stock every new product from an established brand free of charge"},"correctOption":"A","correctAnswer":"Existing customer trust transfers to the new product line, reducing perceived buyer risk and winning faster retail shelf space","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because brand extension leverages existing reputation, lowering launch promotion barriers and encouraging trial.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because all products remain subject to consumer safety laws.","C":"Incorrect because raw materials still incur full production costs.","D":"Incorrect because retailers evaluate commercial demand before allocating shelf space."}}},{"id":"P1_U3_MCQ_305","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_305","question":"A dairy company packages fresh yogurt in sealed foil-lidded tubs packed inside rigid corrugated trays for refrigerated lorry transport. Which essential role of 'packaging' is illustrated?","options":{"A":"Preventing bacterial contamination, leaks, and crushing damage during transit and retail storage","B":"Increasing unit freight weight to raise distribution charges","C":"Hiding the expiry date from supermarket shoppers","D":"Eliminating the need for refrigerated delivery vehicles"},"correctOption":"A","correctAnswer":"Preventing bacterial contamination, leaks, and crushing damage during transit and retail storage","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because physical protection and hygiene preservation are primary functional duties of food packaging.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses aim to minimize rather than inflate freight costs.","C":"Incorrect because use-by dates must be printed clearly on packaging by law.","D":"Incorrect because fresh dairy still requires cold-chain transport."}}},{"id":"P1_U3_MCQ_306","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_306","question":"A dish-soap manufacturer introduces an upside-down squeeze bottle with a non-drip valve so cooks can dispense soap with one wet hand. How does this 'packaging' innovation add customer value?","options":{"A":"It improves everyday functional convenience and usability, creating a practical Unique Selling Point over standard bottles","B":"It reduces the chemical cleaning strength of the soap","C":"It forces supermarkets to store the bottles in locked cabinets","D":"It eliminates the need for brand logos or usage instructions"},"correctOption":"A","correctAnswer":"It improves everyday functional convenience and usability, creating a practical Unique Selling Point over standard bottles","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because user-friendly packaging design enhances product utility and differentiates a staple item on crowded shelves.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bottle design improves dispensing without weakening the soap.","C":"Incorrect because innovative packaging attracts prominent open-shelf display.","D":"Incorrect because branding and instructions remain on the bottle label."}}},{"id":"P1_U3_MCQ_307","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_307","question":"Why do cereal brands use bright colours, recognizable mascots, and bold typography on the front of boxes in supermarkets?","options":{"A":"To act as a 'silent salesperson' on crowded supermarket shelves, grabbing shopper attention and reinforcing instant brand recognition","B":"To make the cardboard box heavier for warehouse forklifts","C":"To avoid displaying mandatory ingredient and weight information","D":"To replace all television and digital advertising permanently"},"correctOption":"A","correctAnswer":"To act as a 'silent salesperson' on crowded supermarket shelves, grabbing shopper attention and reinforcing instant brand recognition","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because point-of-sale shelf impact is critical when shoppers scan dozens of competing brands in seconds.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because graphics do not affect freight weight.","C":"Incorrect because ingredient and weight tables are displayed on side/back panels.","D":"Incorrect because packaging works alongside media promotion rather than replacing it."}}},{"id":"P1_U3_MCQ_308","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_308","question":"An automotive engineering firm spends $120 million designing and crash-testing a hydrogen-powered delivery van, generating zero sales revenue during the two-year engineering phase. Which Product Life Cycle stage is this?","options":{"A":"Research and development (Development stage)","B":"Growth stage","C":"Maturity stage","D":"Saturation stage"},"correctOption":"A","correctAnswer":"Research and development (Development stage)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the development stage involves heavy capital outflow for design and testing before any commercial units are sold.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because growth features rapidly rising commercial sales.","C":"Incorrect because maturity represents peak sales and strong cash inflows.","D":"Incorrect because saturation occurs when market ownership reaches maximum levels."}}},{"id":"P1_U3_MCQ_309","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_309","question":"A new smart-garden indoor herb planter has just launched; consumer awareness is low, sales volume is modest, unit production costs are high, and heavy informative ads keep cash flow negative. Which PLC stage is it in?","options":{"A":"Introduction stage","B":"Growth stage","C":"Maturity stage","D":"Decline stage"},"correctOption":"A","correctAnswer":"Introduction stage","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because introduction combines slow initial sales, high unit costs due to low output, and substantial launch marketing expenses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because growth brings rapid sales acceleration and emerging profitability.","C":"Incorrect because maturity features peak sales and positive cash flow.","D":"Incorrect because decline involves falling demand for an established product."}}},{"id":"P1_U3_MCQ_310","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_310","question":"As a portable espresso maker moves from 'Introduction' into the 'Growth stage' of its Product Life Cycle, what typically happens to unit production costs and competitor activity?","options":{"A":"Unit costs fall as higher output unlocks economies of scale, while rival firms notice rising profits and launch competing models","B":"Unit costs triple and all competitors withdraw from the market","C":"Sales volume drops to zero and the product is discontinued","D":"Advertising stops completely because every household already owns two units"},"correctOption":"A","correctAnswer":"Unit costs fall as higher output unlocks economies of scale, while rival firms notice rising profits and launch competing models","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because surging sales volume improves production efficiency and profitability, attracting imitators into the market.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher volume lowers unit costs and attracts—rather than deters—rivals.","C":"Incorrect because falling sales and withdrawal describe the decline stage.","D":"Incorrect because persuasive promotion intensifies during growth to build brand preference."}}},{"id":"P1_U3_MCQ_311","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_311","question":"Why is the 'Maturity stage' of the Product Life Cycle often the most cash-generative phase for an established household brand despite intense competition?","options":{"A":"Initial R&D costs have already been recovered, production runs at high economies of scale, and strong sales volume generates steady cash inflows","B":"Competitors are legally banned from selling rival products during maturity","C":"Mature products never require any promotional spending or price discounts","D":"Unit manufacturing costs are higher in maturity than during initial prototype testing"},"correctOption":"A","correctAnswer":"Initial R&D costs have already been recovered, production runs at high economies of scale, and strong sales volume generates steady cash inflows","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high cumulative volume and amortized development outlays make mature 'cash cow' brands vital profit contributors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because competition is actually fiercest in maturity.","C":"Incorrect because brands spend on reminder ads and promotions to defend share.","D":"Incorrect because unit costs are lowest at peak mature scale."}}},{"id":"P1_U3_MCQ_312","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_312","question":"Sales of a traditional standalone portable MP3 music player fall by 35% per year as consumers listen to music exclusively on smartphones. Which PLC stage has the MP3 player reached?","options":{"A":"Development","B":"Introduction","C":"Growth","D":"Decline"},"correctOption":"D","correctAnswer":"Decline","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because technological substitution has caused sustained falling sales and shrinking profitability.","distractor_reasons":{"A":"Incorrect because development occurs before launch.","B":"Incorrect because introduction involves slowly rising initial sales.","C":"Incorrect because growth features rapidly increasing sales.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_313","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_313","question":"A classic laundry-soap brand whose sales have plateaued in maturity replaces its dated cardboard carton with a sleek, modern resealable pouch and refreshed logo. Which strategy is being applied?","options":{"A":"An extension strategy through packaging redesign and brand modernization","B":"Product withdrawal and liquidation","C":"Launch price skimming","D":"Product-oriented cost cutting"},"correctOption":"A","correctAnswer":"An extension strategy through packaging redesign and brand modernization","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because refreshing packaging revives shelf appeal and reminds shoppers of the brand, extending its mature life.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the brand is investing to stay on shelves rather than withdrawing.","C":"Incorrect because price skimming applies to new product introductions.","D":"Incorrect because upgrading packaging responds to modern shopper tastes."}}},{"id":"P1_U3_MCQ_314","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_314","question":"A popular potato-chip brand entering maturity introduces 'Spicy Truffle' and 'Sea Salt & Rosemary' flavours alongside single-serve multipacks. How does this 'extension strategy' boost sales?","options":{"A":"By eliminating all supermarket distribution channels","B":"By offering new variety and pack formats that re-engage existing buyers and attract new snack occasions","C":"By raising the price of plain chips by 200%","D":"By reducing factory production output to zero"},"correctOption":"B","correctAnswer":"By offering new variety and pack formats that re-engage existing buyers and attract new snack occasions","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because product variations and multipack sizes stimulate fresh trials and higher purchase frequency.","distractor_reasons":{"A":"Incorrect because new flavours rely on wide supermarket distribution.","B":"Correct selection.","C":"Incorrect because core prices remain competitive.","D":"Incorrect because new variants aim to expand total sales volume."}}},{"id":"P1_U3_MCQ_315","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_315","question":"An oat-porridge brand traditionally eaten only as a hot winter breakfast launches adverts promoting 'overnight cold summer oats' with berries. Which 'extension strategy' is this?","options":{"A":"Withdrawing the product during summer months","B":"Switching from market orientation to product orientation","C":"Promoting a new seasonal usage occasion to expand year-round demand","D":"Using loss-leader pricing below raw oat cost"},"correctOption":"C","correctAnswer":"Promoting a new seasonal usage occasion to expand year-round demand","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because educating consumers on new ways or times to consume an existing product unlocks fresh demand.","distractor_reasons":{"A":"Incorrect because the brand is boosting summer sales rather than withdrawing.","B":"Incorrect because adapting to summer refreshment preferences is market-oriented.","C":"Correct selection.","D":"Incorrect because the campaign changes product usage rather than cutting price below cost."}}},{"id":"P1_U3_MCQ_316","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_316","question":"A backpack manufacturer incurs variable costs of $18 per backpack and allocated fixed overheads of $7 per backpack. If it applies a 60% cost-plus mark-up, what is the selling price per backpack?","options":{"A":"$25.00","B":"$35.80","C":"$15.00","D":"$40.00"},"correctOption":"D","correctAnswer":"$40.00","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Total Unit Cost = $18 + $7 = $25.00; Selling Price = $25.00 + (60% of $25.00) = $25.00 + $15.00 = $40.00.","distractor_reasons":{"A":"Incorrect because $25.00 is the total unit cost before adding the 60% profit mark-up.","B":"Incorrect because $35.80 adds 60% only to the $18 variable cost ($18 + $10.80 + $7 = $35.80) rather than full unit cost.","C":"Incorrect because $15.00 is only the profit mark-up amount, not the selling price.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_317","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_317","question":"A bespoke metal-fabrication workshop quotes prices for custom staircases using 'cost-plus pricing'. Why is cost-plus pricing particularly suited to custom job production?","options":{"A":"Every custom order has unique material and labour costs, so calculating full job cost plus an agreed percentage guarantees a profit margin on each contract","B":"Custom staircases have zero material or labour costs","C":"Cost-plus pricing guarantees that the workshop always offers the cheapest price in the country","D":"Customers are legally forbidden from asking for quotes before ordering"},"correctOption":"A","correctAnswer":"Every custom order has unique material and labour costs, so calculating full job cost plus an agreed percentage guarantees a profit margin on each contract","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bespoke jobs lack standard retail market prices, making transparent cost-plus estimation practical and safe.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because custom steel and craftsmanship carry high direct costs.","C":"Incorrect because if workshop costs are high, cost-plus may produce a higher price than rivals.","D":"Incorrect because written quotes are standard before job production begins."}}},{"id":"P1_U3_MCQ_318","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_318","question":"Two rival supermarket chains sell identical branded cans of soup within one cent of each other in every town. Which pricing strategy are they using?","options":{"A":"Price skimming","B":"Competitive pricing","C":"Penetration launch pricing","D":"Prestige luxury pricing"},"correctOption":"B","correctAnswer":"Competitive pricing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when products are identical and shoppers compare prices easily, firms set prices closely aligned with competitors.","distractor_reasons":{"A":"Incorrect because price skimming applies to innovative new launches.","B":"Correct selection.","C":"Incorrect because penetration pricing sets a low introductory price for a new market entrant.","D":"Incorrect because canned soup is an everyday staple rather than a prestige luxury."}}},{"id":"P1_U3_MCQ_319","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_319","question":"A new sports-drink brand enters a market dominated by two global giants by pricing its bottles at $0.99—half the rivals' $1.99 price—for its first six months to persuade shoppers to switch. Which strategy is this?","options":{"A":"Price skimming","B":"Cost-plus luxury pricing","C":"Penetration pricing","D":"Dynamic surge pricing"},"correctOption":"C","correctAnswer":"Penetration pricing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because penetration pricing sets a low initial price to overcome brand loyalty to incumbents and capture rapid market share.","distractor_reasons":{"A":"Incorrect because price skimming sets a high initial price.","B":"Incorrect because $0.99 is an aggressive low-margin entry price.","C":"Correct selection.","D":"Incorrect because dynamic pricing adjusts prices automatically in real time with demand."}}},{"id":"P1_U3_MCQ_320","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_320","question":"A tech company launches the world's first lightweight augmented-reality smart glasses at $1,499, targeting enthusiastic early adopters before lowering the price to $899 eighteen months later. Which condition makes this 'price skimming' successful?","options":{"A":"Dozens of identical cheap copies are already sold in discount stores","B":"The product has zero innovative features or patent protection","C":"Consumers are highly price sensitive and refuse to spend over $100","D":"Strong technological uniqueness and patent protection mean early adopters have price-inelastic demand and gladly pay a premium to own it first"},"correctOption":"D","correctAnswer":"Strong technological uniqueness and patent protection mean early adopters have price-inelastic demand and gladly pay a premium to own it first","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because price skimming requires genuine innovation and lack of immediate substitutes so early buyers pay high margins.","distractor_reasons":{"A":"Incorrect because close substitutes prevent skimming.","B":"Incorrect because skimming depends on breakthrough differentiation.","C":"Incorrect because skimming targets price-insensitive early adopters first.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_321","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_321","question":"A garden centre offers 'Buy One Bag of Potting Soil, Get One Free' during a quiet rainy weekend in autumn to clear warehouse space. Which pricing method is being used?","options":{"A":"Promotional pricing","B":"Price skimming","C":"Penetration launch pricing","D":"Prestige psychological pricing"},"correctOption":"A","correctAnswer":"Promotional pricing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because temporary multi-buy discounts stimulate immediate off-peak sales and clear excess inventory.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because skimming sets high launch prices for innovations.","C":"Incorrect because penetration pricing introduces a brand-new product to the market.","D":"Incorrect because BOGOF signals bargain clearance rather than prestige."}}},{"id":"P1_U3_MCQ_322","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_322","question":"How does 'dynamic pricing' used by online hotels and airlines differ from 'psychological pricing' used by retail stores?","options":{"A":"Dynamic pricing adjusts prices continuously in real time based on live demand and remaining capacity, whereas psychological pricing sets specific price numbers (like $19.99) to influence buyer perception","B":"Dynamic pricing keeps prices fixed for ten years, whereas psychological pricing changes every five seconds","C":"Dynamic pricing is illegal in e-commerce, whereas psychological pricing is mandatory","D":"Dynamic pricing is used only for agricultural commodities, whereas psychological pricing is used only for airline tickets"},"correctOption":"A","correctAnswer":"Dynamic pricing adjusts prices continuously in real time based on live demand and remaining capacity, whereas psychological pricing sets specific price numbers (like $19.99) to influence buyer perception","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dynamic pricing responds algorithmically to supply-demand fluctuations, while psychological pricing targets consumer mental framing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this reverses the two concepts.","C":"Incorrect because both pricing strategies are lawful when transparent.","D":"Incorrect because airlines use dynamic pricing extensively while retailers use charm pricing."}}},{"id":"P1_U3_MCQ_323","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_323","question":"When a cinema chain cuts weekday ticket prices by 20% (from $15 to $12), ticket sales jump by 50% (from 400 to 600 tickets). What is the Price Elasticity of Demand (PED), and is demand elastic or inelastic?","options":{"A":"PED = 0.4 (price inelastic)","B":"PED = 2.5 (price elastic)","C":"PED = 1.0 (unitary elastic)","D":"PED = 30.0 (perfectly inelastic)"},"correctOption":"B","correctAnswer":"PED = 2.5 (price elastic)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because PED = % Change in Quantity Demanded / % Change in Price = 50% / 20% = 2.5; since 2.5 > 1, demand is price elastic.","distractor_reasons":{"A":"Incorrect because 0.4 divides 20% by 50% (inverting the PED formula).","B":"Correct selection.","C":"Incorrect because unitary elasticity occurs when %ΔQd equals %ΔP.","D":"Incorrect because 30.0 subtracts 20% from 50% instead of dividing."}}},{"id":"P1_U3_MCQ_324","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_324","question":"A patented insulin-pump manufacturer raises cartridge prices by 12%, and unit sales decrease by only 1% because diabetic patients rely on the device daily with no close substitute. What happens to total revenue?","options":{"A":"Total sales revenue falls by 12%","B":"Total sales revenue drops to zero","C":"Total sales revenue increases because demand is highly price inelastic","D":"Demand becomes completely price elastic"},"correctOption":"C","correctAnswer":"Total sales revenue increases because demand is highly price inelastic","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because for essential medical items with inelastic demand, the 12% higher price per unit easily outweighs the 1% drop in volume.","distractor_reasons":{"A":"Incorrect because quantity fell by only 1% while price rose by 12%.","B":"Incorrect because 99% of orders continue at the higher price.","C":"Correct selection.","D":"Incorrect because a 1% response to a 12% price change confirms strong inelasticity (PED ≈ 0.08)."}}},{"id":"P1_U3_MCQ_325","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_325","question":"Why is consumer demand for luxury overseas cruises much more 'price elastic' than demand for everyday table salt?","options":{"A":"Table salt costs more per packet than a luxury cruise","B":"Luxury cruises have zero competing holiday options","C":"Table salt is a luxury good bought only once every five years","D":"Cruises take up a large share of household income and can easily be postponed, whereas salt is a low-cost daily necessity with few substitutes"},"correctOption":"D","correctAnswer":"Cruises take up a large share of household income and can easily be postponed, whereas salt is a low-cost daily necessity with few substitutes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because big-ticket discretionary luxuries trigger strong price sensitivity, while tiny-budget necessities are bought regardless of small price changes.","distractor_reasons":{"A":"Incorrect because table salt costs very little compared with luxury travel.","B":"Incorrect because cruises compete with resorts, flights, and other leisure spending.","C":"Incorrect because salt is a basic household staple.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_326","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_326","question":"What is the primary objective of the 'Place' element within a business's marketing mix?","options":{"A":"Ensuring products are available to target customers at convenient locations, in the right quantities, and at the right time","B":"Designing the chemical formula and packaging colours of the product","C":"Calculating cost-plus mark-up percentages for the finance team","D":"Writing humorous scripts for television commercials"},"correctOption":"A","correctAnswer":"Ensuring products are available to target customers at convenient locations, in the right quantities, and at the right time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Place governs distribution channels, logistics, and retail availability so buyers can actually purchase the product.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because product design and packaging belong to Product.","C":"Incorrect because mark-up calculation belongs to Price.","D":"Incorrect because advert scripts belong to Promotion."}}},{"id":"P1_U3_MCQ_327","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_327","question":"A mattress startup sells mattresses exclusively via its own website and ships boxed mattresses directly from its factory to customers' homes. What is a disadvantage of this 'direct distribution channel' compared with selling through furniture stores?","options":{"A":"The startup must share 50% of its retail margin with wholesale middlemen","B":"Shoppers cannot physically lie down and test mattress firmness in local stores before buying, and the startup bears all individual delivery and return logistics","C":"The startup has zero access to customer email addresses or feedback","D":"Selling direct online is legally prohibited for bulky household furniture"},"correctOption":"B","correctAnswer":"Shoppers cannot physically lie down and test mattress firmness in local stores before buying, and the startup bears all individual delivery and return logistics","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cutting out retail showrooms removes physical product inspection and shifts storage, single-item shipping, and return handling onto the producer.","distractor_reasons":{"A":"Incorrect because direct selling avoids sharing margins with wholesalers.","B":"Correct selection.","C":"Incorrect because direct e-commerce gives the brand full ownership of customer data.","D":"Incorrect because direct-to-consumer online mattress sales are completely lawful."}}},{"id":"P1_U3_MCQ_328","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_328","question":"A consumer-electronics brand sells its laptops directly to major national retail chains (Producer -> Retailer -> Consumer) without using a wholesaler. Why does this two-tier channel work well?","options":{"A":"Large retail chains buy in full truckloads for their own distribution centres, saving the wholesaler's margin while giving the brand nationwide store displays","B":"National retail chains manufacture the laptops inside their shops","C":"Retailers pay zero money for the laptops until five years after selling them","D":"Using retailers eliminates all competition from rival laptop brands"},"correctOption":"A","correctAnswer":"Large retail chains buy in full truckloads for their own distribution centres, saving the wholesaler's margin while giving the brand nationwide store displays","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because large retailers have sufficient scale to buy directly in bulk from manufacturers while providing wide consumer reach.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retailers distribute finished goods rather than manufacturing them.","C":"Incorrect because standard trade credit terms apply (e.g., 30–60 days).","D":"Incorrect because retail stores display multiple rival laptop brands side-by-side."}}},{"id":"P1_U3_MCQ_329","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_329","question":"A small family-owned convenience store needs 20 different brands of snacks, drinks, and cleaning supplies each week, but only has storage space for two cases of each item. Which intermediary is essential to supply this store efficiently?","options":{"A":"An overseas export sales agent","B":"A national television advertising agency","C":"A consumer focus group moderator","D":"A wholesaler who buys bulk pallets from dozens of manufacturers and 'breaks bulk' into small mixed orders for independent shops"},"correctOption":"D","correctAnswer":"A wholesaler who buys bulk pallets from dozens of manufacturers and 'breaks bulk' into small mixed orders for independent shops","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because wholesalers aggregate products from many producers and supply small retailers in manageable quantities.","distractor_reasons":{"A":"Incorrect because export agents arrange international sales rather than domestic grocery wholesaling.","B":"Incorrect because ad agencies create promotional campaigns rather than distributing stock.","C":"Incorrect because focus groups conduct market research.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_330","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_330","question":"An Italian luxury olive-oil producer appoints an 'agent' in South Korea to pitch its oils to Seoul department stores and restaurants. What distinguishes this 'agent' from a 'wholesaler'?","options":{"A":"The agent never takes legal ownership of the olive oil and earns a commission on orders arranged, whereas a wholesaler buys stock outright to resell","B":"The agent owns all the olive groves in Italy and bottles the oil","C":"The agent sells exclusively to individual walk-in shoppers from a market stall","D":"The agent pays the producer a fixed salary regardless of whether any orders are won"},"correctOption":"A","correctAnswer":"The agent never takes legal ownership of the olive oil and earns a commission on orders arranged, whereas a wholesaler buys stock outright to resell","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because agents act as commissioned commercial intermediaries connecting exporters with foreign buyers without holding inventory ownership.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the Italian producer owns the production assets.","C":"Incorrect because agents negotiate B2B trade orders with department stores and restaurants.","D":"Incorrect because independent agents work on commission rather than salaried employment."}}},{"id":"P1_U3_MCQ_331","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_331","question":"A bakery produces fresh artisan sourdough bread daily that tastes best within 24 hours. Why must it avoid a long distribution channel involving regional wholesalers?","options":{"A":"Wholesalers are legally banned from handling bread products","B":"Bread is a luxury prestige item sold only in airport boutiques","C":"Multi-stage wholesale storage adds transit delays that would leave bread stale before reaching consumers","D":"Wholesalers always sell bread below raw flour cost"},"correctOption":"C","correctAnswer":"Multi-stage wholesale storage adds transit delays that would leave bread stale before reaching consumers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because highly perishable foods require short, rapid distribution channels (direct to consumer or direct to local retailers).","distractor_reasons":{"A":"Incorrect because wholesalers handle packaged long-life baked goods, just not 24-hour fresh artisan loaves.","B":"Incorrect because bread is an everyday staple.","C":"Correct selection.","D":"Incorrect because wholesalers add a profit mark-up."}}},{"id":"P1_U3_MCQ_332","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_332","question":"Why does a Swiss luxury fountain-pen maker distribute its $900 pens exclusively through 40 prestigious flagship boutiques worldwide rather than thousands of supermarket stationery aisles?","options":{"A":"Supermarkets refuse to sell any writing instruments","B":"Exclusive distribution protects prestige brand image, ensures knowledgeable personal service, and aligns Place with luxury Product and Price","C":"Fountain pens are perishable items that spoil within 48 hours","D":"Exclusive distribution eliminates all manufacturing costs"},"correctOption":"B","correctAnswer":"Exclusive distribution protects prestige brand image, ensures knowledgeable personal service, and aligns Place with luxury Product and Price","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high-involvement luxury goods require upscale retail settings that reinforce exclusivity and offer expert consultation.","distractor_reasons":{"A":"Incorrect because supermarkets sell everyday ballpoint pens.","B":"Correct selection.","C":"Incorrect because fountain pens are durable goods.","D":"Incorrect because precision craftsmanship still incurs high production costs."}}},{"id":"P1_U3_MCQ_333","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_333","question":"A small pottery studio in rural Wales launches an 'e-commerce' online shop. What is a major commercial benefit of e-commerce for this small business?","options":{"A":"It can sell handmade ceramics to customers across the world 24 hours a day without renting expensive city-centre retail shops","B":"It eliminates all parcel postage, packaging, and payment-processing fees","C":"It guarantees that no other pottery studio can sell online","D":"Customers never return fragile ceramic items shipped by courier"},"correctOption":"A","correctAnswer":"It can sell handmade ceramics to customers across the world 24 hours a day without renting expensive city-centre retail shops","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because e-commerce removes geographic location barriers and lowers fixed retail property overheads.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shipping, protective packaging, and card fees remain real expenses.","C":"Incorrect because online marketplaces are open to global rivals.","D":"Incorrect because fragile transit breakages and returns remain operational risks."}}},{"id":"P1_U3_MCQ_334","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_334","question":"What is a significant disadvantage for an electronics retailer operating in a highly transparent 'e-commerce' market?","options":{"A":"Shoppers can compare identical model prices across dozens of websites in seconds, intensifying price competition and squeezing retail profit margins","B":"Online stores can only display products to customers living within 5 kilometres","C":"E-commerce websites are legally forbidden from running promotional discounts","D":"Online buyers cannot read customer reviews before purchasing"},"correctOption":"A","correctAnswer":"Shoppers can compare identical model prices across dozens of websites in seconds, intensifying price competition and squeezing retail profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because price-comparison engines reduce search costs for consumers, making price elasticity higher for standardized goods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because e-commerce reaches nationwide and international buyers.","C":"Incorrect because online flash sales and discount codes are widespread.","D":"Incorrect because customer reviews are a central feature of online retail."}}},{"id":"P1_U3_MCQ_335","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_335","question":"How has the rise of 'e-commerce' changed consumer purchasing behaviour for everyday household goods?","options":{"A":"Consumers can order anytime from mobile phones with home delivery or click-and-collect, though they must wait for delivery and cannot physically inspect items beforehand","B":"Consumers are forced to pay higher prices online than in physical shops for every item","C":"Consumers can no longer return faulty goods bought over the internet","D":"Physical supermarkets have completely disappeared from every city"},"correctOption":"A","correctAnswer":"Consumers can order anytime from mobile phones with home delivery or click-and-collect, though they must wait for delivery and cannot physically inspect items beforehand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because e-commerce trades immediate physical possession and tactile inspection for 24/7 convenience and broad choice.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because online prices are often lower due to lower store overheads.","C":"Incorrect because consumer protection laws grant strong distance-selling return rights.","D":"Incorrect because physical stores continue to thrive alongside online channels."}}},{"id":"P1_U3_MCQ_336","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_336","question":"A newly opened dental clinic distributes leaflets explaining its modern painless laser treatments and weekend opening hours to local residents. Which primary aim of 'promotion' is being pursued?","options":{"A":"Raising local awareness and informing potential patients about new services available","B":"Reducing fixed clinic rent and dental equipment depreciation","C":"Harvesting cash flow from a dying product in the decline stage","D":"Conducting random census sampling of national tooth-brushing habits"},"correctOption":"A","correctAnswer":"Raising local awareness and informing potential patients about new services available","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because new businesses must first make target local consumers aware of their existence and service benefits.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because promotion incurs marketing spend rather than cutting fixed property rent.","C":"Incorrect because the clinic is newly launched rather than declining.","D":"Incorrect because promotional leaflets communicate information rather than collecting survey data."}}},{"id":"P1_U3_MCQ_337","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_337","question":"How does 'above-the-line promotion' differ from 'below-the-line promotion'?","options":{"A":"Above-the-line uses paid mass-media advertising (TV, radio, press, online display ads) where the firm pays media owners for space, whereas below-the-line uses direct non-mass-media incentives (coupons, PR, personal selling, POS displays) controlled directly by the business","B":"Above-the-line promotion is always completely free, whereas below-the-line costs millions","C":"Above-the-line targets only factory workers, whereas below-the-line targets only foreign governments","D":"Above-the-line is illegal for consumer brands, whereas below-the-line is mandatory"},"correctOption":"A","correctAnswer":"Above-the-line uses paid mass-media advertising (TV, radio, press, online display ads) where the firm pays media owners for space, whereas below-the-line uses direct non-mass-media incentives (coupons, PR, personal selling, POS displays) controlled directly by the business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the distinction separates paid third-party media advertising from direct promotional tactics like sales promotions and PR.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because paid mass-media advertising is typically very expensive.","C":"Incorrect because both target external buyers and stakeholders.","D":"Incorrect because both are standard, lawful components of the promotional mix."}}},{"id":"P1_U3_MCQ_338","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_338","question":"A city council launches a new high-speed tram line and publishes posters showing exact station maps, ticket fares, and departure frequencies. Why is 'informative advertising' more suitable than 'persuasive image advertising' here?","options":{"A":"Commuters need clear practical facts to understand how to use a brand-new transport service","B":"Informative posters are legally required to omit ticket prices","C":"Persuasive advertising is banned in all transport industries","D":"Commuters never look at station maps before boarding trains"},"correctOption":"A","correctAnswer":"Commuters need clear practical facts to understand how to use a brand-new transport service","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because unfamiliar services and public utilities succeed when potential users receive clear factual guidance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because transparent fare details are helpful and lawful.","C":"Incorrect because airlines and rail firms regularly use persuasive travel adverts.","D":"Incorrect because route maps directly assist passenger adoption."}}},{"id":"P1_U3_MCQ_339","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_339","question":"A manufacturer of specialized laboratory microscopes wants to promote its latest model to university biology professors and hospital lab directors. Which advertising medium is most cost-effective?","options":{"A":"Specialist scientific and medical trade journals read directly by laboratory decision-makers","B":"Billboards outside children's amusement parks","C":"Commercials during prime-time pop-music talent shows","D":"Flyers handed out at suburban shopping malls"},"correctOption":"A","correctAnswer":"Specialist scientific and medical trade journals read directly by laboratory decision-makers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because specialist trade publications reach a concentrated niche of professional buyers with minimal wasted ad spend.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because amusement-park visitors are not laboratory equipment buyers.","C":"Incorrect because mass TV entertainment wastes huge budget on non-buyers.","D":"Incorrect because general mall shoppers do not purchase hospital microscopes."}}},{"id":"P1_U3_MCQ_340","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_340","question":"Why do small online retailers favour 'pay-per-click (PPC) search engine and social media advertising' over traditional print newspaper adverts?","options":{"A":"Advertisers pay only when interested users actually click the ad, can target exact keywords or demographics, and can track exact return on investment","B":"Search engine ads are always 100% free regardless of how many clicks occur","C":"Print newspapers have zero readers anywhere in the world","D":"Digital ads guarantee that every click converts into a $1,000 purchase"},"correctOption":"A","correctAnswer":"Advertisers pay only when interested users actually click the ad, can target exact keywords or demographics, and can track exact return on investment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because digital performance advertising offers precise intent targeting, flexible small budgets, and real-time conversion analytics.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because PPC advertisers pay per click according to auction bids.","C":"Incorrect because newspapers still serve specific older or local audiences.","D":"Incorrect because clicks bring website traffic, though conversion still depends on product and price."}}},{"id":"P1_U3_MCQ_341","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_341","question":"A coffee-shop chain issues stamped 'Buy 9 Coffees, Get the 10th Free' cards to commuters. Which type of promotional tool is this?","options":{"A":"Sales promotion (customer loyalty incentive)","B":"Public relations press release","C":"Above-the-line television advertising","D":"Personal B2B consultative selling"},"correctOption":"A","correctAnswer":"Sales promotion (customer loyalty incentive)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because loyalty stamp cards reward repeat purchases with a tangible short-term product incentive.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because PR seeks unpaid media coverage rather than issuing customer reward cards.","C":"Incorrect because stamp cards are a below-the-line point-of-sale promotion.","D":"Incorrect because personal selling involves one-to-one sales pitches."}}},{"id":"P1_U3_MCQ_342","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_342","question":"A shampoo brand offers '25% Extra Free' bonus bottles in supermarkets for one month. What is a likely financial drawback if the brand runs bonus-pack promotions continuously?","options":{"A":"Higher packaging and ingredient costs per unit reduce profit margins, and shoppers refuse to buy standard-sized bottles at regular prices","B":"Supermarkets refuse to display bonus packs on shelves","C":"Giving extra shampoo for free lowers factory raw-material consumption","D":"Competitors are legally prohibited from offering competing promotions"},"correctOption":"A","correctAnswer":"Higher packaging and ingredient costs per unit reduce profit margins, and shoppers refuse to buy standard-sized bottles at regular prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because giving away 25% more product at the same price compresses unit profit margin unless it builds lasting brand loyalty.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supermarkets welcome popular promotional packs.","C":"Incorrect because larger fill volumes increase raw-material usage.","D":"Incorrect because rivals frequently match promotions."}}},{"id":"P1_U3_MCQ_343","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_343","question":"A technology company hosts an environmental summit showcasing how its factories run on 100% solar power, attracting positive articles from national business journalists. Why do consumers often trust this 'Public Relations (PR)' coverage more than paid adverts?","options":{"A":"Independent journalists write editorial news stories rather than the company buying ad space to praise itself","B":"Companies pay journalists directly to print word-for-word advertising scripts disguised as news","C":"PR articles are legally forbidden from mentioning the company's name","D":"Paid advertisements are illegal in business newspapers"},"correctOption":"A","correctAnswer":"Independent journalists write editorial news stories rather than the company buying ad space to praise itself","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because third-party editorial endorsement carries higher perceived objectivity and credibility than self-funded commercials.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because genuine PR earns unpaid editorial coverage rather than bribing journalists.","C":"Incorrect because positive brand mention is the goal of PR.","D":"Incorrect because paid display ads are completely lawful."}}},{"id":"P1_U3_MCQ_344","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_344","question":"A custom yacht builder employs experienced marine sales consultants to meet wealthy clients at boat shows, configure interior layouts, and negotiate $2 million build contracts. Why is 'personal selling' vital here?","options":{"A":"High-value, bespoke purchases require one-to-one trust, tailored technical advice, and flexible contract negotiation","B":"Personal selling is the lowest-cost way to reach 50 million everyday shoppers","C":"Yachts are impulse purchases bought at supermarket checkouts","D":"Personal selling eliminates the need to build seaworthy yachts"},"correctOption":"A","correctAnswer":"High-value, bespoke purchases require one-to-one trust, tailored technical advice, and flexible contract negotiation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because complex, high-ticket items involve detailed buyer questions and customized terms that only human interaction can resolve.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because personal selling has a very high cost per contact.","C":"Incorrect because luxury yachts are major capital purchases.","D":"Incorrect because product engineering excellence remains paramount."}}},{"id":"P1_U3_MCQ_345","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_345","question":"An airline sends tailored SMS and email alerts offering discounted business-class seat upgrades to frequent flyers 24 hours before departure. What is a potential drawback of 'direct marketing' if overused?","options":{"A":"Sending too many messages annoys customers as 'spam', causing them to unsubscribe or view the brand negatively","B":"Direct emails cost $50 per message to send","C":"Direct marketing cannot be personalized with the customer's name or flight details","D":"Airlines are legally forbidden from emailing loyalty-club members"},"correctOption":"A","correctAnswer":"Sending too many messages annoys customers as 'spam', causing them to unsubscribe or view the brand negatively","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because excessive direct messaging creates inbox fatigue and opt-outs if frequency is not managed carefully.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because digital messaging has a tiny marginal cost per send.","C":"Incorrect because personalization is direct marketing's core strength.","D":"Incorrect because opted-in loyalty members can lawfully receive offers."}}},{"id":"P1_U3_MCQ_346","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_346","question":"A toy manufacturer forecasts annual revenue of $1,800,000 and sets its marketing budget at 5% of forecasted sales. If 40% of the marketing budget is allocated to digital video ads, how much is spent on digital video ads?","options":{"A":"$90,000","B":"$36,000","C":"$72,000","D":"$54,000"},"correctOption":"B","correctAnswer":"$36,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Total Marketing Budget = 5% of $1,800,000 = $90,000; Digital Video Spend = 40% of $90,000 = $36,000.","distractor_reasons":{"A":"Incorrect because $90,000 is the entire annual marketing budget before taking 40% for digital video.","B":"Correct selection.","C":"Incorrect because $72,000 is 4% of $1,800,000 (or 80% of the budget).","D":"Incorrect because $54,000 is the remaining 60% of the budget."}}},{"id":"P1_U3_MCQ_347","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_347","question":"What is a major weakness of setting a company's annual 'marketing budget' strictly as a fixed percentage (e.g., 5%) of last year's actual sales revenue?","options":{"A":"If sales fell last year, the budget automatically shrinks when the business actually needs more promotion to revive demand","B":"It is mathematically impossible to calculate 5% of annual sales revenue","C":"Accounting laws forbid businesses from linking marketing budgets to sales figures","D":"A percentage-of-sales budget guarantees that every advert produces a 500% profit"},"correctOption":"A","correctAnswer":"If sales fell last year, the budget automatically shrinks when the business actually needs more promotion to revive demand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tying budgets mechanically to past sales treats promotion as a result of sales rather than a driver of future sales.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because percentage-of-sales is simple to compute, which is why firms often use it despite its strategic flaw.","C":"Incorrect because internal budgeting methods are management decisions.","D":"Incorrect because budget size alone does not guarantee creative effectiveness."}}},{"id":"P1_U3_MCQ_348","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_348","question":"A restaurant chain spends $20,000 on local social media ads featuring a unique promo code 'DINE20', which generates $85,000 in tracked food orders with a 50% gross profit margin ($42,500 gross profit). How does tracking promo codes improve marketing decisions?","options":{"A":"It proves precisely that the campaign generated $22,500 net contribution above ad spend, justifying future digital investment","B":"It eliminates the need to pay chefs or buy food ingredients","C":"It prevents customers from visiting the restaurant without a smartphone","D":"It converts promotional expenses into fixed factory assets"},"correctOption":"A","correctAnswer":"It proves precisely that the campaign generated $22,500 net contribution above ad spend, justifying future digital investment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because traceable codes measure exact return on marketing investment ($42,500 gross profit minus $20,000 ad cost = +$22,500) rather than guessing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because food and kitchen labour costs still apply.","C":"Incorrect because walk-in diners are still welcome.","D":"Incorrect because advertising remains an operating expense."}}},{"id":"P1_U3_MCQ_349","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_349","question":"A supermarket introduces 'click-and-collect' lockers in its car parks and QR codes on shelf labels that unlock recipe videos and instant digital coupons on shoppers' phones. How does this technology integrate 'Place' and 'Promotion'?","options":{"A":"It blends digital convenience and interactive point-of-sale offers directly into the physical shopping experience","B":"It eliminates the need to keep food shelves stocked","C":"It forces shoppers to pay twice for every grocery item scanned","D":"It prevents customers from comparing unit prices per kilogram"},"correctOption":"A","correctAnswer":"It blends digital convenience and interactive point-of-sale offers directly into the physical shopping experience","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mobile-enabled retail connects physical fulfilment convenience with real-time digital engagement.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because stocked inventory remains essential for both store and click-and-collect orders.","C":"Incorrect because QR coupons provide discounts rather than double-charging.","D":"Incorrect because unit pricing remains clearly displayed."}}},{"id":"P1_U3_MCQ_350","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_350","question":"An indie video-game studio launches a multiplayer PC game priced at $19.99, distributing it digitally via Steam and promoting it through live gaming streamers on Twitch and YouTube. Why are 'Place' and 'Promotion' well aligned here?","options":{"A":"Both digital distribution and gaming-stream promotion meet PC gamers directly on the online platforms where they already watch, socialize, and download games","B":"Printed newspaper adverts and physical DVD boxes are the only ways PC gamers buy games","C":"Digital downloads incur high international shipping container tariffs","D":"Twitch streamers are legally required to promote every new game for free"},"correctOption":"A","correctAnswer":"Both digital distribution and gaming-stream promotion meet PC gamers directly on the online platforms where they already watch, socialize, and download games","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because matching digital delivery channels with interactive creator streams removes friction between seeing gameplay and instant purchase.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because PC gaming has shifted overwhelmingly to digital downloads.","C":"Incorrect because digital software distribution has zero physical shipping containers.","D":"Incorrect because sponsored streams are commercial promotional agreements."}}},{"id":"P1_U3_MCQ_351","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_351","question":"What best defines a business's 'marketing strategy'?","options":{"A":"A long-term plan that uses market research to select target segments and coordinates Product, Price, Place, and Promotion to achieve marketing objectives","B":"A daily timetable showing when factory cleaners mop the warehouse floor","C":"A single one-day price discount offered without checking costs or competitors","D":"A legal contract hiring a new human resources manager"},"correctOption":"A","correctAnswer":"A long-term plan that uses market research to select target segments and coordinates Product, Price, Place, and Promotion to achieve marketing objectives","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a marketing strategy integrates customer targeting with a consistent, goal-driven 4Ps marketing mix.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cleaning schedules are routine operational housekeeping.","C":"Incorrect because an isolated ad-hoc discount is a short-term tactic rather than a strategy.","D":"Incorrect because recruitment contracts belong to Human Resources."}}},{"id":"P1_U3_MCQ_352","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_352","question":"An artisan cashmere-coat brand targets affluent fashion buyers. Which coordinated marketing mix justifies a $1,800 retail price?","options":{"A":"100% pure Scottish cashmere with hand-finished tailoring (Product), prestige pricing (Price), flagship city boutiques and white-glove online delivery (Place), and glossy fashion-magazine editorials (Promotion)","B":"Synthetic polyester blends (Product), prestige pricing (Price), discount warehouse bins (Place), and local bus-stop flyers (Promotion)","C":"100% pure cashmere (Product), $15 clearance pricing (Price), supermarket checkout racks (Place), and coupon leaflets (Promotion)","D":"Unlabelled coats (Product), cost-plus pricing (Price), wholesale cash-and-carry depots (Place), and zero promotion"},"correctOption":"A","correctAnswer":"100% pure Scottish cashmere with hand-finished tailoring (Product), prestige pricing (Price), flagship city boutiques and white-glove online delivery (Place), and glossy fashion-magazine editorials (Promotion)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because superior craftsmanship, exclusive retail settings, and prestigious editorial promotion reinforce the $1,800 price positioning.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because synthetic fabric and discount bins destroy credibility for an $1,800 coat.","C":"Incorrect because $15 pricing and supermarket racks lose money and ruin luxury image.","D":"Incorrect because unlabelled wholesale coats fail to build luxury brand equity."}}},{"id":"P1_U3_MCQ_353","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_353","question":"A new bottled-water brand targets everyday commuters seeking affordable hydration. Which marketing mix is most coherent and commercially viable?","options":{"A":"Recyclable ergonomic 500ml bottles (Product), competitive $1.00 pricing (Price), intensive distribution across supermarkets, train kiosks, and vending machines (Place), and commuter billboard/social ads (Promotion)","B":"Heavy crystal decanters (Product), $95 price skimming (Price), appointment-only jewellery stores (Place), and personal door-to-door sales advisors (Promotion)","C":"Unlabelled plastic jugs (Product), $25 pricing (Price), sold solely from one rural farm gate (Place), and scientific journal ads (Promotion)","D":"500ml bottles (Product), $0.05 loss-leader pricing permanently (Price), sold only via postal mail order (Place), and zero promotion"},"correctOption":"A","correctAnswer":"Recyclable ergonomic 500ml bottles (Product), competitive $1.00 pricing (Price), intensive distribution across supermarkets, train kiosks, and vending machines (Place), and commuter billboard/social ads (Promotion)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because everyday convenience products require competitive pricing, maximum retail accessibility, and high-visibility commuter promotion.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $95 crystal decanters in jewellery shops do not serve everyday commuters.","C":"Incorrect because $25 unlabelled jugs at a single rural farm gate cannot reach urban commuters.","D":"Incorrect because permanent $0.05 pricing causes massive losses and postal delivery is impractical for single bottles."}}},{"id":"P1_U3_MCQ_354","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_354","question":"When a cordless drill brand moves from 'Introduction' into 'Growth' and 'Maturity', why must it widen its 'Place' strategy from specialist tool shops to major hardware superstores and online marketplaces?","options":{"A":"To reach mainstream DIY buyers nationwide and achieve the high sales volumes needed for manufacturing economies of scale","B":"Because specialist tool shops are legally required to close after six months","C":"Because hardware superstores charge zero retail margin on power tools","D":"To reduce consumer awareness of the drill brand"},"correctOption":"A","correctAnswer":"To reach mainstream DIY buyers nationwide and achieve the high sales volumes needed for manufacturing economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because early adopters visit specialist outlets at introduction, whereas mainstream growth and maturity require broad retail availability.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because specialist tool shops remain open, just serving a smaller segment.","C":"Incorrect because superstores negotiate wholesale discounts for their retail margin.","D":"Incorrect because wider shelf presence increases brand visibility."}}},{"id":"P1_U3_MCQ_355","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_355","question":"A rival smartwatch brand launches a model with 10-day battery life, causing an established smartwatch company's sales to dip. Which strategic marketing response addresses the root competitive threat?","options":{"A":"Invest in R&D to upgrade battery efficiency while running persuasive campaigns highlighting superior health sensors and app ecosystem integration","B":"Pretend the rival watch does not exist and cut R&D spending to zero","C":"Raise watch prices by 50% without improving battery life","D":"Switch from online and retail sales to postal mail-order catalogues only"},"correctOption":"A","correctAnswer":"Invest in R&D to upgrade battery efficiency while running persuasive campaigns highlighting superior health sensors and app ecosystem integration","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because matching or leapfrogging rival product performance while emphasizing existing strengths defends market share effectively.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ignoring superior competitor features accelerates share loss.","C":"Incorrect because raising prices on an inferior battery model drives buyers away.","D":"Incorrect because restricting distribution does not solve the product feature gap."}}},{"id":"P1_U3_MCQ_356","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_356","question":"How does rapid growth in smartphone mobile commerce ('m-commerce') require a clothing retailer to adapt its marketing strategy?","options":{"A":"Optimize mobile-friendly checkout apps, offer one-tap digital wallet payments, and run short vertical video ads with direct shoppable links","B":"Remove all product photos from its website to save mobile data","C":"Disable smartphone access to its online store so shoppers must use desktop computers","D":"Stop accepting digital payments and accept only paper cheques by post"},"correctOption":"A","correctAnswer":"Optimize mobile-friendly checkout apps, offer one-tap digital wallet payments, and run short vertical video ads with direct shoppable links","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because aligning digital promotion and seamless mobile checkout with how consumers browse on phones boosts conversion rates.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because clear visual photos and videos are vital for mobile apparel shoppers.","C":"Incorrect because blocking mobile users cuts off the largest e-commerce traffic source.","D":"Incorrect because paper cheques create massive checkout friction."}}},{"id":"P1_U3_MCQ_357","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_357","question":"Why does expanding into 'foreign markets' help a domestic manufacturer reduce overall business risk?","options":{"A":"If the home country enters an economic recession, strong sales in growing foreign economies can offset domestic revenue declines","B":"Foreign countries never experience economic downturns or competition","C":"Exporting eliminates all foreign exchange-rate fluctuations","D":"Foreign governments guarantee 100% profit margins to all imported brands"},"correctOption":"A","correctAnswer":"If the home country enters an economic recession, strong sales in growing foreign economies can offset domestic revenue declines","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because geographic diversification prevents over-dependence on a single national economy's business cycle.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because foreign markets have their own business cycles and rivals.","C":"Incorrect because international trade introduces currency conversion risk.","D":"Incorrect because exporters compete on commercial merit without profit guarantees."}}},{"id":"P1_U3_MCQ_358","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_358","question":"A European snack company exports beef-flavoured crisps and pork-gelatin sweets into a predominantly Muslim country without changing ingredients or Halal certification, resulting in zero supermarket orders. Which barrier to foreign market entry was overlooked?","options":{"A":"Cultural and religious dietary laws governing acceptable food ingredients","B":"High shipping container weight limits","C":"Lack of internet broadband speed in supermarkets","D":"Excessive use of random survey sampling"},"correctOption":"A","correctAnswer":"Cultural and religious dietary laws governing acceptable food ingredients","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because religious and cultural dietary rules strictly govern consumer food acceptance and import approval.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because snack crisps and sweets are lightweight.","C":"Incorrect because supermarket orders were rejected due to non-Halal ingredients, not internet speed.","D":"Incorrect because the failure resulted from ignoring local cultural research."}}},{"id":"P1_U3_MCQ_359","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_359","question":"A luxury handbag maker from Europe enters a developing economy where average household incomes are one-fifth of European levels, yet tries to sell identical $2,000 bags without introducing smaller, lower-priced accessories. Why will sales likely struggle?","options":{"A":"Failure to adapt product sizing and pricing tiers to local purchasing power and income distribution","B":"Consumers in developing economies never buy branded fashion accessories","C":"European handbags are legally banned from being exported","D":"Lower-priced leather wallets have higher manufacturing costs than $2,000 coats"},"correctOption":"A","correctAnswer":"Failure to adapt product sizing and pricing tiers to local purchasing power and income distribution","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lower average disposable incomes restrict the size of the ultra-luxury segment, making accessible entry-level luxury items (like wallets or fragrances) strategic.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because aspirational brand demand is strong when priced within local reach.","C":"Incorrect because luxury goods are major European exports.","D":"Incorrect because smaller accessories use less material and cost less to produce."}}},{"id":"P1_U3_MCQ_360","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_360","question":"A domestic appliance maker produces blenders at a landed export cost (including shipping) of $40 per unit. If the importing country charges a 25% import tariff on blenders, what is the minimum price per blender needed just to break even on landed tariff-paid cost?","options":{"A":"$45.00","B":"$50.00","C":"$65.00","D":"$30.00"},"correctOption":"B","correctAnswer":"$50.00","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Import Tariff = 25% of $40 = $10.00; Total Tariff-Paid Cost = $40.00 + $10.00 = $50.00.","distractor_reasons":{"A":"Incorrect because $45.00 adds only 12.5% ($5) instead of 25%.","B":"Correct selection.","C":"Incorrect because $65.00 adds $25 flat rather than 25% of $40.","D":"Incorrect because $30.00 subtracts $10 instead of adding the import tariff."}}},{"id":"P1_U3_MCQ_361","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_361","question":"A Japanese electronics company forms a 50/50 'joint venture' with a Brazilian manufacturer to assemble and market air conditioners in South America. What is a key strategic advantage of this entry method?","options":{"A":"Local assembly avoids high finished-product import tariffs while combining Japanese engineering with the Brazilian partner's local distribution network and market insight","B":"The Japanese firm keeps 100% of all profits without sharing control","C":"Joint ventures guarantee zero cultural or management disagreements","D":"Neither partner has to invest any money or technical staff"},"correctOption":"A","correctAnswer":"Local assembly avoids high finished-product import tariffs while combining Japanese engineering with the Brazilian partner's local distribution network and market insight","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because local joint-venture production bypasses import barriers and leverages complementary strengths while sharing capital risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profits and governance are shared 50/50.","C":"Incorrect because differing corporate cultures remain a key risk.","D":"Incorrect because both partners contribute capital, technology, or facilities."}}},{"id":"P1_U3_MCQ_362","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_362","question":"A British sportswear brand grants a local textile company in India the legal right to manufacture and sell its branded gymwear for five years in return for an 8% royalty on wholesale revenue. What is a major risk of this 'licensing' agreement?","options":{"A":"Once the five-year license expires, the local manufacturer may use the production expertise and market contacts gained to launch its own rival brand","B":"The British brand must pay 100% of the Indian factory's electricity and wage bills","C":"Licensing prevents the British brand from earning any royalty income","D":"Licensing exposes the British brand to high import tariffs on finished gymwear"},"correctOption":"A","correctAnswer":"Once the five-year license expires, the local manufacturer may use the production expertise and market contacts gained to launch its own rival brand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because transferring technical know-how and local market access to an independent licensee risks nurturing a future competitor.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the licensee funds its own factory operations.","C":"Incorrect because the licensor earns the contracted 8% royalty.","D":"Incorrect because local production avoids finished-good import tariffs."}}},{"id":"P1_U3_MCQ_363","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_363","question":"A Canadian fast-casual sandwich chain enters 15 European countries by selling master 'franchise' rights to local operators who invest their own capital to open branded stores. Why is franchising faster than opening wholly owned branches?","options":{"A":"Franchisees provide the startup capital and local store management, allowing simultaneous multi-country expansion without exhausting the franchisor's balance sheet","B":"Franchisees require zero training, brand manuals, or quality audits","C":"The franchisor receives 100% of every store's net profit","D":"Franchising eliminates the need to adapt menus to local dietary preferences"},"correctOption":"A","correctAnswer":"Franchisees provide the startup capital and local store management, allowing simultaneous multi-country expansion without exhausting the franchisor's balance sheet","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leveraging franchisee capital and local entrepreneurial drive overcomes financial and managerial bottlenecks.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because franchisors must invest heavily in training and quality monitoring.","C":"Incorrect because the franchisor earns upfront fees and ongoing royalty percentages.","D":"Incorrect because successful global franchises still adapt menus to local tastes."}}},{"id":"P1_U3_MCQ_364","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_364","question":"When is setting up a 'wholly owned foreign manufacturing subsidiary' preferable to 'direct exporting' from the home country?","options":{"A":"When foreign sales volume is large and stable, transport costs or import tariffs are very high, and the firm wants 100% control over quality and profits","B":"When the business has almost zero capital and wants to test a tiny foreign market for two months","C":"When the foreign country is politically unstable and confiscates foreign factories","D":"When the product is digital software downloadable over the internet at zero shipping cost"},"correctOption":"A","correctAnswer":"When foreign sales volume is large and stable, transport costs or import tariffs are very high, and the firm wants 100% control over quality and profits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high committed capital is justified when scale, tariff savings, and full operational control outweigh startup risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because low-capital market testing suits direct exporting or local distributors.","C":"Incorrect because political instability makes fixed foreign asset ownership high-risk.","D":"Incorrect because digital software needs no overseas factories."}}},{"id":"P1_U3_MCQ_365","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_365","question":"Why does a global smartphone brand keep its hardware specifications and operating system standardized worldwide while translating user manuals, app stores, and advertising campaigns for each country?","options":{"A":"Standardized hardware captures massive global manufacturing economies of scale, while localized promotion and language support ensure cultural relevance","B":"Governments ban companies from selling identical phone hardware in two different countries","C":"Translating user manuals increases factory chip-fabrication costs by 500%","D":"Consumers prefer phones with operating systems written in foreign languages they cannot read"},"correctOption":"A","correctAnswer":"Standardized hardware captures massive global manufacturing economies of scale, while localized promotion and language support ensure cultural relevance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because balancing global production scale with local communication adaptation maximizes both cost efficiency and customer appeal.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because global tech firms sell uniform core devices worldwide.","C":"Incorrect because software/manual localization is inexpensive relative to hardware tooling.","D":"Incorrect because local language interfaces are vital for usability."}}},{"id":"P1_U3_MCQ_366","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_366","question":"Why do governments enact 'consumer protection legislation' regulating how businesses advertise, price, and sell goods?","options":{"A":"To protect individual buyers—who have less technical information and bargaining power than large corporations—from unsafe, faulty, or deceptive products","B":"To guarantee that every private business makes at least a 40% net profit margin","C":"To prevent consumers from ever returning broken or misdescribed items","D":"To eliminate all price competition between rival supermarkets"},"correctOption":"A","correctAnswer":"To protect individual buyers—who have less technical information and bargaining power than large corporations—from unsafe, faulty, or deceptive products","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumer protection laws correct information asymmetry and enforce minimum standards of honesty, safety, and quality.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because laws protect buyers rather than guaranteeing business profits.","C":"Incorrect because consumer laws grant statutory return and refund rights.","D":"Incorrect because competition laws actively encourage fair rivalry."}}},{"id":"P1_U3_MCQ_367","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_367","question":"A travel website advertises a '5-Star Beachfront Resort' with photos of white sand, but arriving guests discover the hotel is a 2-star building three miles inland next to a highway. Which legal control has been violated?","options":{"A":"Trade descriptions and misleading advertising laws prohibiting false statements about product or service features","B":"Factory minimum-wage legislation","C":"Weights and measures liquid-volume rules","D":"Patent royalty licensing rules"},"correctOption":"A","correctAnswer":"Trade descriptions and misleading advertising laws prohibiting false statements about product or service features","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because misrepresenting location, star rating, and amenities deceives consumers and breaches fair-trading descriptions laws.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because minimum-wage laws govern employee pay.","C":"Incorrect because weights and measures govern physical quantity labelling.","D":"Incorrect because patent rules govern inventions."}}},{"id":"P1_U3_MCQ_368","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_368","question":"A shopper buys a waterproof hiking jacket, and during its first light rain shower water leaks straight through the seams. The store displays a sign saying 'No Refunds Under Any Circumstances'. Why is the store's policy unlawful?","options":{"A":"Statutory consumer rights require goods to be 'fit for their intended purpose' and of satisfactory quality, overriding shop signs that try to waive legal remedies","B":"Retailers are legally required to refund jackets simply because a shopper dislikes the colour six months later","C":"Hiking jackets are exempt from all sales taxes","D":"Stores are forbidden from displaying any signs near cash registers"},"correctOption":"A","correctAnswer":"Statutory consumer rights require goods to be 'fit for their intended purpose' and of satisfactory quality, overriding shop signs that try to waive legal remedies","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a waterproof jacket that leaks is not fit for purpose, and retailers cannot contract out of statutory consumer protections.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because statutory remedies apply to faulty/unfit goods rather than change-of-mind months later.","C":"Incorrect because sales taxes apply normally.","D":"Incorrect because signs are lawful unless they misrepresent statutory rights."}}},{"id":"P1_U3_MCQ_369","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_369","question":"A petrol station's fuel pumps are found by trading-standards inspectors to dispense only 0.92 litres of petrol for every 1.00 litre charged on the digital display. Which consumer law is being breached?","options":{"A":"Weights and measures legislation requiring accurate measurement of goods sold by volume or weight","B":"Employment redundancy notice legislation","C":"Copyright protection over television jingles","D":"Franchise territory exclusivity agreements"},"correctOption":"A","correctAnswer":"Weights and measures legislation requiring accurate measurement of goods sold by volume or weight","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because weights-and-measures statutes require calibrated equipment so buyers receive the exact quantity paid for.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because redundancy laws belong to Human Resources.","C":"Incorrect because copyright protects artistic works.","D":"Incorrect because franchise agreements are private commercial contracts."}}},{"id":"P1_U3_MCQ_370","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_370","question":"A sofa store advertises '70% Off — Ends Sunday!' continuously for 52 weeks in a row, never actually selling sofas at the higher reference price. Why do consumer regulators fine this tactic?","options":{"A":"Fictitious urgency and misleading reference pricing deceive shoppers into believing a permanent price is a temporary bargain","B":"Sofa stores are legally required to raise prices every Monday morning","C":"Advertising furniture discounts is banned in all newspapers","D":"Consumers are prohibited from buying sofas on weekends"},"correctOption":"A","correctAnswer":"Fictitious urgency and misleading reference pricing deceive shoppers into believing a permanent price is a temporary bargain","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fake countdown deadlines and inflated reference prices manipulate buyer urgency unfairly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because firms set prices freely provided promotional claims are genuine.","C":"Incorrect because genuine sales promotions are lawful.","D":"Incorrect because weekend retail trading is standard."}}},{"id":"P1_U3_MCQ_371","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_371","question":"A bakery switches to a cheaper supplier of almond flour for its chocolate brownies, but forgets to update the ingredient list or add a 'Contains Tree Nuts' allergen warning on the wrapper. What severe legal and commercial consequence could follow?","options":{"A":"Life-threatening allergic reactions in customers, mandatory product recalls, heavy criminal fines, and catastrophic brand trust collapse","B":"Automatic 50% increase in repeat orders from nut-allergic shoppers","C":"Exemption from paying business income taxes for five years","D":"Reduced packaging printing costs with zero legal liability"},"correctOption":"A","correctAnswer":"Life-threatening allergic reactions in customers, mandatory product recalls, heavy criminal fines, and catastrophic brand trust collapse","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because food allergen labelling laws are strictly enforced to protect consumer lives; omissions trigger immediate recalls and prosecution.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because unlisted allergens endanger customers and destroy trust.","C":"Incorrect because safety breaches incur fines rather than tax breaks.","D":"Incorrect because businesses bear strict legal liability for accurate allergen declarations."}}},{"id":"P1_U3_MCQ_372","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_372","question":"Under modern data-protection and digital-marketing laws, what must an e-commerce retailer do before adding a new website visitor's email address to its promotional newsletter list?","options":{"A":"Obtain clear, affirmative opt-in consent from the customer and provide an easy one-click unsubscribe option in every marketing email","B":"Automatically subscribe every visitor using hidden pre-ticked boxes","C":"Publish the customer's home address and phone number publicly on social media","D":"Charge the customer $10 to remove their email from the mailing list"},"correctOption":"A","correctAnswer":"Obtain clear, affirmative opt-in consent from the customer and provide an easy one-click unsubscribe option in every marketing email","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because privacy regulations require explicit permission for direct marketing and transparent opt-out rights.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pre-ticked boxes do not constitute valid consent under data protection laws.","C":"Incorrect because sharing personal data publicly breaches privacy laws.","D":"Incorrect because unsubscribing must be free and straightforward."}}},{"id":"P1_U3_MCQ_373","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_373","question":"Why do broadcasting regulators enforce strict rules prohibiting television adverts from pressuring children directly to beg parents to buy expensive toys ('pester power')?","options":{"A":"Because young children lack the critical maturity to distinguish persuasive commercial intent from factual reality, requiring ethical and legal protection","B":"Because toy companies are legally forbidden from manufacturing plastic toys","C":"Because parents never buy birthday or holiday presents for their children","D":"Because television channels only broadcast educational documentaries"},"correctOption":"A","correctAnswer":"Because young children lack the critical maturity to distinguish persuasive commercial intent from factual reality, requiring ethical and legal protection","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because advertising standards codes protect vulnerable audiences such as children from exploitative psychological pressure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because manufacturing toys is lawful when safety standards are met.","C":"Incorrect because parents remain the primary purchasers of toys.","D":"Incorrect because commercial channels air diverse programming under advertising rules."}}},{"id":"P1_U3_MCQ_374","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_374","question":"A household-appliance manufacturer spends $400,000 extra each year on independent electrical safety certifications and clear multilingual warning manuals. How can its marketing team turn this legal compliance cost into a competitive advantage?","options":{"A":"Highlight certified safety testing and 5-year reliability guarantees in promotions to justify premium pricing over uncertified budget imports","B":"Hide all safety certificates so customers assume the appliances are untested","C":"Stop inspecting factory output because certificates last forever without quality checks","D":"Cut warranty coverage to zero days to recover the $400,000 fee"},"correctOption":"A","correctAnswer":"Highlight certified safety testing and 5-year reliability guarantees in promotions to justify premium pricing over uncertified budget imports","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because visible safety assurance reduces perceived buyer risk, strengthening brand trust and supporting higher profit margins.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because showcasing safety credentials builds buyer confidence.","C":"Incorrect because ongoing quality control is required to maintain certification.","D":"Incorrect because strong safety testing allows the firm to offer generous warranties confidently."}}},{"id":"P1_U3_MCQ_375","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_375","question":"A mid-sized European baby-stroller manufacturer faces falling domestic birth rates and strict European safety standards. Which integrated 'marketing strategy' is most likely to achieve sustainable long-term growth?","options":{"A":"Leverage its strict European safety certification as a premium trust USP to enter fast-growing Asian middle-class markets via local joint-venture distributors while expanding domestic accessories for existing parents","B":"Cut stroller frame quality to lower costs, ignore safety testing laws, and rely solely on domestic high-street shops","C":"Double domestic stroller prices while stopping all digital marketing and product R&D","D":"Sell unbranded strollers at below variable cost using misleading '90% Off' fake discounts"},"correctOption":"A","correctAnswer":"Leverage its strict European safety certification as a premium trust USP to enter fast-growing Asian middle-class markets via local joint-venture distributors while expanding domestic accessories for existing parents","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because turning regulatory safety excellence into an international trust advantage opens growing foreign demographics while extending domestic customer value.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because compromising child safety violates laws and destroys brand reputation.","C":"Incorrect because doubling prices in a shrinking domestic market collapses sales.","D":"Incorrect because selling below variable cost causes losses and fake discounts breach consumer law."}}},{"id":"P1_U3_MCQ_376","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_376","question":"A desk-accessory startup discovers through home-office visits that remote workers struggle with tangled charger cables, and designs a magnetic modular cable organizer priced to yield a 35% profit margin. Which core principle of marketing is shown?","options":{"A":"Identifying customer pain points and satisfying them profitably","B":"Producing the cheapest possible item regardless of buyer usefulness","C":"Focusing purely on maximizing factory machine running hours","D":"Eliminating all promotional spending to cut fixed overheads"},"correctOption":"A","correctAnswer":"Identifying customer pain points and satisfying them profitably","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because effective marketing connects a genuine consumer need with a commercial solution that generates sustainable profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ignoring buyer utility undermines product demand.","C":"Incorrect because maximizing machine hours without demand focus reflects production orientation.","D":"Incorrect because new products still require promotion to build awareness."}}},{"id":"P1_U3_MCQ_377","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_377","question":"Noticing a steady rise in single-person pet ownership, a home-security firm develops an indoor camera with built-in treat dispensing and barking alerts two years before major rivals enter the space. Which marketing role does this demonstrate?","options":{"A":"Anticipating future customer needs ahead of competitors","B":"Managing statutory corporate tax filings","C":"Negotiating raw-material bulk discounts with steel mills","D":"Operating a pure price-skimming monopoly on basic cameras"},"correctOption":"A","correctAnswer":"Anticipating future customer needs ahead of competitors","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because spotting emerging demographic lifestyle trends allows marketing teams to anticipate future demand early.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax compliance is handled by Finance.","C":"Incorrect because supplier procurement belongs to Operations.","D":"Incorrect because standard security cameras already face wide competition."}}},{"id":"P1_U3_MCQ_378","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_378","question":"A specialty coffee roaster calculates that acquiring a first-time online buyer costs $28 in adverts, whereas retaining an existing subscriber costs $4 per year in loyalty perks. Why is maintaining customer loyalty vital for profitability?","options":{"A":"Repeat buyers generate recurring revenue at much lower marketing cost per order than constantly replacing lost customers","B":"Loyal customers never expect consistent coffee bean quality","C":"High customer loyalty eliminates all coffee roasting and shipping expenses","D":"Retained subscribers are legally forbidden from buying rival brands"},"correctOption":"A","correctAnswer":"Repeat buyers generate recurring revenue at much lower marketing cost per order than constantly replacing lost customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because repeat purchases amortize initial customer acquisition costs and produce reliable long-term cash flow.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quality consistency is what sustains loyalty.","C":"Incorrect because production and delivery costs still apply to every order.","D":"Incorrect because consumers always remain free to switch brands."}}},{"id":"P1_U3_MCQ_379","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_379","question":"Total annual sales in a regional organic baby-food market equal $425 million, and PureSpoon Ltd achieves annual sales of $85 million. What is PureSpoon Ltd's market share?","options":{"A":"5.0%","B":"20.0%","C":"25.0%","D":"85.0%"},"correctOption":"B","correctAnswer":"20.0%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Market Share (%) = ($85m / $425m) × 100 = 20.0%.","distractor_reasons":{"A":"Incorrect because 5.0 divides $425m by $85m instead of $85m by $425m.","B":"Correct selection.","C":"Incorrect because 25.0% divides $85m by $340m ($425m - $85m).","D":"Incorrect because 85.0% confuses dollar sales with percentage share."}}},{"id":"P1_U3_MCQ_380","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_380","question":"During an economic slowdown, total industry sales of home-renovation tiles fall by 12%, while AquaTile Ltd's sales revenue declines by only 3%. What happened to AquaTile Ltd's market share?","options":{"A":"Its market share increased because its sales fell far less sharply than the overall market","B":"Its market share fell by 9%","C":"Its market share dropped to zero","D":"Its market share remained completely unchanged"},"correctOption":"A","correctAnswer":"Its market share increased because its sales fell far less sharply than the overall market","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because outperforming the industry average—even in a shrinking market—means capturing a larger slice of remaining sales.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because losing fewer sales than rivals raises relative share.","C":"Incorrect because AquaTile retained 97% of its previous sales.","D":"Incorrect because relative share changes whenever firm growth differs from total market growth."}}},{"id":"P1_U3_MCQ_381","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_381","question":"In a country where the proportion of citizens aged over 65 has doubled in twenty years, pharmacies report booming sales of joint-support supplements, hearing aids, and step-free holiday packages. Which factor is driving these spending changes?","options":{"A":"Demographic changes in the population age structure","B":"A sudden collapse in national internet access","C":"Government bans on youth clothing stores","D":"Falling average life expectancy across all cities"},"correctOption":"A","correctAnswer":"Demographic changes in the population age structure","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an aging population shifts aggregate consumer demand toward healthcare, accessibility, and senior leisure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because internet access has expanded rather than collapsed.","C":"Incorrect because demand shifts reflect population demographics rather than bans.","D":"Incorrect because longer life expectancy is what drives an aging demographic."}}},{"id":"P1_U3_MCQ_382","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_382","question":"Eco-conscious shoppers increasingly reject single-use plastic detergent bottles in favour of concentrated soluble cleaning tablets shipped in compostable cardboard pouches. Which trend explains this shift?","options":{"A":"Growing environmental awareness influencing ethical purchasing choices","B":"Consumers stopping washing their clothes altogether","C":"A shortage of cardboard boxes worldwide","D":"Detergent tablets being legally required to cost five times more than liquid soap"},"correctOption":"A","correctAnswer":"Growing environmental awareness influencing ethical purchasing choices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustainability values alter consumer preferences toward low-waste, recyclable packaging.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because laundry demand continues via more sustainable formats.","C":"Incorrect because cardboard pouches are widely available.","D":"Incorrect because refill tablets are often competitively priced."}}},{"id":"P1_U3_MCQ_383","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_383","question":"With hybrid remote working becoming permanent in major cities, downtown sandwich shops see Monday and Friday footfall drop by 35%, while suburban cafés experience record weekday queues. What caused this spending shift?","options":{"A":"Changing work patterns altering where consumers spend money during the week","B":"City-centre restaurants banning office workers from entering","C":"Suburban cafés giving away all meals for free","D":"A total disappearance of commuter trains"},"correctOption":"A","correctAnswer":"Changing work patterns altering where consumers spend money during the week","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because working from home relocates daily lunch and coffee spending from business districts to residential suburbs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because city cafés actively want weekday diners.","C":"Incorrect because suburban cafés charge commercial prices.","D":"Incorrect because trains still operate, just with fewer Friday/Monday commuters."}}},{"id":"P1_U3_MCQ_384","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_384","question":"A local stationery store in Malaysia used to compete only with shops on the same street, but now loses sales to overseas sellers offering free cross-border shipping on online marketplaces. Why has competition increased?","options":{"A":"Globalization and e-commerce platforms allow foreign sellers to reach domestic buyers directly","B":"Local consumers stopped using pens and notebooks completely","C":"High-street stationery shops are legally barred from selling online","D":"International air freight has become completely free for all factories"},"correctOption":"A","correctAnswer":"Globalization and e-commerce platforms allow foreign sellers to reach domestic buyers directly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because digital marketplaces dismantle geographic barriers, exposing local retailers to global price and variety rivalry.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because stationery demand still exists, just captured by online rivals.","C":"Incorrect because local shops can also launch online stores.","D":"Incorrect because sellers subsidize shipping within their pricing."}}},{"id":"P1_U3_MCQ_385","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_385","question":"In the smartphone accessories industry, rival factories copy newly released phone-case designs within three weeks and sell lookalikes online. Why does rapid technological imitation intensify competition?","options":{"A":"Product differentiation advantages are short-lived, forcing firms to innovate continuously or compete heavily on price","B":"Imitators always charge ten times more than original designers","C":"Consumers prefer phone cases that do not fit their phones","D":"Rapid imitation reduces the total number of sellers in the market"},"correctOption":"A","correctAnswer":"Product differentiation advantages are short-lived, forcing firms to innovate continuously or compete heavily on price","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fast copying erodes first-mover uniqueness and increases the number of close substitutes.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because copycat sellers typically undercut the original brand's price.","C":"Incorrect because lookalikes match phone dimensions closely.","D":"Incorrect because rapid entry increases seller numbers."}}},{"id":"P1_U3_MCQ_386","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_386","question":"To defend market share against cheaper imported washing machines, a domestic appliance manufacturer introduces a 7-year parts-and-labour warranty and next-day engineer home visits. How is it responding to competition?","options":{"A":"By differentiating through superior after-sales service and reliability assurance rather than engaging in a destructive price war","B":"By lowering product build quality to match cheap imports","C":"By reducing customer service phone hours to one hour per week","D":"By stopping all deliveries to appliance retailers"},"correctOption":"A","correctAnswer":"By differentiating through superior after-sales service and reliability assurance rather than engaging in a destructive price war","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because non-price differentiation reduces perceived buyer risk on major household appliances.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a 7-year warranty requires high build quality.","C":"Incorrect because next-day support expands service availability.","D":"Incorrect because distribution continues normally."}}},{"id":"P1_U3_MCQ_387","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_387","question":"A craft kombucha brewery faces dozens of rival tea drinks in supermarkets, so it brews exclusively with wild-harvested botanical herbs in returnable apothecary glass bottles. What is the brewery creating?","options":{"A":"A clear Unique Selling Point (USP) that sets its brand apart on crowded shelves","B":"An undifferentiated mass-market commodity","C":"A product-oriented assembly line ignoring flavour trends","D":"A legal monopoly banning all other soft drinks"},"correctOption":"A","correctAnswer":"A clear Unique Selling Point (USP) that sets its brand apart on crowded shelves","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because distinctive ingredients and sustainable reusable bottles give buyers a compelling reason to choose the brand.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because wild botanicals and returnable bottles strongly differentiate the product.","C":"Incorrect because eco-bottles and botanical flavours align with modern wellness trends.","D":"Incorrect because supermarkets continue stocking rival beverages."}}},{"id":"P1_U3_MCQ_388","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_388","question":"When saturation and fierce price discounting squeeze profits in its home market, a regional gym chain expands into smaller provincial towns that currently have no modern fitness clubs. Which competitive response is this?","options":{"A":"Entering new, less-saturated geographic markets to capture untapped demand","B":"Doubling membership fees in its saturated home-city clubs","C":"Closing all gyms and selling exercise equipment for scrap","D":"Switching from gyms to manufacturing agricultural tractors"},"correctOption":"A","correctAnswer":"Entering new, less-saturated geographic markets to capture untapped demand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because geographic market development relieves competitive pressure by finding underserved locations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raising fees in a saturated market would drive members to rivals.","C":"Incorrect because the chain is expanding rather than liquidating.","D":"Incorrect because the firm remains in fitness services."}}},{"id":"P1_U3_MCQ_389","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_389","question":"A cutlery workshop designs ergonomically angled chef knives exclusively for left-handed professional cooks. Which market strategy is this?","options":{"A":"Niche marketing","B":"Mass marketing","C":"Undifferentiated commodity marketing","D":"Loss-leader supermarket marketing"},"correctOption":"A","correctAnswer":"Niche marketing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because left-handed chefs represent a small, specialized segment overlooked by mass-market knife producers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because mass marketing produces standard right-handed knives for the majority.","C":"Incorrect because the knives are specifically engineered for left-handed ergonomics.","D":"Incorrect because specialist chef knives are premium tools rather than supermarket loss leaders."}}},{"id":"P1_U3_MCQ_390","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_390","question":"Why can a specialist maker of gluten-free, nut-free wedding cakes charge higher profit margins than a standard high-street bakery?","options":{"A":"Customers with severe food allergies face few safe alternatives and willingly pay a premium for trusted specialist expertise","B":"Allergen-free ingredients cost zero money to purchase","C":"High-street bakeries are legally banned from baking wedding cakes","D":"Specialist bakeries never pay kitchen electricity or staff wages"},"correctOption":"A","correctAnswer":"Customers with severe food allergies face few safe alternatives and willingly pay a premium for trusted specialist expertise","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because niche specialization solves a critical high-stakes need with minimal direct competition, supporting premium pricing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because certified allergen-free ingredients are actually costlier.","C":"Incorrect because standard bakeries make regular wedding cakes.","D":"Incorrect because normal overhead and labour costs still apply."}}},{"id":"P1_U3_MCQ_391","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_391","question":"A boutique watchmaker produces only 400 mechanical diving watches per year for deep-sea saturation divers. What cost disadvantage does this 'niche market' scale create compared with mass-market watch brands?","options":{"A":"Inability to achieve large technical and purchasing economies of scale, resulting in much higher unit production costs","B":"Excessive spending on global prime-time television commercials","C":"Too many millions of customers ordering watches every week","D":"Being forced to sell watches below raw steel cost"},"correctOption":"A","correctAnswer":"Inability to achieve large technical and purchasing economies of scale, resulting in much higher unit production costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because small batch sizes mean fixed tooling and engineering expenses are spread over very few units.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because niche firms rarely buy mass prime-time TV ads.","C":"Incorrect because total demand in a niche is small.","D":"Incorrect because niche watches are priced at a high premium."}}},{"id":"P1_U3_MCQ_392","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_392","question":"A battery manufacturer produces standardized AA alkaline batteries sold in identical packs across supermarkets, petrol stations, and hardware stores nationwide. Which approach is this?","options":{"A":"Mass marketing","B":"Bespoke niche marketing","C":"Psychographic luxury targeting","D":"Geographic micro-segmentation"},"correctOption":"A","correctAnswer":"Mass marketing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because standard AA batteries appeal to the broadest possible consumer base with one uniform product.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because AA batteries serve universal everyday household demand.","C":"Incorrect because batteries are functional staples rather than luxury lifestyle goods.","D":"Incorrect because identical packs are sold everywhere."}}},{"id":"P1_U3_MCQ_393","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_393","question":"What is a major financial advantage for a household-soap company operating successfully in a large 'mass market'?","options":{"A":"High total sales volumes enable automated flow production, bulk raw-material discounts, and huge total revenue potential","B":"Zero rival soap brands are allowed to enter supermarkets","C":"Mass-market soap requires no brand advertising or packaging","D":"Every consumer pays a custom negotiated luxury price"},"correctOption":"A","correctAnswer":"High total sales volumes enable automated flow production, bulk raw-material discounts, and huge total revenue potential","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because serving the whole market maximizes output volume, driving down average unit costs while generating massive revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because mass markets are fiercely competitive.","C":"Incorrect because mass brands invest heavily in packaging and advertising.","D":"Incorrect because mass-market goods carry standardized retail prices."}}},{"id":"P1_U3_MCQ_394","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_394","question":"A mass-market manufacturer of sugary carbonated colas invests $500 million in single-purpose bottling plants, only for mainstream consumer tastes to shift rapidly toward sparkling mineral water. What vulnerability of 'mass marketing' is exposed?","options":{"A":"Heavy fixed capital investment in standardized mass production makes it costly and slow to adapt when mainstream consumer fashions shift","B":"Mass-market bottling machines can switch recipes at zero cost overnight","C":"Sparkling water is a tiny niche bought by fewer than 100 people","D":"Mass-market firms never face changes in consumer preferences"},"correctOption":"A","correctAnswer":"Heavy fixed capital investment in standardized mass production makes it costly and slow to adapt when mainstream consumer fashions shift","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because specialized high-volume facilities create rigidity when broad market tastes evolve.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retooling high-speed lines and rebranding involves major cost.","C":"Incorrect because bottled sparkling water is itself a huge mainstream category.","D":"Incorrect because health and lifestyle trends frequently reshape mass markets."}}},{"id":"P1_U3_MCQ_395","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_395","question":"On the exact same flight, an airline sells 'Basic Economy' seats with no checked bag for $90, 'Flexible Economy' seats for $160, and 'Lie-Flat Business Class' pods for $950. Why does the airline segment passengers this way?","options":{"A":"Different passengers value flexibility and comfort differently; segmentation captures maximum revenue from each willingness-to-pay group","B":"Airlines are legally forbidden from selling identical seats at different prices","C":"Lie-flat pods cost less to install than standard economy seats","D":"Segmentation reduces the total number of passengers flying each year"},"correctOption":"A","correctAnswer":"Different passengers value flexibility and comfort differently; segmentation captures maximum revenue from each willingness-to-pay group","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because matching service tiers to distinct traveller budgets fills the aircraft while maximizing total flight yield.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tiered fare classes are standard airline practice.","C":"Incorrect because business pods occupy much more cabin floor space.","D":"Incorrect because budget fares attract price-sensitive flyers who otherwise wouldn't travel."}}},{"id":"P1_U3_MCQ_396","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_396","question":"A fashion retailer launches a tailored wool suit collection for female corporate executives alongside an affordable unisex fleece loungewear line for university students. Which segmentation variables are combined?","options":{"A":"Gender, occupation/life stage, and income","B":"Climatic zone and postal code only","C":"Undifferentiated mass standardization","D":"Industrial B2B factory capacity"},"correctOption":"A","correctAnswer":"Gender, occupation/life stage, and income","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because buyer gender, professional vs student lifestyle, and disposable income define the two distinct collections.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both collections sell across the same cities.","C":"Incorrect because two distinct lines serve two separate buyer groups.","D":"Incorrect because both lines target individual retail consumers."}}},{"id":"P1_U3_MCQ_397","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_397","question":"An automotive brand promotes heavy-duty four-wheel-drive pickup trucks in rural farming provinces with unpaved roads, while advertising ultra-compact electric city cars in congested megacities. Which segmentation basis is applied?","options":{"A":"Geographic segmentation (urban vs rural environment and infrastructure)","B":"Gender segmentation","C":"Age-only segmentation","D":"Religious dietary segmentation"},"correctOption":"A","correctAnswer":"Geographic segmentation (urban vs rural environment and infrastructure)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because road conditions, parking density, and local geography determine vehicle suitability.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both men and women drive pickups in rural areas and city cars in megacities.","C":"Incorrect because location rather than driver age explains the vehicle split.","D":"Incorrect because religion does not dictate road infrastructure."}}},{"id":"P1_U3_MCQ_398","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_398","question":"A commercial bank offers zero-fee mobile checking accounts with small overdrafts for college students, while providing dedicated private wealth advisors and airport lounge passes for clients holding over $500,000 in savings. Which segmentation variable separates these products?","options":{"A":"Income and wealth (socio-economic status)","B":"Customer gender","C":"Climatic weather zone","D":"Product-oriented mass production"},"correctOption":"A","correctAnswer":"Income and wealth (socio-economic status)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because financial asset levels and earning power dictate banking needs and fee structures.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both accounts serve all genders.","C":"Incorrect because weather climate has no bearing on bank account tiers.","D":"Incorrect because services are tailored to client wealth brackets."}}},{"id":"P1_U3_MCQ_399","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_399","question":"An outdoor brand sells ultralight titanium stoves and minimalist bivouac tents marketed around 'leave-no-trace wilderness self-reliance' for solo mountain trekkers. Which segmentation approach is used?","options":{"A":"Psychographic segmentation (lifestyle, hobbies, and personal values)","B":"Postal code segmentation","C":"Gender-only segmentation","D":"Undifferentiated commodity marketing"},"correctOption":"A","correctAnswer":"Psychographic segmentation (lifestyle, hobbies, and personal values)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shared outdoor passion and minimalist environmental values unite trekkers across different ages and regions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because trekkers live in many postcodes and travel to mountains.","C":"Incorrect because solo trekkers include all genders.","D":"Incorrect because ultralight titanium gear is highly specialized."}}},{"id":"P1_U3_MCQ_400","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_400","question":"A smartphone maker launches a $699 'Lite' phone with nearly identical camera and screen specs to its $999 'Pro' model, causing existing 'Pro' buyers to downgrade to the cheaper model. What segmentation pitfall occurred?","options":{"A":"Poorly differentiated segments led to 'cannibalization', eroding revenue from higher-margin customers","B":"The firm spent too much on primary random sampling","C":"Consumers refused to buy any smartphones at all","D":"Unit manufacturing costs dropped to zero"},"correctOption":"A","correctAnswer":"Poorly differentiated segments led to 'cannibalization', eroding revenue from higher-margin customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when tiered products lack clear separation, high-income buyers trade down, reducing overall profit margins.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the issue was overlapping product positioning rather than survey sampling.","C":"Incorrect because customers still bought the 'Lite' phone.","D":"Incorrect because hardware manufacturing costs remained substantial."}}},{"id":"P1_U3_MCQ_401","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_401","question":"An artisanal glassblowing studio spends months crafting heavy, ornate crystal fruit bowls because the founder admires classical sculpture, without checking whether modern apartment dwellers want delicate hand-wash-only bowls. Sales are dismal. Why?","options":{"A":"The studio is product-oriented, prioritizing the maker's artistic tastes over researched buyer preferences","B":"The studio conducted too many customer focus groups","C":"Crystal bowls are legally prohibited from being sold in retail shops","D":"The studio used dynamic online surge pricing"},"correctOption":"A","correctAnswer":"The studio is product-oriented, prioritizing the maker's artistic tastes over researched buyer preferences","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because product-oriented firms build what they enjoy making rather than researching practical consumer demand.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no customer research was performed.","C":"Incorrect because glassware is completely legal to sell.","D":"Incorrect because lack of market fit—not dynamic pricing—caused low sales."}}},{"id":"P1_U3_MCQ_402","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_402","question":"After tracking rising customer requests for dairy-free lunches, a meal-kit company tests six plant-based recipes with subscribers and adds the top three to its weekly menu, boosting retention by 18%. Which orientation does this reflect?","options":{"A":"Market orientation","B":"Product orientation","C":"Production-led orientation","D":"Asset-stripping orientation"},"correctOption":"A","correctAnswer":"Market orientation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because listening to customer feedback and testing solutions before rollout exemplifies market orientation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because recipes were driven by subscriber demand rather than chef ego.","C":"Incorrect because the focus was recipe relevance rather than sheer factory volume.","D":"Incorrect because asset-stripping refers to corporate restructuring."}}},{"id":"P1_U3_MCQ_403","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_403","question":"Before signing a five-year lease on a retail unit in a new city, a bubble-tea chain researches local footfall, competitor store density, and student spending power. How does this research help management?","options":{"A":"It reduces the financial risk of committing to a costly long-term lease in an unprofitable location","B":"It eliminates the need to pay rent or staff wages once the shop opens","C":"It legally prevents rival bubble-tea shops from opening nearby","D":"It guarantees that 100% of passers-by will buy two drinks daily"},"correctOption":"A","correctAnswer":"It reduces the financial risk of committing to a costly long-term lease in an unprofitable location","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because evaluating demand and competition beforehand prevents expensive sunk-cost location mistakes.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rent and wages remain ongoing operating expenses.","C":"Incorrect because competitors can still enter open retail areas.","D":"Incorrect because research estimates likely conversion rather than guaranteeing 100% sales."}}},{"id":"P1_U3_MCQ_404","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_404","question":"Six months after launching an updated mobile banking app, a bank surveys users to measure satisfaction with the new bill-splitting feature and identify bugs. Why is ongoing post-launch market research important?","options":{"A":"It tracks whether the product is meeting customer expectations in real use and highlights improvements needed to prevent customer churn","B":"Market research is only allowed before a product is launched","C":"Post-launch surveys automatically double customer bank balances","D":"Ongoing research replaces the need for software engineers"},"correctOption":"A","correctAnswer":"It tracks whether the product is meeting customer expectations in real use and highlights improvements needed to prevent customer churn","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because continuous feedback helps businesses refine existing offerings and sustain competitiveness.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because research is valuable throughout the entire Product Life Cycle.","C":"Incorrect because surveys collect feedback rather than altering account balances.","D":"Incorrect because engineers are still required to fix issues uncovered."}}},{"id":"P1_U3_MCQ_405","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_405","question":"A health-club chain distributes a questionnaire to 800 members asking whether they would pay $10 extra per month for an infrared sauna or a dedicated indoor cycling studio. Why is 'primary research' needed here?","options":{"A":"No published external report can reveal what this specific club's own members prefer and are willing to pay","B":"Primary research is always cheaper than reading free online statistics","C":"Primary research requires zero questionnaire design effort","D":"Secondary data is illegal to use in the fitness industry"},"correctOption":"A","correctAnswer":"No published external report can reveal what this specific club's own members prefer and are willing to pay","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bespoke pricing and facility trade-offs for a specific customer base require fresh, tailored primary data.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because primary research is more expensive than free secondary sources.","C":"Incorrect because designing clear questions requires careful planning.","D":"Incorrect because secondary fitness reports are widely used alongside primary surveys."}}},{"id":"P1_U3_MCQ_406","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_406","question":"A fashion startup spends five months commissioning bespoke primary interviews and street surveys before launching a summer sandal collection, by which time summer has ended and rivals have already captured the market. Which drawback of primary research occurred?","options":{"A":"Time-consuming data collection delayed product launch, causing the firm to miss a seasonal window","B":"Primary research data is always outdated before it is collected","C":"Street surveys cannot be used for clothing or footwear","D":"Primary research costs zero money to conduct"},"correctOption":"A","correctAnswer":"Time-consuming data collection delayed product launch, causing the firm to miss a seasonal window","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because designing, fielding, and analyzing primary research takes time that can erode speed-to-market in fast-moving trends.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because primary data is up-to-date when collected, though slow collection can miss deadlines.","C":"Incorrect because apparel firms frequently survey shoppers.","D":"Incorrect because primary research is relatively costly."}}},{"id":"P1_U3_MCQ_407","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_407","question":"A juice company includes the question: 'Don't you agree that our refreshing organic mango juice tastes much better than artificial supermarket brands?' Why will this question produce unreliable data?","options":{"A":"It is a leading question phrased to push respondents toward praising the company's juice","B":"It is an open-ended question requiring a written paragraph","C":"It relies on outdated government census tables","D":"It asks respondents to calculate Price Elasticity of Demand"},"correctOption":"A","correctAnswer":"It is a leading question phrased to push respondents toward praising the company's juice","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because loaded adjectives ('refreshing organic' vs 'artificial') bias respondents into agreeing rather than giving honest feedback.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 'Don't you agree...' nudges a closed Yes/No answer.","C":"Incorrect because this is a primary survey question.","D":"Incorrect because no elasticity calculation is requested."}}},{"id":"P1_U3_MCQ_408","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_408","question":"During a pilot study of 30 commuters, a bicycle manufacturer includes the open-ended question: 'What frustrates you most about folding your bike on crowded trains?' Why is an open question useful at this exploratory stage?","options":{"A":"It lets commuters describe unexpected practical issues in their own words rather than restricting them to pre-guessed tick boxes","B":"Open-ended essays can be turned into pie charts instantaneously without reading them","C":"Open questions guarantee a 100% completion rate on long surveys","D":"Open questions eliminate all interviewer bias"},"correctOption":"A","correctAnswer":"It lets commuters describe unexpected practical issues in their own words rather than restricting them to pre-guessed tick boxes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because open questions uncover rich, unanticipated insights during early exploratory research.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because open responses take substantial time to read and categorize.","C":"Incorrect because typing long answers often lowers completion rates.","D":"Incorrect because interpreting free-text answers can still involve researcher subjectivity."}}},{"id":"P1_U3_MCQ_409","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_409","question":"A broadband provider conducts 'telephone interviews' to ask households about internet speeds. What is a common disadvantage of telephone surveys compared with face-to-face interviews?","options":{"A":"Many people hang up immediately suspecting a sales call, and interviewers cannot show visual product prototypes or packaging","B":"Telephone calls are slower and more expensive than flying interviewers to every town","C":"Interviewers cannot clarify confusing questions during a live phone call","D":"Telephone interviews are illegal in telecommunications markets"},"correctOption":"A","correctAnswer":"Many people hang up immediately suspecting a sales call, and interviewers cannot show visual product prototypes or packaging","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cold-call skepticism causes high refusal rates and prevents showing physical mock-ups.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because phone interviews are faster and cheaper than travel-heavy face-to-face interviews.","C":"Incorrect because live interviewers can explain questions over the phone.","D":"Incorrect because compliant phone research is lawful."}}},{"id":"P1_U3_MCQ_410","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_410","question":"A retirement-village developer distributes its housing preference survey exclusively via a QR code posted on a social-media gaming forum. Why is this 'online survey' sample flawed?","options":{"A":"Sampling bias: elderly retirees are heavily under-represented on gaming forums, making the findings unrepresentative of the target market","B":"Online surveys are always the most expensive research method","C":"Online surveys take six months to tabulate numerical results","D":"QR codes cannot be scanned by modern smartphones"},"correctOption":"A","correctAnswer":"Sampling bias: elderly retirees are heavily under-represented on gaming forums, making the findings unrepresentative of the target market","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an online channel must reach the actual target demographic; gaming forums skew young.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because online surveys are fast and low-cost.","C":"Incorrect because digital forms tabulate data automatically in real time.","D":"Incorrect because smartphones scan QR codes easily; the flaw is the audience channel."}}},{"id":"P1_U3_MCQ_411","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_411","question":"A cereal company runs two 'focus groups' of 8 parents each, and 12 of the 16 parents say they love a broccoli-flavoured breakfast cereal. Why would launching nationally based solely on this result be risky?","options":{"A":"A tiny qualitative sample of 16 people is not statistically representative of millions of national households","B":"Focus groups are secondary research collected from government census books","C":"Focus groups never allow participants to taste sample products","D":"Broccoli cereal is illegal to sell in supermarkets"},"correctOption":"A","correctAnswer":"A tiny qualitative sample of 16 people is not statistically representative of millions of national households","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because focus groups provide deep qualitative reactions but lack the sample size needed for reliable demand forecasting.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because focus groups are primary qualitative research.","C":"Incorrect because product tasting is common in focus groups.","D":"Incorrect because the risk is commercial demand uncertainty, not legality."}}},{"id":"P1_U3_MCQ_412","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_412","question":"In a focus group testing a new sports-car advert, one loud participant mocks the advert's music, causing quieter group members to stay silent or agree despite liking it. What limitation of focus groups occurred?","options":{"A":"Peer pressure and dominant individuals distorting genuine individual opinions ('groupthink')","B":"Secondary data obsolescence","C":"Excessively large sample size causing computer crashes","D":"Postal mail delivery delays"},"correctOption":"A","correctAnswer":"Peer pressure and dominant individuals distorting genuine individual opinions ('groupthink')","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social conformity in group settings can suppress minority viewpoints unless skillfully moderated.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because focus groups generate live primary insights.","C":"Incorrect because focus groups involve small groups of 6–12 people.","D":"Incorrect because focus groups take place live rather than by mail."}}},{"id":"P1_U3_MCQ_413","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_413","question":"A supermarket hires researchers with clipboards to stand noticeably beside the organic vegetable display recording what shoppers pick up. Shoppers notice they are being watched and buy more organic vegetables than usual. Which observation flaw occurred?","options":{"A":"People alter their natural shopping behaviour when they realize they are being observed","B":"Observation cannot record which products shoppers put into their baskets","C":"Supermarkets are legally forbidden from observing aisles","D":"Observation produces qualitative essays instead of behavioural counts"},"correctOption":"A","correctAnswer":"People alter their natural shopping behaviour when they realize they are being observed","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because visible observers trigger social-desirability behaviour (the Hawthorne effect), skewing natural choices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because recording physical product selection is observation's exact strength.","C":"Incorrect because in-store retail observation is standard practice.","D":"Incorrect because observation records visible actions rather than essays."}}},{"id":"P1_U3_MCQ_414","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_414","question":"While a beverage company runs a six-week regional 'test market' for a new energy drink in one city, its biggest rival secretly floods that same city with 'Half-Price' coupons to ruin the trial sales figures. What risk of test marketing does this show?","options":{"A":"Test marketing alerts competitors to the new product early, allowing rivals to imitate it or distort trial results","B":"Test marketing costs more than launching immediately across 50 countries","C":"Test marketing is illegal in grocery retail chains","D":"Test marketing never uses real paying customers"},"correctOption":"A","correctAnswer":"Test marketing alerts competitors to the new product early, allowing rivals to imitate it or distort trial results","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because regional trials expose commercial plans publicly before national rollout.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because regional testing costs far less than a full-scale launch.","C":"Incorrect because test marketing is lawful.","D":"Incorrect because test marketing measures actual purchases by real shoppers."}}},{"id":"P1_U3_MCQ_415","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_415","question":"Before developing a new loyalty tier, a supermarket analyzes two years of its own till-receipt scanner records and customer loyalty-card purchase histories. Which type of data is being used?","options":{"A":"Internal secondary data","B":"External government census data","C":"Primary focus-group data","D":"External competitor press releases"},"correctOption":"A","correctAnswer":"Internal secondary data","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because historical transaction data already stored inside the firm's own systems is internal secondary data.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the data came from the supermarket's own tills rather than a government agency.","C":"Incorrect because no new group discussions were held.","D":"Incorrect because the records are internal company files."}}},{"id":"P1_U3_MCQ_416","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_416","question":"A baby-stroller manufacturer downloads free official national birth-rate projections and household income tables from the government statistics office. Which research source is this?","options":{"A":"External secondary research","B":"Internal company accounting records","C":"Primary quota street interviews","D":"Primary test marketing"},"correctOption":"A","correctAnswer":"External secondary research","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because publicly available demographic data compiled by government bodies is external secondary research.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the data was published by the government rather than internal sales ledgers.","C":"Incorrect because no new interviews were conducted.","D":"Incorrect because no trial product launch occurred."}}},{"id":"P1_U3_MCQ_417","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_417","question":"An automotive components supplier reads quarterly reports published by the National Motor Manufacturers' Trade Association to estimate annual electric-vehicle production growth. Why is this external secondary source helpful?","options":{"A":"Trade associations aggregate sector-wide production forecasts quickly and affordably for member businesses","B":"Trade association reports contain confidential prototypes of rival suppliers","C":"Trade association reports eliminate the need to negotiate contracts with carmakers","D":"Primary research is illegal in automotive manufacturing"},"correctOption":"A","correctAnswer":"Trade associations aggregate sector-wide production forecasts quickly and affordably for member businesses","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because industry bodies compile reliable macro-level sector data that individual SMEs could not gather independently.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because trade reports publish aggregate industry trends rather than rival trade secrets.","C":"Incorrect because B2B sales negotiations remain essential.","D":"Incorrect because primary customer research is lawful and common."}}},{"id":"P1_U3_MCQ_418","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_418","question":"An entrepreneur uses a free 2019 commercial real-estate report to pick a city-centre café site in 2026, ignoring how hybrid remote work reshaped office occupancy since then. Which weakness of 'secondary research' caused this mistake?","options":{"A":"Secondary data can become outdated quickly in fast-changing markets, leading to flawed decisions","B":"Secondary data is always more expensive than hiring 50 street interviewers","C":"Secondary reports never include numerical statistics","D":"Government and industry reports are legally forbidden from being read by startups"},"correctOption":"A","correctAnswer":"Secondary data can become outdated quickly in fast-changing markets, leading to flawed decisions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because historical secondary reports may no longer reflect current consumer habits or market conditions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because free secondary reports are far cheaper than primary fieldwork.","C":"Incorrect because secondary reports contain extensive quantitative tables.","D":"Incorrect because published reports are openly accessible."}}},{"id":"P1_U3_MCQ_419","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_419","question":"Which of the following findings from a hotel guest study represents 'qualitative data' rather than 'quantitative data'?","options":{"A":"Guests explained in interviews that dim hallway lighting made the corridor feel unsafe at night","B":"78% of surveyed guests rated room cleanliness 5 out of 5","C":"Average guest length of stay increased from 2.1 nights to 2.6 nights","D":"Room-service revenue rose by $14,500 in the third quarter"},"correctOption":"A","correctAnswer":"Guests explained in interviews that dim hallway lighting made the corridor feel unsafe at night","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because descriptive emotional feelings and perceptions about lighting safety represent non-numerical qualitative insight.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 78% and 5-point scores are numerical quantitative metrics.","C":"Incorrect because night counts are quantitative figures.","D":"Incorrect because dollar revenue is quantitative data."}}},{"id":"P1_U3_MCQ_420","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_420","question":"A national telecom company has 8 million mobile subscribers and wants to test reactions to a new family data plan. Why does it survey a sample of 1,500 subscribers rather than all 8 million?","options":{"A":"Surveying 8 million people would be prohibitively expensive and take too long, whereas a well-chosen sample gives accurate results quickly","B":"It is illegal to contact more than 2,000 customers in a survey","C":"Smaller samples are always 100% free of any statistical margin of error","D":"Telecom companies do not have phone numbers for their own subscribers"},"correctOption":"A","correctAnswer":"Surveying 8 million people would be prohibitively expensive and take too long, whereas a well-chosen sample gives accurate results quickly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sampling balances statistical reliability against practical time and budget constraints.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no legal cap restricts survey size.","C":"Incorrect because every sample carries some margin of sampling error.","D":"Incorrect because telecom firms hold subscriber billing records."}}},{"id":"P1_U3_MCQ_421","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_421","question":"A street-food vendor wants to use 'random sampling' to survey everyone who eats lunch in a busy public square, but has no list of visitors and passers-by hurry past refusing to stop. Why is pure random sampling impractical here?","options":{"A":"True random sampling requires a complete sampling frame (list of the entire population) and high cooperation from selected individuals","B":"Random sampling can only be used with open-ended essay questions","C":"Random sampling is forbidden in food and hospitality businesses","D":"Random sampling requires interviewing every person in the country"},"correctOption":"A","correctAnswer":"True random sampling requires a complete sampling frame (list of the entire population) and high cooperation from selected individuals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because without a master list of anonymous square visitors, every individual cannot be assigned an equal selection probability.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because random sampling works with closed and open questionnaires.","C":"Incorrect because food businesses can use random sampling when customer lists exist.","D":"Incorrect because interviewing everyone is a census rather than a sample."}}},{"id":"P1_U3_MCQ_422","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_422","question":"A shopping mall's visitor profile is 60% female and 40% male. If a market-research team uses 'quota sampling' to interview 300 shoppers, how many female and male shoppers must they interview?","options":{"A":"150 female and 150 male","B":"180 female and 120 male","C":"120 female and 180 male","D":"60 female and 40 male"},"correctOption":"B","correctAnswer":"180 female and 120 male","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because 60% of 300 = 180 female respondents, and 40% of 300 = 120 male respondents.","distractor_reasons":{"A":"Incorrect because 150/150 splits 50/50 instead of matching the 60/40 mall gender ratio.","B":"Correct selection.","C":"Incorrect because 120/180 reverses the female and male quotas.","D":"Incorrect because 60 + 40 equals only 100 respondents rather than 300."}}},{"id":"P1_U3_MCQ_423","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_423","question":"To estimate national demand for a $40 budget toaster, a researcher interviews 400 shoppers outside an ultra-luxury designer boutique district on a Tuesday morning. Why will the data be inaccurate?","options":{"A":"Location and time sampling bias: wealthy weekday boutique shoppers do not reflect the income or habits of average national toaster buyers","B":"400 interviews is too large a sample for a household appliance","C":"Budget toasters are secondary research products","D":"Shoppers outside luxury boutiques never own kitchen appliances"},"correctOption":"A","correctAnswer":"Location and time sampling bias: wealthy weekday boutique shoppers do not reflect the income or habits of average national toaster buyers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because surveying in an unrepresentative affluent district on a workday skews results away from mainstream buyers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 400 is a reasonable sample size if properly representative.","C":"Incorrect because toasters are physical consumer goods.","D":"Incorrect because the issue is unrepresentative income/lifestyle bias rather than zero ownership."}}},{"id":"P1_U3_MCQ_424","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_424","question":"In face-to-face street interviews, respondents claim they eat fast food 'less than once a month' and read 'four books a month', contradicting actual local fast-food sales and library records. What caused this research inaccuracy?","options":{"A":"Social-desirability bias: respondents give answers that make them look healthier or more cultured rather than admitting actual habits","B":"Secondary census calculation error","C":"Excessive use of random number generators","D":"High postal stamp prices"},"correctOption":"A","correctAnswer":"Social-desirability bias: respondents give answers that make them look healthier or more cultured rather than admitting actual habits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because people often under-report stigmatized habits and over-report virtuous ones in front of an interviewer.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the distortion arose from live interview answers.","C":"Incorrect because random selection does not cause dishonest self-reporting.","D":"Incorrect because the interviews were face-to-face."}}},{"id":"P1_U3_MCQ_425","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_425","question":"A marketing analyst wants to present how monthly online ice-cream orders rose and fell across all 36 months over the past three years to highlight seasonal peaks. Which chart format is clearest?","options":{"A":"A line graph plotting monthly sales over time","B":"A single pie chart showing 36 tiny slices","C":"An unformatted text paragraph listing 36 numbers","D":"A Venn diagram of factory staff"},"correctOption":"A","correctAnswer":"A line graph plotting monthly sales over time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because line graphs clearly reveal continuous trends, growth rates, and seasonal fluctuations across time.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a 36-slice pie chart is unreadable and hides chronological sequence.","C":"Incorrect because raw text numbers obscure visual seasonal waves.","D":"Incorrect because Venn diagrams show set overlaps rather than time series."}}},{"id":"P1_U3_MCQ_426","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_426","question":"An espresso-machine manufacturer sells compact pod coffee makers to households and heavy-duty three-group steam machines to commercial cafés. How are these two product lines classified?","options":{"A":"Household pod machines are consumer goods, whereas commercial café machines are producer (capital) goods","B":"Both machines are intangible consumer services","C":"Household pod machines are producer goods, whereas café machines are consumer goods","D":"Both machines are raw agricultural commodities"},"correctOption":"A","correctAnswer":"Household pod machines are consumer goods, whereas commercial café machines are producer (capital) goods","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because goods bought for personal household enjoyment are consumer goods, while equipment bought by businesses to produce services are producer goods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because physical machines are tangible goods rather than services.","C":"Incorrect because this reverses consumer and producer classifications.","D":"Incorrect because assembled appliances are manufactured goods."}}},{"id":"P1_U3_MCQ_427","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_427","question":"A cybersecurity consultancy provides 24/7 network-threat monitoring for hospitals and banks, while a mobile pet groomer washes dogs at families' homes. How do these offerings compare?","options":{"A":"Cybersecurity monitoring is a producer (B2B) service, whereas mobile dog grooming is a consumer service","B":"Both businesses sell tangible durable goods","C":"Dog grooming is a producer service, whereas hospital cybersecurity is a consumer service","D":"Neither business operates in the tertiary sector"},"correctOption":"A","correctAnswer":"Cybersecurity monitoring is a producer (B2B) service, whereas mobile dog grooming is a consumer service","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because services sold to organizations are producer services, while services sold to private households are consumer services.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both deliver intangible service activities.","C":"Incorrect because this reverses the business and household buyers.","D":"Incorrect because both operate in the tertiary service sector."}}},{"id":"P1_U3_MCQ_428","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_428","question":"A toy company generates 40 new board-game concepts, then eliminates 32 ideas after estimating production costs, safety rules, and likely retail demand before building any prototypes. Which NPD stage is this?","options":{"A":"Idea screening and business analysis","B":"Full commercial national rollout","C":"Decline-stage product withdrawal","D":"Mature extension packaging redesign"},"correctOption":"A","correctAnswer":"Idea screening and business analysis","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because screening filters out unfeasible or unprofitable ideas early before expensive prototype engineering begins.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because commercial launch is the final stage after testing.","C":"Incorrect because decline applies to aging existing products.","D":"Incorrect because extension strategies revive mature products."}}},{"id":"P1_U3_MCQ_429","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_429","question":"What is the main financial risk for a medical-device firm investing heavily in 'new product development (NPD)'?","options":{"A":"Substantial R&D and clinical testing costs are incurred upfront with no guarantee the product will pass trials or achieve commercial sales","B":"Successful new products are legally banned from earning a profit","C":"R&D spending reduces factory fixed overheads to zero","D":"New medical devices require no regulatory safety approval"},"correctOption":"A","correctAnswer":"Substantial R&D and clinical testing costs are incurred upfront with no guarantee the product will pass trials or achieve commercial sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because R&D outlays represent sunk costs that may never be recovered if technical or market failure occurs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because successful innovations earn strong patent-protected profits.","C":"Incorrect because R&D adds significant development costs.","D":"Incorrect because medical devices face strict regulatory approval."}}},{"id":"P1_U3_MCQ_430","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_430","question":"When a famous athletic-shoe brand raises sneaker prices by 8%, loyal runners continue buying its shoes instead of switching to unbranded trainers. How does 'brand image' create this effect?","options":{"A":"Emotional trust and perceived status make demand less price elastic, protecting profit margins against small price increases","B":"Unbranded trainers are legally banned from sports stores","C":"Strong brand image eliminates all rubber and stitching costs","D":"Runners are unable to see price tags in shoe shops"},"correctOption":"A","correctAnswer":"Emotional trust and perceived status make demand less price elastic, protecting profit margins against small price increases","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because brand loyalty reduces willingness to substitute, lowering price sensitivity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because budget unbranded trainers are widely sold.","C":"Incorrect because manufacturing material costs remain.","D":"Incorrect because buyers see prices and willingly pay the brand premium."}}},{"id":"P1_U3_MCQ_431","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_431","question":"Why do major supermarket chains willingly allocate prime eye-level shelf space to a leading global tomato-ketchup brand even though the brand offers lower wholesale discounts than unknown rivals?","options":{"A":"Strong consumer brand loyalty pulls shoppers into the store, and shoppers might switch supermarkets if the flagship ketchup is missing","B":"Ketchup manufacturers own all supermarket buildings","C":"Unknown ketchup brands taste identical and cost zero to stock","D":"Supermarkets are legally forced to put famous brands at eye level"},"correctOption":"A","correctAnswer":"Strong consumer brand loyalty pulls shoppers into the store, and shoppers might switch supermarkets if the flagship ketchup is missing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 'must-stock' brand equity gives manufacturers stronger bargaining power with retailers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supermarkets are independent retail businesses.","C":"Incorrect because supermarkets maximize profit per metre of shelf space.","D":"Incorrect because shelf placement is a commercial negotiation."}}},{"id":"P1_U3_MCQ_432","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_432","question":"A frozen-meal box displays cooking microwave wattage times, calorie tables, allergy warnings, a recycling symbol, and a scannable barcode. Which function of 'packaging' does this fulfill?","options":{"A":"Communicating essential consumer usage, nutritional, legal, and retail inventory information","B":"Preventing shoppers from knowing how to heat the meal","C":"Increasing shipping container fuel consumption","D":"Eliminating the need for frozen delivery trucks"},"correctOption":"A","correctAnswer":"Communicating essential consumer usage, nutritional, legal, and retail inventory information","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because packaging informs consumers safely while providing barcodes for retail checkout and stock control.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because heating instructions guide safe preparation.","C":"Incorrect because printed labels do not inflate freight fuel.","D":"Incorrect because frozen foods still require cold-chain transport."}}},{"id":"P1_U3_MCQ_433","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_433","question":"A headphone manufacturer replaces non-recyclable foam-and-plastic blister packaging with sleek, 100% recycled molded-pulp boxes printed with soy ink. How does this packaging change benefit the brand?","options":{"A":"It appeals to environmentally conscious buyers, improves brand reputation, and prepares the firm for stricter single-use plastic laws","B":"It guarantees that headphones will never break if dropped in water","C":"It eliminates all factory assembly wages","D":"It prevents online stores from shipping headphones by courier"},"correctOption":"A","correctAnswer":"It appeals to environmentally conscious buyers, improves brand reputation, and prepares the firm for stricter single-use plastic laws","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustainable packaging strengthens ethical brand positioning and reduces regulatory compliance risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because outer retail packaging does not waterproof the headphones during use.","C":"Incorrect because assembly wages remain unchanged.","D":"Incorrect because molded pulp protects products well during courier transit."}}},{"id":"P1_U3_MCQ_434","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_434","question":"On a Product Life Cycle cash-flow chart, why does the cash-flow line dip deepest below zero just before the 'Introduction' stage begins?","options":{"A":"Heavy cumulative spending on R&D, prototype testing, factory tooling, and launch promotion occurs before any sales revenue is earned","B":"Customers are paid cash bonuses to return the product","C":"Sales volume reaches its all-time peak during R&D","D":"Competitors steal all factory machinery before launch"},"correctOption":"A","correctAnswer":"Heavy cumulative spending on R&D, prototype testing, factory tooling, and launch promotion occurs before any sales revenue is earned","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because upfront capital and development outflows peak right as commercial launch starts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because negative cash flow reflects R&D and launch expenses.","C":"Incorrect because sales revenue is zero during R&D.","D":"Incorrect because the cash outflow is planned investment."}}},{"id":"P1_U3_MCQ_435","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_435","question":"During the 'Introduction' stage of a new plant-based protein snack bar, why does the brand hand out free sample bars at commuter train stations alongside informative posters?","options":{"A":"Consumers are unfamiliar with the new product's taste, so free trials overcome hesitation and build initial awareness","B":"The snack bar is already in the decline stage and being discontinued","C":"Free samples eliminate the need for supermarket distribution","D":"Informative promotion is only used when 90% of households already buy the product"},"correctOption":"A","correctAnswer":"Consumers are unfamiliar with the new product's taste, so free trials overcome hesitation and build initial awareness","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trial sampling and informative promotion educate early adopters and spark initial word-of-mouth.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sampling launches a new product rather than closing an old one.","C":"Incorrect because sampling drives shoppers into supermarkets to buy full boxes.","D":"Incorrect because reminder ads—not launch education—suit saturated mature products."}}},{"id":"P1_U3_MCQ_436","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_436","question":"As a robotic window-cleaner enters the 'Growth' stage of its Product Life Cycle, sales surge and three rival brands launch competing models. How should the firm adapt its promotion?","options":{"A":"Shift from purely explaining what the product does toward persuasive brand-preference advertising highlighting why its model is superior to rivals","B":"Stop all advertising completely because competitors have arrived","C":"Withdraw the robotic cleaner immediately before reaching maturity","D":"Cut distribution back to a single local hardware shop"},"correctOption":"A","correctAnswer":"Shift from purely explaining what the product does toward persuasive brand-preference advertising highlighting why its model is superior to rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because once consumers understand the product category, persuasive promotion defends brand share against imitators.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because stopping promotion lets rivals capture the expanding market.","C":"Incorrect because growth is a profitable expansion phase.","D":"Incorrect because distribution should widen during growth."}}},{"id":"P1_U3_MCQ_437","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_437","question":"A leading brand of household dishwashing tablets is in the 'Maturity' stage, where almost every dishwasher owner already buys tablets and four strong rivals compete on supermarket shelves. Which pricing and promotion mix is typical?","options":{"A":"Competitive pricing paired with reminder advertising and occasional multi-buy promotions to retain loyal buyers","B":"Extreme price skimming at triple rival prices with zero advertising","C":"Introductory penetration pricing below raw chemical cost for ten years","D":"Purely technical B2B trade-journal adverts explaining how dishwashers work"},"correctOption":"A","correctAnswer":"Competitive pricing paired with reminder advertising and occasional multi-buy promotions to retain loyal buyers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mature markets require competitive pricing and continuous brand reminders to prevent switching.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because skimming works only at initial innovative launch.","C":"Incorrect because selling below cost for years is financially unsustainable.","D":"Incorrect because households already know how dishwashing tablets work."}}},{"id":"P1_U3_MCQ_438","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_438","question":"A consumer-electronics firm still sells a legacy standalone GPS car-navigation unit whose sales fall 40% annually as drivers use free smartphone maps. Rather than spending on R&D or ads, the firm cuts marketing spend to zero and sells remaining stock at modest margins until demand vanishes. Which strategy is this?","options":{"A":"Harvesting a declining product to extract remaining cash before final withdrawal","B":"Launching a bold extension strategy","C":"Introductory price skimming","D":"Aggressive penetration pricing to capture 80% market share"},"correctOption":"A","correctAnswer":"Harvesting a declining product to extract remaining cash before final withdrawal","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because harvesting minimizes support costs on an irreversibly declining product to maximize short-term cash extraction.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no product updates or promotional investments are being made.","C":"Incorrect because skimming applies to new launches.","D":"Incorrect because investing to capture share in a dying category wastes capital."}}},{"id":"P1_U3_MCQ_439","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_439","question":"Sales of a traditional British malted hot drink have plateaued in the UK, so the manufacturer exports the drink to West African and Southeast Asian markets where rising middle-class demand creates rapid growth. Which 'extension strategy' is this?","options":{"A":"Entering new geographic markets to extend the product's overall life cycle","B":"Withdrawing the brand worldwide","C":"Switching to product-oriented factory closures","D":"Using predatory loss-leader pricing in UK supermarkets"},"correctOption":"A","correctAnswer":"Entering new geographic markets to extend the product's overall life cycle","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a product mature or declining in one country may be at the introduction/growth stage in overseas markets.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the firm is expanding internationally rather than withdrawing.","C":"Incorrect because export growth increases factory utilization.","D":"Incorrect because the strategy focuses on overseas market development."}}},{"id":"P1_U3_MCQ_440","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_440","question":"As sales of a popular gaming console slow in year five of its Product Life Cycle, the maker bundles two hit games into the box and lowers the console price by $100 to attract more budget-conscious families. What is the goal of this 'extension strategy'?","options":{"A":"To stimulate a fresh wave of demand from price-sensitive buyers and delay the onset of decline","B":"To reduce software game compatibility to zero","C":"To transition the console into a bespoke luxury collector's item","D":"To eliminate all retail store distribution"},"correctOption":"A","correctAnswer":"To stimulate a fresh wave of demand from price-sensitive buyers and delay the onset of decline","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because price reductions and value bundles unlock the remaining price-elastic segment of the market.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bundling games expands software value.","C":"Incorrect because lowering price targets mainstream families rather than luxury collectors.","D":"Incorrect because retail stores remain the main channel for console bundles."}}},{"id":"P1_U3_MCQ_441","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_441","question":"A lamp factory has fixed costs of $40,000 per month, produces 10,000 lamps per month, and incurs variable costs of $6 per lamp. If it uses cost-plus pricing with a 25% mark-up, what is the selling price per lamp?","options":{"A":"$10.00","B":"$12.50","C":"$7.50","D":"$14.00"},"correctOption":"B","correctAnswer":"$12.50","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Average Fixed Cost = $40,000 / 10,000 = $4.00; Total Unit Cost = $4.00 + $6.00 = $10.00; Selling Price = $10.00 × 1.25 = $12.50.","distractor_reasons":{"A":"Incorrect because $10.00 is the total unit cost before adding the 25% profit mark-up.","B":"Correct selection.","C":"Incorrect because $7.50 adds 25% only to the $6.00 variable cost and omits fixed costs.","D":"Incorrect because $14.00 adds a 40% mark-up instead of 25%."}}},{"id":"P1_U3_MCQ_442","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_442","question":"A furniture maker calculates its unit cost at $180 and adds a rigid 50% cost-plus mark-up to price its dining chairs at $270, even though rival stores sell nearly identical chairs for $195. What is the main flaw of 'cost-plus pricing' shown here?","options":{"A":"It ignores competitor prices and consumer willingness to pay, risking uncompetitive pricing if internal production costs are high","B":"Cost-plus pricing is mathematically impossible when fixed costs exist","C":"Cost-plus pricing guarantees zero profit even when every chair sells","D":"Furniture retailers are legally banned from using cost-plus formulas"},"correctOption":"A","correctAnswer":"It ignores competitor prices and consumer willingness to pay, risking uncompetitive pricing if internal production costs are high","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost-plus pricing looks solely at internal expenses rather than external market demand and rivalry.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fixed costs are allocated per unit to compute total unit cost.","C":"Incorrect because it guarantees a profit margin if units actually sell—the problem is low sales at an uncompetitive price.","D":"Incorrect because cost-plus is lawful and widely used."}}},{"id":"P1_U3_MCQ_443","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_443","question":"When three rival budget airlines match every $5 ticket cut on the same route using 'competitive pricing', fares fall below operating costs for all three carriers. What risk does strict competitive price-matching create?","options":{"A":"It can trigger a destructive price war that erodes industry-wide profit margins without increasing any single airline's market share","B":"Passengers stop flying when airfares become cheaper","C":"Jet fuel becomes completely free during airline price wars","D":"Competitive pricing guarantees a 50% net profit margin"},"correctOption":"A","correctAnswer":"It can trigger a destructive price war that erodes industry-wide profit margins without increasing any single airline's market share","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when rivals match cuts immediately, no firm gains relative share while all firms earn less per ticket.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower fares stimulate passenger volume, though at unprofitable margins.","C":"Incorrect because operating costs remain unchanged.","D":"Incorrect because price wars compress margins."}}},{"id":"P1_U3_MCQ_444","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_444","question":"A streaming-music startup launches at $2.99 per month using 'penetration pricing' to attract 500,000 subscribers, but when it raises the fee to $9.99 a year later, 60% of users cancel immediately. Which risk of penetration pricing occurred?","options":{"A":"Low launch prices attract bargain-hunters with weak brand loyalty who abandon the product once prices rise to profitable levels","B":"Penetration pricing sets launch prices too high for early adopters","C":"Streaming platforms pay zero music licensing royalties","D":"Penetration pricing is illegal in digital subscription businesses"},"correctOption":"A","correctAnswer":"Low launch prices attract bargain-hunters with weak brand loyalty who abandon the product once prices rise to profitable levels","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because buyers acquired purely on rock-bottom price often churn when normal pricing is introduced.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because setting high initial prices describes price skimming.","C":"Incorrect because streaming firms pay significant royalties.","D":"Incorrect because introductory promotional pricing is lawful."}}},{"id":"P1_U3_MCQ_445","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_445","question":"A kitchen-gadget firm launches an unpatented electric avocado slicer at $89 using 'price skimming'. Within two months, six competitors launch identical slicers at $24, collapsing the pioneer's sales. Why did price skimming fail here?","options":{"A":"Lack of patent protection and low barriers to entry meant high initial profit margins rapidly attracted low-cost imitators","B":"Price skimming works best for basic unpatented commodities","C":"Consumers prefer paying $89 even when identical $24 alternatives exist","D":"Price skimming sets the initial price below variable manufacturing cost"},"correctOption":"A","correctAnswer":"Lack of patent protection and low barriers to entry meant high initial profit margins rapidly attracted low-cost imitators","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustainable skimming requires strong intellectual property or technical barriers to delay copycats.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because commodities cannot sustain high skimming premiums.","C":"Incorrect because price-conscious buyers quickly switch to identical cheaper versions.","D":"Incorrect because skimming sets high prices well above unit cost."}}},{"id":"P1_U3_MCQ_446","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_446","question":"A supermarket sells fresh rotisserie chickens and cartons of milk below wholesale cost ('loss leaders') near the back of the store. How does this 'promotional pricing' tactic increase overall supermarket profit?","options":{"A":"Bargain staples draw shoppers into the store, where they walk past high-margin aisles and fill trolleys with profitable items","B":"Selling milk below cost generates a direct profit on every milk carton sold","C":"Suppliers pay supermarkets to throw away unsold chickens","D":"Shoppers are legally forced to spend at least $100 before leaving"},"correctOption":"A","correctAnswer":"Bargain staples draw shoppers into the store, where they walk past high-margin aisles and fill trolleys with profitable items","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because loss leaders drive store footfall so total basket margin outweighs the small loss on the promotional staple.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a loss leader loses money on the individual item itself.","C":"Incorrect because the retailer absorbs the promotional discount.","D":"Incorrect because shoppers buy other items voluntarily out of convenience."}}},{"id":"P1_U3_MCQ_447","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_447","question":"A Swiss watchmaker prices its mechanical chronographs at $6,500 rather than $1,500 because affluent buyers associate the higher price with rarity, precision craftsmanship, and social prestige. Which pricing strategy is this?","options":{"A":"Prestige / psychological pricing","B":"Penetration launch pricing","C":"Loss-leader clearance pricing","D":"Predatory price cutting"},"correctOption":"A","correctAnswer":"Prestige / psychological pricing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because psychological pricing uses price cues—either charm endings ($9.99) or luxury prestige figures ($6,500)—to shape perceived value.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because penetration pricing sets low entry prices.","C":"Incorrect because $6,500 is a high luxury price rather than a clearance discount.","D":"Incorrect because predatory pricing slashes prices below cost to bankrupt rivals."}}},{"id":"P1_U3_MCQ_448","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_448","question":"During a sudden torrential rainstorm, a ride-hailing app's algorithm automatically doubles trip fares ('dynamic pricing') to attract more drivers onto the roads, sparking angry social-media posts from stranded riders. What trade-off of dynamic pricing does this show?","options":{"A":"While dynamic pricing balances real-time supply and demand and maximizes peak revenue, sharp price spikes risk customer resentment and brand backlash","B":"Dynamic pricing keeps fares identical 24 hours a day regardless of weather","C":"Dynamic pricing eliminates the need for drivers or vehicles","D":"Surge fares always lose money for ride-hailing platforms"},"correctOption":"A","correctAnswer":"While dynamic pricing balances real-time supply and demand and maximizes peak revenue, sharp price spikes risk customer resentment and brand backlash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because algorithmic surge pricing optimizes short-term market clearing but can feel exploitative during emergencies.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because dynamic pricing changes prices continuously with demand.","C":"Incorrect because higher fares incentivize human drivers to log on.","D":"Incorrect because higher fares boost per-trip commission revenue."}}},{"id":"P1_U3_MCQ_449","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_449","question":"When a commuter rail operator increases monthly season-ticket prices by 10% (from $200 to $220), ticket sales fall by 4% (from 5,000 to 4,800 passes). What is the Price Elasticity of Demand (PED), and is demand elastic or inelastic?","options":{"A":"PED = 0.4 (price inelastic)","B":"PED = 2.5 (price elastic)","C":"PED = 1.0 (unitary elastic)","D":"PED = 6.0 (perfectly elastic)"},"correctOption":"A","correctAnswer":"PED = 0.4 (price inelastic)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because PED = % Change in Quantity Demanded / % Change in Price = 4% / 10% = 0.4; since 0.4 < 1, demand is price inelastic.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 2.5 divides 10% by 4% (inverting the PED formula).","C":"Incorrect because unitary elasticity requires equal percentage changes.","D":"Incorrect because 6.0 subtracts 4% from 10% instead of dividing."}}},{"id":"P1_U3_MCQ_450","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_450","question":"A water-utility company knows that household demand for tap water is highly 'price inelastic' (PED = 0.15). What will happen to the utility's total sales revenue if it cuts water prices by 20%?","options":{"A":"Total revenue will fall because the 20% price cut triggers only a tiny 3% increase in water consumption","B":"Total revenue will double because households will drink ten times more water","C":"Total revenue will remain completely unchanged","D":"Demand will become infinitely price elastic"},"correctOption":"A","correctAnswer":"Total revenue will fall because the 20% price cut triggers only a tiny 3% increase in water consumption","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because for price-inelastic goods, lowering price reduces revenue per unit far more than the small volume gain.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because water usage is constrained by practical household needs.","C":"Incorrect because revenue stays constant only when PED = 1.0.","D":"Incorrect because PED remains 0.15."}}},{"id":"P1_U3_MCQ_451","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_451","question":"A manufacturer of custom-engineered hydroelectric power turbines sells directly to national electricity utilities without using wholesalers or retail shops. Why is this 'zero-intermediary direct channel' essential?","options":{"A":"High-value B2B industrial equipment is built to bespoke engineering specifications and requires direct technical collaboration between producer and buyer","B":"Supermarkets refuse to stock hydroelectric turbines due to shelf weight","C":"Electricity utilities buy turbines on impulse every weekend","D":"Wholesalers are legally barred from buying industrial machinery"},"correctOption":"A","correctAnswer":"High-value B2B industrial equipment is built to bespoke engineering specifications and requires direct technical collaboration between producer and buyer","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because complex capital projects involve direct tendering, engineering customization, and installation support.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because consumer retail stores are irrelevant to power-station infrastructure.","C":"Incorrect because turbines are multi-million-dollar capital investments.","D":"Incorrect because the channel choice reflects technical complexity rather than legal bans."}}},{"id":"P1_U3_MCQ_452","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_452","question":"A producer of chilled fresh sushi boxes supplies refrigerated distribution depots of major supermarket chains directly (Producer -> Retailer -> Consumer). Why is a wholesaler omitted here?","options":{"A":"Chilled sushi has a 48-hour shelf life, so skipping wholesalers preserves freshness while supermarkets buy in large enough volumes to deal direct","B":"Wholesalers charge zero profit margin on fresh seafood","C":"Supermarkets prepare all sushi inside their parking lots","D":"Sushi boxes can be stored unrefrigerated for six months"},"correctOption":"A","correctAnswer":"Chilled sushi has a 48-hour shelf life, so skipping wholesalers preserves freshness while supermarkets buy in large enough volumes to deal direct","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because short shelf-life perishables need fast cold-chain delivery and large retail chains possess centralized logistics.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because wholesalers charge a margin for storage and breaking bulk.","C":"Incorrect because central kitchens supply supermarket depots.","D":"Incorrect because raw fish products are highly perishable."}}},{"id":"P1_U3_MCQ_453","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_453","question":"A confectionery giant sells chocolate bars to regional wholesalers, who then supply 45,000 small rural newsagents and village kiosks (Producer -> Wholesaler -> Retailer -> Consumer). Why is this three-tier channel efficient?","options":{"A":"Delivery vans from the factory would lose money making thousands of tiny drop-offs to remote kiosks, whereas wholesalers consolidate mixed deliveries locally","B":"Chocolate bars spoil within four hours of leaving the factory","C":"Rural kiosks buy full 40-foot shipping containers of chocolate every week","D":"Manufacturers are legally prohibited from selling directly to small shops"},"correctOption":"A","correctAnswer":"Delivery vans from the factory would lose money making thousands of tiny drop-offs to remote kiosks, whereas wholesalers consolidate mixed deliveries locally","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because wholesalers achieve transport economies by bundling many brands into single deliveries for fragmented small retailers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because packaged chocolate has a long shelf life.","C":"Incorrect because small kiosks lack space and cash for full containers.","D":"Incorrect because direct delivery is legal, simply uneconomical for tiny orders."}}},{"id":"P1_U3_MCQ_454","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_454","question":"Besides 'breaking bulk', how does a 'wholesaler' assist small independent clothing boutiques financially and operationally?","options":{"A":"By storing seasonal inventory in regional warehouses and offering 30-day trade credit so boutiques can sell stock before paying","B":"By designing and sewing all garments inside the boutique's fitting rooms","C":"By paying the boutique owner's personal home mortgage","D":"By guaranteeing that every dress will sell at full price"},"correctOption":"A","correctAnswer":"By storing seasonal inventory in regional warehouses and offering 30-day trade credit so boutiques can sell stock before paying","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because wholesalers absorb inventory holding risk and ease retailer working-capital pressure via trade credit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because garment manufacturing happens in factories.","C":"Incorrect because trade credit supports business inventory rather than personal bills.","D":"Incorrect because retailers still bear fashion-markdown risk."}}},{"id":"P1_U3_MCQ_455","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_455","question":"How do 'retailers' add value for both manufacturers and everyday shoppers in the distribution chain?","options":{"A":"They gather thousands of complementary products in convenient local stores, display them attractively, and assist shoppers at the point of purchase","B":"They manufacture raw steel and plastic polymers for factories","C":"They act solely as commission agents who never hold physical stock","D":"They prevent consumers from comparing rival brands in one place"},"correctOption":"A","correctAnswer":"They gather thousands of complementary products in convenient local stores, display them attractively, and assist shoppers at the point of purchase","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retail assortment, convenient hours, and local accessibility bridge factory output with household shopping habits.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raw-material extraction belongs to primary/secondary sectors.","C":"Incorrect because retailers purchase and hold physical store inventory.","D":"Incorrect because multi-brand stores enable convenient comparison."}}},{"id":"P1_U3_MCQ_456","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_456","question":"A New Zealand organic honey exporter hires a Tokyo-based 'agent' to negotiate listings with Japanese gourmet department stores. Why is an agent useful when entering an unfamiliar overseas market?","options":{"A":"The agent possesses established local retail relationships, language fluency, and customs knowledge, earning commission only when orders are secured","B":"The agent buys the entire New Zealand bee farm outright","C":"The agent eliminates all Japanese food import safety inspections","D":"Agents work completely free of charge without commission or fees"},"correctOption":"A","correctAnswer":"The agent possesses established local retail relationships, language fluency, and customs knowledge, earning commission only when orders are secured","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because commission-based local agents lower fixed market-entry overhead while bridging cultural and B2B network barriers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because agents act as commercial intermediaries rather than acquirers.","C":"Incorrect because imported foods must still pass Japanese customs and health checks.","D":"Incorrect because agents earn a percentage commission on sales arranged."}}},{"id":"P1_U3_MCQ_457","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_457","question":"A manufacturer of medical ultrasound scanners distributes its machines through specialist regional medical-equipment dealers with trained clinical demonstrators rather than general online marketplaces. Which factor determined this 'Place' choice?","options":{"A":"Technical product complexity requiring hands-on demonstration, staff training, and certified maintenance support","B":"Ultrasound scanners are cheap impulse buys for teenagers","C":"General online marketplaces are illegal for medical devices","D":"Specialist dealers charge zero wholesale margin"},"correctOption":"A","correctAnswer":"Technical product complexity requiring hands-on demonstration, staff training, and certified maintenance support","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because complex diagnostic equipment requires expert pre-sale demonstration and reliable after-sale calibration.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because scanners are expensive clinical capital assets.","C":"Incorrect because the choice is driven by clinical training needs rather than legality.","D":"Incorrect because specialist dealers earn margins/fees for technical support."}}},{"id":"P1_U3_MCQ_458","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_458","question":"Why is mint chewing gum sold across hundreds of thousands of checkout counters, vending machines, and kiosks ('intensive distribution'), whereas grand pianos are sold in only a handful of city showrooms?","options":{"A":"Chewing gum is a low-cost frequent impulse purchase where immediate convenience drives sales, whereas grand pianos are rare, high-involvement purchases buyers travel to inspect","B":"Chewing gum spoils within two hours unless kept in vending machines","C":"Grand pianos are cheap everyday items bought at petrol stations","D":"Supermarkets refuse to sell chewing gum due to high weight"},"correctOption":"A","correctAnswer":"Chewing gum is a low-cost frequent impulse purchase where immediate convenience drives sales, whereas grand pianos are rare, high-involvement purchases buyers travel to inspect","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shopping frequency and buyer effort determine whether a product needs maximum convenience outlets or selective/exclusive showrooms.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because gum has a long shelf life.","C":"Incorrect because grand pianos are major luxury investments.","D":"Incorrect because gum is lightweight and profitable at checkouts."}}},{"id":"P1_U3_MCQ_459","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_459","question":"A clothing retailer lets shoppers order jackets on its smartphone app, pick them up two hours later at a local store, and exchange sizes free of charge at any branch. How does this 'omnichannel' strategy benefit the retailer?","options":{"A":"It combines online browsing convenience with instant store collection and drives extra footfall into physical shops where buyers often purchase additional items","B":"It eliminates the need to maintain accurate inventory tracking across warehouses and shops","C":"It forces online buyers to pay double shipping charges","D":"It closes all physical branches permanently"},"correctOption":"A","correctAnswer":"It combines online browsing convenience with instant store collection and drives extra footfall into physical shops where buyers often purchase additional items","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because integrating digital and physical channels reduces return friction and boosts cross-selling inside stores.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because omnichannel retail requires tightly integrated real-time stock systems.","C":"Incorrect because click-and-collect saves delivery fees.","D":"Incorrect because physical branches serve as collection and exchange hubs."}}},{"id":"P1_U3_MCQ_460","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_460","question":"How has rapid 'e-commerce' growth pressured traditional high-street book and electronics stores?","options":{"A":"Physical stores carry heavy fixed property rents and local business rates while online rivals operate from lower-cost out-of-town fulfilment warehouses","B":"High-street stores are legally banned from displaying prices in shop windows","C":"Online retailers pay 90% higher corporate income tax than high-street shops","D":"Consumers are prohibited from walking into city-centre shops"},"correctOption":"A","correctAnswer":"Physical stores carry heavy fixed property rents and local business rates while online rivals operate from lower-cost out-of-town fulfilment warehouses","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high-street fixed occupancy overheads make matching pure-play online prices difficult unless stores offer experiential value.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because displaying prices is standard and often legally required.","C":"Incorrect because online warehouses typically incur lower property taxes per dollar of sales.","D":"Incorrect because footfall shifted voluntarily toward online convenience."}}},{"id":"P1_U3_MCQ_461","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_461","question":"An online fashion retailer offers free return shipping and sees 38% of dresses sent back after customers wear them once for weekend parties ('wardrobing'). Which operational challenge of 'e-commerce' does this highlight?","options":{"A":"High reverse-logistics costs, damaged/worn returned stock, and potential payment fraud erode online profit margins","B":"Online fashion stores never have to pay for website hosting or cybersecurity","C":"E-commerce laws forbid customers from returning clothes that do not fit","D":"Returned dresses automatically double in resale value"},"correctOption":"A","correctAnswer":"High reverse-logistics costs, damaged/worn returned stock, and potential payment fraud erode online profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high apparel return rates create expensive inspection, repackaging, and markdown losses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cybersecurity and platform maintenance are major ongoing costs.","C":"Incorrect because distance-selling rules protect genuine sizing returns.","D":"Incorrect because returned items often require heavy discounting or disposal."}}},{"id":"P1_U3_MCQ_462","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_462","question":"After false rumours circulate online that a bottled-juice brand uses banned artificial dyes, the company publishes independent lab certificates and factory transparency videos across major news sites. Which aim of 'promotion' is this?","options":{"A":"Defending and restoring brand reputation by correcting public misinformation","B":"Calculating unit variable manufacturing costs","C":"Harvesting a declining product prior to liquidation","D":"Conducting random quota sampling of fruit farmers"},"correctOption":"A","correctAnswer":"Defending and restoring brand reputation by correcting public misinformation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because crisis communication and transparent evidence protect consumer trust and prevent sudden sales collapse.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cost calculation belongs to Finance/Operations.","C":"Incorrect because the brand is actively investing to protect ongoing sales.","D":"Incorrect because the campaign communicates outward to consumers."}}},{"id":"P1_U3_MCQ_463","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_463","question":"A luxury fragrance house airs cinematic adverts showing glamorous Parisian evening galas without mentioning perfume ingredients or bottle prices. Which promotional goal is being pursued?","options":{"A":"Building an aspirational brand image and emotional desirability through persuasive advertising","B":"Providing factual technical assembly instructions","C":"Clearing damaged warehouse stock via loss-leader discounts","D":"Explaining how a brand-new invention functions for the first time"},"correctOption":"A","correctAnswer":"Building an aspirational brand image and emotional desirability through persuasive advertising","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lifestyle imagery creates symbolic status value that differentiates luxury fragrances.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because perfumes need no technical assembly.","C":"Incorrect because luxury prestige campaigns avoid bargain clearance messaging.","D":"Incorrect because consumers already understand how perfume is used."}}},{"id":"P1_U3_MCQ_464","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_464","question":"Why do pharmaceutical companies rely on 'informative advertising' listing active ingredients, dosage guidelines, and clinical trial efficacy when promoting allergy medicines to pharmacists?","options":{"A":"Healthcare professionals make purchasing recommendations based on verified clinical facts rather than emotional lifestyle slogans","B":"Informative adverts are always free to publish in medical journals","C":"Pharmacists are legally forbidden from reading clinical trial results","D":"Allergy medicines have zero competition from rival brands"},"correctOption":"A","correctAnswer":"Healthcare professionals make purchasing recommendations based on verified clinical facts rather than emotional lifestyle slogans","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because technical and medical audiences require objective evidence to evaluate safety and effectiveness.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because medical journal ad space is paid.","C":"Incorrect because clinical data is essential to pharmacy practice.","D":"Incorrect because multiple rival antihistamine brands compete."}}},{"id":"P1_U3_MCQ_465","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_465","question":"A national supermarket chain spends $2 million on a festive 'television advertising' campaign. What is a key advantage of TV over local flyers, alongside its main drawback?","options":{"A":"TV combines sight, sound, and emotion to reach millions of households simultaneously, but requires very high production and airtime budgets","B":"TV adverts cost almost nothing to produce, but can only be seen by 50 people","C":"TV adverts allow viewers to click directly on bananas inside the screen to buy them instantly without internet","D":"TV advertising is legal only for B2B industrial steel manufacturers"},"correctOption":"A","correctAnswer":"TV combines sight, sound, and emotion to reach millions of households simultaneously, but requires very high production and airtime budgets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because broadcast television delivers unmatched mass reach and storytelling impact at a high absolute cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this reverses TV's high cost and massive reach.","C":"Incorrect because traditional broadcast TV lacks direct click-to-cart interactivity.","D":"Incorrect because consumer supermarkets are among the biggest TV advertisers."}}},{"id":"P1_U3_MCQ_466","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_466","question":"A family-owned emergency plumbing business operating within one town advertises on 'local commercial radio' during morning commuter drive-time. Why is local radio well suited to this business?","options":{"A":"It reaches local residents across the exact service area repeatedly at a fraction of national TV costs, building memorable phone-number recall","B":"Local radio broadcasts worldwide to every continent","C":"Radio adverts allow plumbers to show 20-page technical blueprints","D":"Local radio stations air business adverts completely free"},"correctOption":"A","correctAnswer":"It reaches local residents across the exact service area repeatedly at a fraction of national TV costs, building memorable phone-number recall","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because regional radio avoids wasted geographic coverage while audio jingles reinforce emergency recall.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because regional radio targets the local broadcast area.","C":"Incorrect because radio is purely audio without visual diagrams.","D":"Incorrect because commercial radio charges airtime rates."}}},{"id":"P1_U3_MCQ_467","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_467","question":"A fast-food chain places large billboards along major commuter highways. Why must billboard adverts use only a bold product photo, brand logo, and five or fewer words?","options":{"A":"Passing drivers and commuters only glance at roadside billboards for 2–3 seconds, so lengthy text goes unread","B":"Printing more than five words on a billboard is a criminal offence","C":"Billboards are placed exclusively inside quiet university libraries","D":"Highway billboards cost more per word printed"},"correctOption":"A","correctAnswer":"Passing drivers and commuters only glance at roadside billboards for 2–3 seconds, so lengthy text goes unread","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because brief visual exposure requires instant, uncluttered message comprehension.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because brevity is a practical communication rule rather than a criminal law.","C":"Incorrect because billboards sit outdoors along roads and stations.","D":"Incorrect because billboard rates are priced by site location and size rather than word count."}}},{"id":"P1_U3_MCQ_468","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_468","question":"A skincare startup pays a popular fitness influencer $15,000 to review its sunscreen on social media, but a week later the influencer becomes involved in a major public scandal. Which risk of 'influencer marketing' is demonstrated?","options":{"A":"The brand's reputation becomes closely tied to an external individual whose personal controversies can damage consumer trust","B":"Social media influencers have zero followers under age 60","C":"Influencer posts are legally required to be broadcast on national radio","D":"Influencer marketing eliminates all sunscreen manufacturing costs"},"correctOption":"A","correctAnswer":"The brand's reputation becomes closely tied to an external individual whose personal controversies can damage consumer trust","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because partnering with human creators introduces reputational spillover risk outside the firm's direct control.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because influencers have large, highly engaged audiences.","C":"Incorrect because influencer content runs on social platforms.","D":"Incorrect because production costs remain unchanged."}}},{"id":"P1_U3_MCQ_469","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_469","question":"A gourmet cheese producer sets up a tasting counter at the end of a supermarket aisle offering warm brie on crackers alongside a bright 'Point-of-Sale (POS)' display stand. How does this sales promotion boost sales?","options":{"A":"Sensory sampling reduces perceived taste risk and triggers immediate impulse purchases right where shoppers make buying decisions","B":"It forces shoppers to order cheese by postal mail six weeks later","C":"It replaces the need to pay supermarket listing fees","D":"It prevents shoppers from seeing rival cheeses in the dairy fridge"},"correctOption":"A","correctAnswer":"Sensory sampling reduces perceived taste risk and triggers immediate impulse purchases right where shoppers make buying decisions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because in-store sampling and prominent end-of-aisle POS stands convert hesitation into instant basket additions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shoppers pick up packs immediately at the display.","C":"Incorrect because supermarkets charge fees for prime end-cap promotional spaces.","D":"Incorrect because rival cheeses remain stocked in the dairy aisle."}}},{"id":"P1_U3_MCQ_470","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_470","question":"A breakfast-cereal brand prints '$1.50 Off Your Next Box' coupons inside its cereal cartons. How does this 'sales promotion' encourage repeat buying without permanently cutting shelf prices?","options":{"A":"Only price-sensitive shoppers who buy the first box and redeem the coupon receive the discount, encouraging a second purchase while regular buyers still pay full price","B":"Supermarkets must lower shelf prices for every shopper worldwide forever","C":"Coupons eliminate all cardboard printing and oat costs","D":"Competitors are legally forbidden from selling cereal during coupon promotions"},"correctOption":"A","correctAnswer":"Only price-sensitive shoppers who buy the first box and redeem the coupon receive the discount, encouraging a second purchase while regular buyers still pay full price","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because targeted coupons reward repeat purchase behavior selectively without eroding margins across all customers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because coupons apply only when redeemed at checkout.","C":"Incorrect because printing and coupon redemption incur promotional costs.","D":"Incorrect because rivals continue competing normally."}}},{"id":"P1_U3_MCQ_471","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_471","question":"A regional construction firm sponsors local youth football jerseys and funds a community riverside park cleanup, earning positive coverage in local newspapers. How does this 'Public Relations (PR)' activity benefit the business?","options":{"A":"It builds community goodwill, enhances corporate reputation, and keeps the brand visible to local homeowners and council planners","B":"It guarantees that the firm wins every government building contract without submitting bids","C":"It eliminates all cement and worker safety equipment costs","D":"PR sponsorship is legally tax-free up to 100% of company revenue"},"correctOption":"A","correctAnswer":"It builds community goodwill, enhances corporate reputation, and keeps the brand visible to local homeowners and council planners","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because community sponsorship fosters positive stakeholder sentiment and earned local media coverage.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because public contracts still require competitive tendering.","C":"Incorrect because construction materials and safety costs remain.","D":"Incorrect because sponsorship is a normal business expense rather than a 100% revenue tax exemption."}}},{"id":"P1_U3_MCQ_472","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_472","question":"A dental-implant manufacturer employs qualified dental-hygienist sales representatives to visit private dental clinics and demonstrate surgical implant kits. Why is high-cost 'personal selling' justified here?","options":{"A":"Each clinic that adopts the system generates tens of thousands of dollars in recurring annual implant orders, easily covering the rep's salary","B":"Dental implants are low-priced impulse snacks bought by children","C":"Personal selling is cheaper per contact than posting a free social-media photo","D":"Dental clinics are legally forbidden from reading product brochures"},"correctOption":"A","correctAnswer":"Each clinic that adopts the system generates tens of thousands of dollars in recurring annual implant orders, easily covering the rep's salary","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high customer lifetime value and technical training needs make face-to-face B2B consultative selling highly profitable.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because surgical implants are specialized clinical products.","C":"Incorrect because field sales reps have a high cost per visit.","D":"Incorrect because brochures support—rather than replace—clinical demonstrations."}}},{"id":"P1_U3_MCQ_473","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_473","question":"An online furniture retailer sends an automated email two hours after a logged-in shopper leaves a sofa in their digital shopping basket, offering free fabric swatches and a 5% completion code. Which promotional tool is this?","options":{"A":"Targeted direct marketing","B":"Above-the-line broadcast television advertising","C":"Public relations press conference","D":"Wholesale trade-fair exhibition"},"correctOption":"A","correctAnswer":"Targeted direct marketing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sending a personalized, action-triggered offer directly to an identified prospect exemplifies modern direct marketing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because TV ads broadcast identical messages to mass audiences.","C":"Incorrect because PR targets media journalists and the public.","D":"Incorrect because trade fairs target B2B retail buyers."}}},{"id":"P1_U3_MCQ_474","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_474","question":"A sportswear brand allocates a quarterly promotional budget of $45,000: 50% to digital ads, 30% to PR and sporting events, and 20% to in-store displays. How much does the brand spend on PR and sporting events?","options":{"A":"$9,000","B":"$13,500","C":"$22,500","D":"$15,000"},"correctOption":"B","correctAnswer":"$13,500","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because 30% of $45,000 = 0.30 × $45,000 = $13,500.","distractor_reasons":{"A":"Incorrect because $9,000 is 20% (in-store displays).","B":"Correct selection.","C":"Incorrect because $22,500 is 50% (digital ads).","D":"Incorrect because $15,000 is one-third (33.3%) rather than 30%."}}},{"id":"P1_U3_MCQ_475","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_475","question":"A budget cosmetics brand launches a viral short-video makeup challenge encouraging customers to post before-and-after clips using its $6 lip tint. How does 'user-generated content (UGC)' reduce promotional costs?","options":{"A":"Enthusiastic customers create and share authentic product demonstrations voluntarily, amplifying organic reach without paying for every view","B":"Short-video platforms pay companies $100 every time a user uploads a video","C":"UGC eliminates all cosmetics manufacturing and packaging expenses","D":"UGC guarantees that zero negative reviews will ever appear online"},"correctOption":"A","correctAnswer":"Enthusiastic customers create and share authentic product demonstrations voluntarily, amplifying organic reach without paying for every view","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because peer-created social videos act as low-cost, credible word-of-mouth endorsements.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because platforms do not pay brands per user upload.","C":"Incorrect because physical production costs still apply.","D":"Incorrect because open social campaigns can also attract critical comments."}}},{"id":"P1_U3_MCQ_476","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_476","question":"A newly launched cloud-accounting software firm sets 'rapid market-share acquisition' as its top objective for Year 1. Which marketing strategy best aligns with this objective?","options":{"A":"Penetration subscription pricing with a free 60-day trial, self-serve online onboarding, and targeted small-business search/social ads","B":"High price skimming at triple rival fees, sold only via printed postal brochures with zero free trial","C":"Harvesting cash by cutting product support and stopping all advertising","D":"Selling exclusively to 10 multinational banks via five-year custom tenders"},"correctOption":"A","correctAnswer":"Penetration subscription pricing with a free 60-day trial, self-serve online onboarding, and targeted small-business search/social ads","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because low entry pricing, friction-free online signup, and broad SME digital promotion maximize fast user adoption.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because high prices and slow postal brochures restrict rapid adoption.","C":"Incorrect because harvesting applies to dying products rather than Year 1 growth.","D":"Incorrect because slow enterprise tenders yield few accounts in Year 1."}}},{"id":"P1_U3_MCQ_477","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_477","question":"A luggage manufacturer designs a durable, water-resistant carry-on backpack for budget university backpackers. Which 4Ps marketing mix is most consistent with this target segment?","options":{"A":"Practical multi-pocket nylon backpack (Product), affordable $49 pricing (Price), direct online store and campus pop-ups (Place), and student social-media/referral discounts (Promotion)","B":"Hand-stitched alligator-leather trunk (Product), $4,500 prestige pricing (Price), five-star hotel boutiques (Place), and private-jet magazine ads (Promotion)","C":"Nylon backpack (Product), $49 pricing (Price), sold solely at airport first-class lounges (Place), and medical trade-journal ads (Promotion)","D":"Unlabelled cardboard boxes (Product), $500 cost-plus pricing (Price), wholesale steel depots (Place), and zero promotion"},"correctOption":"A","correctAnswer":"Practical multi-pocket nylon backpack (Product), affordable $49 pricing (Price), direct online store and campus pop-ups (Place), and student social-media/referral discounts (Promotion)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because functional durability, student-friendly price, digital/campus access, and peer referral promotion fit student travellers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $4,500 luxury trunks target ultra-wealthy travellers.","C":"Incorrect because first-class lounges and medical journals do not reach university backpackers.","D":"Incorrect because $500 cardboard boxes fail to meet student travel needs."}}},{"id":"P1_U3_MCQ_478","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_478","question":"An organic cold-pressed face serum made with rare botanical oils is priced at $140 per bottle, but distributed in plastic bargain bins next to $2 paper towels in discount supermarkets with photocopied black-and-white flyers. Why is this marketing strategy failing?","options":{"A":"The 4Ps are inconsistent: discount Place and cheap Promotion destroy the luxury credibility needed to justify a $140 Product and Price","B":"Organic face serums are legally banned from costing over $5","C":"Discount supermarket shoppers prefer buying $140 serums out of bargain bins","D":"Photocopied flyers are too expensive for skincare brands"},"correctOption":"A","correctAnswer":"The 4Ps are inconsistent: discount Place and cheap Promotion destroy the luxury credibility needed to justify a $140 Product and Price","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because all four elements of the marketing mix must send a unified positioning message to target buyers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because luxury skincare regularly sells above $100 in upscale boutiques.","C":"Incorrect because luxury buyers expect upscale retail environments and polished branding.","D":"Incorrect because flyers are cheap; the problem is cheap brand positioning."}}},{"id":"P1_U3_MCQ_479","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_479","question":"How should a cordless robotic lawnmower manufacturer adapt its marketing strategy as the product transitions from 'Introduction' into 'Maturity'?","options":{"A":"Broaden Place from specialist garden centres to mass DIY superstores, shift Price from skimming to competitive tiers, and introduce trade-in upgrade promotions","B":"Narrow distribution back to a single showroom and double the original launch price","C":"Stop all customer support and withdraw the product while sales are at their peak","D":"Run purely educational adverts explaining that grass grows in summer"},"correctOption":"A","correctAnswer":"Broaden Place from specialist garden centres to mass DIY superstores, shift Price from skimming to competitive tiers, and introduce trade-in upgrade promotions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mature mass adoption requires wider retail reach, competitive pricing, and replacement incentives.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because narrowing distribution and doubling prices shrinks mature market share.","C":"Incorrect because peak maturity is the most profitable phase to defend.","D":"Incorrect because mature buyers already understand basic product function."}}},{"id":"P1_U3_MCQ_480","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_480","question":"During a severe economic recession when household disposable incomes fall, a mid-market pasta-sauce brand sees shoppers switching to cheap supermarket own-label jars. Which strategic adjustment protects volume and brand loyalty?","options":{"A":"Introduce larger 'Family Value' jars with lower cost per gram and run recipe promotions showing how to cook nutritious $2 family meals at home","B":"Raise jar prices by 45% without changing ingredients or pack size","C":"Stop supplying supermarkets and sell jars only at luxury airport boutiques","D":"Cut sauce quality secretly while keeping high luxury prices"},"correctOption":"A","correctAnswer":"Introduce larger 'Family Value' jars with lower cost per gram and run recipe promotions showing how to cook nutritious $2 family meals at home","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because emphasizing value-for-money and affordable home-cooking aligns with recession-hit household budgets.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because steep price hikes accelerate switching to own-label rivals.","C":"Incorrect because luxury airport boutiques do not serve everyday grocery shoppers.","D":"Incorrect because degrading quality permanently alienates loyal buyers."}}},{"id":"P1_U3_MCQ_481","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_481","question":"When cocoa bean prices surge by 60%, a chocolate-bar maker quietly shrinks bar weight from 100g to 85g while keeping the $2.00 price ('shrinkflation'), sparking consumer anger online. What alternative marketing response maintains stronger trust?","options":{"A":"Communicate transparently or introduce a clearly labelled 'Sharing Duo' pack and new crunchy wafer variants that justify value openly","B":"Hide ingredient weight labels completely in violation of food laws","C":"Stop selling chocolate bars until cocoa prices fall back to 1990 levels","D":"Replace cocoa entirely with sawdust without telling buyers"},"correctOption":"A","correctAnswer":"Communicate transparently or introduce a clearly labelled 'Sharing Duo' pack and new crunchy wafer variants that justify value openly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because honest pack-tier innovation preserves brand trust better than stealth weight cuts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because net weight declarations are legally mandatory.","C":"Incorrect because halting sales surrenders shelf space to rivals.","D":"Incorrect because adulterating food is illegal and unethical."}}},{"id":"P1_U3_MCQ_482","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_482","question":"An eyewear retailer adds an Augmented Reality (AR) 'Virtual Try-On' camera feature to its mobile app so online shoppers can see how glasses frames fit their face shape in real time. How does this technology strengthen its marketing strategy?","options":{"A":"It overcomes the biggest barrier to buying glasses online—uncertainty over fit and appearance—boosting online conversion and lowering returns","B":"It eliminates the need to manufacture physical eyeglass frames","C":"It forces optometrists to close all eye-testing clinics","D":"It doubles the shipping weight of eyeglass parcels"},"correctOption":"A","correctAnswer":"It overcomes the biggest barrier to buying glasses online—uncertainty over fit and appearance—boosting online conversion and lowering returns","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because interactive AR visualization bridges the sensory gap between physical showrooms and e-commerce.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because physical glasses are still produced and shipped.","C":"Incorrect because clinical eye exams remain essential.","D":"Incorrect because digital app features do not affect parcel weight."}}},{"id":"P1_U3_MCQ_483","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_483","question":"With single-person households rising sharply in major cities, a frozen-food company launches single-serve 'Solo Gourmet' trays with zero food waste alongside its traditional 4-person family packs. Which market change is driving this product adaptation?","options":{"A":"Demographic shifts in household size and living arrangements","B":"A government ban on family-sized dining tables","C":"Falling national electricity generation","D":"A total disappearance of household microwave ovens"},"correctOption":"A","correctAnswer":"Demographic shifts in household size and living arrangements","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because more solo dwellers create strong demand for convenient single-portion packaging.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because portion sizes reflect household demographics rather than furniture bans.","C":"Incorrect because electricity supply is unrelated.","D":"Incorrect because frozen trays rely on widespread microwave ownership."}}},{"id":"P1_U3_MCQ_484","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_484","question":"Why do consumer-appliance manufacturers frequently enter emerging foreign markets when domestic sales of a product reach saturation?","options":{"A":"Rising disposable incomes and first-time household ownership in emerging economies offer high-growth demand for products already proven at home","B":"Emerging markets have zero local or international competitors","C":"Exporting overseas requires zero adaptation of electrical plugs or manuals","D":"Foreign currencies never fluctuate against the home currency"},"correctOption":"A","correctAnswer":"Rising disposable incomes and first-time household ownership in emerging economies offer high-growth demand for products already proven at home","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because expanding middle classes in developing economies create fresh growth waves for established appliance categories.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because emerging markets feature intense domestic and global rivalry.","C":"Incorrect because voltage, plugs, and languages require localization.","D":"Incorrect because exchange-rate volatility is a core international trade risk."}}},{"id":"P1_U3_MCQ_485","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_485","question":"A soft-drink company translates its humorous English slogan word-for-word into Spanish without consulting native copywriters, accidentally creating an embarrassing slang phrase that triggers ridicule. Which international marketing barrier occurred?","options":{"A":"Language and cultural localization failure in promotional communication","B":"High ocean-freight container tariffs","C":"Excessive use of random statistical sampling","D":"Domestic minimum-wage legislation"},"correctOption":"A","correctAnswer":"Language and cultural localization failure in promotional communication","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because idioms and humour rarely translate literally across cultures, requiring native cultural adaptation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the blunder occurred in slogan translation rather than shipping tariffs.","C":"Incorrect because proper local focus testing would have caught the error.","D":"Incorrect because wage laws are unrelated to slogan translation."}}},{"id":"P1_U3_MCQ_486","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_486","question":"A Malaysian furniture exporter prices its dining sets in Malaysian Ringgit (MYR). If the Ringgit appreciates sharply by 15% against the US Dollar, what happens to the competitiveness of its furniture in the United States?","options":{"A":"Its furniture becomes more expensive in US Dollars for American buyers, reducing price competitiveness unless the exporter absorbs lower profit margins","B":"Its furniture becomes 15% cheaper in US Dollars automatically","C":"Exchange-rate changes have zero effect on export prices","D":"US import tariffs automatically drop to zero when the Ringgit rises"},"correctOption":"A","correctAnswer":"Its furniture becomes more expensive in US Dollars for American buyers, reducing price competitiveness unless the exporter absorbs lower profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because currency appreciation raises the foreign-currency price of exports, squeezing either demand or exporter margins.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because depreciation—not appreciation—makes exports cheaper abroad.","C":"Incorrect because currency conversion directly alters foreign retail prices.","D":"Incorrect because tariff rates are set by trade policy rather than exchange rates."}}},{"id":"P1_U3_MCQ_487","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_487","question":"A European biscuit maker exports chocolate-coated biscuits to tropical Southeast Asia without upgrading the chocolate tempering or moisture-barrier foil, resulting in melted, soggy biscuits on store shelves. Which foreign-market factor was neglected?","options":{"A":"Adapting product formulation and protective packaging to local climate and storage conditions","B":"Translating television jingles into French","C":"Using price skimming on everyday biscuits","D":"Hiring a B2B aircraft leasing agent"},"correctOption":"A","correctAnswer":"Adapting product formulation and protective packaging to local climate and storage conditions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high heat and humidity require heat-stable formulations and superior moisture-seal packaging.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because French translation does not prevent tropical heat melting.","C":"Incorrect because the failure was physical product spoilage rather than pricing.","D":"Incorrect because aircraft leasing is unrelated."}}},{"id":"P1_U3_MCQ_488","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_488","question":"A specialty olive-oil producer wants to enter the German market quickly with low upfront investment by selling wholesale pallets to an established German specialty-food distributor. What is a drawback of using a 'foreign distributor' instead of opening a wholly owned sales subsidiary?","options":{"A":"The producer gives up part of its profit margin to the distributor and has less direct control over how retailers price and promote the brand","B":"The producer must spend $50 million building a bottling factory in Berlin","C":"Foreign distributors are legally forbidden from selling imported foods","D":"The producer must personally deliver single bottles to every German household"},"correctOption":"A","correctAnswer":"The producer gives up part of its profit margin to the distributor and has less direct control over how retailers price and promote the brand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because outsourcing local distribution trades away margin and brand-execution control in exchange for speed and low capital risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because building a foreign factory describes wholly owned direct investment.","C":"Incorrect because import distributors are lawful and common.","D":"Incorrect because the distributor handles local B2B logistics."}}},{"id":"P1_U3_MCQ_489","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_489","question":"An American battery company and a South Korean chemical firm form an international 'joint venture' to build an EV battery plant, but clash over whether to reinvest profits into R&D or pay immediate cash dividends. Which risk of joint ventures is shown?","options":{"A":"Strategic and cultural disagreements between partner management teams over profit allocation and operational control","B":"Joint ventures are illegal in international manufacturing","C":"Neither partner contributes any capital or technology","D":"Joint ventures eliminate all raw-material lithium costs"},"correctOption":"A","correctAnswer":"Strategic and cultural disagreements between partner management teams over profit allocation and operational control","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shared ownership requires continuous alignment on reinvestment, governance, and corporate priorities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because joint ventures are widely used globally.","C":"Incorrect because both partners pool resources.","D":"Incorrect because raw-material expenses still apply."}}},{"id":"P1_U3_MCQ_490","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_490","question":"A global fried-chicken restaurant chain expands via international 'franchising', and one overseas franchisee triggers a food-poisoning outbreak by ignoring kitchen refrigeration rules, hurting the brand's image worldwide. Which drawback of franchising is this?","options":{"A":"Poor quality or hygiene standards at one independent franchisee outlet can damage the global brand reputation of the entire chain","B":"Franchisors must fund 100% of every franchisee's store construction costs","C":"Franchising prevents rapid multi-country store openings","D":"Franchisees never pay upfront fees or ongoing royalties"},"correctOption":"A","correctAnswer":"Poor quality or hygiene standards at one independent franchisee outlet can damage the global brand reputation of the entire chain","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumers view all stores under the same logo as one unified brand, creating reputational contagion risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because franchisees invest their own capital.","C":"Incorrect because speed is franchising's biggest strength.","D":"Incorrect because franchisees pay initial fees and percentage royalties."}}},{"id":"P1_U3_MCQ_491","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_491","question":"A popular animated children's TV studio grants 'licensing' rights to toy, backpack, and bedding manufacturers across 30 countries in exchange for a 10% royalty on wholesale sales. Why is licensing attractive here?","options":{"A":"The studio earns global royalty revenue from its intellectual property without investing capital in toy or textile factories","B":"The studio must operate 30 plastic-moulding factories worldwide","C":"Licensing guarantees that unlicensed counterfeit toys never appear","D":"Toy manufacturers receive the studio's characters for free"},"correctOption":"A","correctAnswer":"The studio earns global royalty revenue from its intellectual property without investing capital in toy or textile factories","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because licensing monetizes brand/character IP rapidly while licensees bear manufacturing and inventory risks.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the licensees own and run the factories.","C":"Incorrect because IP enforcement against counterfeits remains necessary.","D":"Incorrect because licensees pay contracted royalties."}}},{"id":"P1_U3_MCQ_492","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_492","question":"A high-pressure doorstep salesperson convinces an elderly homeowner to sign a $9,000 double-glazing window contract, and the next morning the homeowner changes their mind. How do consumer protection laws protect the buyer?","options":{"A":"Statutory 'cooling-off period' rules grant distance and doorstep buyers a legal window (e.g., 14 days) to cancel contracts for a full refund without penalty","B":"Doorstep contracts can never be cancelled once signed","C":"Homeowners are legally forbidden from buying windows from salespeople","D":"Salespeople must install the windows for free if the buyer complains"},"correctOption":"A","correctAnswer":"Statutory 'cooling-off period' rules grant distance and doorstep buyers a legal window (e.g., 14 days) to cancel contracts for a full refund without penalty","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cooling-off rights protect consumers from impulsive pressure sales and online purchases where items could not be inspected beforehand.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because consumer laws override non-cancellation clauses during the cooling-off period.","C":"Incorrect because doorstep selling is lawful when cooling-off rights are honoured.","D":"Incorrect because cancellation voids the contract and refunds deposits."}}},{"id":"P1_U3_MCQ_493","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_493","question":"A clothing brand prints '100% Eco-Friendly & Biodegradable' on polyester jackets that are actually made from standard petroleum plastics, resulting in heavy regulatory fines for 'greenwashing'. Why do advertising laws penalize false environmental claims?","options":{"A":"Unsubstantiated green claims deceive eco-conscious shoppers and unfairly disadvantage rivals who genuinely invest in sustainable materials","B":"Clothing brands are legally prohibited from using recycled fabrics","C":"Polyester jackets are exempt from all consumer description laws","D":"Regulators fine all companies that sell winter coats"},"correctOption":"A","correctAnswer":"Unsubstantiated green claims deceive eco-conscious shoppers and unfairly disadvantage rivals who genuinely invest in sustainable materials","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because environmental marketing claims must be backed by verifiable scientific evidence to prevent consumer deception.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because genuine sustainable fabrics are encouraged.","C":"Incorrect because apparel labels are strictly covered by misleading-claims laws.","D":"Incorrect because the fine targeted false environmental claims rather than coats themselves."}}},{"id":"P1_U3_MCQ_494","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_494","question":"Why do governments enforce strict legal restrictions banning tobacco and vaping companies from sponsoring youth music festivals or placing adverts on social-media platforms used heavily by teenagers?","options":{"A":"To protect public health and prevent addictive, age-restricted products from being promoted to minors","B":"Because music festivals refuse to accept sponsorship money from any industry","C":"Because social-media platforms have zero adult users","D":"To force tobacco companies to switch to manufacturing bicycles"},"correctOption":"A","correctAnswer":"To protect public health and prevent addictive, age-restricted products from being promoted to minors","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because public-health legislation restricts marketing channels for harmful or age-controlled goods to shield young people.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because festivals accept sponsorships from non-restricted sectors.","C":"Incorrect because youth-heavy platforms require age-gating and ad bans for restricted goods.","D":"Incorrect because the law regulates marketing practices rather than mandating unrelated products."}}},{"id":"P1_U3_MCQ_495","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_495","question":"Three competing domestic airlines secretly agree to set identical minimum fuel surcharges on all flights so none of them loses passengers to cheaper fares. Which legal control is violated?","options":{"A":"Competition and anti-trust laws prohibiting price-fixing cartels that harm consumers","B":"Weights and measures liquid calibration rules","C":"Product allergen labelling regulations","D":"Employee maternity-leave statutes"},"correctOption":"A","correctAnswer":"Competition and anti-trust laws prohibiting price-fixing cartels that harm consumers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because collusive price-fixing eliminates genuine rivalry and forces consumers to pay artificially inflated prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because weights and measures govern physical quantity labels.","C":"Incorrect because allergen rules apply to food packaging.","D":"Incorrect because maternity leave is an employment law."}}},{"id":"P1_U3_MCQ_496","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_496","question":"An electric-kettle manufacturer discovers a faulty thermostat switch that can overheat and cause kitchen fires in 50,000 sold units. Under product-safety legislation, what must the company do immediately?","options":{"A":"Issue an urgent public product recall, halt further store sales, and offer free repairs, safe replacements, or full refunds to buyers","B":"Ignore the fault and quietly sell the remaining defective kettles at a 50% discount","C":"Blame customers for plugging the kettles into electrical sockets","D":"Change the kettle box colour without fixing the faulty switch"},"correctOption":"A","correctAnswer":"Issue an urgent public product recall, halt further store sales, and offer free repairs, safe replacements, or full refunds to buyers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because product-safety laws impose strict liability on producers to remove hazardous goods from homes and prevent injury.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because knowingly selling unsafe goods incurs severe criminal penalties and lawsuits.","C":"Incorrect because normal household use must be completely safe.","D":"Incorrect because cosmetic packaging changes do not resolve the safety hazard."}}},{"id":"P1_U3_MCQ_497","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_497","question":"Even though local law permits sugary soda billboards near schools, a beverage corporation voluntarily removes all adverts within 500 metres of primary schools and shifts ad spend to low-sugar sparkling water. What motivates this 'ethical marketing' decision?","options":{"A":"Strengthening long-term brand trust with parents and preempting stricter government sugar-advertising bans","B":"Increasing short-term sugar sales to six-year-old children","C":"Eliminating all bottling factory electricity expenses","D":"Violating consumer protection laws intentionally"},"correctOption":"A","correctAnswer":"Strengthening long-term brand trust with parents and preempting stricter government sugar-advertising bans","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical self-regulation protects corporate reputation among parents and reduces future regulatory backlash.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the firm is reducing sugary drink promotion to children.","C":"Incorrect because bottling costs remain unchanged.","D":"Incorrect because ethical behaviour goes beyond minimum legal compliance."}}},{"id":"P1_U3_MCQ_498","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_498","question":"How do strict consumer-protection and advertising regulations affect a business's marketing operations and costs?","options":{"A":"Firms must spend more on legal copy reviews, accurate packaging labels, safety testing, and customer return handling, though compliance builds long-term buyer confidence","B":"Consumer laws reduce all marketing and packaging costs to zero","C":"Regulations allow businesses to make any exaggerated health claim without proof","D":"Consumer laws ban businesses from offering warranties or refunds"},"correctOption":"A","correctAnswer":"Firms must spend more on legal copy reviews, accurate packaging labels, safety testing, and customer return handling, though compliance builds long-term buyer confidence","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because regulatory compliance raises administrative and testing overheads while creating a trustworthy marketplace.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because compliance adds testing and legal verification expenses.","C":"Incorrect because claims must be substantiated.","D":"Incorrect because laws guarantee minimum refund and repair rights."}}},{"id":"P1_U3_MCQ_499","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_499","question":"Before launching an electric-scooter sharing service in Kuala Lumpur, a startup surveys 600 train commuters on first-mile gaps, sets dynamic per-minute app pricing with student passes, places docks at LRT stations, and runs referral codes. Why is this strategy likely to succeed?","options":{"A":"It is market-oriented, targets clear commuter segments, and aligns convenient station Place, flexible Price, and digital Promotion around real user needs","B":"It ignores commuter travel habits and sells scooters solely via printed postal catalogues","C":"It relies purely on product-oriented engineering without checking station footfall","D":"It uses permanent loss-leader pricing at zero cents per ride forever"},"correctOption":"A","correctAnswer":"It is market-oriented, targets clear commuter segments, and aligns convenient station Place, flexible Price, and digital Promotion around real user needs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because primary commuter research directly informs accessible station placement, tiered pricing, and viral referral promotion.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the startup surveyed commuters and used mobile app access.","C":"Incorrect because station placement was driven by commuter survey data.","D":"Incorrect because dynamic per-minute pricing and student passes generate recurring revenue."}}},{"id":"P1_U3_MCQ_500","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_500","question":"Facing declining sales of traditional loose-leaf black tea, a heritage tea company segments busy young professionals, launches biodegradable pyramid herbal-infusion tea bags, sells subscriptions online plus via trendy cafés, and backs relaxation claims with certified nutritional data. How does this turn the business around?","options":{"A":"It combines targeted market segmentation, an extension strategy into convenient modern formats, omnichannel Place, and legally compliant promotion","B":"It cuts tea quality, raises prices by 300%, and removes all ingredient labels","C":"It relies solely on outdated 1995 secondary reports and stops all online sales","D":"It uses misleading 'Cures All Diseases' health claims to boost short-term orders"},"correctOption":"A","correctAnswer":"It combines targeted market segmentation, an extension strategy into convenient modern formats, omnichannel Place, and legally compliant promotion","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because revitalizing a mature/declining brand requires aligning product innovation, modern distribution, and credible, lawful promotion with a growing demographic segment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cutting quality and removing mandatory labels would destroy trust and breach food laws.","C":"Incorrect because e-commerce subscriptions and modern formats actively capture younger buyers.","D":"Incorrect because unverified medical claims violate consumer protection and advertising regulations."}}},{"id":"P1_U3_MCQ_501","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_501","question":"What is meant by the term 'marketing'?","options":{"A":"Identifying customer wants and satisfying them profitably.","B":"Producing goods at the lowest possible unit cost regardless of demand.","C":"Advertising and selling existing inventory to the general public.","D":"Distributing finished goods from factories to retail outlets."},"correctOption":"A","correctAnswer":"Identifying customer wants and satisfying them profitably.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because marketing is the management process responsible for identifying customer needs and wants and satisfying them profitably.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because focusing solely on production efficiency without considering customer demand describes a product-oriented approach.","C":"Incorrect because advertising and selling are only individual elements of promotion and sales, not the whole marketing function.","D":"Incorrect because transporting goods to retail outlets describes distribution ('place'), which is just one part of the marketing mix."}}},{"id":"P1_U3_MCQ_502","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_502","question":"What is the key difference between a 'customer' and a 'consumer'?","options":{"A":"A customer only buys services, whereas a consumer only buys tangible goods.","B":"A customer buys goods or services from a business, whereas a consumer uses them for personal use.","C":"A customer buys products in bulk for resale, whereas a consumer is always another business.","D":"A customer buys from niche markets, whereas a consumer only buys from mass markets."},"correctOption":"B","correctAnswer":"A customer buys goods or services from a business, whereas a consumer uses them for personal use.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a customer is a person or business that purchases goods or services, whereas a consumer is the final user who buys or uses goods or services for personal use and not for resale.","distractor_reasons":{"A":"Incorrect because both customers and consumers can purchase or use both tangible goods and intangible services.","B":"Correct selection.","C":"Incorrect because a consumer buys for personal use rather than for resale, and is an individual rather than a business.","D":"Incorrect because both customers and consumers exist in both niche and mass markets."}}},{"id":"P1_U3_MCQ_503","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_503","question":"How is 'market share' defined?","options":{"A":"The total profit earned by a business divided by the total profit of the industry.","B":"The number of retail outlets selling a business's brand compared to rivals.","C":"The percentage of total sales revenue for the whole market held by one brand or business.","D":"The total value of all goods and services sold within a country in one year."},"correctOption":"C","correctAnswer":"The percentage of total sales revenue for the whole market held by one brand or business.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market share measures the proportion (percentage) of total market sales revenue held by a single brand or business.","distractor_reasons":{"A":"Incorrect because market share is based on sales revenue (or sales volume), not profit.","B":"Incorrect because the number of retail outlets measures distribution coverage rather than market share.","C":"Correct selection.","D":"Incorrect because the total value of all goods and services sold in an economy measures national output (GDP), not a firm's market share."}}},{"id":"P1_U3_MCQ_504","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_504","question":"Which statement best defines 'customer loyalty'?","options":{"A":"When customers purchase a product once because of a temporary price discount.","B":"When suppliers agree to sell raw materials exclusively to one manufacturer.","C":"When employees remain working for the same business for many years.","D":"When existing customers continually buy products from the same business rather than competitors."},"correctOption":"D","correctAnswer":"When existing customers continually buy products from the same business rather than competitors.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because customer loyalty occurs when existing customers repeatedly purchase from the same business instead of switching to rival brands.","distractor_reasons":{"A":"Incorrect because a one-off purchase driven by a discount does not represent ongoing repeat purchasing or loyalty.","B":"Incorrect because exclusive supply agreements relate to supplier relationships, not customer behaviour.","C":"Incorrect because employees staying with a business describes low labour turnover, not customer loyalty.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_505","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_505","question":"Why is maintaining customer loyalty an important role of marketing?","options":{"A":"It is usually much cheaper to keep existing customers than to attract new ones.","B":"It removes the need to ever update or improve existing products.","C":"It guarantees that competitors will exit the industry completely.","D":"It eliminates all fixed costs associated with operating a marketing department."},"correctOption":"A","correctAnswer":"It is usually much cheaper to keep existing customers than to attract new ones.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retaining existing customers costs significantly less in promotion and acquisition expenses than attracting brand-new customers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses must still adapt and improve products as customer expectations evolve over time.","C":"Incorrect because high customer loyalty strengthens a firm's position but does not force all rivals out of the market.","D":"Incorrect because marketing departments still incur fixed salaries and administrative expenses."}}},{"id":"P1_U3_MCQ_506","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_506","question":"What is the primary purpose of 'building customer relationships' in marketing?","options":{"A":"To force customers into signing long-term legal purchasing contracts.","B":"To communicate with customers to encourage repeat purchases and understand their changing needs.","C":"To replace primary market research with government census statistics.","D":"To reduce product quality once customers have become regular buyers."},"correctOption":"B","correctAnswer":"To communicate with customers to encourage repeat purchases and understand their changing needs.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because building customer relationships involves ongoing communication with customers to encourage repeat business and gather insight into their changing buying habits and needs.","distractor_reasons":{"A":"Incorrect because customer relationships rely on trust and engagement rather than binding legal contracts.","B":"Correct selection.","C":"Incorrect because customer relationships actually provide direct primary feedback rather than relying on secondary government data.","D":"Incorrect because lowering quality would destroy trust and drive loyal customers away."}}},{"id":"P1_U3_MCQ_507","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_507","question":"How does a business gain a competitive advantage by 'anticipating changes in customer needs'?","options":{"A":"By waiting for competitors to launch new products before copying them.","B":"By keeping prices fixed regardless of changes in consumer incomes.","C":"By identifying new trends or market gaps early and developing products ahead of rivals.","D":"By reducing expenditure on research and development to maximize short-term cash."},"correctOption":"C","correctAnswer":"By identifying new trends or market gaps early and developing products ahead of rivals.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because anticipating changes in customer needs allows a business to spot emerging trends or gaps in the market early and launch products before competitors do.","distractor_reasons":{"A":"Incorrect because waiting to copy rivals is reactive rather than anticipating future customer needs.","B":"Incorrect because rigid pricing ignores changing economic conditions and consumer spending power.","C":"Correct selection.","D":"Incorrect because cutting R&D prevents a business from innovating to meet future customer demands."}}},{"id":"P1_U3_MCQ_508","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_508","question":"Which factor is a direct cause of changes in consumer spending patterns?","options":{"A":"A change in the legal form of ownership of a supplier.","B":"An increase in the span of control within a factory.","C":"A reduction in the number of shares traded on a stock exchange.","D":"Changes in consumer tastes, fashions, and levels of disposable income."},"correctOption":"D","correctAnswer":"Changes in consumer tastes, fashions, and levels of disposable income.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumer spending patterns change due to shifts in tastes and fashions, technological advances, changes in income, and ageing populations.","distractor_reasons":{"A":"Incorrect because a supplier's legal ownership structure does not directly alter what consumers choose to buy.","B":"Incorrect because internal organizational hierarchy does not dictate consumer purchasing habits.","C":"Incorrect because stock exchange trading volume does not directly cause shifts in consumer product preferences.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_509","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_509","question":"How does an ageing population affect consumer spending patterns in a country?","options":{"A":"Demand increases for products and services aimed at older people, such as healthcare and retirement homes.","B":"Demand increases rapidly for baby clothing and primary school textbooks.","C":"Consumers stop purchasing services and spend exclusively on raw materials.","D":"Total demand for all luxury goods disappears completely."},"correctOption":"A","correctAnswer":"Demand increases for products and services aimed at older people, such as healthcare and retirement homes.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an ageing population increases the proportion of older consumers, raising demand for age-related goods and services such as anti-ageing products, healthcare, and care homes.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because demand for baby and children's items rises with a higher birth rate, not an ageing population.","C":"Incorrect because older consumers purchase a wide variety of consumer goods and services, not industrial raw materials.","D":"Incorrect because many older consumers have significant savings and pensions to spend on leisure and luxury items."}}},{"id":"P1_U3_MCQ_510","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_510","question":"How do advances in technology change consumer spending patterns?","options":{"A":"They prevent consumers from comparing prices across different retailers.","B":"New technological products replace older versions, causing sales of outdated products to fall.","C":"They force all consumers to shop exclusively at local physical stores.","D":"They make consumer tastes permanently fixed over several decades."},"correctOption":"B","correctAnswer":"New technological products replace older versions, causing sales of outdated products to fall.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because new technological innovations (such as smartphones and tablets) attract consumer spending away from older alternatives (such as traditional desktop computers).","distractor_reasons":{"A":"Incorrect because technology, especially the internet, makes price comparison much easier for consumers.","B":"Correct selection.","C":"Incorrect because technological advances in ecommerce encourage online shopping rather than restricting buyers to physical shops.","D":"Incorrect because rapid technological innovation accelerates changes in consumer tastes."}}},{"id":"P1_U3_MCQ_511","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_511","question":"Which factor explains why many markets have become more competitive in recent years?","options":{"A":"Higher international transport costs preventing imports from entering domestic markets.","B":"Government bans on businesses creating websites or using social media.","C":"Globalisation, improved transport links, and the growth of ecommerce.","D":"A decrease in the amount of product information available to consumers."},"correctOption":"C","correctAnswer":"Globalisation, improved transport links, and the growth of ecommerce.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because globalisation, lower international transport costs, ecommerce, and greater consumer access to product information have increased competition worldwide.","distractor_reasons":{"A":"Incorrect because transport improvements have lowered shipping costs, making imports more competitive rather than blocking them.","B":"Incorrect because online platforms and social media are widely used and have intensified competition.","C":"Correct selection.","D":"Incorrect because consumers now have far more product and price information via the internet, which increases competition."}}},{"id":"P1_U3_MCQ_512","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_512","question":"How can a business best respond to increased competition in its market?","options":{"A":"Stop conducting market research so competitors cannot copy its ideas.","B":"Raise prices above competitors' levels without improving product quality.","C":"Reduce product features while keeping prices unchanged.","D":"Improve existing products to differentiate them and keep costs low to remain price competitive."},"correctOption":"D","correctAnswer":"Improve existing products to differentiate them and keep costs low to remain price competitive.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because businesses respond to stronger competition by differentiating and improving products, developing new products, maintaining strong customer relationships, and lowering costs to offer competitive prices.","distractor_reasons":{"A":"Incorrect because stopping market research leaves the business blind to changing customer needs and rival strategies.","B":"Incorrect because raising prices without adding value will cause customers to switch to cheaper competitors.","C":"Incorrect because reducing quality or features for the same price makes the product less attractive than rival offerings.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_513","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_513","question":"What is meant by a 'mass market'?","options":{"A":"Where a business sells standardised products to a very large number of customers.","B":"A small, specialised segment of a larger market with unique customer needs.","C":"A market where only luxury, custom-made goods are sold at premium prices.","D":"A market restricted solely to business-to-business industrial buyers."},"correctOption":"A","correctAnswer":"Where a business sells standardised products to a very large number of customers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a mass market exists where a business sells standardised products to a very large number of consumers across the whole market.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a small, specialised segment of a larger market defines a niche market.","C":"Incorrect because luxury, custom-made products target a niche market rather than a mass market.","D":"Incorrect because mass markets typically consist of millions of everyday individual consumers."}}},{"id":"P1_U3_MCQ_514","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_514","question":"Which of the following is a key advantage of operating in a mass market?","options":{"A":"There are very few competitors selling similar products.","B":"High sales volumes can lead to high revenue and economies of scale.","C":"Products are custom-made to satisfy the exact individual preferences of every buyer.","D":"Consumers are always willing to pay exceptionally high luxury prices."},"correctOption":"B","correctAnswer":"High sales volumes can lead to high revenue and economies of scale.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because selling to a mass market generates high total sales volumes, leading to high revenue and lower average costs through economies of scale.","distractor_reasons":{"A":"Incorrect because competition in mass markets is usually intense with many rival businesses.","B":"Correct selection.","C":"Incorrect because mass market products are standardised rather than custom-made for individual buyers.","D":"Incorrect because mass market products must be priced affordably for the majority of consumers."}}},{"id":"P1_U3_MCQ_515","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_515","question":"What is a major disadvantage of selling in a mass market?","options":{"A":"Total sales potential is too small to allow business growth.","B":"Businesses must design completely different products for every single customer.","C":"Competition is high and it is difficult to differentiate standardised products from rivals.","D":"Brand names rarely become widely known among the general public."},"correctOption":"C","correctAnswer":"Competition is high and it is difficult to differentiate standardised products from rivals.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because mass markets attract intense competition, making it difficult to differentiate standardised products from those of competitors.","distractor_reasons":{"A":"Incorrect because limited sales potential is a disadvantage of niche markets, not mass markets.","B":"Incorrect because mass marketing avoids the cost of producing different versions for every customer.","C":"Correct selection.","D":"Incorrect because wide promotion in mass markets usually makes brand names very well known."}}},{"id":"P1_U3_MCQ_516","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_516","question":"What is meant by a 'niche market'?","options":{"A":"The total number of consumers who buy everyday necessities in a country.","B":"A market where standardised goods are sold at the lowest possible price.","C":"A market dominated exclusively by large multinational corporations.","D":"A small, usually specialised, segment of a much larger market."},"correctOption":"D","correctAnswer":"A small, usually specialised, segment of a much larger market.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a niche market is a small, specialised sub-group or segment of a much larger market.","distractor_reasons":{"A":"Incorrect because the total number of buyers for everyday goods describes a mass market.","B":"Incorrect because standardised, low-priced goods are typical of mass markets, whereas niche products are specialised.","C":"Incorrect because large multinationals often focus on mass markets, leaving niche markets to smaller specialist firms.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_517","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_517","question":"Which of the following is an advantage to a small business of targeting a niche market?","options":{"A":"It can avoid direct competition from large businesses that focus on mass markets.","B":"It guarantees unlimited sales volume and massive economies of scale.","C":"It completely eliminates the risk of business failure if demand falls.","D":"It requires no understanding of specific customer needs or preferences."},"correctOption":"A","correctAnswer":"It can avoid direct competition from large businesses that focus on mass markets.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because large firms often overlook small niche segments to focus on mass markets, allowing small businesses to operate with less competition and charge higher prices for specialised products.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because niche markets have small customer numbers, limiting sales volume and economies of scale.","C":"Incorrect because niche businesses often rely on a single specialised product, increasing risk if demand drops.","D":"Incorrect because succeeding in a niche market requires a very close focus on specific consumer needs."}}},{"id":"P1_U3_MCQ_518","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_518","question":"What is a key disadvantage of operating in a niche market?","options":{"A":"Consumers refuse to pay higher prices for specialised products.","B":"Sales potential is limited due to the small number of customers, restricting growth.","C":"It is impossible to build close relationships with customers.","D":"Promotion must be broadcast to the entire population at huge expense."},"correctOption":"B","correctAnswer":"Sales potential is limited due to the small number of customers, restricting growth.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because niche markets consist of a small number of buyers, meaning total sales potential is limited and a firm must expand outside the niche to achieve major growth.","distractor_reasons":{"A":"Incorrect because niche consumers are often willing to pay higher prices for products tailored to their specific needs.","B":"Correct selection.","C":"Incorrect because focusing on a small group of buyers actually makes it easier to build strong customer relationships.","D":"Incorrect because niche promotion can be narrowly targeted rather than broadcast to the mass public."}}},{"id":"P1_U3_MCQ_519","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_519","question":"What is meant by 'market segmentation'?","options":{"A":"Dividing a company's workforce into separate functional departments.","B":"Selling one identical product to every consumer in the entire economy.","C":"Breaking down a whole market into identifiable sub-groups of consumers with similar characteristics and marketing different products to each.","D":"Calculating the percentage of total industry sales earned by each competitor."},"correctOption":"C","correctAnswer":"Breaking down a whole market into identifiable sub-groups of consumers with similar characteristics and marketing different products to each.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market segmentation involves dividing a market into distinct sub-groups (segments) of consumers who share similar characteristics or preferences and tailoring products and marketing to each group.","distractor_reasons":{"A":"Incorrect because dividing workers into departments describes organizational structure, not market segmentation.","B":"Incorrect because selling one identical product to everyone describes undifferentiated mass marketing.","C":"Correct selection.","D":"Incorrect because calculating percentages of total sales describes measuring market share."}}},{"id":"P1_U3_MCQ_520","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_520","question":"What is a 'market segment'?","options":{"A":"A geographic region where a business is legally banned from trading.","B":"The distribution channel used to transport raw materials to a factory.","C":"A specific stage in the life cycle of a consumer product.","D":"An identifiable sub-group of a whole market in which consumers share similar characteristics or preferences."},"correctOption":"D","correctAnswer":"An identifiable sub-group of a whole market in which consumers share similar characteristics or preferences.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a market segment is a distinct sub-group within a larger market whose members share similar characteristics, needs, or preferences.","distractor_reasons":{"A":"Incorrect because a market segment is a group of consumers, not a restricted trading zone.","B":"Incorrect because transporting materials relates to supply chains and distribution, not consumer grouping.","C":"Incorrect because stages such as growth and maturity belong to the product life cycle.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_521","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_521","question":"Which of the following lists five common ways businesses segment a market?","options":{"A":"Age, income, location, gender, and lifestyle.","B":"Land, labour, capital, enterprise, and profit.","C":"Product, price, place, promotion, and packaging.","D":"Introduction, growth, maturity, saturation, and decline."},"correctOption":"A","correctAnswer":"Age, income, location, gender, and lifestyle.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because markets are commonly segmented by demographic and behavioural factors: age, income, location, gender, and lifestyle.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because land, labour, capital, and enterprise are the four factors of production.","C":"Incorrect because product, price, place, and promotion are the elements of the marketing mix.","D":"Incorrect because introduction, growth, maturity, and decline are stages of the product life cycle."}}},{"id":"P1_U3_MCQ_522","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_522","question":"How does segmenting a market by 'lifestyle' work?","options":{"A":"By pricing products according to the average monthly salary of consumers.","B":"By developing and marketing different products based on consumers' hobbies, interests, and ways of living.","C":"By selling waterproof clothing only in regions with high annual rainfall.","D":"By designing toys specifically for infants versus older teenagers."},"correctOption":"B","correctAnswer":"By developing and marketing different products based on consumers' hobbies, interests, and ways of living.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because lifestyle segmentation divides consumers according to how they spend their free time, their hobbies, and their daily way of living (e.g., sports enthusiasts versus indoor craft hobbyists).","distractor_reasons":{"A":"Incorrect because pricing according to earnings is segmentation by income.","B":"Correct selection.","C":"Incorrect because tailoring products to regional climate is segmentation by location.","D":"Incorrect because targeting infants versus teenagers is segmentation by age."}}},{"id":"P1_U3_MCQ_523","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_523","question":"What is a key advantage to a business of using market segmentation?","options":{"A":"It reduces production and storage costs by making only one standardised product.","B":"It eliminates the need to carry out any market research before launching products.","C":"Promotion can be directed accurately at specific consumer groups, making better use of the marketing budget.","D":"It ensures that every single market segment is large enough to be profitable."},"correctOption":"C","correctAnswer":"Promotion can be directed accurately at specific consumer groups, making better use of the marketing budget.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market segmentation allows a business to tailor both products and promotions to each consumer group, avoiding wasted advertising spend on uninterested audiences.","distractor_reasons":{"A":"Incorrect because producing multiple product variations for different segments increases production and inventory storage costs.","B":"Incorrect because market segmentation requires extensive market research to understand each segment's characteristics.","C":"Correct selection.","D":"Incorrect because some market segments may be too small to generate enough sales to be profitable."}}},{"id":"P1_U3_MCQ_524","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_524","question":"Which of the following is a disadvantage of market segmentation?","options":{"A":"Customer needs are ignored because only one generic product is offered.","B":"Businesses cannot charge higher prices for products designed for specific segments.","C":"Promotional messages must be identical across all media platforms.","D":"Research, development, production, and storage costs increase when creating different products for multiple segments."},"correctOption":"D","correctAnswer":"Research, development, production, and storage costs increase when creating different products for multiple segments.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because developing, researching, producing, storing, and promoting different product versions for separate market segments raises business costs.","distractor_reasons":{"A":"Incorrect because market segmentation specifically aims to meet the distinct needs of different customer groups.","B":"Incorrect because tailored products often allow a business to charge higher prices, which is an advantage.","C":"Incorrect because segmentation involves adapting promotions to appeal to each target group.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_525","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_525","question":"Why might a business choose NOT to target a particular market segment?","options":{"A":"The segment may have too few consumers to generate enough sales to be profitable.","B":"Consumers in a single segment never share any similar preferences.","C":"Legal controls prohibit businesses from advertising to specific age groups.","D":"Market segmentation prevents a business from selling in mass markets."},"correctOption":"A","correctAnswer":"The segment may have too few consumers to generate enough sales to be profitable.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because if a market segment contains only a small number of potential buyers, the revenue earned may not cover the extra costs of developing and marketing a specialised product.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because by definition, consumers in a market segment share similar characteristics or preferences.","C":"Incorrect because segmenting by age is standard business practice, provided promotions follow consumer protection rules.","D":"Incorrect because large businesses often target multiple segments simultaneously across a mass market."}}},{"id":"P1_U3_MCQ_526","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_526","question":"What is meant by 'market research'?","options":{"A":"The process of manufacturing new prototypes in a factory laboratory.","B":"The process of gathering, analysing, and interpreting information about a market.","C":"The legal registration of a brand name and logo with the government.","D":"The physical distribution of finished goods to wholesale warehouses."},"correctOption":"B","correctAnswer":"The process of gathering, analysing, and interpreting information about a market.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because market research is the systematic process of gathering, analysing, and interpreting information about a market, consumers, and competitors.","distractor_reasons":{"A":"Incorrect because building prototypes is part of product research and development (R&D), not market research.","B":"Correct selection.","C":"Incorrect because registering a brand name or trademark is legal intellectual property protection.","D":"Incorrect because moving goods to warehouses is logistics and distribution ('place')."}}},{"id":"P1_U3_MCQ_527","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_527","question":"What distinguishes a 'product-oriented' business from a 'market-oriented' business?","options":{"A":"A product-oriented business conducts extensive customer surveys before designing any product.","B":"A product-oriented business sells only intangible services rather than physical goods.","C":"A product-oriented business focuses on the product and production process first, hoping customers will buy it afterward.","D":"A product-oriented business operates exclusively in niche markets."},"correctOption":"C","correctAnswer":"A product-oriented business focuses on the product and production process first, hoping customers will buy it afterward.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a product-oriented business concentrates on designing and manufacturing a product based on its own technical expertise first, and then tries to persuade customers to buy it.","distractor_reasons":{"A":"Incorrect because researching customer needs before developing a product defines a market-oriented business.","B":"Incorrect because product-oriented firms commonly produce physical, technical, or traditional goods.","C":"Correct selection.","D":"Incorrect because either orientation can exist in different market structures, though market orientation is safer in competitive markets."}}},{"id":"P1_U3_MCQ_528","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_528","question":"Why is it important for a business to carry out market research before launching a new product?","options":{"A":"It guarantees that competitors will not lower their prices.","B":"It eliminates all variable costs of manufacturing the new product.","C":"It allows the business to avoid paying government taxes on sales revenue.","D":"It reduces the risk of new product failure by identifying whether consumers will buy it and at what price."},"correctOption":"D","correctAnswer":"It reduces the risk of new product failure by identifying whether consumers will buy it and at what price.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because market research reduces the risk and uncertainty of launching a new product by identifying consumer needs, willingness to buy, acceptable price levels, and competitor strength.","distractor_reasons":{"A":"Incorrect because market research gathers information about competitors but cannot control their pricing decisions.","B":"Incorrect because variable production costs (such as raw materials) still occur regardless of research.","C":"Incorrect because taxes apply to business profits and sales irrespective of market research.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_529","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_529","question":"What is 'primary market research' (field research)?","options":{"A":"The collection and collation of original data via direct contact with potential or existing consumers.","B":"The use of statistics already published by government departments and trade journals.","C":"Research carried out solely by businesses operating in the primary sector of industry.","D":"Analysing historical sales records held inside the company's finance department."},"correctOption":"A","correctAnswer":"The collection and collation of original data via direct contact with potential or existing consumers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because primary (field) research involves collecting brand-new, original data directly from potential or existing customers for a specific business purpose.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because using already published information describes secondary (desk) research.","C":"Incorrect because 'primary' in market research means first-hand original data, not farming or mining.","D":"Incorrect because internal historical sales records are an internal source of secondary data."}}},{"id":"P1_U3_MCQ_530","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_530","question":"Which of the following is a key advantage of primary market research over secondary market research?","options":{"A":"It is always cheaper and faster to collect than existing data.","B":"The data is up to date, tailored to the specific needs of the business, and unavailable to competitors.","C":"It provides complete nationwide population census figures free of charge.","D":"It requires no planning or sample selection before collecting data."},"correctOption":"B","correctAnswer":"The data is up to date, tailored to the specific needs of the business, and unavailable to competitors.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because primary research is collected first-hand for the business's specific problem, is completely up to date, and remains exclusive to the business that conducted it.","distractor_reasons":{"A":"Incorrect because primary research is usually more expensive and time-consuming than secondary research.","B":"Correct selection.","C":"Incorrect because nationwide census figures are secondary data collected by governments.","D":"Incorrect because primary research requires careful planning, questionnaire design, and sampling."}}},{"id":"P1_U3_MCQ_531","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_531","question":"What is a major disadvantage of primary market research?","options":{"A":"The information is automatically available to all rival businesses.","B":"The data is always several years out of date before it is analysed.","C":"It can be expensive and time-consuming to collect and collate.","D":"It cannot be used to find out consumers' opinions about a new product."},"correctOption":"C","correctAnswer":"It can be expensive and time-consuming to collect and collate.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because designing surveys, interviewing respondents, and analysing original data requires significant time and financial expenditure.","distractor_reasons":{"A":"Incorrect because exclusive ownership of the findings is an advantage of primary research, not a disadvantage.","B":"Incorrect because being out of date is a common disadvantage of secondary data, whereas primary data is current.","C":"Correct selection.","D":"Incorrect because discovering consumer opinions and preferences is one of the main strengths of primary research."}}},{"id":"P1_U3_MCQ_532","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_532","question":"Which of the following are all methods of primary market research?","options":{"A":"Government census reports, trade magazines, and competitor websites.","B":"Market research agency reports, newspaper articles, and internal sales records.","C":"Focus groups, trade journals, and national income statistics.","D":"Questionnaires, interviews, focus groups, and observation."},"correctOption":"D","correctAnswer":"Questionnaires, interviews, focus groups, and observation.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because questionnaires (surveys), interviews, focus groups, and observation all involve collecting original, first-hand data directly from consumers.","distractor_reasons":{"A":"Incorrect because census reports, trade magazines, and competitor websites are all secondary research sources.","B":"Incorrect because published market reports, newspapers, and internal records are secondary data.","C":"Incorrect because trade journals and national income statistics are secondary sources.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_533","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_533","question":"What is an advantage of using 'online questionnaires' compared to postal questionnaires?","options":{"A":"They are faster and cheaper to distribute and analyse, and can reach respondents worldwide.","B":"They guarantee a 100% response rate from every person who receives a link.","C":"They allow an interviewer to explain ambiguous questions face-to-face.","D":"They effectively reach consumers who have no access to the internet."},"correctOption":"A","correctAnswer":"They are faster and cheaper to distribute and analyse, and can reach respondents worldwide.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because online questionnaires eliminate printing and postage costs, reach a wide geographic audience quickly, and allow automated data collation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because online surveys still suffer from non-response as many people ignore survey links.","C":"Incorrect because questionnaires are self-completed without an interviewer present to clarify questions.","D":"Incorrect because lack of internet access among some groups is actually a disadvantage of online questionnaires."}}},{"id":"P1_U3_MCQ_534","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_534","question":"What is a disadvantage of using 'questionnaires' as a primary research method?","options":{"A":"It is impossible to ask closed 'Yes/No' questions on a questionnaire.","B":"Respondents cannot ask for clarification if a question is ambiguous, and response rates can be low.","C":"Questionnaires can only ever be conducted with one person per week.","D":"They always suffer from direct interviewer body-language bias."},"correctOption":"B","correctAnswer":"Respondents cannot ask for clarification if a question is ambiguous, and response rates can be low.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because self-completed questionnaires offer no opportunity to explain unclear questions or probe deeper, and postal or online surveys often suffer from low response rates.","distractor_reasons":{"A":"Incorrect because closed questions are very commonly used in questionnaires.","B":"Correct selection.","C":"Incorrect because questionnaires can be distributed to thousands of people simultaneously.","D":"Incorrect because interviewer bias occurs during face-to-face or phone interviews rather than self-completed questionnaires."}}},{"id":"P1_U3_MCQ_535","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_535","question":"What is a key advantage of using 'interviews' rather than self-completed questionnaires?","options":{"A":"Interviews are much cheaper and faster to conduct across large samples.","B":"Interviews completely eliminate any possibility of interviewer bias.","C":"The interviewer can explain misunderstood questions and ask follow-up questions for detailed answers.","D":"Interviews require no trained staff to ask questions or record answers."},"correctOption":"C","correctAnswer":"The interviewer can explain misunderstood questions and ask follow-up questions for detailed answers.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because interviews allow two-way interaction, enabling the interviewer to clarify confusing questions, build rapport, and ask follow-up questions.","distractor_reasons":{"A":"Incorrect because interviews are time-consuming and expensive, leading to smaller sample sizes.","B":"Incorrect because interviewer bias (leading the interviewee) is a major disadvantage of interviews.","C":"Correct selection.","D":"Incorrect because effective interviews require skilled interviewers to avoid bias and build trust."}}},{"id":"P1_U3_MCQ_536","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_536","question":"What is meant by 'interviewer bias' in primary market research?","options":{"A":"When a respondent refuses to answer any open-ended questions.","B":"When government statistics contain outdated population figures.","C":"When a sample is too large to be analysed on a computer.","D":"When the interviewer consciously or subconsciously leads the interviewee into answering in a certain way."},"correctOption":"D","correctAnswer":"When the interviewer consciously or subconsciously leads the interviewee into answering in a certain way.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because interviewer bias happens when the interviewer's tone, wording, or reaction influences the respondent's answers, distorting the research results.","distractor_reasons":{"A":"Incorrect because refusal to answer is non-response rather than interviewer bias.","B":"Incorrect because outdated government statistics relate to secondary data accuracy.","C":"Incorrect because a large sample improves accuracy rather than causing interviewer bias.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_537","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_537","question":"What is a 'focus group' in market research?","options":{"A":"A group of people representative of the target market brought together to discuss opinions about products and promotions.","B":"A team of company directors who set the annual marketing budget.","C":"A random crowd of passers-by counted silently by a researcher in a shopping mall.","D":"A panel of government officials who approve product safety labels."},"correctOption":"A","correctAnswer":"A group of people representative of the target market brought together to discuss opinions about products and promotions.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a focus group consists of selected members of the target market who participate in a guided group discussion to share detailed views on products, packaging, or adverts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because directors setting budgets are internal decision-makers, not a market research sample.","C":"Incorrect because silently watching and counting shoppers describes observation, not a focus group.","D":"Incorrect because government safety regulators are external authorities, not consumer focus groups."}}},{"id":"P1_U3_MCQ_538","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_538","question":"What is a key disadvantage of using focus groups for primary market research?","options":{"A":"Participants are forbidden from interacting with one another during the session.","B":"Discussion can be biased if dominant or argumentative individuals influence other members' opinions.","C":"They provide zero qualitative insight into why consumers prefer certain features.","D":"They always cost more per person than conducting individual one-to-one interviews."},"correctOption":"B","correctAnswer":"Discussion can be biased if dominant or argumentative individuals influence other members' opinions.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because outspoken or dominant individuals in a focus group can sway the discussion and pressure quieter participants, causing biased results.","distractor_reasons":{"A":"Incorrect because interaction among participants is a core feature and advantage of focus groups.","B":"Correct selection.","C":"Incorrect because gaining detailed qualitative opinions is the main strength of focus groups.","D":"Incorrect because focus groups are usually quicker and cheaper than interviewing each person individually."}}},{"id":"P1_U3_MCQ_539","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_539","question":"What is 'observation' as a method of primary market research?","options":{"A":"Reading competitor websites to record their current selling prices.","B":"Sending postal surveys to households asking about their weekly spending.","C":"Watching and recording consumer behaviour and actions when buying or choosing between products.","D":"Interviewing customers in depth about their emotional feelings toward a brand."},"correctOption":"C","correctAnswer":"Watching and recording consumer behaviour and actions when buying or choosing between products.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because observation collects primary data by watching and recording actual consumer behaviour (such as footfall or shelf selection) without questioning them.","distractor_reasons":{"A":"Incorrect because checking competitor websites is secondary desk research.","B":"Incorrect because sending surveys uses questionnaires rather than observation.","C":"Correct selection.","D":"Incorrect because observation records actions but cannot uncover underlying motives or feelings without questioning."}}},{"id":"P1_U3_MCQ_540","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_540","question":"What is the main limitation of observation as a market research method?","options":{"A":"Consumers frequently lie to researchers during observation.","B":"It is illegal to watch shoppers in public retail stores.","C":"It cannot record how many customers enter a store or look at a display.","D":"Because consumers are not questioned, the underlying reasons for their actions cannot be identified."},"correctOption":"D","correctAnswer":"Because consumers are not questioned, the underlying reasons for their actions cannot be identified.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because observation only reveals what consumers do (their actions), not why they behaved that way, since no questions are asked.","distractor_reasons":{"A":"Incorrect because an advantage of observation is that shoppers act naturally rather than trying to please or mislead an interviewer.","B":"Incorrect because observing customer traffic and behaviour in stores is standard, legal market research practice.","C":"Incorrect because counting shoppers and tracking display views is exactly what observation does well.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_541","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_541","question":"What is meant by a 'sample' in market research?","options":{"A":"The group of people selected to respond to a market research exercise, representing the target population.","B":"Every single consumer who lives within a country's borders.","C":"A free miniature product given away as part of a sales promotion.","D":"A secondary report published by a government statistical office."},"correctOption":"A","correctAnswer":"The group of people selected to respond to a market research exercise, representing the target population.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a sample is a smaller group of people selected from the target market population to participate in market research so their views represent the whole group.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because surveying every person in a country is a full population census, not a sample.","C":"Incorrect because a promotional giveaway is a free sample product, not a research sample.","D":"Incorrect because a government report is a secondary data source."}}},{"id":"P1_U3_MCQ_542","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_542","question":"How does 'quota sampling' differ from 'random sampling'?","options":{"A":"Quota sampling selects people entirely by chance, whereas random sampling selects by age or gender.","B":"Quota sampling selects people based on specific characteristics (such as age or income), whereas random sampling selects people entirely by chance.","C":"Quota sampling surveys the entire population, whereas random sampling surveys only business owners.","D":"Quota sampling uses only secondary data, whereas random sampling uses only primary data."},"correctOption":"B","correctAnswer":"Quota sampling selects people based on specific characteristics (such as age or income), whereas random sampling selects people entirely by chance.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because random sampling gives every member of the population an equal chance of selection purely by chance, whereas quota sampling selects specific proportions of people based on characteristics like age, gender, or income.","distractor_reasons":{"A":"Incorrect because this reverses the definitions of random sampling and quota sampling.","B":"Correct selection.","C":"Incorrect because both are sampling methods that survey a subset of the target population rather than everyone.","D":"Incorrect because both random and quota sampling are used to select respondents for primary research."}}},{"id":"P1_U3_MCQ_543","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_543","question":"Why is sampling useful to businesses conducting market research?","options":{"A":"It guarantees that market research results will always be 100% accurate.","B":"It removes the need to design clear, unbiased questionnaire questions.","C":"It saves time and money compared to surveying the entire target population while still providing representative results.","D":"It allows a business to avoid analysing the data after collection."},"correctOption":"C","correctAnswer":"It saves time and money compared to surveying the entire target population while still providing representative results.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because surveying every consumer in a market is impractical and costly; a well-chosen sample saves time and money while representing the target population.","distractor_reasons":{"A":"Incorrect because sampling always carries a margin of error and never guarantees 100% accuracy.","B":"Incorrect because poorly worded questions will still distort results regardless of how the sample is chosen.","C":"Correct selection.","D":"Incorrect because collected sample data must still be collated, presented, and analysed."}}},{"id":"P1_U3_MCQ_544","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_544","question":"What is 'secondary market research' (desk research)?","options":{"A":"Collecting brand-new data by interviewing customers outside a retail shop.","B":"Research conducted only after a product has reached the decline stage.","C":"Research carried out exclusively by manufacturing firms in the secondary sector.","D":"Using information that has already been collected and is available for use by others."},"correctOption":"D","correctAnswer":"Using information that has already been collected and is available for use by others.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because secondary (desk) research uses existing data that was previously collected for another purpose, either internally or by external organisations.","distractor_reasons":{"A":"Incorrect because interviewing customers directly collects original data, which is primary research.","B":"Incorrect because secondary research is typically the first step before primary research at any product stage.","C":"Incorrect because 'secondary' refers to second-hand data, not the secondary manufacturing sector.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_545","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_545","question":"What is a major advantage of secondary market research?","options":{"A":"It is usually quicker and cheaper to obtain than conducting primary research.","B":"The data is always collected exclusively for the business's specific new product.","C":"Competitors are legally prevented from accessing the same published reports.","D":"The statistics are always guaranteed to reflect yesterday's consumer preferences."},"correctOption":"A","correctAnswer":"It is usually quicker and cheaper to obtain than conducting primary research.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because secondary data already exists (often free or low-cost online or in government publications), making it much faster and cheaper to gather than primary research.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because secondary data was collected for other purposes and may not be specific to the business's needs.","C":"Incorrect because external secondary data is generally available to all competing businesses.","D":"Incorrect because secondary data can be several years out of date."}}},{"id":"P1_U3_MCQ_546","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_546","question":"What is a common disadvantage of using government sources (such as a national census) for secondary market research?","options":{"A":"They are extremely expensive for a small business to access.","B":"They may be out of date (e.g., collected every 10 years) and are not specific to an individual product or brand.","C":"They provide information only about a single town rather than national regions.","D":"They rely entirely on biased opinions from focus groups."},"correctOption":"B","correctAnswer":"They may be out of date (e.g., collected every 10 years) and are not specific to an individual product or brand.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because government censuses are infrequent (often every 10 years) so data can be outdated, and they provide broad demographic data rather than product-specific market insights.","distractor_reasons":{"A":"Incorrect because government statistics are usually free and widely accessible online or in libraries.","B":"Correct selection.","C":"Incorrect because government sources cover both national and regional levels.","D":"Incorrect because government statistics are based on official demographic and economic records, not focus groups."}}},{"id":"P1_U3_MCQ_547","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_547","question":"Which statement describes a disadvantage of using 'market reports' produced by specialist agencies?","options":{"A":"They never contain any data about industry trends or competitors.","B":"They are written purely for entertainment rather than business analysis.","C":"They can be expensive to purchase and may become out of date quickly in fast-changing markets.","D":"They are illegal for businesses to use when planning a marketing strategy."},"correctOption":"C","correctAnswer":"They can be expensive to purchase and may become out of date quickly in fast-changing markets.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because specialist market research agencies charge high fees for detailed market reports, and reports not updated annually can quickly become outdated.","distractor_reasons":{"A":"Incorrect because detailed industry and competitor data is precisely what market reports provide.","B":"Incorrect because market reports are professional analytical documents created for businesses.","C":"Correct selection.","D":"Incorrect because purchasing commercial market reports is a standard, legal research practice."}}},{"id":"P1_U3_MCQ_548","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_548","question":"What is a limitation of using 'trade magazines' as a source of secondary market research?","options":{"A":"They contain zero information about the industry in which the business operates.","B":"They are strictly confidential and cannot be read by small business owners.","C":"They are always published once every ten years like a national census.","D":"Articles and opinions may be influenced by major advertisers and lack verified research methods."},"correctOption":"D","correctAnswer":"Articles and opinions may be influenced by major advertisers and lack verified research methods.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade magazines do not use rigorous research agency methodologies and their editorial opinions may be biased toward major industry advertisers.","distractor_reasons":{"A":"Incorrect because trade magazines focus specifically on news and trends within a particular industry.","B":"Incorrect because trade magazines are publicly available to managers and businesses in that sector.","C":"Incorrect because trade magazines are typically published weekly or monthly, not every ten years.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_549","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_549","question":"How does 'sample size' influence the accuracy of primary market research data?","options":{"A":"A larger sample generally produces more accurate and reliable results, though at a higher cost.","B":"A smaller sample always produces more accurate results because fewer opinions conflict.","C":"Sample size has no effect on accuracy as long as secondary data is ignored.","D":"A sample size of fewer than five people is ideal for nationwide mass markets."},"correctOption":"A","correctAnswer":"A larger sample generally produces more accurate and reliable results, though at a higher cost.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because surveying a larger number of representative respondents reduces sampling error and increases reliability, though it increases research costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a very small sample is unlikely to reflect the diverse views of the whole target market.","C":"Incorrect because sample size is one of the primary determinants of survey reliability.","D":"Incorrect because a sample of fewer than five people is far too small to represent a nationwide mass market."}}},{"id":"P1_U3_MCQ_550","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_550","question":"Which set of factors directly affects the accuracy and reliability of market research data?","options":{"A":"Span of control, chain of command, and leadership style.","B":"Sample selection, sample size, question wording, bias, and age of the information.","C":"Channel of distribution, packaging colour, and brand logo.","D":"Import tariffs, exchange rates, and factory location."},"correctOption":"B","correctAnswer":"Sample selection, sample size, question wording, bias, and age of the information.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because data accuracy depends on how representative the sample is, sample size, clear unbiased question wording, absence of researcher/source bias, and how current the data is.","distractor_reasons":{"A":"Incorrect because these are organizational management concepts rather than market research factors.","B":"Correct selection.","C":"Incorrect because these are elements of the marketing mix rather than research reliability factors.","D":"Incorrect because these are external economic and operational factors."}}},{"id":"P1_U3_MCQ_551","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_551","question":"What is meant by the term 'brand image'?","options":{"A":"The legal contract signed between a manufacturer and a wholesaler.","B":"The physical cardboard box used to protect a product during transport.","C":"An image or identity given to a product which distinguishes it from competitors' brands.","D":"The percentage of total market sales held by a single business."},"correctOption":"C","correctAnswer":"An image or identity given to a product which distinguishes it from competitors' brands.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because brand image is the unique identity and perception created for a product in the minds of consumers that differentiates it from rival products.","distractor_reasons":{"A":"Incorrect because a contract between channel members is a distribution agreement, not brand image.","B":"Incorrect because the physical container is packaging, which supports brand image rather than defining it.","C":"Correct selection.","D":"Incorrect because percentage of total sales defines market share."}}},{"id":"P1_U3_MCQ_552","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_552","question":"What is 'brand loyalty'?","options":{"A":"When a business refuses to change its product design for fifty years.","B":"When retailers agree to stock only one manufacturer's products.","C":"When a government protects a company's logo from being copied.","D":"When consumers keep buying the same brand instead of choosing a competitor's product."},"correctOption":"D","correctAnswer":"When consumers keep buying the same brand instead of choosing a competitor's product.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because brand loyalty occurs when consumers repeatedly choose and purchase the same brand over rival brands.","distractor_reasons":{"A":"Incorrect because failing to update products usually causes declining sales rather than loyalty.","B":"Incorrect because retailer stocking decisions relate to distribution channels, not consumer brand loyalty.","C":"Incorrect because legal protection of a logo is trademark law, not brand loyalty.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_553","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_553","question":"How does a strong brand image benefit a business?","options":{"A":"Consumers become less price sensitive and are often willing to pay higher prices than for unbranded goods.","B":"The business no longer needs to maintain consistent product quality.","C":"It eliminates all costs of advertising and promotion permanently.","D":"It prevents any new competitors from ever entering the industry."},"correctOption":"A","correctAnswer":"Consumers become less price sensitive and are often willing to pay higher prices than for unbranded goods.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a strong brand image builds trust and desirability, making consumers less price sensitive and willing to pay higher prices than for unbranded equivalents.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because poor quality quickly destroys a brand's reputation and image.","C":"Incorrect because strong brands require ongoing advertising to maintain and reinforce their image.","D":"Incorrect because strong brand loyalty makes entry harder for rivals but does not legally block them."}}},{"id":"P1_U3_MCQ_554","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_554","question":"Which of the following correctly describes the main roles of 'packaging'?","options":{"A":"To increase shipping weight, hide product ingredients, and raise manufacturing costs.","B":"To protect the product, promote it, support the brand image, and provide required product information.","C":"To replace the need for distribution channels and retail stores.","D":"To prevent consumers from comparing the product with competing brands."},"correctOption":"B","correctAnswer":"To protect the product, promote it, support the brand image, and provide required product information.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because packaging performs four key roles: protecting the product during transport/use, attracting customers (promotion), reinforcing brand image, and displaying legal/usage information.","distractor_reasons":{"A":"Incorrect because packaging must legally show ingredients/allergens on food items and should minimise unnecessary weight and cost.","B":"Correct selection.","C":"Incorrect because packaging facilitates transport through distribution channels rather than replacing them.","D":"Incorrect because packaging displays product details that help consumers compare items."}}},{"id":"P1_U3_MCQ_555","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_555","question":"What is meant by a 'Unique Selling Point (USP)'?","options":{"A":"The single retail shop where a product is exclusively sold.","B":"The lowest possible price at which a product can break even.","C":"The special feature of a product that differentiates it from the products of competitors.","D":"A one-day sales promotion offering free samples to passers-by."},"correctOption":"C","correctAnswer":"The special feature of a product that differentiates it from the products of competitors.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a Unique Selling Point (USP) is a distinctive feature, design, or benefit of a product that sets it apart from competing products.","distractor_reasons":{"A":"Incorrect because where a product is sold relates to 'place' (distribution), not its USP.","B":"Incorrect because break-even price is a financial/pricing calculation, not a product feature.","C":"Correct selection.","D":"Incorrect because free samples are a short-term sales promotion method."}}},{"id":"P1_U3_MCQ_556","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_556","question":"Which statement describes an advantage of developing new products?","options":{"A":"It requires zero market research or technical development expenditure.","B":"It guarantees that every new launch will immediately earn a high profit.","C":"It prevents competitors from ever developing similar technology.","D":"It creates diversification, reducing the business's reliance on existing products and markets."},"correctOption":"D","correctAnswer":"It creates diversification, reducing the business's reliance on existing products and markets.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because developing new products broadens a firm's product range (diversification), reducing dependence on existing products whose sales may eventually decline.","distractor_reasons":{"A":"Incorrect because high research and development costs are a major disadvantage of new product development.","B":"Incorrect because new products carry a high risk of low sales and financial failure.","C":"Incorrect because successful new products are often quickly copied by competitors.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_557","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_557","question":"What is a major disadvantage of developing new products?","options":{"A":"High research and development costs and the risk that consumer demand may be too low to make a profit.","B":"It damages the business's reputation for being innovative and creative.","C":"It prevents the business from entering export markets in other countries.","D":"It forces the business to withdraw all its profitable existing products."},"correctOption":"A","correctAnswer":"High research and development costs and the risk that consumer demand may be too low to make a profit.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because developing new products involves expensive market research and technical R&D, with no guarantee that enough consumers will buy the product to cover those costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because successful new products actually enhance a brand's reputation for innovation.","C":"Incorrect because developing products tailored to foreign tastes helps firms enter export markets.","D":"Incorrect because businesses routinely sell new products alongside existing profitable lines."}}},{"id":"P1_U3_MCQ_558","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_558","question":"What are the four main stages of the 'product life cycle' in chronological order?","options":{"A":"Research, testing, pricing, and advertising.","B":"Introduction, growth, maturity, and decline.","C":"Primary, secondary, tertiary, and quaternary.","D":"Planning, organising, commanding, and controlling."},"correctOption":"B","correctAnswer":"Introduction, growth, maturity, and decline.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the standard product life cycle traces a product's sales from Introduction, through Growth and Maturity, to Decline.","distractor_reasons":{"A":"Incorrect because these are pre-launch marketing activities rather than life cycle stages.","B":"Correct selection.","C":"Incorrect because these are economic sectors of industry.","D":"Incorrect because these are the functions of management."}}},{"id":"P1_U3_MCQ_559","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_559","question":"Which characteristics best describe the 'introduction' stage of the product life cycle?","options":{"A":"Sales reach their peak, competition is intense, and prices are heavily discounted.","B":"Sales fall rapidly as the product becomes technologically obsolete.","C":"Sales grow slowly because few consumers are aware of the product, and profit is often low or negative due to high development and launch costs.","D":"Sales grow at their fastest rate and brand loyalty is already firmly established."},"correctOption":"C","correctAnswer":"Sales grow slowly because few consumers are aware of the product, and profit is often low or negative due to high development and launch costs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because at the introduction stage consumer awareness is low so sales grow slowly, while heavy launch advertising and unrecovered R&D costs keep profit low or negative.","distractor_reasons":{"A":"Incorrect because peak sales and intense competition characterize the maturity stage.","B":"Incorrect because rapidly falling sales due to obsolescence describe the decline stage.","C":"Correct selection.","D":"Incorrect because rapid sales acceleration describes the growth stage."}}},{"id":"P1_U3_MCQ_560","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_560","question":"What happens during the 'maturity' stage of the product life cycle?","options":{"A":"The product is launched for the first time and consumers have never heard of it.","B":"Sales fall sharply and the product is immediately withdrawn from sale.","C":"There are zero competitors in the market and development costs have not yet been recovered.","D":"Sales growth slows down and reaches a peak, competition becomes intense, and extension strategies may be considered."},"correctOption":"D","correctAnswer":"Sales growth slows down and reaches a peak, competition becomes intense, and extension strategies may be considered.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because in the maturity stage sales level off at their peak, competition is fierce, and businesses use heavy promotion or extension strategies to maintain sales.","distractor_reasons":{"A":"Incorrect because initial launch with low awareness describes the introduction stage.","B":"Incorrect because sharp falls and withdrawal occur in the decline stage.","C":"Incorrect because absence of rivals and unrecovered R&D occur in the introduction stage.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_561","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_561","question":"What is the purpose of an 'extension strategy' in the product life cycle?","options":{"A":"To keep a product at the maturity stage of its life cycle and prolong its profitable sales before decline sets in.","B":"To speed up the decline stage so a product can be withdrawn earlier.","C":"To increase the length of the chain of command in the marketing department.","D":"To delay launching a newly developed product until competitors leave the market."},"correctOption":"A","correctAnswer":"To keep a product at the maturity stage of its life cycle and prolong its profitable sales before decline sets in.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because extension strategies aim to boost demand and keep a product in the maturity stage for longer, postponing decline and avoiding immediate R&D costs for a replacement.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because extension strategies aim to prevent or delay decline, not accelerate it.","C":"Incorrect because chain of command relates to organizational structure, not the product life cycle.","D":"Incorrect because extension strategies apply to existing mature products rather than delaying new launches."}}},{"id":"P1_U3_MCQ_562","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_562","question":"Which of the following are recognised product life cycle extension strategies?","options":{"A":"Increasing unit production costs, reducing product quality, and stopping all advertising.","B":"Entering new markets, finding new uses for the product, adapting the product or packaging, and increasing advertising/sales promotion.","C":"Conducting random sampling, using trade magazines, and hiring external auditors.","D":"Downsizing the workforce, delayering management, and selling off factories."},"correctOption":"B","correctAnswer":"Entering new markets, finding new uses for the product, adapting the product or packaging, and increasing advertising/sales promotion.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the five core extension strategies are selling into new markets, finding new uses, adapting the product, adapting the packaging, and increasing advertising or sales promotion.","distractor_reasons":{"A":"Incorrect because raising costs, cutting quality, and halting promotion would accelerate product decline.","B":"Correct selection.","C":"Incorrect because these are market research and accounting activities, not product extension strategies.","D":"Incorrect because these are organizational restructuring actions rather than marketing extension strategies."}}},{"id":"P1_U3_MCQ_563","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_563","question":"What is a key advantage of finding 'new uses' for an existing product as an extension strategy?","options":{"A":"No advertising or promotion is needed to inform consumers about the new use.","B":"Competitors are legally barred from copying the new use.","C":"No physical changes to the product are required, which helps keep production costs down.","D":"It guarantees that existing customers will double their weekly purchases immediately."},"correctOption":"C","correctAnswer":"No physical changes to the product are required, which helps keep production costs down.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because promoting a new use for an already well-known product requires no costly redesign or manufacturing changes.","distractor_reasons":{"A":"Incorrect because new advertising and promotion are essential to inform consumers about the alternative use.","B":"Incorrect because rival firms can also promote the same alternative use for their versions.","C":"Correct selection.","D":"Incorrect because consumers may be reluctant to change how they use a familiar product, so sales increases are not guaranteed."}}},{"id":"P1_U3_MCQ_564","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_564","question":"How is 'cost-plus pricing' determined?","options":{"A":"Setting the price lower than competitors' prices to enter a new market quickly.","B":"Varying prices continuously online according to real-time changes in customer demand.","C":"Setting the price at the exact same level as the market leader.","D":"Calculating the unit cost of manufacturing or supplying the product and adding a percentage mark-up for profit."},"correctOption":"D","correctAnswer":"Calculating the unit cost of manufacturing or supplying the product and adding a percentage mark-up for profit.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cost-plus pricing calculates the average cost per unit and adds a predetermined percentage mark-up to ensure a profit margin on each unit sold.","distractor_reasons":{"A":"Incorrect because setting a price below competitors to gain market share is penetration pricing.","B":"Incorrect because changing prices in response to real-time demand is dynamic pricing.","C":"Incorrect because matching rivals' prices is competitive pricing.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_565","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_565","question":"What is a major disadvantage of 'cost-plus pricing'?","options":{"A":"It ignores competitors' prices and whether consumers are actually willing to pay the calculated price.","B":"It is extremely complex and impossible to calculate once unit costs are known.","C":"It forces a business to sell every unit below its average cost of production.","D":"It cannot be adjusted to use different profit mark-ups in different markets."},"correctOption":"A","correctAnswer":"It ignores competitors' prices and whether consumers are actually willing to pay the calculated price.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost-plus pricing focuses purely on internal costs plus a mark-up, ignoring market demand and competitors' prices—which can result in low sales if the price is too high.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ease of calculation is actually one of the main advantages of cost-plus pricing.","C":"Incorrect because adding a positive mark-up sets the price above average unit cost (provided expected output is sold).","D":"Incorrect because businesses can apply different percentage mark-ups in different market segments."}}},{"id":"P1_U3_MCQ_566","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_566","question":"What is meant by 'competitive pricing'?","options":{"A":"Setting a very high initial price for a newly invented luxury product.","B":"Setting the price of a product in line with competitors' prices to maintain sales and market share.","C":"Setting a price significantly below rivals' prices to penetrate a new market.","D":"Charging different customers different prices based on their online browsing history."},"correctOption":"B","correctAnswer":"Setting the price of a product in line with competitors' prices to maintain sales and market share.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because competitive pricing sets prices at a similar level to competitors' prices for comparable products in order to protect sales and market share.","distractor_reasons":{"A":"Incorrect because setting a high initial price for a new product is price skimming.","B":"Correct selection.","C":"Incorrect because pricing below competitors to enter a market is penetration pricing.","D":"Incorrect because varying prices based on demand or customer data is dynamic pricing."}}},{"id":"P1_U3_MCQ_567","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_567","question":"What is a potential disadvantage of using 'competitive pricing'?","options":{"A":"It always triggers a destructive price war that drives prices down to zero.","B":"It requires complicated mathematical formulas to estimate future demand elasticity.","C":"If a business has higher average costs than its competitors, matching their low prices may result in a loss.","D":"Consumers will automatically assume the product is a rare luxury item."},"correctOption":"C","correctAnswer":"If a business has higher average costs than its competitors, matching their low prices may result in a loss.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because if competitors benefit from lower average costs (e.g., through economies of scale), a higher-cost business matching their prices may fail to cover its costs and make a loss.","distractor_reasons":{"A":"Incorrect because matching competitors' prices actually helps avoid a price war.","B":"Incorrect because competitive pricing is simple to use by surveying rivals' prices.","C":"Correct selection.","D":"Incorrect because matching average market prices does not create a luxury image."}}},{"id":"P1_U3_MCQ_568","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_568","question":"What is 'penetration pricing'?","options":{"A":"Setting a high price when launching a unique, technologically advanced product.","B":"Adding a fixed 50% mark-up onto the total production cost of each unit.","C":"Raising prices sharply during peak holiday travel seasons.","D":"Setting a price lower than competitors' prices when entering a new market in order to gain market share quickly."},"correctOption":"D","correctAnswer":"Setting a price lower than competitors' prices when entering a new market in order to gain market share quickly.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because penetration pricing involves launching a product at a lower price than competitors to attract buyers quickly and build market share.","distractor_reasons":{"A":"Incorrect because setting a high launch price is price skimming.","B":"Incorrect because adding a percentage profit mark-up to cost is cost-plus pricing.","C":"Incorrect because varying prices with seasonal demand is dynamic pricing.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_569","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_569","question":"Which of the following is a disadvantage of 'penetration pricing'?","options":{"A":"Profit per unit is low in the short term, and customers may stop buying if the business later tries to raise the price.","B":"It is completely ineffective at attracting price-sensitive consumers to try a new product.","C":"It creates an overly luxurious brand image that intimidates everyday shoppers.","D":"It immediately recovers high research and development costs within the first week."},"correctOption":"A","correctAnswer":"Profit per unit is low in the short term, and customers may stop buying if the business later tries to raise the price.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because low penetration prices yield low unit profit margins (or short-term losses) and condition consumers to expect a low price, making future price increases risky.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because attracting price-sensitive buyers to try a new product is the main advantage of penetration pricing.","C":"Incorrect because a low price can actually undermine a high-quality or luxury brand image.","D":"Incorrect because quickly recovering high R&D costs is an advantage of price skimming, not penetration pricing."}}},{"id":"P1_U3_MCQ_570","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_570","question":"What is 'price skimming'?","options":{"A":"Setting a price below average cost to drive all existing competitors out of business.","B":"Setting a high initial price for a newly developed or innovative product on the market.","C":"Matching the lowest price offered by any supermarket in the local area.","D":"Reducing prices automatically whenever online website traffic drops."},"correctOption":"B","correctAnswer":"Setting a high initial price for a newly developed or innovative product on the market.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because price skimming sets a high initial price for a new or uniquely differentiated product to earn high unit profits and reinforce a high-quality image before competitors enter.","distractor_reasons":{"A":"Incorrect because pricing below competitors to gain market share is penetration pricing.","B":"Correct selection.","C":"Incorrect because matching rivals' prices is competitive pricing.","D":"Incorrect because adjusting prices in response to online demand is dynamic pricing."}}},{"id":"P1_U3_MCQ_571","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_571","question":"Why might a business choose to use 'price skimming' when launching a new product?","options":{"A":"To appeal to low-income consumers who only buy discounted goods.","B":"To avoid having to differentiate the product from older competing models.","C":"To earn high profit per unit and quickly recover high research and development costs.","D":"To discourage any competitors from ever noticing the profitability of the market."},"correctOption":"C","correctAnswer":"To earn high profit per unit and quickly recover high research and development costs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because high skimming prices generate high profit margins per unit sold, helping the business quickly recoup expensive research and development costs while reinforcing a prestige image.","distractor_reasons":{"A":"Incorrect because high skimming prices exclude low-income buyers and target early adopters willing to pay a premium.","B":"Incorrect because price skimming only works if the product is clearly differentiated and superior to existing products.","C":"Correct selection.","D":"Incorrect because high profits from price skimming actually attract competitors into the market—a key disadvantage."}}},{"id":"P1_U3_MCQ_572","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_572","question":"What is meant by 'dynamic pricing'?","options":{"A":"Keeping the exact same fixed price printed in a catalogue for an entire year.","B":"Calculating price strictly by adding a fixed percentage mark-up to variable cost.","C":"Setting a permanent low price to enter a foreign export market.","D":"Changing the price of a product, usually when selling online, depending on the changing level of demand."},"correctOption":"D","correctAnswer":"Changing the price of a product, usually when selling online, depending on the changing level of demand.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because dynamic pricing flexibly adjusts prices—commonly via online platforms—rising when demand is high and falling when demand is low to maximise revenue.","distractor_reasons":{"A":"Incorrect because dynamic pricing is the opposite of fixed pricing.","B":"Incorrect because adding a mark-up to cost is cost-plus pricing.","C":"Incorrect because a low entry price is penetration pricing.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_573","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_573","question":"What is a major advantage of 'dynamic pricing' for businesses such as airlines and hotels?","options":{"A":"It helps sell all available capacity at varying prices, maximising total revenue and reducing unsold waste.","B":"It guarantees that every customer pays the exact same price regardless of booking time.","C":"It completely eliminates customer confusion and dissatisfaction over price changes.","D":"It removes the need for any online booking or IT systems."},"correctOption":"A","correctAnswer":"It helps sell all available capacity at varying prices, maximising total revenue and reducing unsold waste.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dynamic pricing raises prices during peak demand and lowers them when spare capacity remains, maximising total revenue and ensuring seats or rooms do not go unsold.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because customers pay different prices depending on when they purchase and current demand levels.","C":"Incorrect because customer confusion and dissatisfaction when seeing different prices is a disadvantage of dynamic pricing.","D":"Incorrect because dynamic pricing relies heavily on real-time IT and online sales systems."}}},{"id":"P1_U3_MCQ_574","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_574","question":"What is meant by 'price elasticity of demand'?","options":{"A":"The total fixed cost divided by the selling price of a product.","B":"The responsiveness of quantity demanded of a product to a change in its price.","C":"The speed at which a manufacturer can increase factory output when raw material prices fall.","D":"The percentage of total market revenue controlled by the largest firm."},"correctOption":"B","correctAnswer":"The responsiveness of quantity demanded of a product to a change in its price.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because price elasticity of demand measures how sensitive or responsive the quantity demanded of a product is when its price changes.","distractor_reasons":{"A":"Incorrect because fixed costs divided by price relates to break-even analysis, not demand elasticity.","B":"Correct selection.","C":"Incorrect because the responsiveness of output to price changes describes price elasticity of supply.","D":"Incorrect because percentage of total market revenue defines market share."}}},{"id":"P1_U3_MCQ_575","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_575","question":"If demand for a product is 'price inelastic', what happens when the business increases the price?","options":{"A":"Quantity demanded falls by a greater percentage than the price increase, reducing total sales revenue.","B":"Quantity demanded falls to zero immediately because consumers switch to substitutes.","C":"Quantity demanded falls by a smaller percentage than the price increase, so total sales revenue rises.","D":"Quantity demanded increases in direct proportion to the price rise."},"correctOption":"C","correctAnswer":"Quantity demanded falls by a smaller percentage than the price increase, so total sales revenue rises.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when demand is price inelastic, consumers are relatively insensitive to price changes; quantity demanded drops by a smaller percentage than the price rise, causing total revenue to increase.","distractor_reasons":{"A":"Incorrect because quantity demanded falling by a larger percentage than the price rise describes price elastic demand.","B":"Incorrect because consumers switching away completely occurs when demand is perfectly elastic, not inelastic.","C":"Correct selection.","D":"Incorrect because higher prices reduce quantity demanded (the law of demand), rather than increasing it."}}},{"id":"P1_U3_MCQ_576","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_576","question":"What is meant by a 'distribution channel'?","options":{"A":"The paid television and social media advertisements used to promote a brand.","B":"The internal chain of command through which managers pass instructions to workers.","C":"The production line inside a factory that assembles raw materials into finished goods.","D":"The means by which a product is passed from the producer to the customer."},"correctOption":"D","correctAnswer":"The means by which a product is passed from the producer to the customer.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a distribution channel ('place') is the route or means by which goods and services move from the manufacturer/producer to the final customer.","distractor_reasons":{"A":"Incorrect because paid media messages belong to 'promotion', not 'place'.","B":"Incorrect because internal authority lines describe the chain of command in HRM/management.","C":"Incorrect because factory assembly is part of operations management, not distribution.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_577","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_577","question":"Which statement describes a 'direct channel of distribution' (producer direct to customer)?","options":{"A":"The producer sells directly to the final customer without using any intermediaries such as wholesalers or retailers.","B":"The producer sells in bulk to a wholesaler, who then supplies small independent retailers.","C":"The producer appoints an overseas agent to manage all sales and marketing in another country.","D":"The producer sells exclusively through large national supermarket chains."},"correctOption":"A","correctAnswer":"The producer sells directly to the final customer without using any intermediaries such as wholesalers or retailers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because direct distribution involves zero intermediaries—the producer sells straight to the customer via factory shops, mail order, or its own website.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because using wholesalers and retailers is a traditional multi-intermediary channel.","C":"Incorrect because appointing an agent introduces an intermediary into the channel.","D":"Incorrect because selling through supermarkets uses retailers as intermediaries."}}},{"id":"P1_U3_MCQ_578","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_578","question":"What is a key advantage to a manufacturer of selling directly to customers?","options":{"A":"Wholesalers hold all the inventory, reducing the manufacturer's storage costs.","B":"The manufacturer keeps all the profit and maintains complete control over how the product is marketed and priced.","C":"The manufacturer receives fewer individual orders and makes fewer delivery journeys.","D":"Customers can browse competing brands from many different manufacturers in one store."},"correctOption":"B","correctAnswer":"The manufacturer keeps all the profit and maintains complete control over how the product is marketed and priced.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because direct selling eliminates intermediary profit margins, allowing the producer to earn all the profit and control pricing, display, and promotion.","distractor_reasons":{"A":"Incorrect because holding inventory for many small orders is a disadvantage of direct selling; wholesalers reduce producer storage costs.","B":"Correct selection.","C":"Incorrect because selling directly to individual consumers increases the number of orders and deliveries.","D":"Incorrect because offering products from multiple producers is an advantage of retailers, not direct manufacturer outlets."}}},{"id":"P1_U3_MCQ_579","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_579","question":"What is the role of a 'retailer' in a distribution channel?","options":{"A":"To extract raw materials from the Earth for manufacturing businesses.","B":"To buy raw components in bulk and manufacture finished consumer goods.","C":"To buy products from producers or wholesalers and sell them to final customers in relatively small quantities.","D":"To pass laws protecting consumers from faulty goods and misleading advertisements."},"correctOption":"C","correctAnswer":"To buy products from producers or wholesalers and sell them to final customers in relatively small quantities.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a retailer is an intermediary business that purchases goods from producers or wholesalers and sells them in smaller quantities to final consumers.","distractor_reasons":{"A":"Incorrect because extracting natural resources is the role of primary sector businesses.","B":"Incorrect because manufacturing finished goods is the role of secondary sector producers.","C":"Correct selection.","D":"Incorrect because passing consumer protection laws is the role of the government."}}},{"id":"P1_U3_MCQ_580","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_580","question":"What is a disadvantage to a manufacturer of distributing products through retailers rather than directly to consumers?","options":{"A":"The manufacturer must process thousands of tiny individual customer deliveries.","B":"Customers have less choice because retailers only sell one brand.","C":"The manufacturer cannot focus on manufacturing because it must run retail shops.","D":"The manufacturer earns a lower profit per unit and loses direct contact with final customers."},"correctOption":"D","correctAnswer":"The manufacturer earns a lower profit per unit and loses direct contact with final customers.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retailers buy at a lower wholesale/trade price to earn their own profit margin, and the manufacturer loses direct customer contact and feedback.","distractor_reasons":{"A":"Incorrect because selling large quantities to retailers actually reduces the manufacturer's delivery and administration costs.","B":"Incorrect because retailers typically stock rival brands, giving customers more choice.","C":"Incorrect because using retailers frees the manufacturer to focus on production.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_581","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_581","question":"What is the main function of a 'wholesaler' in a distribution channel?","options":{"A":"Breaking bulk by buying in large quantities from manufacturers and selling in smaller quantities to retailers.","B":"Designing advertisements and television commercials for consumer brands.","C":"Selling single items directly to individual household consumers in high-street shops.","D":"Providing bank loans and overdrafts to start-up entrepreneurs."},"correctOption":"A","correctAnswer":"Breaking bulk by buying in large quantities from manufacturers and selling in smaller quantities to retailers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a wholesaler buys large bulk quantities from manufacturers, stores the inventory, and breaks bulk into smaller quantities for retailers to buy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because creating advertisements is the role of an advertising agency or marketing department.","C":"Incorrect because selling single items to final consumers is the role of a retailer.","D":"Incorrect because providing loans is the role of commercial banks, though wholesalers may offer trade credit on goods."}}},{"id":"P1_U3_MCQ_582","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_582","question":"How does using a wholesaler benefit a manufacturer?","options":{"A":"The final price paid by consumers is lower than in direct selling.","B":"The wholesaler holds most of the inventory, reducing the manufacturer's storage costs and number of delivery journeys.","C":"The manufacturer retains full control over which shops sell the product and at what retail price.","D":"The manufacturer receives immediate face-to-face feedback from every individual consumer."},"correctOption":"B","correctAnswer":"The wholesaler holds most of the inventory, reducing the manufacturer's storage costs and number of delivery journeys.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because wholesalers store large amounts of inventory and distribute to numerous small retailers, reducing the manufacturer's warehouse space, storage costs, and order processing.","distractor_reasons":{"A":"Incorrect because adding both a wholesaler and a retailer increases intermediary mark-ups and raises the final consumer price.","B":"Correct selection.","C":"Incorrect because manufacturers lose control over the selling process once goods are sold to wholesalers.","D":"Incorrect because two intermediaries separate the manufacturer from final consumers, preventing direct feedback."}}},{"id":"P1_U3_MCQ_583","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_583","question":"What is the role of an 'agent' in a distribution channel?","options":{"A":"A government inspector who tests whether imported goods meet safety regulations.","B":"A factory employee responsible for checking product quality on the assembly line.","C":"An independent person or business appointed to deal with the sales and distribution of a product, often in another country.","D":"A bank manager who approves mortgages for retail property owners."},"correctOption":"C","correctAnswer":"An independent person or business appointed to deal with the sales and distribution of a product, often in another country.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an agent is an independent intermediary appointed by a producer—frequently when entering foreign export markets—to handle local sales and distribution.","distractor_reasons":{"A":"Incorrect because government safety inspectors enforce legal compliance rather than distributing products.","B":"Incorrect because quality inspectors work within operations management inside a factory.","C":"Correct selection.","D":"Incorrect because bank managers provide financial services rather than product distribution."}}},{"id":"P1_U3_MCQ_584","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_584","question":"What is a key advantage of using an agent when selling products in another country?","options":{"A":"The producer retains 100% direct control over every marketing decision.","B":"Agents never charge any fees or commission for their distribution services.","C":"Agents always possess deeper technical knowledge of the product than the manufacturer.","D":"The agent has specialist local market knowledge of consumer tastes and distribution networks."},"correctOption":"D","correctAnswer":"The agent has specialist local market knowledge of consumer tastes and distribution networks.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because local agents understand the foreign market's culture, regulations, and distribution channels, increasing the likelihood of successful export sales.","distractor_reasons":{"A":"Incorrect because loss of control over how the product is marketed is a disadvantage of using an agent.","B":"Incorrect because agents charge fees or commission, which raises costs or final consumer prices.","C":"Incorrect because agents typically have less detailed product knowledge than the producer itself.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_585","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_585","question":"What is meant by 'ecommerce' (electronic commerce)?","options":{"A":"The online buying and selling of goods and services using internet-linked devices such as laptops and smartphones.","B":"Selling goods exclusively through printed mail-order catalogues sent by post.","C":"Using automated robots to assemble cars inside a manufacturing plant.","D":"Distributing leaflets by hand to shoppers in a local town centre."},"correctOption":"A","correctAnswer":"The online buying and selling of goods and services using internet-linked devices such as laptops and smartphones.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ecommerce refers to buying and selling goods and services over the internet via connected devices such as computers, tablets, and smartphones.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because printed mail-order catalogues do not use internet-linked electronic transactions.","C":"Incorrect because factory robotics relates to production technology (CAM), not ecommerce.","D":"Incorrect because handing out paper leaflets is traditional offline advertising."}}},{"id":"P1_U3_MCQ_586","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_586","question":"Which of the following are three common examples of ecommerce?","options":{"A":"Door-to-door selling, newspaper classified adverts, and cash-only market stalls.","B":"Mobile/internet banking, online shopping, and online ticketing.","C":"Wholesale cash-and-carry warehouses, postal questionnaires, and billboard posters.","D":"Job production, batch production, and flow production."},"correctOption":"B","correctAnswer":"Mobile/internet banking, online shopping, and online ticketing.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because mobile/internet banking, online shopping, and online ticketing (e-tickets) are key real-world applications of ecommerce.","distractor_reasons":{"A":"Incorrect because these are traditional offline trading and promotional methods.","B":"Correct selection.","C":"Incorrect because physical warehouses, postal mail, and roadside billboards are offline operations.","D":"Incorrect because these are the three main methods of manufacturing production."}}},{"id":"P1_U3_MCQ_587","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_587","question":"What is a major advantage of ecommerce for a retail business?","options":{"A":"Product return rates from customers fall to zero because buyers can try items on before ordering.","B":"There is zero competition from overseas producers when selling online.","C":"Websites allow the business to reach global markets 24/7 while reducing physical shop and sales staff costs.","D":"IT systems and websites never require updating or cybersecurity protection."},"correctOption":"C","correctAnswer":"Websites allow the business to reach global markets 24/7 while reducing physical shop and sales staff costs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because ecommerce enables 24/7 global sales through a website while lowering fixed overhead costs associated with operating high-street retail stores.","distractor_reasons":{"A":"Incorrect because higher product return rates (since buyers cannot touch or try items beforehand) are a disadvantage of online shopping.","B":"Incorrect because operating online increases global competition from low-cost international sellers.","C":"Correct selection.","D":"Incorrect because websites require frequent updates and face risks from hackers and IT failures."}}},{"id":"P1_U3_MCQ_588","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_588","question":"What is a key disadvantage of ecommerce for customers?","options":{"A":"Online stores are only open for four hours a day.","B":"Customers can never compare prices between different online sellers.","C":"Online prices are always higher than prices in physical high-street shops.","D":"Customers cannot physically touch, inspect, or try on products before buying, and face security/fraud risks."},"correctOption":"D","correctAnswer":"Customers cannot physically touch, inspect, or try on products before buying, and face security/fraud risks.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because online shoppers cannot physically inspect or try on goods prior to delivery, lose personal face-to-face advice, and risk payment fraud or identity theft.","distractor_reasons":{"A":"Incorrect because 24/7 convenience at any time of day is a major advantage for customers.","B":"Incorrect because easy price comparison across websites is a benefit to online shoppers.","C":"Incorrect because lower overhead costs often allow online retailers to offer lower prices than physical shops.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_589","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_589","question":"What is the overall aim of 'promotion' in the marketing mix?","options":{"A":"To raise customer awareness of a product or brand, generate sales, and help create brand loyalty.","B":"To calculate the exact break-even level of output for a factory.","C":"To transport raw materials from primary sector suppliers to manufacturers.","D":"To recruit and train new employees for the human resources department."},"correctOption":"A","correctAnswer":"To raise customer awareness of a product or brand, generate sales, and help create brand loyalty.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because promotion encompasses advertising and sales promotion activities designed to inform/persuade customers, raise awareness, boost sales, and build brand loyalty.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because break-even calculation is an operations/finance tool.","C":"Incorrect because moving materials is logistics and supply chain management.","D":"Incorrect because recruiting and training staff is the role of human resource management."}}},{"id":"P1_U3_MCQ_590","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_590","question":"How does 'informative advertising' differ from 'persuasive advertising'?","options":{"A":"Informative advertising is free of charge, whereas persuasive advertising is paid for.","B":"Informative advertising provides factual details about features, price, and uses, whereas persuasive advertising focuses on creating a desirable image to convince consumers to buy.","C":"Informative advertising is used only in the decline stage, whereas persuasive advertising is used only before a product is invented.","D":"Informative advertising uses only social media, whereas persuasive advertising uses only roadside billboards."},"correctOption":"B","correctAnswer":"Informative advertising provides factual details about features, price, and uses, whereas persuasive advertising focuses on creating a desirable image to convince consumers to buy.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because informative advertising gives consumers factual information (such as specifications, price, and benefits), while persuasive advertising appeals to emotions and lifestyle to create brand desirability.","distractor_reasons":{"A":"Incorrect because all advertising is paid-for communication.","B":"Correct selection.","C":"Incorrect because informative advertising is heavily used at the introduction stage when launching a new product.","D":"Incorrect because both informative and persuasive messages can be delivered across various media."}}},{"id":"P1_U3_MCQ_591","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_591","question":"What is meant by 'sales promotion'?","options":{"A":"Long-term television campaigns designed solely to build corporate public relations.","B":"Promoting an existing employee to a senior management position.","C":"Short-term incentives such as vouchers, reward schemes, competitions, or special offers aimed at boosting sales.","D":"Selecting the most efficient wholesaler to distribute perishable food products."},"correctOption":"C","correctAnswer":"Short-term incentives such as vouchers, reward schemes, competitions, or special offers aimed at boosting sales.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sales promotions are short-term incentives (like discounts, BOGOF offers, vouchers, competitions, and loyalty reward schemes) used to stimulate immediate purchases.","distractor_reasons":{"A":"Incorrect because long-term TV campaigns are advertising rather than short-term sales promotion.","B":"Incorrect because internal staff promotion is an HRM concept, not marketing sales promotion.","C":"Correct selection.","D":"Incorrect because selecting a wholesaler relates to 'place' (distribution)."}}},{"id":"P1_U3_MCQ_592","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_592","question":"How do 'reward schemes' (such as customer loyalty cards) benefit a business?","options":{"A":"They require zero IT systems or administrative costs to operate.","B":"They guarantee that customers will never shop at any competing store.","C":"They allow the business to avoid paying value-added tax on discounted goods.","D":"They encourage repeat purchases and provide valuable customer data for market research when shoppers register."},"correctOption":"D","correctAnswer":"They encourage repeat purchases and provide valuable customer data for market research when shoppers register.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because reward schemes incentivize customers to keep returning to collect points/rewards while capturing registration and purchasing data for market research.","distractor_reasons":{"A":"Incorrect because managing loyalty schemes requires costly IT databases and ongoing rewards.","B":"Incorrect because shoppers often hold loyalty cards for several competing supermarkets at once.","C":"Incorrect because loyalty cards do not exempt a business from taxes.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_593","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_593","question":"What is a potential disadvantage of using 'special offers' (such as price discounts or 'buy-one-get-one-free')?","options":{"A":"Profit margin per unit is reduced, and frequent discounts may damage an exclusive or luxury brand image.","B":"They are completely ineffective at clearing excess inventory nearing its sell-by date.","C":"Consumers are never motivated to try a new product by a temporary price discount.","D":"They permanently increase the cost of raw materials used in manufacturing."},"correctOption":"A","correctAnswer":"Profit margin per unit is reduced, and frequent discounts may damage an exclusive or luxury brand image.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because price reductions cut unit profit margins, may cause buyers to stockpile and buy less later at full price, and can cheapen a luxury brand's image.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because clearing seasonal or short-dated inventory is actually a common advantage of special offers.","C":"Incorrect because encouraging first-time trial is a primary purpose of special offers.","D":"Incorrect because promotional discounts affect selling revenue rather than supplier raw material costs."}}},{"id":"P1_U3_MCQ_594","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_594","question":"What is a key advantage of advertising on 'social media'?","options":{"A":"It guarantees that negative customer comments can never be posted publicly.","B":"It reaches a large, often younger audience, allows two-way communication, and adverts can be shared virally at low cost.","C":"It effectively reaches elderly consumers who do not own smartphones or computers.","D":"It requires zero staff time to monitor messages or update online content."},"correctOption":"B","correctAnswer":"It reaches a large, often younger audience, allows two-way communication, and adverts can be shared virally at low cost.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because social media advertising can target specific demographics cost-effectively, encourages two-way engagement, drives website traffic, and can go viral.","distractor_reasons":{"A":"Incorrect because viral negative feedback is a major risk and disadvantage of social media marketing.","B":"Correct selection.","C":"Incorrect because consumers who do not use social media cannot be reached through this medium.","D":"Incorrect because managing social media accounts requires ongoing time and resources."}}},{"id":"P1_U3_MCQ_595","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_595","question":"What is a common disadvantage of using 'direct/targeted emails' for advertising?","options":{"A":"They incur high paper printing and postal stamp expenses for every message sent.","B":"They cannot be sent to customers who have previously subscribed to a mailing list.","C":"Recipients may view them as irritating spam, delete them unread, or unsubscribe from the mailing list.","D":"They cause severe environmental damage due to large amounts of discarded paper waste."},"correctOption":"C","correctAnswer":"Recipients may view them as irritating spam, delete them unread, or unsubscribe from the mailing list.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because commercial emails are often filtered into spam/junk folders or deleted unread by irritated consumers, requiring continuous database maintenance.","distractor_reasons":{"A":"Incorrect because zero printing or postage cost is an advantage of email over physical mail.","B":"Incorrect because targeted emails are specifically sent to existing subscribers and past customers.","C":"Correct selection.","D":"Incorrect because low environmental impact compared to printed leaflets is an advantage of email."}}},{"id":"P1_U3_MCQ_596","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_596","question":"What is a disadvantage of using 'billboards' as an advertising medium?","options":{"A":"They can only be displayed for a maximum of twenty-four hours.","B":"They cannot display large, colourful visual images.","C":"They are always more expensive than a nationwide prime-time television campaign.","D":"Detailed product information cannot be included because passers-by and drivers only see them briefly."},"correctOption":"D","correctAnswer":"Detailed product information cannot be included because passers-by and drivers only see them briefly.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because billboards are passed quickly by pedestrians and motorists, meaning adverts must rely on brief slogans and visuals rather than detailed technical text.","distractor_reasons":{"A":"Incorrect because billboards remain displayed for long periods, which is an advantage.","B":"Incorrect because large, eye-catching visuals are a core strength of billboards.","C":"Incorrect because billboards are relatively low cost compared to national TV advertising.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_597","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_597","question":"What is an advantage of using 'leaflets' for local advertising?","options":{"A":"They are a low-cost printed method that can be handed out locally and kept by consumers for future reference.","B":"Every recipient is guaranteed to read the leaflet carefully and make a purchase.","C":"They are widely praised by environmental groups for eliminating paper waste.","D":"They allow live two-way video interaction between the business and the customer."},"correctOption":"A","correctAnswer":"They are a low-cost printed method that can be handed out locally and kept by consumers for future reference.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leaflets are inexpensive to print, can be distributed door-to-door or in busy streets, may include money-off vouchers, and can be kept by consumers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because many leaflets are thrown away unread as 'junk mail'.","C":"Incorrect because discarded paper leaflets are often criticised for creating litter and environmental waste.","D":"Incorrect because two-way digital interaction is a feature of social media, not printed leaflets."}}},{"id":"P1_U3_MCQ_598","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_598","question":"What is the primary role of 'Public Relations (PR)' in promotion?","options":{"A":"Paying for short-term price discounts on supermarket shelves.","B":"Maintaining a positive public image for the business through unpaid media coverage, press releases, and sponsorships.","C":"Calculating the percentage mark-up on manufactured goods.","D":"Distributing bulk shipments from factories to regional wholesalers."},"correctOption":"B","correctAnswer":"Maintaining a positive public image for the business through unpaid media coverage, press releases, and sponsorships.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because public relations aims to create and maintain a favourable public image and goodwill for the business using press releases, charity events, and media coverage.","distractor_reasons":{"A":"Incorrect because short-term price discounts are a method of sales promotion.","B":"Correct selection.","C":"Incorrect because calculating mark-up relates to cost-plus pricing.","D":"Incorrect because bulk shipment relates to distribution ('place')."}}},{"id":"P1_U3_MCQ_599","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_599","question":"When is 'personal selling' (using sales representatives to meet buyers face-to-face) most appropriate?","options":{"A":"When selling low-priced everyday items like loaves of bread to millions of shoppers.","B":"When a business has almost no promotion budget and sells to a mass market.","C":"When selling expensive, complex, or technical producer goods that require detailed demonstration and explanation.","D":"When the product is sold exclusively through automated self-service vending machines."},"correctOption":"C","correctAnswer":"When selling expensive, complex, or technical producer goods that require detailed demonstration and explanation.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because personal selling is costly per contact and is best suited to high-value, complex, or technical products (such as industrial machinery) where tailored advice is needed.","distractor_reasons":{"A":"Incorrect because mass-market convenience goods rely on mass advertising and retail display rather than individual sales reps.","B":"Incorrect because employing trained sales representatives is expensive per customer reached.","C":"Correct selection.","D":"Incorrect because vending machines involve automated self-service with zero human sales interaction."}}},{"id":"P1_U3_MCQ_600","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_600","question":"Which factor is most important when deciding which method of promotion to use?","options":{"A":"The number of shareholders who attend the company's Annual General Meeting.","B":"The span of control of supervisors on the factory assembly line.","C":"The depreciation method used for non-current factory machinery.","D":"The size of the promotion budget, the stage of the product life cycle, the nature of the product, and the target market."},"correctOption":"D","correctAnswer":"The size of the promotion budget, the stage of the product life cycle, the nature of the product, and the target market.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because marketing managers select promotional methods based on available budget, expected revenue gain, product life cycle stage, product type (consumer vs producer), target audience, and brand image.","distractor_reasons":{"A":"Incorrect because AGM attendance relates to corporate governance rather than promotional media choice.","B":"Incorrect because factory supervision structure does not determine how products are advertised.","C":"Incorrect because accounting depreciation methods do not guide promotional strategy.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_601","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_601","question":"What is meant by a 'marketing strategy'?","options":{"A":"A plan to combine the right combination of the four elements of the marketing mix for a product or service to achieve a particular marketing objective.","B":"A financial statement showing a business's assets, liabilities, and capital at a specific date.","C":"A legal contract between an employer and an employee outlining working hours and pay.","D":"A government policy restricting the quantity of foreign goods imported into a country."},"correctOption":"A","correctAnswer":"A plan to combine the right combination of the four elements of the marketing mix for a product or service to achieve a particular marketing objective.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a marketing strategy sets out a clear marketing objective and details the integrated marketing mix (product, price, place, promotion) designed to achieve that goal.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a record of assets and liabilities is a statement of financial position.","C":"Incorrect because an employer-employee agreement is a contract of employment.","D":"Incorrect because a restriction on import quantities is an import quota."}}},{"id":"P1_U3_MCQ_602","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_602","question":"Why is consistency between all four elements of the marketing mix essential for a successful marketing strategy?","options":{"A":"Because the law requires all businesses to spend the exact same amount on each of the four Ps.","B":"Because if one element clashes with the others (such as a luxury product sold in a cheap discount store), consumers receive mixed messages and the strategy will fail.","C":"Because a business is legally forbidden from ever changing its marketing mix once launched.","D":"Because consistency eliminates the need to identify a target market segment."},"correctOption":"B","correctAnswer":"Because if one element clashes with the others (such as a luxury product sold in a cheap discount store), consumers receive mixed messages and the strategy will fail.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because all four Ps must reinforce the same brand image and target market positioning; any inconsistency undermines consumer trust and causes the strategy to fail.","distractor_reasons":{"A":"Incorrect because there is no legal requirement to spend equal budgets across product, price, place, and promotion.","B":"Correct selection.","C":"Incorrect because businesses must regularly adapt their marketing mix across the product life cycle and as market conditions change.","D":"Incorrect because a consistent marketing mix is built specifically around the needs of a clearly defined target market."}}},{"id":"P1_U3_MCQ_603","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_603","question":"Which of the following is an example of a clear 'marketing objective'?","options":{"A":"Reducing factory absenteeism by introducing flexitime for assembly workers.","B":"Increasing the span of control of warehouse supervisors from four to eight subordinates.","C":"Increasing market share of an existing product or achieving a target sales level in a new market.","D":"Issuing new shares on a stock exchange to repay long-term bank loans."},"correctOption":"C","correctAnswer":"Increasing market share of an existing product or achieving a target sales level in a new market.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because marketing objectives focus on market performance targets such as increasing sales, gaining market share, entering new markets, or improving customer loyalty.","distractor_reasons":{"A":"Incorrect because reducing worker absenteeism is a human resource management objective.","B":"Incorrect because changing spans of control is an organizational structure decision.","C":"Correct selection.","D":"Incorrect because issuing shares to repay debt is a corporate finance decision."}}},{"id":"P1_U3_MCQ_604","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_604","question":"Which four factors must a Marketing Manager consider when developing or adapting a marketing mix?","options":{"A":"Land, labour, capital, and enterprise.","B":"Cash inflows, cash outflows, opening balance, and closing balance.","C":"Job description, person specification, shortlist, and induction.","D":"Marketing objective, finance available, target market, and level of competition."},"correctOption":"D","correctAnswer":"Marketing objective, finance available, target market, and level of competition.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the choice of product, price, place, and promotion depends on the marketing objective, the available marketing budget, the target market's characteristics, and competitors' actions.","distractor_reasons":{"A":"Incorrect because these are the four factors of production.","B":"Incorrect because these are the components of a cash flow forecast.","C":"Incorrect because these are stages in employee recruitment and selection.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_605","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_605","question":"Why must a business adapt its marketing strategy over time?","options":{"A":"Because consumer tastes change, new competitors enter, and the product moves through different stages of its life cycle.","B":"Because consumer protection laws expire every twelve months.","C":"Because products can never remain in the maturity stage for more than one month.","D":"Because market research becomes illegal after a product's initial launch."},"correctOption":"A","correctAnswer":"Because consumer tastes change, new competitors enter, and the product moves through different stages of its life cycle.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because market conditions are dynamic—consumer preferences evolve, competitors launch new rivals, and a product requires different pricing and promotion as it moves from introduction to maturity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because consumer protection laws remain permanently in force unless amended by parliament.","C":"Incorrect because well-managed brands can remain in the maturity stage for many years.","D":"Incorrect because ongoing market research is essential throughout a product's entire life."}}},{"id":"P1_U3_MCQ_606","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_606","question":"What is a major advantage to a business of entering new markets in other countries?","options":{"A":"The business can use the exact same language and packaging in every country without any changes.","B":"It increases total potential sales and spreads business risk across different economies.","C":"There are never any import tariffs, transport costs, or legal controls in foreign markets.","D":"Consumers in all countries have identical incomes, religions, and cultural tastes."},"correctOption":"B","correctAnswer":"It increases total potential sales and spreads business risk across different economies.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because expanding into foreign markets enlarges the customer base to boost sales and spreads risk so a downturn in the home economy can be offset by growth abroad.","distractor_reasons":{"A":"Incorrect because language and legal labelling requirements frequently require packaging adaptations.","B":"Correct selection.","C":"Incorrect because foreign markets often impose tariffs, transport expenses, and different legal rules.","D":"Incorrect because differences in income, religion, and culture are major challenges in international marketing."}}},{"id":"P1_U3_MCQ_607","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_607","question":"How does entering foreign markets help a business 'spread risk'?","options":{"A":"It guarantees that exchange rates will never fluctuate.","B":"It eliminates all fixed costs of operating factories in the home country.","C":"If demand falls due to a recession or new rival in the home country, strong sales in booming foreign markets can offset the loss.","D":"It prevents foreign governments from passing any consumer protection laws."},"correctOption":"C","correctAnswer":"If demand falls due to a recession or new rival in the home country, strong sales in booming foreign markets can offset the loss.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because operating across multiple national markets reduces reliance on a single domestic economy; weak demand at home can be balanced by growth elsewhere.","distractor_reasons":{"A":"Incorrect because international trade exposes businesses to exchange rate fluctuations.","B":"Incorrect because domestic factory fixed costs remain until assets are sold or closed.","C":"Correct selection.","D":"Incorrect because businesses must comply with the laws of every country in which they sell."}}},{"id":"P1_U3_MCQ_608","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_608","question":"Which of the following are three key barriers or disadvantages of entering new markets in other countries?","options":{"A":"Lower total sales potential, complete absence of competitors, and lower consumer choice.","B":"Automatic economies of scale, zero marketing costs, and guaranteed brand loyalty.","C":"Short chains of command, wide spans of control, and democratic leadership.","D":"Cultural differences, lack of local market knowledge, and different legal requirements."},"correctOption":"D","correctAnswer":"Cultural differences, lack of local market knowledge, and different legal requirements.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because businesses entering foreign markets often face cultural/religious differences, lack of knowledge about local tastes and competitors, and unfamiliar legal regulations.","distractor_reasons":{"A":"Incorrect because entering foreign markets increases total sales potential rather than reducing it.","B":"Incorrect because entering new countries increases marketing and research costs and does not guarantee loyalty.","C":"Incorrect because these are internal organizational management concepts.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_609","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_609","question":"How might 'cultural differences' affect a business's marketing mix when entering a foreign market?","options":{"A":"Product ingredients, recipes, and advertising images may have to be adapted to respect local religious beliefs and social norms.","B":"The business must always charge a higher price than in its home market regardless of local incomes.","C":"The business is forbidden from using local agents or wholesalers to distribute its goods.","D":"Consumers in foreign countries ignore product quality and buy purely based on packaging size."},"correctOption":"A","correctAnswer":"Product ingredients, recipes, and advertising images may have to be adapted to respect local religious beliefs and social norms.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cultural and religious norms (such as dietary restrictions or social customs) require adapting products and promotional imagery so they are acceptable and appealing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because prices must be adjusted to match local income levels and competition, which may be lower.","C":"Incorrect because employing local agents is a common, effective way to overcome cultural barriers.","D":"Incorrect because consumers worldwide value product quality and suitability."}}},{"id":"P1_U3_MCQ_610","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_610","question":"Why is 'lack of knowledge' a serious disadvantage when entering a new market in another country?","options":{"A":"It prevents the business from calculating its own domestic factory costs.","B":"Without understanding local consumer incomes, age structures, and competitors, the business may choose an unsuitable marketing mix and make a loss.","C":"It forces the business to sell its products below cost in its home market.","D":"It makes it illegal to conduct primary or secondary market research abroad."},"correctOption":"B","correctAnswer":"Without understanding local consumer incomes, age structures, and competitors, the business may choose an unsuitable marketing mix and make a loss.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unfamiliarity with foreign consumer incomes, demographics, and rival pricing can lead to costly marketing errors, though conducting research or hiring local agents adds expense.","distractor_reasons":{"A":"Incorrect because a firm knows its own internal production costs from its accounting records.","B":"Correct selection.","C":"Incorrect because lack of foreign market knowledge does not force domestic below-cost pricing.","D":"Incorrect because conducting market research in foreign markets is legal and strongly recommended."}}},{"id":"P1_U3_MCQ_611","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_611","question":"What is meant by 'legal controls on marketing'?","options":{"A":"Internal company rules setting annual sales targets for the marketing department.","B":"Agreements between competing businesses to fix prices at a high level.","C":"Laws passed by government to protect consumers from faulty goods, unsafe goods, and misleading promotion.","D":"Voluntary ethical guidelines written by advertising agencies."},"correctOption":"C","correctAnswer":"Laws passed by government to protect consumers from faulty goods, unsafe goods, and misleading promotion.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because legal controls on marketing are government laws designed to protect consumers against unfair practices such as faulty products, unsafe goods, and false promotional claims.","distractor_reasons":{"A":"Incorrect because internal sales targets are management objectives, not legal controls.","B":"Incorrect because price-fixing agreements between rivals are illegal anti-competitive cartels.","C":"Correct selection.","D":"Incorrect because legal controls are mandatory laws enforced by government, not voluntary guidelines."}}},{"id":"P1_U3_MCQ_612","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_612","question":"Why do governments introduce legal controls to protect consumers?","options":{"A":"To ensure that all private sector businesses earn the exact same annual profit.","B":"To prevent consumers from buying imported goods from foreign businesses.","C":"To eliminate competition between businesses in mass markets.","D":"Because modern products are complex and persuasive promotions could otherwise mislead consumers into buying unsafe, faulty, or unsuitable goods."},"correctOption":"D","correctAnswer":"Because modern products are complex and persuasive promotions could otherwise mislead consumers into buying unsafe, faulty, or unsuitable goods.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because technical product complexity and sophisticated marketing make it difficult for consumers to judge product quality beforehand, requiring legal protection against exploitation.","distractor_reasons":{"A":"Incorrect because profits in a market economy vary based on business efficiency and demand.","B":"Incorrect because consumer protection laws apply equally to domestic and imported goods.","C":"Incorrect because governments aim to encourage fair competition rather than eliminate it.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_613","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_613","question":"What do consumer protection laws regarding 'misleading promotion' prohibit?","options":{"A":"Making false or deliberately misleading claims about a product's materials, performance, or price reductions in advertisements.","B":"Using social media or billboards to inform consumers about a newly launched product.","C":"Offering genuine temporary price discounts during a seasonal clearance sale.","D":"Stating the true country of origin and ingredients on food packaging."},"correctOption":"A","correctAnswer":"Making false or deliberately misleading claims about a product's materials, performance, or price reductions in advertisements.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because laws against misleading promotion require advertisements and price-reduction claims to be truthful and accurate (e.g., not claiming cotton is wool, or advertising fake 'discounts').","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because truthful advertising on social media or billboards is completely legal.","C":"Incorrect because genuine price reductions are legal; only false claims of a discount are prohibited.","D":"Incorrect because displaying accurate ingredients and origin is a legal requirement, not a violation."}}},{"id":"P1_U3_MCQ_614","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_614","question":"Which requirement is covered by legal controls over 'product quality and faulty goods'?","options":{"A":"Goods must always be sold at the lowest price in the industry.","B":"Goods must be of satisfactory quality, fit for their intended purpose, and perform as described.","C":"Goods must be packaged in single-use plastic containers.","D":"Goods must be sold exclusively through wholesalers rather than online."},"correctOption":"B","correctAnswer":"Goods must be of satisfactory quality, fit for their intended purpose, and perform as described.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consumer protection laws make it illegal to sell goods that are faulty/unsatisfactory in quality, unfit for the purpose requested by the buyer, or fail to match their description.","distractor_reasons":{"A":"Incorrect because businesses are free to set high prices for high-quality goods.","B":"Correct selection.","C":"Incorrect because many governments actually ban or restrict single-use plastics to protect the environment.","D":"Incorrect because businesses may choose any legal distribution channel."}}},{"id":"P1_U3_MCQ_615","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_615","question":"What is the purpose of 'Weights and Measures' legal controls?","options":{"A":"To limit the maximum physical size of retail supermarkets.","B":"To control the number of employees a factory can hire.","C":"To prevent businesses from selling underweight goods or using inaccurate weighing equipment.","D":"To ensure that all competitors charge identical prices per kilogram."},"correctOption":"C","correctAnswer":"To prevent businesses from selling underweight goods or using inaccurate weighing equipment.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Weights and Measures legislation protects consumers by ensuring goods contain the stated weight or volume and that scales/measuring equipment are accurate.","distractor_reasons":{"A":"Incorrect because retail store size is governed by local planning laws, not Weights and Measures.","B":"Incorrect because workforce size is not regulated by Weights and Measures laws.","C":"Correct selection.","D":"Incorrect because businesses set their own prices per unit weight."}}},{"id":"P1_U3_MCQ_616","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_616","question":"What makes a 'misleading price reduction' claim illegal under consumer protection laws?","options":{"A":"Reducing a product's price by 20% after it has been sold at the higher price for several months.","B":"Charging a higher price in an airport shop than in a suburban supermarket.","C":"Offering a 'buy-one-get-one-free' promotion on perishable groceries.","D":"Advertising a 'special discount' (such as '$40 off') when the product was actually sold at the exact same price previously."},"correctOption":"D","correctAnswer":"Advertising a 'special discount' (such as '$40 off') when the product was actually sold at the exact same price previously.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because claiming a fake price reduction when the item was never genuinely sold at the higher 'original' price deceives consumers about the value of the offer.","distractor_reasons":{"A":"Incorrect because discounting a genuine previous selling price is a legal sales promotion.","B":"Incorrect because charging different prices in different locations is legal.","C":"Incorrect because genuine BOGOF offers are legal sales promotions.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_617","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_617","question":"What is a positive effect on a business of complying with consumer protection laws?","options":{"A":"It builds consumer confidence and a strong reputation for safe, reliable products, leading to repeat sales and avoiding fines.","B":"It reduces product design, quality testing, and manufacturing costs to zero.","C":"It allows the business to ignore customer complaints about faulty products.","D":"It exempts the business from having to advertise its products."},"correctOption":"A","correctAnswer":"It builds consumer confidence and a strong reputation for safe, reliable products, leading to repeat sales and avoiding fines.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because observing legal controls enhances brand reputation, increases buyer confidence, encourages repeat purchases, and protects the firm from legal fines and bad publicity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because meeting strict safety and quality standards increases design and testing costs.","C":"Incorrect because legal controls require businesses to refund, replace, or compensate consumers for faulty goods.","D":"Incorrect because legal compliance does not replace the need for promotion."}}},{"id":"P1_U3_MCQ_618","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_618","question":"What is a negative effect on a business of strict legal controls protecting consumers?","options":{"A":"Consumers lose trust in the safety of products sold in shops.","B":"Costs increase due to safer product designs, improved quality control, and potential compensation claims, which may force higher prices.","C":"Businesses are legally prevented from exporting products to other countries.","D":"Brand loyalty decreases because products last longer and work properly."},"correctOption":"B","correctAnswer":"Costs increase due to safer product designs, improved quality control, and potential compensation claims, which may force higher prices.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because complying with safety regulations, accurate labelling, and quality standards raises production and compliance costs, which may reduce profit margins or require higher selling prices.","distractor_reasons":{"A":"Incorrect because legal controls actually increase consumer trust in product safety.","B":"Correct selection.","C":"Incorrect because meeting high domestic quality standards often makes it easier to meet export standards.","D":"Incorrect because reliable, durable products strengthen rather than weaken brand loyalty."}}},{"id":"P1_U3_MCQ_619","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_619","question":"What happens if a business is found guilty of selling unsafe goods that injure a consumer?","options":{"A":"The business receives a government grant to expand its factory.","B":"The consumer is fined for failing to inspect the product before purchase.","C":"The business is legally liable to pay compensation to the injured consumer and suffers severe reputational damage.","D":"The business is allowed to continue selling the unsafe item if it lowers the price."},"correctOption":"C","correctAnswer":"The business is legally liable to pay compensation to the injured consumer and suffers severe reputational damage.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because manufacturers and retailers are legally liable to compensate consumers injured by unsafe or defective goods, alongside facing fines and damaging publicity.","distractor_reasons":{"A":"Incorrect because law-breaking businesses face penalties rather than government grants.","B":"Incorrect because consumer protection laws place legal responsibility on the seller/manufacturer, not the consumer.","C":"Correct selection.","D":"Incorrect because unsafe products must be recalled and withdrawn from sale regardless of price."}}},{"id":"P1_U3_MCQ_620","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_620","question":"Why might a law-abiding business suffer unfair competition when consumer protection laws are poorly enforced?","options":{"A":"Because law-abiding businesses are forbidden from lowering their prices.","B":"Because consumers always prefer buying dangerous, faulty goods.","C":"Because government inspectors close down law-abiding businesses first.","D":"Because unscrupulous traders can ignore safety and quality laws to sell cheap, substandard goods and undercut compliant firms."},"correctOption":"D","correctAnswer":"Because unscrupulous traders can ignore safety and quality laws to sell cheap, substandard goods and undercut compliant firms.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because if authorities fail to stop rogue traders who ignore safety and quality rules, those traders save compliance costs and undercut responsible businesses on price.","distractor_reasons":{"A":"Incorrect because compliant businesses can reduce prices if they lower costs efficiently, though compliance costs are higher.","B":"Incorrect because consumers want safe products, but may be misled by cheap prices from dishonest sellers.","C":"Incorrect because enforcement targets businesses that breach regulations.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_621","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_621","question":"How do legal controls over marketing affect a business's promotional activities?","options":{"A":"All advertisements and packaging labels must be truthful, accurate, and avoid exaggerated or false claims.","B":"Businesses are banned from using persuasive advertising on television or social media.","C":"Businesses are prohibited from offering loyalty cards or competitions.","D":"All promotional campaigns must be approved by competitors before launch."},"correctOption":"A","correctAnswer":"All advertisements and packaging labels must be truthful, accurate, and avoid exaggerated or false claims.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because marketing laws require all promotional claims, descriptions, and price comparisons to be honest and verifiable so consumers are not deceived.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because persuasive advertising is legal as long as it does not make false or misleading factual claims.","C":"Incorrect because loyalty schemes and competitions are legal sales promotions when run fairly.","D":"Incorrect because competitors have no authority to approve a rival's advertising."}}},{"id":"P1_U3_MCQ_622","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_622","question":"When planning to enter a foreign market, why must managers research the target country's 'legal requirements'?","options":{"A":"Because every country in the world uses the exact same product safety and advertising laws.","B":"Because certain products, ingredients, advertising images, or pricing practices legal at home may be restricted or illegal abroad.","C":"Because foreign governments require all importers to operate as sole traders.","D":"Because legal requirements determine how many levels of hierarchy a company must have."},"correctOption":"B","correctAnswer":"Because certain products, ingredients, advertising images, or pricing practices legal at home may be restricted or illegal abroad.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because safety standards, banned ingredients, advertising censorship rules, and price controls vary widely between countries, requiring compliance to avoid fines or product bans.","distractor_reasons":{"A":"Incorrect because national laws differ significantly from country to country.","B":"Correct selection.","C":"Incorrect because foreign entrants typically operate as limited companies, joint ventures, or via local agents.","D":"Incorrect because internal management hierarchy is not dictated by foreign marketing laws."}}},{"id":"P1_U3_MCQ_623","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_623","question":"Which element of the marketing mix is directly affected when a business must change a product's electrical plug or safety features to meet foreign legal standards?","options":{"A":"Place (channel of distribution).","B":"Promotion (sales promotion).","C":"Product (design and specification).","D":"People (employee recruitment)."},"correctOption":"C","correctAnswer":"Product (design and specification).","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because modifying physical design, technical specifications, or safety components to meet legal regulations directly alters the 'product' element of the marketing mix.","distractor_reasons":{"A":"Incorrect because 'place' concerns distribution channels and retail outlets rather than physical product design.","B":"Incorrect because 'promotion' concerns advertising and sales incentives.","C":"Correct selection.","D":"Incorrect because employee recruitment is an HRM function rather than one of the four Ps."}}},{"id":"P1_U3_MCQ_624","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_624","question":"How can a business overcome the barrier of 'lack of local knowledge' when entering a new market in another country?","options":{"A":"By ignoring local consumer preferences and selling only unsold domestic inventory.","B":"By refusing to conduct any primary or secondary market research.","C":"By eliminating all customer service and after-sales support.","D":"By conducting detailed market research, appointing a local agent, or forming a joint venture with a local business."},"correctOption":"D","correctAnswer":"By conducting detailed market research, appointing a local agent, or forming a joint venture with a local business.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because local market research, experienced local agents, or joint ventures with domestic partners provide crucial insight into local culture, tastes, laws, and distribution.","distractor_reasons":{"A":"Incorrect because ignoring local tastes typically results in rejected products and financial losses.","B":"Incorrect because market research is essential to understand a new foreign market.","C":"Incorrect because poor customer service alienates new international buyers.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_625","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_625","question":"What is the relationship between a 'marketing objective' and the 'marketing mix' within a marketing strategy?","options":{"A":"The marketing objective defines what the business wants to achieve, and the marketing mix provides the coordinated four Ps used to achieve it.","B":"The marketing mix is chosen first at random, and the marketing objective is invented afterward.","C":"The marketing objective applies only to finance, whereas the marketing mix applies only to production.","D":"They are unrelated concepts used by separate competing companies."},"correctOption":"A","correctAnswer":"The marketing objective defines what the business wants to achieve, and the marketing mix provides the coordinated four Ps used to achieve it.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a marketing strategy begins with a clear marketing objective (the target) and selects a consistent combination of product, price, place, and promotion (the tools) to achieve that target.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the objective must be set first so that the four Ps can be designed to achieve it.","C":"Incorrect because both the marketing objective and the four Ps belong to the marketing function.","D":"Incorrect because both are core components of a single business's marketing strategy."}}},{"id":"P1_U3_MCQ_626","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_626","question":"What is the primary role of marketing within a business?","options":{"A":"Identifying and satisfying customer needs and wants profitably.","B":"Maximising factory output regardless of current consumer demand.","C":"Setting the lowest possible price for every item produced.","D":"Managing internal employee recruitment and payroll administration."},"correctOption":"A","correctAnswer":"Identifying and satisfying customer needs and wants profitably.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because marketing is the management process responsible for identifying, anticipating, and satisfying customer requirements profitably.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because maximising output without checking demand describes a product-oriented approach rather than marketing.","C":"Incorrect because pricing depends on the marketing mix and brand positioning, not always charging the lowest price.","D":"Incorrect because recruitment and payroll are functions of the Human Resource Management department."}}},{"id":"P1_U3_MCQ_627","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_627","question":"Why is anticipating changes in customer needs an important role of marketing?","options":{"A":"It eliminates the need to conduct any future market research.","B":"It enables a business to adapt products early before sales decline.","C":"It guarantees that competitors cannot enter the same industry.","D":"It ensures fixed production costs remain unchanged over time."},"correctOption":"B","correctAnswer":"It enables a business to adapt products early before sales decline.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because predicting shifts in consumer tastes allows a business to innovate and update its offerings ahead of falling demand.","distractor_reasons":{"A":"Incorrect because ongoing market research is still essential to track changing consumer trends.","B":"Correct selection.","C":"Incorrect because anticipating customer needs helps a business compete, but does not legally block new rivals from entering.","D":"Incorrect because fixed costs are determined by scale and overheads, not by anticipating demand."}}},{"id":"P1_U3_MCQ_628","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_628","question":"What is meant by maintaining customer loyalty as an objective of marketing?","options":{"A":"Forcing customers to sign long-term contracts before purchasing.","B":"Selling products exclusively through wholesale intermediaries.","C":"Encouraging existing customers to make repeat purchases from the business.","D":"Preventing customers from comparing prices on the internet."},"correctOption":"C","correctAnswer":"Encouraging existing customers to make repeat purchases from the business.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because customer loyalty means building strong relationships so customers repeatedly choose the business's brand over competitors.","distractor_reasons":{"A":"Incorrect because loyalty relies on customer satisfaction and relationship building rather than legal compulsion.","B":"Incorrect because distribution choices relate to Place, not customer loyalty.","C":"Correct selection.","D":"Incorrect because businesses cannot stop consumers from comparing prices online."}}},{"id":"P1_U3_MCQ_629","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_629","question":"What is meant by the term 'market share'?","options":{"A":"The total value of all goods and services sold across an entire economy.","B":"The proportion of a company's shares owned by institutional investors.","C":"The difference between a product's selling price and its variable cost.","D":"The percentage of total market sales held by one brand or business."},"correctOption":"D","correctAnswer":"The percentage of total market sales held by one brand or business.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because market share measures a single business's or brand's sales revenue as a percentage of total sales revenue in that market.","distractor_reasons":{"A":"Incorrect because total economic output refers to Gross Domestic Product, not market share.","B":"Incorrect because this confuses market share with share capital ownership in a limited company.","C":"Incorrect because selling price minus variable cost is unit contribution.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_630","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_630","question":"Which of the following is a direct benefit to a business of gaining a high market share?","options":{"A":"Greater influence over suppliers and retailers due to high order volumes.","B":"Complete exemption from government consumer protection regulations.","C":"Zero need to spend money on product quality control or promotion.","D":"Automatic elimination of all variable production costs."},"correctOption":"A","correctAnswer":"Greater influence over suppliers and retailers due to high order volumes.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because market leaders buy in large quantities and attract strong customer demand, giving them bargaining power over suppliers and distributors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because all businesses must obey consumer protection laws regardless of size.","C":"Incorrect because market leaders must still maintain quality and promote products to defend their position.","D":"Incorrect because variable costs still rise with output."}}},{"id":"P1_U3_MCQ_631","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_631","question":"How do changes in consumer tastes and fashions affect markets?","options":{"A":"They keep demand for traditional products permanently constant.","B":"They cause spending patterns to shift rapidly toward newer trends.","C":"They eliminate the need for businesses to update product designs.","D":"They reduce competition in clothing and technology industries."},"correctOption":"B","correctAnswer":"They cause spending patterns to shift rapidly toward newer trends.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because evolving tastes and fashions lead consumers to abandon outdated styles and spend more on trending products.","distractor_reasons":{"A":"Incorrect because changing tastes cause demand for older products to fall rather than stay constant.","B":"Correct selection.","C":"Incorrect because shifting fashions force businesses to regularly update designs.","D":"Incorrect because fast-changing trends typically intensify competition among rivals."}}},{"id":"P1_U3_MCQ_632","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_632","question":"Why do changes in technology frequently alter consumer spending patterns?","options":{"A":"Technological progress forces governments to ban all imported goods.","B":"New technology always increases the average cost of manufacturing.","C":"Innovative products make older versions obsolete and shift consumer demand.","D":"Consumers prefer buying products that lack modern digital features."},"correctOption":"C","correctAnswer":"Innovative products make older versions obsolete and shift consumer demand.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because technological advancements introduce improved features and new products, causing demand for outdated alternatives to fall.","distractor_reasons":{"A":"Incorrect because technological change encourages international trade rather than import bans.","B":"Incorrect because new technology usually lowers average production costs through efficiency.","C":"Correct selection.","D":"Incorrect because most consumers shift spending toward newer, more capable technologies."}}},{"id":"P1_U3_MCQ_633","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_633","question":"How does a rise in average household income typically change consumer spending patterns?","options":{"A":"Consumers spend all of their extra income solely on basic necessities.","B":"Demand for luxury and non-essential goods and services tends to fall.","C":"Businesses are forced to switch from mass markets to niche markets.","D":"Consumers spend a higher proportion of income on luxury and leisure items."},"correctOption":"D","correctAnswer":"Consumers spend a higher proportion of income on luxury and leisure items.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because higher disposable incomes enable consumers to buy more luxury goods, holidays, and branded products after covering basic needs.","distractor_reasons":{"A":"Incorrect because spending on basic necessities rises very little once essential needs are met.","B":"Incorrect because rising incomes increase, rather than decrease, demand for luxury items.","C":"Incorrect because higher incomes expand overall demand in both mass and niche markets.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_634","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_634","question":"How does an ageing population affect consumer spending patterns in a country?","options":{"A":"Demand increases for healthcare, retirement services, and leisure travel.","B":"Demand rises sharply for primary school equipment and baby products.","C":"Total spending on medical care and pharmaceuticals steadily declines.","D":"Businesses stop segmenting markets by consumer age."},"correctOption":"A","correctAnswer":"Demand increases for healthcare, retirement services, and leisure travel.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a larger proportion of older consumers shifts market demand toward healthcare, mobility aids, and leisure services.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because an ageing population has a smaller proportion of young children.","C":"Incorrect because older populations require more medical care, not less.","D":"Incorrect because demographic shifts make age segmentation even more important."}}},{"id":"P1_U3_MCQ_635","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_635","question":"Which development has made many national markets significantly more competitive in recent decades?","options":{"A":"Higher transport costs that prevent goods from crossing national borders.","B":"Globalisation and the expansion of multinational companies into domestic markets.","C":"Government laws prohibiting businesses from advertising on social media.","D":"A worldwide decline in consumer access to smartphones and the internet."},"correctOption":"B","correctAnswer":"Globalisation and the expansion of multinational companies into domestic markets.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because globalisation and multinational companies expose domestic firms to rivalry from large foreign producers.","distractor_reasons":{"A":"Incorrect because transport costs have generally fallen, increasing international competition.","B":"Correct selection.","C":"Incorrect because social media advertising is widely permitted and used globally.","D":"Incorrect because smartphone and internet usage has expanded rapidly worldwide."}}},{"id":"P1_U3_MCQ_636","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_636","question":"How has the growth of e-commerce increased competition in retail markets?","options":{"A":"It restricts consumers to buying only from shops within walking distance.","B":"It prevents small businesses from selling goods outside their home town.","C":"It allows consumers to easily compare prices and buy from sellers worldwide.","D":"It forces all online sellers to charge identical prices for products."},"correctOption":"C","correctAnswer":"It allows consumers to easily compare prices and buy from sellers worldwide.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because online shopping enables consumers to compare prices instantly and order from domestic or overseas competitors.","distractor_reasons":{"A":"Incorrect because e-commerce removes geographic distance barriers for shoppers.","B":"Incorrect because websites allow even small firms to reach national and global buyers.","C":"Correct selection.","D":"Incorrect because online businesses set their own competitive prices."}}},{"id":"P1_U3_MCQ_637","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_637","question":"Which of the following is an effective way for a business to respond to increased market competition?","options":{"A":"Reducing product quality while raising selling prices.","B":"Stopping all communication with existing customers.","C":"Ignoring changes in competitor pricing and product features.","D":"Maintaining strong customer relationships and improving product quality."},"correctOption":"D","correctAnswer":"Maintaining strong customer relationships and improving product quality.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because superior quality and strong customer relationships build loyalty and differentiate the business from rivals.","distractor_reasons":{"A":"Incorrect because lowering quality while raising prices drives customers to competitors.","B":"Incorrect because weak communication alienates customers in a competitive market.","C":"Incorrect because ignoring rivals causes a business to lose market share.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_638","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_638","question":"How can a business respond effectively when consumer spending patterns shift away from its existing products?","options":{"A":"Develop new products that match current customer needs and keep costs low.","B":"Continue producing the exact same range without conducting research.","C":"Increase fixed overhead costs to raise the break-even output level.","D":"Eliminate all promotional activities to avoid informing consumers."},"correctOption":"A","correctAnswer":"Develop new products that match current customer needs and keep costs low.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because innovating new products aligned with changing demand and controlling costs keeps the business competitive and profitable.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because continuing to sell unwanted products leads to falling sales and failure.","C":"Incorrect because higher fixed costs raise break-even output and reduce profitability.","D":"Incorrect because promotion is necessary to make buyers aware of updated products."}}},{"id":"P1_U3_MCQ_639","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_639","question":"What is meant by a 'mass market'?","options":{"A":"A small, specialised market segment with unique consumer requirements.","B":"A very large market in which standardised products are sold to many consumers.","C":"A market where only one monopoly supplier is legally permitted to trade.","D":"A local market restricted solely to business-to-business transactions."},"correctOption":"B","correctAnswer":"A very large market in which standardised products are sold to many consumers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a mass market consists of a huge number of consumers buying standardised products with broad appeal.","distractor_reasons":{"A":"Incorrect because a small, specialised segment defines a niche market.","B":"Correct selection.","C":"Incorrect because mass markets usually feature intense competition among multiple large firms.","D":"Incorrect because mass markets typically serve millions of individual consumers."}}},{"id":"P1_U3_MCQ_640","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_640","question":"What is a major advantage to a business of operating in a mass market?","options":{"A":"There are no rival businesses competing for the same customers.","B":"Products can be custom-made individually without using machinery.","C":"High sales volumes enable economies of scale and lower average costs.","D":"Customers are always willing to pay luxury prices for basic items."},"correctOption":"C","correctAnswer":"High sales volumes enable economies of scale and lower average costs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because large-scale production and sales in a mass market allow firms to benefit from purchasing, technical, and marketing economies of scale.","distractor_reasons":{"A":"Incorrect because mass markets attract intense competition from many rivals.","B":"Incorrect because mass markets rely on flow/mass production of standardised goods rather than one-off job production.","C":"Correct selection.","D":"Incorrect because standardised mass-market goods are usually sold at competitive, lower prices."}}},{"id":"P1_U3_MCQ_641","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_641","question":"Which of the following is a disadvantage of operating in a mass market?","options":{"A":"Total potential sales volume is strictly limited to a few buyers.","B":"Average production costs are higher than in bespoke job production.","C":"Businesses cannot use national television or social media advertising.","D":"High competition forces heavy spending on advertising and keeps prices low."},"correctOption":"D","correctAnswer":"High competition forces heavy spending on advertising and keeps prices low.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because fierce rivalry in mass markets drives down prices and requires large promotional budgets to stand out.","distractor_reasons":{"A":"Incorrect because limited sales volume is a disadvantage of a niche market, not a mass market.","B":"Incorrect because mass production achieves lower average unit costs than job production.","C":"Incorrect because mass-market firms frequently use national advertising media.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_642","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_642","question":"What is meant by a 'niche market'?","options":{"A":"A small, specialised segment of a much larger market.","B":"A market where identical goods are sold to the entire population.","C":"An online auction platform where consumers sell second-hand items.","D":"A government-controlled sector providing free public services."},"correctOption":"A","correctAnswer":"A small, specialised segment of a much larger market.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a niche market is a small, specialised sub-segment of a larger market with distinct customer needs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because selling identical goods to the whole population describes a mass market.","C":"Incorrect because an online auction site is a consumer-to-consumer e-commerce platform.","D":"Incorrect because government-provided services belong to the public sector."}}},{"id":"P1_U3_MCQ_643","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_643","question":"What is a key advantage to a small business of targeting a niche market?","options":{"A":"It guarantees millions of unit sales every year.","B":"It avoids direct competition from large mass-market businesses.","C":"It achieves maximum purchasing economies of scale.","D":"It eliminates the need to understand specific customer needs."},"correctOption":"B","correctAnswer":"It avoids direct competition from large mass-market businesses.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because large corporations often overlook small niche segments, allowing smaller firms to serve specialised needs with less rivalry and higher profit margins.","distractor_reasons":{"A":"Incorrect because niche markets have small total customer numbers.","B":"Correct selection.","C":"Incorrect because low output volumes prevent niche firms from gaining large bulk-buying discounts.","D":"Incorrect because serving a niche requires deep understanding of customers' specialised requirements."}}},{"id":"P1_U3_MCQ_644","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_644","question":"Which of the following is a major disadvantage of operating in a niche market?","options":{"A":"Products cannot be tailored to specific customer preferences.","B":"Prices must always be set lower than mass-market alternatives.","C":"Limited market size restricts growth and leaves the firm vulnerable if demand falls.","D":"Large multinational firms dominate every small niche segment."},"correctOption":"C","correctAnswer":"Limited market size restricts growth and leaves the firm vulnerable if demand falls.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because niche markets have few customers, limiting economies of scale and creating high risk if consumer tastes change.","distractor_reasons":{"A":"Incorrect because tailoring products to specialised needs is a primary strength of niche marketing.","B":"Incorrect because niche products often command premium prices due to specialisation.","C":"Correct selection.","D":"Incorrect because large multinationals usually focus on high-volume mass markets."}}},{"id":"P1_U3_MCQ_645","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_645","question":"What is meant by 'market segmentation'?","options":{"A":"Merging two rival businesses in the same industry into one company.","B":"Selling the exact same product at the same price to every consumer.","C":"Dividing the production line into separate stages for flow manufacturing.","D":"Dividing a whole market into distinct sub-groups of consumers with similar needs."},"correctOption":"D","correctAnswer":"Dividing a whole market into distinct sub-groups of consumers with similar needs.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because market segmentation splits a broad market into identifiable consumer groups (segments) sharing similar characteristics or buying habits.","distractor_reasons":{"A":"Incorrect because combining two businesses at the same stage is horizontal integration.","B":"Incorrect because treating all buyers identically is undifferentiated mass marketing.","C":"Incorrect because organising factory stages relates to operations management, not market segmentation.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_646","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_646","question":"Which basis of market segmentation groups consumers into categories such as children, teenagers, adults, and senior citizens?","options":{"A":"Age segmentation.","B":"Location segmentation.","C":"Income segmentation.","D":"Lifestyle segmentation."},"correctOption":"A","correctAnswer":"Age segmentation.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because segmenting by age divides consumers according to their stage of life, as different age groups demand different products.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because location segmentation divides buyers by geographic region or climate.","C":"Incorrect because income segmentation groups buyers by earnings and spending power.","D":"Incorrect because lifestyle segmentation groups consumers by hobbies, interests, and attitudes."}}},{"id":"P1_U3_MCQ_647","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_647","question":"Why do businesses segment markets according to consumer income?","options":{"A":"Because all income groups buy identical luxury goods.","B":"Because consumers with different earnings can afford different price levels and quality.","C":"Because income segmentation eliminates the need for advertising.","D":"Because consumer income never changes during an economic cycle."},"correctOption":"B","correctAnswer":"Because consumers with different earnings can afford different price levels and quality.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because grouping buyers by income allows businesses to offer budget ranges to lower-income groups and premium goods to higher-income groups.","distractor_reasons":{"A":"Incorrect because lower-income consumers cannot afford luxury items.","B":"Correct selection.","C":"Incorrect because businesses must still promote products to each targeted income segment.","D":"Incorrect because incomes fluctuate with employment levels and economic growth."}}},{"id":"P1_U3_MCQ_648","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_648","question":"Which factor is being used when a business adapts its clothing range according to regional climate and urban versus rural areas?","options":{"A":"Gender segmentation.","B":"Age segmentation.","C":"Location segmentation.","D":"Income segmentation."},"correctOption":"C","correctAnswer":"Location segmentation.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because location segmentation divides consumers based on where they live, including climate, country, or urban/rural differences.","distractor_reasons":{"A":"Incorrect because gender segmentation divides markets between male and female consumers.","B":"Incorrect because age segmentation divides consumers by age brackets.","C":"Correct selection.","D":"Incorrect because income segmentation divides buyers by earnings."}}},{"id":"P1_U3_MCQ_649","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_649","question":"What does segmenting a market by 'lifestyle' involve?","options":{"A":"Grouping consumers strictly by their annual salary.","B":"Grouping consumers solely by the postal code of their home.","C":"Grouping consumers only by whether they are male or female.","D":"Grouping consumers according to their hobbies, interests, and attitudes."},"correctOption":"D","correctAnswer":"Grouping consumers according to their hobbies, interests, and attitudes.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lifestyle segmentation classifies consumers based on their activities, interests, values, and how they choose to live.","distractor_reasons":{"A":"Incorrect because annual salary is the basis of income segmentation.","B":"Incorrect because postal codes relate to location segmentation.","C":"Incorrect because male and female categories represent gender segmentation.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_650","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_650","question":"What is a major advantage to a business of using market segmentation?","options":{"A":"It enables the marketing mix to be tailored closely to specific customer needs, boosting sales.","B":"It lowers production costs by ensuring only one identical product is ever made.","C":"It completely removes the cost of conducting market research.","D":"It prevents competitors from targeting the same consumer groups."},"correctOption":"A","correctAnswer":"It enables the marketing mix to be tailored closely to specific customer needs, boosting sales.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because understanding each segment's exact needs allows a firm to design targeted products, prices, and promotions, increasing sales and reducing wasted advertising.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because segmentation often requires producing different product variations, which can raise production costs.","C":"Incorrect because market research is needed to identify and understand market segments.","D":"Incorrect because competitors are free to target the same profitable segments."}}},{"id":"P1_U3_MCQ_651","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_651","question":"Which statement accurately describes a market-oriented business?","options":{"A":"It develops a product first based on engineering skill and then searches for buyers.","B":"It carries out market research to identify customer needs before developing a product.","C":"It ignores customer feedback and focuses solely on lowering factory costs.","D":"It refuses to change its product design even when consumer tastes shift."},"correctOption":"B","correctAnswer":"It carries out market research to identify customer needs before developing a product.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a market-oriented business puts the customer first by researching wants and needs prior to designing and producing goods.","distractor_reasons":{"A":"Incorrect because designing a product before researching demand describes a product-oriented business.","B":"Correct selection.","C":"Incorrect because market-oriented firms actively collect and act upon customer feedback.","D":"Incorrect because market-oriented businesses adapt their offerings to match evolving consumer preferences."}}},{"id":"P1_U3_MCQ_652","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_652","question":"What is a key characteristic of a product-oriented business?","options":{"A":"It conducts extensive consumer surveys before designing any prototype.","B":"It relies exclusively on secondary government data to set prices.","C":"It focuses primarily on the product itself and production quality before finding a market.","D":"It only operates in the tertiary service sector of the economy."},"correctOption":"C","correctAnswer":"It focuses primarily on the product itself and production quality before finding a market.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because product-oriented businesses concentrate on manufacturing a high-quality or innovative product first, then try to persuade consumers to buy it.","distractor_reasons":{"A":"Incorrect because researching customer wants before design is the hallmark of a market-oriented business.","B":"Incorrect because pricing and research methods do not define product orientation.","C":"Correct selection.","D":"Incorrect because product-oriented businesses are frequently found in manufacturing and technology sectors."}}},{"id":"P1_U3_MCQ_653","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_653","question":"What is the main reason why businesses carry out market research?","options":{"A":"To guarantee that every new product will earn a monopoly profit.","B":"To avoid paying legal minimum wages to sales employees.","C":"To replace the need for quality control in the factory.","D":"To reduce the risk of product failure by understanding customer needs and competition."},"correctOption":"D","correctAnswer":"To reduce the risk of product failure by understanding customer needs and competition.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because market research provides information about consumer preferences, market size, and competitors, lowering the risk of launching unsuitable products.","distractor_reasons":{"A":"Incorrect because market research reduces risk, but cannot guarantee success or monopoly status.","B":"Incorrect because legal minimum wage laws apply regardless of market research.","C":"Incorrect because quality control ensures production standards, whereas market research gathers market data.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_654","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_654","question":"What is meant by 'primary market research' (field research)?","options":{"A":"The collection and collation of original, first-hand data directly from potential or existing customers.","B":"The analysis of historical sales statistics already published by government departments.","C":"The reading of competitor websites and trade magazines to gather industry news.","D":"The extraction of raw materials such as oil and timber from the Earth."},"correctOption":"A","correctAnswer":"The collection and collation of original, first-hand data directly from potential or existing customers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because primary research involves gathering brand-new, original data directly from the field for a specific business purpose.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because using existing government statistics is secondary (desk) research.","C":"Incorrect because reviewing published websites and trade magazines is secondary research.","D":"Incorrect because extracting natural resources defines the primary sector of industry, not primary research."}}},{"id":"P1_U3_MCQ_655","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_655","question":"What is meant by 'secondary market research' (desk research)?","options":{"A":"Conducting face-to-face interviews with shoppers in a town centre.","B":"Using information that has already been collected and published by other organisations.","C":"Observing customers as they select items from supermarket shelves.","D":"Organising a focus group to test a newly invented product prototype."},"correctOption":"B","correctAnswer":"Using information that has already been collected and published by other organisations.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because secondary research uses existing data previously gathered for another purpose, such as market reports, government data, or company records.","distractor_reasons":{"A":"Incorrect because interviewing shoppers collects new first-hand data (primary research).","B":"Correct selection.","C":"Incorrect because observing shoppers is a primary research method.","D":"Incorrect because running a focus group generates original primary data."}}},{"id":"P1_U3_MCQ_656","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_656","question":"What is a major advantage of primary research compared to secondary research?","options":{"A":"It is always completely free of charge to collect.","B":"It requires no planning or questionnaire design.","C":"The data is up to date and collected specifically for the business's exact needs.","D":"It can be completed in seconds without contacting any consumers."},"correctOption":"C","correctAnswer":"The data is up to date and collected specifically for the business's exact needs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because primary research is tailored to the business's specific questions and reflects current market conditions, unlike older secondary sources.","distractor_reasons":{"A":"Incorrect because primary research is usually expensive to conduct.","B":"Incorrect because primary research requires careful design of surveys, samples, or interviews.","C":"Correct selection.","D":"Incorrect because collecting original data from consumers is time-consuming."}}},{"id":"P1_U3_MCQ_657","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_657","question":"Which of the following is a disadvantage of primary market research?","options":{"A":"The information is freely available to all rival competitors.","B":"The data is always several years out of date before collection.","C":"It cannot be used to ask consumers about new product ideas.","D":"It is often expensive and time-consuming to collect and analyse."},"correctOption":"D","correctAnswer":"It is often expensive and time-consuming to collect and analyse.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because designing surveys, paying interviewers, and analysing original responses requires substantial time and money.","distractor_reasons":{"A":"Incorrect because primary data belongs to the business that collected it, whereas secondary data is publicly available.","B":"Incorrect because out-of-date data is a limitation of secondary research, not primary research.","C":"Incorrect because primary research is ideal for testing new product concepts.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_658","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_658","question":"What is a key advantage of secondary market research?","options":{"A":"It is relatively cheap and quick to obtain compared to primary research.","B":"It is guaranteed to answer the business's exact product-specific questions.","C":"It prevents competitors from accessing the same published statistics.","D":"It eliminates any risk of bias in the original data collection."},"correctOption":"A","correctAnswer":"It is relatively cheap and quick to obtain compared to primary research.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because secondary sources like government websites and trade reports already exist, saving time and money.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because secondary data was collected for another purpose and may not fit specific business needs.","C":"Incorrect because published secondary sources are accessible to competitors too.","D":"Incorrect because secondary data may still contain bias or errors from whoever originally collected it."}}},{"id":"P1_U3_MCQ_659","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_659","question":"What is a major limitation of relying solely on secondary market research?","options":{"A":"It takes longer to access than conducting nationwide face-to-face interviews.","B":"The data may be out of date or collected for a different purpose.","C":"It can only provide qualitative opinions rather than numerical figures.","D":"It is illegal to use government statistics for commercial planning."},"correctOption":"B","correctAnswer":"The data may be out of date or collected for a different purpose.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because published data may reflect past market conditions or be too broad for a specific product decision.","distractor_reasons":{"A":"Incorrect because secondary research is much faster to gather than field interviews.","B":"Correct selection.","C":"Incorrect because secondary sources often provide quantitative statistics such as population and sales data.","D":"Incorrect because government statistics are publicly provided for business and research use."}}},{"id":"P1_U3_MCQ_660","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_660","question":"Which primary research method involves asking a sample of consumers a set of structured questions online, by post, or in person?","options":{"A":"Observation.","B":"Trade magazine review.","C":"Questionnaire or survey.","D":"Competitor website analysis."},"correctOption":"C","correctAnswer":"Questionnaire or survey.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because questionnaires or surveys use a planned list of questions to gather structured responses from a sample of people.","distractor_reasons":{"A":"Incorrect because observation watches behaviour without asking questions.","B":"Incorrect because reading trade magazines is secondary research.","C":"Correct selection.","D":"Incorrect because reviewing competitor websites is secondary research."}}},{"id":"P1_U3_MCQ_661","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_661","question":"Which problem can reduce the reliability of data collected through online or postal questionnaires?","options":{"A":"Interviewer facial expressions influencing every respondent.","B":"Inability to ask any quantitative multiple-choice questions.","C":"Excessive cost of hiring physical meeting rooms for respondents.","D":"Low response rates and poorly worded questions that bias answers."},"correctOption":"D","correctAnswer":"Low response rates and poorly worded questions that bias answers.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because many people ignore online or postal surveys, and unclear or leading questions can distort the results.","distractor_reasons":{"A":"Incorrect because there is no interviewer present during self-completed online or postal questionnaires.","B":"Incorrect because questionnaires are ideal for collecting quantitative multiple-choice data.","C":"Incorrect because hiring meeting rooms is a cost associated with focus groups, not postal/online surveys.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_662","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_662","question":"What is a key advantage of using face-to-face interviews as a primary research method?","options":{"A":"The interviewer can explain unclear questions and gather detailed responses.","B":"It is the cheapest method for reaching millions of global consumers overnight.","C":"It completely eliminates any possibility of interviewer bias.","D":"Respondents always give honest answers even on sensitive personal topics."},"correctOption":"A","correctAnswer":"The interviewer can explain unclear questions and gather detailed responses.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because direct interaction allows the interviewer to clarify misunderstandings and probe deeper into customer opinions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because interviewing people individually is expensive and slow compared to online surveys.","C":"Incorrect because interviewers can unintentionally influence respondents through tone or wording.","D":"Incorrect because respondents may give socially desirable rather than completely honest answers in person."}}},{"id":"P1_U3_MCQ_663","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_663","question":"What is a disadvantage of using interviews to gather primary market research?","options":{"A":"Questions cannot be explained if a respondent is confused.","B":"Trained interviewers are expensive to employ and interviewer bias may occur.","C":"It only provides secondary historical data from past years.","D":"It cannot be used to gather qualitative consumer opinions."},"correctOption":"B","correctAnswer":"Trained interviewers are expensive to employ and interviewer bias may occur.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because conducting individual interviews requires paying skilled staff and risks the interviewer leading the respondent's answers.","distractor_reasons":{"A":"Incorrect because clarifying questions is an advantage of interviews, not a disadvantage.","B":"Correct selection.","C":"Incorrect because interviews collect original primary data.","D":"Incorrect because interviews are well suited to collecting detailed qualitative insights."}}},{"id":"P1_U3_MCQ_664","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_664","question":"What is a 'focus group' in market research?","options":{"A":"A team of factory inspectors checking finished goods for defects.","B":"A government agency that regulates misleading product advertisements.","C":"A small group of consumers brought together to discuss views on a product or advert.","D":"A department responsible for preparing annual financial statements."},"correctOption":"C","correctAnswer":"A small group of consumers brought together to discuss views on a product or advert.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a focus group gathers a small group of target consumers for a guided discussion to obtain in-depth qualitative feedback.","distractor_reasons":{"A":"Incorrect because checking finished goods for defects is quality control.","B":"Incorrect because consumer protection agencies enforce laws rather than conduct focus groups.","C":"Correct selection.","D":"Incorrect because preparing financial statements is the role of the Finance department."}}},{"id":"P1_U3_MCQ_665","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_665","question":"Which of the following is a disadvantage of using focus groups for market research?","options":{"A":"Participants are not allowed to express detailed opinions.","B":"It relies purely on outdated government census publications.","C":"It cannot be used to test packaging designs or advertisements.","D":"Dominant group members may influence the opinions expressed by quieter participants."},"correctOption":"D","correctAnswer":"Dominant group members may influence the opinions expressed by quieter participants.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because outspoken individuals in a group discussion can sway others, biasing the qualitative feedback collected.","distractor_reasons":{"A":"Incorrect because encouraging detailed opinions is the main purpose of a focus group.","B":"Incorrect because focus groups generate new primary data.","C":"Incorrect because focus groups are frequently used to test packaging and adverts.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_666","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_666","question":"How does the 'observation' method of primary market research work?","options":{"A":"Watching and recording consumer behaviour, such as store traffic or product selection.","B":"Mailing paper questionnaires to thousands of households across the country.","C":"Reading published market reports written by independent research agencies.","D":"Interviewing a panel of consumers about why they prefer a rival brand."},"correctOption":"A","correctAnswer":"Watching and recording consumer behaviour, such as store traffic or product selection.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because observation involves recording actual consumer actions (such as counting shoppers or watching shelf choices) without direct questioning.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because mailing surveys is the questionnaire method.","C":"Incorrect because reading published reports is secondary research.","D":"Incorrect because questioning a panel is an interview or focus group method."}}},{"id":"P1_U3_MCQ_667","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_667","question":"What is the main limitation of observation as a method of market research?","options":{"A":"It is illegal to record customer footfall inside retail stores.","B":"It shows how consumers behave, but does not explain the reasons behind their choices.","C":"It requires consumers to fill out lengthy written forms.","D":"It can only be used for secondary desk research."},"correctOption":"B","correctAnswer":"It shows how consumers behave, but does not explain the reasons behind their choices.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because observation records visible actions (what people buy or where they walk) without revealing their underlying motives.","distractor_reasons":{"A":"Incorrect because observing public shopper behaviour is a standard legal research practice.","B":"Correct selection.","C":"Incorrect because observation does not require respondents to complete forms.","D":"Incorrect because observation collects new primary data."}}},{"id":"P1_U3_MCQ_668","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_668","question":"Which of the following is an example of an external secondary research source?","options":{"A":"A questionnaire designed and distributed by the business's own marketing team.","B":"A focus group hosted at the company's headquarters.","C":"Government census statistics and published market research reports.","D":"Live observation of shoppers entering the business's retail branch."},"correctOption":"C","correctAnswer":"Government census statistics and published market research reports.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because government statistics and commercial market reports are published by external organisations and already exist.","distractor_reasons":{"A":"Incorrect because an original questionnaire is primary research.","B":"Incorrect because a focus group generates original primary research.","C":"Correct selection.","D":"Incorrect because observing shoppers collects primary data."}}},{"id":"P1_U3_MCQ_669","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_669","question":"Why do businesses examine competitor websites and trade magazines during market research?","options":{"A":"To collect first-hand primary feedback from their own loyal customers.","B":"To conduct random sampling of local household incomes.","C":"To avoid having to pay any taxes on online sales.","D":"To gather secondary data on rival prices, product ranges, and industry trends."},"correctOption":"D","correctAnswer":"To gather secondary data on rival prices, product ranges, and industry trends.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because competitor websites and trade publications provide readily available secondary information about rivals and market developments.","distractor_reasons":{"A":"Incorrect because reviewing websites and magazines is secondary desk research, not primary customer feedback.","B":"Incorrect because random sampling is a primary survey technique.","C":"Incorrect because market research does not affect tax obligations.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_670","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_670","question":"What is meant by a 'sample' in market research?","options":{"A":"A selected group of people chosen to represent the wider target market.","B":"The entire population of a country who could ever buy any product.","C":"A faulty item removed from a factory production line by an inspector.","D":"A legal document setting out the terms of an employment contract."},"correctOption":"A","correctAnswer":"A selected group of people chosen to represent the wider target market.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a sample is a smaller sub-group of the target population surveyed to estimate the views of the whole market.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the entire group is the target population, whereas a sample is a representative subset.","C":"Incorrect because inspecting defective items relates to quality control.","D":"Incorrect because employment terms belong to HRM contracts."}}},{"id":"P1_U3_MCQ_671","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_671","question":"Why is sampling useful to businesses conducting primary market research?","options":{"A":"It guarantees 100% accuracy without any margin of error.","B":"It is much cheaper and faster than surveying every individual in the target market.","C":"It eliminates the need to write clear survey questions.","D":"It allows businesses to ignore the target market's demographic profile."},"correctOption":"B","correctAnswer":"It is much cheaper and faster than surveying every individual in the target market.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because surveying an entire population is usually impractical and costly, whereas a well-chosen sample provides reliable insights quickly and affordably.","distractor_reasons":{"A":"Incorrect because sampling always carries some degree of sampling error.","B":"Correct selection.","C":"Incorrect because clear, unbiased questions are still essential for accurate results.","D":"Incorrect because understanding the target market's profile is vital for selecting a representative sample."}}},{"id":"P1_U3_MCQ_672","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_672","question":"How are respondents chosen in a 'random sample'?","options":{"A":"Only the business's existing loyal customers are invited to reply.","B":"Interviewers select people strictly based on specific age and income quotas.","C":"Every member of the target population has an equal chance of being selected.","D":"Only respondents who volunteer on social media are included."},"correctOption":"C","correctAnswer":"Every member of the target population has an equal chance of being selected.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because random sampling selects individuals purely by chance so every member of the population has an equal probability of inclusion.","distractor_reasons":{"A":"Incorrect because restricting to existing customers creates bias and is not random across the population.","B":"Incorrect because selecting by specific characteristics in set proportions defines quota sampling.","C":"Correct selection.","D":"Incorrect because self-selected social media volunteers do not form a random sample."}}},{"id":"P1_U3_MCQ_673","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_673","question":"What is meant by 'quota sampling'?","options":{"A":"Selecting every tenth name from an alphabetical telephone directory.","B":"Surveying every single person living within a country.","C":"Choosing respondents completely by luck using a computer generator.","D":"Selecting respondents based on specific characteristics such as age or gender in set proportions."},"correctOption":"D","correctAnswer":"Selecting respondents based on specific characteristics such as age or gender in set proportions.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because quota sampling divides the population into specific groups (e.g. age or gender) and requires researchers to interview a fixed number from each group.","distractor_reasons":{"A":"Incorrect because picking every nth name is systematic/random sampling.","B":"Incorrect because surveying everyone is a census, not sampling.","C":"Incorrect because pure chance selection defines random sampling.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_674","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_674","question":"Which factor is most likely to reduce the accuracy of primary market research data?","options":{"A":"Using a sample size that is too small or unrepresentative of the target market.","B":"Testing the questionnaire on a small pilot group before the main survey.","C":"Using clear, neutral wording that avoids leading respondents.","D":"Combining primary survey findings with up-to-date secondary statistics."},"correctOption":"A","correctAnswer":"Using a sample size that is too small or unrepresentative of the target market.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because if a sample is too small or does not reflect the target market's characteristics, the findings will be biased and unreliable.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pilot testing improves accuracy by identifying confusing questions early.","C":"Incorrect because neutral wording prevents bias and increases accuracy.","D":"Incorrect because cross-checking primary and secondary data improves reliability."}}},{"id":"P1_U3_MCQ_675","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_675","question":"Which factor most strongly affects the accuracy of secondary market research data?","options":{"A":"The physical weather conditions on the day a manager reads the report.","B":"How recently the data was published and the reliability of its original source.","C":"Whether the business uses flow production or batch production.","D":"The number of subordinates reporting to the Operations Manager."},"correctOption":"B","correctAnswer":"How recently the data was published and the reliability of its original source.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because outdated statistics or biased original publishers can make secondary data inaccurate for current business decisions.","distractor_reasons":{"A":"Incorrect because reading conditions do not change the accuracy of published data.","B":"Correct selection.","C":"Incorrect because production methods do not determine the accuracy of external research sources.","D":"Incorrect because span of control is an organisational structure concept unrelated to research accuracy."}}},{"id":"P1_U3_MCQ_676","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_676","question":"What is meant by 'brand image'?","options":{"A":"The legal patent protecting an invention from being copied.","B":"The total cost of manufacturing one unit of a product.","C":"The unique identity and perception of a product that distinguishes it from competitors.","D":"The physical warehouse where finished goods are stored before delivery."},"correctOption":"C","correctAnswer":"The unique identity and perception of a product that distinguishes it from competitors.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because brand image is the distinct identity, name, and reputation that sets a product apart from rivals in consumers' minds.","distractor_reasons":{"A":"Incorrect because legal protection of inventions is a patent, not brand image.","B":"Incorrect because cost per unit is average production cost.","C":"Correct selection.","D":"Incorrect because storage facilities relate to inventory and distribution."}}},{"id":"P1_U3_MCQ_677","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_677","question":"Why is building a strong brand image important for a business?","options":{"A":"It eliminates all variable costs of raw materials.","B":"It removes the need to comply with consumer safety laws.","C":"It guarantees that a product will never enter the decline stage.","D":"It enables higher prices to be charged and encourages customer loyalty."},"correctOption":"D","correctAnswer":"It enables higher prices to be charged and encourages customer loyalty.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumers trust strong brands, allowing the business to charge premium prices, increase added value, and retain loyal buyers.","distractor_reasons":{"A":"Incorrect because raw material costs still vary with output.","B":"Incorrect because all businesses must meet safety standards regardless of brand strength.","C":"Incorrect because even strong brands can decline if not updated over time.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_678","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_678","question":"What is meant by 'brand loyalty'?","options":{"A":"When consumers repeatedly purchase the same brand rather than switching to rivals.","B":"When employees refuse to leave a company for higher-paying jobs.","C":"When suppliers offer bulk-buying discounts to large manufacturers.","D":"When a wholesaler agrees to stock only one category of goods."},"correctOption":"A","correctAnswer":"When consumers repeatedly purchase the same brand rather than switching to rivals.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because brand loyalty occurs when satisfied customers consistently buy the same brand again and again.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because employee retention relates to HRM motivation, not brand loyalty.","C":"Incorrect because bulk discounts are purchasing economies of scale.","D":"Incorrect because wholesaler stocking relates to distribution channels."}}},{"id":"P1_U3_MCQ_679","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_679","question":"Which of the following is a key role of packaging in the marketing mix?","options":{"A":"Increasing the weight of the product to raise transport expenses.","B":"Protecting the product, displaying required information, and reinforcing brand image.","C":"Replacing the need for any advertising or sales promotion.","D":"Ensuring the product is sold solely through online websites."},"correctOption":"B","correctAnswer":"Protecting the product, displaying required information, and reinforcing brand image.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because packaging physically protects goods during transport/storage, carries legal/usage labels, and attracts buyers through visual branding.","distractor_reasons":{"A":"Incorrect because businesses design packaging to minimise unnecessary weight and transport costs.","B":"Correct selection.","C":"Incorrect because packaging supports promotion rather than replacing advertising altogether.","D":"Incorrect because attractive packaging is especially vital on physical retail shelves as well as online."}}},{"id":"P1_U3_MCQ_680","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_680","question":"What is an advantage to a business of developing new products?","options":{"A":"It requires zero spending on research and development.","B":"It guarantees immediate high profits from the very first day of launch.","C":"It diversifies the product range, spreads risk, and can create a Unique Selling Point.","D":"It eliminates the need to train production workers."},"correctOption":"C","correctAnswer":"It diversifies the product range, spreads risk, and can create a Unique Selling Point.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because new products expand a firm's portfolio, reduce reliance on older products, and offer unique features that attract buyers.","distractor_reasons":{"A":"Incorrect because developing new products usually involves substantial research and development costs.","B":"Incorrect because new products often make losses during the introduction stage due to high launch costs.","C":"Correct selection.","D":"Incorrect because new products frequently require employee training on new production processes."}}},{"id":"P1_U3_MCQ_681","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_681","question":"What is a major risk or disadvantage of developing new products?","options":{"A":"It prevents the business from entering new international markets.","B":"It reduces the business's brand image among existing customers.","C":"It makes existing machinery run faster than its maximum capacity.","D":"High research and development costs may not be recovered if sales are low."},"correctOption":"D","correctAnswer":"High research and development costs may not be recovered if sales are low.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because developing and testing new products is expensive, and if consumer demand is weak, the business suffers a financial loss.","distractor_reasons":{"A":"Incorrect because new products often help businesses enter new markets.","B":"Incorrect because successful innovation typically strengthens brand image.","C":"Incorrect because product development does not alter machine speed limits.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_682","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_682","question":"What does the 'Product Life Cycle' illustrate?","options":{"A":"The stages a product passes through from introduction to decline in sales over time.","B":"The physical journey of raw materials from a mine to a retail shop.","C":"The daily working hours of employees on a flow production line.","D":"The sequence of stages in recruiting and selecting a new manager."},"correctOption":"A","correctAnswer":"The stages a product passes through from introduction to decline in sales over time.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the Product Life Cycle tracks how a product's sales evolve through introduction, growth, maturity, and decline.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because moving goods from raw material to retailer describes economic sectors and channels of distribution.","C":"Incorrect because employee hours relate to employment contracts and shift patterns.","D":"Incorrect because hiring steps represent the recruitment and selection process."}}},{"id":"P1_U3_MCQ_683","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_683","question":"Which set of characteristics best describes the 'introduction' stage of the Product Life Cycle?","options":{"A":"Peak sales volume, intense competition, and falling promotional spending.","B":"Slow sales growth, high promotional costs, and negative cash flow or losses.","C":"Rapidly falling sales as consumers switch to newer substitute products.","D":"Maximum economies of scale and lowest possible unit production costs."},"correctOption":"B","correctAnswer":"Slow sales growth, high promotional costs, and negative cash flow or losses.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because during introduction, consumer awareness is low so sales grow slowly while high launch advertising and development costs cause losses.","distractor_reasons":{"A":"Incorrect because peak sales and intense competition describe the maturity stage.","B":"Correct selection.","C":"Incorrect because rapidly falling sales describe the decline stage.","D":"Incorrect because low output volumes during introduction prevent maximum economies of scale."}}},{"id":"P1_U3_MCQ_684","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_684","question":"What happens during the 'growth' stage of the Product Life Cycle?","options":{"A":"Sales fall sharply and the product is withdrawn from the market.","B":"Sales remain completely flat at zero while prototypes are tested.","C":"Sales rise rapidly, unit costs fall, and the product begins to earn profits.","D":"No competitors ever enter the market because demand is shrinking."},"correctOption":"C","correctAnswer":"Sales rise rapidly, unit costs fall, and the product begins to earn profits.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because as consumers become aware of the product, sales accelerate, economies of scale lower unit costs, and profitability improves.","distractor_reasons":{"A":"Incorrect because falling sales and withdrawal happen in the decline stage.","B":"Incorrect because prototype testing occurs during development before introduction.","C":"Correct selection.","D":"Incorrect because rising sales during growth attract new competitors into the market."}}},{"id":"P1_U3_MCQ_685","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_685","question":"Which feature characterizes the 'maturity' stage of the Product Life Cycle?","options":{"A":"The product is brand new and unknown to almost all consumers.","B":"Losses are at their highest because no units have been sold yet.","C":"Production is halted permanently due to obsolete technology.","D":"Sales growth slows and reaches its peak amid intense competition."},"correctOption":"D","correctAnswer":"Sales growth slows and reaches its peak amid intense competition.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because in the maturity stage, most potential buyers have adopted the product, sales level off at their peak, and competition is fierce.","distractor_reasons":{"A":"Incorrect because low awareness defines the introduction stage.","B":"Incorrect because early losses occur in development and introduction, whereas maturity is usually highly profitable.","C":"Incorrect because withdrawal occurs at the end of the decline stage.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_686","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_686","question":"Why do sales fall during the 'decline' stage of the Product Life Cycle?","options":{"A":"Consumer tastes change or newer, improved products replace the existing one.","B":"The business has just launched its first informative advertising campaign.","C":"Economies of scale reach their highest possible level.","D":"Consumer incomes rise rapidly across all segments."},"correctOption":"A","correctAnswer":"Consumer tastes change or newer, improved products replace the existing one.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because products enter decline when shifting fashions or superior technological alternatives make them obsolete.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because initial informative advertising happens in the introduction stage.","C":"Incorrect because falling output in decline raises average fixed costs rather than maximising economies of scale.","D":"Incorrect because rising consumer incomes generally boost demand rather than cause product decline."}}},{"id":"P1_U3_MCQ_687","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_687","question":"What is the purpose of an 'extension strategy' in the Product Life Cycle?","options":{"A":"To speed up the withdrawal of an unprofitable product from shops.","B":"To prolong the maturity stage and prevent sales from falling into decline.","C":"To increase the time taken to recruit new factory workers.","D":"To raise fixed overhead costs during the introduction stage."},"correctOption":"B","correctAnswer":"To prolong the maturity stage and prevent sales from falling into decline.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because extension strategies are marketing actions used in maturity or early decline to boost sales and extend the product's profitable lifespan.","distractor_reasons":{"A":"Incorrect because extension strategies aim to keep the product selling rather than withdraw it.","B":"Correct selection.","C":"Incorrect because extension strategies relate to product marketing, not HRM recruitment.","D":"Incorrect because extension strategies are applied in maturity/decline, not introduction."}}},{"id":"P1_U3_MCQ_688","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_688","question":"Which of the following is an example of an extension strategy involving the product itself?","options":{"A":"Stopping all advertising and closing retail distribution outlets.","B":"Raising the selling price without making any improvements to the item.","C":"Redesigning the packaging or adding new features and flavours to the product.","D":"Reducing the quality of raw materials to cut production expenses."},"correctOption":"C","correctAnswer":"Redesigning the packaging or adding new features and flavours to the product.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because updating packaging or introducing minor product modifications refreshes consumer interest and extends sales.","distractor_reasons":{"A":"Incorrect because cutting promotion and distribution accelerates decline.","B":"Incorrect because raising prices without adding value reduces demand.","C":"Correct selection.","D":"Incorrect because lowering quality damages brand reputation and speeds up decline."}}},{"id":"P1_U3_MCQ_689","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_689","question":"How can a business use market expansion as an extension strategy for a mature product?","options":{"A":"By limiting sales exclusively to a single local neighbourhood.","B":"By refusing to sell the product through e-commerce platforms.","C":"By reducing the number of retail shops stocking the item.","D":"By entering new overseas markets or promoting new uses for the product."},"correctOption":"D","correctAnswer":"By entering new overseas markets or promoting new uses for the product.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because launching a mature product in new geographic markets or encouraging new ways to use it generates fresh demand.","distractor_reasons":{"A":"Incorrect because restricting sales to one area shrinks demand.","B":"Incorrect because avoiding e-commerce limits access to new buyers.","C":"Incorrect because reducing distribution outlets lowers sales volume.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_690","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_690","question":"What is meant by 'cost-plus pricing'?","options":{"A":"Calculating the unit cost of producing a product and adding a percentage mark-up for profit.","B":"Setting a low initial price to attract customers quickly to a new product.","C":"Changing prices continuously in real time based on online customer demand.","D":"Matching the exact price charged by the largest competitor in the market."},"correctOption":"A","correctAnswer":"Calculating the unit cost of producing a product and adding a percentage mark-up for profit.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost-plus pricing determines average unit cost and adds a fixed percentage or amount to ensure a profit margin.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a low launch price defines penetration pricing.","C":"Incorrect because real-time price adjustments define dynamic pricing.","D":"Incorrect because matching rivals' prices defines competitive pricing."}}},{"id":"P1_U3_MCQ_691","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_691","question":"What is an advantage of using cost-plus pricing?","options":{"A":"It guarantees that the business's price is always lower than every rival's price.","B":"It is simple to calculate and ensures production costs are covered if target sales are achieved.","C":"It automatically maximises sales during off-peak seasons.","D":"It adjusts prices instantly whenever competitor stock runs out."},"correctOption":"B","correctAnswer":"It is simple to calculate and ensures production costs are covered if target sales are achieved.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cost-plus pricing is straightforward to apply and ensures each unit sold contributes a planned profit margin over cost.","distractor_reasons":{"A":"Incorrect because cost-plus pricing may result in a price higher than competitors' prices.","B":"Correct selection.","C":"Incorrect because adjusting prices for off-peak demand describes dynamic pricing.","D":"Incorrect because cost-plus pricing does not automatically track competitor inventory."}}},{"id":"P1_U3_MCQ_692","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_692","question":"What is a major disadvantage of cost-plus pricing?","options":{"A":"It fails to include fixed costs when calculating total unit costs.","B":"It is illegal under consumer protection laws in most countries.","C":"It ignores competitors' prices and customer willingness to pay, risking lost sales.","D":"It requires expensive real-time computer algorithms to operate."},"correctOption":"C","correctAnswer":"It ignores competitors' prices and customer willingness to pay, risking lost sales.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because if a business's costs are higher than rivals', adding a standard mark-up can make the price uncompetitive.","distractor_reasons":{"A":"Incorrect because average unit cost includes both fixed and variable costs.","B":"Incorrect because cost-plus pricing is a completely legal pricing method.","C":"Correct selection.","D":"Incorrect because algorithms are associated with dynamic pricing, whereas cost-plus is simple arithmetic."}}},{"id":"P1_U3_MCQ_693","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_693","question":"What is meant by 'competitive pricing'?","options":{"A":"Setting a very high launch price for a unique, patented invention.","B":"Offering a product free of charge permanently to all consumers.","C":"Adding a fixed 50% mark-up onto the variable cost of raw materials.","D":"Setting a price in line with or just below the prices charged by rival businesses."},"correctOption":"D","correctAnswer":"Setting a price in line with or just below the prices charged by rival businesses.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because competitive pricing bases a product's price on what competitors charge for similar goods in the market.","distractor_reasons":{"A":"Incorrect because a high launch price for an innovative product defines price skimming.","B":"Incorrect because permanently free goods generate no sales revenue.","C":"Incorrect because adding a fixed mark-up to costs defines cost-plus pricing.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_694","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_694","question":"Why might a business choose to use competitive pricing?","options":{"A":"To avoid destructive price wars while keeping sales steady in a crowded market.","B":"To recover high research and development costs immediately at launch.","C":"To ensure prices change every minute according to website traffic.","D":"To create an ultra-exclusive luxury image above all rival brands."},"correctOption":"A","correctAnswer":"To avoid destructive price wars while keeping sales steady in a crowded market.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pricing close to competitors prevents aggressive price-cutting wars and keeps the product attractive when goods are similar.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because recovering high R&D costs quickly is the goal of price skimming.","C":"Incorrect because minute-by-minute price changes describe dynamic pricing.","D":"Incorrect because an exclusive luxury image usually requires premium or skimming prices above rivals."}}},{"id":"P1_U3_MCQ_695","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_695","question":"What is meant by 'penetration pricing'?","options":{"A":"Charging the highest price wealthy buyers will pay when a product is first launched.","B":"Setting a low initial price when launching a new product to gain market share quickly.","C":"Raising prices sharply during peak holiday travel periods.","D":"Selling products below cost permanently to force rivals out of business."},"correctOption":"B","correctAnswer":"Setting a low initial price when launching a new product to gain market share quickly.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because penetration pricing uses an introductory low price to encourage consumers to try a new product and rapidly build sales volume.","distractor_reasons":{"A":"Incorrect because charging a high initial price defines price skimming.","B":"Correct selection.","C":"Incorrect because peak-period price increases describe dynamic pricing.","D":"Incorrect because penetration pricing is a temporary launch strategy, after which prices are usually raised."}}},{"id":"P1_U3_MCQ_696","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_696","question":"What is a disadvantage of using penetration pricing?","options":{"A":"It prevents consumers from noticing the new product at launch.","B":"It creates an overly expensive image that deters budget shoppers.","C":"Initial profit margins are low and customers may resist when prices are later raised.","D":"It can only be used for luxury goods with zero competitors."},"correctOption":"C","correctAnswer":"Initial profit margins are low and customers may resist when prices are later raised.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because low launch prices yield small profits per unit, and buyers attracted by cheap prices may switch away once the price increases.","distractor_reasons":{"A":"Incorrect because low prices attract high initial attention and trial.","B":"Incorrect because penetration pricing sets a low, affordable price rather than an expensive one.","C":"Correct selection.","D":"Incorrect because penetration pricing is typically used in competitive mass markets, not luxury niches."}}},{"id":"P1_U3_MCQ_697","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_697","question":"What is meant by 'price skimming'?","options":{"A":"Setting a low launch price to enter a highly competitive mass market.","B":"Reducing prices every week until all unsold inventory is cleared.","C":"Charging identical prices to every competitor in a local town.","D":"Setting a high initial price for a new, unique, or innovative product."},"correctOption":"D","correctAnswer":"Setting a high initial price for a new, unique, or innovative product.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because price skimming sets a high price at launch for an innovative product with little competition before lowering it later.","distractor_reasons":{"A":"Incorrect because a low launch price defines penetration pricing.","B":"Incorrect because weekly clearance discounts are promotional markdowns, not skimming.","C":"Incorrect because matching rivals' prices defines competitive pricing.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_698","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_698","question":"What is a major advantage of price skimming for a business launching an innovative product?","options":{"A":"It helps recover high research and development costs quickly and creates a quality image.","B":"It guarantees that low-income consumers can afford the product immediately.","C":"It discourages any competitors from ever developing similar technology.","D":"It eliminates the need to advertise the product's new features."},"correctOption":"A","correctAnswer":"It helps recover high research and development costs quickly and creates a quality image.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high profit margins from early adopters allow the business to recoup R&D expenses rapidly and establish prestige.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because high initial prices exclude low-income buyers until prices are lowered later.","C":"Incorrect because high profits from skimming often attract competitors to develop rival versions.","D":"Incorrect because promotion is still required to justify the high price and explain innovations."}}},{"id":"P1_U3_MCQ_699","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_699","question":"What is meant by 'dynamic pricing'?","options":{"A":"Keeping a product's price completely fixed for at least five years.","B":"Adjusting prices flexibly and rapidly in response to changing demand and supply conditions.","C":"Calculating unit production cost and adding a fixed percentage profit.","D":"Offering a permanent 10% discount to all senior citizens."},"correctOption":"B","correctAnswer":"Adjusting prices flexibly and rapidly in response to changing demand and supply conditions.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because dynamic pricing uses real-time data to raise prices when demand is high and lower them when demand is weak.","distractor_reasons":{"A":"Incorrect because dynamic pricing changes frequently rather than staying fixed.","B":"Correct selection.","C":"Incorrect because adding a fixed percentage to unit cost defines cost-plus pricing.","D":"Incorrect because a permanent demographic discount is a fixed price concession, not dynamic pricing."}}},{"id":"P1_U3_MCQ_700","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_700","question":"How does dynamic pricing benefit businesses such as airlines and hotels?","options":{"A":"It ensures every customer pays the exact same fare regardless of booking date.","B":"It eliminates the need to use computers or online booking systems.","C":"It maximises revenue during peak demand and fills spare capacity during quiet periods.","D":"It guarantees that competitors cannot lower their ticket prices."},"correctOption":"C","correctAnswer":"It maximises revenue during peak demand and fills spare capacity during quiet periods.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because raising prices when seats or rooms are scarce boosts profit margins, while lowering prices in off-peak times attracts extra bookings.","distractor_reasons":{"A":"Incorrect because dynamic pricing results in different customers paying different prices depending on timing and demand.","B":"Incorrect because dynamic pricing relies heavily on IT and online booking platforms.","C":"Correct selection.","D":"Incorrect because competitors also use dynamic pricing to adjust their own fares."}}},{"id":"P1_U3_MCQ_701","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_701","question":"What is meant by a 'channel of distribution'?","options":{"A":"The television station chosen to broadcast a commercial.","B":"The sequence of stages used to manufacture a product on a factory line.","C":"The internal chain of command between senior directors and factory workers.","D":"The means by which a product is passed from the place of production to the customer."},"correctOption":"D","correctAnswer":"The means by which a product is passed from the place of production to the customer.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a channel of distribution describes the route and intermediaries (such as wholesalers and retailers) used to get goods from producer to consumer.","distractor_reasons":{"A":"Incorrect because selecting media stations relates to Promotion, not Place.","B":"Incorrect because factory stages relate to operations management.","C":"Incorrect because authority levels in a business refer to organisational hierarchy.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_702","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_702","question":"Which distribution channel involves a producer selling straight to the final buyer without using any intermediaries?","options":{"A":"Direct to customers.","B":"Producer to wholesaler to retailer to consumer.","C":"Producer to agent to wholesaler to consumer.","D":"Producer to retailer to consumer."},"correctOption":"A","correctAnswer":"Direct to customers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a direct channel connects the manufacturer directly with the end consumer (e.g. via factory outlets or the producer's own website).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this traditional channel uses two intermediaries (wholesaler and retailer).","C":"Incorrect because this channel uses both an agent and a wholesaler.","D":"Incorrect because this channel uses retailers as intermediaries."}}},{"id":"P1_U3_MCQ_703","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_703","question":"What is a major advantage to a producer of selling directly to consumers?","options":{"A":"Wholesalers handle all storage and delivery costs free of charge.","B":"The producer keeps the full profit margin and controls how the product is marketed.","C":"Retailers take full responsibility for resolving all customer complaints.","D":"The producer never needs to advertise or promote its brand."},"correctOption":"B","correctAnswer":"The producer keeps the full profit margin and controls how the product is marketed.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because avoiding intermediaries means no profit margin is shared with retailers or wholesalers, and the producer controls pricing and presentation.","distractor_reasons":{"A":"Incorrect because wholesalers are not used in a direct channel.","B":"Correct selection.","C":"Incorrect because retailers are bypassed in direct selling, so the producer handles customers directly.","D":"Incorrect because direct sellers must promote their products so consumers know where to buy."}}},{"id":"P1_U3_MCQ_704","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_704","question":"What is a disadvantage of direct distribution for a manufacturer of everyday consumer goods?","options":{"A":"The producer loses all contact with final customers.","B":"Intermediaries charge high retail mark-ups that double the selling price.","C":"High storage, administration, and delivery costs of dispatching many small orders.","D":"It is illegal to sell manufactured goods directly to the public."},"correctOption":"C","correctAnswer":"High storage, administration, and delivery costs of dispatching many small orders.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because storing finished inventory and shipping thousands of small individual parcels directly to households is costly and time-consuming.","distractor_reasons":{"A":"Incorrect because direct distribution increases, rather than reduces, direct contact with customers.","B":"Incorrect because there are no intermediaries taking mark-ups in a direct channel.","C":"Correct selection.","D":"Incorrect because direct-to-consumer selling is completely legal."}}},{"id":"P1_U3_MCQ_705","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_705","question":"What is the primary role of a 'retailer' in a channel of distribution?","options":{"A":"Manufacturing raw materials into finished consumer goods.","B":"Acting solely as an overseas legal adviser for exporting firms.","C":"Buying in bulk from factories and selling exclusively to other factories.","D":"Buying goods from producers or wholesalers and selling them in small quantities to consumers."},"correctOption":"D","correctAnswer":"Buying goods from producers or wholesalers and selling them in small quantities to consumers.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retailers (such as supermarkets and high-street shops) buy stock in larger quantities and sell single items conveniently to final consumers.","distractor_reasons":{"A":"Incorrect because manufacturing goods is the role of secondary-sector producers.","B":"Incorrect because overseas sales representatives are agents, not retailers.","C":"Incorrect because retailers sell to final consumers rather than manufacturing factories.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_706","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_706","question":"What is an advantage to a manufacturer of distributing products through retailers?","options":{"A":"Retailers provide wide geographic coverage and convenient access for shoppers.","B":"The manufacturer avoids paying any retailer profit margin.","C":"Retailers never stock competing brands alongside the manufacturer's product.","D":"The manufacturer keeps total control over the final price charged in every shop."},"correctOption":"A","correctAnswer":"Retailers provide wide geographic coverage and convenient access for shoppers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because established retail chains place products in numerous towns and cities where consumers regularly shop.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retailers add a profit mark-up when selling to consumers.","C":"Incorrect because most retailers stock multiple competing brands side by side.","D":"Incorrect because retailers normally set their own final retail selling prices."}}},{"id":"P1_U3_MCQ_707","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_707","question":"What is the primary function of a 'wholesaler' in a distribution channel?","options":{"A":"Designing television advertisements for global brands.","B":"Buying in bulk from producers, storing inventory, and selling smaller batches to retailers.","C":"Selling individual items directly to household consumers through high-street shops.","D":"Inspecting factory machinery to ensure compliance with health and safety laws."},"correctOption":"B","correctAnswer":"Buying in bulk from producers, storing inventory, and selling smaller batches to retailers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because wholesalers act as middlemen who 'break bulk'—buying huge quantities from manufacturers and reselling smaller cases to independent retailers.","distractor_reasons":{"A":"Incorrect because designing adverts is the role of advertising agencies or marketing departments.","B":"Correct selection.","C":"Incorrect because selling individual items to consumers is the role of retailers.","D":"Incorrect because safety inspections are carried out by operations staff or government inspectors."}}},{"id":"P1_U3_MCQ_708","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_708","question":"How does selling through a wholesaler benefit a manufacturer?","options":{"A":"It guarantees that the manufacturer receives the full retail price for every unit.","B":"It gives the manufacturer direct face-to-face contact with every individual shopper.","C":"It reduces the manufacturer's storage and transport costs through large bulk orders.","D":"It eliminates the need to maintain product quality standards."},"correctOption":"C","correctAnswer":"It reduces the manufacturer's storage and transport costs through large bulk orders.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because wholesalers buy in large bulk quantities and store the goods themselves, saving the producer warehousing and small-delivery expenses.","distractor_reasons":{"A":"Incorrect because both the wholesaler and retailer add profit margins.","B":"Incorrect because adding a wholesaler places two intermediaries between the producer and consumer.","C":"Correct selection.","D":"Incorrect because manufacturers must still maintain quality to keep wholesalers and consumers buying."}}},{"id":"P1_U3_MCQ_709","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_709","question":"What is a disadvantage to a producer of using a wholesaler in its distribution channel?","options":{"A":"The producer must build large warehouses to store stock for small shops.","B":"Small independent retailers are unable to buy stock in affordable quantities.","C":"The producer has to deliver single items directly to thousands of households.","D":"The wholesaler takes a profit margin, reducing the producer's share or raising final prices."},"correctOption":"D","correctAnswer":"The wholesaler takes a profit margin, reducing the producer's share or raising final prices.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because adding a wholesaler creates an extra intermediary who takes a cut of the profit, either lowering producer revenue or making the retail price less competitive.","distractor_reasons":{"A":"Incorrect because wholesalers take over the storage function from the producer.","B":"Incorrect because enabling small shops to buy small quantities is an advantage of wholesalers.","C":"Incorrect because wholesalers handle distribution to retailers rather than the producer shipping to households.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_710","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_710","question":"What is the role of an 'agent' in a channel of distribution?","options":{"A":"An independent specialist hired to find buyers and arrange sales in a foreign market.","B":"A factory employee responsible for operating automated welding robots.","C":"A supermarket checkout operator scanning customer barcodes.","D":"A government official who collects import tariffs at national borders."},"correctOption":"A","correctAnswer":"An independent specialist hired to find buyers and arrange sales in a foreign market.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because agents are appointed to represent a business in overseas markets, using local contacts and knowledge to secure sales for a commission.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because operating factory machines is a production role.","C":"Incorrect because checkout staff work for retailers.","D":"Incorrect because customs officers work for the government, not as distribution agents."}}},{"id":"P1_U3_MCQ_711","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_711","question":"What is a disadvantage of using an agent to sell products in another country?","options":{"A":"The agent has no knowledge of local language or customs.","B":"The business has less control over how the product is marketed and must pay commission.","C":"The business must build its own expensive retail stores in the foreign country.","D":"Agents are legally prohibited from selling to foreign wholesalers."},"correctOption":"B","correctAnswer":"The business has less control over how the product is marketed and must pay commission.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because agents act independently on commission, meaning the producer sacrifices direct control over day-to-day selling and promotion.","distractor_reasons":{"A":"Incorrect because local market knowledge is the main advantage of hiring an agent.","B":"Correct selection.","C":"Incorrect because using an agent avoids the capital cost of opening overseas branches.","D":"Incorrect because agents regularly arrange deals with overseas wholesalers and retailers."}}},{"id":"P1_U3_MCQ_712","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_712","question":"What is meant by 'e-commerce' (electronic commerce)?","options":{"A":"Advertising products solely through printed posters and street leaflets.","B":"Manufacturing electronic components on an automated assembly line.","C":"The online buying and selling of goods and services using internet-linked devices.","D":"Using internal email to send shift schedules to factory employees."},"correctOption":"C","correctAnswer":"The online buying and selling of goods and services using internet-linked devices.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because e-commerce refers to conducting commercial transactions—buying and selling goods or services—over the internet.","distractor_reasons":{"A":"Incorrect because posters and leaflets are traditional offline advertising methods.","B":"Incorrect because manufacturing electronics is secondary-sector production, not e-commerce.","C":"Correct selection.","D":"Incorrect because emailing staff schedules is internal workplace communication."}}},{"id":"P1_U3_MCQ_713","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_713","question":"Which of the following is a major advantage of e-commerce to a business?","options":{"A":"It guarantees zero competition from overseas producers.","B":"It eliminates all costs of shipping and delivering physical parcels.","C":"It increases face-to-face personal interaction with every shopper.","D":"It allows the business to reach global customers 24/7 without physical shop rents."},"correctOption":"D","correctAnswer":"It allows the business to reach global customers 24/7 without physical shop rents.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an e-commerce website operates continuously worldwide, expanding potential sales while reducing high-street retail overhead costs.","distractor_reasons":{"A":"Incorrect because e-commerce increases global competition rather than removing it.","B":"Incorrect because delivering individual online orders often increases transport costs.","C":"Incorrect because e-commerce lacks direct face-to-face personal contact.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_714","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_714","question":"Which of the following is a disadvantage of e-commerce for a retail business?","options":{"A":"High costs of processing returned goods because customers cannot try items before buying.","B":"Customers can only place orders during standard daytime shop opening hours.","C":"It is impossible to display photographs or product descriptions on a website.","D":"Banks refuse to process debit or credit card payments made online."},"correctOption":"A","correctAnswer":"High costs of processing returned goods because customers cannot try items before buying.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because online shoppers cannot touch or try on products beforehand, leading to higher return rates and added administration/logistics expenses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because e-commerce allows customers to order 24 hours a day, 7 days a week.","C":"Incorrect because websites routinely display rich images, videos, and detailed descriptions.","D":"Incorrect because electronic card payments are a standard feature of e-commerce."}}},{"id":"P1_U3_MCQ_715","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_715","question":"What is a key advantage of e-commerce to customers?","options":{"A":"Products can always be touched, worn, and tested physically before paying.","B":"It is convenient to shop 24/7 from home and easily compare prices across websites.","C":"Delivery of physical goods is always instantaneous with zero waiting time.","D":"There is zero risk of online fraud or fake websites."},"correctOption":"B","correctAnswer":"It is convenient to shop 24/7 from home and easily compare prices across websites.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because online shopping saves travel time, operates around the clock, and lets buyers compare prices and choices quickly.","distractor_reasons":{"A":"Incorrect because inability to inspect physical items before purchase is a disadvantage of e-commerce.","B":"Correct selection.","C":"Incorrect because physical goods take time to be delivered after ordering.","D":"Incorrect because security concerns, hacking, and bogus websites remain risks for online shoppers."}}},{"id":"P1_U3_MCQ_716","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_716","question":"Which of the following is a disadvantage of online shopping for customers?","options":{"A":"Limited choice compared to a small local corner shop.","B":"Inability to pay using debit or credit cards.","C":"Inability to see, touch, or try on products before purchase, plus potential delivery fees.","D":"Websites close every evening and on weekends."},"correctOption":"C","correctAnswer":"Inability to see, touch, or try on products before purchase, plus potential delivery fees.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because online buyers cannot physically inspect goods beforehand, often pay extra shipping charges, and face inconvenience when returning unsuitable items.","distractor_reasons":{"A":"Incorrect because online shopping offers far wider choice than physical stores.","B":"Incorrect because card payments are quick and standard online.","C":"Correct selection.","D":"Incorrect because online stores remain open 24/7."}}},{"id":"P1_U3_MCQ_717","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_717","question":"What is the primary purpose of 'promotion' in the marketing mix?","options":{"A":"To calculate the break-even level of output for a factory.","B":"To transport raw materials from suppliers to manufacturing plants.","C":"To recruit and train new managers for the Human Resources department.","D":"To inform consumers about products, persuade them to buy, and build brand image."},"correctOption":"D","correctAnswer":"To inform consumers about products, persuade them to buy, and build brand image.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because promotion communicates with target customers to raise awareness, encourage purchases, and strengthen brand identity.","distractor_reasons":{"A":"Incorrect because break-even calculation is a financial/operations management tool.","B":"Incorrect because transporting materials is part of operations and logistics.","C":"Incorrect because staff recruitment is an HRM function.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_718","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_718","question":"How does 'sales promotion' differ from 'advertising'?","options":{"A":"Sales promotion offers short-term incentives to boost immediate sales, whereas advertising communicates through paid media.","B":"Sales promotion is only used by public sector charities, whereas advertising is for profit-making firms.","C":"Sales promotion is legally banned in retail stores, whereas advertising is unrestricted.","D":"Sales promotion never costs the business any money, whereas advertising is always expensive."},"correctOption":"A","correctAnswer":"Sales promotion offers short-term incentives to boost immediate sales, whereas advertising communicates through paid media.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sales promotion uses short-term deals (like vouchers, discounts, and competitions) to trigger immediate buying, while advertising uses media (like TV, social media, and billboards) to inform and persuade.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because private-sector businesses widely use both advertising and sales promotion.","C":"Incorrect because sales promotions are legal provided they are not misleading.","D":"Incorrect because sales promotions (such as price discounts, free gifts, and loyalty points) also incur costs."}}},{"id":"P1_U3_MCQ_719","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_719","question":"Why do businesses use money-off vouchers as a method of sales promotion?","options":{"A":"To permanently increase the standard retail price of the product.","B":"To encourage consumers to try a new product or make a repeat purchase.","C":"To replace the need for product packaging.","D":"To prevent wholesalers from stocking competing brands."},"correctOption":"B","correctAnswer":"To encourage consumers to try a new product or make a repeat purchase.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because money-off coupons reduce the purchase price temporarily, motivating hesitant buyers to trial a new item or buy again.","distractor_reasons":{"A":"Incorrect because vouchers offer a temporary price reduction rather than a permanent price increase.","B":"Correct selection.","C":"Incorrect because vouchers are often printed on or inside packaging rather than replacing it.","D":"Incorrect because vouchers target final consumers, not wholesaler stocking decisions."}}},{"id":"P1_U3_MCQ_720","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_720","question":"How do customer reward schemes (loyalty cards) help a business achieve its marketing aims?","options":{"A":"They eliminate the need to maintain satisfactory product quality.","B":"They ensure the business never has to pay for advertising.","C":"They encourage repeat purchases by awarding points or discounts to regular shoppers.","D":"They prevent customers from ever visiting rival stores by law."},"correctOption":"C","correctAnswer":"They encourage repeat purchases by awarding points or discounts to regular shoppers.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because reward schemes give customers financial incentives to keep returning to the same business, strengthening customer loyalty.","distractor_reasons":{"A":"Incorrect because customers will stop returning if product quality is poor.","B":"Incorrect because businesses still advertise alongside running loyalty programmes.","C":"Correct selection.","D":"Incorrect because loyalty cards encourage repeat visits through rewards, not legal bans."}}},{"id":"P1_U3_MCQ_721","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_721","question":"What is an advantage of using competitions or special offers as a sales promotion method?","options":{"A":"They guarantee zero production costs for the promoted item.","B":"They permanently establish a luxury price image for budget goods.","C":"They eliminate all shipping expenses for e-commerce orders.","D":"They attract consumer attention and boost short-term sales volume."},"correctOption":"D","correctAnswer":"They attract consumer attention and boost short-term sales volume.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because competitions and special offers create excitement and urgency, stimulating immediate customer purchases.","distractor_reasons":{"A":"Incorrect because production costs are unaffected by sales promotions.","B":"Incorrect because frequent discounts can actually cheapen a brand's luxury image.","C":"Incorrect because shipping costs still apply unless absorbed by the seller.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_722","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_722","question":"What is a key advantage of advertising on social media platforms?","options":{"A":"It is relatively low cost and allows precise targeting of specific consumer groups.","B":"Consumers never ignore online adverts or scroll past sponsored posts.","C":"It guarantees that older consumers without internet access will see the advert.","D":"It requires no creative design or ongoing content updates."},"correctOption":"A","correctAnswer":"It is relatively low cost and allows precise targeting of specific consumer groups.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social media advertising reaches large audiences affordably and uses user data to target specific ages, locations, and interests.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because many users ignore or block constant social media advertisements.","C":"Incorrect because people without internet or social media accounts cannot view online ads.","D":"Incorrect because effective social media campaigns require engaging visuals and regular updates."}}},{"id":"P1_U3_MCQ_723","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_723","question":"What is an advantage of using direct or targeted emails as an advertising method?","options":{"A":"Every recipient is legally required to open and read marketing emails.","B":"It is a cheap way to send personalised offers directly to interested or existing customers.","C":"It requires no customer email addresses or database management.","D":"It reaches people who do not own computers or smartphones."},"correctOption":"B","correctAnswer":"It is a cheap way to send personalised offers directly to interested or existing customers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because targeted emails cost very little to send and can be tailored to customers who have already shown interest in the business.","distractor_reasons":{"A":"Incorrect because many recipients delete promotional emails as spam without reading them.","B":"Correct selection.","C":"Incorrect because businesses must collect and maintain a list of valid customer email addresses.","D":"Incorrect because recipients need internet-connected devices to read emails."}}},{"id":"P1_U3_MCQ_724","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_724","question":"What is a major disadvantage of using printed leaflets as an advertising method?","options":{"A":"They are much more expensive to produce than nationwide television commercials.","B":"Consumers cannot keep them for future reference or attach money-off vouchers.","C":"They are often thrown away unread as junk mail and may be seen as wasteful.","D":"They cannot be distributed in a specific local area."},"correctOption":"C","correctAnswer":"They are often thrown away unread as junk mail and may be seen as wasteful.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because many people discard unsolicited leaflets immediately without reading them, and paper waste can harm a firm's environmental image.","distractor_reasons":{"A":"Incorrect because leaflets are one of the cheapest advertising methods compared to TV.","B":"Incorrect because keeping printed leaflets and including vouchers are advantages of leaflets.","C":"Correct selection.","D":"Incorrect because leaflets are easily targeted to specific local neighbourhoods."}}},{"id":"P1_U3_MCQ_725","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_725","question":"What is a key limitation of advertising on roadside billboards?","options":{"A":"They are removed after only five minutes of display.","B":"They cannot display large, colourful images.","C":"They can only be viewed by people who own a smartphone.","D":"Very little detailed product information can be included because passers-by have little time to read."},"correctOption":"D","correctAnswer":"Very little detailed product information can be included because passers-by have little time to read.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because drivers and pedestrians pass billboards quickly, so adverts must rely on short slogans and bold visuals rather than detailed text.","distractor_reasons":{"A":"Incorrect because billboards remain displayed for weeks or months.","B":"Incorrect because large, eye-catching visuals are the main strength of billboards.","C":"Incorrect because billboards are visible to anyone passing by physically.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_726","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_726","question":"What is meant by a 'marketing strategy'?","options":{"A":"A plan combining a clear marketing objective with an appropriate marketing mix to achieve it.","B":"A financial statement showing a business's assets and liabilities on a specific date.","C":"A legal contract signed between an employer and a newly recruited worker.","D":"A production schedule showing the daily output targets of factory machines."},"correctOption":"A","correctAnswer":"A plan combining a clear marketing objective with an appropriate marketing mix to achieve it.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a marketing strategy sets out a specific marketing goal (such as increasing market share) and coordinates Product, Price, Place, and Promotion to achieve it.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because assets and liabilities are shown on a Statement of Financial Position.","C":"Incorrect because an employer-employee agreement is a contract of employment.","D":"Incorrect because daily factory output targets relate to operations management."}}},{"id":"P1_U3_MCQ_727","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_727","question":"Why is it essential for all four elements of the marketing mix to be consistent with one another?","options":{"A":"Because laws require every business to spend equal money on each of the four Ps.","B":"Because a unified marketing mix sends a clear, believable image to the target market.","C":"Because consistency eliminates the need to conduct any market research.","D":"Because consistent products never enter the decline stage of the life cycle."},"correctOption":"B","correctAnswer":"Because a unified marketing mix sends a clear, believable image to the target market.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because if one element contradicts the others (e.g. a luxury product sold in discount stores), consumers become confused and the strategy fails.","distractor_reasons":{"A":"Incorrect because there is no legal rule requiring equal spending across the four Ps.","B":"Correct selection.","C":"Incorrect because market research is still needed to design a suitable marketing mix.","D":"Incorrect because all products eventually face life-cycle changes regardless of mix consistency."}}},{"id":"P1_U3_MCQ_728","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_728","question":"Which of the following illustrates an inconsistent marketing mix?","options":{"A":"Selling an everyday household soap at a competitive price in supermarkets.","B":"Advertising a new youth smartphone app on popular social media platforms.","C":"Promoting an exclusive, high-priced luxury watch using cheap street leaflets.","D":"Using price skimming for a newly invented, high-tech electronic device."},"correctOption":"C","correctAnswer":"Promoting an exclusive, high-priced luxury watch using cheap street leaflets.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cheap street flyers clash with a high price and luxury brand image, undermining consumer perception of exclusivity.","distractor_reasons":{"A":"Incorrect because competitive pricing and supermarket distribution fit an everyday consumer good.","B":"Incorrect because social media matches a youth-targeted digital app.","C":"Correct selection.","D":"Incorrect because price skimming is well suited to innovative high-tech products."}}},{"id":"P1_U3_MCQ_729","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_729","question":"Why must a business regularly review and adapt its marketing strategy over time?","options":{"A":"Because consumer tastes, competitor actions, and Product Life Cycle stages constantly evolve.","B":"Because fixed costs never change once a business has been established.","C":"Because consumer protection laws forbid using the same brand name for more than two years.","D":"Because market segmentation only works during the introduction stage."},"correctOption":"A","correctAnswer":"Because consumer tastes, competitor actions, and Product Life Cycle stages constantly evolve.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dynamic market conditions—such as new competitors, shifting customer preferences, and product maturity—require ongoing updates to the four Ps.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fixed costs can change over time as a business expands or relocates.","C":"Incorrect because businesses can keep brand names permanently.","D":"Incorrect because market segmentation remains useful across all stages of the Product Life Cycle."}}},{"id":"P1_U3_MCQ_730","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_730","question":"How does the amount of finance available to a business influence its marketing mix?","options":{"A":"It determines whether the business must operate in the public sector.","B":"It limits which promotional methods and distribution channels the business can afford.","C":"It forces every small business to use price skimming.","D":"It eliminates the need to calculate unit production costs."},"correctOption":"B","correctAnswer":"It limits which promotional methods and distribution channels the business can afford.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a small marketing budget prevents a business from affording costly national TV campaigns or opening its own retail store network.","distractor_reasons":{"A":"Incorrect because public-sector status depends on government ownership, not budget size.","B":"Correct selection.","C":"Incorrect because small businesses choose pricing methods based on product and competition, not automatically skimming.","D":"Incorrect because knowing unit costs is always essential for setting profitable prices."}}},{"id":"P1_U3_MCQ_731","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_731","question":"How does the nature of the target market influence a business's marketing mix?","options":{"A":"Target market income, age, and lifestyle dictate suitable pricing, promotion media, and outlets.","B":"Target markets have no effect on product packaging or design.","C":"Every target market prefers buying goods exclusively through wholesalers.","D":"All target markets respond identically to price increases."},"correctOption":"A","correctAnswer":"Target market income, age, and lifestyle dictate suitable pricing, promotion media, and outlets.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the four Ps must match the buying habits, spending power, and media preferences of the chosen customer segment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because packaging and design must appeal directly to the target demographic.","C":"Incorrect because consumers buy from retailers or directly online, not usually from wholesalers.","D":"Incorrect because price sensitivity varies widely across different income and lifestyle groups."}}},{"id":"P1_U3_MCQ_732","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_732","question":"How does a high level of competition in an industry affect a business's marketing strategy?","options":{"A":"The business can safely charge very high prices without promoting its product.","B":"The business has no need to differentiate its product from rivals.","C":"The business must focus on competitive pricing, product differentiation, and effective promotion.","D":"The business should stop conducting market research to save money."},"correctOption":"C","correctAnswer":"The business must focus on competitive pricing, product differentiation, and effective promotion.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because intense competition requires businesses to offer attractive prices, distinct features, and persuasive promotion to win customers.","distractor_reasons":{"A":"Incorrect because charging high prices without promotion in a competitive market will cause customers to switch to rivals.","B":"Incorrect because differentiation is vital when many competitors offer similar products.","C":"Correct selection.","D":"Incorrect because market research is crucial to track competitor moves and customer preferences."}}},{"id":"P1_U3_MCQ_733","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_733","question":"What is the main purpose of government legal controls related to marketing?","options":{"A":"To guarantee that every private business makes a high annual profit.","B":"To prevent small businesses from advertising on the internet.","C":"To force all retailers to charge the exact same price for food items.","D":"To protect consumers from faulty goods, unsafe products, and misleading promotion."},"correctOption":"D","correctAnswer":"To protect consumers from faulty goods, unsafe products, and misleading promotion.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumer protection laws prevent businesses from deceiving buyers with false claims or selling dangerous, defective products.","distractor_reasons":{"A":"Incorrect because governments do not guarantee profits for private businesses.","B":"Incorrect because online advertising is permitted for businesses of all sizes.","C":"Incorrect because businesses are free to set competitive prices unless price controls apply to specific essentials.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_734","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_734","question":"Which marketing practice is prohibited by legal controls against misleading promotion?","options":{"A":"Advertising a jacket as genuine leather when it is actually made of synthetic plastic.","B":"Using colourful photographs on social media to show a product's real features.","C":"Offering a genuine 20% discount on last season's stock.","D":"Stating the accurate country of origin and ingredients on food packaging."},"correctOption":"A","correctAnswer":"Advertising a jacket as genuine leather when it is actually made of synthetic plastic.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumer protection laws make it illegal to give false or deceptive descriptions of a product's materials or capabilities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because truthfully displaying real product features is completely legal.","C":"Incorrect because genuine price reductions are permitted.","D":"Incorrect because accurate labelling complies with consumer protection regulations."}}},{"id":"P1_U3_MCQ_735","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_735","question":"What do consumer protection laws regarding product quality require from businesses?","options":{"A":"Every product sold must be the most expensive brand on the market.","B":"Goods must be safe, free from faults, and fit for the purpose intended by the buyer.","C":"Customers are never entitled to a refund even if an appliance breaks on first use.","D":"Businesses only have to check quality if they export goods overseas."},"correctOption":"B","correctAnswer":"Goods must be safe, free from faults, and fit for the purpose intended by the buyer.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because legal controls require goods to be of satisfactory quality, safe to use, and suitable for their stated purpose.","distractor_reasons":{"A":"Incorrect because low-priced goods are legal as long as they are safe and fit for purpose.","B":"Correct selection.","C":"Incorrect because consumers have legal rights to refunds, repairs, or replacements for faulty goods.","D":"Incorrect because domestic consumer protection laws apply to all sales within a country."}}},{"id":"P1_U3_MCQ_736","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_736","question":"What is the purpose of 'weights and measures' legal controls in marketing?","options":{"A":"To restrict the physical size of retail supermarkets in city centres.","B":"To force manufacturers to use only biodegradable glass packaging.","C":"To prevent businesses from selling underweight goods or using inaccurate weighing scales.","D":"To limit the number of adverts a business can broadcast per hour."},"correctOption":"C","correctAnswer":"To prevent businesses from selling underweight goods or using inaccurate weighing scales.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because weights and measures laws ensure consumers receive the exact weight or volume of product stated on the label.","distractor_reasons":{"A":"Incorrect because store size falls under planning regulations, not weights and measures.","B":"Incorrect because packaging material rules relate to environmental regulations.","C":"Correct selection.","D":"Incorrect because broadcast limits relate to media advertising standards."}}},{"id":"P1_U3_MCQ_737","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_737","question":"Which pricing practice is illegal under legal controls against misleading price reductions?","options":{"A":"Lowering prices during an annual end-of-year clearance sale.","B":"Using competitive pricing to match a rival supermarket's price.","C":"Offering a bulk-buying discount to wholesale customers.","D":"Claiming a product is reduced by '$50 off' when it was never sold at the higher price."},"correctOption":"D","correctAnswer":"Claiming a product is reduced by '$50 off' when it was never sold at the higher price.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because advertising fake discounts based on an inflated, fictitious previous price deceives consumers about true value.","distractor_reasons":{"A":"Incorrect because genuine seasonal clearance reductions are legal.","B":"Incorrect because matching competitor prices is a standard legal pricing method.","C":"Incorrect because offering volume discounts to trade buyers is legal.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_738","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_738","question":"What is a positive effect on a business of complying fully with consumer protection laws?","options":{"A":"It builds customer trust and a strong reputation while avoiding fines and bad publicity.","B":"It completely eliminates all production and quality-testing costs.","C":"It guarantees that no competitor will ever enter the market.","D":"It allows the business to ignore changing consumer preferences."},"correctOption":"A","correctAnswer":"It builds customer trust and a strong reputation while avoiding fines and bad publicity.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reliable, safe products and honest promotion create consumer confidence, repeat sales, and protection from legal penalties.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because meeting legal safety and quality rules usually increases testing and compliance costs.","C":"Incorrect because legal compliance does not prevent rivals from competing.","D":"Incorrect because businesses must still adapt to consumer trends to survive."}}},{"id":"P1_U3_MCQ_739","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_739","question":"What is a negative effect on businesses of strict legal controls related to marketing?","options":{"A":"Consumers lose all confidence in buying manufactured goods.","B":"Higher costs of product safety testing, quality control, and redesigns may reduce profits.","C":"Businesses are prevented from exporting goods to high-income countries.","D":"Employees become less motivated to work safely."},"correctOption":"B","correctAnswer":"Higher costs of product safety testing, quality control, and redesigns may reduce profits.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because complying with safety, labelling, and quality regulations raises business expenses, forcing higher prices or lower profit margins.","distractor_reasons":{"A":"Incorrect because legal protection increases, rather than decreases, consumer confidence.","B":"Correct selection.","C":"Incorrect because meeting strict quality standards often helps businesses qualify to export to high-income markets.","D":"Incorrect because safer products and processes generally improve workplace morale."}}},{"id":"P1_U3_MCQ_740","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_740","question":"What is a major advantage to a business of entering new markets in other countries?","options":{"A":"It eliminates all cultural and language differences between customers.","B":"It removes the need to transport products over long distances.","C":"It increases total potential sales and enables growth when the home market is saturated.","D":"It guarantees that foreign governments will provide free grants."},"correctOption":"C","correctAnswer":"It increases total potential sales and enables growth when the home market is saturated.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because expanding internationally opens access to millions of new consumers, driving revenue growth and economies of scale.","distractor_reasons":{"A":"Incorrect because entering foreign markets introduces cultural and language challenges.","B":"Incorrect because exporting physical goods generally increases transport distances and costs.","C":"Correct selection.","D":"Incorrect because government grants are not guaranteed when entering foreign markets."}}},{"id":"P1_U3_MCQ_741","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_741","question":"How does entering markets in other countries help a business 'spread risk'?","options":{"A":"By ensuring that exchange rates never fluctuate between currencies.","B":"By selling only one identical product in a single town.","C":"By eliminating all legal regulations in every country entered.","D":"By offsetting falling sales during a home-country recession with strong sales in booming foreign economies."},"correctOption":"D","correctAnswer":"By offsetting falling sales during a home-country recession with strong sales in booming foreign economies.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because operating in multiple countries reduces dependence on one domestic economy; if one market slows down, growth elsewhere can compensate.","distractor_reasons":{"A":"Incorrect because international trade exposes a business to exchange rate fluctuations.","B":"Incorrect because relying on one product in one town concentrates risk rather than spreading it.","C":"Incorrect because businesses must obey the local laws of every country they enter.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_742","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_742","question":"Why might a business enter a new foreign market with a product that has reached the maturity stage at home?","options":{"A":"To act as an extension strategy by launching the product where it is still new to consumers.","B":"To avoid paying any wages to foreign distribution workers.","C":"Because mature products never require any adaptation for foreign cultures.","D":"Because domestic consumers are legally barred from buying mature goods."},"correctOption":"A","correctAnswer":"To act as an extension strategy by launching the product where it is still new to consumers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a product that is mature in the domestic market may be completely new in an overseas market, extending its profitable Product Life Cycle.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because workers involved in foreign distribution must still be paid.","C":"Incorrect because products often need adaptation to suit local tastes and laws abroad.","D":"Incorrect because mature products remain legal to sell domestically."}}},{"id":"P1_U3_MCQ_743","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_743","question":"Why are 'cultural differences' a disadvantage or barrier when entering new markets in other countries?","options":{"A":"Foreign consumers never buy any imported products regardless of price.","B":"Differences in religion, diet, language, and social norms may cause unadapted products or adverts to fail.","C":"Cultural differences prevent businesses from using the internet for market research.","D":"All countries share identical religious holidays and dress codes."},"correctOption":"B","correctAnswer":"Differences in religion, diet, language, and social norms may cause unadapted products or adverts to fail.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because failing to respect local beliefs, languages, or dietary customs can offend consumers and lead to product rejection.","distractor_reasons":{"A":"Incorrect because foreign consumers regularly purchase imported goods that fit their needs.","B":"Correct selection.","C":"Incorrect because online market research can still be conducted across countries.","D":"Incorrect because cultural traditions, religions, and social norms vary widely around the world."}}},{"id":"P1_U3_MCQ_744","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_744","question":"How can a business overcome cultural differences when entering a foreign market?","options":{"A":"By forcing foreign consumers to adopt the home country's traditional diet.","B":"By refusing to translate product labels or advertisements into the local language.","C":"By adapting product ingredients, packaging, and promotional images to match local customs.","D":"By setting prices much higher than local consumers can afford."},"correctOption":"C","correctAnswer":"By adapting product ingredients, packaging, and promotional images to match local customs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because tailoring the marketing mix—such as modifying food recipes or advertising imagery—ensures cultural acceptability.","distractor_reasons":{"A":"Incorrect because businesses must adapt to consumer preferences rather than forcing change.","B":"Incorrect because untranslated labels hinder sales and may break local laws.","C":"Correct selection.","D":"Incorrect because unaffordable pricing leads to failure in the new market."}}},{"id":"P1_U3_MCQ_745","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_745","question":"How does 'lack of knowledge' create a barrier when entering a market in another country?","options":{"A":"Managers may not know how to operate their own domestic factory machines.","B":"It prevents the business from calculating its domestic fixed costs.","C":"It guarantees that competitors in the foreign country will go bankrupt.","D":"Unfamiliarity with local incomes, consumer tastes, and competitors can lead to an unsuitable marketing mix."},"correctOption":"D","correctAnswer":"Unfamiliarity with local incomes, consumer tastes, and competitors can lead to an unsuitable marketing mix.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because without understanding local spending power, demographics, and rivals, a business may set the wrong price or choose ineffective promotion.","distractor_reasons":{"A":"Incorrect because lack of knowledge in international expansion refers to unfamiliarity with the foreign market.","B":"Incorrect because domestic fixed costs are known internally.","C":"Incorrect because lack of local knowledge weakens the entering firm rather than local rivals.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_746","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_746","question":"Which action helps a business overcome a lack of local knowledge when entering a foreign market?","options":{"A":"Conducting detailed local market research or hiring a local agent or joint venture partner.","B":"Launching the exact domestic marketing mix immediately without any research.","C":"Stopping all communication with distributors in the target country.","D":"Assuming that average consumer incomes are identical in every country."},"correctOption":"A","correctAnswer":"Conducting detailed local market research or hiring a local agent or joint venture partner.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because local research, agents, or joint venture partners provide vital insights into consumer behaviour, regulations, and distribution channels.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because launching blindly without research risks costly marketing errors.","C":"Incorrect because strong communication with local distributors is essential.","D":"Incorrect because income levels vary significantly between countries."}}},{"id":"P1_U3_MCQ_747","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_747","question":"How can differing 'legal requirements' act as a disadvantage when entering new markets in other countries?","options":{"A":"Foreign laws always allow businesses to sell dangerous products without testing.","B":"Different safety standards, labelling rules, or advertising restrictions require costly product changes.","C":"Legal requirements eliminate the need to pay import tariffs.","D":"Foreign governments ban all businesses from using quality assurance."},"correctOption":"B","correctAnswer":"Different safety standards, labelling rules, or advertising restrictions require costly product changes.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because foreign markets may enforce stricter electrical safety laws, packaging rules, or content bans, raising compliance and adaptation costs.","distractor_reasons":{"A":"Incorrect because many foreign countries enforce strict consumer safety regulations.","B":"Correct selection.","C":"Incorrect because tariffs are trade taxes separate from product and marketing regulations.","D":"Incorrect because governments encourage quality assurance to protect consumers."}}},{"id":"P1_U3_MCQ_748","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_748","question":"Why can entering new markets in other countries reduce a business's short-term profitability?","options":{"A":"Total potential market size shrinks whenever a business exports.","B":"Economies of scale are impossible to achieve when output rises.","C":"High upfront costs of foreign market research, product adaptation, transport, and promotion.","D":"Foreign consumers refuse to pay for any goods using electronic banking."},"correctOption":"C","correctAnswer":"High upfront costs of foreign market research, product adaptation, transport, and promotion.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because researching unfamiliar markets, modifying products for local laws/cultures, and establishing overseas distribution require heavy initial investment.","distractor_reasons":{"A":"Incorrect because entering foreign markets expands total market size.","B":"Incorrect because higher international sales volume usually increases economies of scale.","C":"Correct selection.","D":"Incorrect because electronic payments are widely used globally."}}},{"id":"P1_U3_MCQ_749","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_749","question":"Why is selling solely through an e-commerce website sometimes insufficient when entering a foreign market?","options":{"A":"Websites cannot be accessed by internet users outside the home country.","B":"Online shopping is illegal in all developing economies.","C":"E-commerce websites cannot display prices in foreign currencies.","D":"Perishable foods, bulky items, and personal services still require physical local distribution or outlets."},"correctOption":"D","correctAnswer":"Perishable foods, bulky items, and personal services still require physical local distribution or outlets.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because products that spoil quickly, are heavy to ship long distances, or require face-to-face delivery cannot rely purely on cross-border parcel shipping.","distractor_reasons":{"A":"Incorrect because websites are globally accessible over the internet.","B":"Incorrect because e-commerce operates legally in both developing and developed economies.","C":"Incorrect because websites easily display multiple currencies.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_750","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_750","question":"What determines whether a business's chosen marketing mix will be successful?","options":{"A":"How well Product, Price, Place, and Promotion align with the marketing objective and target market.","B":"Whether the business spends the maximum possible amount on billboard advertising.","C":"Whether the business uses cost-plus pricing for every single item it sells.","D":"Whether the business avoids all forms of secondary market research."},"correctOption":"A","correctAnswer":"How well Product, Price, Place, and Promotion align with the marketing objective and target market.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an effective marketing strategy requires all four Ps to work harmoniously together to satisfy the target segment and achieve the stated objective.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because billboards may be unsuitable or unaffordable depending on the target market and budget.","C":"Incorrect because the best pricing method depends on the product, competition, and market conditions.","D":"Incorrect because secondary research is a valuable, cost-effective input into marketing decisions."}}},{"id":"P1_U3_MCQ_751","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_751","question":"What is meant by 'building customer relationships' as a role of marketing?","options":{"A":"Communicating regularly with buyers to understand feedback and encourage long-term loyalty.","B":"Forcing retail shops to sign exclusive supply agreements with the manufacturer.","C":"Reducing after-sales customer service staff to lower fixed administrative overheads.","D":"Setting identical prices for every product sold across all international markets."},"correctOption":"A","correctAnswer":"Communicating regularly with buyers to understand feedback and encourage long-term loyalty.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because building customer relationships involves ongoing two-way communication and good service so customers feel valued and return repeatedly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because exclusive supply deals relate to distribution agreements rather than customer relationships.","C":"Incorrect because cutting customer support weakens relationships and damages loyalty.","D":"Incorrect because uniform global pricing ignores local market needs and does not build relationships."}}},{"id":"P1_U3_MCQ_752","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_752","question":"Why is it more cost-effective for a business to retain existing loyal customers than to constantly attract new ones?","options":{"A":"Existing loyal customers never complain even if product quality falls.","B":"Marketing and promotional costs per sale are lower for repeat buyers than for acquiring new buyers.","C":"Loyal customers are legally required to pay higher prices than first-time shoppers.","D":"Retaining existing customers eliminates all variable manufacturing expenses."},"correctOption":"B","correctAnswer":"Marketing and promotional costs per sale are lower for repeat buyers than for acquiring new buyers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because repeat buyers already trust the brand, meaning less advertising expenditure is needed to persuade them to purchase again.","distractor_reasons":{"A":"Incorrect because loyal customers still expect consistent quality and will leave if standards drop.","B":"Correct selection.","C":"Incorrect because loyal buyers often receive loyalty rewards rather than higher prices.","D":"Incorrect because variable production costs still occur for every unit sold."}}},{"id":"P1_U3_MCQ_753","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_753","question":"Which situation best demonstrates a business failing to respond to the power of changing customer needs?","options":{"A":"A smartphone maker launching a model with an improved camera and longer battery life.","B":"A supermarket adding a range of plant-based ready meals after noticing rising vegan demand.","C":"A DVD rental store refusing to offer online streaming despite widespread broadband adoption.","D":"A sportswear brand using recycled ocean plastics to appeal to eco-conscious buyers."},"correctOption":"C","correctAnswer":"A DVD rental store refusing to offer online streaming despite widespread broadband adoption.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because clinging to physical DVD rentals while consumers shift to digital streaming ignores technological and taste changes, leading to business failure.","distractor_reasons":{"A":"Incorrect because upgrading phone features responds directly to consumer expectations.","B":"Incorrect because introducing plant-based meals adapts to changing dietary trends.","C":"Correct selection.","D":"Incorrect because using recycled materials responds to growing environmental awareness."}}},{"id":"P1_U3_MCQ_754","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_754","question":"How have improvements in international transport contributed to increased competition in many markets?","options":{"A":"They have prevented domestic firms from exporting goods to neighbouring countries.","B":"They have increased import tariffs charged by governments at seaports.","C":"They have forced consumers to buy only perishable local produce.","D":"They have lowered the cost and time of shipping goods globally, allowing foreign rivals to enter domestic markets."},"correctOption":"D","correctAnswer":"They have lowered the cost and time of shipping goods globally, allowing foreign rivals to enter domestic markets.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because faster, cheaper container shipping and air freight enable overseas manufacturers to sell competitively in domestic markets.","distractor_reasons":{"A":"Incorrect because better transport makes exporting easier for domestic firms too.","B":"Incorrect because transport efficiency is separate from government tariff rates.","C":"Incorrect because refrigerated transport actually allows perishable goods to be traded internationally.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_755","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_755","question":"Why does keeping production costs low help a business respond to increased competition?","options":{"A":"It allows the business to offer competitive prices while still maintaining healthy profit margins.","B":"It guarantees that consumer tastes will never change in the future.","C":"It eliminates the need to conduct any primary or secondary market research.","D":"It ensures that the business becomes a legal monopoly in its industry."},"correctOption":"A","correctAnswer":"It allows the business to offer competitive prices while still maintaining healthy profit margins.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lower unit costs enable a firm to match or undercut rivals' prices without sacrificing profitability.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because internal cost control does not stop external consumer preferences from evolving.","C":"Incorrect because market research is still needed to monitor rivals and customers.","D":"Incorrect because low costs help a firm compete, rather than granting a legal monopoly."}}},{"id":"P1_U3_MCQ_756","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_756","question":"A local bakery faces falling bread sales because a large supermarket opened nearby selling cheaper loaves. Which response best uses product improvement to stay competitive?","options":{"A":"Closing the bakery early every afternoon to save on electricity bills.","B":"Introducing freshly baked artisan sourdough and gluten-free specialty breads.","C":"Stopping all social media posts and removing the shop sign outside.","D":"Buying cheaper, lower-quality flour while keeping bread prices unchanged."},"correctOption":"B","correctAnswer":"Introducing freshly baked artisan sourdough and gluten-free specialty breads.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because upgrading the product range with unique, high-quality specialty loaves differentiates the bakery from standard supermarket bread.","distractor_reasons":{"A":"Incorrect because shorter opening hours reduce convenience and sales further.","B":"Correct selection.","C":"Incorrect because reducing visibility and promotion will lose more customers.","D":"Incorrect because lowering quality for the same price drives customers away."}}},{"id":"P1_U3_MCQ_757","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_757","question":"Which product is most likely to be sold in a mass market?","options":{"A":"Hand-built luxury sports cars costing $400,000 each.","B":"Custom-made orthodontic braces fitted for individual patients.","C":"Standardised everyday toothpaste sold in supermarkets nationwide.","D":"Left-handed professional concert harps crafted to order."},"correctOption":"C","correctAnswer":"Standardised everyday toothpaste sold in supermarkets nationwide.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because everyday toothpaste is a standardised product with huge, broad appeal across almost the entire population.","distractor_reasons":{"A":"Incorrect because ultra-expensive luxury sports cars serve a small high-income niche.","B":"Incorrect because custom medical items are tailored to individual needs rather than mass-produced.","C":"Correct selection.","D":"Incorrect because specialised instruments for left-handed musicians represent a tiny niche market."}}},{"id":"P1_U3_MCQ_758","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_758","question":"Which business is operating in a niche market?","options":{"A":"A global soft drinks manufacturer selling cola in 150 countries.","B":"A national supermarket chain selling everyday groceries to millions of households.","C":"A mass-market clothing retailer selling basic white cotton T-shirts.","D":"A specialist tailor making waterproof hiking coats exclusively for mountain rescue teams."},"correctOption":"D","correctAnswer":"A specialist tailor making waterproof hiking coats exclusively for mountain rescue teams.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because mountain rescue gear serves a very small, specialised segment of the outdoor clothing market with specific technical requirements.","distractor_reasons":{"A":"Incorrect because global cola sales represent a classic mass market.","B":"Incorrect because nationwide grocery retailing serves a broad mass market.","C":"Incorrect because basic cotton T-shirts appeal to the general mass market.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_759","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_759","question":"Why can businesses operating in a niche market often charge higher profit margins per unit than mass-market firms?","options":{"A":"Customers have specific needs that few rivals satisfy and are willing to pay more for specialised products.","B":"Niche businesses achieve the highest possible purchasing economies of scale.","C":"Government laws prevent niche businesses from offering any price discounts.","D":"Niche businesses never have to pay for raw materials or skilled labour."},"correctOption":"A","correctAnswer":"Customers have specific needs that few rivals satisfy and are willing to pay more for specialised products.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because specialised products tailored to distinct needs face less direct competition, allowing higher prices and profit margins per unit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because low sales volumes in niche markets limit economies of scale.","C":"Incorrect because niche firms are free to set their own prices and discounts.","D":"Incorrect because niche producers often use expensive specialist materials and skilled labour."}}},{"id":"P1_U3_MCQ_760","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_760","question":"What happens if a niche market grows rapidly and becomes highly profitable?","options":{"A":"The original niche firm is guaranteed a permanent legal monopoly.","B":"Larger mass-market businesses may enter the segment and threaten the small niche firm.","C":"Unit production costs automatically rise to infinity.","D":"Consumers stop buying the product because it is too popular."},"correctOption":"B","correctAnswer":"Larger mass-market businesses may enter the segment and threaten the small niche firm.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because if a niche grows large enough to offer high sales volumes, big corporations with economies of scale may enter and outcompete the small pioneer.","distractor_reasons":{"A":"Incorrect because unless protected by patents, profitable niches attract new entrants.","B":"Correct selection.","C":"Incorrect because higher output usually lowers average unit costs through economies of scale.","D":"Incorrect because market growth reflects rising consumer demand."}}},{"id":"P1_U3_MCQ_761","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_761","question":"Why is operating in a mass market often less risky for product diversification than relying on a single niche market?","options":{"A":"Mass-market businesses never face any competition from rival brands.","B":"Mass markets require zero spending on national advertising.","C":"Large customer numbers and multiple product variations spread risk across wider demand.","D":"Mass-market consumers always buy products regardless of price or quality."},"correctOption":"C","correctAnswer":"Large customer numbers and multiple product variations spread risk across wider demand.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because mass-market firms serve huge customer bases and can sell several product lines, whereas a niche firm depends heavily on one small segment.","distractor_reasons":{"A":"Incorrect because mass markets typically involve intense competition.","B":"Incorrect because mass-market firms usually spend heavily on advertising.","C":"Correct selection.","D":"Incorrect because mass-market buyers are very sensitive to price and quality."}}},{"id":"P1_U3_MCQ_762","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_762","question":"What does segmenting a market by 'socio-economic group' involve?","options":{"A":"Dividing consumers solely by whether they live in coastal or inland towns.","B":"Grouping buyers strictly according to their favourite sports teams.","C":"Classifying customers based only on their biological age.","D":"Grouping consumers according to their occupation, education, and social status."},"correctOption":"D","correctAnswer":"Grouping consumers according to their occupation, education, and social status.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because socio-economic segmentation categorises people by job type, qualifications, and income/social class, which strongly influence buying patterns.","distractor_reasons":{"A":"Incorrect because coastal versus inland living is geographic/location segmentation.","B":"Incorrect because hobbies and interests relate to lifestyle segmentation.","C":"Incorrect because age brackets represent age segmentation.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_763","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_763","question":"A computer manufacturer sells basic laptops for home students and high-specification workstations for professional video editors. Which segmentation method is being used?","options":{"A":"Use of the product.","B":"Gender segmentation.","C":"Climate segmentation.","D":"Age segmentation."},"correctOption":"A","correctAnswer":"Use of the product.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the manufacturer divides buyers based on how they intend to use the computer (everyday study versus heavy professional editing).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because laptops are not divided into male and female versions here.","C":"Incorrect because climate does not determine student versus video-editing specifications.","D":"Incorrect because the distinction is based on task/usage rather than age."}}},{"id":"P1_U3_MCQ_764","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_764","question":"Which segmentation method is most appropriate for a company selling luxury winter ski holidays?","options":{"A":"Gender and household size.","B":"Income and lifestyle.","C":"Gender and occupation only.","D":"Local postal code only."},"correctOption":"B","correctAnswer":"Income and lifestyle.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because luxury ski trips require high disposable income and appeal to consumers with an active, winter-sports lifestyle.","distractor_reasons":{"A":"Incorrect because ski holidays are enjoyed by all genders regardless of family size.","B":"Correct selection.","C":"Incorrect because occupation and gender alone do not capture interest in skiing or ability to pay.","D":"Incorrect because postal code alone ignores whether residents can afford or enjoy skiing."}}},{"id":"P1_U3_MCQ_765","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_765","question":"How does market segmentation help a business identify new market opportunities?","options":{"A":"By highlighting specific consumer sub-groups whose needs are not currently met by competitors.","B":"By forcing all consumers in the country to buy the exact same product design.","C":"By eliminating the need to calculate profit margins on new product launches.","D":"By reducing the total number of employees required in the finance department."},"correctOption":"A","correctAnswer":"By highlighting specific consumer sub-groups whose needs are not currently met by competitors.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because analysing individual segments often reveals underserved gaps in the market where new products can be profitably launched.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because segmentation involves tailoring products to distinct groups rather than selling one uniform item.","C":"Incorrect because financial profitability analysis is always required before launching products.","D":"Incorrect because segmentation is a marketing tool unrelated to finance staffing levels."}}},{"id":"P1_U3_MCQ_766","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_766","question":"How does market segmentation make promotional spending more cost-effective?","options":{"A":"It allows a business to target adverts specifically at media channels used by its chosen segment.","B":"It requires television stations to broadcast adverts free of charge.","C":"It eliminates the need to design attractive promotional messages.","D":"It ensures every person in the country buys the advertised product."},"correctOption":"A","correctAnswer":"It allows a business to target adverts specifically at media channels used by its chosen segment.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because knowing who the target buyers are avoids wasting money advertising to people unlikely to purchase the product.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because media channels still charge standard advertising rates.","C":"Incorrect because tailored, persuasive messaging is still vital.","D":"Incorrect because segmented promotion aims at a specific target group rather than the entire population."}}},{"id":"P1_U3_MCQ_767","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_767","question":"What is a potential disadvantage to a business of dividing its market into too many small segments?","options":{"A":"Customers receive products that match their exact needs too closely.","B":"Higher production and marketing costs from creating separate product ranges and adverts for each segment.","C":"Total sales revenue falls to zero because segments cannot buy online.","D":"Competitors are legally prevented from entering any of the segments."},"correctOption":"B","correctAnswer":"Higher production and marketing costs from creating separate product ranges and adverts for each segment.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because producing multiple tailored versions and running separate promotional campaigns reduces economies of scale and increases costs.","distractor_reasons":{"A":"Incorrect because meeting customer needs closely is a benefit, not a disadvantage.","B":"Correct selection.","C":"Incorrect because segmented products can still be sold online and in stores.","D":"Incorrect because rivals can compete in any segment."}}},{"id":"P1_U3_MCQ_768","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_768","question":"A toy manufacturer wants to launch a new educational board game. Which primary segmentation basis should it use first?","options":{"A":"Location (urban vs rural).","B":"Occupation of the child.","C":"Age of the children.","D":"Car ownership."},"correctOption":"C","correctAnswer":"Age of the children.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because children's reading ability, interests, and safety requirements vary sharply by age bracket.","distractor_reasons":{"A":"Incorrect because children in both urban and rural areas play board games.","B":"Incorrect because children do not have occupations.","C":"Correct selection.","D":"Incorrect because car ownership is irrelevant to educational board games."}}},{"id":"P1_U3_MCQ_769","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_769","question":"A sportswear company sells affordable running shoes under one brand and high-end carbon-plated marathon shoes under another. What is the main benefit of targeting both income segments?","options":{"A":"It eliminates all competition in the athletic footwear industry.","B":"It guarantees identical profit margins on every pair of shoes sold.","C":"It prevents the company from ever needing to advertise.","D":"It maximises total market coverage and sales across both budget and premium buyers."},"correctOption":"D","correctAnswer":"It maximises total market coverage and sales across both budget and premium buyers.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because offering distinct tiers captures sales from price-sensitive runners as well as high-income enthusiasts.","distractor_reasons":{"A":"Incorrect because rival sportswear brands still compete in both tiers.","B":"Incorrect because premium shoes typically earn higher profit margins than budget shoes.","C":"Incorrect because both brands still require promotion.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_770","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_770","question":"Which formula correctly calculates a business's market share?","options":{"A":"(Business sales / Total market sales) x 100","B":"(Total market sales / Business sales) x 100","C":"(Gross profit / Sales revenue) x 100","D":"(Fixed costs / Contribution per unit)"},"correctOption":"A","correctAnswer":"(Business sales / Total market sales) x 100","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because market share expresses one firm's sales as a percentage of total sales in the entire market.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because dividing total market sales by business sales inverts the fraction.","C":"Incorrect because this formula calculates gross profit margin.","D":"Incorrect because this formula calculates break-even output."}}},{"id":"P1_U3_MCQ_771","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_771","question":"Total annual sales in the national bottled water market are $50 million. Company X achieves annual sales of $10 million. What is Company X's market share?","options":{"A":"5%","B":"20%","C":"40%","D":"50%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ($10 million / $50 million) x 100 = 20%.","distractor_reasons":{"A":"Incorrect because $50m / $10m = 5, not 5%.","B":"Correct selection.","C":"Incorrect because 40% would require $20 million in sales.","D":"Incorrect because 50% would require $25 million in sales."}}},{"id":"P1_U3_MCQ_772","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_772","question":"Why can a business's sales revenue increase while its market share decreases at the same time?","options":{"A":"Because the business lowered its selling prices to zero.","B":"Because total market sales fell faster than the business's sales.","C":"Because total market sales grew at a faster percentage rate than the business's own sales.","D":"Because the business stopped recording cash transactions."},"correctOption":"C","correctAnswer":"Because total market sales grew at a faster percentage rate than the business's own sales.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because if the overall market expands by 30% while the business's sales only grow by 10%, its percentage slice of the market shrinks.","distractor_reasons":{"A":"Incorrect because zero prices would reduce sales revenue to zero.","B":"Incorrect because if total market sales fell while the business's sales rose, market share would increase.","C":"Correct selection.","D":"Incorrect because accounting omissions do not explain real market growth dynamics."}}},{"id":"P1_U3_MCQ_773","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_773","question":"How does a fall in average consumer incomes during an economic recession affect spending patterns?","options":{"A":"Demand rises sharply for luxury yachts and designer jewellery.","B":"Consumers stop buying basic food and household utilities.","C":"Businesses switch from discount pricing to high price skimming.","D":"Consumers switch from expensive branded goods to cheaper own-label or value alternatives."},"correctOption":"D","correctAnswer":"Consumers switch from expensive branded goods to cheaper own-label or value alternatives.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lower disposable incomes make shoppers more price-sensitive, increasing demand for budget and supermarket own-brand items.","distractor_reasons":{"A":"Incorrect because demand for luxury items falls when incomes decline.","B":"Incorrect because basic necessities remain essential even during a recession.","C":"Incorrect because businesses usually lower prices or offer promotions during recessions.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_774","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_774","question":"Which demographic trend in many developed countries has created growing markets for retirement villages, hearing aids, and cruise holidays?","options":{"A":"An ageing population with a larger proportion of retired consumers.","B":"A rapid increase in the birth rate of newborn babies.","C":"A sharp decline in life expectancy across all regions.","D":"A decrease in the number of people aged over 65."},"correctOption":"A","correctAnswer":"An ageing population with a larger proportion of retired consumers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because longer life expectancy and lower birth rates expand the older age segment, raising demand for retirement-related goods and services.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher birth rates boost demand for baby products rather than retirement villages.","C":"Incorrect because falling life expectancy would shrink the elderly population.","D":"Incorrect because fewer over-65s would reduce demand for retirement services."}}},{"id":"P1_U3_MCQ_775","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_775","question":"What is the main danger for a business that relies purely on a product-oriented approach in a fast-changing consumer market?","options":{"A":"It will spend too much money listening to customer focus groups.","B":"It risks producing high-quality goods that consumers no longer want to buy.","C":"It will achieve too many economies of scale too quickly.","D":"It will be forced to lower its prices every single day."},"correctOption":"B","correctAnswer":"It risks producing high-quality goods that consumers no longer want to buy.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because focusing solely on the product without researching changing customer preferences can result in unsold stock when tastes shift.","distractor_reasons":{"A":"Incorrect because product-oriented firms do very little customer research.","B":"Correct selection.","C":"Incorrect because low demand prevents a firm from achieving high-volume economies of scale.","D":"Incorrect because daily price changes relate to dynamic pricing, not product orientation."}}},{"id":"P1_U3_MCQ_776","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_776","question":"Which information can a market-oriented business obtain by conducting market research before launching a new snack bar?","options":{"A":"The exact future interest rate set by the central bank in five years.","B":"A legal guarantee that no rival company will ever copy the recipe.","C":"Preferred flavours, suitable packaging sizes, and the price consumers are willing to pay.","D":"The personal bank account balances of individual factory workers."},"correctOption":"C","correctAnswer":"Preferred flavours, suitable packaging sizes, and the price consumers are willing to pay.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market research investigates customer preferences regarding product features, pricing, and packaging prior to launch.","distractor_reasons":{"A":"Incorrect because central bank interest rates are macroeconomic policies, not market research data.","B":"Incorrect because market research cannot legally block competitors.","C":"Correct selection.","D":"Incorrect because employee personal finances are private and irrelevant to product demand."}}},{"id":"P1_U3_MCQ_777","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_777","question":"What is the difference between quantitative and qualitative market research data?","options":{"A":"Quantitative data is collected only from secondary sources, whereas qualitative data is always primary.","B":"Quantitative data is gathered by the government, whereas qualitative data is gathered by private firms.","C":"Quantitative data is always unbiased, whereas qualitative data is always inaccurate.","D":"Quantitative data consists of numerical statistics, whereas qualitative data explores opinions and reasons."},"correctOption":"D","correctAnswer":"Quantitative data consists of numerical statistics, whereas qualitative data explores opinions and reasons.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because quantitative research answers 'how many' or 'what percentage' in numbers, while qualitative research explains 'why' consumers feel a certain way.","distractor_reasons":{"A":"Incorrect because both primary and secondary research can produce quantitative and qualitative data.","B":"Incorrect because private businesses collect both types of data.","C":"Incorrect because quantitative surveys can also be biased if poorly designed.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_778","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_778","question":"Which of the following is an example of an internal secondary research source?","options":{"A":"The business's own past sales records and customer loyalty card purchase data.","B":"A national population census published by the government statistics office.","C":"An online survey sent out to 500 potential new customers yesterday.","D":"A trade association report sold to all companies in the industry."},"correctOption":"A","correctAnswer":"The business's own past sales records and customer loyalty card purchase data.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the company's own historical sales figures and customer records already exist inside the business.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because government census data is an external secondary source.","C":"Incorrect because a newly sent online survey collects original primary data.","D":"Incorrect because a trade association report is an external secondary source."}}},{"id":"P1_U3_MCQ_779","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_779","question":"Why do businesses often carry out secondary market research before conducting primary research?","options":{"A":"Because primary research is illegal unless secondary research is completed first.","B":"Because secondary data is quick and cheap to gather, helping narrow down what primary research is still needed.","C":"Because secondary data is always more accurate and up to date than primary data.","D":"Because secondary research requires interviewing thousands of shoppers in person."},"correctOption":"B","correctAnswer":"Because secondary data is quick and cheap to gather, helping narrow down what primary research is still needed.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because checking existing secondary data first avoids wasting money collecting information that has already been published.","distractor_reasons":{"A":"Incorrect because there is no legal requirement to do secondary research first.","B":"Correct selection.","C":"Incorrect because secondary data is often older and less specific than primary research.","D":"Incorrect because interviewing shoppers is primary field research."}}},{"id":"P1_U3_MCQ_780","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_780","question":"What is a major advantage of online surveys compared to postal questionnaires?","options":{"A":"Online surveys reach people who have no access to the internet.","B":"Online surveys guarantee a 100% response rate from every recipient.","C":"Responses are collected quickly at very low cost and analysed automatically by software.","D":"An interviewer sits beside every respondent to clarify confusing questions."},"correctOption":"C","correctAnswer":"Responses are collected quickly at very low cost and analysed automatically by software.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because online surveys avoid printing and postage expenses and instantly tabulate results into charts and tables.","distractor_reasons":{"A":"Incorrect because offline populations cannot complete online surveys.","B":"Incorrect because many people ignore online survey links.","C":"Correct selection.","D":"Incorrect because online surveys are self-completed without a live interviewer."}}},{"id":"P1_U3_MCQ_781","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_781","question":"Why might a postal questionnaire produce a biased sample of opinions?","options":{"A":"Because postal questionnaires can only be answered by teenagers.","B":"Because postal mail is delivered instantaneously within two seconds.","C":"Because interviewers force respondents to choose Option A.","D":"Because low response rates mean only people with very strong views or spare time reply."},"correctOption":"D","correctAnswer":"Because low response rates mean only people with very strong views or spare time reply.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because busy people often throw away postal surveys, leaving a self-selected group of respondents that may not reflect the whole market.","distractor_reasons":{"A":"Incorrect because postal questionnaires are usually sent to adult households.","B":"Incorrect because postal surveys are slow to send and receive back.","C":"Incorrect because there is no interviewer present with postal surveys.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_782","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_782","question":"Which primary research method is best suited for obtaining deep, qualitative insights into how target customers react to three new TV advert concepts?","options":{"A":"A focus group.","B":"Counting store footfall by observation.","C":"Reading government census tables.","D":"A 2-question postal postcard."},"correctOption":"A","correctAnswer":"A focus group.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a focus group allows participants to watch the adverts and discuss their emotional reactions and suggestions in detail.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because observation only counts people and cannot measure reactions to draft adverts.","C":"Incorrect because government census data is secondary demographic data.","D":"Incorrect because a short postal card cannot show video adverts or capture rich discussion."}}},{"id":"P1_U3_MCQ_783","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_783","question":"A supermarket manager uses CCTV footage to track which aisles shoppers visit most frequently and where they pause. Which research method is this?","options":{"A":"Quota sampling.","B":"Observation.","C":"Secondary desk research.","D":"Postal survey."},"correctOption":"B","correctAnswer":"Observation.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because watching and recording shoppers' actual movements without questioning them is primary observation.","distractor_reasons":{"A":"Incorrect because quota sampling is a method of choosing people to question.","B":"Correct selection.","C":"Incorrect because recording live shopper movement generates new primary data.","D":"Incorrect because no written questionnaire is mailed to shoppers."}}},{"id":"P1_U3_MCQ_784","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_784","question":"What is a major advantage of observation over questionnaires in market research?","options":{"A":"It reveals the exact household income of every shopper.","B":"It explains why a customer prefers one brand over another.","C":"It records what consumers actually do rather than what they claim they do.","D":"It is the best method for testing ideas for products that do not exist yet."},"correctOption":"C","correctAnswer":"It records what consumers actually do rather than what they claim they do.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because respondents in surveys sometimes give inaccurate or socially desirable answers, whereas observation captures real behaviour.","distractor_reasons":{"A":"Incorrect because watching shoppers does not reveal their private income.","B":"Incorrect because observation cannot uncover underlying motives without asking questions.","C":"Correct selection.","D":"Incorrect because consumers cannot be observed interacting with a product that has not been made yet."}}},{"id":"P1_U3_MCQ_785","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_785","question":"Why do market researchers use sampling instead of interviewing the entire population (a census)?","options":{"A":"Because interviewing everyone in a target market is usually too expensive and time-consuming.","B":"Because random samples always give more accurate results than surveying 100% of the population.","C":"Because data protection laws forbid businesses from interviewing more than 50 people.","D":"Because sampling eliminates the need to analyse survey answers."},"correctOption":"A","correctAnswer":"Because interviewing everyone in a target market is usually too expensive and time-consuming.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because surveying millions of potential buyers is impractical and costly, so a representative sample provides timely insights at manageable cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a full census is more accurate than a sample, though far costlier.","C":"Incorrect because there is no 50-person legal limit on market research.","D":"Incorrect because sample data still requires careful statistical analysis."}}},{"id":"P1_U3_MCQ_786","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_786","question":"What is a key advantage of random sampling?","options":{"A":"Researchers can deliberately choose only friends and family to save time.","B":"It reduces selection bias because every member of the target population has an equal chance of being chosen.","C":"It guarantees that exact age and gender proportions are matched without a population list.","D":"It requires no list or database of the target population."},"correctOption":"B","correctAnswer":"It reduces selection bias because every member of the target population has an equal chance of being chosen.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because pure random selection removes interviewer bias in choosing who gets surveyed.","distractor_reasons":{"A":"Incorrect because choosing friends and family is convenience sampling and heavily biased.","B":"Correct selection.","C":"Incorrect because matching exact demographic proportions without a full list describes quota sampling.","D":"Incorrect because true random sampling usually requires a sampling frame (list) of the population."}}},{"id":"P1_U3_MCQ_787","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_787","question":"What is a potential limitation of random sampling?","options":{"A":"Interviewers always pick only wealthy consumers.","B":"It can only be used for secondary desk research.","C":"By pure chance, a small random sample might over-represent one demographic group.","D":"It is impossible to conduct using computer software."},"correctOption":"C","correctAnswer":"By pure chance, a small random sample might over-represent one demographic group.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because pure chance selection does not guarantee demographic balance, especially if the sample size is small.","distractor_reasons":{"A":"Incorrect because every individual has an equal chance in random sampling.","B":"Incorrect because random sampling is a primary research sampling method.","C":"Correct selection.","D":"Incorrect because computers are widely used to generate random samples."}}},{"id":"P1_U3_MCQ_788","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_788","question":"A cosmetics company instructs interviewers in a shopping mall to survey 100 women aged 18–25, 100 women aged 26–40, and 100 women aged over 40. Which sampling method is being used?","options":{"A":"Random sampling.","B":"Census sampling.","C":"Secondary sampling.","D":"Quota sampling."},"correctOption":"D","correctAnswer":"Quota sampling.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because interviewers are given fixed targets (quotas) of respondents sharing specific gender and age characteristics.","distractor_reasons":{"A":"Incorrect because respondents are not chosen purely at random from a full population list.","B":"Incorrect because a census surveys the entire population rather than 300 shoppers.","C":"Incorrect because this is original primary research.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_789","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_789","question":"What is a weakness of quota sampling compared to random sampling?","options":{"A":"Interviewers choose who to approach within each quota, which can introduce human selection bias.","B":"It prevents researchers from collecting data from different age groups.","C":"It requires a complete list of every citizen in the country.","D":"It takes much longer to complete than surveying an entire country."},"correctOption":"A","correctAnswer":"Interviewers choose who to approach within each quota, which can introduce human selection bias.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because interviewers may approach friendly-looking or easily accessible people to fill their quotas, creating selection bias.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because quota sampling specifically ensures multiple age groups are included.","C":"Incorrect because not needing a full population list is actually an advantage of quota sampling.","D":"Incorrect because quota sampling is much faster than a full census."}}},{"id":"P1_U3_MCQ_790","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_790","question":"Why is the following questionnaire question poorly written: 'Don't you agree that our delicious new fruit juice is better than sugary sodas?'","options":{"A":"It is too short for respondents to read.","B":"It is a leading question that pushes respondents toward a positive answer, biasing the results.","C":"It asks for too much confidential financial information.","D":"It can only be answered using secondary government data."},"correctOption":"B","correctAnswer":"It is a leading question that pushes respondents toward a positive answer, biasing the results.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because words like 'Don't you agree' and 'delicious' steer respondents to agree, making the survey data unreliable.","distractor_reasons":{"A":"Incorrect because question length is not the flaw here.","B":"Correct selection.","C":"Incorrect because the question asks about drink preference, not personal finances.","D":"Incorrect because this is a primary consumer survey question."}}},{"id":"P1_U3_MCQ_791","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_791","question":"A business surveys 20 people outside a luxury golf club to estimate national demand for a new budget commuter bicycle. Why will the research results likely be inaccurate?","options":{"A":"The sample size is too small and unrepresentative of typical budget bicycle commuters.","B":"Golfers are legally prohibited from answering market research questions.","C":"Budget bicycles can only be researched using secondary sources.","D":"The questionnaire contained too many open-ended questions."},"correctOption":"A","correctAnswer":"The sample size is too small and unrepresentative of typical budget bicycle commuters.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 20 wealthy golf club visitors do not represent the wider commuter population, leading to severe sampling error and bias.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because anyone may legally participate in market research.","C":"Incorrect because primary research is useful for bicycles if conducted with a representative sample.","D":"Incorrect because the core error here is the unrepresentative location and tiny sample size."}}},{"id":"P1_U3_MCQ_792","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_792","question":"Why might secondary market research data published by a rival company's trade group be unreliable?","options":{"A":"Because trade groups never publish numerical statistics.","B":"Because the organisation may have presented data selectively to promote its own industry interests.","C":"Because secondary data can only be read once before expiring.","D":"Because trade reports are always written in dead languages."},"correctOption":"B","correctAnswer":"Because the organisation may have presented data selectively to promote its own industry interests.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because industry lobbies or commercial publishers may emphasise favourable figures and omit weaknesses, introducing source bias.","distractor_reasons":{"A":"Incorrect because trade groups frequently publish industry sales and growth statistics.","B":"Correct selection.","C":"Incorrect because published reports can be reviewed repeatedly.","D":"Incorrect because trade reports are written in standard business languages."}}},{"id":"P1_U3_MCQ_793","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_793","question":"Which visual presentation method is best for showing how a total market of 100% is divided among four competing brands?","options":{"A":"A pie chart.","B":"A factory floor layout map.","C":"An organisation hierarchy chart.","D":"A job description."},"correctOption":"A","correctAnswer":"A pie chart.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a pie chart visually displays proportions or percentage shares making up a whole (100%).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a factory map shows physical machine placement.","C":"Incorrect because an organisation chart shows management roles and chain of command.","D":"Incorrect because a job description outlines an employee's duties."}}},{"id":"P1_U3_MCQ_794","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_794","question":"Which chart is most effective for illustrating changes in a product's monthly sales revenue over a 12-month period?","options":{"A":"A pie chart.","B":"A line graph.","C":"A person specification.","D":"A balance sheet."},"correctOption":"B","correctAnswer":"A line graph.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because line graphs clearly show continuous trends and fluctuations over time.","distractor_reasons":{"A":"Incorrect because pie charts show parts of a whole at a single point in time rather than trends over 12 months.","B":"Correct selection.","C":"Incorrect because a person specification lists candidate skills for recruitment.","D":"Incorrect because a balance sheet is a financial statement of assets and liabilities."}}},{"id":"P1_U3_MCQ_795","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_795","question":"A survey of 400 consumers asks which smartphone feature matters most: 180 choose Battery Life, 120 choose Camera Quality, 60 choose Screen Size, and 40 choose Price. What percentage chose Camera Quality?","options":{"A":"15%","B":"25%","C":"30%","D":"45%"},"correctOption":"C","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because (120 / 400) x 100 = 30%.","distractor_reasons":{"A":"Incorrect because 60 / 400 = 15% (Screen Size).","B":"Incorrect because 25% would be 100 respondents.","C":"Correct selection.","D":"Incorrect because 180 / 400 = 45% (Battery Life)."}}},{"id":"P1_U3_MCQ_796","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_796","question":"In the same survey of 400 consumers (180 Battery Life, 120 Camera Quality, 60 Screen Size, 40 Price), what conclusion should the smartphone manufacturer draw?","options":{"A":"Consumers care only about low prices and ignore technical performance.","B":"Screen size is the single highest priority for target customers.","C":"The company should remove cameras from its next smartphone model.","D":"Product development and advertising should emphasise long battery life and strong camera quality."},"correctOption":"D","correctAnswer":"Product development and advertising should emphasise long battery life and strong camera quality.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because 75% of respondents (300 out of 400) prioritised either battery life (45%) or camera quality (30%).","distractor_reasons":{"A":"Incorrect because only 10% (40 out of 400) ranked price as their top feature.","B":"Incorrect because screen size was chosen by only 15% of respondents.","C":"Incorrect because 30% ranked camera quality as their number one priority.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_797","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_797","question":"A bar chart shows a cafe's quarterly sales: Q1 = $20,000, Q2 = $25,000, Q3 = $40,000, Q4 = $15,000. Which marketing action is best supported by this data?","options":{"A":"Introducing special promotions or seasonal menu items in Q4 to boost off-peak sales.","B":"Closing the cafe permanently during Q3 when sales are highest.","C":"Raising prices by 100% in Q4 to recover lost revenue.","D":"Stopping all advertising during Q1, Q2, and Q4."},"correctOption":"A","correctAnswer":"Introducing special promotions or seasonal menu items in Q4 to boost off-peak sales.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sales drop sharply to $15,000 in Q4, so targeted promotions or seasonal products can stimulate demand during the quiet quarter.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Q3 is the peak revenue quarter ($40,000).","C":"Incorrect because doubling prices during weak Q4 demand would drive away remaining customers.","D":"Incorrect because cutting promotion in quiet quarters would worsen low sales."}}},{"id":"P1_U3_MCQ_798","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_798","question":"Why should a business combine both primary and secondary market research when planning a major product launch?","options":{"A":"Because combining them makes the research completely free of cost.","B":"Because secondary research provides broad market context cheaply while primary research answers specific current questions.","C":"Because primary research can only collect quantitative data and secondary research only qualitative data.","D":"Because government regulators reject business plans unless both methods are used."},"correctOption":"B","correctAnswer":"Because secondary research provides broad market context cheaply while primary research answers specific current questions.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because using both sources balances cost-effective industry background with tailored, up-to-date customer insights.","distractor_reasons":{"A":"Incorrect because primary research still incurs collection costs.","B":"Correct selection.","C":"Incorrect because both primary and secondary sources can provide quantitative and qualitative data.","D":"Incorrect because regulators do not mandate specific research methods for product launches."}}},{"id":"P1_U3_MCQ_799","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_799","question":"How can a business reduce interviewer bias during face-to-face market research?","options":{"A":"By allowing interviewers to reword questions however they like during each interview.","B":"By instructing interviewers to smile only when respondents praise the company.","C":"By training interviewers to read standardised, neutral questions in a consistent tone.","D":"By interviewing only employees who work in the company's marketing department."},"correctOption":"C","correctAnswer":"By training interviewers to read standardised, neutral questions in a consistent tone.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because standardised wording and neutral delivery prevent interviewers from steering respondents' answers.","distractor_reasons":{"A":"Incorrect because changing wording inconsistently introduces interviewer bias.","B":"Incorrect because reacting positively to praise encourages biased answers.","C":"Correct selection.","D":"Incorrect because internal marketing staff do not represent external consumers."}}},{"id":"P1_U3_MCQ_800","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_800","question":"What is a 'pilot survey' in primary market research?","options":{"A":"A survey conducted exclusively with airline pilots.","B":"The final nationwide census distributed to every household.","C":"A secondary report published by an aviation trade journal.","D":"A small-scale trial run of a questionnaire to test for unclear or biased questions before the full survey."},"correctOption":"D","correctAnswer":"A small-scale trial run of a questionnaire to test for unclear or biased questions before the full survey.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because testing a draft questionnaire on a small group identifies confusing wording or layout errors before spending money on a large survey.","distractor_reasons":{"A":"Incorrect because 'pilot' here means a preliminary trial, not aviation staff.","B":"Incorrect because a pilot survey occurs before the main survey.","C":"Incorrect because a pilot survey is a primary research preparation step.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_801","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_801","question":"What is meant by a product's 'Unique Selling Point' (USP)?","options":{"A":"A special feature of a product that differentiates it from competitors and attracts buyers.","B":"The single retail shop where the product is legally allowed to be sold.","C":"The lowest possible price charged during a clearance sale.","D":"The total fixed cost required to set up a production line."},"correctOption":"A","correctAnswer":"A special feature of a product that differentiates it from competitors and attracts buyers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a USP is a distinct benefit, design, or innovation that makes a product stand out from rival offerings.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because distribution locations relate to Place, not USP.","C":"Incorrect because clearance discounts are temporary pricing tactics.","D":"Incorrect because set-up costs are financial/operations figures."}}},{"id":"P1_U3_MCQ_802","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_802","question":"How does a strong brand image increase a business's 'added value'?","options":{"A":"By automatically reducing the cost of raw materials to zero.","B":"By allowing the business to charge a higher selling price than unbranded equivalents with similar production costs.","C":"By eliminating the need to pay wages to production employees.","D":"By reducing the physical weight of the finished product."},"correctOption":"B","correctAnswer":"By allowing the business to charge a higher selling price than unbranded equivalents with similar production costs.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value is the difference between selling price and bought-in material costs; strong branding raises the price consumers are willing to pay.","distractor_reasons":{"A":"Incorrect because raw materials still cost money.","B":"Correct selection.","C":"Incorrect because production workers must still be paid.","D":"Incorrect because brand perception adds psychological/status value rather than changing weight."}}},{"id":"P1_U3_MCQ_803","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_803","question":"Why is eye-catching packaging particularly important for fast-moving consumer goods (FMCG) sold in supermarkets?","options":{"A":"Because supermarkets forbid brands from using any media advertising.","B":"Because packaging eliminates the need for barcode scanners at checkouts.","C":"Because shoppers make quick decisions on crowded shelves where attractive packaging helps the product stand out.","D":"Because packaging prevents products from ever reaching the decline stage."},"correctOption":"C","correctAnswer":"Because shoppers make quick decisions on crowded shelves where attractive packaging helps the product stand out.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because in self-service supermarkets, distinctive colours, shapes, and labels act as a 'silent salesman' among competing brands.","distractor_reasons":{"A":"Incorrect because FMCG brands advertise heavily on TV and social media.","B":"Incorrect because packaging actually carries the printed barcode for scanning.","C":"Correct selection.","D":"Incorrect because good packaging supports sales but cannot permanently prevent product decline."}}},{"id":"P1_U3_MCQ_804","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_804","question":"How are environmental concerns influencing modern product packaging decisions?","options":{"A":"Businesses are using thicker layers of single-use non-recyclable plastic.","B":"Consumers prefer products packaged in toxic materials that cannot be reused.","C":"Governments have banned all cardboard and glass containers.","D":"Businesses are switching to recyclable, biodegradable, and minimal packaging to satisfy eco-conscious buyers and laws."},"correctOption":"D","correctAnswer":"Businesses are switching to recyclable, biodegradable, and minimal packaging to satisfy eco-conscious buyers and laws.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because rising consumer awareness and environmental regulations push firms to reduce plastic waste and use sustainable packaging.","distractor_reasons":{"A":"Incorrect because excessive single-use plastic harms brand image and faces legal restrictions.","B":"Incorrect because modern consumers increasingly penalise wasteful or toxic packaging.","C":"Incorrect because cardboard and glass are widely encouraged as recyclable materials.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_805","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_805","question":"What happens during the 'development' stage before a product is introduced to the market?","options":{"A":"Prototypes are designed and tested, incurring high R&D costs with zero sales revenue.","B":"Sales reach their maximum peak and competition is at its fiercest.","C":"The product is withdrawn from retail stores due to falling demand.","D":"The business earns its highest net profit margin of the entire life cycle."},"correctOption":"A","correctAnswer":"Prototypes are designed and tested, incurring high R&D costs with zero sales revenue.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because during research and development, money is spent building and testing prototypes before any units are sold.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because peak sales occur during the maturity stage.","C":"Incorrect because withdrawal occurs at the end of the decline stage.","D":"Incorrect because development generates cash outflows and losses rather than profits."}}},{"id":"P1_U3_MCQ_806","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_806","question":"How do pricing decisions typically change as a product moves from the introduction stage to the maturity stage?","options":{"A":"Prices always start at zero in introduction and rise by 500% in maturity.","B":"Initial skimming or penetration prices often shift toward competitive pricing as rivals enter the market.","C":"Businesses stop charging prices in maturity and rely solely on government subsidies.","D":"Pricing never changes across any stage of the Product Life Cycle."},"correctOption":"B","correctAnswer":"Initial skimming or penetration prices often shift toward competitive pricing as rivals enter the market.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because early launch pricing (skimming high or penetrating low) usually evolves into competitive pricing once rivals launch similar products in maturity.","distractor_reasons":{"A":"Incorrect because products are not launched for free nor raised fivefold in maturity.","B":"Correct selection.","C":"Incorrect because private businesses rely on sales revenue rather than government subsidies.","D":"Incorrect because pricing must adapt to changing competition and demand across the life cycle."}}},{"id":"P1_U3_MCQ_807","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_807","question":"How do promotional aims change between the introduction stage and the maturity stage of the Product Life Cycle?","options":{"A":"Introduction uses persuasive promotion to defend market share, while maturity uses informative promotion.","B":"No promotion is used during introduction, whereas massive launch advertising begins in decline.","C":"Introduction focuses on informative promotion to build awareness, while maturity uses persuasive promotion to maintain brand loyalty.","D":"Both stages use identical promotional budgets and messages."},"correctOption":"C","correctAnswer":"Introduction focuses on informative promotion to build awareness, while maturity uses persuasive promotion to maintain brand loyalty.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because buyers first need information about what a new product does, whereas in maturity promotion must persuade buyers to choose the brand over rivals.","distractor_reasons":{"A":"Incorrect because this reverses the roles of informative and persuasive promotion.","B":"Incorrect because heavy promotion is vital at introduction and usually reduced in decline.","C":"Correct selection.","D":"Incorrect because promotional objectives and spending change across life-cycle stages."}}},{"id":"P1_U3_MCQ_808","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_808","question":"Which marketing decision is most appropriate when a product reaches the 'decline' stage and extension strategies are no longer cost-effective?","options":{"A":"Invest millions of dollars in building a brand-new factory for the product.","B":"Double the selling price while launching an expensive global TV campaign.","C":"Hire hundreds of extra full-time production workers.","D":"Reduce promotional spending, lower prices to clear remaining stock, and plan to withdraw the product."},"correctOption":"D","correctAnswer":"Reduce promotional spending, lower prices to clear remaining stock, and plan to withdraw the product.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because once a product is permanently declining, cutting advertising expenses and discounting remaining inventory avoids further losses before discontinuation.","distractor_reasons":{"A":"Incorrect because investing in new factories for a dying product wastes capital.","B":"Incorrect because raising prices and spending heavily on TV ads will generate large losses in decline.","C":"Incorrect because falling output requires fewer workers, not more.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_809","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_809","question":"Which of the following is an example of an extension strategy?","options":{"A":"Finding new uses for an existing product, such as promoting baking soda as a fridge deodoriser.","B":"Halting production immediately as soon as sales growth begins to slow.","C":"Increasing unit production costs by using slower machinery.","D":"Removing the product from all online stores."},"correctOption":"A","correctAnswer":"Finding new uses for an existing product, such as promoting baking soda as a fridge deodoriser.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because encouraging consumers to use a mature product in new ways creates fresh demand and extends its life cycle.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because slowing growth signals maturity, which is typically the most profitable stage.","C":"Incorrect because raising production costs reduces profitability rather than extending sales.","D":"Incorrect because restricting distribution reduces sales volume."}}},{"id":"P1_U3_MCQ_810","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_810","question":"A shoe manufacturer produces 10,000 pairs of trainers at a total cost of $200,000. It applies a 40% cost-plus mark-up. What is the selling price per pair?","options":{"A":"$20","B":"$28","C":"$32","D":"$40"},"correctOption":"B","correctAnswer":"$28","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unit cost is $200,000 / 10,000 = $20, and adding a 40% mark-up ($20 x 0.40 = $8) gives a selling price of $28.","distractor_reasons":{"A":"Incorrect because $20 is the unit cost before adding the 40% mark-up.","B":"Correct selection.","C":"Incorrect because $32 represents a 60% mark-up rather than 40%.","D":"Incorrect because $40 represents a 100% mark-up."}}},{"id":"P1_U3_MCQ_811","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_811","question":"What is meant by 'promotional pricing'?","options":{"A":"Setting a permanent high price to reflect superior luxury quality.","B":"Adjusting prices every hour using real-time demand software.","C":"Temporarily lowering the price of a product for a short period to boost sales or clear excess stock.","D":"Calculating average unit cost and adding a fixed 25% profit margin."},"correctOption":"C","correctAnswer":"Temporarily lowering the price of a product for a short period to boost sales or clear excess stock.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because promotional pricing reduces prices for a limited time (such as seasonal sales or 'buy one get one free' deals) to attract shoppers.","distractor_reasons":{"A":"Incorrect because a high prestige price describes price skimming or premium pricing.","B":"Incorrect because hourly algorithm adjustments define dynamic pricing.","C":"Correct selection.","D":"Incorrect because adding a fixed percentage to unit cost defines cost-plus pricing."}}},{"id":"P1_U3_MCQ_812","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_812","question":"What is a potential disadvantage of using promotional pricing too frequently?","options":{"A":"It guarantees that competitors will raise their prices.","B":"It eliminates all variable costs of manufacturing.","C":"It prevents customers from noticing the product in retail stores.","D":"It lowers profit per unit and can damage the brand's quality image if buyers expect constant discounts."},"correctOption":"D","correctAnswer":"It lowers profit per unit and can damage the brand's quality image if buyers expect constant discounts.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because frequent price cuts shrink profit margins and train customers to delay buying until the next sale.","distractor_reasons":{"A":"Incorrect because frequent discounts often trigger competitors to cut prices too.","B":"Incorrect because variable production costs remain unchanged.","C":"Incorrect because price promotions usually increase shopper attention.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_813","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_813","question":"A technology company has spent $15 million developing a revolutionary foldable tablet with no direct competitors yet. Which pricing method should it choose at launch?","options":{"A":"Price skimming.","B":"Penetration pricing.","C":"Promotional clearance pricing.","D":"Below-cost pricing."},"correctOption":"A","correctAnswer":"Price skimming.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because price skimming sets a high initial price for an innovative, unique product to quickly recover high R&D costs from early adopters.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because penetration pricing sets a low price, which would take far too long to recover $15 million in R&D.","C":"Incorrect because clearance pricing is used to get rid of old, unwanted stock.","D":"Incorrect because selling below cost would generate immediate losses."}}},{"id":"P1_U3_MCQ_814","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_814","question":"A new soft drinks brand is entering a crowded market dominated by established rivals selling similar cans at $1.00. Which pricing method is most suitable to gain rapid market share?","options":{"A":"Price skimming at $3.50 per can.","B":"Penetration pricing at $0.75 per can.","C":"Cost-plus pricing with a 200% mark-up.","D":"Dynamic surge pricing every ten minutes."},"correctOption":"B","correctAnswer":"Penetration pricing at $0.75 per can.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because penetration pricing sets an attractive introductory price below the $1.00 market norm to persuade consumers to switch and try the new drink.","distractor_reasons":{"A":"Incorrect because charging $3.50 for a standard soft drink in a crowded market will result in almost zero sales.","B":"Correct selection.","C":"Incorrect because a 200% mark-up would make the price uncompetitive against established rivals.","D":"Incorrect because frequent price surges are unsuitable for everyday supermarket cans."}}},{"id":"P1_U3_MCQ_815","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_815","question":"What is a potential disadvantage of dynamic pricing for a business?","options":{"A":"Prices can never be increased during busy peak periods.","B":"It requires no computers or internet connectivity.","C":"Customers may feel treated unfairly if they discover they paid much more than another buyer for the same seat or item.","D":"It forces the business to keep prices fixed for an entire year."},"correctOption":"C","correctAnswer":"Customers may feel treated unfairly if they discover they paid much more than another buyer for the same seat or item.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sharp price spikes during high demand can irritate customers and damage brand trust.","distractor_reasons":{"A":"Incorrect because raising prices during peak demand is a primary feature of dynamic pricing.","B":"Incorrect because dynamic pricing relies on computer algorithms and real-time data.","C":"Correct selection.","D":"Incorrect because dynamic prices change continuously rather than staying fixed."}}},{"id":"P1_U3_MCQ_816","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_816","question":"What does 'price elastic demand' mean?","options":{"A":"Consumer demand does not change at all when the price rises or falls.","B":"A percentage change in price causes a smaller percentage change in quantity demanded.","C":"The product's physical packaging can stretch without breaking.","D":"A percentage change in price causes a larger percentage change in quantity demanded."},"correctOption":"D","correctAnswer":"A percentage change in price causes a larger percentage change in quantity demanded.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when demand is price elastic, customers are very sensitive to price changes, so a small price rise causes a big drop in sales.","distractor_reasons":{"A":"Incorrect because zero response describes perfectly price inelastic demand.","B":"Incorrect because a smaller percentage change in demand defines price inelastic demand.","C":"Incorrect because price elasticity measures consumer responsiveness to price, not physical material properties.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_817","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_817","question":"What does 'price inelastic demand' mean?","options":{"A":"Consumers are relatively insensitive to price changes, so a price rise causes only a small fall in quantity demanded.","B":"A 5% price increase causes sales volume to fall by 50%.","C":"The product has dozens of identical, cheap substitutes available nearby.","D":"Sales revenue falls to zero whenever the price is increased by 1%."},"correctOption":"A","correctAnswer":"Consumers are relatively insensitive to price changes, so a price rise causes only a small fall in quantity demanded.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because with price inelastic demand (such as essential fuel or strong brand loyalty), percentage demand changes by less than the percentage price change.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a 50% drop from a 5% price rise indicates highly price elastic demand.","C":"Incorrect because many close substitutes make demand price elastic, not inelastic.","D":"Incorrect because extreme sensitivity describes elastic demand."}}},{"id":"P1_U3_MCQ_818","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_818","question":"If demand for a business's product is 'price elastic', what happens to total sales revenue if the business increases its price?","options":{"A":"Total sales revenue increases sharply.","B":"Total sales revenue decreases because the percentage drop in sales volume outweighs the higher price.","C":"Total sales revenue remains completely unchanged.","D":"Total fixed costs fall to zero."},"correctOption":"B","correctAnswer":"Total sales revenue decreases because the percentage drop in sales volume outweighs the higher price.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when customers are highly price-sensitive, raising the price drives away so many buyers that total revenue falls.","distractor_reasons":{"A":"Incorrect because raising price increases revenue only when demand is price inelastic.","B":"Correct selection.","C":"Incorrect because a large fall in quantity sold reduces total revenue.","D":"Incorrect because price elasticity affects demand and revenue, not fixed production costs."}}},{"id":"P1_U3_MCQ_819","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_819","question":"If demand for a product is 'price inelastic', what happens to total sales revenue if the business raises its selling price?","options":{"A":"Total sales revenue falls sharply because almost all customers stop buying.","B":"Total sales revenue drops to zero immediately.","C":"Total sales revenue increases because most customers continue buying despite the higher price.","D":"Variable costs per unit double automatically."},"correctOption":"C","correctAnswer":"Total sales revenue increases because most customers continue buying despite the higher price.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when demand is price inelastic, the extra revenue earned from the higher price exceeds the small loss in unit sales.","distractor_reasons":{"A":"Incorrect because steep drops in sales happen when demand is price elastic.","B":"Incorrect because inelastic demand means buyers keep purchasing.","C":"Correct selection.","D":"Incorrect because price changes do not alter variable manufacturing costs."}}},{"id":"P1_U3_MCQ_820","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_820","question":"Which factor is most likely to make demand for a product 'price inelastic'?","options":{"A":"There are many identical, lower-priced substitute products sold next door.","B":"The product is an expensive non-essential luxury item.","C":"The purchase takes up 80% of a household's annual income.","D":"The product is a daily necessity with very few substitutes and strong brand loyalty."},"correctOption":"D","correctAnswer":"The product is a daily necessity with very few substitutes and strong brand loyalty.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumers have little choice but to keep buying necessities or strongly preferred brands even when prices rise.","distractor_reasons":{"A":"Incorrect because close substitutes make it easy for buyers to switch, creating price elastic demand.","B":"Incorrect because non-essential luxuries usually have price elastic demand.","C":"Incorrect because items taking a huge share of income make buyers very price-sensitive (elastic).","D":"Correct selection."}}},{"id":"P1_U3_MCQ_821","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_821","question":"Why do businesses invest heavily in building brand loyalty and Unique Selling Points (USPs) in relation to price elasticity?","options":{"A":"To make demand more price inelastic so the business can raise prices without losing many customers.","B":"To make demand more price elastic so customers switch to competitors easily.","C":"To ensure that the business never earns a profit margin.","D":"To avoid complying with weights and measures laws."},"correctOption":"A","correctAnswer":"To make demand more price inelastic so the business can raise prices without losing many customers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because strong branding differentiates the product from substitutes, reducing customer price sensitivity (making demand more inelastic).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses want less price sensitivity, not more.","C":"Incorrect because lower price sensitivity helps increase profit margins.","D":"Incorrect because legal regulations apply regardless of branding."}}},{"id":"P1_U3_MCQ_822","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_822","question":"A bus company discovers that demand for commuter tickets during morning rush hour is price inelastic, whereas off-peak afternoon demand is price elastic. How should it set prices to maximise revenue?","options":{"A":"Lower morning rush-hour fares and double afternoon off-peak fares.","B":"Charge higher fares during morning rush hour and offer discounted fares in the afternoon.","C":"Make all bus journeys completely free at all times of day.","D":"Cancel all morning rush-hour buses to save fuel."},"correctOption":"B","correctAnswer":"Charge higher fares during morning rush hour and offer discounted fares in the afternoon.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because raising fares when demand is inelastic (rush hour) boosts revenue, while lowering fares when demand is elastic (afternoon) attracts enough extra passengers to raise revenue.","distractor_reasons":{"A":"Incorrect because cutting inelastic prices reduces revenue and raising elastic prices drives away off-peak riders.","B":"Correct selection.","C":"Incorrect because zero fares generate zero ticket revenue.","D":"Incorrect because rush hour is the period of strongest passenger demand."}}},{"id":"P1_U3_MCQ_823","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_823","question":"What is 'loss-leader pricing' in retail?","options":{"A":"Pricing every item in a store below manufacturing cost permanently.","B":"Setting a high price for a brand-new gadget at launch.","C":"Selling a popular product at or below cost to attract shoppers into the store to buy other profitable items.","D":"Adding a 10% mark-up onto the wholesale cost of every product."},"correctOption":"C","correctAnswer":"Selling a popular product at or below cost to attract shoppers into the store to buy other profitable items.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because supermarkets often discount staple items (like milk or bread) heavily to draw footfall, earning overall profit from the rest of the shopper's trolley.","distractor_reasons":{"A":"Incorrect because discounting every item below cost would bankrupt the retailer.","B":"Incorrect because a high launch price defines price skimming.","C":"Correct selection.","D":"Incorrect because adding a fixed mark-up defines cost-plus pricing."}}},{"id":"P1_U3_MCQ_824","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_824","question":"How does a product's position in the 'maturity' stage affect a business's decision to develop new products?","options":{"A":"Businesses wait until all mature products have completely stopped selling before starting R&D.","B":"Businesses stop all research and development permanently once one product reaches maturity.","C":"Businesses withdraw mature products immediately even while they are making high profits.","D":"Businesses use profits from mature 'cash cow' products to fund R&D for future new products."},"correctOption":"D","correctAnswer":"Businesses use profits from mature 'cash cow' products to fund R&D for future new products.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because mature products generate strong positive cash flow, enabling the business to invest in new products before existing ones decline.","distractor_reasons":{"A":"Incorrect because waiting until sales collapse leaves a dangerous gap in revenue.","B":"Incorrect because ongoing innovation is vital for long-term survival.","C":"Incorrect because profitable mature products should be maintained or extended, not withdrawn early.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_825","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_825","question":"Why might a small business struggle to develop innovative new products compared to a large multinational corporation?","options":{"A":"Limited financial capital to pay for expensive research, prototype testing, and patent protection.","B":"Small businesses are legally prohibited from inventing new products.","C":"Small businesses have too many employees in their R&D departments.","D":"Consumers refuse to buy new products from small local firms."},"correctOption":"A","correctAnswer":"Limited financial capital to pay for expensive research, prototype testing, and patent protection.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because R&D is costly and risky, and small firms often lack the retained profits or borrowing power to fund lengthy development.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because small businesses are free to innovate and frequently create niche inventions.","C":"Incorrect because small businesses usually have very few or no dedicated R&D staff.","D":"Incorrect because consumers regularly buy innovative products from small enterprises."}}},{"id":"P1_U3_MCQ_826","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_826","question":"Which distribution channel is most appropriate for a baker making fresh wedding cakes to order?","options":{"A":"Producer -> Wholesaler -> Retailer -> Consumer.","B":"Producer -> Direct to Consumer.","C":"Producer -> Overseas Agent -> Wholesaler -> Consumer.","D":"Producer -> National Supermarket Warehouse -> Consumer."},"correctOption":"B","correctAnswer":"Producer -> Direct to Consumer.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because custom wedding cakes are perishable, bespoke items made to individual customer specifications, requiring direct contact and fast delivery.","distractor_reasons":{"A":"Incorrect because passing through wholesalers and retailers takes too long for fresh bespoke cakes.","B":"Correct selection.","C":"Incorrect because overseas agents are for exporting mass goods, not local custom cakes.","D":"Incorrect because supermarket warehouses handle standardised packaged goods rather than bespoke wedding cakes."}}},{"id":"P1_U3_MCQ_827","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_827","question":"Which distribution channel is typically best for a manufacturer of canned soup selling to thousands of small corner shops across a country?","options":{"A":"Producer -> Direct door-to-door delivery to every individual shopper.","B":"Producer -> Overseas export agent -> Consumer.","C":"Producer -> Wholesaler -> Retailer -> Consumer.","D":"Producer -> Custom job-order showroom -> Consumer."},"correctOption":"C","correctAnswer":"Producer -> Wholesaler -> Retailer -> Consumer.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because canned soup has a long shelf life and is bought in small cases by thousands of independent shops, making wholesalers ideal for breaking bulk.","distractor_reasons":{"A":"Incorrect because delivering single cans of soup directly to millions of homes is far too expensive.","B":"Incorrect because export agents are used for foreign markets rather than domestic corner shops.","C":"Correct selection.","D":"Incorrect because canned soup is a mass-market FMCG item rather than a bespoke showroom product."}}},{"id":"P1_U3_MCQ_828","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_828","question":"Why do large supermarket chains usually buy groceries directly from food manufacturers rather than through wholesalers?","options":{"A":"Wholesalers are legally banned from selling food products.","B":"Supermarkets only sell one brand of each grocery item.","C":"Food manufacturers refuse to offer discounts on large bulk orders.","D":"Supermarkets buy in huge bulk quantities themselves and avoid paying a wholesaler's profit margin."},"correctOption":"D","correctAnswer":"Supermarkets buy in huge bulk quantities themselves and avoid paying a wholesaler's profit margin.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because major supermarket chains have their own regional distribution warehouses and purchase in massive volumes directly from producers.","distractor_reasons":{"A":"Incorrect because wholesalers regularly supply smaller independent grocers.","B":"Incorrect because supermarkets stock wide ranges of competing brands.","C":"Incorrect because manufacturers offer substantial bulk discounts to major supermarket chains.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_829","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_829","question":"Which factor is most important when choosing a distribution channel for fresh fish or cut flowers?","options":{"A":"Speed and shortness of the channel so the perishable product reaches buyers before spoiling.","B":"Using as many wholesalers and storage warehouses as possible.","C":"Selling exclusively through mail-order catalogues taking three weeks to deliver.","D":"Choosing the slowest sea-freight route to minimise fuel usage."},"correctOption":"A","correctAnswer":"Speed and shortness of the channel so the perishable product reaches buyers before spoiling.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because perishable goods deteriorate quickly, requiring direct or short channels with rapid refrigerated transport.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because multiple intermediaries delay delivery and increase spoilage.","C":"Incorrect because three-week mail delivery would ruin fresh fish or flowers.","D":"Incorrect because slow transport is unsuitable for perishable items."}}},{"id":"P1_U3_MCQ_830","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_830","question":"Why are complex technical products (such as industrial turbines or medical scanners) normally sold directly from the producer to the business customer?","options":{"A":"Because supermarkets refuse to stock medical scanners on their shelves.","B":"Because specialist technical advice, custom installation, and after-sales maintenance are required.","C":"Because wholesalers buy industrial turbines in packs of 10,000 units.","D":"Because technical products never require any customer support."},"correctOption":"B","correctAnswer":"Because specialist technical advice, custom installation, and after-sales maintenance are required.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high-value technical equipment requires direct engineering consultation, tailored specifications, and ongoing servicing from the manufacturer.","distractor_reasons":{"A":"Incorrect because supermarkets are consumer retailers, not B2B engineering suppliers.","B":"Correct selection.","C":"Incorrect because heavy industrial machinery is ordered individually or in small numbers, not bulk-broken by wholesalers.","D":"Incorrect because complex equipment requires extensive training and after-sales support."}}},{"id":"P1_U3_MCQ_831","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_831","question":"How does 'informative advertising' differ from 'persuasive advertising'?","options":{"A":"Informative advertising is illegal on television, whereas persuasive advertising is permitted.","B":"Informative advertising is only used in the decline stage, whereas persuasive advertising is only used before launch.","C":"Informative advertising provides factual details about a product's features, whereas persuasive advertising appeals to emotions to convince buyers to prefer the brand.","D":"Informative advertising is free of charge, whereas persuasive advertising costs money."},"correctOption":"C","correctAnswer":"Informative advertising provides factual details about a product's features, whereas persuasive advertising appeals to emotions to convince buyers to prefer the brand.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because informative ads educate consumers about how a product works or where to buy it, while persuasive ads create desire and brand preference.","distractor_reasons":{"A":"Incorrect because both informative and persuasive advertising are legal across media.","B":"Incorrect because informative advertising is heavily used at introduction, and persuasive advertising dominates growth and maturity.","C":"Correct selection.","D":"Incorrect because both forms require paid media space or production costs."}}},{"id":"P1_U3_MCQ_832","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_832","question":"When is 'informative advertising' most useful for a business?","options":{"A":"When withdrawing an obsolete product from the market.","B":"When cutting production staff during a factory closure.","C":"When selling an identical commodity that every consumer already understands completely.","D":"When launching a brand-new invention whose features and uses consumers do not yet know."},"correctOption":"D","correctAnswer":"When launching a brand-new invention whose features and uses consumers do not yet know.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumers will not buy an unfamiliar new product unless advertising clearly explains what it does and how it benefits them.","distractor_reasons":{"A":"Incorrect because promotional spending is cut when withdrawing a declining product.","B":"Incorrect because internal staffing reductions are not promoted via consumer advertising.","C":"Incorrect because familiar everyday goods rely more on persuasive branding than basic explanation.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_833","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_833","question":"What is a major advantage of television advertising for a large national brand?","options":{"A":"It reaches millions of viewers simultaneously and combines sight, sound, and movement to create strong brand impact.","B":"It is the cheapest advertising medium available for small local corner shops.","C":"Viewers are legally prevented from changing channels during commercial breaks.","D":"It targets only one specific street within a small village."},"correctOption":"A","correctAnswer":"It reaches millions of viewers simultaneously and combines sight, sound, and movement to create strong brand impact.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because TV reaches huge mass-market audiences and uses audio-visual storytelling to build high brand awareness.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because TV production and airtime are extremely expensive, making it unsuitable for small local shops.","C":"Incorrect because viewers frequently skip ads, switch channels, or use ad-free streaming.","D":"Incorrect because TV broadcasts regionally or nationally rather than to a single street."}}},{"id":"P1_U3_MCQ_834","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_834","question":"What is a key disadvantage of advertising in national newspapers or magazines?","options":{"A":"Readers cannot view the advert for more than three seconds.","B":"Print readership has declined as consumers shift online, and static pages lack sound or video.","C":"It is impossible to include detailed product specifications or coupons.","D":"Specialist magazines cannot target specific hobbyist audiences."},"correctOption":"B","correctAnswer":"Print readership has declined as consumers shift online, and static pages lack sound or video.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because falling print circulation reduces reach among younger audiences, and static print is less dynamic than video.","distractor_reasons":{"A":"Incorrect because readers can study a print advert for as long as they wish.","B":"Correct selection.","C":"Incorrect because print ads are very good for detailed text and cut-out vouchers.","D":"Incorrect because specialist magazines actually target hobbyists very effectively."}}},{"id":"P1_U3_MCQ_835","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_835","question":"What is meant by 'point-of-sale displays' as a method of sales promotion?","options":{"A":"Television commercials aired late at night after shops close.","B":"Emails sent to customers six months after they bought an item.","C":"Eye-catching stands, signs, or product arrangements placed near supermarket checkouts or aisle ends to trigger impulse buys.","D":"Posters displayed inside a factory warehouse for delivery truck drivers."},"correctOption":"C","correctAnswer":"Eye-catching stands, signs, or product arrangements placed near supermarket checkouts or aisle ends to trigger impulse buys.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because point-of-sale (POS) displays catch shoppers' attention at the exact moment and place where purchasing decisions happen.","distractor_reasons":{"A":"Incorrect because TV commercials are media advertising, not in-store displays.","B":"Incorrect because follow-up emails are direct digital marketing.","C":"Correct selection.","D":"Incorrect because warehouse signs for staff are internal operational notices."}}},{"id":"P1_U3_MCQ_836","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_836","question":"Why do food and cosmetics companies distribute 'free samples' as a sales promotion technique?","options":{"A":"Because the products failed safety inspections and cannot be sold.","B":"To eliminate the need to pay any retail distribution margins.","C":"To reduce the total weight of inventory stored in warehouses.","D":"To remove consumer risk by letting shoppers try the product first, encouraging future full-size purchases."},"correctOption":"D","correctAnswer":"To remove consumer risk by letting shoppers try the product first, encouraging future full-size purchases.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumers often hesitate to buy an unfamiliar food or skincare item; trying a free sample builds confidence and stimulates repeat sales.","distractor_reasons":{"A":"Incorrect because free samples must meet all legal health and safety standards.","B":"Incorrect because samples are often distributed through retailers.","C":"Incorrect because sample sizes are produced specifically for promotion, adding packaging costs.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_837","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_837","question":"How does a 'Buy One, Get One Free' (BOGOF) promotion benefit a business?","options":{"A":"It quickly increases sales volume and clears excess stock while maintaining the product's standard unit price perception.","B":"It doubles the profit margin earned on every single unit given away.","C":"It guarantees that competitors will stop advertising their products.","D":"It eliminates all manufacturing costs for the second free item."},"correctOption":"A","correctAnswer":"It quickly increases sales volume and clears excess stock while maintaining the product's standard unit price perception.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because BOGOF encourages shoppers to buy larger quantities immediately without formally cutting the item's shelf price.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because giving away a second item halves the average revenue per unit.","C":"Incorrect because rivals often respond with their own promotions.","D":"Incorrect because the business still pays the variable cost of producing both units."}}},{"id":"P1_U3_MCQ_838","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_838","question":"What is the role of 'sponsorship' in a business's promotional mix?","options":{"A":"Paying factory workers overtime to increase weekend output.","B":"Paying to have the company's name or logo associated with a sports team, event, or television programme to boost brand awareness.","C":"Buying shares in a rival company to take over its board of directors.","D":"Offering a 50% cash discount to customers who pay invoices early."},"correctOption":"B","correctAnswer":"Paying to have the company's name or logo associated with a sports team, event, or television programme to boost brand awareness.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sponsorship links the brand with popular events or teams watched by the target audience, generating wide publicity.","distractor_reasons":{"A":"Incorrect because overtime pay is an operations/HRM wage cost.","B":"Correct selection.","C":"Incorrect because buying shares in a rival is a takeover/investment action.","D":"Incorrect because early-payment discounts are trade credit terms."}}},{"id":"P1_U3_MCQ_839","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_839","question":"What is a risk of using sports or celebrity sponsorship as a promotional tool?","options":{"A":"Sponsorship is completely free and therefore ignored by media outlets.","B":"It is illegal for private companies to sponsor sporting events.","C":"If the sponsored athlete or event suffers a scandal, negative publicity can damage the sponsor's brand image.","D":"Logos cannot be displayed on sportswear or stadium banners."},"correctOption":"C","correctAnswer":"If the sponsored athlete or event suffers a scandal, negative publicity can damage the sponsor's brand image.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because associating a brand closely with an individual or team exposes the business to reputational harm if misconduct occurs.","distractor_reasons":{"A":"Incorrect because major sponsorships are very expensive.","B":"Incorrect because commercial sponsorship is widespread and legal (aside from restricted products like tobacco).","C":"Correct selection.","D":"Incorrect because displaying logos on kits and banners is standard in sponsorship."}}},{"id":"P1_U3_MCQ_840","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_840","question":"What is meant by 'Public Relations' (PR) in promotion?","options":{"A":"Buying paid 30-second commercial slots during prime-time television.","B":"Distributing discount coupons at supermarket entrances.","C":"Conducting door-to-door market research interviews.","D":"Activities aimed at gaining favourable media coverage and building a positive public image, such as press releases and charity work."},"correctOption":"D","correctAnswer":"Activities aimed at gaining favourable media coverage and building a positive public image, such as press releases and charity work.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because PR focuses on maintaining good public goodwill and earning unpaid news coverage rather than buying direct advertising space.","distractor_reasons":{"A":"Incorrect because buying TV slots is paid advertising.","B":"Incorrect because coupons are sales promotions.","C":"Incorrect because door-to-door interviews are market research.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_841","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_841","question":"Why is 'cost-effectiveness' important when a business decides how to spend its marketing budget on promotion?","options":{"A":"Because promotion should generate extra sales revenue and profit that exceed the cost of the campaign.","B":"Because businesses should always choose the most expensive advertising medium regardless of audience.","C":"Because laws cap promotional spending at 1% of annual revenue.","D":"Because cheap promotion always produces higher sales than expensive promotion."},"correctOption":"A","correctAnswer":"Because promotion should generate extra sales revenue and profit that exceed the cost of the campaign.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because marketing budgets are limited, so managers must evaluate the return on investment (extra sales per dollar spent) of each promotional method.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because expensive media waste money if the target segment does not watch or read them.","C":"Incorrect because there is no universal legal cap of 1% on promotion.","D":"Incorrect because very cheap methods (like flyers) may yield low response rates compared to better-targeted options."}}},{"id":"P1_U3_MCQ_842","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_842","question":"How has the use of social media networks changed promotion for small businesses?","options":{"A":"Small businesses are now banned from promoting locally without a national TV budget.","B":"Small businesses can interact directly with customers, share viral content, and target ads on a modest budget.","C":"Social media eliminates the need to respond to negative customer reviews.","D":"Social media promotion guarantees that every post reaches 100% of the world's population."},"correctOption":"B","correctAnswer":"Small businesses can interact directly with customers, share viral content, and target ads on a modest budget.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because social media lowers barriers to promotion, allowing smaller firms to build communities and run targeted ads affordably.","distractor_reasons":{"A":"Incorrect because small businesses can advertise on social media without a TV budget.","B":"Correct selection.","C":"Incorrect because public negative comments on social media require prompt management to protect reputation.","D":"Incorrect because algorithms limit organic reach to a fraction of users."}}},{"id":"P1_U3_MCQ_843","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_843","question":"What is a potential threat to a business from using social media for promotion?","options":{"A":"Customers are unable to share product links with their friends.","B":"Posts can only contain plain black-and-white text without images.","C":"Public customer complaints or product failures can spread virally within hours, damaging reputation.","D":"Social media platforms charge millions of dollars just to create a business profile."},"correctOption":"C","correctAnswer":"Public customer complaints or product failures can spread virally within hours, damaging reputation.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social media gives consumers a public voice, meaning poor service or bad reviews can rapidly harm brand image.","distractor_reasons":{"A":"Incorrect because easy sharing is a major benefit of social media.","B":"Incorrect because social media supports photos, videos, and interactive content.","C":"Correct selection.","D":"Incorrect because setting up a business social media page is normally free."}}},{"id":"P1_U3_MCQ_844","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_844","question":"What is an opportunity created by e-commerce for a business's 'Place' strategy?","options":{"A":"It forces the business to open expensive physical stores in every city.","B":"It prevents customers in rural areas from ordering the business's products.","C":"It eliminates the need to package physical goods safely for transport.","D":"It enables direct-to-consumer selling worldwide without needing retail intermediaries."},"correctOption":"D","correctAnswer":"It enables direct-to-consumer selling worldwide without needing retail intermediaries.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an e-commerce store acts as a global direct distribution channel, letting producers retain full retail margins.","distractor_reasons":{"A":"Incorrect because e-commerce reduces the need for physical retail branches.","B":"Incorrect because rural customers with internet access can order online easily.","C":"Incorrect because parcel delivery actually requires sturdy protective packaging.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_845","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_845","question":"What is a threat of e-commerce to traditional high-street retail shops?","options":{"A":"Lower-cost online competitors can undercut high-street prices because they do not pay expensive shop rents.","B":"Online websites are legally forbidden from selling clothing or electronics.","C":"Shoppers prefer waiting in long checkout queues rather than ordering from home.","D":"High-street shops are prohibited from creating their own websites."},"correctOption":"A","correctAnswer":"Lower-cost online competitors can undercut high-street prices because they do not pay expensive shop rents.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because online-only retailers avoid high-street property rents and store staffing costs, enabling lower prices that draw shoppers away from physical stores.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because clothing and electronics are among the largest e-commerce categories.","C":"Incorrect because convenience and avoiding queues attract shoppers online.","D":"Incorrect because many high-street chains successfully operate 'click-and-collect' or online stores alongside physical shops."}}},{"id":"P1_U3_MCQ_846","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_846","question":"How does e-commerce affect 'Price' decisions for businesses selling online?","options":{"A":"Businesses can charge double the market price because shoppers cannot check rival prices.","B":"Price comparison websites make prices transparent, forcing online sellers to stay highly competitive or use dynamic pricing.","C":"Online businesses are legally required to charge identical prices across all websites.","D":"Delivery fees are banned by international law."},"correctOption":"B","correctAnswer":"Price comparison websites make prices transparent, forcing online sellers to stay highly competitive or use dynamic pricing.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consumers can compare rival prices in seconds online, increasing price transparency and competitive pressure.","distractor_reasons":{"A":"Incorrect because online buyers can check rival prices effortlessly.","B":"Correct selection.","C":"Incorrect because online retailers set their own independent prices.","D":"Incorrect because businesses may charge delivery fees provided they are clearly disclosed."}}},{"id":"P1_U3_MCQ_847","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_847","question":"What is a cybersecurity threat that businesses operating e-commerce websites must manage?","options":{"A":"Shoplifters physically stealing items from website web pages.","B":"Customers paying with physical coins through their computer screens.","C":"Hacking, data breaches of customer payment details, and website downtime.","D":"Excessive rent increases charged by high-street landlords."},"correctOption":"C","correctAnswer":"Hacking, data breaches of customer payment details, and website downtime.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because online retailers must invest in secure payment encryption and IT reliability to prevent cyberattacks and lost sales.","distractor_reasons":{"A":"Incorrect because physical shoplifting occurs in brick-and-mortar shops, not online.","B":"Incorrect because online payments are digital.","C":"Correct selection.","D":"Incorrect because high-street shop rents affect physical stores rather than websites."}}},{"id":"P1_U3_MCQ_848","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_848","question":"How can a traditional brick-and-mortar retailer combine physical stores with e-commerce to gain an advantage?","options":{"A":"By closing its website every weekend and refusing card payments.","B":"By charging online customers triple the in-store price.","C":"By refusing to accept returns of online orders in its physical branches.","D":"By offering 'click and collect' where buyers order online and pick up in-store for free."},"correctOption":"D","correctAnswer":"By offering 'click and collect' where buyers order online and pick up in-store for free.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because 'click and collect' saves delivery charges for customers and brings them into physical stores where they may buy extra items.","distractor_reasons":{"A":"Incorrect because closing a website reduces convenience and sales.","B":"Incorrect because overcharging online shoppers drives them to competitors.","C":"Incorrect because easy in-store returns build confidence in ordering online.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_849","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_849","question":"Why might a luxury designer handbag brand choose NOT to sell its bags on third-party mass-market discount websites?","options":{"A":"Selling alongside cheap discount goods would weaken its exclusive brand image and prestige.","B":"Third-party websites cannot process high-value credit card payments.","C":"Luxury handbags are too heavy to be transported by courier vans.","D":"Laws prohibit luxury brands from selling handbags over the internet."},"correctOption":"A","correctAnswer":"Selling alongside cheap discount goods would weaken its exclusive brand image and prestige.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Place must match brand positioning; selective distribution in flagship boutiques and official brand sites preserves exclusivity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because online payment gateways easily process high-value transactions.","C":"Incorrect because handbags are lightweight and easy to ship.","D":"Incorrect because luxury brands legally sell online through their own controlled platforms."}}},{"id":"P1_U3_MCQ_850","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_850","question":"Which promotional method is most appropriate for a small local plumber with a very limited marketing budget?","options":{"A":"A nationwide television commercial during the World Cup final.","B":"Local directory listings, targeted social media posts in the town, and printed flyers.","C":"Sponsoring an international Formula 1 racing team.","D":"Full-page adverts in national daily financial newspapers."},"correctOption":"B","correctAnswer":"Local directory listings, targeted social media posts in the town, and printed flyers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a local plumber serves nearby households and has a small budget, making low-cost local search/social ads and neighbourhood flyers cost-effective.","distractor_reasons":{"A":"Incorrect because national TV ads are unaffordable and waste money reaching viewers outside the plumber's local area.","B":"Correct selection.","C":"Incorrect because Formula 1 sponsorship costs millions of dollars.","D":"Incorrect because national newspapers are costly and poorly targeted for a local tradesperson."}}},{"id":"P1_U3_MCQ_851","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_851","question":"A company wants to achieve the marketing objective of 'increasing market share by 5% over the next year' in a competitive snack market. Which marketing strategy is most suitable?","options":{"A":"Raise prices by 30%, cut advertising completely, and reduce the number of shops stocking the snacks.","B":"Stop all product innovation and rely solely on outdated packaging from ten years ago.","C":"Launch a new trending flavour, use competitive pricing with multi-buy offers, and promote heavily on social media and in supermarkets.","D":"Switch from mass-market distribution to selling exclusively by appointment from the factory gate."},"correctOption":"C","correctAnswer":"Launch a new trending flavour, use competitive pricing with multi-buy offers, and promote heavily on social media and in supermarkets.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because combining an appealing new product flavour, competitive/promotional pricing, wide retail availability, and strong promotion aligns all four Ps to win buyers from rivals.","distractor_reasons":{"A":"Incorrect because higher prices, less promotion, and fewer outlets will shrink market share.","B":"Incorrect because ignoring trends and packaging loses market share in snack markets.","C":"Correct selection.","D":"Incorrect because restricting sales to the factory gate destroys convenience for everyday snack buyers."}}},{"id":"P1_U3_MCQ_852","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_852","question":"Why is 'Product' often considered the central element of the marketing mix when developing a marketing strategy?","options":{"A":"Because if the product fails to satisfy customer needs or is poor quality, low prices and heavy promotion will not sustain repeat sales.","B":"Because laws forbid businesses from changing their prices or promotional methods.","C":"Because products never require any packaging or branding.","D":"Because Place and Promotion have zero influence on consumer buying decisions."},"correctOption":"A","correctAnswer":"Because if the product fails to satisfy customer needs or is poor quality, low prices and heavy promotion will not sustain repeat sales.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a poorly designed or faulty product leads to dissatisfied customers and negative reviews regardless of how well it is advertised or priced.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses freely adjust prices and promotions.","C":"Incorrect because packaging and branding are integral parts of the Product element.","D":"Incorrect because Place and Promotion are also essential to make buyers aware and able to purchase."}}},{"id":"P1_U3_MCQ_853","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_853","question":"When might 'Price' be the most decisive element of the marketing mix in influencing consumer decisions?","options":{"A":"When selling life-saving patented medicines with no substitutes.","B":"When selling undifferentiated everyday commodities (such as basic petrol or sugar) where competing brands are nearly identical.","C":"When selling bespoke diamond wedding rings to billionaires.","D":"When consumers are completely unaware that the product exists."},"correctOption":"B","correctAnswer":"When selling undifferentiated everyday commodities (such as basic petrol or sugar) where competing brands are nearly identical.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when competing products offer identical functionality, demand is highly price elastic and shoppers choose the cheapest option.","distractor_reasons":{"A":"Incorrect because life-saving medicines have price inelastic demand.","B":"Correct selection.","C":"Incorrect because billionaire luxury buyers prioritise exclusivity and craftsmanship over low price.","D":"Incorrect because if buyers do not know the product exists, Promotion is the critical first barrier."}}},{"id":"P1_U3_MCQ_854","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_854","question":"When is 'Place' (convenient availability) likely to be the most critical element of the marketing mix?","options":{"A":"For impulse convenience items such as bottled water, umbrellas on a rainy day, or snack bars.","B":"For custom-built commercial passenger aircraft.","C":"For bespoke architectural home designs.","D":"For rare antique paintings sold at international auctions."},"correctOption":"A","correctAnswer":"For impulse convenience items such as bottled water, umbrellas on a rainy day, or snack bars.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumers buying convenience or impulse items will simply buy whichever brand is immediately available in the nearest shop or vending machine.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because airlines negotiate directly with manufacturers over technical specifications and price.","C":"Incorrect because architectural services are commissioned directly rather than bought on impulse.","D":"Incorrect because collectors travel or bid online for rare antiques regardless of convenience."}}},{"id":"P1_U3_MCQ_855","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_855","question":"In which market is 'Promotion' especially influential in differentiating similar products and driving consumer choice?","options":{"A":"Markets for raw industrial iron ore sold to steel mills.","B":"Markets for perfumes, soft drinks, and fashion trainers where brand image heavily shapes consumer preference.","C":"Government monopoly water utility supply.","D":"Wholesale bulk grain trading between farms and flour mills."},"correctOption":"B","correctAnswer":"Markets for perfumes, soft drinks, and fashion trainers where brand image heavily shapes consumer preference.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because in lifestyle and personal-image markets like perfumes and trainers, persuasive advertising and celebrity endorsement build emotional brand appeal.","distractor_reasons":{"A":"Incorrect because industrial buyers judge iron ore by chemical grade and price rather than lifestyle ads.","B":"Correct selection.","C":"Incorrect because a monopoly utility has no competitors to persuade buyers against.","D":"Incorrect because B2B agricultural buyers focus on commodity grade and price."}}},{"id":"P1_U3_MCQ_856","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_856","question":"A toy company advertises a plastic action figure on TV showing it flying across a room on its own, even though the toy cannot fly. Which legal control does this breach?","options":{"A":"Weights and measures regulations.","B":"Minimum wage employment legislation.","C":"Laws against misleading promotion and false trade descriptions.","D":"Health and safety factory noise limits."},"correctOption":"C","correctAnswer":"Laws against misleading promotion and false trade descriptions.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because consumer protection and advertising laws prohibit exaggerated or false claims about what a product can actually do.","distractor_reasons":{"A":"Incorrect because weights and measures govern quantity/weight labels, not exaggerated performance claims.","B":"Incorrect because minimum wage laws govern worker pay.","C":"Correct selection.","D":"Incorrect because factory noise limits relate to workplace operations."}}},{"id":"P1_U3_MCQ_857","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_857","question":"A cereal box states 'Net Weight: 500g', but spot checks reveal boxes consistently contain only 440g. Which area of marketing legislation has been violated?","options":{"A":"Patent infringement law.","B":"Trade union collective bargaining law.","C":"Environmental zoning regulations.","D":"Weights and measures legislation."},"correctOption":"D","correctAnswer":"Weights and measures legislation.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because weights and measures laws make it an offence to sell short-weight goods or misstate package quantities.","distractor_reasons":{"A":"Incorrect because patents protect inventions from being copied.","B":"Incorrect because trade union laws govern employee representation.","C":"Incorrect because zoning laws regulate where factories or shops may be built.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_858","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_858","question":"What happens if a business sells an electric kettle that overheats and causes burns during normal household use?","options":{"A":"It breaches consumer safety laws, forcing product recalls, legal fines, compensation claims, and severe brand damage.","B":"The customer has no legal rights once they leave the shop.","C":"The business is rewarded with lower corporation tax rates.","D":"Only the factory worker who assembled the kettle can be prosecuted, while the company faces no consequences."},"correctOption":"A","correctAnswer":"It breaches consumer safety laws, forcing product recalls, legal fines, compensation claims, and severe brand damage.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumer protection laws require goods to be safe and fit for purpose; dangerous products trigger costly recalls, penalties, and loss of trust.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because statutory consumer rights protect buyers after purchase.","C":"Incorrect because selling unsafe goods brings legal penalties rather than tax rewards.","D":"Incorrect because the business itself is legally liable for selling unsafe products."}}},{"id":"P1_U3_MCQ_859","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_859","question":"Why do many governments restrict or ban the advertising of cigarettes and alcohol to young people?","options":{"A":"To increase government spending on tobacco subsidies.","B":"To protect public health and prevent persuasive promotion from encouraging harmful consumption among minors.","C":"To help cigarette companies reduce their marketing expenses and increase profits.","D":"Because print newspapers refuse to accept money from any advertisers."},"correctOption":"B","correctAnswer":"To protect public health and prevent persuasive promotion from encouraging harmful consumption among minors.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because legal controls over promotion also aim to protect vulnerable groups and public health from harmful products.","distractor_reasons":{"A":"Incorrect because advertising bans discourage smoking rather than subsidising it.","B":"Correct selection.","C":"Incorrect because advertising restrictions limit tobacco companies' ability to attract new customers.","D":"Incorrect because newspapers depend heavily on advertising revenue."}}},{"id":"P1_U3_MCQ_860","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_860","question":"How can strict consumer protection laws create a competitive advantage for an ethical, high-quality business?","options":{"A":"They allow the ethical business to sell faulty items without giving refunds.","B":"They eliminate all costs of quality assurance testing.","C":"They force dishonest rivals out of the market or penalise them, rewarding firms that already maintain high safety and honesty standards.","D":"They permit the business to make exaggerated claims in online adverts."},"correctOption":"C","correctAnswer":"They force dishonest rivals out of the market or penalise them, rewarding firms that already maintain high safety and honesty standards.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because strong legal enforcement prevents unscrupulous competitors from undercutting responsible firms by selling unsafe or falsely described goods.","distractor_reasons":{"A":"Incorrect because all businesses must refund or replace faulty goods.","B":"Incorrect because quality assurance testing is still required.","C":"Correct selection.","D":"Incorrect because consumer laws prohibit exaggerated or misleading claims."}}},{"id":"P1_U3_MCQ_861","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_861","question":"Why do businesses often seek to enter new markets in other countries when their home market becomes 'saturated'?","options":{"A":"Because saturated domestic markets offer little room for further sales growth, whereas fast-growing foreign economies offer new demand.","B":"Because exporting goods to other countries eliminates all transport and packaging costs.","C":"Because foreign consumers never care about price or product quality.","D":"Because domestic governments ban businesses from selling to local citizens once they reach 20% market share."},"correctOption":"A","correctAnswer":"Because saturated domestic markets offer little room for further sales growth, whereas fast-growing foreign economies offer new demand.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when almost everyone in the domestic market already owns the product, expanding abroad unlocks new customers and revenue growth.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because international shipping increases transport and packaging expenses.","C":"Incorrect because foreign consumers are just as discerning about price and quality.","D":"Incorrect because no such 20% domestic sales ban exists."}}},{"id":"P1_U3_MCQ_862","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_862","question":"How does entering foreign markets help a business achieve greater 'economies of scale'?","options":{"A":"By reducing total factory output so fewer raw materials are needed.","B":"By increasing total global sales volume, allowing fixed R&D and machinery costs to be spread over more units.","C":"By forcing the business to build small, inefficient workshops in every town.","D":"By eliminating all import tariffs worldwide."},"correctOption":"B","correctAnswer":"By increasing total global sales volume, allowing fixed R&D and machinery costs to be spread over more units.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher combined domestic and export production lowers average unit costs through bulk purchasing and fuller capacity utilisation.","distractor_reasons":{"A":"Incorrect because entering new markets increases output rather than reducing it.","B":"Correct selection.","C":"Incorrect because small workshops cause diseconomies rather than economies of scale.","D":"Incorrect because tariffs are set by governments, not eliminated by a firm's expansion."}}},{"id":"P1_U3_MCQ_863","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_863","question":"How can 'language differences' create problems when a business enters a new foreign market?","options":{"A":"Foreign consumers can always understand English slogans without translation.","B":"Language differences eliminate the need to print instruction manuals.","C":"Direct translation of brand names or advertising slogans may accidentally carry offensive or nonsensical meanings in the local language.","D":"Language differences prevent businesses from using dynamic pricing."},"correctOption":"C","correctAnswer":"Direct translation of brand names or advertising slogans may accidentally carry offensive or nonsensical meanings in the local language.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because poorly translated slogans, labels, or product names can confuse or offend local buyers, requiring professional localisation.","distractor_reasons":{"A":"Incorrect because many consumers prefer or require labels and ads in their native language.","B":"Incorrect because instruction manuals and safety warnings must be accurately translated.","C":"Correct selection.","D":"Incorrect because pricing algorithms are unaffected by spoken languages."}}},{"id":"P1_U3_MCQ_864","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_864","question":"How can 'exchange rate changes' create a problem for an exporter selling products in a foreign country?","options":{"A":"Exchange rates never change between any two currencies.","B":"If the exporter's home currency appreciates (rises in value), its products become more expensive for foreign buyers, reducing sales.","C":"Exchange rate fluctuations automatically cancel all shipping insurance.","D":"Foreign retailers refuse to accept electronic bank transfers."},"correctOption":"B","correctAnswer":"If the exporter's home currency appreciates (rises in value), its products become more expensive for foreign buyers, reducing sales.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a stronger domestic currency makes exports pricier in foreign currency terms (or reduces profit margins if local prices are held steady).","distractor_reasons":{"A":"Incorrect because exchange rates fluctuate daily on foreign exchange markets.","B":"Correct selection.","C":"Incorrect because insurance contracts remain valid regardless of exchange rate shifts.","D":"Incorrect because international bank transfers are standard in global trade."}}},{"id":"P1_U3_MCQ_865","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_865","question":"How do 'import tariffs and quotas' imposed by a foreign government act as a barrier to entering that market?","options":{"A":"They lower the selling price of imported goods below local competitors.","B":"They provide free warehouse storage for foreign exporters.","C":"Tariffs tax imported goods (making them more expensive) while quotas restrict the maximum quantity allowed into the country.","D":"They force domestic consumers to buy only imported products."},"correctOption":"C","correctAnswer":"Tariffs tax imported goods (making them more expensive) while quotas restrict the maximum quantity allowed into the country.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because protectionist trade barriers raise the price or limit the volume of foreign products to protect local producers.","distractor_reasons":{"A":"Incorrect because tariffs increase, rather than lower, the price of imports.","B":"Incorrect because tariffs are taxes paid by importers, not free storage.","C":"Correct selection.","D":"Incorrect because tariffs and quotas aim to protect domestic producers, not force import purchases."}}},{"id":"P1_U3_MCQ_866","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_866","question":"Why are 'higher transport costs' a problem when exporting bulky or heavy goods to distant countries?","options":{"A":"Long-distance freight adds substantially to unit costs, forcing higher selling prices that may make the product uncompetitive against local rivals.","B":"Cargo ships and aircraft refuse to carry manufactured goods across oceans.","C":"Transport costs are always paid by the exporting country's government.","D":"Bulky goods become lighter the further they travel."},"correctOption":"A","correctAnswer":"Long-distance freight adds substantially to unit costs, forcing higher selling prices that may make the product uncompetitive against local rivals.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shipping heavy or low-value-to-weight items over long distances erodes profit margins or prices the exporter out of the foreign market.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because international shipping lines regularly transport manufactured goods.","C":"Incorrect because businesses pay their own commercial freight expenses.","D":"Incorrect because physical weight does not decrease during transit."}}},{"id":"P1_U3_MCQ_867","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_867","question":"How does forming a 'joint venture' with a local company help a business overcome the problems of entering a new foreign market?","options":{"A":"The foreign entrant gains immediate access to local market knowledge, established distribution networks, and shared capital costs.","B":"The foreign entrant keeps 100% of all profits without sharing any decision-making.","C":"It eliminates all cultural and language differences between the two countries automatically.","D":"It exempts the business from obeying the host country's tax and safety laws."},"correctOption":"A","correctAnswer":"The foreign entrant gains immediate access to local market knowledge, established distribution networks, and shared capital costs.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because partnering with an existing local firm combines the entrant's product expertise with the local partner's contacts, cultural insight, and outlets.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profits and control must be shared with the joint venture partner.","C":"Incorrect because cultural differences still exist and must even be managed between the two partners.","D":"Incorrect because joint ventures must comply fully with host-country laws."}}},{"id":"P1_U3_MCQ_868","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_868","question":"What is a potential disadvantage of entering a foreign market through a 'joint venture'?","options":{"A":"The business has to bear 100% of the financial risk alone.","B":"Disagreements may arise between the partners over strategy, quality standards, and profit sharing.","C":"The local partner has zero knowledge of domestic consumers.","D":"Joint ventures are illegal in all international markets."},"correctOption":"B","correctAnswer":"Disagreements may arise between the partners over strategy, quality standards, and profit sharing.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because differences in management styles, business culture, and objectives can create conflict between joint venture partners.","distractor_reasons":{"A":"Incorrect because sharing capital and risk is an advantage of a joint venture.","B":"Correct selection.","C":"Incorrect because local market knowledge is the main reason for choosing a local partner.","D":"Incorrect because joint ventures are a common, legal method of international expansion."}}},{"id":"P1_U3_MCQ_869","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_869","question":"How does 'licensing' help a business enter a foreign market while avoiding high transport costs and import tariffs?","options":{"A":"The business ships every finished item individually by air freight from its home factory.","B":"The business sells its entire company permanently to a foreign government.","C":"The business grants a foreign firm permission to manufacture and sell its patented product locally in return for royalty fees.","D":"The business smuggles goods across borders without paying customs duties."},"correctOption":"C","correctAnswer":"The business grants a foreign firm permission to manufacture and sell its patented product locally in return for royalty fees.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because local production by a licensee eliminates cross-border shipping and import tariffs while generating royalty income with low capital risk.","distractor_reasons":{"A":"Incorrect because air freight incurs high transport costs and tariffs.","B":"Incorrect because licensing retains ownership of the brand/patent rather than selling the whole company.","C":"Correct selection.","D":"Incorrect because smuggling is illegal."}}},{"id":"P1_U3_MCQ_870","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_870","question":"What is a risk of using 'licensing' to expand into a foreign market?","options":{"A":"The business must invest huge sums building its own overseas factories.","B":"The foreign licensee may produce poor-quality goods that harm the brand's reputation or become a future competitor.","C":"The business receives zero royalty payments even if sales are high.","D":"Licensing requires hiring thousands of domestic retail staff."},"correctOption":"B","correctAnswer":"The foreign licensee may produce poor-quality goods that harm the brand's reputation or become a future competitor.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because giving a foreign firm access to designs/technology reduces direct quality control and risks creating a future rival once the licence ends.","distractor_reasons":{"A":"Incorrect because the licensee provides the local factory capital.","B":"Correct selection.","C":"Incorrect because licensees pay agreed royalties based on sales or output.","D":"Incorrect because the licensee hires its own local workforce."}}},{"id":"P1_U3_MCQ_871","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_871","question":"How does 'international franchising' help a fast-food or retail brand expand rapidly into foreign countries?","options":{"A":"Local franchisees invest their own capital to open outlets and bring local cultural knowledge while following the franchisor's proven business model.","B":"The franchisor pays every franchisee's rent and staff wages out of its own pocket.","C":"Franchisees are free to change the brand name, menu, and logo however they wish.","D":"International franchising eliminates the need for any training or quality checks."},"correctOption":"A","correctAnswer":"Local franchisees invest their own capital to open outlets and bring local cultural knowledge while following the franchisor's proven business model.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because franchisees fund local store openings and understand local consumers while paying fees and royalties to use an established brand.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because franchisees fund their own local operating expenses.","C":"Incorrect because franchisees must follow the franchisor's brand standards, though minor local menu adaptations may be approved.","D":"Incorrect because franchisors must train franchisees and monitor quality to protect the global brand."}}},{"id":"P1_U3_MCQ_872","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_872","question":"What does 'localising existing brands' (glocalisation) involve when entering foreign markets?","options":{"A":"Selling the exact same product, recipe, and advertisement in every country without any modification.","B":"Abandoning the global brand name completely in every foreign city.","C":"Keeping the core global brand identity while adapting product flavours, packaging, or promotions to suit local cultural preferences.","D":"Refusing to sell products in any country outside the company's home continent."},"correctOption":"C","correctAnswer":"Keeping the core global brand identity while adapting product flavours, packaging, or promotions to suit local cultural preferences.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because localising a global brand (such as offering vegetarian or spicy regional menu options at global fast-food chains) respects local tastes while leveraging global brand recognition.","distractor_reasons":{"A":"Incorrect because an unadapted global approach ignores local cultural and dietary differences.","B":"Incorrect because localisation preserves the core brand identity rather than abandoning it.","C":"Correct selection.","D":"Incorrect because localisation is a strategy specifically used for international expansion."}}},{"id":"P1_U3_MCQ_873","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_873","question":"A global fast-food chain enters a country where most consumers do not eat beef for religious reasons. Which marketing strategy adjustment is essential?","options":{"A":"Keep beef burgers as the sole menu item and run ads telling locals to change their diet.","B":"Double the price of all meals to offset expected low customer numbers.","C":"Close all restaurants during lunchtime and dinner hours.","D":"Replace beef items with chicken, fish, and vegetarian burgers while ensuring local cultural compliance."},"correctOption":"D","correctAnswer":"Replace beef items with chicken, fish, and vegetarian burgers while ensuring local cultural compliance.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because adapting the Product element to respect religious and dietary norms is vital for acceptance and sales in the new market.","distractor_reasons":{"A":"Incorrect because ignoring religious dietary restrictions will cause the business to fail.","B":"Incorrect because high prices will further deter local customers.","C":"Incorrect because closing at peak meal times destroys restaurant revenue.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_874","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_874","question":"A high-end smartphone maker wants to enter a developing country where average household incomes are significantly lower than in its home market. Which strategy adjustment is most appropriate?","options":{"A":"Introduce a more affordable, slightly simplified model or offer monthly instalment plans while highlighting durability.","B":"Raise the phone's price by 40% above its home-country luxury price.","C":"Sell the phone exclusively in five-star airport lounges.","D":"Advertise only in print magazines written in a foreign language."},"correctOption":"A","correctAnswer":"Introduce a more affordable, slightly simplified model or offer monthly instalment plans while highlighting durability.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because adjusting Product specifications and Price/payment terms to match lower disposable incomes makes the brand accessible to the new market.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raising prices where incomes are lower will prevent almost all sales.","C":"Incorrect because restricting Place to airport lounges misses the wider domestic market.","D":"Incorrect because foreign-language print ads will not reach local consumers effectively."}}},{"id":"P1_U3_MCQ_875","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_875","question":"Before finalising a marketing strategy to launch a new product in a foreign country, why must managers review all four elements of the marketing mix together?","options":{"A":"To ensure that Product, Price, Place, and Promotion support each other, fit the local target segment, comply with local laws, and stay within budget.","B":"Because international law requires every exporter to use price skimming and wholesalers.","C":"To guarantee that exchange rates and competitor prices remain frozen for ten years.","D":"Because once a marketing strategy is chosen, it can never be changed again."},"correctOption":"A","correctAnswer":"To ensure that Product, Price, Place, and Promotion support each other, fit the local target segment, comply with local laws, and stay within budget.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an effective international marketing strategy integrates all four Ps harmoniously while respecting budget limits, local culture, and legal controls.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses choose pricing and distribution methods suited to their specific product and market.","C":"Incorrect because exchange rates and competitors constantly change.","D":"Incorrect because marketing strategies must be reviewed and adapted continuously as market conditions evolve."}}},{"id":"P1_U3_MCQ_876","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_876","question":"Why is identifying customer needs before designing a product essential for business survival?","options":{"A":"It ensures the business produces goods that consumers actually want and are willing to buy.","B":"It eliminates all fixed overhead expenses in the factory.","C":"It prevents competitors from lowering their prices.","D":"It guarantees that government taxes on sales are reduced."},"correctOption":"A","correctAnswer":"It ensures the business produces goods that consumers actually want and are willing to buy.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because aligning products with genuine customer needs reduces the risk of unsold stock and business failure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fixed overheads still exist regardless of customer research.","C":"Incorrect because identifying customer needs does not stop rivals from changing prices.","D":"Incorrect because sales tax rates are set by governments, not marketing."}}},{"id":"P1_U3_MCQ_877","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_877","question":"Total sales in the electric scooter market are $80 million. Brand Z generates annual sales of $24 million. What is Brand Z's market share?","options":{"A":"20%","B":"30%","C":"33%","D":"40%"},"correctOption":"B","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ($24 million / $80 million) x 100 = 30%.","distractor_reasons":{"A":"Incorrect because 20% of $80 million is $16 million.","B":"Correct selection.","C":"Incorrect because 33% of $80 million is approximately $26.4 million.","D":"Incorrect because 40% of $80 million is $32 million."}}},{"id":"P1_U3_MCQ_878","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_878","question":"How does rapid innovation in mobile apps and streaming platforms change consumer spending patterns?","options":{"A":"Consumers spend more money on physical newspapers and printed maps.","B":"Consumers stop purchasing smartphones and internet subscriptions.","C":"Consumers shift spending toward digital subscriptions and on-demand services.","D":"Consumers buy identical technology products for twenty years without upgrading."},"correctOption":"C","correctAnswer":"Consumers shift spending toward digital subscriptions and on-demand services.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because technological convenience shifts consumer expenditure from physical media toward digital platforms.","distractor_reasons":{"A":"Incorrect because digital apps have reduced demand for printed maps and newspapers.","B":"Incorrect because demand for smartphones and broadband has grown alongside streaming.","C":"Correct selection.","D":"Incorrect because rapid tech advances shorten replacement cycles."}}},{"id":"P1_U3_MCQ_879","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_879","question":"Which factor best explains why a niche manufacturer of vegan leather handbags can survive alongside huge global fashion brands?","options":{"A":"It achieves greater purchasing economies of scale than global corporations.","B":"It sells identical bags to every consumer segment at discount prices.","C":"It has no variable costs when sourcing plant-based materials.","D":"It caters closely to the ethical values of a specific consumer group overlooked by mass-market rivals."},"correctOption":"D","correctAnswer":"It caters closely to the ethical values of a specific consumer group overlooked by mass-market rivals.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because niche businesses succeed by meeting specialised needs and values that standardised mass-market brands miss.","distractor_reasons":{"A":"Incorrect because small niche firms have lower output and fewer economies of scale than global brands.","B":"Incorrect because niche firms focus on specialised segments rather than mass discounting.","C":"Incorrect because vegan leather materials still incur variable costs.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_880","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_880","question":"What happens to a niche business if consumer preferences suddenly shift away from its single specialised product?","options":{"A":"The business faces a high risk of failure because its small customer base offers no alternative demand.","B":"The business automatically transforms into a mass-market monopoly.","C":"Its fixed costs immediately fall to zero.","D":"Its market share increases to 100%."},"correctOption":"A","correctAnswer":"The business faces a high risk of failure because its small customer base offers no alternative demand.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because relying on one small, specialised segment leaves a niche firm highly vulnerable when tastes change.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because falling demand shrinks the business rather than making it a mass-market leader.","C":"Incorrect because fixed overheads such as rent remain even when sales drop.","D":"Incorrect because market share does not protect a firm when total segment demand disappears."}}},{"id":"P1_U3_MCQ_881","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_881","question":"Which characteristic defines a product sold in a mass market?","options":{"A":"Custom-engineered to one individual buyer's blueprints.","B":"Standardised design aimed at appealing to the largest possible number of consumers.","C":"Sold exclusively in a single luxury boutique.","D":"Priced above the reach of 99% of households."},"correctOption":"B","correctAnswer":"Standardised design aimed at appealing to the largest possible number of consumers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because mass-market goods are standardised to satisfy broad, common consumer needs at high sales volumes.","distractor_reasons":{"A":"Incorrect because one-off custom items represent bespoke job production rather than mass markets.","B":"Correct selection.","C":"Incorrect because mass-market products require wide distribution across many outlets.","D":"Incorrect because mass-market goods are priced affordably for wide appeal."}}},{"id":"P1_U3_MCQ_882","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_882","question":"A travel agency offers budget coach tours for retired seniors, adventure backpacking trips for students, and luxury beach resorts for high-income families. Which marketing concept is this?","options":{"A":"Undifferentiated mass marketing.","B":"Product orientation.","C":"Market segmentation.","D":"Price skimming."},"correctOption":"C","correctAnswer":"Market segmentation.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the agency divides the travel market by age, income, and lifestyle to tailor distinct holiday packages to each group.","distractor_reasons":{"A":"Incorrect because undifferentiated marketing offers one identical product to everyone.","B":"Incorrect because tailoring packages to distinct customer groups is market-oriented segmentation.","C":"Correct selection.","D":"Incorrect because price skimming is launching a single innovative product at a high initial price."}}},{"id":"P1_U3_MCQ_883","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_883","question":"Which segmentation factor is being applied when a skincare brand develops separate product lines for men and women?","options":{"A":"Location segmentation.","B":"Income segmentation.","C":"Use of product segmentation.","D":"Gender segmentation."},"correctOption":"D","correctAnswer":"Gender segmentation.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because dividing consumers into male and female target groups is gender segmentation.","distractor_reasons":{"A":"Incorrect because location segmentation groups buyers by geographic region.","B":"Incorrect because income segmentation divides buyers by earnings.","C":"Incorrect because product usage divides buyers by how or how often they use an item.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_884","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_884","question":"How does rising competition from low-cost overseas imports affect domestic manufacturers?","options":{"A":"It forces domestic firms to improve efficiency, differentiate products, or risk losing market share.","B":"It allows domestic firms to raise prices without improving product quality.","C":"It removes the need for domestic firms to advertise their brands.","D":"It guarantees higher profit margins for all local producers."},"correctOption":"A","correctAnswer":"It forces domestic firms to improve efficiency, differentiate products, or risk losing market share.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cheaper foreign rivals put downward pressure on prices and force domestic producers to cut costs or innovate.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raising prices without adding value drives buyers toward cheaper imports.","C":"Incorrect because stronger competition makes brand promotion even more important.","D":"Incorrect because intense competition typically squeezes profit margins."}}},{"id":"P1_U3_MCQ_885","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_885","question":"Why do multinational businesses often adjust their product designs when segmenting markets by geographic location?","options":{"A":"Because transport laws ban identical goods from crossing national borders.","B":"Because climate, cultural traditions, and local infrastructure differ across regions.","C":"Because geographic segmentation eliminates all marketing research costs.","D":"Because consumers in every country have identical income levels."},"correctOption":"B","correctAnswer":"Because climate, cultural traditions, and local infrastructure differ across regions.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because regional climate (e.g. cold vs tropical) and cultural norms directly affect what products consumers need.","distractor_reasons":{"A":"Incorrect because identical goods can legally cross borders unless they breach local standards.","B":"Correct selection.","C":"Incorrect because researching regional differences still requires market research.","D":"Incorrect because incomes vary substantially across regions and countries."}}},{"id":"P1_U3_MCQ_886","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_886","question":"What is a key difference between a customer and a consumer?","options":{"A":"A customer always operates in the public sector, whereas a consumer is in the private sector.","B":"A customer manufactures the product, whereas a consumer delivers it to shops.","C":"A customer buys the product, whereas a consumer is the end user who actually uses or consumes it.","D":"A customer buys only online, whereas a consumer buys only in physical stores."},"correctOption":"C","correctAnswer":"A customer buys the product, whereas a consumer is the end user who actually uses or consumes it.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the buyer (e.g. a parent buying baby food or toys) is the customer, while the person using the item (the child) is the consumer.","distractor_reasons":{"A":"Incorrect because both customers and consumers exist in private and public markets.","B":"Incorrect because manufacturers and distributors are producers/intermediaries, not customers or consumers.","C":"Correct selection.","D":"Incorrect because shopping channel does not define customer versus consumer."}}},{"id":"P1_U3_MCQ_887","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_887","question":"Why should a children's breakfast cereal brand consider both the consumer and the customer in its marketing?","options":{"A":"Because children earn high salaries and pay for groceries themselves.","B":"Because parents never check nutritional labels before buying food.","C":"Because laws require children to approve all supermarket price tags.","D":"Because children influence what cereal they want to eat, while parents make the final purchasing decision."},"correctOption":"D","correctAnswer":"Because children influence what cereal they want to eat, while parents make the final purchasing decision.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because appealing packaging attracts the child (consumer) while health/value messages reassure the parent (customer).","distractor_reasons":{"A":"Incorrect because children do not earn salaries to pay for household groceries.","B":"Incorrect because parents frequently evaluate nutrition and price as customers.","C":"Incorrect because no such law exists.","D":"Correct selection."}}},{"id":"P1_U3_MCQ_888","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_888","question":"Why is a market-oriented approach generally less risky than a product-oriented approach when launching consumer goods?","options":{"A":"It bases product design on proven customer demand identified through research before committing production funds.","B":"It avoids spending any money on prototypes or product testing.","C":"It guarantees that competitors cannot launch rival products.","D":"It eliminates all variable costs of raw materials."},"correctOption":"A","correctAnswer":"It bases product design on proven customer demand identified through research before committing production funds.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because researching buyer preferences beforehand reduces the likelihood of producing goods that fail to sell.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because market-oriented firms still build and test prototypes with target consumers.","C":"Incorrect because rivals can still launch competing products.","D":"Incorrect because raw materials still carry variable costs."}}},{"id":"P1_U3_MCQ_889","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_889","question":"In which industry is a product-oriented approach still commonly found?","options":{"A":"Fast-fashion clothing retailing.","B":"Pharmaceutical research and specialised scientific or engineering equipment.","C":"Supermarket breakfast cereal production.","D":"High-street coffee shop chains."},"correctOption":"B","correctAnswer":"Pharmaceutical research and specialised scientific or engineering equipment.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because medical drugs and advanced engineering rely heavily on scientific breakthroughs and technical performance before markets are developed.","distractor_reasons":{"A":"Incorrect because fast fashion is strongly market-oriented, tracking rapid consumer trends.","B":"Correct selection.","C":"Incorrect because packaged foods rely heavily on consumer taste and market research.","D":"Incorrect because coffee chains adapt menus closely to customer preferences."}}},{"id":"P1_U3_MCQ_890","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_890","question":"Which of the following questions in a questionnaire collects 'qualitative' data?","options":{"A":"How many times did you visit our cinema last month? (0 / 1-2 / 3+)","B":"What is your annual household income bracket?","C":"Please explain in your own words what you disliked about our online ticket booking process.","D":"On a scale of 1 to 5, how satisfied were you with the seat comfort?"},"correctOption":"C","correctAnswer":"Please explain in your own words what you disliked about our online ticket booking process.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because open-ended descriptive opinions about reasons and experiences constitute qualitative data.","distractor_reasons":{"A":"Incorrect because visit frequency produces numerical quantitative data.","B":"Incorrect because income brackets produce numerical quantitative data.","C":"Correct selection.","D":"Incorrect because numerical rating scales generate quantitative scores."}}},{"id":"P1_U3_MCQ_891","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_891","question":"Why is 'quantitative' market research data useful for business decision-making?","options":{"A":"It is easy to analyse statistically and present in charts to measure market size and percentage preferences.","B":"It always reveals the deep psychological motives behind every consumer choice.","C":"It requires no sample selection or questionnaire planning.","D":"It is always free from any wording bias."},"correctOption":"A","correctAnswer":"It is easy to analyse statistically and present in charts to measure market size and percentage preferences.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because numerical data from large samples can be quickly counted, compared, and turned into percentages and graphs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because uncovering deep motives is the strength of qualitative research.","C":"Incorrect because quantitative surveys still require careful sampling and question design.","D":"Incorrect because poorly worded quantitative questions can still produce biased figures."}}},{"id":"P1_U3_MCQ_892","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_892","question":"A toy manufacturer reviews national birth rate statistics from the government's official website before planning next year's production. What type of research is this?","options":{"A":"Primary field observation.","B":"External secondary desk research.","C":"Focus group qualitative research.","D":"Internal primary survey research."},"correctOption":"B","correctAnswer":"External secondary desk research.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because government statistics are already published by an external organisation, making them external secondary data.","distractor_reasons":{"A":"Incorrect because no live consumer behaviour is being watched first-hand.","B":"Correct selection.","C":"Incorrect because no group discussion is taking place.","D":"Incorrect because the data comes from an external government source rather than internal records."}}},{"id":"P1_U3_MCQ_893","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_893","question":"Why might a business look at its own customer complaints log as part of market research?","options":{"A":"It is an inexpensive internal secondary source that highlights recurring product or service faults.","B":"It provides primary data on what non-customers think of rival brands.","C":"It shows the exact market share of every foreign competitor.","D":"It replaces the need for quality assurance in the factory."},"correctOption":"A","correctAnswer":"It is an inexpensive internal secondary source that highlights recurring product or service faults.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because existing company records of complaints provide ready-made internal secondary insights into areas needing improvement.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because company complaint logs reflect existing customers rather than non-customers.","C":"Incorrect because internal logs do not measure competitors' sales.","D":"Incorrect because complaint logs identify problems after they occur rather than preventing defects."}}},{"id":"P1_U3_MCQ_894","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_894","question":"What is a major advantage of conducting interviews by telephone rather than face-to-face on the street?","options":{"A":"Interviewers can show physical product prototypes and packaging designs.","B":"Respondents never hang up before finishing a long questionnaire.","C":"It covers a wide geographic area quickly at lower travel cost than in-person interviews.","D":"It completely eliminates interviewer tone bias."},"correctOption":"C","correctAnswer":"It covers a wide geographic area quickly at lower travel cost than in-person interviews.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because telephone interviewers can contact respondents nationwide from one office without travel expenses.","distractor_reasons":{"A":"Incorrect because visual prototypes cannot be shown over a standard voice call.","B":"Incorrect because telephone respondents frequently hang up early.","C":"Correct selection.","D":"Incorrect because an interviewer's voice and phrasing can still influence replies."}}},{"id":"P1_U3_MCQ_895","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_895","question":"Why are focus groups expensive per participant compared to online questionnaires?","options":{"A":"Each participant must be flown to a foreign country.","B":"They require hiring a trained moderator, renting a venue, and often paying incentives to participants.","C":"Focus groups must include at least 10,000 participants per session.","D":"Government taxes are charged on every question asked in a group."},"correctOption":"B","correctAnswer":"They require hiring a trained moderator, renting a venue, and often paying incentives to participants.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because facilitating a small group discussion requires a skilled moderator, facility costs, and participant rewards for their time.","distractor_reasons":{"A":"Incorrect because focus groups are usually recruited locally or hosted online.","B":"Correct selection.","C":"Incorrect because focus groups typically involve only 6 to 10 people.","D":"Incorrect because no government tax applies to asking research questions."}}},{"id":"P1_U3_MCQ_896","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_896","question":"A soft drinks company places 10,000 names of registered loyalty app users into a computer program that randomly selects 500 people to receive a survey. Which sampling method is used?","options":{"A":"Quota sampling.","B":"Random sampling.","C":"Observation sampling.","D":"Secondary sampling."},"correctOption":"B","correctAnswer":"Random sampling.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because every person on the list has an equal chance of being chosen purely by chance.","distractor_reasons":{"A":"Incorrect because respondents were not selected to fill specific demographic quotas.","B":"Correct selection.","C":"Incorrect because observation watches behaviour rather than sending surveys.","D":"Incorrect because this is primary survey research."}}},{"id":"P1_U3_MCQ_897","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_897","question":"Why might a business choose 'quota sampling' over 'random sampling' when conducting street interviews?","options":{"A":"Because quota sampling requires no complete list of the entire population and ensures key demographic groups are represented.","B":"Because quota sampling completely removes all human interviewer bias.","C":"Because random sampling is illegal in public shopping centres.","D":"Because quota sampling requires surveying 100% of the country's residents."},"correctOption":"A","correctAnswer":"Because quota sampling requires no complete list of the entire population and ensures key demographic groups are represented.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because researchers rarely have a full directory of every shopper, so setting age/gender quotas ensures balanced representation quickly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because interviewers still choose whom to approach within each quota, creating potential bias.","C":"Incorrect because random sampling is legal.","D":"Incorrect because surveying 100% of residents is a census, not sampling."}}},{"id":"P1_U3_MCQ_898","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_898","question":"A survey asks respondents: 'How much money do you spend on clothes? [ ] $10-$50 [ ] $50-$100'. Why is this question flawed?","options":{"A":"The answer categories overlap at $50, causing confusion over which box to tick.","B":"It uses too many technical engineering terms.","C":"Respondents cannot answer questions about clothing purchases.","D":"It forces respondents to write a 500-word essay."},"correctOption":"A","correctAnswer":"The answer categories overlap at $50, causing confusion over which box to tick.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because overlapping numerical ranges ($10–$50 and $50–$100) create ambiguity and reduce data accuracy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the wording is simple and non-technical.","C":"Incorrect because clothing expenditure is a standard consumer survey topic.","D":"Incorrect because it is a closed tick-box question."}}},{"id":"P1_U3_MCQ_899","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_899","question":"Why should a business treat 6-year-old market research data on smartphone usage with caution?","options":{"A":"Because consumer technology habits and competitor offerings change rapidly, making older data out of date.","B":"Because smartphone prices never change over six years.","C":"Because secondary data older than five years cannot be read.","D":"Because 6-year-old data is always forged by competitors."},"correctOption":"A","correctAnswer":"Because consumer technology habits and competitor offerings change rapidly, making older data out of date.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fast-moving industries evolve quickly, so outdated secondary statistics no longer reflect current market conditions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because prices and features shift constantly in electronics.","C":"Incorrect because older data can still be read, though its relevance is limited.","D":"Incorrect because the limitation is obsolescence rather than deliberate forgery."}}},{"id":"P1_U3_MCQ_900","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_900","question":"Which type of product is a custom-built accounting software system sold to medium-sized businesses?","options":{"A":"Consumer convenience good.","B":"Producer service / business-to-business (B2B) product.","C":"Fast-moving consumer good (FMCG).","D":"Primary raw material."},"correctOption":"B","correctAnswer":"Producer service / business-to-business (B2B) product.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because accounting software is purchased by other businesses to support their operations rather than by household consumers.","distractor_reasons":{"A":"Incorrect because convenience goods are everyday household items like bread or soap.","B":"Correct selection.","C":"Incorrect because FMCGs are low-cost, frequently bought consumer items.","D":"Incorrect because software is a tertiary/quaternary digital product, not a raw material."}}},{"id":"P1_U3_MCQ_901","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_901","question":"How does a strong brand name help a business launch new products in the future?","options":{"A":"Consumers who already trust the brand are more willing to try new items released under the same brand name.","B":"It eliminates all research and development expenses for future products.","C":"It prevents retailers from charging any profit margin on new items.","D":"It legally stops rivals from inventing similar products."},"correctOption":"A","correctAnswer":"Consumers who already trust the brand are more willing to try new items released under the same brand name.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because positive brand reputation transfers trust to brand extensions, lowering launch resistance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because new products still require R&D investment.","C":"Incorrect because retailers still take margins on branded goods.","D":"Incorrect because brand names are protected by trademarks, whereas inventions require patents."}}},{"id":"P1_U3_MCQ_902","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_902","question":"Besides protecting a product from damage, how does packaging help a business comply with marketing laws?","options":{"A":"By hiding the product's weight and ingredients from shoppers.","B":"By displaying required safety warnings, ingredients, and net weight information clearly.","C":"By increasing the retail price above competitors.","D":"By preventing consumers from returning faulty goods."},"correctOption":"B","correctAnswer":"By displaying required safety warnings, ingredients, and net weight information clearly.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consumer protection regulations require accurate labelling of contents, allergens, weights, and safety instructions on packaging.","distractor_reasons":{"A":"Incorrect because hiding weights or ingredients violates consumer laws.","B":"Correct selection.","C":"Incorrect because legal compliance does not mandate charging higher prices than rivals.","D":"Incorrect because packaging cannot override statutory consumer refund rights."}}},{"id":"P1_U3_MCQ_903","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_903","question":"Why do many products fail shortly after the 'introduction' stage of the Product Life Cycle?","options":{"A":"Sales growth is too fast for factories to keep up with demand.","B":"Fixed costs are zero during the launch phase.","C":"High launch promotion and R&D costs are not recovered due to weak consumer awareness or poor product-market fit.","D":"Consumers are already bored with the product after ten years on sale."},"correctOption":"C","correctAnswer":"High launch promotion and R&D costs are not recovered due to weak consumer awareness or poor product-market fit.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash outflows are heavy at introduction, and if buyers reject the product, losses force early withdrawal.","distractor_reasons":{"A":"Incorrect because slow initial sales, not excessive demand, cause launch failure.","B":"Incorrect because R&D and launch marketing represent heavy upfront costs.","C":"Correct selection.","D":"Incorrect because long-term market saturation describes maturity or decline, not introduction."}}},{"id":"P1_U3_MCQ_904","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_904","question":"Which Product Life Cycle stage is typically associated with the highest positive cash flow and profits for a business?","options":{"A":"Development.","B":"Introduction.","C":"Maturity.","D":"Decline."},"correctOption":"C","correctAnswer":"Maturity.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because in maturity, initial R&D costs have been recovered, sales volume is at its peak, and economies of scale keep unit costs low.","distractor_reasons":{"A":"Incorrect because development has zero revenue and heavy R&D outflows.","B":"Incorrect because introduction usually makes losses due to low sales and high launch advertising.","C":"Correct selection.","D":"Incorrect because falling sales and price discounts reduce profitability in decline."}}},{"id":"P1_U3_MCQ_905","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_905","question":"A chocolate bar brand has been in the maturity stage for five years and sales are starting to flatten. Which action is an effective extension strategy?","options":{"A":"Launching a limited-edition salted caramel flavour and updating the wrapper design.","B":"Removing the chocolate bar from all supermarkets.","C":"Stopping all advertising and raising the price by 50%.","D":"Reducing the cocoa quality while keeping the price unchanged."},"correctOption":"A","correctAnswer":"Launching a limited-edition salted caramel flavour and updating the wrapper design.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because introducing new flavour variations and refreshed packaging stimulates renewed consumer interest and delays decline.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cutting distribution reduces sales immediately.","C":"Incorrect because cutting promotion while raising price accelerates decline.","D":"Incorrect because lowering quality alienates loyal customers."}}},{"id":"P1_U3_MCQ_906","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_906","question":"A bakery makes 500 loaves of artisan bread at a total cost of $1,000. If it uses cost-plus pricing with a 50% mark-up, what is the price of one loaf?","options":{"A":"$2.00","B":"$2.50","C":"$3.00","D":"$3.50"},"correctOption":"C","correctAnswer":"$3.00","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unit cost is $1,000 / 500 = $2.00, and adding a 50% mark-up ($1.00) gives $3.00 per loaf.","distractor_reasons":{"A":"Incorrect because $2.00 is the average unit cost before adding the mark-up.","B":"Incorrect because $2.50 is only a 25% mark-up.","C":"Correct selection.","D":"Incorrect because $3.50 is a 75% mark-up."}}},{"id":"P1_U3_MCQ_907","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_907","question":"Why might a business using cost-plus pricing fail to make a profit even if it adds a 30% mark-up to its estimated unit cost?","options":{"A":"If actual sales volume is much lower than forecast, fixed costs per unit will be higher than expected and unsold stock may not cover overheads.","B":"Because cost-plus pricing forbids businesses from selling to retailers.","C":"Because variable costs disappear once a mark-up is added.","D":"Because 30% mark-ups are illegal in competitive markets."},"correctOption":"A","correctAnswer":"If actual sales volume is much lower than forecast, fixed costs per unit will be higher than expected and unsold stock may not cover overheads.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because average unit cost depends on assumed output; if high prices deter buyers and sales fall short, fixed costs are not fully recovered.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cost-plus pricing can be used when selling to retailers or consumers.","C":"Incorrect because variable costs still exist for every unit made.","D":"Incorrect because businesses can set any legal mark-up percentage."}}},{"id":"P1_U3_MCQ_908","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_908","question":"When is 'price skimming' most likely to succeed?","options":{"A":"When launching an identical bottle of tap water in a crowded supermarket.","B":"When launching a breakthrough medical device or gaming console with strong patent protection and eager early adopters.","C":"When clearing outdated winter coats at the end of spring.","D":"When targeting low-income shoppers in a highly price-sensitive commodity market."},"correctOption":"B","correctAnswer":"When launching a breakthrough medical device or gaming console with strong patent protection and eager early adopters.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unique, innovative products with little immediate competition can command high prices from buyers willing to pay for the latest technology.","distractor_reasons":{"A":"Incorrect because identical commodities require competitive pricing.","B":"Correct selection.","C":"Incorrect because end-of-season clearance requires promotional markdown pricing.","D":"Incorrect because price-sensitive low-income markets require penetration or value pricing."}}},{"id":"P1_U3_MCQ_909","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_909","question":"Why do businesses using 'price skimming' usually lower their prices several months or a year after launch?","options":{"A":"To attract more price-sensitive customer segments once early adopters have bought the product and competitors enter the market.","B":"Because unit production costs always double after the first year.","C":"Because consumer protection laws force all prices down after six months.","D":"To destroy their own brand reputation for quality."},"correctOption":"A","correctAnswer":"To attract more price-sensitive customer segments once early adopters have bought the product and competitors enter the market.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because once the initial wave of high-paying early adopters is satisfied and rivals emerge, lowering the price expands sales into the wider market.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because unit costs generally fall over time due to economies of scale and experience.","C":"Incorrect because laws do not force businesses to lower prices after six months.","D":"Incorrect because gradual price reductions are planned to reach broader market segments."}}},{"id":"P1_U3_MCQ_910","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_910","question":"How does 'penetration pricing' help a new entrant overcome strong brand loyalty toward existing competitors?","options":{"A":"By charging a much higher price than established brands to look superior.","B":"By offering a noticeably lower introductory price that tempts buyers to switch and try the new brand.","C":"By refusing to advertise the product until prices are raised.","D":"By selling the product exclusively through overseas agents."},"correctOption":"B","correctAnswer":"By offering a noticeably lower introductory price that tempts buyers to switch and try the new brand.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a low launch price reduces the financial risk for consumers trying an unfamiliar brand, helping build rapid market share.","distractor_reasons":{"A":"Incorrect because charging more for an unknown brand in a crowded market deters buyers.","B":"Correct selection.","C":"Incorrect because heavy promotion is needed alongside penetration pricing so buyers know about the low price.","D":"Incorrect because penetration pricing usually targets broad domestic mass distribution."}}},{"id":"P1_U3_MCQ_911","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_911","question":"Which of the following is an example of 'psychological pricing'?","options":{"A":"Pricing a jacket at $99.99 instead of $100.00 so consumers perceive it as significantly cheaper.","B":"Adding a 20% profit mark-up onto total factory cost.","C":"Raising airline ticket prices automatically when only three seats remain.","D":"Charging every customer the exact average cost of production."},"correctOption":"A","correctAnswer":"Pricing a jacket at $99.99 instead of $100.00 so consumers perceive it as significantly cheaper.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pricing just below a round number ($99.99 vs $100) or setting high prestige prices appeals to consumer psychology rather than pure cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because adding a fixed percentage to cost is cost-plus pricing.","C":"Incorrect because real-time capacity pricing is dynamic pricing.","D":"Incorrect because pricing at average cost leaves zero profit."}}},{"id":"P1_U3_MCQ_912","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_912","question":"A cinema raises evening weekend ticket prices by 15% and finds that total ticket revenue increases. What does this indicate about demand for weekend evening tickets?","options":{"A":"Demand is price elastic.","B":"Demand is price inelastic.","C":"Demand is completely zero.","D":"Fixed costs have decreased."},"correctOption":"B","correctAnswer":"Demand is price inelastic.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when a price increase leads to higher total sales revenue, the percentage drop in ticket sales was smaller than the 15% price rise (price inelastic).","distractor_reasons":{"A":"Incorrect because if demand were price elastic, a 15% price rise would cause total revenue to fall.","B":"Correct selection.","C":"Incorrect because zero demand would yield zero revenue.","D":"Incorrect because revenue changes reflect demand elasticity rather than fixed costs."}}},{"id":"P1_U3_MCQ_913","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_913","question":"Which distribution channel is used when an airline sells flight tickets directly to passengers through its own mobile app?","options":{"A":"Producer -> Wholesaler -> Retailer -> Consumer.","B":"Producer -> Agent -> Retailer -> Consumer.","C":"Producer -> Direct to Consumer.","D":"Producer -> Wholesaler -> Consumer."},"correctOption":"C","correctAnswer":"Producer -> Direct to Consumer.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because selling via the company's own app bypasses travel agents and third-party intermediaries.","distractor_reasons":{"A":"Incorrect because no wholesalers or retailers are involved.","B":"Incorrect because travel agents are bypassed when passengers book on the airline's app.","C":"Correct selection.","D":"Incorrect because no wholesaler is used."}}},{"id":"P1_U3_MCQ_914","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_914","question":"Why do small independent grocery stores rely heavily on wholesalers?","options":{"A":"Because manufacturers often refuse to deliver very small quantities to thousands of individual corner shops.","B":"Because wholesalers manufacture all food items inside their warehouses.","C":"Because laws ban small shops from buying directly from any supplier.","D":"Because wholesalers sell goods to shops completely free of charge."},"correctOption":"A","correctAnswer":"Because manufacturers often refuse to deliver very small quantities to thousands of individual corner shops.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because wholesalers break bulk, allowing small retailers to buy mixed cases of many brands in small, affordable quantities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because wholesalers distribute goods made by manufacturers rather than producing them.","C":"Incorrect because small shops can buy directly if a producer accepts small orders, though it is rarely economical.","D":"Incorrect because wholesalers charge retailers a price that includes their wholesale profit margin."}}},{"id":"P1_U3_MCQ_915","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_915","question":"What is a disadvantage to a manufacturer of selling through large national retail chains?","options":{"A":"The product is hidden from mass-market shoppers.","B":"Large retailers have strong buying power and may demand heavy discounts, squeezing the manufacturer's profit margin.","C":"The manufacturer must deliver single items directly to every consumer's house.","D":"Retailers refuse to use barcode scanners."},"correctOption":"B","correctAnswer":"Large retailers have strong buying power and may demand heavy discounts, squeezing the manufacturer's profit margin.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because major supermarket and retail chains account for huge sales volumes, giving them bargaining power to negotiate low wholesale prices and promotional fees.","distractor_reasons":{"A":"Incorrect because national retail chains provide wide visibility to shoppers.","B":"Correct selection.","C":"Incorrect because manufacturers deliver in bulk to the retailer's distribution depots.","D":"Incorrect because large retailers use advanced EPOS barcode technology."}}},{"id":"P1_U3_MCQ_916","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_916","question":"How does using an 'agent' benefit a medium-sized manufacturer entering an unfamiliar overseas market for the first time?","options":{"A":"The agent provides local market expertise, language fluency, and buyer contacts without requiring the manufacturer to open foreign offices.","B":"The agent buys the manufacturer's domestic factories.","C":"The agent guarantees that foreign exchange rates will never change.","D":"The agent works without receiving any commission or payment."},"correctOption":"A","correctAnswer":"The agent provides local market expertise, language fluency, and buyer contacts without requiring the manufacturer to open foreign offices.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because local agents already know the foreign market's regulations, culture, and buyers, reducing entry risk and fixed overhead.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because agents arrange sales rather than purchasing factories.","C":"Incorrect because agents have no control over currency exchange rates.","D":"Incorrect because agents earn a commission percentage on sales arranged."}}},{"id":"P1_U3_MCQ_917","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_917","question":"Which product is least suitable for selling solely through an e-commerce website?","options":{"A":"E-books and downloadable music tracks.","B":"Hotel room bookings and airline tickets.","C":"Freshly poured hot restaurant meals delivered 500 miles away.","D":"Standardised paperback books and computer accessories."},"correctOption":"C","correctAnswer":"Freshly poured hot restaurant meals delivered 500 miles away.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because hot prepared food spoils and cools rapidly, making long-distance parcel shipping impractical.","distractor_reasons":{"A":"Incorrect because digital downloads are ideal for e-commerce.","B":"Incorrect because travel and accommodation bookings are among the most successful e-commerce sectors.","C":"Correct selection.","D":"Incorrect because durable packaged items ship easily via e-commerce."}}},{"id":"P1_U3_MCQ_918","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_918","question":"How can a business use its e-commerce website to improve its 'Promotion' as well as its 'Place'?","options":{"A":"By hiding all product prices until after the customer pays.","B":"By showcasing product videos, customer reviews, special online discount codes, and newsletter sign-ups.","C":"By preventing search engines from listing the website.","D":"By removing all brand logos from the homepage."},"correctOption":"B","correctAnswer":"By showcasing product videos, customer reviews, special online discount codes, and newsletter sign-ups.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a website acts simultaneously as a direct sales outlet (Place) and an interactive promotional showcase (Promotion).","distractor_reasons":{"A":"Incorrect because hiding prices is deceptive and drives visitors away.","B":"Correct selection.","C":"Incorrect because businesses use search engine optimisation to attract visitors.","D":"Incorrect because strong branding on a website reinforces brand image."}}},{"id":"P1_U3_MCQ_919","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_919","question":"What is a major advantage of radio advertising for a regional retail business?","options":{"A":"Viewers can watch high-definition video demonstrations of the product.","B":"It is much cheaper than television advertising and reaches local commuters effectively.","C":"Listeners can click directly on a radio broadcast to buy items.","D":"The advert remains visible in listeners' homes for several weeks like a magazine."},"correctOption":"B","correctAnswer":"It is much cheaper than television advertising and reaches local commuters effectively.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because local radio stations charge far less than TV while reaching regional audiences during daily drives and work hours.","distractor_reasons":{"A":"Incorrect because radio is audio-only without visual imagery.","B":"Correct selection.","C":"Incorrect because traditional radio lacks clickable links.","D":"Incorrect because radio messages are brief and transient rather than permanent like print."}}},{"id":"P1_U3_MCQ_920","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_920","question":"Why do businesses advertise in specialist trade or hobby magazines (such as cycling or photography journals)?","options":{"A":"Because specialist magazines have larger audiences than national television.","B":"Because specialist magazines are distributed free to every household in the country.","C":"Because readers already have a strong interest in that niche activity, reducing wasted advertising spend.","D":"Because specialist magazines forbid competitors from advertising."},"correctOption":"C","correctAnswer":"Because readers already have a strong interest in that niche activity, reducing wasted advertising spend.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because niche magazines reach a pre-segmented audience of enthusiasts who are much more likely to buy related products.","distractor_reasons":{"A":"Incorrect because niche magazines have much smaller circulations than national TV.","B":"Incorrect because enthusiasts typically pay to subscribe or buy specialist journals.","C":"Correct selection.","D":"Incorrect because rival brands also advertise in the same specialist publications."}}},{"id":"P1_U3_MCQ_921","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_921","question":"Which promotional method involves offering a free gift inside a cereal box or giving away a branded mug with a coffee purchase?","options":{"A":"Informative billboard advertising.","B":"Sales promotion (free gifts / premiums).","C":"Secondary market research.","D":"Price skimming."},"correctOption":"B","correctAnswer":"Sales promotion (free gifts / premiums).","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because free gifts provide an immediate short-term incentive for consumers to choose that product over rivals.","distractor_reasons":{"A":"Incorrect because billboards are outdoor media advertising.","B":"Correct selection.","C":"Incorrect because giving away gifts is promotion, not data collection.","D":"Incorrect because price skimming is setting a high launch price."}}},{"id":"P1_U3_MCQ_922","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_922","question":"What is a disadvantage of using 'Buy One, Get One Free' (BOGOF) promotions for perishable food items?","options":{"A":"Customers may not be able to consume the second item before it expires, or it may simply delay their next purchase rather than increasing long-term demand.","B":"Supermarkets are legally barred from running BOGOF deals.","C":"It increases the selling price per unit for consumers.","D":"It eliminates all storage costs in the factory."},"correctOption":"A","correctAnswer":"Customers may not be able to consume the second item before it expires, or it may simply delay their next purchase rather than increasing long-term demand.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because short-term sales promotions often bring forward future purchases or lead to food waste rather than creating permanent new demand.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because BOGOF promotions are legal.","C":"Incorrect because BOGOF halves the average price paid per item.","D":"Incorrect because factory storage costs still apply prior to delivery."}}},{"id":"P1_U3_MCQ_923","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_923","question":"Why do businesses often prefer 'Public Relations' (PR) stories in newspapers over paid advertisements?","options":{"A":"Because PR editorial coverage appears more credible to readers as independent news and avoids paying for media space.","B":"Because PR guarantees that journalists will never write anything critical.","C":"Because PR eliminates the need to have a quality product.","D":"Because paid advertisements are illegal for limited companies."},"correctOption":"A","correctAnswer":"Because PR editorial coverage appears more credible to readers as independent news and avoids paying for media space.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumers tend to trust news articles more than paid ads, and favourable press coverage costs far less than buying ad space.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses cannot control exactly how independent journalists write a story.","C":"Incorrect because poor product quality will generate negative publicity.","D":"Incorrect because paid advertising is legal for all companies."}}},{"id":"P1_U3_MCQ_924","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_924","question":"How does influencer marketing on social media help a fashion or cosmetics brand?","options":{"A":"It guarantees zero returns of online clothing orders.","B":"It reaches engaged niche followers who trust the influencer's recommendations, boosting brand awareness and credibility.","C":"It eliminates all costs of manufacturing garments.","D":"It prevents competitors from creating social media accounts."},"correctOption":"B","correctAnswer":"It reaches engaged niche followers who trust the influencer's recommendations, boosting brand awareness and credibility.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because popular content creators already have the attention and trust of specific target demographics.","distractor_reasons":{"A":"Incorrect because online clothing orders still experience returns.","B":"Correct selection.","C":"Incorrect because manufacturing costs are unrelated to social media promotion.","D":"Incorrect because rivals can also use social media and influencers."}}},{"id":"P1_U3_MCQ_925","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_925","question":"Which factor is most important when selecting an advertising medium for a new luxury yacht?","options":{"A":"Reaching the largest possible number of school students.","B":"Choosing the cheapest possible street flyer printer.","C":"Targeting high-net-worth individuals through exclusive wealth magazines, private jet lounges, and international boat shows.","D":"Advertising on discount supermarket shopping trolleys."},"correctOption":"C","correctAnswer":"Targeting high-net-worth individuals through exclusive wealth magazines, private jet lounges, and international boat shows.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because promotional media must match the target segment's lifestyle and income while reinforcing the brand's luxury image.","distractor_reasons":{"A":"Incorrect because school students cannot afford luxury yachts.","B":"Incorrect because cheap street flyers clash with a luxury brand and miss wealthy buyers.","C":"Correct selection.","D":"Incorrect because supermarket trolleys target mass grocery shoppers rather than yacht buyers."}}},{"id":"P1_U3_MCQ_926","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_926","question":"A company wants to enter a new market segment of eco-conscious young professionals with a reusable insulated coffee cup. Which marketing mix is most consistent?","options":{"A":"Recycled stainless-steel design, mid-to-premium price, sold via specialty coffee shops and online, promoted on Instagram.","B":"Single-use thin plastic cup, ultra-cheap price, sold in wholesale hardware warehouses, promoted in farming newspapers.","C":"Heavy glass mug, high skimming price, sold only by postal mail order, zero social media presence.","D":"Unbranded plain cup, price doubled every week, sold exclusively in retirement homes."},"correctOption":"A","correctAnswer":"Recycled stainless-steel design, mid-to-premium price, sold via specialty coffee shops and online, promoted on Instagram.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustainable materials, appropriate pricing, convenient coffee-shop/online availability, and Instagram promotion all align with eco-conscious young professionals.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because single-use plastic and farming newspapers completely miss eco-conscious young professionals.","C":"Incorrect because postal mail order and lack of social media fail to reach young professionals.","D":"Incorrect because retirement homes and erratic pricing do not match the target segment."}}},{"id":"P1_U3_MCQ_927","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_927","question":"Why might a business change its marketing strategy when one of its key products enters the 'maturity' stage?","options":{"A":"To shift from informative launch ads to persuasive brand-loyalty promotion, competitive pricing, and extension strategies.","B":"To stop selling the product immediately while profits are at their highest.","C":"To eliminate all quality control checks in the factory.","D":"To reduce distribution outlets so fewer shoppers can find the item."},"correctOption":"A","correctAnswer":"To shift from informative launch ads to persuasive brand-loyalty promotion, competitive pricing, and extension strategies.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because intense competition in maturity requires defending market share through brand differentiation, competitive prices, and product extensions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because maturity is the most profitable stage and should be maintained or extended.","C":"Incorrect because maintaining quality is essential to keep loyal customers in maturity.","D":"Incorrect because wide availability is important in maturity."}}},{"id":"P1_U3_MCQ_928","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_928","question":"Which marketing objective is most appropriate for a newly established start-up business in its first year of trading?","options":{"A":"Achieving global market dominance across fifty countries immediately.","B":"Building initial brand awareness and achieving break-even sales volume.","C":"Maximising dividend payouts to international institutional shareholders.","D":"Withdrawing all products from the market."},"correctOption":"B","correctAnswer":"Building initial brand awareness and achieving break-even sales volume.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because new businesses must first make consumers aware of their existence and reach enough sales to cover costs and survive.","distractor_reasons":{"A":"Incorrect because a start-up lacks the resources for immediate global dominance.","B":"Correct selection.","C":"Incorrect because start-ups rarely have institutional shareholders or surplus profits in year one.","D":"Incorrect because withdrawing products would end the business immediately."}}},{"id":"P1_U3_MCQ_929","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_929","question":"An electronics retailer advertises a laptop as 'Waterproof up to 10 metres', but the laptop breaks when splashed with rain. Which consumer protection principle has been breached?","options":{"A":"Goods must match their description and be fit for the stated purpose.","B":"Retailers must charge the lowest price in the city.","C":"All electronics must be manufactured domestically.","D":"Businesses must use wholesalers for all computer sales."},"correctOption":"A","correctAnswer":"Goods must match their description and be fit for the stated purpose.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumer laws require products to perform as advertised and match trade descriptions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pricing levels are not fixed by consumer description laws.","C":"Incorrect because imported electronics are legal.","D":"Incorrect because distribution channels are chosen by the business."}}},{"id":"P1_U3_MCQ_930","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_930","question":"What legal right does a consumer normally have when they purchase a brand-new washing machine that fails to work on the day it is delivered?","options":{"A":"The right to take ownership of the retailer's delivery van.","B":"The right to a full refund, repair, or replacement because the item is faulty and not of satisfactory quality.","C":"No rights at all once the receipt has been printed.","D":"The right to force the shop manager to resign."},"correctOption":"B","correctAnswer":"The right to a full refund, repair, or replacement because the item is faulty and not of satisfactory quality.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consumer protection statutes guarantee remedies (refund, repair, or replacement) for defective goods.","distractor_reasons":{"A":"Incorrect because consumers cannot seize business assets.","B":"Correct selection.","C":"Incorrect because consumer rights apply after purchase when goods are faulty.","D":"Incorrect because staffing decisions belong to the employer, not shoppers."}}},{"id":"P1_U3_MCQ_931","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_931","question":"Why do governments enforce strict labelling laws on packaged food products regarding allergens and expiry dates?","options":{"A":"To protect consumer health and safety and ensure buyers have accurate information before purchasing.","B":"To make food packaging heavier and more expensive to transport.","C":"To prevent supermarkets from offering price discounts.","D":"To eliminate all competition among food manufacturers."},"correctOption":"A","correctAnswer":"To protect consumer health and safety and ensure buyers have accurate information before purchasing.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because accurate allergen and use-by labels prevent illness and help consumers make safe, informed choices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because printing accurate labels is for safety, not adding weight.","C":"Incorrect because supermarkets can still discount food items safely within expiry dates.","D":"Incorrect because labelling rules apply equally to all competing food firms."}}},{"id":"P1_U3_MCQ_932","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_932","question":"How does entering foreign markets help extend the life of a product that is declining in its domestic market?","options":{"A":"Consumers in countries where the product has not been sold before may treat it as an exciting new innovation.","B":"Foreign governments guarantee to buy all unsold domestic inventory at double price.","C":"Exporting eliminates all production and shipping costs.","D":"Foreign consumers never switch to newer technologies."},"correctOption":"A","correctAnswer":"Consumers in countries where the product has not been sold before may treat it as an exciting new innovation.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Product Life Cycles differ across countries; a mature or declining product at home may be in the introduction or growth stage abroad.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because foreign governments do not buy up private firms' unsold stock.","C":"Incorrect because exporting adds international shipping costs.","D":"Incorrect because foreign consumers also adopt new technologies over time."}}},{"id":"P1_U3_MCQ_933","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_933","question":"Which barrier is most likely to affect a domestic clothing retailer expanding into a country with a much hotter climate and different religious dress customs?","options":{"A":"Excessive demand for heavy woollen winter coats.","B":"Need to redesign the product range to match local climate and cultural modesty standards.","C":"Total absence of any retail shopping centres.","D":"Inability to hire local sales staff."},"correctOption":"B","correctAnswer":"Need to redesign the product range to match local climate and cultural modesty standards.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because both geographic climate and cultural norms dictate clothing fabrics, styles, and designs.","distractor_reasons":{"A":"Incorrect because hot climates reduce demand for heavy winter coats.","B":"Correct selection.","C":"Incorrect because modern shopping centres exist worldwide.","D":"Incorrect because local retail staff can be recruited and trained."}}},{"id":"P1_U3_MCQ_934","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_934","question":"Why might a foreign company choose to set up a 'joint venture' with a local partner rather than opening a wholly owned branch on its own?","options":{"A":"To benefit from the local partner's existing distribution channels, regulatory knowledge, and brand trust while sharing set-up costs.","B":"To avoid sharing any profits or control with anyone else.","C":"To avoid paying any local taxes or obeying safety regulations.","D":"To ensure that no local employees are ever hired."},"correctOption":"A","correctAnswer":"To benefit from the local partner's existing distribution channels, regulatory knowledge, and brand trust while sharing set-up costs.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a local partner lowers entry barriers, speeds up market access, and shares financial risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because joint ventures require sharing both profits and control.","C":"Incorrect because joint ventures must pay local taxes and obey all local laws.","D":"Incorrect because local partners typically employ local staff."}}},{"id":"P1_U3_MCQ_935","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_935","question":"How can 'licensing' overcome high import tariffs imposed by a foreign country?","options":{"A":"Because the product is manufactured locally inside the foreign country by the licensee rather than being imported across the border.","B":"Because licensed goods are exempt from all local sales taxes.","C":"Because the licensor ships goods secretly without customs declarations.","D":"Because tariffs only apply to agricultural products."},"correctOption":"A","correctAnswer":"Because the product is manufactured locally inside the foreign country by the licensee rather than being imported across the border.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because import tariffs apply to goods crossing national borders; local production by a licensee avoids import duties.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because local sales taxes (like VAT) still apply to locally produced goods.","C":"Incorrect because smuggling is illegal.","D":"Incorrect because import tariffs frequently apply to manufactured goods as well."}}},{"id":"P1_U3_MCQ_936","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_936","question":"What is a major risk for a franchisor expanding internationally through local franchisees?","options":{"A":"The franchisor must provide 100% of the capital for every overseas outlet.","B":"If one foreign franchisee delivers poor hygiene or bad customer service, it can damage the global brand's reputation.","C":"Franchisees are prohibited from adapting any menu items even with franchisor approval.","D":"The franchisor receives no initial fee or ongoing royalty payments."},"correctOption":"B","correctAnswer":"If one foreign franchisee delivers poor hygiene or bad customer service, it can damage the global brand's reputation.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consumers view all outlets under the same brand name as one company, so misconduct at one branch harms the entire chain.","distractor_reasons":{"A":"Incorrect because franchisees invest their own capital to open outlets.","B":"Correct selection.","C":"Incorrect because franchisors often approve local menu adaptations to suit regional tastes.","D":"Incorrect because franchisees pay initial licence fees and ongoing royalties."}}},{"id":"P1_U3_MCQ_937","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_937","question":"When evaluating a proposed marketing strategy, why is checking the 'marketing budget' essential?","options":{"A":"To ensure that the chosen promotional campaigns, research, and distribution channels are financially affordable and generate a positive return.","B":"Because laws require every business to spend at least half its revenue on TV ads.","C":"Because a large budget guarantees that consumers will love a faulty product.","D":"Because marketing budgets eliminate all fixed factory overheads."},"correctOption":"A","correctAnswer":"To ensure that the chosen promotional campaigns, research, and distribution channels are financially affordable and generate a positive return.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an effective marketing strategy must be realistic within the firm's financial resources and earn more profit than it costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no law mandates spending 50% of revenue on advertising.","C":"Incorrect because heavy spending cannot save a defective product.","D":"Incorrect because marketing budgets allocate promotional funds rather than removing factory overheads."}}},{"id":"P1_U3_MCQ_938","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_938","question":"How does the marketing department help a food manufacturer respond to growing consumer concern about plastic waste?","options":{"A":"By anticipating the shift in customer preferences and recommending biodegradable packaging before sales decline.","B":"By increasing factory production of single-use plastic wrappers to lower unit costs.","C":"By hiding ingredient and packaging material details from supermarket labels.","D":"By stopping all market research until sales fall by 50%."},"correctOption":"A","correctAnswer":"By anticipating the shift in customer preferences and recommending biodegradable packaging before sales decline.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a core role of marketing is identifying and anticipating evolving customer needs so the business can adapt its products proactively.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because producing more unwanted single-use plastic ignores changing consumer values.","C":"Incorrect because hiding material information alienates eco-conscious buyers and risks breaching labelling rules.","D":"Incorrect because waiting until sales collapse delays necessary product adaptation."}}},{"id":"P1_U3_MCQ_939","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_939","question":"Why is maintaining customer loyalty often more profitable for a business than constantly searching for brand-new customers?","options":{"A":"Existing satisfied customers make repeat purchases and require lower advertising expenditure per sale than attracting new buyers.","B":"Loyal customers never compare prices or product quality.","C":"Customer loyalty eliminates all fixed overhead expenses.","D":"Businesses are legally prohibited from advertising to existing customers."},"correctOption":"A","correctAnswer":"Existing satisfied customers make repeat purchases and require lower advertising expenditure per sale than attracting new buyers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retaining current customers generates steady repeat revenue and positive word-of-mouth at a much lower marketing cost than acquiring first-time buyers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because loyal customers still expect good value and quality.","C":"Incorrect because fixed overheads remain regardless of repeat purchases.","D":"Incorrect because businesses regularly market new offers to existing customers."}}},{"id":"P1_U3_MCQ_940","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_940","question":"Total annual sales in the domestic bottled water market are $60 million. Company A records annual sales of $15 million. What is Company A's market share?","options":{"A":"15%","B":"20%","C":"25%","D":"40%"},"correctOption":"C","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Market Share = ($15 million / $60 million) x 100 = 25%.","distractor_reasons":{"A":"Incorrect because 15% of $60 million is $9 million.","B":"Incorrect because 20% of $60 million is $12 million.","C":"Correct selection.","D":"Incorrect because 40% of $60 million is $24 million."}}},{"id":"P1_U3_MCQ_941","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_941","question":"What is a key commercial advantage of being the market leader with the highest market share in an industry?","options":{"A":"Retailers are eager to stock the leading brand, and high sales volumes enable purchasing and marketing economies of scale.","B":"The business no longer needs to develop new products or maintain quality.","C":"The market leader is exempt from paying corporation tax.","D":"Competitors are legally banned from lowering their prices."},"correctOption":"A","correctAnswer":"Retailers are eager to stock the leading brand, and high sales volumes enable purchasing and marketing economies of scale.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dominant market share gives strong negotiating power with retailers, high brand visibility, and lower unit costs from large-scale output.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because market leaders must keep innovating to defend their position.","C":"Incorrect because market leaders pay taxes like all other profitable businesses.","D":"Incorrect because rivals can still compete aggressively on price."}}},{"id":"P1_U3_MCQ_942","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_942","question":"How does an ageing population in a developed country affect consumer spending patterns?","options":{"A":"Demand increases for healthcare services, retirement holidays, and accessible housing, while demand for baby products may fall.","B":"Consumers spend all their income exclusively on high-school textbooks.","C":"Demand for mobility aids and pharmaceutical products drops to zero.","D":"All businesses switch to producing only children's toys."},"correctOption":"A","correctAnswer":"Demand increases for healthcare services, retirement holidays, and accessible housing, while demand for baby products may fall.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because demographic changes shift market demand toward goods and services tailored to older age groups.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because an ageing population reduces, rather than increases, the proportion of school-age students.","C":"Incorrect because an older population increases demand for healthcare and mobility products.","D":"Incorrect because businesses adapt toward growing senior segments rather than shrinking child segments."}}},{"id":"P1_U3_MCQ_943","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_943","question":"Which development has made many consumer markets significantly more competitive in recent years?","options":{"A":"The growth of e-commerce and globalisation, allowing overseas and online rivals to reach local shoppers easily.","B":"The complete removal of internet access in major cities.","C":"Government bans on international trade across all countries.","D":"Consumers refusing to compare prices before buying expensive items."},"correctOption":"A","correctAnswer":"The growth of e-commerce and globalisation, allowing overseas and online rivals to reach local shoppers easily.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because online selling lowers entry barriers and international trade exposes local firms to global competitors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because internet access has expanded rapidly.","C":"Incorrect because international trade has grown rather than been banned.","D":"Incorrect because comparison websites make it easier for shoppers to compare prices."}}},{"id":"P1_U3_MCQ_944","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_944","question":"How can an established high-street bookstore best respond to intense price competition from large online retailers?","options":{"A":"By offering signed author events, a cosy in-store café, and expert staff recommendations that online sites cannot replicate.","B":"By closing the shop every Saturday when shoppers are free to visit.","C":"By raising book prices 40% above the cover price without offering any extra service.","D":"By removing all signs and window displays outside the store."},"correctOption":"A","correctAnswer":"By offering signed author events, a cosy in-store café, and expert staff recommendations that online sites cannot replicate.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because differentiating through customer experience and community events adds value where small retailers cannot win a pure price war.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because closing on peak shopping days reduces sales further.","C":"Incorrect because raising prices without added value drives customers away.","D":"Incorrect because poor visibility reduces walk-in customer footfall."}}},{"id":"P1_U3_MCQ_945","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_945","question":"Why are businesses operating in a niche market often able to charge higher profit margins than mass-market firms?","options":{"A":"Specialised products meet exact buyer requirements with fewer direct competitors, making customers less price-sensitive.","B":"Niche businesses always produce millions of standardised units per day.","C":"Suppliers charge niche firms zero money for raw materials.","D":"Niche businesses never pay rent or wages."},"correctOption":"A","correctAnswer":"Specialised products meet exact buyer requirements with fewer direct competitors, making customers less price-sensitive.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because customers with specific needs value tailored solutions and face limited alternatives, supporting premium pricing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because high-volume standardised output describes mass markets.","C":"Incorrect because niche firms still pay for specialised materials.","D":"Incorrect because niche businesses still incur normal operating overheads."}}},{"id":"P1_U3_MCQ_946","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_946","question":"What is a major limitation of operating exclusively in a small niche market?","options":{"A":"Low sales volumes limit opportunities to achieve economies of scale, keeping average unit costs relatively high.","B":"The business must advertise on every national television channel simultaneously.","C":"Customers are forced to buy identical standardised products.","D":"The business faces hundreds of giant multinational rivals in that tiny segment."},"correctOption":"A","correctAnswer":"Low sales volumes limit opportunities to achieve economies of scale, keeping average unit costs relatively high.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a small customer base restricts total output, preventing bulk-buying and mass-production cost savings.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because niche firms use targeted, low-cost specialist media rather than national TV.","C":"Incorrect because niche products are tailored rather than standardised.","D":"Incorrect because large multinationals usually avoid small niches due to limited revenue potential."}}},{"id":"P1_U3_MCQ_947","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_947","question":"What is a primary advantage for a business targeting a mass market?","options":{"A":"High sales volumes allow the business to benefit from economies of scale, lowering average cost per unit.","B":"There is zero competition from other brands.","C":"Every customer receives a custom-made, one-of-a-kind product.","D":"No advertising or promotion is ever required."},"correctOption":"A","correctAnswer":"High sales volumes allow the business to benefit from economies of scale, lowering average cost per unit.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because selling standardised goods to a huge customer base generates high output and lowers unit costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because mass markets typically attract intense competition.","C":"Incorrect because mass-market products are standardised rather than bespoke.","D":"Incorrect because mass-market brands invest heavily in promotion to stand out."}}},{"id":"P1_U3_MCQ_948","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_948","question":"What is a major disadvantage of selling a single standardised product in a mass market?","options":{"A":"Fierce competition often forces lower prices and smaller profit margins, while specific consumer tastes may go unsatisfied.","B":"The business cannot use automated flow production.","C":"Unit production costs are always higher than bespoke job production.","D":"Supermarkets refuse to stock well-known mass-market brands."},"correctOption":"A","correctAnswer":"Fierce competition often forces lower prices and smaller profit margins, while specific consumer tastes may go unsatisfied.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rival firms target the same large audience with similar goods, driving price competition and leaving specialised preferences unmet.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because standardised mass-market goods are ideal for flow production.","C":"Incorrect because mass production achieves much lower unit costs than job production.","D":"Incorrect because supermarkets rely heavily on fast-selling mass-market goods."}}},{"id":"P1_U3_MCQ_949","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_949","question":"An airline divides passengers into Economy Class, Business Class, and First Class cabins on the same flight. Which type of segmentation is this?","options":{"A":"Income / socio-economic segmentation.","B":"Gender segmentation.","C":"Age segmentation.","D":"Climate segmentation."},"correctOption":"A","correctAnswer":"Income / socio-economic segmentation.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cabin classes separate travellers according to their income levels and willingness to pay for comfort and extra services.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cabin classes are open to all genders.","C":"Incorrect because cabin classes are based on ticket price and income rather than passenger age.","D":"Incorrect because all passengers on the same flight travel to the same destination."}}},{"id":"P1_U3_MCQ_950","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_950","question":"Why do businesses carry out market research before investing heavily in launching a new product?","options":{"A":"To reduce the risk of product failure by checking customer demand, preferred features, and acceptable price levels.","B":"To guarantee with 100% certainty that competitors will go bankrupt.","C":"To eliminate all fixed factory costs.","D":"To avoid having to pay for product packaging."},"correctOption":"A","correctAnswer":"To reduce the risk of product failure by checking customer demand, preferred features, and acceptable price levels.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because gathering evidence on buyer preferences and market size prevents wasting capital on unwanted products.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because market research reduces risk but cannot guarantee rival bankruptcy.","C":"Incorrect because fixed costs still exist when producing goods.","D":"Incorrect because packaging is still required for distribution and protection."}}},{"id":"P1_U3_MCQ_951","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_951","question":"What happens to a strictly 'product-oriented' business if consumer tastes suddenly shift toward a new style of product?","options":{"A":"It risks losing significant sales because it focuses on what its engineers can make rather than researching what customers want.","B":"It automatically spots the trend first through daily customer focus groups.","C":"Its profit margins double even when nobody buys its products.","D":"It immediately switches its entire product range every morning."},"correctOption":"A","correctAnswer":"It risks losing significant sales because it focuses on what its engineers can make rather than researching what customers want.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because product-oriented firms concentrate on technical product features first and neglect ongoing consumer research.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because continuous customer focus groups describe a market-oriented business.","C":"Incorrect because unsold goods generate losses rather than profits.","D":"Incorrect because product-oriented businesses are slow to adapt to shifting consumer trends."}}},{"id":"P1_U3_MCQ_952","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_952","question":"A supermarket manager watches how shoppers move through aisles and which shelves they pause at without asking them any questions. What is a limitation of this 'observation' method?","options":{"A":"It shows what shoppers actually do, but cannot explain the reasons behind their choices.","B":"Shoppers lie about their answers during silent observation.","C":"It requires printing 50,000 paper questionnaires.","D":"It can only be used for online digital software."},"correctOption":"A","correctAnswer":"It shows what shoppers actually do, but cannot explain the reasons behind their choices.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because observation records real behaviour accurately, but without questioning shoppers, researchers do not know *why* they ignored or picked an item.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no questions are asked in pure observation.","C":"Incorrect because observation does not use questionnaires.","D":"Incorrect because observation works both in physical stores and via website analytics."}}},{"id":"P1_U3_MCQ_953","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_953","question":"What is a major advantage of using 'online surveys' for primary market research?","options":{"A":"Large numbers of responses can be collected quickly at very low cost, and results are automatically tabulated by software.","B":"Every elderly resident without internet access is guaranteed to respond.","C":"Interviewers can physically hand product samples to respondents through the screen.","D":"Respondents spend two hours writing detailed essays on every question."},"correctOption":"A","correctAnswer":"Large numbers of responses can be collected quickly at very low cost, and results are automatically tabulated by software.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because online questionnaires eliminate printing, postage, and interviewer travel expenses while speeding up data analysis.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because people without internet access are excluded from online surveys.","C":"Incorrect because physical samples cannot be handed over via an online link.","D":"Incorrect because online respondents usually prefer short, quick surveys."}}},{"id":"P1_U3_MCQ_954","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_954","question":"Why might a snack company launch a new crisp flavour in just two cities ('test marketing') before rolling it out nationwide?","options":{"A":"To measure real customer repeat purchases and fix any taste or packaging flaws before spending millions on national production and TV ads.","B":"Because laws ban selling snacks in more than two cities during the first five years.","C":"To ensure competitors have plenty of time to copy the flavour nationwide first.","D":"To avoid paying any taxes on snack sales."},"correctOption":"A","correctAnswer":"To measure real customer repeat purchases and fix any taste or packaging flaws before spending millions on national production and TV ads.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because test marketing trials the full marketing mix in a small representative area, reducing the financial cost of a nationwide failure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no law restricts nationwide launches.","C":"Incorrect because giving rivals time to copy is actually a disadvantage of test marketing.","D":"Incorrect because taxes still apply to test-market sales."}}},{"id":"P1_U3_MCQ_955","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_955","question":"Which of the following is an 'internal' source of secondary market research data?","options":{"A":"The business's own past sales records and customer loyalty card purchase histories.","B":"A national population census published by the government.","C":"An industry trend report sold by a private market research agency.","D":"Articles published in a national financial newspaper."},"correctOption":"A","correctAnswer":"The business's own past sales records and customer loyalty card purchase histories.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal secondary data already exists inside the business's own files and databases.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because government census data is an external secondary source.","C":"Incorrect because research agency reports are external secondary sources.","D":"Incorrect because newspapers are external secondary sources."}}},{"id":"P1_U3_MCQ_956","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_956","question":"Which of the following is an 'external' source of secondary market research data?","options":{"A":"Industry reports published by trade associations and market research agencies.","B":"The company's own accounting ledger of last month's sales.","C":"Feedback collected yesterday from a focus group hired by the business.","D":"Street interviews conducted this morning by the firm's marketing team."},"correctOption":"A","correctAnswer":"Industry reports published by trade associations and market research agencies.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade association publications and research agency reports are compiled by outside organisations and already exist.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because internal sales ledgers are internal secondary data.","C":"Incorrect because a newly run focus group is primary research.","D":"Incorrect because new street interviews are primary research."}}},{"id":"P1_U3_MCQ_957","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_957","question":"What is a major disadvantage of relying solely on external secondary data when designing a brand-new product?","options":{"A":"The data was collected for another purpose, may not answer specific questions about the new product, and is also available to competitors.","B":"Secondary data is always more expensive than hiring an agency to conduct nationwide face-to-face interviews.","C":"Secondary data never contains any numerical statistics.","D":"It takes ten years to download a government report from the internet."},"correctOption":"A","correctAnswer":"The data was collected for another purpose, may not answer specific questions about the new product, and is also available to competitors.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because existing external data is general rather than tailored to a firm's specific product idea, and rivals can access the exact same information.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because secondary data is usually much cheaper than primary research.","C":"Incorrect because secondary sources frequently provide rich quantitative statistics.","D":"Incorrect because secondary desk research is quick to access."}}},{"id":"P1_U3_MCQ_958","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_958","question":"Why do many businesses combine 'quantitative' and 'qualitative' research methods?","options":{"A":"Quantitative data measures how many customers hold a view, while qualitative data explains why they feel that way.","B":"Quantitative data provides emotional stories, while qualitative data provides only financial balance sheets.","C":"Combining both methods eliminates the need to choose a sample.","D":"Laws prohibit using only one type of research data."},"correctOption":"A","correctAnswer":"Quantitative data measures how many customers hold a view, while qualitative data explains why they feel that way.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because using both gives statistical breadth (numbers/percentages) alongside psychological depth (reasons/opinions).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this reverses the meanings of quantitative and qualitative data.","C":"Incorrect because both surveys and focus groups still require selecting samples.","D":"Incorrect because businesses freely choose whichever research methods suit their budget."}}},{"id":"P1_U3_MCQ_959","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_959","question":"Why do businesses survey a 'sample' of consumers rather than asking every single potential buyer in the country?","options":{"A":"Surveying the entire population would be far too expensive and time-consuming, delaying product launch decisions.","B":"A sample of 5 people is always more accurate than asking 50,000 people.","C":"Computers cannot process more than 100 survey responses.","D":"It is illegal to ask more than 1,000 consumers for their opinion."},"correctOption":"A","correctAnswer":"Surveying the entire population would be far too expensive and time-consuming, delaying product launch decisions.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a well-chosen representative sample provides reliable estimates quickly and at a fraction of the cost of a full census.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tiny samples have high sampling error and poor accuracy.","C":"Incorrect because modern software easily analyses millions of responses.","D":"Incorrect because no law caps survey sample sizes."}}},{"id":"P1_U3_MCQ_960","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_960","question":"What is a practical difficulty of using 'random sampling' for a new mass-market snack?","options":{"A":"The business does not have a complete list of every person in the target population from which to draw names randomly.","B":"Random sampling forces researchers to interview only their own family members.","C":"Random sampling guarantees that 100% of selected people will complete the survey.","D":"Random sampling can only be used for qualitative focus groups."},"correctOption":"A","correctAnswer":"The business does not have a complete list of every person in the target population from which to draw names randomly.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because true random sampling requires a full directory (sampling frame) of the population, which rarely exists for general consumer goods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because interviewing family members is convenience sampling, not random sampling.","C":"Incorrect because many randomly chosen people refuse or ignore surveys.","D":"Incorrect because random sampling is widely used in quantitative surveys when a customer list exists."}}},{"id":"P1_U3_MCQ_961","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_961","question":"An interviewer in a shopping mall is instructed to survey 40 men and 40 women, with half aged under 35 and half aged 35 or over. Which sampling method is being used?","options":{"A":"Quota sampling.","B":"Random sampling.","C":"Test marketing.","D":"Secondary desk sampling."},"correctOption":"A","correctAnswer":"Quota sampling.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the target population is segmented by characteristics (gender and age) and specific numerical quotas are filled for each group.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because respondents are chosen to fill demographic quotas rather than purely by chance from a full list.","C":"Incorrect because test marketing trials selling a product in a region.","D":"Incorrect because this is primary field research."}}},{"id":"P1_U3_MCQ_962","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_962","question":"Why might the results of a street questionnaire about healthy eating habits be inaccurate even with a large sample size?","options":{"A":"Respondents may give socially desirable answers (claiming they eat more vegetables than they really do) or questions may be worded in a leading way.","B":"Large sample sizes always produce less accurate data than tiny samples.","C":"Street questionnaires cannot ask any closed-ended questions.","D":"Healthy food manufacturers are banned from conducting surveys."},"correctOption":"A","correctAnswer":"Respondents may give socially desirable answers (claiming they eat more vegetables than they really do) or questions may be worded in a leading way.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because respondent dishonesty/embarrassment and biased question phrasing distort primary data accuracy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because larger representative samples generally improve statistical reliability.","C":"Incorrect because street questionnaires routinely use closed questions.","D":"Incorrect because food businesses regularly run consumer surveys."}}},{"id":"P1_U3_MCQ_963","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_963","question":"What is a major benefit to a business of regularly developing new products?","options":{"A":"It creates a Unique Selling Point (USP), diversifies risk across multiple products, and attracts new customers.","B":"It requires zero spending on research, prototypes, or market testing.","C":"It guarantees that every new product will become an instant bestseller.","D":"It eliminates all competition in the industry."},"correctOption":"A","correctAnswer":"It creates a Unique Selling Point (USP), diversifies risk across multiple products, and attracts new customers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because continuous product innovation keeps the brand competitive, reduces reliance on one ageing product, and opens new revenue streams.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because R&D and testing are costly and time-consuming.","C":"Incorrect because many new products fail after launch.","D":"Incorrect because rivals also innovate."}}},{"id":"P1_U3_MCQ_964","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_964","question":"How does a strong, trusted brand image affect the price elasticity of demand for a product?","options":{"A":"It makes demand more price inelastic, allowing the business to charge higher prices without losing many loyal customers.","B":"It forces the business to sell its products below production cost.","C":"It makes consumers switch to unbranded rivals whenever prices change by 1 cent.","D":"It eliminates the need for quality control."},"correctOption":"A","correctAnswer":"It makes demand more price inelastic, allowing the business to charge higher prices without losing many loyal customers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because strong brand loyalty reduces the perceived closeness of substitutes, making customers less sensitive to price increases.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because strong brands command premium prices rather than loss-making prices.","C":"Incorrect because high sensitivity to tiny price changes describes weak brand differentiation (price elastic demand).","D":"Incorrect because maintaining consistent quality is vital to protect brand image."}}},{"id":"P1_U3_MCQ_965","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_965","question":"How can innovative packaging directly increase sales of a liquid laundry detergent?","options":{"A":"An easy-pour, non-drip spout with a measuring cap makes the product more convenient to use and stands out on supermarket shelves.","B":"Making the bottle heavy and impossible to open discourages rival brands.","C":"Removing the brand logo and usage instructions saves ink costs.","D":"Using fragile glass bottles increases excitement during delivery."},"correctOption":"A","correctAnswer":"An easy-pour, non-drip spout with a measuring cap makes the product more convenient to use and stands out on supermarket shelves.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because functional, convenient, and eye-catching packaging adds practical value for shoppers and attracts attention at the point of sale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because inconvenient packaging frustrates customers and hurts repeat sales.","C":"Incorrect because brand recognition and clear instructions are essential functions of packaging.","D":"Incorrect because fragile packaging increases breakage and transport waste."}}},{"id":"P1_U3_MCQ_966","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_966","question":"What happens to cash flow during the 'development' stage of the Product Life Cycle?","options":{"A":"Cash flow is heavily negative because the business spends money on R&D and prototypes while earning zero sales revenue.","B":"Cash flow reaches its highest positive peak.","C":"Sales revenue grows rapidly while R&D spending stops.","D":"The business clears leftover inventory at discounted prices."},"correctOption":"A","correctAnswer":"Cash flow is heavily negative because the business spends money on R&D and prototypes while earning zero sales revenue.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the product has not yet been launched to buyers, so outflows occur with no offsetting sales inflows.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because peak positive cash flow occurs in the maturity stage.","C":"Incorrect because rapid sales growth describes the growth stage.","D":"Incorrect because clearance discounting happens in the decline stage."}}},{"id":"P1_U3_MCQ_967","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_967","question":"Which feature is characteristic of the 'growth' stage of the Product Life Cycle?","options":{"A":"Sales rise rapidly as awareness spreads, profits start to appear, and competitors begin launching rival versions.","B":"Sales fall steadily toward zero as the product becomes obsolete.","C":"The product is still being tested secretly inside a laboratory.","D":"No retail shops agree to stock the product."},"correctOption":"A","correctAnswer":"Sales rise rapidly as awareness spreads, profits start to appear, and competitors begin launching rival versions.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid adoption drives fast revenue growth and unit cost reductions, attracting imitators into the market.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because falling sales toward obsolescence describe the decline stage.","C":"Incorrect because laboratory testing describes the development stage.","D":"Incorrect because distribution expands rapidly during the growth stage."}}},{"id":"P1_U3_MCQ_968","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_968","question":"Why do sales fall during the 'decline' stage of the Product Life Cycle?","options":{"A":"Newer technologies emerge, consumer tastes change, or the market becomes saturated.","B":"Consumers have never heard of the product because it was launched yesterday.","C":"Factory workers refuse to manufacture profitable items.","D":"Governments ban all mature products after three years."},"correctOption":"A","correctAnswer":"Newer technologies emerge, consumer tastes change, or the market becomes saturated.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because technological replacements (e.g. streaming replacing DVDs) or shifting trends erode demand for older products.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because low initial awareness describes the introduction stage.","C":"Incorrect because decline is driven by falling market demand rather than worker refusal.","D":"Incorrect because no law bans products after three years."}}},{"id":"P1_U3_MCQ_969","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_969","question":"A manufacturer of baking soda promotes new uses for its product—such as deodorising refrigerators and cleaning carpets—to boost flattening sales. Which strategy is this?","options":{"A":"An extension strategy.","B":"Price skimming.","C":"Product withdrawal.","D":"Quota sampling."},"correctOption":"A","correctAnswer":"An extension strategy.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because finding new uses or new market segments for an existing mature product revitalises demand and extends its life cycle.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because price skimming sets a high launch price for a new innovation.","C":"Incorrect because product withdrawal removes an item from sale.","D":"Incorrect because quota sampling is a market research technique."}}},{"id":"P1_U3_MCQ_970","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_970","question":"A firm produces 1,000 units of a toy with monthly fixed costs of $4,000 and variable costs of $3 per unit. If it applies a 40% cost-plus mark-up, what is the selling price per toy?","options":{"A":"$7.00","B":"$8.40","C":"$9.80","D":"$10.50"},"correctOption":"C","correctAnswer":"$9.80","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Total Cost = $4,000 + (1,000 x $3) = $7,000; Unit Cost = $7,000 / 1,000 = $7.00; adding a 40% mark-up ($2.80) gives $9.80.","distractor_reasons":{"A":"Incorrect because $7.00 is the average unit cost before adding the 40% profit mark-up.","B":"Incorrect because $8.40 represents a 20% mark-up ($7.00 + $1.40).","C":"Correct selection.","D":"Incorrect because $10.50 represents a 50% mark-up ($7.00 + $3.50)."}}},{"id":"P1_U3_MCQ_971","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_971","question":"What is a major weakness of 'cost-plus pricing' in a competitive consumer market?","options":{"A":"It ignores competitors' prices and what customers are actually willing to pay, risking an uncompetitive price if costs are high.","B":"It is too complicated to calculate even when unit costs are known.","C":"It guarantees that the business makes zero profit on every item sold.","D":"It is illegal for retail businesses to use cost-plus pricing."},"correctOption":"A","correctAnswer":"It ignores competitors' prices and what customers are actually willing to pay, risking an uncompetitive price if costs are high.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost-plus pricing looks only at internal costs rather than market demand or rival prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because simplicity of calculation is actually the main advantage of cost-plus pricing.","C":"Incorrect because adding a mark-up aims to build a profit margin above unit cost.","D":"Incorrect because cost-plus pricing is legal and widely used."}}},{"id":"P1_U3_MCQ_972","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_972","question":"When is 'competitive pricing' most appropriate for a business?","options":{"A":"When selling a product in a market with many close substitutes where consumers can easily compare prices.","B":"When the business holds a global patent on a life-saving medicine with zero competitors.","C":"When selling a one-of-a-kind historical painting at an auction.","D":"When production costs are higher than every competitor's selling price."},"correctOption":"A","correctAnswer":"When selling a product in a market with many close substitutes where consumers can easily compare prices.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because in markets with similar competing products, charging noticeably more than rivals causes customers to switch immediately.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a patented breakthrough with no rivals allows price skimming.","C":"Incorrect because unique items have no direct substitutes.","D":"Incorrect because matching low rival prices when unit costs are higher would result in losses."}}},{"id":"P1_U3_MCQ_973","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_973","question":"What is a potential risk of using 'penetration pricing' when launching a new product?","options":{"A":"Profit margins are very low initially, and price-sensitive customers may stop buying once the introductory price is raised.","B":"Customers refuse to try the product because the price is too low.","C":"Fixed factory overheads disappear completely.","D":"The business gains too much market share too quickly."},"correctOption":"A","correctAnswer":"Profit margins are very low initially, and price-sensitive customers may stop buying once the introductory price is raised.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because low launch prices delay cost recovery and attract bargain hunters who may switch away when prices rise later.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because low introductory prices generally encourage trial, except for luxury prestige goods.","C":"Incorrect because fixed overheads remain unchanged.","D":"Incorrect because gaining market share quickly is the intended goal of penetration pricing."}}},{"id":"P1_U3_MCQ_974","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_974","question":"Why should a premium clothing brand avoid running 'promotional pricing' (50% off sales) every single month?","options":{"A":"Frequent discounting can cheapen the brand's luxury image and train customers to wait for sales instead of paying full price.","B":"Supermarkets are legally barred from reducing prices more than once a year.","C":"Promotional pricing increases variable manufacturing costs per garment.","D":"Customers dislike buying clothes at discounted prices."},"correctOption":"A","correctAnswer":"Frequent discounting can cheapen the brand's luxury image and train customers to wait for sales instead of paying full price.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because constant price cuts erode brand prestige and reduce long-term full-price revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses can legally run sales throughout the year.","C":"Incorrect because retail discounts do not alter factory manufacturing costs.","D":"Incorrect because shoppers welcome discounts, which is why they wait for them."}}},{"id":"P1_U3_MCQ_975","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix: Product and Price","questionNumber":"P1_U3_MCQ_975","question":"A ride-hailing app automatically increases fares during heavy rainstorms and Saturday night peak hours, then lowers fares on quiet Tuesday afternoons. Which pricing method is this?","options":{"A":"Dynamic pricing.","B":"Cost-plus pricing.","C":"Penetration pricing.","D":"Loss-leader pricing."},"correctOption":"A","correctAnswer":"Dynamic pricing.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dynamic pricing uses algorithms to adjust prices continuously in response to real-time changes in demand and supply.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cost-plus pricing adds a fixed percentage onto average cost.","C":"Incorrect because penetration pricing sets a low initial launch price for a new product.","D":"Incorrect because loss-leader pricing sells an item below cost to attract shoppers to buy other profitable goods."}}},{"id":"P1_U3_MCQ_976","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_976","question":"What is the main objective of the 'Place' element in the marketing mix?","options":{"A":"Ensuring products are available in the right locations, at the right time, and in convenient ways for target customers to purchase.","B":"Designing the company's television commercials and social media slogans.","C":"Calculating the break-even level of output for a factory.","D":"Negotiating annual wage increases with trade unions."},"correctOption":"A","correctAnswer":"Ensuring products are available in the right locations, at the right time, and in convenient ways for target customers to purchase.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Place covers distribution channels and retail/online outlets that connect producers with consumers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because advertising and slogans belong to Promotion.","C":"Incorrect because break-even analysis belongs to Operations/Finance.","D":"Incorrect because wage negotiations belong to Human Resources."}}},{"id":"P1_U3_MCQ_977","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_977","question":"Which type of product is most suited to the traditional distribution channel 'Producer -> Wholesaler -> Retailer -> Consumer'?","options":{"A":"Everyday convenience items like canned drinks and confectionery sold through thousands of small independent corner shops.","B":"Custom-built commercial passenger aircraft ordered directly by airlines.","C":"Downloadable smartphone video games.","D":"One-off tailored wedding gowns."},"correctOption":"A","correctAnswer":"Everyday convenience items like canned drinks and confectionery sold through thousands of small independent corner shops.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because wholesalers break bulk and distribute widely to numerous small retailers that manufacturers cannot economically supply directly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because aircraft are sold directly from manufacturer to airline.","C":"Incorrect because digital apps are distributed directly online.","D":"Incorrect because bespoke dresses are sold directly from designer to bride."}}},{"id":"P1_U3_MCQ_978","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_978","question":"Why do large national supermarket chains usually buy groceries directly from manufacturers ('Producer -> Retailer -> Consumer') rather than using wholesalers?","options":{"A":"Supermarkets buy in huge bulk quantities, operate their own regional distribution warehouses, and save money by cutting out the wholesaler's margin.","B":"Wholesalers are legally banned from selling food to supermarkets.","C":"Supermarkets only sell one brand of each grocery item.","D":"Manufacturers deliver single tins of soup directly to each supermarket cashier."},"correctOption":"A","correctAnswer":"Supermarkets buy in huge bulk quantities, operate their own regional distribution warehouses, and save money by cutting out the wholesaler's margin.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because major retailers possess the scale and logistics infrastructure to perform the wholesaling function themselves at lower cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no law prevents supermarkets from using wholesalers.","C":"Incorrect because supermarkets stock wide product ranges.","D":"Incorrect because manufacturers deliver full truckloads to supermarket distribution centres."}}},{"id":"P1_U3_MCQ_979","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_979","question":"What is a major advantage for a manufacturer of selling directly to consumers ('Producer -> Consumer')?","options":{"A":"The producer keeps the entire retail profit margin and maintains complete control over pricing, brand image, and customer relationships.","B":"The producer incurs zero delivery, storage, or customer service costs.","C":"The product automatically appears on the shelves of every supermarket chain.","D":"Wholesalers pay for all of the manufacturer's advertising."},"correctOption":"A","correctAnswer":"The producer keeps the entire retail profit margin and maintains complete control over pricing, brand image, and customer relationships.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because removing intermediaries avoids sharing profit margins and allows direct communication with buyers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the producer must handle individual order fulfilment, storage, and customer queries itself.","C":"Incorrect because direct selling bypasses supermarkets.","D":"Incorrect because no wholesalers are involved in direct distribution."}}},{"id":"P1_U3_MCQ_980","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_980","question":"What is a disadvantage for a manufacturer of distributing products exclusively through its own direct-to-consumer channel?","options":{"A":"The manufacturer bears high warehousing, individual parcel shipping, and customer service administration costs, and may reach fewer casual shoppers.","B":"Retail chains demand huge bulk discounts from the manufacturer.","C":"Wholesalers take 40% of the selling price as profit.","D":"The manufacturer is banned from collecting customer email addresses."},"correctOption":"A","correctAnswer":"The manufacturer bears high warehousing, individual parcel shipping, and customer service administration costs, and may reach fewer casual shoppers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because handling thousands of small individual deliveries is logistically expensive and misses consumers who prefer browsing multi-brand stores.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retail chains are not used in a direct channel.","C":"Incorrect because wholesalers are bypassed in a direct channel.","D":"Incorrect because direct sellers can collect customer data (subject to privacy laws)."}}},{"id":"P1_U3_MCQ_981","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_981","question":"How does operating an e-commerce store benefit a small specialist retailer?","options":{"A":"It allows customers worldwide to browse and buy 24 hours a day without the high rent of multiple physical high-street shops.","B":"It eliminates all parcel postage and packaging expenses.","C":"It guarantees that competitors cannot lower their online prices.","D":"It removes the need to hold any inventory or manage suppliers."},"correctOption":"A","correctAnswer":"It allows customers worldwide to browse and buy 24 hours a day without the high rent of multiple physical high-street shops.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because e-commerce expands geographic reach around the clock at much lower property overhead than opening physical branches.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shipping and packaging costs are significant in e-commerce.","C":"Incorrect because online price competition is intense.","D":"Incorrect because e-commerce retailers still must source and manage inventory."}}},{"id":"P1_U3_MCQ_982","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_982","question":"What is a common challenge faced by clothing retailers selling through e-commerce?","options":{"A":"High rates of returned items because shoppers cannot try clothes on for size and fabric feel before ordering.","B":"Shoppers can only place orders between 9:00 AM and 5:00 PM.","C":"Online stores are legally prohibited from offering home delivery.","D":"Customers are unable to compare prices with rival websites."},"correctOption":"A","correctAnswer":"High rates of returned items because shoppers cannot try clothes on for size and fabric feel before ordering.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because uncertainty over fit and appearance leads to frequent returns, adding reverse-logistics and repackaging costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because e-commerce stores operate 24/7.","C":"Incorrect because home delivery is standard in e-commerce.","D":"Incorrect because online shoppers compare prices very easily."}}},{"id":"P1_U3_MCQ_983","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_983","question":"Which of the following is a primary aim of 'Promotion' in the marketing mix?","options":{"A":"To inform potential buyers about product features, persuade them to purchase, and build a positive brand image.","B":"To calculate the factory's average fixed cost per unit.","C":"To inspect finished products for manufacturing defects.","D":"To recruit production workers for night shifts."},"correctOption":"A","correctAnswer":"To inform potential buyers about product features, persuade them to purchase, and build a positive brand image.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because promotion communicates value to target customers to stimulate awareness, brand loyalty, and sales.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because unit cost calculation belongs to Operations/Finance.","C":"Incorrect because defect inspection is quality control in Operations.","D":"Incorrect because recruitment is a Human Resources function."}}},{"id":"P1_U3_MCQ_984","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_984","question":"When is 'informative advertising' most appropriate?","options":{"A":"When launching a brand-new or technically complex product where consumers need clear facts on how it works and what it does.","B":"When selling bottled water that is identical to twenty competing brands.","C":"When trying to hide product specifications from buyers.","D":"When withdrawing an obsolete product from the market."},"correctOption":"A","correctAnswer":"When launching a brand-new or technically complex product where consumers need clear facts on how it works and what it does.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because unfamiliar innovations require educating consumers about functions, benefits, and availability before they will buy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because identical everyday goods rely mainly on persuasive emotional branding.","C":"Incorrect because informative ads provide factual details rather than hiding them.","D":"Incorrect because withdrawn products are no longer promoted."}}},{"id":"P1_U3_MCQ_985","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_985","question":"Why do small local businesses rarely advertise on national television?","options":{"A":"Production and airtime costs are extremely expensive, and most national viewers live too far away to visit a single local shop.","B":"Television commercials cannot display moving images or sound.","C":"Small businesses are legally banned from buying TV airtime.","D":"Nobody watches television anymore."},"correctOption":"A","correctAnswer":"Production and airtime costs are extremely expensive, and most national viewers live too far away to visit a single local shop.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high cost and huge geographic wastage make national TV unsuitable for a single local outlet.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because combining sight, sound, and motion is TV's main strength.","C":"Incorrect because any business with sufficient budget can buy TV ads.","D":"Incorrect because TV still reaches large mass audiences."}}},{"id":"P1_U3_MCQ_986","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_986","question":"What is a key advantage of targeted social media advertising compared to traditional print newspaper ads?","options":{"A":"Businesses can aim adverts specifically at users matching exact age, location, and interest profiles and measure clicks in real time.","B":"Social media users never scroll past adverts without buying.","C":"It guarantees that competitors cannot see the business's adverts.","D":"Social media platforms forbid any negative user comments."},"correctOption":"A","correctAnswer":"Businesses can aim adverts specifically at users matching exact age, location, and interest profiles and measure clicks in real time.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because digital platforms use user data to target relevant segments accurately and provide instant performance analytics.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because many users ignore or block online ads.","C":"Incorrect because public social media ads are visible to rivals.","D":"Incorrect because public comment sections can attract criticism if customers are unhappy."}}},{"id":"P1_U3_MCQ_987","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_987","question":"How does a supermarket 'loyalty card' scheme increase long-term revenue?","options":{"A":"By rewarding repeat shoppers with points and personalised vouchers, encouraging them to do all their weekly shopping at that chain instead of rivals.","B":"By forcing shoppers to pay an extra 20% fee at the checkout.","C":"By eliminating the need to stock fresh fruit and vegetables.","D":"By preventing shoppers from using cash or debit cards."},"correctOption":"A","correctAnswer":"By rewarding repeat shoppers with points and personalised vouchers, encouraging them to do all their weekly shopping at that chain instead of rivals.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because loyalty rewards incentivize repeat visits while giving the supermarket valuable data on individual buying habits.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because loyalty cards offer discounts/points rather than extra checkout fees.","C":"Incorrect because fresh produce remains essential for supermarkets.","D":"Incorrect because loyalty cards work alongside all normal payment methods."}}},{"id":"P1_U3_MCQ_988","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing mix: Place and Promotion","questionNumber":"P1_U3_MCQ_988","question":"What is a potential risk for a sportswear company that spends millions sponsoring a famous football team?","options":{"A":"If the team performs poorly or players are involved in a public scandal, negative publicity can damage the sponsor's brand image.","B":"The company's logo is hidden from television cameras during matches.","C":"Sponsorship eliminates all manufacturing costs of sports shoes.","D":"Fans are legally banned from buying the sponsor's shirts."},"correctOption":"A","correctAnswer":"If the team performs poorly or players are involved in a public scandal, negative publicity can damage the sponsor's brand image.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because brand reputation becomes closely linked to the sponsored team or athlete, creating reputational risk if controversies arise.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because high TV visibility is the main benefit of sports sponsorship.","C":"Incorrect because sponsorship is a promotional expense, not a manufacturing saving.","D":"Incorrect because sponsorship aims to boost merchandise sales."}}},{"id":"P1_U3_MCQ_989","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_989","question":"What is meant by a 'marketing strategy'?","options":{"A":"A coordinated plan combining the four elements of the marketing mix (Product, Price, Place, Promotion) to achieve specific marketing objectives.","B":"A single television advert broadcast once during a sports final.","C":"A list of factory machines that need oil maintenance.","D":"A legal contract between two wholesale delivery drivers."},"correctOption":"A","correctAnswer":"A coordinated plan combining the four elements of the marketing mix (Product, Price, Place, Promotion) to achieve specific marketing objectives.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a marketing strategy aligns all 4Ps consistently around target customer needs, company goals, and available budget.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because one advert is a single promotional tactic rather than a complete strategy.","C":"Incorrect because machine maintenance belongs to Operations.","D":"Incorrect because delivery driver contracts are operational/legal matters."}}},{"id":"P1_U3_MCQ_990","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_990","question":"Which marketing mix best fits a discount supermarket chain aiming to grow market share among budget-conscious families?","options":{"A":"Core everyday groceries with own-label basics, competitive low prices, accessible suburban stores, and price-comparison leaflets/TV ads.","B":"Imported luxury caviar, high skimming prices, single boutique in an exclusive financial district, and invitations to private art galleries.","C":"Unlabelled bulk sacks, prices raised every week, sold only by postal catalogue, and zero local advertising.","D":"Single-serving gourmet meals, luxury gift wrapping, sold only in airport departure lounges."},"correctOption":"A","correctAnswer":"Core everyday groceries with own-label basics, competitive low prices, accessible suburban stores, and price-comparison leaflets/TV ads.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because everyday product essentials, low prices, convenient locations, and value-focused promotion work together to attract budget-conscious families.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because luxury caviar and boutiques target wealthy niche buyers.","C":"Incorrect because postal catalogues and rising prices fail to serve weekly family grocery shoppers.","D":"Incorrect because airport departure lounges serve travellers rather than weekly family shoppers."}}},{"id":"P1_U3_MCQ_991","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_991","question":"Primary market research reveals that busy office workers care far more about 30-minute lunch delivery than saving $1 on meal price. How should a salad restaurant adjust its marketing strategy?","options":{"A":"Invest in fast local delivery riders and app ordering (Place), maintaining a mid-range price that covers delivery costs.","B":"Cut delivery drivers to save money and reduce salad prices by $1.","C":"Close at lunchtime and open only at midnight.","D":"Stop accepting online or app orders."},"correctOption":"A","correctAnswer":"Invest in fast local delivery riders and app ordering (Place), maintaining a mid-range price that covers delivery costs.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because aligning Place (rapid delivery) with researched customer priorities creates higher value than unnecessary price cuts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cutting delivery speed contradicts the main customer priority identified in research.","C":"Incorrect because office workers buy lunch during midday hours.","D":"Incorrect because app ordering supports fast lunchtime convenience."}}},{"id":"P1_U3_MCQ_992","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_992","question":"A cosmetics company claims in an advert that its face cream 'permanently erases all wrinkles in 24 hours', despite having no scientific evidence. Which legal control does this violate?","options":{"A":"Laws prohibiting false and misleading descriptions in advertising.","B":"Laws requiring every company to use wholesalers.","C":"Laws fixing maximum retail prices on skincare products.","D":"Laws banning television commercials for cosmetics."},"correctOption":"A","correctAnswer":"Laws prohibiting false and misleading descriptions in advertising.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumer protection legislation makes it illegal to deceive shoppers with unsubstantiated or false performance claims.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because distribution channels are not mandated by law.","C":"Incorrect because skincare prices are set by businesses.","D":"Incorrect because truthful cosmetic ads are legal on TV."}}},{"id":"P1_U3_MCQ_993","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_993","question":"Why do many countries enforce 'cooling-off' or mandatory return periods for goods purchased online or by mail order?","options":{"A":"To protect consumers who cannot physically inspect or test items before buying at a distance.","B":"To prevent e-commerce websites from accepting credit cards.","C":"To force consumers to keep faulty items delivered by courier.","D":"To eliminate all shipping costs for online retailers."},"correctOption":"A","correctAnswer":"To protect consumers who cannot physically inspect or test items before buying at a distance.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because distance-selling laws give online buyers time to inspect delivered goods and cancel/return them if unsuitable.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because online retailers freely accept card payments.","C":"Incorrect because consumer laws protect the right to return faulty or unsuitable distance purchases.","D":"Incorrect because retailers still incur shipping costs."}}},{"id":"P1_U3_MCQ_994","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_994","question":"How do 'weights and measures' consumer protection laws affect a business's packaging and pricing?","options":{"A":"Businesses must state accurate net weights or volumes on packages and must not sell underweight goods.","B":"Businesses must sell every product in 1-kilogram bags.","C":"Businesses are forbidden from printing prices on supermarket shelves.","D":"Businesses can advertise 500g boxes while secretly putting only 300g inside."},"correctOption":"A","correctAnswer":"Businesses must state accurate net weights or volumes on packages and must not sell underweight goods.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because weights and measures regulations ensure consumers receive the exact quantity stated on the label.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because any pack size is legal provided its stated weight/volume is accurate.","C":"Incorrect because clear price display is actually required by consumer laws.","D":"Incorrect because short-weighting customers is illegal."}}},{"id":"P1_U3_MCQ_995","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_995","question":"Why might a successful domestic soft-drinks manufacturer decide to enter foreign markets?","options":{"A":"Its home market is saturated with slow growth, whereas overseas markets offer new sales expansion and spread business risk across economies.","B":"Exporting overseas eliminates all transport and customs paperwork.","C":"Foreign consumers have identical tastes and languages in every country.","D":"Domestic laws force profitable firms to stop selling in their home country."},"correctOption":"A","correctAnswer":"Its home market is saturated with slow growth, whereas overseas markets offer new sales expansion and spread business risk across economies.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because expanding internationally overcomes domestic market saturation, increases output for economies of scale, and reduces reliance on one economy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because international trade increases shipping and customs documentation.","C":"Incorrect because tastes and languages differ widely across countries.","D":"Incorrect because firms continue selling domestically alongside exports."}}},{"id":"P1_U3_MCQ_996","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_996","question":"What problem can arise if a company translates its domestic advertising slogan word-for-word into a foreign language without local research?","options":{"A":"The translated phrase may lose its intended meaning, sound nonsensical, or accidentally offend local cultural values.","B":"Foreign printing presses refuse to print translated words.","C":"Import tariffs automatically triple whenever a slogan is translated.","D":"Local consumers immediately buy twice as much of the product."},"correctOption":"A","correctAnswer":"The translated phrase may lose its intended meaning, sound nonsensical, or accidentally offend local cultural values.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because idioms and brand names frequently carry unintended or offensive meanings across languages and cultures.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because local media print translated copy routinely.","C":"Incorrect because import tariffs are based on product classification and value, not ad wording.","D":"Incorrect because poor translation typically damages brand credibility and reduces sales."}}},{"id":"P1_U3_MCQ_997","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_997","question":"Besides cultural and language differences, which financial factor creates risk when a business sells products in foreign markets?","options":{"A":"Exchange rate fluctuations, which can unexpectedly make exported goods more expensive for foreign buyers or reduce converted profits.","B":"Foreign banks refuse to accept electronic money transfers.","C":"Fixed factory rent in the home country doubles every time a container is exported.","D":"All foreign currencies have the exact same value forever."},"correctOption":"A","correctAnswer":"Exchange rate fluctuations, which can unexpectedly make exported goods more expensive for foreign buyers or reduce converted profits.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because appreciation of the exporter's home currency raises foreign selling prices or squeezes profit margins when foreign revenue is converted back.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because international bank transfers operate globally.","C":"Incorrect because domestic rent does not automatically double with exports.","D":"Incorrect because exchange rates fluctuate continuously."}}},{"id":"P1_U3_MCQ_998","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_998","question":"A global fast-food chain keeps its core restaurant branding worldwide but introduces spicy paneer burgers in India and teriyaki burgers in Japan. How does this overcome foreign market barriers?","options":{"A":"By adapting the Product element of the marketing mix to respect local religious dietary rules and regional taste preferences.","B":"By eliminating all local market research before opening new branches.","C":"By charging 500% more than every local restaurant competitor.","D":"By banning local ingredients from all overseas kitchens."},"correctOption":"A","correctAnswer":"By adapting the Product element of the marketing mix to respect local religious dietary rules and regional taste preferences.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because localising menu items aligns the global brand with local cultural norms and culinary tastes, boosting customer acceptance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because successful menu adaptation relies on thorough local market research.","C":"Incorrect because fast-food chains use competitive local pricing.","D":"Incorrect because sourcing local ingredients helps adapt menus and control costs."}}},{"id":"P1_U3_MCQ_999","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_999","question":"Why might a small manufacturer choose to sell through an established overseas distributor or agent rather than setting up its own foreign sales subsidiary?","options":{"A":"It avoids high upfront capital costs and uses the local distributor's existing retail contacts and regulatory knowledge.","B":"It guarantees 100% control over how the product is displayed in every foreign shop.","C":"Distributors never charge any commission or wholesale margin.","D":"Setting up a wholly owned foreign subsidiary is completely free."},"correctOption":"A","correctAnswer":"It avoids high upfront capital costs and uses the local distributor's existing retail contacts and regulatory knowledge.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because working with local intermediaries lowers financial risk and speeds up market entry when a firm lacks capital and local expertise.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because using third-party distributors actually reduces direct control over retail presentation.","C":"Incorrect because distributors take a margin or commission for their services.","D":"Incorrect because opening foreign offices and warehouses requires heavy capital investment."}}},{"id":"P1_U3_MCQ_1000","section":"3","unit":"Unit 3: Marketing","chapter":"3.5 Marketing strategy","questionNumber":"P1_U3_MCQ_1000","question":"When recommending a new marketing strategy to a business, why must managers consider the firm's current production capacity alongside its promotional plans?","options":{"A":"If heavy promotion generates orders that exceed factory capacity, unfulfilled orders and long delays will disappoint customers and harm the brand.","B":"Production capacity has zero connection to how many units can be sold.","C":"Advertising campaigns automatically double factory floor space overnight.","D":"Laws forbid businesses from promoting products unless their factories are 100% empty."},"correctOption":"A","correctAnswer":"If heavy promotion generates orders that exceed factory capacity, unfulfilled orders and long delays will disappoint customers and harm the brand.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an effective marketing strategy must align demand creation (Promotion/Price) with operational ability to supply (Product/Place).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sales volume is constrained by how much output the business can produce or source.","C":"Incorrect because expanding physical capacity requires capital investment and time.","D":"Incorrect because no such law exists."}}}];
